INSERT INTO `chapter_details` VALUES (1,1,'بِسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ','Bismillaahir Rahmaanir Raheem',1,'1:1',1,1,1,1,0,1,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(2,1,'ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَـٰلَمِينَ','Alhamdu lillaahi Rabbil \'aalameen',2,'1:2',1,1,1,1,0,1,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(3,1,'ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ','Ar-Rahmaanir-Raheem',3,'1:3',1,1,1,1,0,1,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(4,1,'مَـٰلِكِ يَوْمِ ٱلدِّينِ','Maaliki Yawmid-Deen',4,'1:4',1,1,1,1,0,1,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(5,1,'إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ','Iyyaaka na\'budu wa lyyaaka nasta\'een',5,'1:5',1,1,1,1,0,1,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(6,1,'ٱهْدِنَا ٱلصِّرَٰطَ ٱلْمُسْتَقِيمَ','Ihdinas-Siraatal-Mustaqeem',6,'1:6',1,1,1,1,0,1,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(7,1,'صِرَٰطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِمْ وَلَا ٱلضَّآلِّينَ','Siraatal-lazeena an\'amta \'alaihim ghayril-maghdoobi \'alaihim wa lad-daaalleen',7,'1:7',1,1,1,1,0,1,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(8,2,'الٓمٓ','Alif-Laaam-Meeem',1,'2:1',1,1,2,1,0,2,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(9,2,'ذَٰلِكَ ٱلْكِتَـٰبُ لَا رَيْبَ ۛ فِيهِ ۛ هُدًى لِّلْمُتَّقِينَ','Zaalikal Kitaabu laa raiba feeh; udal lilmuttaqeen',2,'2:2',1,1,2,1,0,2,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(10,2,'ٱلَّذِينَ يُؤْمِنُونَ بِٱلْغَيْبِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقْنَـٰهُمْ يُنفِقُونَ','Allazeena yu\'minoona bilghaibi wa yuqeemoonas salaata wa mimmaa razaqnaahum yunfiqoon',3,'2:3',1,1,2,1,0,2,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(11,2,'وَٱلَّذِينَ يُؤْمِنُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ وَبِٱلْـَٔاخِرَةِ هُمْ يُوقِنُونَ','Wallazeena yu\'minoona bimaa unzila ilaika wa maaa unzila min qablika wa bil Aakhirati hum yooqinoon',4,'2:4',1,1,2,1,0,2,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(12,2,'أُو۟لَـٰٓئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ ۖ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ','Ulaaa\'ika \'alaa hudam mir rabbihim wa ulaaa\'ika humul muflihoon',5,'2:5',1,1,2,1,0,2,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(13,2,'إِنَّ ٱلَّذِينَ كَفَرُوا۟ سَوَآءٌ عَلَيْهِمْ ءَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ','Innal lazeena kafaroo sawaaa\'un \'alaihim \'a-anzar tahum am lam tunzirhum laa yu\'minoon',6,'2:6',1,1,2,1,0,3,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(14,2,'خَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَعَلَىٰ سَمْعِهِمْ ۖ وَعَلَىٰٓ أَبْصَـٰرِهِمْ غِشَـٰوَةٌ ۖ وَلَهُمْ عَذَابٌ عَظِيمٌ','Khatamal laahu \'alaa quloobihim wa \'alaa sam\'i-him wa \'alaaa absaarihim ghishaa watunw wa lahum \'azaabun \'azeem',7,'2:7',1,1,2,1,0,3,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(15,2,'وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ وَبِٱلْيَوْمِ ٱلْـَٔاخِرِ وَمَا هُم بِمُؤْمِنِينَ','Wa minan naasi mai yaqoolu aamannaa billaahi wa bil yawmil aakhiri wa maa hum bimu\'mineen',8,'2:8',1,1,3,1,0,3,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(16,2,'يُخَـٰدِعُونَ ٱللَّهَ وَٱلَّذِينَ ءَامَنُوا۟ وَمَا يَخْدَعُونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ','Yukhaadi\'oonal laaha wallazeena aamanoo wa maa yakhda\'oona illaaa anfusahum wa maa yash\'uroon',9,'2:9',1,1,3,1,0,3,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(17,2,'فِى قُلُوبِهِم مَّرَضٌ فَزَادَهُمُ ٱللَّهُ مَرَضًا ۖ وَلَهُمْ عَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْذِبُونَ','Fee quloobihim mara dun fazzdahumul laahu maradan wa lahum \'azaabun aleemum bimaa kaanoo yakziboon',10,'2:10',1,1,3,1,0,3,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(18,2,'وَإِذَا قِيلَ لَهُمْ لَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ قَالُوٓا۟ إِنَّمَا نَحْنُ مُصْلِحُونَ','Wa izaa qeela lahum laa tufsidoo fil ardi qaalo innamaa nahnu muslihoon',11,'2:11',1,1,3,1,0,3,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(19,2,'أَلَآ إِنَّهُمْ هُمُ ٱلْمُفْسِدُونَ وَلَـٰكِن لَّا يَشْعُرُونَ','Alaaa innahum humul mufsidoona wa laakil laa yash\'uroon',12,'2:12',1,1,3,1,0,3,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(20,2,'وَإِذَا قِيلَ لَهُمْ ءَامِنُوا۟ كَمَآ ءَامَنَ ٱلنَّاسُ قَالُوٓا۟ أَنُؤْمِنُ كَمَآ ءَامَنَ ٱلسُّفَهَآءُ ۗ أَلَآ إِنَّهُمْ هُمُ ٱلسُّفَهَآءُ وَلَـٰكِن لَّا يَعْلَمُونَ','Wa izaa qeela lahum aaminoo kamaaa aamanan naasu qaalooo anu\'minu kamaaa aamanas sufahaaa\'; alaaa innahum humus sufahaaa\'u wa laakil laa ya\'lamoon',13,'2:13',1,1,3,1,0,3,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(21,2,'وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَوْا۟ إِلَىٰ شَيَـٰطِينِهِمْ قَالُوٓا۟ إِنَّا مَعَكُمْ إِنَّمَا نَحْنُ مُسْتَهْزِءُونَ','Wa izaa laqul lazeena aamanoo qaalooo aamannaa wa izaa khalw ilaa shayaateenihim qaalooo innaa ma\'akum innamaa nahnu mustahzi\'oon',14,'2:14',1,1,3,1,0,3,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(22,2,'ٱللَّهُ يَسْتَهْزِئُ بِهِمْ وَيَمُدُّهُمْ فِى طُغْيَـٰنِهِمْ يَعْمَهُونَ','Allahu yastahzi\'u bihim wa yamudduhum fee tughyaanihim ya\'mahoon',15,'2:15',1,1,3,1,0,3,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(23,2,'أُو۟لَـٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلضَّلَـٰلَةَ بِٱلْهُدَىٰ فَمَا رَبِحَت تِّجَـٰرَتُهُمْ وَمَا كَانُوا۟ مُهْتَدِينَ','Ulaaa\'ikal lazeenash tara wud dalaalata bilhudaa famaa rabihat tijaaratuhum wa maa kaanoo muhtadeen',16,'2:16',1,1,3,1,0,3,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(24,2,'مَثَلُهُمْ كَمَثَلِ ٱلَّذِى ٱسْتَوْقَدَ نَارًا فَلَمَّآ أَضَآءَتْ مَا حَوْلَهُۥ ذَهَبَ ٱللَّهُ بِنُورِهِمْ وَتَرَكَهُمْ فِى ظُلُمَـٰتٍ لَّا يُبْصِرُونَ','Masaluhum kamasalillazis tawqada naaran falammaaa adaaa\'at maa hawlahoo zahabal laahu binoorihim wa tarakahum fee zulumaatil laa yubsiroon',17,'2:17',1,1,3,1,0,4,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(25,2,'صُمٌّۢ بُكْمٌ عُمْىٌ فَهُمْ لَا يَرْجِعُونَ','Summum bukmun \'umyun fahum laa yarji\'oon',18,'2:18',1,1,3,1,0,4,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(26,2,'أَوْ كَصَيِّبٍ مِّنَ ٱلسَّمَآءِ فِيهِ ظُلُمَـٰتٌ وَرَعْدٌ وَبَرْقٌ يَجْعَلُونَ أَصَـٰبِعَهُمْ فِىٓ ءَاذَانِهِم مِّنَ ٱلصَّوَٰعِقِ حَذَرَ ٱلْمَوْتِ ۚ وَٱللَّهُ مُحِيطٌۢ بِٱلْكَـٰفِرِينَ','Aw kasaiyibim minas samaaa\'i feehi zulumaatunw wa ra\'dunw wa barq, yaj\'aloona asaabi\'ahum feee aazaanihim minas sawaa\'iqi hazaral mawt\' wallaahu muheetum bilkaafireen',19,'2:19',1,1,3,1,0,4,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(27,2,'يَكَادُ ٱلْبَرْقُ يَخْطَفُ أَبْصَـٰرَهُمْ ۖ كُلَّمَآ أَضَآءَ لَهُم مَّشَوْا۟ فِيهِ وَإِذَآ أَظْلَمَ عَلَيْهِمْ قَامُوا۟ ۚ وَلَوْ شَآءَ ٱللَّهُ لَذَهَبَ بِسَمْعِهِمْ وَأَبْصَـٰرِهِمْ ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ','Yakaadul barqu yakhtafu absaarahum kullamaaa adaaa\'a lahum mashaw feehi wa izaaa azlama \'alaihim qaamoo; wa law shaaa\'al laahu lazahaba bisam\'ihim wa absaarihim; innal laaha \'alaa kulli shai\'in Qadeer',20,'2:20',1,1,3,1,0,4,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(28,2,'يَـٰٓأَيُّهَا ٱلنَّاسُ ٱعْبُدُوا۟ رَبَّكُمُ ٱلَّذِى خَلَقَكُمْ وَٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ','Yaaa aiyuhan naasu\'budoo Rabbakumul lazee khalaqakum wallazeena min qablikum la\'allakum tattaqoon',21,'2:21',1,1,4,1,0,4,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(29,2,'ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ فِرَٰشًا وَٱلسَّمَآءَ بِنَآءً وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزْقًا لَّكُمْ ۖ فَلَا تَجْعَلُوا۟ لِلَّهِ أَندَادًا وَأَنتُمْ تَعْلَمُونَ','Allazee ja\'ala lakumul arda firaashanw wassamaaa\'a binaaa \'anw wa anzala minassamaaa\'i maaa\'an fa akhraja bihee minas samaraati rizqal lakum falaa taj\'aloo lillaahi andaadanw wa antum ta\'lamoon',22,'2:22',1,1,4,1,0,4,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(30,2,'وَإِن كُنتُمْ فِى رَيْبٍ مِّمَّا نَزَّلْنَا عَلَىٰ عَبْدِنَا فَأْتُوا۟ بِسُورَةٍ مِّن مِّثْلِهِۦ وَٱدْعُوا۟ شُهَدَآءَكُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَـٰدِقِينَ','Wa in kuntum fee raibim mimmaa nazzalnaa \'alaa \'abdinaa fatoo bi Sooratim mim mislihee wad\'oo shuhadaaa\'akum min doonil laahi in kuntum saadiqeen',23,'2:23',1,1,4,1,0,4,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(31,2,'فَإِن لَّمْ تَفْعَلُوا۟ وَلَن تَفْعَلُوا۟ فَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِى وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ ۖ أُعِدَّتْ لِلْكَـٰفِرِينَ','Fail lam taf\'aloo wa lan taf\'aloo fattaqun Naaral latee waqooduhan naasu walhijaaratu u\'iddat lilkaafireen',24,'2:24',1,1,4,1,0,4,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(32,2,'وَبَشِّرِ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أَنَّ لَهُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ۖ كُلَّمَا رُزِقُوا۟ مِنْهَا مِن ثَمَرَةٍ رِّزْقًا ۙ قَالُوا۟ هَـٰذَا ٱلَّذِى رُزِقْنَا مِن قَبْلُ ۖ وَأُتُوا۟ بِهِۦ مُتَشَـٰبِهًا ۖ وَلَهُمْ فِيهَآ أَزْوَٰجٌ مُّطَهَّرَةٌ ۖ وَهُمْ فِيهَا خَـٰلِدُونَ','Wa bashshiril lazeena aamanoo wa \'amilus saalihaati anna lahum jannaatin tajree min tahtihal anhaaru kullamaa riziqoo minhaa min samaratir rizqan qaaloo haazal lazee ruziqnaa min qablu wa utoo bihee mutashaabihaa, wa lahum feehaaa azwaajum mutahhara tunw wa hum feehaa khaalidoon',25,'2:25',1,1,4,1,0,5,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(33,2,'۞ إِنَّ ٱللَّهَ لَا يَسْتَحْىِۦٓ أَن يَضْرِبَ مَثَلًا مَّا بَعُوضَةً فَمَا فَوْقَهَا ۚ فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ فَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ ۖ وَأَمَّا ٱلَّذِينَ كَفَرُوا۟ فَيَقُولُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَـٰذَا مَثَلًا ۘ يُضِلُّ بِهِۦ كَثِيرًا وَيَهْدِى بِهِۦ كَثِيرًا ۚ وَمَا يُضِلُّ بِهِۦٓ إِلَّا ٱلْفَـٰسِقِينَ','Innal laaha laa yastahyeee ai yadriba masalam maa ba\'oodatan famaa fawqahaa; faammal lazeena aamanoo faya\'lamoona annahul haqqu mir rabbihim wa ammal lazeena kafaroo fayaqooloona maazaaa araadal laahu bihaazaa masalaa; yudillu bihee kaseeranw wa yahdee bihee kaseeraa; wa maa yudillu biheee illal faasiqeen',26,'2:26',1,2,4,1,0,5,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(34,2,'ٱلَّذِينَ يَنقُضُونَ عَهْدَ ٱللَّهِ مِنۢ بَعْدِ مِيثَـٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفْسِدُونَ فِى ٱلْأَرْضِ ۚ أُو۟لَـٰٓئِكَ هُمُ ٱلْخَـٰسِرُونَ','Allazeena yanqudoona \'ahdal laahi mim ba\'di meesaaqihee wa yaqt\'oona maaa amaral laahu biheee ai yoosala wa yufsidoona fil ard; ulaaa\'ika hum khaasirron',27,'2:27',1,2,4,1,0,5,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(35,2,'كَيْفَ تَكْفُرُونَ بِٱللَّهِ وَكُنتُمْ أَمْوَٰتًا فَأَحْيَـٰكُمْ ۖ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ ثُمَّ إِلَيْهِ تُرْجَعُونَ','Kaifa takfuroona billaahi wa kuntum amwaatan fa ahyaakum summa yumeetukum summa yuhyeekum summaa ilaihi turja\'oon',28,'2:28',1,2,4,1,0,5,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(36,2,'هُوَ ٱلَّذِى خَلَقَ لَكُم مَّا فِى ٱلْأَرْضِ جَمِيعًا ثُمَّ ٱسْتَوَىٰٓ إِلَى ٱلسَّمَآءِ فَسَوَّىٰهُنَّ سَبْعَ سَمَـٰوَٰتٍ ۚ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ','Huwal lazee khalaqa lakum maa fil ardi jamee\'an summas tawaaa ilas samaaa\'i fasaw waahunna sab\'a samaa waat; wa Huwa bikulli shai\'in Aleem',29,'2:29',1,2,4,1,0,5,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(37,2,'وَإِذْ قَالَ رَبُّكَ لِلْمَلَـٰٓئِكَةِ إِنِّى جَاعِلٌ فِى ٱلْأَرْضِ خَلِيفَةً ۖ قَالُوٓا۟ أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ ٱلدِّمَآءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ ۖ قَالَ إِنِّىٓ أَعْلَمُ مَا لَا تَعْلَمُونَ','Wa iz qaala rabbuka lil malaaa\'ikati innee jaa\'ilun fil ardi khaleefatan qaalooo ataj\'alu feehaa mai yufsidu feehaa wa yasfikud dimaaa\'a wa nahnu nusabbihu bihamdika wa nuqaddisu laka qaala inneee a\'lamu maa laa ta\'lamoon',30,'2:30',1,2,5,1,0,6,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(38,2,'وَعَلَّمَ ءَادَمَ ٱلْأَسْمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمْ عَلَى ٱلْمَلَـٰٓئِكَةِ فَقَالَ أَنۢبِـُٔونِى بِأَسْمَآءِ هَـٰٓؤُلَآءِ إِن كُنتُمْ صَـٰدِقِينَ','Wa \'allama Aadamal asmaaa\'a kullahaa summa \'aradahum \'alal malaaa\'ikati faqaala ambi\'oonee bias maaa\'i haaa\'ulaaa\'i in kuntum saadiqeen',31,'2:31',1,2,5,1,0,6,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(39,2,'قَالُوا۟ سُبْحَـٰنَكَ لَا عِلْمَ لَنَآ إِلَّا مَا عَلَّمْتَنَآ ۖ إِنَّكَ أَنتَ ٱلْعَلِيمُ ٱلْحَكِيمُ','Qaaloo subhaanaka laa \'ilma lanaaa illaa maa \'allamtanaaa innaka antal\'aleemul hakeem',32,'2:32',1,2,5,1,0,6,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(40,2,'قَالَ يَـٰٓـَٔادَمُ أَنۢبِئْهُم بِأَسْمَآئِهِمْ ۖ فَلَمَّآ أَنۢبَأَهُم بِأَسْمَآئِهِمْ قَالَ أَلَمْ أَقُل لَّكُمْ إِنِّىٓ أَعْلَمُ غَيْبَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَأَعْلَمُ مَا تُبْدُونَ وَمَا كُنتُمْ تَكْتُمُونَ','Qaala yaaa Aadamu ambi\' hum biasmaaa\'ihimfalammaaa amba ahum bi asmaaa\'ihim qaala alam aqul lakum inneee a\'lamu ghaibas samaawaati wal ardi wa a\'lamu maa tubdoona wa maa kuntum taktumoon',33,'2:33',1,2,5,1,0,6,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(41,2,'وَإِذْ قُلْنَا لِلْمَلَـٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَـٰفِرِينَ','Wa iz qulnaa lilmalaaa\'i katis judoo liAadama fasajadooo illaaa Ibleesa abaa wastakbara wa kaana minal kaafireen',34,'2:34',1,2,5,1,0,6,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(42,2,'وَقُلْنَا يَـٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ وَكُلَا مِنْهَا رَغَدًا حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَـٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّـٰلِمِينَ','Wa qulnaa yaaa Aadamus kun anta wa zawjukal jannata wa kulaa minhaa raghadan haisu shi\'tumaa wa laa taqabaa haazihish shajarata fatakoonaa minaz zaalimeen',35,'2:35',1,2,5,1,0,6,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(43,2,'فَأَزَلَّهُمَا ٱلشَّيْطَـٰنُ عَنْهَا فَأَخْرَجَهُمَا مِمَّا كَانَا فِيهِ ۖ وَقُلْنَا ٱهْبِطُوا۟ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ ۖ وَلَكُمْ فِى ٱلْأَرْضِ مُسْتَقَرٌّ وَمَتَـٰعٌ إِلَىٰ حِينٍ','Fa azallahumash Shaitaanu \'anhaa fa akhrajahumaa mimmaa kaanaa fee wa qulnah bitoo ba\'dukum liba\'din \'aduwwunw wa lakum fil ardi mustaqarrunw wa mataa\'un ilaa heen',36,'2:36',1,2,5,1,0,6,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(44,2,'فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَـٰتٍ فَتَابَ عَلَيْهِ ۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ','Fatalaqqaaa Aadamu mir Rabbihee Kalimaatin fataaba \'alayh; innahoo Huwat Tawwaabur Raheem',37,'2:37',1,2,5,1,0,6,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(45,2,'قُلْنَا ٱهْبِطُوا۟ مِنْهَا جَمِيعًا ۖ فَإِمَّا يَأْتِيَنَّكُم مِّنِّى هُدًى فَمَن تَبِعَ هُدَاىَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ','Qulnah bitoo minhaa jamee \'an fa immaa yaatiyannakum minnee hudan faman tabi\'a hudaaya falaa khawfun \'alaihim wa laa hum yahza noon',38,'2:38',1,2,5,1,0,7,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(46,2,'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَـٰتِنَآ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ','Wallazeena kafaroo wa kaz zabooo bi aayaatinaa ulaaa\'ika Ashaabun Naari hum feehaa khaalidoon',39,'2:39',1,2,5,1,0,7,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(47,2,'يَـٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَوْفُوا۟ بِعَهْدِىٓ أُوفِ بِعَهْدِكُمْ وَإِيَّـٰىَ فَٱرْهَبُونِ','Yaa Baneee Israaa\'eelaz kuroo ni\'matiyal lateee an\'amtu \'alaikum wa awfoo bi\'Ahdeee oofi bi ahdikum wa iyyaaya farhaboon',40,'2:40',1,2,6,1,0,7,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(48,2,'وَءَامِنُوا۟ بِمَآ أَنزَلْتُ مُصَدِّقًا لِّمَا مَعَكُمْ وَلَا تَكُونُوٓا۟ أَوَّلَ كَافِرٍۭ بِهِۦ ۖ وَلَا تَشْتَرُوا۟ بِـَٔايَـٰتِى ثَمَنًا قَلِيلًا وَإِيَّـٰىَ فَٱتَّقُونِ','Wa aaminoo bimaaa anzaltu musaddiqal limaa ma\'akum wa laa takoonooo awwala kaafirim bihee wa laa tashtaroo bi Aayaatee samanan qaleelanw wa iyyaaya fattaqoon',41,'2:41',1,2,6,1,0,7,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(49,2,'وَلَا تَلْبِسُوا۟ ٱلْحَقَّ بِٱلْبَـٰطِلِ وَتَكْتُمُوا۟ ٱلْحَقَّ وَأَنتُمْ تَعْلَمُونَ','Wa laa talbisul haqqa bilbaatili wa taktumul haqqa wa antum ta\'lamoon',42,'2:42',1,2,6,1,0,7,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(50,2,'وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَٱرْكَعُوا۟ مَعَ ٱلرَّٰكِعِينَ','Wa aqeemus salaata wa aatuz zakaata warka\'oo ma\'ar raaki\'een',43,'2:43',1,2,6,1,0,7,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(51,2,'۞ أَتَأْمُرُونَ ٱلنَّاسَ بِٱلْبِرِّ وَتَنسَوْنَ أَنفُسَكُمْ وَأَنتُمْ تَتْلُونَ ٱلْكِتَـٰبَ ۚ أَفَلَا تَعْقِلُونَ','Ataamuroonan naasa bilbirri wa tansawna anfusakum wa antum tatloonal Kitaab; afalaa ta\'qiloon',44,'2:44',1,3,6,1,0,7,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(52,2,'وَٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ ۚ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى ٱلْخَـٰشِعِينَ','Wasta\'eenoo bissabri was Salaah; wa innahaa lakabee ratun illaa alal khaashi\'een',45,'2:45',1,3,6,1,0,7,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(53,2,'ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَـٰقُوا۟ رَبِّهِمْ وَأَنَّهُمْ إِلَيْهِ رَٰجِعُونَ','Allazeena yazunnoona annahum mulaaqoo Rabbihim wa annahum ilaihi raaji\'oon',46,'2:46',1,3,6,1,0,7,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(54,2,'يَـٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّى فَضَّلْتُكُمْ عَلَى ٱلْعَـٰلَمِينَ','Yaa Baneee Israaa\'eelaz kuroo ni\'matiyal lateee an\'amtu \'alaikum wa annee faddaltukum \'alal \'aalameen',47,'2:47',1,3,7,1,0,7,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(55,2,'وَٱتَّقُوا۟ يَوْمًا لَّا تَجْزِى نَفْسٌ عَن نَّفْسٍ شَيْـًٔا وَلَا يُقْبَلُ مِنْهَا شَفَـٰعَةٌ وَلَا يُؤْخَذُ مِنْهَا عَدْلٌ وَلَا هُمْ يُنصَرُونَ','Wattaqoo Yawmal laa tajzee nafsun \'an nafsin shai\'anw wa laa yuqbalu minhaa shafaa\'atunw wa laa yu\'khazu minhaa \'adlunw wa laa hum yunsaroon',48,'2:48',1,3,7,1,0,7,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(56,2,'وَإِذْ نَجَّيْنَـٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ يُذَبِّحُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ ۚ وَفِى ذَٰلِكُم بَلَآءٌ مِّن رَّبِّكُمْ عَظِيمٌ','Wa iz najjainaakum min Aali Fir\'awna yasoomoonakum sooo\'al azaabi yuzabbihoona abuaaa\'akum wa yastahyoona nisaaa\'akum; wa fee zaalikum balaaa\'um mir Rabbikum \'azeem',49,'2:49',1,3,7,1,0,8,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(57,2,'وَإِذْ فَرَقْنَا بِكُمُ ٱلْبَحْرَ فَأَنجَيْنَـٰكُمْ وَأَغْرَقْنَآ ءَالَ فِرْعَوْنَ وَأَنتُمْ تَنظُرُونَ','Wa iz faraqnaa bikumul bahra fa anjainaakum wa agh-raqnaaa Aala Fir\'awna wa antum tanzuroon',50,'2:50',1,3,7,1,0,8,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(58,2,'وَإِذْ وَٰعَدْنَا مُوسَىٰٓ أَرْبَعِينَ لَيْلَةً ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَـٰلِمُونَ','Wa iz waa\'adnaa Moosaaa arba\'eena lailatan summattakhaztumul \'ijla mim ba\'dihee wa antum zaalimoon',51,'2:51',1,3,7,1,0,8,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(59,2,'ثُمَّ عَفَوْنَا عَنكُم مِّنۢ بَعْدِ ذَٰلِكَ لَعَلَّكُمْ تَشْكُرُونَ','Summa \'afawnaa \'ankum mim ba\'di zaalika la\'allakum tashkuroon',52,'2:52',1,3,7,1,0,8,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(60,2,'وَإِذْ ءَاتَيْنَا مُوسَى ٱلْكِتَـٰبَ وَٱلْفُرْقَانَ لَعَلَّكُمْ تَهْتَدُونَ','Wa iz aatainaa Moosal kitaaba wal Furqaana la\'allakum tahtadoon',53,'2:53',1,3,7,1,0,8,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(61,2,'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَـٰقَوْمِ إِنَّكُمْ ظَلَمْتُمْ أَنفُسَكُم بِٱتِّخَاذِكُمُ ٱلْعِجْلَ فَتُوبُوٓا۟ إِلَىٰ بَارِئِكُمْ فَٱقْتُلُوٓا۟ أَنفُسَكُمْ ذَٰلِكُمْ خَيْرٌ لَّكُمْ عِندَ بَارِئِكُمْ فَتَابَ عَلَيْكُمْ ۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ','Wa iz qaala Moosaa liqawmihee yaa qawmi innakum zalamtum anfusakum bittikhaa zikumul \'ijla fatoobooo ilaa Baari\'ikum faqtulooo anfusakum zaalikum khairul lakum \'inda Baari\'ikum fataaba \'alaikum; innahoo Huwat Tawwaabur Raheem',54,'2:54',1,3,7,1,0,8,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(62,2,'وَإِذْ قُلْتُمْ يَـٰمُوسَىٰ لَن نُّؤْمِنَ لَكَ حَتَّىٰ نَرَى ٱللَّهَ جَهْرَةً فَأَخَذَتْكُمُ ٱلصَّـٰعِقَةُ وَأَنتُمْ تَنظُرُونَ','Wa iz qultum yaa Moosaa lan nu\'mina laka hattaa naral laaha jahratan fa akhazat kumus saa\'iqatu wa antum tanzuroon',55,'2:55',1,3,7,1,0,8,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(63,2,'ثُمَّ بَعَثْنَـٰكُم مِّنۢ بَعْدِ مَوْتِكُمْ لَعَلَّكُمْ تَشْكُرُونَ','Summa ba\'asnaakum mim ba\'di mawtikum la\'allakum tashkuroon',56,'2:56',1,3,7,1,0,8,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(64,2,'وَظَلَّلْنَا عَلَيْكُمُ ٱلْغَمَامَ وَأَنزَلْنَا عَلَيْكُمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ ۖ كُلُوا۟ مِن طَيِّبَـٰتِ مَا رَزَقْنَـٰكُمْ ۖ وَمَا ظَلَمُونَا وَلَـٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ','Wa zallalnaa \'alaikumul ghamaama wa anzalnaa \'alaikumul Manna was Salwaa kuloo min taiyibaati maa razaqnaakum wa maa zalamoonaa wa laakin kaanooo anfusahum yazlimoon',57,'2:57',1,3,7,1,0,8,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(65,2,'وَإِذْ قُلْنَا ٱدْخُلُوا۟ هَـٰذِهِ ٱلْقَرْيَةَ فَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ رَغَدًا وَٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًا وَقُولُوا۟ حِطَّةٌ نَّغْفِرْ لَكُمْ خَطَـٰيَـٰكُمْ ۚ وَسَنَزِيدُ ٱلْمُحْسِنِينَ','Wa iz qulnad khuloo haazihil qaryata fakuloo minhaa haisu shi\'tum raghadanw wadkhulul baaba sujjadanw wa qooloo hittatun naghfir lakum khataayaakum; wa sanazeedul muhsineen',58,'2:58',1,3,7,1,0,9,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(66,2,'فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ فَأَنزَلْنَا عَلَى ٱلَّذِينَ ظَلَمُوا۟ رِجْزًا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَفْسُقُونَ','Fabaddalal lazeena zalamoo qawlan ghairal lazee qeela lahum fa anzalnaa \'alal lazeena zalamoo rijzam minas samaaa\'i bimaa kaanoo yafsuqoon',59,'2:59',1,3,7,1,0,9,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(67,2,'۞ وَإِذِ ٱسْتَسْقَىٰ مُوسَىٰ لِقَوْمِهِۦ فَقُلْنَا ٱضْرِب بِّعَصَاكَ ٱلْحَجَرَ ۖ فَٱنفَجَرَتْ مِنْهُ ٱثْنَتَا عَشْرَةَ عَيْنًا ۖ قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ ۖ كُلُوا۟ وَٱشْرَبُوا۟ مِن رِّزْقِ ٱللَّهِ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ','Wa izis tasqaa Moosaa liqawmihee faqulnad rib bi\'asaakal hajara fanfajarat minhusnataaa \'ashrata \'aynan qad \'alima kullu unaasim mash rabahum kuloo washraboo mir rizqil laahi wa laa ta\'saw fil ardi mufsideen',60,'2:60',1,4,8,1,0,9,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(68,2,'وَإِذْ قُلْتُمْ يَـٰمُوسَىٰ لَن نَّصْبِرَ عَلَىٰ طَعَامٍ وَٰحِدٍ فَٱدْعُ لَنَا رَبَّكَ يُخْرِجْ لَنَا مِمَّا تُنۢبِتُ ٱلْأَرْضُ مِنۢ بَقْلِهَا وَقِثَّآئِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَا ۖ قَالَ أَتَسْتَبْدِلُونَ ٱلَّذِى هُوَ أَدْنَىٰ بِٱلَّذِى هُوَ خَيْرٌ ۚ ٱهْبِطُوا۟ مِصْرًا فَإِنَّ لَكُم مَّا سَأَلْتُمْ ۗ وَضُرِبَتْ عَلَيْهِمُ ٱلذِّلَّةُ وَٱلْمَسْكَنَةُ وَبَآءُو بِغَضَبٍ مِّنَ ٱللَّهِ ۗ ذَٰلِكَ بِأَنَّهُمْ كَانُوا۟ يَكْفُرُونَ بِـَٔايَـٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيْرِ ٱلْحَقِّ ۗ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ','Wa iz qultum yaa Moosaa lan nasbira \'alaa ta\'aaminw waahidin fad\'u lanaa rabbaka yukhrij lanaa mimmaa tumbitul ardu mimbaqlihaa wa qis saaa\'ihaa wa foomihaa wa \'adasihaa wa basalihaa qaala atastabdiloonal lazee huwa adnaa billazee huwa khayr; ihbitoo misran fa inna lakum maa sa altum; wa duribat \'alaihimuz zillatu walmaskanatu wa baaa\'oo bighadabim minal laah; zaalika bi annahum kaano yakfuroona bi aayaatil laahi wa yaqtuloonan Nabiyyeena bighairil haqq; zaalika bimaa \'asaw wa kaanoo ya\'tadoon',61,'2:61',1,4,8,1,0,9,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(69,2,'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَادُوا۟ وَٱلنَّصَـٰرَىٰ وَٱلصَّـٰبِـِٔينَ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَعَمِلَ صَـٰلِحًا فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ','Innal lazeena aamanoo wallazeena haadoo wan nasaaraa was Saabi\'eena man aamana billaahi wal yawmil aakhiri wa \'amila saalihan falahum ajruhum \'inda Rabbihim wa laa khawfun \'alaihim wa laa hum yahzanoon',62,'2:62',1,4,9,1,0,10,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(70,2,'وَإِذْ أَخَذْنَا مِيثَـٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ ٱلطُّورَ خُذُوا۟ مَآ ءَاتَيْنَـٰكُم بِقُوَّةٍ وَٱذْكُرُوا۟ مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ','Wa iz akhaznaa meesaaqakum wa rafa\'naa fawqakumut Toora khuzoo maaa aatainaakum biquwwatinw wazkuroo maa feehi la\'allakum tattaqoon',63,'2:63',1,4,9,1,0,10,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(71,2,'ثُمَّ تَوَلَّيْتُم مِّنۢ بَعْدِ ذَٰلِكَ ۖ فَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ لَكُنتُم مِّنَ ٱلْخَـٰسِرِينَ','Summa tawallaitum mim ba\'di zaalika falawlaa fadlul laahi \'alaikum wa rahmatuhoo lakuntum minal khaasireen',64,'2:64',1,4,9,1,0,10,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(72,2,'وَلَقَدْ عَلِمْتُمُ ٱلَّذِينَ ٱعْتَدَوْا۟ مِنكُمْ فِى ٱلسَّبْتِ فَقُلْنَا لَهُمْ كُونُوا۟ قِرَدَةً خَـٰسِـِٔينَ','Wa laqad \'alimtumul lazeena\'-tadaw minkum fis Sabti faqulnaa lahum koonoo qiradatan khaasi\'een',65,'2:65',1,4,9,1,0,10,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(73,2,'فَجَعَلْنَـٰهَا نَكَـٰلًا لِّمَا بَيْنَ يَدَيْهَا وَمَا خَلْفَهَا وَمَوْعِظَةً لِّلْمُتَّقِينَ','Faja\'alnaahaa nakaalal limaa baina yadihaa wa maa khalfahaa wa maw\'izatal lilmuttaqeen',66,'2:66',1,4,9,1,0,10,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(74,2,'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦٓ إِنَّ ٱللَّهَ يَأْمُرُكُمْ أَن تَذْبَحُوا۟ بَقَرَةً ۖ قَالُوٓا۟ أَتَتَّخِذُنَا هُزُوًا ۖ قَالَ أَعُوذُ بِٱللَّهِ أَنْ أَكُونَ مِنَ ٱلْجَـٰهِلِينَ','Wa iz qaala Moosaa liqawmiheee innal laaha yaamurukum an tazbahoo baqaratan qaalooo atattakhizunna huzuwan qaala a\'oozu billaahi an akoona minal jaahileen',67,'2:67',1,4,9,1,0,10,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(75,2,'قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِىَ ۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا فَارِضٌ وَلَا بِكْرٌ عَوَانٌۢ بَيْنَ ذَٰلِكَ ۖ فَٱفْعَلُوا۟ مَا تُؤْمَرُونَ','Qaalud-\'u lanaa rabbaka yubaiyil lanaa maa hee; qaala innahoo yaqoolu innahaa baqaratul laa faaridunw wa laa bikrun \'awaanum baina zaalika faf\'aloo maa tu\'maroon',68,'2:68',1,4,9,1,0,10,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(76,2,'قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا لَوْنُهَا ۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ صَفْرَآءُ فَاقِعٌ لَّوْنُهَا تَسُرُّ ٱلنَّـٰظِرِينَ','Qaalud-\'u lanaa rabaaka yubaiyil lanaa maa lawnuhaa; qaala innahoo yaqoolu innahaa baqaratun safraaa\'u faqi\'ul lawnuhaa tasurrunnaazireen',69,'2:69',1,4,9,1,0,10,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(77,2,'قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِىَ إِنَّ ٱلْبَقَرَ تَشَـٰبَهَ عَلَيْنَا وَإِنَّآ إِن شَآءَ ٱللَّهُ لَمُهْتَدُونَ','Qaalud-\'u lanaa rabbaka yubaiyil lanaa maa hiya innal baqara tashaabaha \'alainaa wa innaaa in shaaa\'al laahu lamuhtadoon',70,'2:70',1,4,9,1,0,11,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(78,2,'قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا ذَلُولٌ تُثِيرُ ٱلْأَرْضَ وَلَا تَسْقِى ٱلْحَرْثَ مُسَلَّمَةٌ لَّا شِيَةَ فِيهَا ۚ قَالُوا۟ ٱلْـَٔـٰنَ جِئْتَ بِٱلْحَقِّ ۚ فَذَبَحُوهَا وَمَا كَادُوا۟ يَفْعَلُونَ','Qaala innahoo yaqoolu innahaa baqaratul laa zaloolun tuseerul arda wa laa tasqil harsa musallamatullaa shiyata feehaa; qaalul \'aana jita bilhaqq; fazabahoohaa wa maa kaado yaf\'aloon',71,'2:71',1,4,9,1,0,11,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(79,2,'وَإِذْ قَتَلْتُمْ نَفْسًا فَٱدَّٰرَْٰٔتُمْ فِيهَا ۖ وَٱللَّهُ مُخْرِجٌ مَّا كُنتُمْ تَكْتُمُونَ','Wa iz qataltum nafsan faddaara\'tum feehaa wallaahu mukrijum maa kuntum taktumoon',72,'2:72',1,4,10,1,0,11,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(80,2,'فَقُلْنَا ٱضْرِبُوهُ بِبَعْضِهَا ۚ كَذَٰلِكَ يُحْىِ ٱللَّهُ ٱلْمَوْتَىٰ وَيُرِيكُمْ ءَايَـٰتِهِۦ لَعَلَّكُمْ تَعْقِلُونَ','Faqulnad riboohu biba\'dihaa; kazaalika yuhyil laa hul mawtaa wa yureekum aayaatihee la\'allakum ta\'qiloon',73,'2:73',1,4,10,1,0,11,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(81,2,'ثُمَّ قَسَتْ قُلُوبُكُم مِّنۢ بَعْدِ ذَٰلِكَ فَهِىَ كَٱلْحِجَارَةِ أَوْ أَشَدُّ قَسْوَةً ۚ وَإِنَّ مِنَ ٱلْحِجَارَةِ لَمَا يَتَفَجَّرُ مِنْهُ ٱلْأَنْهَـٰرُ ۚ وَإِنَّ مِنْهَا لَمَا يَشَّقَّقُ فَيَخْرُجُ مِنْهُ ٱلْمَآءُ ۚ وَإِنَّ مِنْهَا لَمَا يَهْبِطُ مِنْ خَشْيَةِ ٱللَّهِ ۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعْمَلُونَ','Summa qasat quloobukum mim ba\'di zaalika fahiya kalhijaarati aw-ashaadu qaswah; wa inna minal hijaarati lamaa yatafajjaru minhul anhaar; wa inna minhaa lamaa yash shaqqaqu fayakhruju minhul maaa\'; wa inna minhaa lamaa yahbitu min khashyatil laa; wa mal laahu bighaafilin \'ammaa ta\'maloon',74,'2:74',1,4,10,1,0,11,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(82,2,'۞ أَفَتَطْمَعُونَ أَن يُؤْمِنُوا۟ لَكُمْ وَقَدْ كَانَ فَرِيقٌ مِّنْهُمْ يَسْمَعُونَ كَلَـٰمَ ٱللَّهِ ثُمَّ يُحَرِّفُونَهُۥ مِنۢ بَعْدِ مَا عَقَلُوهُ وَهُمْ يَعْلَمُونَ','Afatatma\'oona ai yu\'minoo lakum wa qad kaana fareequm minhum yasma\'oona Kalaamal laahi summa yuharri foonahoo mim ba\'di maa\'aqaloohu wa hum ya\'lamoon',75,'2:75',2,5,10,1,0,11,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(83,2,'وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَا بَعْضُهُمْ إِلَىٰ بَعْضٍ قَالُوٓا۟ أَتُحَدِّثُونَهُم بِمَا فَتَحَ ٱللَّهُ عَلَيْكُمْ لِيُحَآجُّوكُم بِهِۦ عِندَ رَبِّكُمْ ۚ أَفَلَا تَعْقِلُونَ','Wa izaa laqul lazeena aamanoo qaalooo aamannaa wa izaakhalaa ba\'duhum ilaa ba\'din qaalooo atuhaddisoonahum bimaa fatahal laahu \'alaikum liyuhaajjookum bihee \'inda rabbikum; afalaa ta\'qiloon',76,'2:76',2,5,10,1,0,11,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(84,2,'أَوَلَا يَعْلَمُونَ أَنَّ ٱللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ','Awalaa ya\'lamoona annal laaha ya\'lamu maa yusirroona wa maa yu\'linoon',77,'2:77',2,5,10,1,0,12,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(85,2,'وَمِنْهُمْ أُمِّيُّونَ لَا يَعْلَمُونَ ٱلْكِتَـٰبَ إِلَّآ أَمَانِىَّ وَإِنْ هُمْ إِلَّا يَظُنُّونَ','Wa minhum ummiyyoona laa ya\'lamoonal kitaaba illaaa amaaniyya wa in hum illaa yazunnoon',78,'2:78',2,5,10,1,0,12,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(86,2,'فَوَيْلٌ لِّلَّذِينَ يَكْتُبُونَ ٱلْكِتَـٰبَ بِأَيْدِيهِمْ ثُمَّ يَقُولُونَ هَـٰذَا مِنْ عِندِ ٱللَّهِ لِيَشْتَرُوا۟ بِهِۦ ثَمَنًا قَلِيلًا ۖ فَوَيْلٌ لَّهُم مِّمَّا كَتَبَتْ أَيْدِيهِمْ وَوَيْلٌ لَّهُم مِّمَّا يَكْسِبُونَ','Fawailul lillazeena yaktuboonal kitaaba bi aydddhim summa yaqooloona haazaa min \'indil laahi liyashtaroo bihee samanan qaleelan fawilul lahum mimaa katabat aydeehim wa wailul lahum mimmaa yaksiboon',79,'2:79',2,5,10,1,0,12,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(87,2,'وَقَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًا مَّعْدُودَةً ۚ قُلْ أَتَّخَذْتُمْ عِندَ ٱللَّهِ عَهْدًا فَلَن يُخْلِفَ ٱللَّهُ عَهْدَهُۥٓ ۖ أَمْ تَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ','Wa qaaloo lan tamassanan Naaru illaaa ayyaamam ma\'doo dah; qul attakhaztum \'indal laahi \'ahdan falai yukhlifal laahu \'ahdahooo am taqooloona \'alal laahi maa laa ta\'lamoon',80,'2:80',2,5,10,1,0,12,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(88,2,'بَلَىٰ مَن كَسَبَ سَيِّئَةً وَأَحَـٰطَتْ بِهِۦ خَطِيٓـَٔتُهُۥ فَأُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ','Balaa man kasaba sayyi\'atanw wa ahaatat bihee khateee\'atuhoo fa-ulaaa\'ika Ashaabun Naari hum feehaa khaalidoon',81,'2:81',2,5,10,1,0,12,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(89,2,'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْجَنَّةِ ۖ هُمْ فِيهَا خَـٰلِدُونَ','Wallazeena aamanoo wa \'amilus saalihaati ulaaa\'ika Ashaabul Jannati hum feeha khaalidoon',82,'2:82',2,5,10,1,0,12,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(90,2,'وَإِذْ أَخَذْنَا مِيثَـٰقَ بَنِىٓ إِسْرَٰٓءِيلَ لَا تَعْبُدُونَ إِلَّا ٱللَّهَ وَبِٱلْوَٰلِدَيْنِ إِحْسَانًا وَذِى ٱلْقُرْبَىٰ وَٱلْيَتَـٰمَىٰ وَٱلْمَسَـٰكِينِ وَقُولُوا۟ لِلنَّاسِ حُسْنًا وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ ثُمَّ تَوَلَّيْتُمْ إِلَّا قَلِيلًا مِّنكُمْ وَأَنتُم مُّعْرِضُونَ','Wa iz akhaznaa meesaaqa Baneee Israaa\'eela laa ta\'budoona illal laaha wa bil waalidaini ihsaananw wa zil qurbaa walyataamaa walmasaakeeni wa qooloo linnaasi husnanw wa aqeemus salaata wa aatuzZakaata summa tawallitum illaa qaleelam minkum wa antum mu\'ridoon',83,'2:83',2,5,11,1,0,12,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(91,2,'وَإِذْ أَخَذْنَا مِيثَـٰقَكُمْ لَا تَسْفِكُونَ دِمَآءَكُمْ وَلَا تُخْرِجُونَ أَنفُسَكُم مِّن دِيَـٰرِكُمْ ثُمَّ أَقْرَرْتُمْ وَأَنتُمْ تَشْهَدُونَ','Wa iz akhaznaa meesaa qakum laa tasfikoona dimaaa\'akum wa laa tukrijoona anfusakum min diyaarikum summa aqrartum wa antum tashhadoon',84,'2:84',2,5,11,1,0,13,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(92,2,'ثُمَّ أَنتُمْ هَـٰٓؤُلَآءِ تَقْتُلُونَ أَنفُسَكُمْ وَتُخْرِجُونَ فَرِيقًا مِّنكُم مِّن دِيَـٰرِهِمْ تَظَـٰهَرُونَ عَلَيْهِم بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَإِن يَأْتُوكُمْ أُسَـٰرَىٰ تُفَـٰدُوهُمْ وَهُوَ مُحَرَّمٌ عَلَيْكُمْ إِخْرَاجُهُمْ ۚ أَفَتُؤْمِنُونَ بِبَعْضِ ٱلْكِتَـٰبِ وَتَكْفُرُونَ بِبَعْضٍ ۚ فَمَا جَزَآءُ مَن يَفْعَلُ ذَٰلِكَ مِنكُمْ إِلَّا خِزْىٌ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَيَوْمَ ٱلْقِيَـٰمَةِ يُرَدُّونَ إِلَىٰٓ أَشَدِّ ٱلْعَذَابِ ۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعْمَلُونَ','Summa antum haaa\'ulaaa\'i taqtuloona anfusakum wa tukhrijoona fareeqam minkum min diyaarihim tazaaharoona \'alaihim bil ismi wal\'udwaani wa iny yaatookum usaaraa tufaadoohum wahuwa muharramun \'alaikum ikhraajuhum; afatu\' mi-noona biba\'dil Kitaabi wa takfuroona biba\'d; famaa jazaaa\'u mai yaf\'alu zaalika minkum illaa khizyun fil hayaatid-dunyaa wa yawmal qiyaamati yuraddoona ilaaa ashaddil \'azaab; wa mal laahu bighaafilin \'ammaa ta\'maloon',85,'2:85',2,5,11,1,0,13,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(93,2,'أُو۟لَـٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلْحَيَوٰةَ ٱلدُّنْيَا بِٱلْـَٔاخِرَةِ ۖ فَلَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنصَرُونَ','Ulaaa\'ikal lazeenash tarawul hayaatad dunyaa bil aakhirati falaa yukhaffafu \'anhumul \'azaabu wa laa hum yunsaroon',86,'2:86',2,5,11,1,0,13,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(94,2,'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَـٰبَ وَقَفَّيْنَا مِنۢ بَعْدِهِۦ بِٱلرُّسُلِ ۖ وَءَاتَيْنَا عِيسَى ٱبْنَ مَرْيَمَ ٱلْبَيِّنَـٰتِ وَأَيَّدْنَـٰهُ بِرُوحِ ٱلْقُدُسِ ۗ أَفَكُلَّمَا جَآءَكُمْ رَسُولٌۢ بِمَا لَا تَهْوَىٰٓ أَنفُسُكُمُ ٱسْتَكْبَرْتُمْ فَفَرِيقًا كَذَّبْتُمْ وَفَرِيقًا تَقْتُلُونَ','Wa laqad aatainaa Moosal Kitaaba wa qaffainaa mim ba\'dihee bir Rusuli wa aatainaa \'Eesab-na-Maryamal baiyinaati wa ayyadnaahu bi Roohil Qudus; afakullamaa jaaa\'akum Rasoolum bimaa laa tahwaaa anfusukumus takbartum fafareeqan kazzabtum wa fareeqan taqtuloon',87,'2:87',2,5,12,1,0,13,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(95,2,'وَقَالُوا۟ قُلُوبُنَا غُلْفٌۢ ۚ بَل لَّعَنَهُمُ ٱللَّهُ بِكُفْرِهِمْ فَقَلِيلًا مَّا يُؤْمِنُونَ','Wa qaaloo quloobunaa ghulf; bal la\'anahumul laahu bikufrihim faqaleelam maa yu\'minoon',88,'2:88',2,5,12,1,0,13,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(96,2,'وَلَمَّا جَآءَهُمْ كِتَـٰبٌ مِّنْ عِندِ ٱللَّهِ مُصَدِّقٌ لِّمَا مَعَهُمْ وَكَانُوا۟ مِن قَبْلُ يَسْتَفْتِحُونَ عَلَى ٱلَّذِينَ كَفَرُوا۟ فَلَمَّا جَآءَهُم مَّا عَرَفُوا۟ كَفَرُوا۟ بِهِۦ ۚ فَلَعْنَةُ ٱللَّهِ عَلَى ٱلْكَـٰفِرِينَ','Wa lammaa jaaa\'ahum Kitaabum min \'indil laahi musaddiqul limaa ma\'ahum wa kaanoo min qablu yastaftihoona \'alal lazeena kafaroo falammaa jaaa\'ahum maa \'arafoo kafaroo bih; fala \'natul laahi \'alal kaafireen',89,'2:89',2,5,12,1,0,14,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(97,2,'بِئْسَمَا ٱشْتَرَوْا۟ بِهِۦٓ أَنفُسَهُمْ أَن يَكْفُرُوا۟ بِمَآ أَنزَلَ ٱللَّهُ بَغْيًا أَن يُنَزِّلَ ٱللَّهُ مِن فَضْلِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ ۖ فَبَآءُو بِغَضَبٍ عَلَىٰ غَضَبٍ ۚ وَلِلْكَـٰفِرِينَ عَذَابٌ مُّهِينٌ','Bi\'samash taraw biheee anfusahum ai yakfuroo bimaaa anzalal laahu baghyan ai yunazzilal laahu min fadlilhee \'alaa mai yashaaa\'u min ibaadihee fabaaa\'oo bighadabin \'alaa ghadab; wa lilkaafireena \'azaabum muheen',90,'2:90',2,5,12,1,0,14,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(98,2,'وَإِذَا قِيلَ لَهُمْ ءَامِنُوا۟ بِمَآ أَنزَلَ ٱللَّهُ قَالُوا۟ نُؤْمِنُ بِمَآ أُنزِلَ عَلَيْنَا وَيَكْفُرُونَ بِمَا وَرَآءَهُۥ وَهُوَ ٱلْحَقُّ مُصَدِّقًا لِّمَا مَعَهُمْ ۗ قُلْ فَلِمَ تَقْتُلُونَ أَنۢبِيَآءَ ٱللَّهِ مِن قَبْلُ إِن كُنتُم مُّؤْمِنِينَ','Wa izaa qeela lahum aaminoo bimaaa anzalal laahu qaaloo nu\'minu bimaaa unzila \'alainaa wa yakfuroona bimaa waraaa\'ahoo wa huwal haqqu musaddiqal limaa ma\'ahum; qul falima taqtuloona Ambiyaaa\'al laahi min qablu in kuntum mu\'mineen',91,'2:91',2,5,12,1,0,14,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(99,2,'۞ وَلَقَدْ جَآءَكُم مُّوسَىٰ بِٱلْبَيِّنَـٰتِ ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَـٰلِمُونَ','Wa laqad jaaa\'akum Moosa bilbaiyinaati summat takhaztunmul \'ijla mim ba\'dihee wa antum zaalimoon',92,'2:92',2,6,12,1,0,14,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(100,2,'وَإِذْ أَخَذْنَا مِيثَـٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ ٱلطُّورَ خُذُوا۟ مَآ ءَاتَيْنَـٰكُم بِقُوَّةٍ وَٱسْمَعُوا۟ ۖ قَالُوا۟ سَمِعْنَا وَعَصَيْنَا وَأُشْرِبُوا۟ فِى قُلُوبِهِمُ ٱلْعِجْلَ بِكُفْرِهِمْ ۚ قُلْ بِئْسَمَا يَأْمُرُكُم بِهِۦٓ إِيمَـٰنُكُمْ إِن كُنتُم مُّؤْمِنِينَ','Wa iz akhaznaa meesaaqakum wa rafa\'naa fawqa kumut Toora khuzoo maaa aatainaakum biquwwatinw wasma\'oo qaaloo sami\'naa wa \'asainaa wa ushriboo fee quloobihimul \'ijla bikufrihim; qul bi\'samaa yaamurukum biheee eemaanukum in kuntum m\'mineen',93,'2:93',2,6,12,1,0,14,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(101,2,'قُلْ إِن كَانَتْ لَكُمُ ٱلدَّارُ ٱلْـَٔاخِرَةُ عِندَ ٱللَّهِ خَالِصَةً مِّن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلْمَوْتَ إِن كُنتُمْ صَـٰدِقِينَ','Qul in kaanat lakumud Daarul Aakhiratu \'indal laahi khaalisatam min doonin naasi fatamannawul mawta in kuntum saadiqeen',94,'2:94',2,6,12,1,0,15,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(102,2,'وَلَن يَتَمَنَّوْهُ أَبَدًۢا بِمَا قَدَّمَتْ أَيْدِيهِمْ ۗ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّـٰلِمِينَ','Wa lai yatamannawhu abadam bimaa qaddamat aydeehim; wallaahu \'aleemum bizzaalimeen',95,'2:95',2,6,12,1,0,15,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(103,2,'وَلَتَجِدَنَّهُمْ أَحْرَصَ ٱلنَّاسِ عَلَىٰ حَيَوٰةٍ وَمِنَ ٱلَّذِينَ أَشْرَكُوا۟ ۚ يَوَدُّ أَحَدُهُمْ لَوْ يُعَمَّرُ أَلْفَ سَنَةٍ وَمَا هُوَ بِمُزَحْزِحِهِۦ مِنَ ٱلْعَذَابِ أَن يُعَمَّرَ ۗ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ','Wa latajidannahum ahrasannaasi \'alaa hayaatinw wa minal lazeena ashrakoo; yawaddu ahaduhum law yu\'ammaru alfa sanatinw wa maa huwa bi muzahzihihee minal \'azaabi ai yu\'ammar; wallaahu baseerum bimaa ya\'maloon',96,'2:96',2,6,12,1,0,15,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(104,2,'قُلْ مَن كَانَ عَدُوًّا لِّجِبْرِيلَ فَإِنَّهُۥ نَزَّلَهُۥ عَلَىٰ قَلْبِكَ بِإِذْنِ ٱللَّهِ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ وَهُدًى وَبُشْرَىٰ لِلْمُؤْمِنِينَ','Qul man kaana \'aduwwal li Jibreela fainnahoo nazzalahoo \'alaa qalbika bi iznil laahi musaddiqal limaa baina yadihi wa hudanw wa bushraa lilmu\'mineen',97,'2:97',2,6,13,1,0,15,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(105,2,'مَن كَانَ عَدُوًّا لِّلَّهِ وَمَلَـٰٓئِكَتِهِۦ وَرُسُلِهِۦ وَجِبْرِيلَ وَمِيكَىٰلَ فَإِنَّ ٱللَّهَ عَدُوٌّ لِّلْكَـٰفِرِينَ','Man kaana \'aduwwal lillaahi wa malaaa\'ikatihee wa Rusulihee wa Jibreela wa Meekaala fa innal laaha \'aduwwul lilkaafireen',98,'2:98',2,6,13,1,0,15,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(106,2,'وَلَقَدْ أَنزَلْنَآ إِلَيْكَ ءَايَـٰتٍۭ بَيِّنَـٰتٍ ۖ وَمَا يَكْفُرُ بِهَآ إِلَّا ٱلْفَـٰسِقُونَ','Wa laqad anzalnaaa ilaika Aayaatim baiyinaatinw wa maa yakfuru bihaaa illal faasiqoon',99,'2:99',2,6,13,1,0,15,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(107,2,'أَوَكُلَّمَا عَـٰهَدُوا۟ عَهْدًا نَّبَذَهُۥ فَرِيقٌ مِّنْهُم ۚ بَلْ أَكْثَرُهُمْ لَا يُؤْمِنُونَ','Awa kullamaa \'aahadoo ahdan nabazahoo fareequm minhum; bal aksaruhum laa u\'minoon',100,'2:100',2,6,13,1,0,15,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(108,2,'وَلَمَّا جَآءَهُمْ رَسُولٌ مِّنْ عِندِ ٱللَّهِ مُصَدِّقٌ لِّمَا مَعَهُمْ نَبَذَ فَرِيقٌ مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ كِتَـٰبَ ٱللَّهِ وَرَآءَ ظُهُورِهِمْ كَأَنَّهُمْ لَا يَعْلَمُونَ','Wa lammaa jaaa\'ahum Rasoolum min \'indil laahi musaddiqul limaa ma\'ahum nabaza fareequm minal lazeena ootul Kitaaba Kitaabal laahi waraaa\'a zuhoorihim ka annahum laa ya\'lamoon',101,'2:101',2,6,13,1,0,15,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(109,2,'وَٱتَّبَعُوا۟ مَا تَتْلُوا۟ ٱلشَّيَـٰطِينُ عَلَىٰ مُلْكِ سُلَيْمَـٰنَ ۖ وَمَا كَفَرَ سُلَيْمَـٰنُ وَلَـٰكِنَّ ٱلشَّيَـٰطِينَ كَفَرُوا۟ يُعَلِّمُونَ ٱلنَّاسَ ٱلسِّحْرَ وَمَآ أُنزِلَ عَلَى ٱلْمَلَكَيْنِ بِبَابِلَ هَـٰرُوتَ وَمَـٰرُوتَ ۚ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّىٰ يَقُولَآ إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ ۖ فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِۦ بَيْنَ ٱلْمَرْءِ وَزَوْجِهِۦ ۚ وَمَا هُم بِضَآرِّينَ بِهِۦ مِنْ أَحَدٍ إِلَّا بِإِذْنِ ٱللَّهِ ۚ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ ۚ وَلَقَدْ عَلِمُوا۟ لَمَنِ ٱشْتَرَىٰهُ مَا لَهُۥ فِى ٱلْـَٔاخِرَةِ مِنْ خَلَـٰقٍ ۚ وَلَبِئْسَ مَا شَرَوْا۟ بِهِۦٓ أَنفُسَهُمْ ۚ لَوْ كَانُوا۟ يَعْلَمُونَ','Wattaba\'oo maa tatlush Shayaateenu \'alaa mulki Sulaimaana wa maa kafara Sulaimaanu wa laakinnash Shayattena kafaroo yu\'al limoonan naasas sihra wa maaa unzila \'alal malakaini bi Baabila Haaroota wa Maaroot; wa maa yu\'allimaani min ahadin hattaa yaqoolaaa innamaa nahnu fitnatun falaa takfur fayata\'al lamoona minhumaa maa yufarriqoona bihee bainal mar\'i wa zawjih; wa maa hum bidaaarreena bihee min ahadin illaa bi-iznillah; wa yata\'allamoona maa yadurruhum wa laa yanfa\'uhum; wa laqad \'alimoo lamanish taraahu maa lahoo fil Aakhirati min khalaaq; wa labi\'sa maa sharaw biheee anfusahum; law kaanoo ya\'lamoon',102,'2:102',2,6,13,1,0,16,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(110,2,'وَلَوْ أَنَّهُمْ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَمَثُوبَةٌ مِّنْ عِندِ ٱللَّهِ خَيْرٌ ۖ لَّوْ كَانُوا۟ يَعْلَمُونَ','Wa law annahum aamanoo wattaqaw lamasoobatum min \'indillaahi khairun law kaanoo ya\'lamoon',103,'2:103',2,6,13,1,0,16,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(111,2,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقُولُوا۟ رَٰعِنَا وَقُولُوا۟ ٱنظُرْنَا وَٱسْمَعُوا۟ ۗ وَلِلْكَـٰفِرِينَ عَذَابٌ أَلِيمٌ','Yaaa ayyuhal lazeena aamanoo laa taqooloo raa\'inaa wa qoolun zurnaa wasma\'oo; wa lilkaafireena \'azaabun aleem',104,'2:104',2,6,14,1,0,16,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(112,2,'مَّا يَوَدُّ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَـٰبِ وَلَا ٱلْمُشْرِكِينَ أَن يُنَزَّلَ عَلَيْكُم مِّنْ خَيْرٍ مِّن رَّبِّكُمْ ۗ وَٱللَّهُ يَخْتَصُّ بِرَحْمَتِهِۦ مَن يَشَآءُ ۚ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ','Maa yawaddul lazeena kafaroo min ahlil kitaabi wa lal mushrikeena ai-yunazzala \'alaikum min khairim mir Rabbikum; wallaahu yakhtassu birahmatihee mai-yashaaa; wallaahu zul fadlil\'azeem',105,'2:105',2,6,14,1,0,16,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(113,2,'۞ مَا نَنسَخْ مِنْ ءَايَةٍ أَوْ نُنسِهَا نَأْتِ بِخَيْرٍ مِّنْهَآ أَوْ مِثْلِهَآ ۗ أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ','Maa nansakh min aayatin aw nunsihaa na-ti bikhairim minhaaa aw mislihaaa; alam ta\'lam annal laaha \'alaa kulli shai\'in qadeer',106,'2:106',2,7,14,1,0,17,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(114,2,'أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۗ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ','Alam ta\'lam annallaaha lahoo mulkus samaawaati wal ard; wa maa lakum min doonil laahi minw waliyyinw wa laa naseer',107,'2:107',2,7,14,1,0,17,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(115,2,'أَمْ تُرِيدُونَ أَن تَسْـَٔلُوا۟ رَسُولَكُمْ كَمَا سُئِلَ مُوسَىٰ مِن قَبْلُ ۗ وَمَن يَتَبَدَّلِ ٱلْكُفْرَ بِٱلْإِيمَـٰنِ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ','Am tureedoona an tas\'aloo Rasoolakum kamaa su\'ila Moosa min qabl; wa mai yatabaddalil kufra bil eemaani faqad dalla sawaaa\'as sabeel',108,'2:108',2,7,14,1,0,17,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(116,2,'وَدَّ كَثِيرٌ مِّنْ أَهْلِ ٱلْكِتَـٰبِ لَوْ يَرُدُّونَكُم مِّنۢ بَعْدِ إِيمَـٰنِكُمْ كُفَّارًا حَسَدًا مِّنْ عِندِ أَنفُسِهِم مِّنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْحَقُّ ۖ فَٱعْفُوا۟ وَٱصْفَحُوا۟ حَتَّىٰ يَأْتِىَ ٱللَّهُ بِأَمْرِهِۦٓ ۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ','Wadda kaseerum min ahlil kitaabi law yaruddoo nakum mim ba\'di eemaanikum kuffaaran hasadam min \'indi anfusihim mim ba\'di maa tabaiyana lahumul haqqu fa\'foo washfahoo hattaa yaa tiyallaahu bi amrih; innal laaha \'alaa kulli shai\'in qadeer',109,'2:109',2,7,14,1,0,17,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(117,2,'وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ ۚ وَمَا تُقَدِّمُوا۟ لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ ٱللَّهِ ۗ إِنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ','Wa aqeemus salaata wa aatuz zakaah; wa maa tuqaddimoo li anfusikum min khairin tajidoohu \'indal laah; innal laaha bimaa ta\'maloona baseer',110,'2:110',2,7,14,1,0,17,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(118,2,'وَقَالُوا۟ لَن يَدْخُلَ ٱلْجَنَّةَ إِلَّا مَن كَانَ هُودًا أَوْ نَصَـٰرَىٰ ۗ تِلْكَ أَمَانِيُّهُمْ ۗ قُلْ هَاتُوا۟ بُرْهَـٰنَكُمْ إِن كُنتُمْ صَـٰدِقِينَ','Wa qaaloo lai yadkhulal jannata illaa man kaana Hoodan aw Nasaaraa; tilka ammniyyuhum; qul haatoo burhaa nakum in kuntum saadiqeen',111,'2:111',2,7,14,1,0,17,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(119,2,'بَلَىٰ مَنْ أَسْلَمَ وَجْهَهُۥ لِلَّهِ وَهُوَ مُحْسِنٌ فَلَهُۥٓ أَجْرُهُۥ عِندَ رَبِّهِۦ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ','Balaa man aslama wajhahoo lillaahi wa huwa muhsinun falahooo ajruhoo \'inda rabbihee wa laa khawfun \'alaihim wa laa hum yahzanoon',112,'2:112',2,7,14,1,0,17,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(120,2,'وَقَالَتِ ٱلْيَهُودُ لَيْسَتِ ٱلنَّصَـٰرَىٰ عَلَىٰ شَىْءٍ وَقَالَتِ ٱلنَّصَـٰرَىٰ لَيْسَتِ ٱلْيَهُودُ عَلَىٰ شَىْءٍ وَهُمْ يَتْلُونَ ٱلْكِتَـٰبَ ۗ كَذَٰلِكَ قَالَ ٱلَّذِينَ لَا يَعْلَمُونَ مِثْلَ قَوْلِهِمْ ۚ فَٱللَّهُ يَحْكُمُ بَيْنَهُمْ يَوْمَ ٱلْقِيَـٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ','Wa qaalatil Yahoodu laisatin Nasaaraa \'alaa shai\'inw-wa qaalatin Nasaaraaa laisatil Yahoodu \'alaa shai\'inw\'wa hum yatloonal Kitaab; kazaalika qaalal lazeena la ya\'lamoona misla qawlihim Yawmal Qiyaamati feemaa kaanoo feehi yakhtalifoon',113,'2:113',2,7,15,1,0,18,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(121,2,'وَمَنْ أَظْلَمُ مِمَّن مَّنَعَ مَسَـٰجِدَ ٱللَّهِ أَن يُذْكَرَ فِيهَا ٱسْمُهُۥ وَسَعَىٰ فِى خَرَابِهَآ ۚ أُو۟لَـٰٓئِكَ مَا كَانَ لَهُمْ أَن يَدْخُلُوهَآ إِلَّا خَآئِفِينَ ۚ لَهُمْ فِى ٱلدُّنْيَا خِزْىٌ وَلَهُمْ فِى ٱلْـَٔاخِرَةِ عَذَابٌ عَظِيمٌ','Wa man azlamu mimmam-mana\'a masaajidal laahi ai-yuzkara feehas muhoo wa sa\'aa fee kharaabihaaa; ulaaa\'ika maa kaana lahum ai yadkhuloohaaa illaa khaaa\'\'feen; lahum fiddunyaa khizyunw wa lahum fil aakhirati \'azaabun \'azeem',114,'2:114',2,7,15,1,0,18,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(122,2,'وَلِلَّهِ ٱلْمَشْرِقُ وَٱلْمَغْرِبُ ۚ فَأَيْنَمَا تُوَلُّوا۟ فَثَمَّ وَجْهُ ٱللَّهِ ۚ إِنَّ ٱللَّهَ وَٰسِعٌ عَلِيمٌ','Wa lillaahil mashriqu walmaghrib; fa aynamaa tuwalloo fasamma wajhullaah; innal laaha waasi\'un Aleem',115,'2:115',2,7,15,1,0,18,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(123,2,'وَقَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدًا ۗ سُبْحَـٰنَهُۥ ۖ بَل لَّهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ كُلٌّ لَّهُۥ قَـٰنِتُونَ','Wa qaalut takhazal laahu waladan subhaanahoo bal lahoo maa fis samaawaati wal ardi kullul lahoo qaanitoon',116,'2:116',2,7,15,1,0,18,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(124,2,'بَدِيعُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ وَإِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ','Badree\'us samaawaati wal ardi wa izaa qadaaa amran fa innamaa yaqoolu lahoo kun fayakoon',117,'2:117',2,7,15,1,0,18,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(125,2,'وَقَالَ ٱلَّذِينَ لَا يَعْلَمُونَ لَوْلَا يُكَلِّمُنَا ٱللَّهُ أَوْ تَأْتِينَآ ءَايَةٌ ۗ كَذَٰلِكَ قَالَ ٱلَّذِينَ مِن قَبْلِهِم مِّثْلَ قَوْلِهِمْ ۘ تَشَـٰبَهَتْ قُلُوبُهُمْ ۗ قَدْ بَيَّنَّا ٱلْـَٔايَـٰتِ لِقَوْمٍ يُوقِنُونَ','Wa qaalal lazeena laa ya\'lamoona law laa yukallimunal laahu aw taateenaaa aayah; kazaalika qaalal lazeena min qablihim misla qawlihim; tashaabahat quloobuhum; qad baiyannal aayaati liqawminy yooqinoon',118,'2:118',2,7,15,1,0,18,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(126,2,'إِنَّآ أَرْسَلْنَـٰكَ بِٱلْحَقِّ بَشِيرًا وَنَذِيرًا ۖ وَلَا تُسْـَٔلُ عَنْ أَصْحَـٰبِ ٱلْجَحِيمِ','Innaaa arsalnaaka bilhaqqi basheeranw wa nazeeranw wa laa tus\'alu \'am Ashaabil Jaheem',119,'2:119',2,7,15,1,0,18,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(127,2,'وَلَن تَرْضَىٰ عَنكَ ٱلْيَهُودُ وَلَا ٱلنَّصَـٰرَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمْ ۗ قُلْ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلْهُدَىٰ ۗ وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم بَعْدَ ٱلَّذِى جَآءَكَ مِنَ ٱلْعِلْمِ ۙ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ','Wa lan tardaa \'ankal Yahoodu wa lan Nasaaraa hattaa tattabi\'a millatahum; qul inna hudal laahi huwalhudaa; wa la\'init taba\'ta ahwaaa\'ahum ba\'dal lazee jaaa\'aka minal \'ilmimaa laka minal laahi minw waliyyinw wa laa naseer',120,'2:120',2,7,15,1,0,19,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(128,2,'ٱلَّذِينَ ءَاتَيْنَـٰهُمُ ٱلْكِتَـٰبَ يَتْلُونَهُۥ حَقَّ تِلَاوَتِهِۦٓ أُو۟لَـٰٓئِكَ يُؤْمِنُونَ بِهِۦ ۗ وَمَن يَكْفُرْ بِهِۦ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْخَـٰسِرُونَ','Allazeena aatainaahumul Kitaaba yatloonahoo haqqa tilaawatiheee ulaaa\'ika yu\'minoona bi; wa mai yakfur bihee fa ulaaa\'ika humul khaasiroon',121,'2:121',2,7,15,1,0,19,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(129,2,'يَـٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّى فَضَّلْتُكُمْ عَلَى ٱلْعَـٰلَمِينَ','Yaa Baneee Israaa\'eelaz-kuroo ni\'matiyal lateee an\'amtu \'alaikum wa annee faddaltukum \'alal \'aalameen',122,'2:122',2,7,16,1,0,19,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(130,2,'وَٱتَّقُوا۟ يَوْمًا لَّا تَجْزِى نَفْسٌ عَن نَّفْسٍ شَيْـًٔا وَلَا يُقْبَلُ مِنْهَا عَدْلٌ وَلَا تَنفَعُهَا شَفَـٰعَةٌ وَلَا هُمْ يُنصَرُونَ','Wattaqoo yawmal laa tajzee nafsun \'an nafsin shai \'anw wa laa yuqbalu minhaa \'adlunw wa laa tanfa\'uhaa shafaa \'atunw wa laa hum yunsaroon',123,'2:123',2,7,16,1,0,19,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(131,2,'۞ وَإِذِ ٱبْتَلَىٰٓ إِبْرَٰهِـۧمَ رَبُّهُۥ بِكَلِمَـٰتٍ فَأَتَمَّهُنَّ ۖ قَالَ إِنِّى جَاعِلُكَ لِلنَّاسِ إِمَامًا ۖ قَالَ وَمِن ذُرِّيَّتِى ۖ قَالَ لَا يَنَالُ عَهْدِى ٱلظَّـٰلِمِينَ','Wa izib talaaa Ibraaheema Rabbuho bi Kalimaatin fa atammahunna qaala Innee jaa\'iluka linnaasi Imaaman qaala wa min zurriyyatee qaala laa yanaalu \'ahdiz zaalimeen',124,'2:124',2,8,16,1,0,19,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(132,2,'وَإِذْ جَعَلْنَا ٱلْبَيْتَ مَثَابَةً لِّلنَّاسِ وَأَمْنًا وَٱتَّخِذُوا۟ مِن مَّقَامِ إِبْرَٰهِـۧمَ مُصَلًّى ۖ وَعَهِدْنَآ إِلَىٰٓ إِبْرَٰهِـۧمَ وَإِسْمَـٰعِيلَ أَن طَهِّرَا بَيْتِىَ لِلطَّآئِفِينَ وَٱلْعَـٰكِفِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ','Wa iz ja\'alnal Baita masaabatal linnassi wa amnanw wattakhizoo mim Maqaami Ibraaheema musallaaa; wa \'ahidnaaa ilaaa Ibraaheema wa Ismaa\'eela an tahhiraa Baitiya littaaa\'ifeena wal\'aakifeena warrukka\'is sujood',125,'2:125',2,8,16,1,0,19,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(133,2,'وَإِذْ قَالَ إِبْرَٰهِـۧمُ رَبِّ ٱجْعَلْ هَـٰذَا بَلَدًا ءَامِنًا وَٱرْزُقْ أَهْلَهُۥ مِنَ ٱلثَّمَرَٰتِ مَنْ ءَامَنَ مِنْهُم بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ ۖ قَالَ وَمَن كَفَرَ فَأُمَتِّعُهُۥ قَلِيلًا ثُمَّ أَضْطَرُّهُۥٓ إِلَىٰ عَذَابِ ٱلنَّارِ ۖ وَبِئْسَ ٱلْمَصِيرُ','Wa iz qaala Ibraaheemu Rabbij \'al haazaa baladan aaminanw warzuq ahlahoo minas samaraati man aamana minhum billaahi wal yawmil aakhiri qaala wa man kafara faumatti\'uhoo qaleelan summa adtarruhooo ilaa \'azaabin Naari wa bi\'salmaseer',126,'2:126',2,8,16,1,0,19,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(134,2,'وَإِذْ يَرْفَعُ إِبْرَٰهِـۧمُ ٱلْقَوَاعِدَ مِنَ ٱلْبَيْتِ وَإِسْمَـٰعِيلُ رَبَّنَا تَقَبَّلْ مِنَّآ ۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلْعَلِيمُ','Wa iz yarfa\'u Ibraaheemul qawaa\'ida minal Baitiwa Ismaa\'eelu Rabbanaa taqabbal minnaa innaka Antas Samee\'ul Aleem',127,'2:127',2,8,16,1,0,20,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(135,2,'رَبَّنَا وَٱجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِن ذُرِّيَّتِنَآ أُمَّةً مُّسْلِمَةً لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبْ عَلَيْنَآ ۖ إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِيمُ','Rabbanaa waj\'alnaa muslimaini laka wa min zurriyyatinaaa ummatam muslimatal laka wa arinaa manaasikanaa wa tub \'alainaa innaka antat Tawwaabur Raheem',128,'2:128',2,8,16,1,0,20,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(136,2,'رَبَّنَا وَٱبْعَثْ فِيهِمْ رَسُولًا مِّنْهُمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَـٰتِكَ وَيُعَلِّمُهُمُ ٱلْكِتَـٰبَ وَٱلْحِكْمَةَ وَيُزَكِّيهِمْ ۚ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ','Rabbanaa wab\'as feehim Rasoolam minhum yatloo \'alaihim aayaatika wa yu\'allimuhumul Kitaaba wal Hikmata wa yuzakkeehim; innaka Antal \'Azeezul Hakeem',129,'2:129',2,8,16,1,0,20,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(137,2,'وَمَن يَرْغَبُ عَن مِّلَّةِ إِبْرَٰهِـۧمَ إِلَّا مَن سَفِهَ نَفْسَهُۥ ۚ وَلَقَدِ ٱصْطَفَيْنَـٰهُ فِى ٱلدُّنْيَا ۖ وَإِنَّهُۥ فِى ٱلْـَٔاخِرَةِ لَمِنَ ٱلصَّـٰلِحِينَ','Wa manny yarghabu \'am-Millarti Ibraaheema illaa man safiha nafsah; wa laqadis tafainaahu fid-dunyaa wa innaho fil aakhirati laminas saaliheen',130,'2:130',2,8,17,1,0,20,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(138,2,'إِذْ قَالَ لَهُۥ رَبُّهُۥٓ أَسْلِمْ ۖ قَالَ أَسْلَمْتُ لِرَبِّ ٱلْعَـٰلَمِينَ','Iz qaala lahoo Rabbuhooo aslim qaala aslamtu li Rabbil \'aalameen',131,'2:131',2,8,17,1,0,20,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(139,2,'وَوَصَّىٰ بِهَآ إِبْرَٰهِـۧمُ بَنِيهِ وَيَعْقُوبُ يَـٰبَنِىَّ إِنَّ ٱللَّهَ ٱصْطَفَىٰ لَكُمُ ٱلدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ','Wa wassaa bihaaa Ibraaheemu baneehi wa Ya\'qoob, yaa baniyya innal laahas tafaa lakumud deena falaa tamootunna illaa wa antum muslimoon',132,'2:132',2,8,17,1,0,20,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(140,2,'أَمْ كُنتُمْ شُهَدَآءَ إِذْ حَضَرَ يَعْقُوبَ ٱلْمَوْتُ إِذْ قَالَ لِبَنِيهِ مَا تَعْبُدُونَ مِنۢ بَعْدِى قَالُوا۟ نَعْبُدُ إِلَـٰهَكَ وَإِلَـٰهَ ءَابَآئِكَ إِبْرَٰهِـۧمَ وَإِسْمَـٰعِيلَ وَإِسْحَـٰقَ إِلَـٰهًا وَٰحِدًا وَنَحْنُ لَهُۥ مُسْلِمُونَ','Am kuntum shuhadaaa\'a iz hadara Ya\'qoobal mawtu iz qaala libaneehi maa ta\'budoona mim ba\'dee qaaloo na\'budu ilaahaka wa ilaaha aabaaa\'ika Ibraaheema wa Ismaa\'eela wa Ishaaqa Ilaahanw waahidanw wa nahnu lahoo muslimoon',133,'2:133',2,8,17,1,0,20,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(141,2,'تِلْكَ أُمَّةٌ قَدْ خَلَتْ ۖ لَهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ ۖ وَلَا تُسْـَٔلُونَ عَمَّا كَانُوا۟ يَعْمَلُونَ','Tilka ummatun qad khalat lahaa maa kasabat wa lakum maa kasabtum wa laa tus\'aloona \'ammaa kaano ya\'maloon',134,'2:134',2,8,17,1,0,20,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(142,2,'وَقَالُوا۟ كُونُوا۟ هُودًا أَوْ نَصَـٰرَىٰ تَهْتَدُوا۟ ۗ قُلْ بَلْ مِلَّةَ إِبْرَٰهِـۧمَ حَنِيفًا ۖ وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ','Wa qaaloo koonoo Hoodan aw Nasaaraa tahtadoo; qul bal Millata Ibraaheema Haneefanw wa maa kaana minal mushrikeen',135,'2:135',2,8,17,1,0,21,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(143,2,'قُولُوٓا۟ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْنَا وَمَآ أُنزِلَ إِلَىٰٓ إِبْرَٰهِـۧمَ وَإِسْمَـٰعِيلَ وَإِسْحَـٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَمَآ أُوتِىَ مُوسَىٰ وَعِيسَىٰ وَمَآ أُوتِىَ ٱلنَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّنْهُمْ وَنَحْنُ لَهُۥ مُسْلِمُونَ','Qoolooo aamannaa billaahi wa maaa unzila ilainaa wa maaa unzila ilaaa Ibraaheema wa Ismaa\'eela wa Ishaaqa wa Ya\'qooba wal Asbaati wa maaootiya Moosa wa \'Eesaa wa maaa ootiyan Nabiyyoona mir Rabbihim laa nufaariq baina ahadim minhum wa nahnu lahoo muslimoon',136,'2:136',2,8,17,1,0,21,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(144,2,'فَإِنْ ءَامَنُوا۟ بِمِثْلِ مَآ ءَامَنتُم بِهِۦ فَقَدِ ٱهْتَدَوا۟ ۖ وَّإِن تَوَلَّوْا۟ فَإِنَّمَا هُمْ فِى شِقَاقٍ ۖ فَسَيَكْفِيكَهُمُ ٱللَّهُ ۚ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ','Fa in aamanoo bimisli maaa aamantum bihee faqadih tadaw wa in tawallaw fa innamaa hum fee shiqaaq; fasayakfeekahumul laah; wa Huwas Samee\'ul Aleem',137,'2:137',2,8,17,1,0,21,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(145,2,'صِبْغَةَ ٱللَّهِ ۖ وَمَنْ أَحْسَنُ مِنَ ٱللَّهِ صِبْغَةً ۖ وَنَحْنُ لَهُۥ عَـٰبِدُونَ','Sibghatal laahi wa man ahsanu minal laahi sibghatanw wa nahnu lahoo \'aabidoon',138,'2:138',2,8,17,1,0,21,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(146,2,'قُلْ أَتُحَآجُّونَنَا فِى ٱللَّهِ وَهُوَ رَبُّنَا وَرَبُّكُمْ وَلَنَآ أَعْمَـٰلُنَا وَلَكُمْ أَعْمَـٰلُكُمْ وَنَحْنُ لَهُۥ مُخْلِصُونَ','Qul atuhaaajjoonanaa fil laahi wa Huwa Rabbunaa wa Rabbukum wa lanaa a\'maalunaa wa lakum a\'maalukum wa nahnu lahoo mukhlisson',139,'2:139',2,8,17,1,0,21,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(147,2,'أَمْ تَقُولُونَ إِنَّ إِبْرَٰهِـۧمَ وَإِسْمَـٰعِيلَ وَإِسْحَـٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطَ كَانُوا۟ هُودًا أَوْ نَصَـٰرَىٰ ۗ قُلْ ءَأَنتُمْ أَعْلَمُ أَمِ ٱللَّهُ ۗ وَمَنْ أَظْلَمُ مِمَّن كَتَمَ شَهَـٰدَةً عِندَهُۥ مِنَ ٱللَّهِ ۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعْمَلُونَ','Am taqooloona inna Ibraaheema wa Ismaa\'eela wa Ishaaq wa Ya\'qooba wal asbaata kaanoo Hoodan aw Nasaaraa; qul \'a-antum a\'lamu amil laah; wa man azlamu mimman katama shahaadatan \'indahoo minallaah; wa mallaahu bighaafilin \'ammaa ta\'maloon',140,'2:140',2,8,17,1,0,21,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(148,2,'تِلْكَ أُمَّةٌ قَدْ خَلَتْ ۖ لَهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ ۖ وَلَا تُسْـَٔلُونَ عَمَّا كَانُوا۟ يَعْمَلُونَ','Tilka ummatun qad khalat lahaa maa kasabat wa lakum maa kasabtum wa laa tus\'aloona \'ammaa kaano ya\'maloo',141,'2:141',2,8,17,1,0,21,1,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(149,2,'۞ سَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ مَا وَلَّىٰهُمْ عَن قِبْلَتِهِمُ ٱلَّتِى كَانُوا۟ عَلَيْهَا ۚ قُل لِّلَّهِ ٱلْمَشْرِقُ وَٱلْمَغْرِبُ ۚ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ','Sayaqoolus sufahaaa\'u minan naasi maa wallaahum \'an Qiblatihimul latee kaanoo \'alaihaa; qulo lillaahil mashriqu walmaghrib; yahdee mai yashaaa\'u ilaa Siraatim Mustaqeem',142,'2:142',3,9,18,1,0,22,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(150,2,'وَكَذَٰلِكَ جَعَلْنَـٰكُمْ أُمَّةً وَسَطًا لِّتَكُونُوا۟ شُهَدَآءَ عَلَى ٱلنَّاسِ وَيَكُونَ ٱلرَّسُولُ عَلَيْكُمْ شَهِيدًا ۗ وَمَا جَعَلْنَا ٱلْقِبْلَةَ ٱلَّتِى كُنتَ عَلَيْهَآ إِلَّا لِنَعْلَمَ مَن يَتَّبِعُ ٱلرَّسُولَ مِمَّن يَنقَلِبُ عَلَىٰ عَقِبَيْهِ ۚ وَإِن كَانَتْ لَكَبِيرَةً إِلَّا عَلَى ٱلَّذِينَ هَدَى ٱللَّهُ ۗ وَمَا كَانَ ٱللَّهُ لِيُضِيعَ إِيمَـٰنَكُمْ ۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٌ رَّحِيمٌ','Wa kazaalika ja\'alnaakum ummatanw wasatal litakoonoo shuhadaaa\'a \'alan naasi wa yakoonar Rasoolu \'alaikum shaheedaa; wa maa ja\'alnal qiblatal latee kunta \'alaihaaa illaa lina\'lama mai yattabi\'ur Rasoola mimmai yanqalibu \'alaa \'aqibayh; wa in kaanat lakabeeratan illaa \'alal lazeena hadal laah; wa maa kaanal laahu liyudee\'a eemaanakum; innal laaha binnaasi la Ra\'oofur Raheem',143,'2:143',3,9,18,1,0,22,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(151,2,'قَدْ نَرَىٰ تَقَلُّبَ وَجْهِكَ فِى ٱلسَّمَآءِ ۖ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَىٰهَا ۚ فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ ۚ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا۟ وُجُوهَكُمْ شَطْرَهُۥ ۗ وَإِنَّ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ لَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ ۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا يَعْمَلُونَ','Qad naraa taqalluba wajhika fis samaaa\'i fala nuwalliyannaka qiblatan tardaahaa; fawalli wajhaka shatral Masjidil haaraam; wa haisu maa kuntum fawalloo wujoohakum shatrah; wa innal lazeena ootul Kitaaba laya\'lamoona annahul haqqu mir Rabbihim; wa mal laahu bighaafilin \'ammaa ya\'maloon',144,'2:144',3,9,18,1,0,22,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(152,2,'وَلَئِنْ أَتَيْتَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ بِكُلِّ ءَايَةٍ مَّا تَبِعُوا۟ قِبْلَتَكَ ۚ وَمَآ أَنتَ بِتَابِعٍ قِبْلَتَهُمْ ۚ وَمَا بَعْضُهُم بِتَابِعٍ قِبْلَةَ بَعْضٍ ۚ وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم مِّنۢ بَعْدِ مَا جَآءَكَ مِنَ ٱلْعِلْمِ ۙ إِنَّكَ إِذًا لَّمِنَ ٱلظَّـٰلِمِينَ','Wa la\'in ataital lazeena ootul kitaaba bikulli aayatim maa tabi\'oo Qiblatak; wa maaa anta bitaabi\'in Qiblatahum; wa maa ba\'duhum bitaabi\'\'in Qiblata ba\'d; wa la\'init taba\'ta ahwaaa;ahum mim ba\'di maa jaaa\'aka minal \'ilmi innaka izal laminaz zaalimeen',145,'2:145',3,9,18,1,0,22,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(153,2,'ٱلَّذِينَ ءَاتَيْنَـٰهُمُ ٱلْكِتَـٰبَ يَعْرِفُونَهُۥ كَمَا يَعْرِفُونَ أَبْنَآءَهُمْ ۖ وَإِنَّ فَرِيقًا مِّنْهُمْ لَيَكْتُمُونَ ٱلْحَقَّ وَهُمْ يَعْلَمُونَ','Allazeena aatainaahumul kitaaba ya\'rifoonahoo kamaa ya\'rifoona abnaaa\'ahum wa inna fareeqam minhum layaktumoonal haqqa wa hum ya\'lamoon',146,'2:146',3,9,18,1,0,23,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(154,2,'ٱلْحَقُّ مِن رَّبِّكَ ۖ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ','Alhaqqu mir Rabbika falaa takoonana minal mumtareen',147,'2:147',3,9,18,1,0,23,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(155,2,'وَلِكُلٍّ وِجْهَةٌ هُوَ مُوَلِّيهَا ۖ فَٱسْتَبِقُوا۟ ٱلْخَيْرَٰتِ ۚ أَيْنَ مَا تَكُونُوا۟ يَأْتِ بِكُمُ ٱللَّهُ جَمِيعًا ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ','Wa likullinw wijhatun huwa muwalleehaa fastabiqul khairaat; ayna maa takoonoo yaati bikumullaahu jamee\'aa; innal laaha \'alaa kulli shai\'in qadeer',148,'2:148',3,9,19,1,0,23,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(156,2,'وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ ۖ وَإِنَّهُۥ لَلْحَقُّ مِن رَّبِّكَ ۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعْمَلُونَ','Wa min haisu kharajta fawalli wajhaka shatral Masjidil Haraami wa innahoo lalhaqqu mir Rabbik; wa mallaahu bighaafilin \'ammaa ta\'maloon',149,'2:149',3,9,19,1,0,23,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(157,2,'وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ ۚ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا۟ وُجُوهَكُمْ شَطْرَهُۥ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيْكُمْ حُجَّةٌ إِلَّا ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ فَلَا تَخْشَوْهُمْ وَٱخْشَوْنِى وَلِأُتِمَّ نِعْمَتِى عَلَيْكُمْ وَلَعَلَّكُمْ تَهْتَدُونَ','Wa min haisu kharajta fawalli wajhaka shatral Masjidil Haraam; wa haisu maa kuntum fawalloo wujoohakum shatrahoo li\'allaa yakoona linnaasi \'alaikum hujjatun illal lazeena zalamoo minhum falaa takhshawhum wakhshawnee wa liutimma ni\'matee \'alaikum wa la\'allakum tahtadoon',150,'2:150',3,9,19,1,0,23,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(158,2,'كَمَآ أَرْسَلْنَا فِيكُمْ رَسُولًا مِّنكُمْ يَتْلُوا۟ عَلَيْكُمْ ءَايَـٰتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ ٱلْكِتَـٰبَ وَٱلْحِكْمَةَ وَيُعَلِّمُكُم مَّا لَمْ تَكُونُوا۟ تَعْلَمُونَ','kamaaa arsalnaa feekum Rasoolam minkum yatloo \'alaikum aayaatina wa yuzakkeekum wa yu\'alli mukumul kitaaba wal hikmata wa yu\'allimukum maa lam takoonoo ta\'lamoon',151,'2:151',3,9,19,1,0,23,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(159,2,'فَٱذْكُرُونِىٓ أَذْكُرْكُمْ وَٱشْكُرُوا۟ لِى وَلَا تَكْفُرُونِ','Fazkurooneee azkurkum washkuroo lee wa laa takfuroon',152,'2:152',3,9,19,1,0,23,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(160,2,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ ۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّـٰبِرِينَ','Yaaa ayyuhal laazeena aamanus ta\'eenoo bissabri was Salaah; innal laaha ma\'as-saabireen',153,'2:153',3,9,20,1,0,23,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(161,2,'وَلَا تَقُولُوا۟ لِمَن يُقْتَلُ فِى سَبِيلِ ٱللَّهِ أَمْوَٰتٌۢ ۚ بَلْ أَحْيَآءٌ وَلَـٰكِن لَّا تَشْعُرُونَ','Wa laa taqooloo limai yuqtalu fee sabeelil laahi amwaat; bal ahyaaa\'unw wa laakil laa tash\'uroon',154,'2:154',3,9,20,1,0,24,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(162,2,'وَلَنَبْلُوَنَّكُم بِشَىْءٍ مِّنَ ٱلْخَوْفِ وَٱلْجُوعِ وَنَقْصٍ مِّنَ ٱلْأَمْوَٰلِ وَٱلْأَنفُسِ وَٱلثَّمَرَٰتِ ۗ وَبَشِّرِ ٱلصَّـٰبِرِينَ','Wa lanablu wannakum bishai\'im minal khawfi waljoo\'i wa naqsim minal amwaali wal anfusi was samaraat; wa bashshiris saabireen',155,'2:155',3,9,20,1,0,24,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(163,2,'ٱلَّذِينَ إِذَآ أَصَـٰبَتْهُم مُّصِيبَةٌ قَالُوٓا۟ إِنَّا لِلَّهِ وَإِنَّآ إِلَيْهِ رَٰجِعُونَ','Allazeena izaaa asaabathum museebatun qaalooo innaa lillaahi wa innaaa ilaihi raaji\'oon',156,'2:156',3,9,20,1,0,24,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(164,2,'أُو۟لَـٰٓئِكَ عَلَيْهِمْ صَلَوَٰتٌ مِّن رَّبِّهِمْ وَرَحْمَةٌ ۖ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُهْتَدُونَ','Ulaaa\'ika \'alaihim salawaatun mir Rabbihim wa rahma; wa ulaaa\'ika humul muhtadoon',157,'2:157',3,9,20,1,0,24,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(165,2,'۞ إِنَّ ٱلصَّفَا وَٱلْمَرْوَةَ مِن شَعَآئِرِ ٱللَّهِ ۖ فَمَنْ حَجَّ ٱلْبَيْتَ أَوِ ٱعْتَمَرَ فَلَا جُنَاحَ عَلَيْهِ أَن يَطَّوَّفَ بِهِمَا ۚ وَمَن تَطَوَّعَ خَيْرًا فَإِنَّ ٱللَّهَ شَاكِرٌ عَلِيمٌ','Innas Safaa wal-Marwata min sha\'aaa\'iril laahi faman hajjal Baita awi\'tamara falaa junaaha \'alaihi ai yattawwafa bihimaa; wa man tatawwa\'a khairan fa innal laaha Shaakirun\'Aleem',158,'2:158',3,10,20,1,0,24,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(166,2,'إِنَّ ٱلَّذِينَ يَكْتُمُونَ مَآ أَنزَلْنَا مِنَ ٱلْبَيِّنَـٰتِ وَٱلْهُدَىٰ مِنۢ بَعْدِ مَا بَيَّنَّـٰهُ لِلنَّاسِ فِى ٱلْكِتَـٰبِ ۙ أُو۟لَـٰٓئِكَ يَلْعَنُهُمُ ٱللَّهُ وَيَلْعَنُهُمُ ٱللَّـٰعِنُونَ','Innal lazeena yaktumoona maaa anzalnaa minal baiyinaati walhudaa mim ba\'di maa baiyannaahu linnaasi fil kitaabi ulaaa\'ika yal\'anuhumul laahu wa yal\'anuhumul laa \'inoon',159,'2:159',3,10,20,1,0,24,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(167,2,'إِلَّا ٱلَّذِينَ تَابُوا۟ وَأَصْلَحُوا۟ وَبَيَّنُوا۟ فَأُو۟لَـٰٓئِكَ أَتُوبُ عَلَيْهِمْ ۚ وَأَنَا ٱلتَّوَّابُ ٱلرَّحِيمُ','Illal lazeena taaboo wa aslahoo wa baiyanoo fa ulaaa\'ika atoobu \'alaihim; wa Anat Tawwaabur Raheem',160,'2:160',3,10,20,1,0,24,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(168,2,'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَمَاتُوا۟ وَهُمْ كُفَّارٌ أُو۟لَـٰٓئِكَ عَلَيْهِمْ لَعْنَةُ ٱللَّهِ وَٱلْمَلَـٰٓئِكَةِ وَٱلنَّاسِ أَجْمَعِينَ','Innal lazeena kafaroo wamaa too wa hum kuffaarun ulaaa\'ika \'alaihim la \'natul laahi walmalaa\'ikati wannaasi ajma\'een',161,'2:161',3,10,20,1,0,24,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(169,2,'خَـٰلِدِينَ فِيهَا ۖ لَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنظَرُونَ','khaalideena feeha laa yukhaffafu \'anhumul \'azaabu wa laa hum yunzaroon',162,'2:162',3,10,20,1,0,24,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(170,2,'وَإِلَـٰهُكُمْ إِلَـٰهٌ وَٰحِدٌ ۖ لَّآ إِلَـٰهَ إِلَّا هُوَ ٱلرَّحْمَـٰنُ ٱلرَّحِيمُ','Wa ilaahukum illaahunw waahid, laaa ilaaha illaa Huwar Rahmaanur Raheem',163,'2:163',3,10,20,1,0,24,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(171,2,'إِنَّ فِى خَلْقِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَـٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَٱلْفُلْكِ ٱلَّتِى تَجْرِى فِى ٱلْبَحْرِ بِمَا يَنفَعُ ٱلنَّاسَ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن مَّآءٍ فَأَحْيَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٍ وَتَصْرِيفِ ٱلرِّيَـٰحِ وَٱلسَّحَابِ ٱلْمُسَخَّرِ بَيْنَ ٱلسَّمَآءِ وَٱلْأَرْضِ لَـَٔايَـٰتٍ لِّقَوْمٍ يَعْقِلُونَ','Inna fee khalqis samaawaati wal ardi wakhtilaafil laili wannahaari walfulkil latee tajree fil hahri bimaa yanfa\'unnaasa wa maaa anzalal laahu minas samaaa\'i mim maaa\'in fa ahyaa bihil arda ba\'da mawtihaa wa bas sa feehaa min kulli daaabbatinw wa tasreefir riyaahi wassahaabil musakhkhari bainas samaaa\'i wal ardi la aayaatil liqawminy ya\'qiloon',164,'2:164',3,10,21,1,0,25,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(172,2,'وَمِنَ ٱلنَّاسِ مَن يَتَّخِذُ مِن دُونِ ٱللَّهِ أَندَادًا يُحِبُّونَهُمْ كَحُبِّ ٱللَّهِ ۖ وَٱلَّذِينَ ءَامَنُوٓا۟ أَشَدُّ حُبًّا لِّلَّهِ ۗ وَلَوْ يَرَى ٱلَّذِينَ ظَلَمُوٓا۟ إِذْ يَرَوْنَ ٱلْعَذَابَ أَنَّ ٱلْقُوَّةَ لِلَّهِ جَمِيعًا وَأَنَّ ٱللَّهَ شَدِيدُ ٱلْعَذَابِ','Wa minan naasi mai yattakhizu min doonil laahi andaadai yuhibboonahum kahubbil laahi wallazeena aamanooo ashaddu hubbal lillah; wa law yaral lazeena zalamoo iz yarawnal \'azaaba annal quwwata lillaahi jamee\'anw wa annallaaha shadeedul \'azaab',165,'2:165',3,10,21,1,0,25,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(173,2,'إِذْ تَبَرَّأَ ٱلَّذِينَ ٱتُّبِعُوا۟ مِنَ ٱلَّذِينَ ٱتَّبَعُوا۟ وَرَأَوُا۟ ٱلْعَذَابَ وَتَقَطَّعَتْ بِهِمُ ٱلْأَسْبَابُ','Iz tabarra al lazeenat tubi\'oo minal lazeenattaba\'oo wa ra awul \'azaaba wa taqatta\'at bihimul asbaab',166,'2:166',3,10,21,1,0,25,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(174,2,'وَقَالَ ٱلَّذِينَ ٱتَّبَعُوا۟ لَوْ أَنَّ لَنَا كَرَّةً فَنَتَبَرَّأَ مِنْهُمْ كَمَا تَبَرَّءُوا۟ مِنَّا ۗ كَذَٰلِكَ يُرِيهِمُ ٱللَّهُ أَعْمَـٰلَهُمْ حَسَرَٰتٍ عَلَيْهِمْ ۖ وَمَا هُم بِخَـٰرِجِينَ مِنَ ٱلنَّارِ','Wa qaalal lazeenat taba\'oo law anna lanaa karratan fanatabarra a minhum kamaa tabarra\'oo minnaa; kazaalika yureehimullaahu a\'maalahum hasaraatin \'alaihim wa maa hum bikhaarijeena minan Naar',167,'2:167',3,10,21,1,0,25,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(175,2,'يَـٰٓأَيُّهَا ٱلنَّاسُ كُلُوا۟ مِمَّا فِى ٱلْأَرْضِ حَلَـٰلًا طَيِّبًا وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَـٰنِ ۚ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ','Yaaa ayyuhan naasu kuloo mimmaa fil ardi halaalan taiyibanw wa laa tattabi\'oo khutu waatish Shaitaan; innahoo lakum \'aduwwum mubeen',168,'2:168',3,10,22,1,0,25,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(176,2,'إِنَّمَا يَأْمُرُكُم بِٱلسُّوٓءِ وَٱلْفَحْشَآءِ وَأَن تَقُولُوا۟ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ','Innamaa yaamurukum bissooo\'i walfahshaaa\'i wa an taqooloo alal laahi maa laa ta\'lamoon',169,'2:169',3,10,22,1,0,25,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(177,2,'وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُوا۟ مَآ أَنزَلَ ٱللَّهُ قَالُوا۟ بَلْ نَتَّبِعُ مَآ أَلْفَيْنَا عَلَيْهِ ءَابَآءَنَآ ۗ أَوَلَوْ كَانَ ءَابَآؤُهُمْ لَا يَعْقِلُونَ شَيْـًٔا وَلَا يَهْتَدُونَ','Wa izaa qeela lahumuttabi\'oo maaa anzalal laahu qaaloo bal nattabi\'u maaa alfainaa \'alaihi aabaaa\'anaaa; awalaw kaana aabaaa\'hum laa ya\'qiloona shai\'anw wa laa yahtadoon',170,'2:170',3,10,22,1,0,26,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(178,2,'وَمَثَلُ ٱلَّذِينَ كَفَرُوا۟ كَمَثَلِ ٱلَّذِى يَنْعِقُ بِمَا لَا يَسْمَعُ إِلَّا دُعَآءً وَنِدَآءً ۚ صُمٌّۢ بُكْمٌ عُمْىٌ فَهُمْ لَا يَعْقِلُونَ','Wa masalul lazeena kafaroo kamasalil lazee yan\'iqu bimaa laa yasma\'u illaa du\'aaa\'anw wa nidaaa\'aa; summum bukmun \'umyun fahum laa ya\'qiloon',171,'2:171',3,10,22,1,0,26,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(179,2,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُلُوا۟ مِن طَيِّبَـٰتِ مَا رَزَقْنَـٰكُمْ وَٱشْكُرُوا۟ لِلَّهِ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ','Yaaa ayyuhal lazeena aamanoo kuloo min taiyibaati maa razaqnaakum washkuroo lillaahi in kuntum iyyaahu ta\'budoon',172,'2:172',3,10,22,1,0,26,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(180,2,'إِنَّمَا حَرَّمَ عَلَيْكُمُ ٱلْمَيْتَةَ وَٱلدَّمَ وَلَحْمَ ٱلْخِنزِيرِ وَمَآ أُهِلَّ بِهِۦ لِغَيْرِ ٱللَّهِ ۖ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَلَآ إِثْمَ عَلَيْهِ ۚ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ','Innamaa harrama \'alaikumul maitata waddama wa lahmal khinzeeri wa maaa uhilla bihee lighairil laahi famanid turra ghaira baaghinw wa laa \'aadin falaaa isma \'alaih; innal laaha Ghafoorur Raheem',173,'2:173',3,10,22,1,0,26,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(181,2,'إِنَّ ٱلَّذِينَ يَكْتُمُونَ مَآ أَنزَلَ ٱللَّهُ مِنَ ٱلْكِتَـٰبِ وَيَشْتَرُونَ بِهِۦ ثَمَنًا قَلِيلًا ۙ أُو۟لَـٰٓئِكَ مَا يَأْكُلُونَ فِى بُطُونِهِمْ إِلَّا ٱلنَّارَ وَلَا يُكَلِّمُهُمُ ٱللَّهُ يَوْمَ ٱلْقِيَـٰمَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ','Innal lazeena yaktumoona maaa anzalal laahu minal kitaabi wa yashtaroona bihee samanan qaleelan ulaaa\'ika maa yaakuloona fee butoonihim illan Naara wa laa yukallimu humul laahu Yawmal Qiyaamati wa laa yuzakkeehim wa lahum \'azaabun aleem',174,'2:174',3,10,22,1,0,26,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(182,2,'أُو۟لَـٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلضَّلَـٰلَةَ بِٱلْهُدَىٰ وَٱلْعَذَابَ بِٱلْمَغْفِرَةِ ۚ فَمَآ أَصْبَرَهُمْ عَلَى ٱلنَّارِ','Ulaaa\'ikal lazeenash tarawud dalaalata bilhudaa wal\'azaaba bilmaghfirah; famaaa asbarahum \'alan Naar',175,'2:175',3,10,22,1,0,26,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(183,2,'ذَٰلِكَ بِأَنَّ ٱللَّهَ نَزَّلَ ٱلْكِتَـٰبَ بِٱلْحَقِّ ۗ وَإِنَّ ٱلَّذِينَ ٱخْتَلَفُوا۟ فِى ٱلْكِتَـٰبِ لَفِى شِقَاقٍۭ بَعِيدٍ','Zaalika bi annal laaha nazzalal kitaaba bilhaqq; wa innal lazeenakh talafoo fil kitaabi lafee shiqaaqim ba\'eed',176,'2:176',3,10,22,1,0,26,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(184,2,'۞ لَّيْسَ ٱلْبِرَّ أَن تُوَلُّوا۟ وُجُوهَكُمْ قِبَلَ ٱلْمَشْرِقِ وَٱلْمَغْرِبِ وَلَـٰكِنَّ ٱلْبِرَّ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَٱلْمَلَـٰٓئِكَةِ وَٱلْكِتَـٰبِ وَٱلنَّبِيِّـۧنَ وَءَاتَى ٱلْمَالَ عَلَىٰ حُبِّهِۦ ذَوِى ٱلْقُرْبَىٰ وَٱلْيَتَـٰمَىٰ وَٱلْمَسَـٰكِينَ وَٱبْنَ ٱلسَّبِيلِ وَٱلسَّآئِلِينَ وَفِى ٱلرِّقَابِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَٱلْمُوفُونَ بِعَهْدِهِمْ إِذَا عَـٰهَدُوا۟ ۖ وَٱلصَّـٰبِرِينَ فِى ٱلْبَأْسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلْبَأْسِ ۗ أُو۟لَـٰٓئِكَ ٱلَّذِينَ صَدَقُوا۟ ۖ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُتَّقُونَ','Laisal birra an tuwalloo wujoohakum qibalal mashriqi walmaghribi wa laakinnal birra man aamana billaahi wal yawmil aakhiri wal malaaa \'ikati wal kitaabi wan nabiyyeena wa aatalmaala \'alaa hubbihee zawilqurbaa walyataa maa walmasaakeena wabnas sabeeli wassaaa\'ileena wa firriqaabi wa aqaamas salaata wa aataz zakaata walmoofoona bi ahdihim izaa \'aahadoo wasaabireena fil baasaaa\'i waddarraaa\'i wa heenal baas; ulaaa\'ikal lazeena sadaqoo wa ulaaa \'ika humul muttaqoon',177,'2:177',3,11,23,1,0,27,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(185,2,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُتِبَ عَلَيْكُمُ ٱلْقِصَاصُ فِى ٱلْقَتْلَى ۖ ٱلْحُرُّ بِٱلْحُرِّ وَٱلْعَبْدُ بِٱلْعَبْدِ وَٱلْأُنثَىٰ بِٱلْأُنثَىٰ ۚ فَمَنْ عُفِىَ لَهُۥ مِنْ أَخِيهِ شَىْءٌ فَٱتِّبَاعٌۢ بِٱلْمَعْرُوفِ وَأَدَآءٌ إِلَيْهِ بِإِحْسَـٰنٍ ۗ ذَٰلِكَ تَخْفِيفٌ مِّن رَّبِّكُمْ وَرَحْمَةٌ ۗ فَمَنِ ٱعْتَدَىٰ بَعْدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٌ','Yaaa ayyuhal lazeena aamanoo kutiba alaikumul qisaasu fil qatlaa alhurru bilhurri wal\'abdu bil\'abdi wal unsaa bil unsaa; faman \'ufiya lahoo min akheehi shai\'un fattibaa\'um bilma\'roofi wa adaaa\'un ilaihi bi ihsaan; zaalika takhfeefum mir rahbikum wa rahmah; famani\' tadaa ba\'da zaalika falahoo \'azaabun aleem',178,'2:178',3,11,23,1,0,27,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(186,2,'وَلَكُمْ فِى ٱلْقِصَاصِ حَيَوٰةٌ يَـٰٓأُو۟لِى ٱلْأَلْبَـٰبِ لَعَلَّكُمْ تَتَّقُونَ','Wa lakum fil qisaasi hayaatuny yaaa ulil albaabi la \'allakum tattaqoon',179,'2:179',3,11,23,1,0,27,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(187,2,'كُتِبَ عَلَيْكُمْ إِذَا حَضَرَ أَحَدَكُمُ ٱلْمَوْتُ إِن تَرَكَ خَيْرًا ٱلْوَصِيَّةُ لِلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ بِٱلْمَعْرُوفِ ۖ حَقًّا عَلَى ٱلْمُتَّقِينَ','Kutiba \'alaikum izaa hadara ahadakumul mawtu in taraka khairanil wasiyyatu lilwaalidaini wal aqrabeena bilma\'roofi haqqan \'alalmut taqeen',180,'2:180',3,11,23,1,0,27,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(188,2,'فَمَنۢ بَدَّلَهُۥ بَعْدَ مَا سَمِعَهُۥ فَإِنَّمَآ إِثْمُهُۥ عَلَى ٱلَّذِينَ يُبَدِّلُونَهُۥٓ ۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ','Famam baddalahoo ba\'da maa sami\'ahoo fa innamaaa ismuhoo \'alallazeena yubaddi loonah; innallaha Samee\'un \'Aleem',181,'2:181',3,11,23,1,0,27,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(189,2,'فَمَنْ خَافَ مِن مُّوصٍ جَنَفًا أَوْ إِثْمًا فَأَصْلَحَ بَيْنَهُمْ فَلَآ إِثْمَ عَلَيْهِ ۚ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ','Faman khaafa mim moosin janafan aw isman fa aslaha bainahum falaaa ismaa \'alayh; innal laaha Ghafooru Raheem',182,'2:182',3,11,23,1,0,28,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(190,2,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُتِبَ عَلَيْكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ','Yaa ayyuhal lazeena aamanoo kutiba \'alaikumus Siyaamu kamaa kutiba \'alal lazeena min qablikum la\'allakum tattaqoon',183,'2:183',3,11,24,1,0,28,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(191,2,'أَيَّامًا مَّعْدُودَٰتٍ ۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ ۚ وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدْيَةٌ طَعَامُ مِسْكِينٍ ۖ فَمَن تَطَوَّعَ خَيْرًا فَهُوَ خَيْرٌ لَّهُۥ ۚ وَأَن تَصُومُوا۟ خَيْرٌ لَّكُمْ ۖ إِن كُنتُمْ تَعْلَمُونَ','Ayyaamam ma\'doodaat; faman kaana minkum mareedan aw\'alaa safarin fa\'iddatum min ayyaamin ukhar; wa \'alal lazeena yuteeqoonahoo fidyatun ta\'aamu miskeenin faman tatawwa\'a khairan fahuwa khairulo lahoo wa an tasoomoo khairul lakum in kuntum ta\'lamoon',184,'2:184',3,11,24,1,0,28,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(192,2,'شَهْرُ رَمَضَانَ ٱلَّذِىٓ أُنزِلَ فِيهِ ٱلْقُرْءَانُ هُدًى لِّلنَّاسِ وَبَيِّنَـٰتٍ مِّنَ ٱلْهُدَىٰ وَٱلْفُرْقَانِ ۚ فَمَن شَهِدَ مِنكُمُ ٱلشَّهْرَ فَلْيَصُمْهُ ۖ وَمَن كَانَ مَرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ ۗ يُرِيدُ ٱللَّهُ بِكُمُ ٱلْيُسْرَ وَلَا يُرِيدُ بِكُمُ ٱلْعُسْرَ وَلِتُكْمِلُوا۟ ٱلْعِدَّةَ وَلِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمْ وَلَعَلَّكُمْ تَشْكُرُونَ','Shahru Ramadaanallazeee unzila feehil Qur\'aanu hudal linnaasi wa baiyinaatim minal hudaa wal furqaan; faman shahida minkumush shahra falyasumhu wa man kaana mareedan aw \'alaa safarin fa\'iddatum min ayyaamin ukhar; yureedul laahu bikumul yusra wa laa yureedu bikumul \'usra wa litukmilul \'iddata wa litukabbirul laaha \'alaa maa hadaakum wa la\'allakum tashkuroon',185,'2:185',3,11,24,1,0,28,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(193,2,'وَإِذَا سَأَلَكَ عِبَادِى عَنِّى فَإِنِّى قَرِيبٌ ۖ أُجِيبُ دَعْوَةَ ٱلدَّاعِ إِذَا دَعَانِ ۖ فَلْيَسْتَجِيبُوا۟ لِى وَلْيُؤْمِنُوا۟ بِى لَعَلَّهُمْ يَرْشُدُونَ','Wa izaa sa alaka \'ibaadee \'annnee fa innee qareebun ujeebu da\'wataddaa\'i izaa da\'aani falyastajeeboo lee walyu minoo beela \'allahum yarshudoon',186,'2:186',3,11,24,1,0,28,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(194,2,'أُحِلَّ لَكُمْ لَيْلَةَ ٱلصِّيَامِ ٱلرَّفَثُ إِلَىٰ نِسَآئِكُمْ ۚ هُنَّ لِبَاسٌ لَّكُمْ وَأَنتُمْ لِبَاسٌ لَّهُنَّ ۗ عَلِمَ ٱللَّهُ أَنَّكُمْ كُنتُمْ تَخْتَانُونَ أَنفُسَكُمْ فَتَابَ عَلَيْكُمْ وَعَفَا عَنكُمْ ۖ فَٱلْـَٔـٰنَ بَـٰشِرُوهُنَّ وَٱبْتَغُوا۟ مَا كَتَبَ ٱللَّهُ لَكُمْ ۚ وَكُلُوا۟ وَٱشْرَبُوا۟ حَتَّىٰ يَتَبَيَّنَ لَكُمُ ٱلْخَيْطُ ٱلْأَبْيَضُ مِنَ ٱلْخَيْطِ ٱلْأَسْوَدِ مِنَ ٱلْفَجْرِ ۖ ثُمَّ أَتِمُّوا۟ ٱلصِّيَامَ إِلَى ٱلَّيْلِ ۚ وَلَا تُبَـٰشِرُوهُنَّ وَأَنتُمْ عَـٰكِفُونَ فِى ٱلْمَسَـٰجِدِ ۗ تِلْكَ حُدُودُ ٱللَّهِ فَلَا تَقْرَبُوهَا ۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ ءَايَـٰتِهِۦ لِلنَّاسِ لَعَلَّهُمْ يَتَّقُونَ','Uhilla lakum laylatas Siyaamir rafasu ilaa nisaaa\'ikum; hunna libaasullakum wa antum libaasullahunn; \'alimal laahu annakum kuntum takhtaanoona anfusakum fataaba \'alaikum wa \'afaa \'ankum fal\'aana baashiroo hunna wabtaghoo maa katabal laahoo lakum; wa kuloo washraboo hattaa yatabaiyana lakumul khaitul abyadu minal khaitil aswadi minal fajri summa atimmus Siyaama ilal layl; wa laa tubaashiroo hunna wa antum \'aakifoona fil masaajid; tilka hudoodul laahi falaa taqraboohaa; kazaalika yubaiyinul laahu aayaatihee linnaasi la\'allahum yattaqoon',187,'2:187',3,11,24,1,0,29,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(195,2,'وَلَا تَأْكُلُوٓا۟ أَمْوَٰلَكُم بَيْنَكُم بِٱلْبَـٰطِلِ وَتُدْلُوا۟ بِهَآ إِلَى ٱلْحُكَّامِ لِتَأْكُلُوا۟ فَرِيقًا مِّنْ أَمْوَٰلِ ٱلنَّاسِ بِٱلْإِثْمِ وَأَنتُمْ تَعْلَمُونَ','Wa laa taakuloo amwaalakum bainakum bilbaatili wa tudloo bihaaa ilal hukkaami litaakuloo fareeqam min amwaalin naasi bil ismi wa antum ta\'lamoon',188,'2:188',3,11,24,1,0,29,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(196,2,'۞ يَسْـَٔلُونَكَ عَنِ ٱلْأَهِلَّةِ ۖ قُلْ هِىَ مَوَٰقِيتُ لِلنَّاسِ وَٱلْحَجِّ ۗ وَلَيْسَ ٱلْبِرُّ بِأَن تَأْتُوا۟ ٱلْبُيُوتَ مِن ظُهُورِهَا وَلَـٰكِنَّ ٱلْبِرَّ مَنِ ٱتَّقَىٰ ۗ وَأْتُوا۟ ٱلْبُيُوتَ مِنْ أَبْوَٰبِهَا ۚ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ','Yas\'aloonaka \'anil ahillati qul hiya mawaaqeetu linnaasi wal Hajj; wa laisal birru bi an taatul buyoota min zuhoorihaa wa laakinnal birra manit taqaa; waatul buyoota min abwaa bihaa; wattaqullaaha la\'allakum tuflihoon',189,'2:189',3,12,25,1,0,29,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(197,2,'وَقَـٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ ٱلَّذِينَ يُقَـٰتِلُونَكُمْ وَلَا تَعْتَدُوٓا۟ ۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُعْتَدِينَ','Wa qaatiloo fee sabeelillaahil lazeena yuqaatiloonakum wa laa ta\'tadooo; innal laaha laa yuhibbul mu\'tadeen',190,'2:190',3,12,25,1,0,29,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(198,2,'وَٱقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ وَأَخْرِجُوهُم مِّنْ حَيْثُ أَخْرَجُوكُمْ ۚ وَٱلْفِتْنَةُ أَشَدُّ مِنَ ٱلْقَتْلِ ۚ وَلَا تُقَـٰتِلُوهُمْ عِندَ ٱلْمَسْجِدِ ٱلْحَرَامِ حَتَّىٰ يُقَـٰتِلُوكُمْ فِيهِ ۖ فَإِن قَـٰتَلُوكُمْ فَٱقْتُلُوهُمْ ۗ كَذَٰلِكَ جَزَآءُ ٱلْكَـٰفِرِينَ','Waqtuloohum haisu saqif tumoohum wa akhrijoohum min haisu akhrajookum; walfitnatu ashaddu minal qatl; wa laa tuqaatiloohum \'indal Majidil Haraami hattaa yaqaatilookum feehi fa in qaatalookum faqtuloohum; kazaalika jazaaa\'ul kaafireen',191,'2:191',3,12,25,1,0,30,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(199,2,'فَإِنِ ٱنتَهَوْا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ','Fa ini-ntahaw fa innal laaha Ghafoorur Raheem',192,'2:192',3,12,25,1,0,30,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(200,2,'وَقَـٰتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌ وَيَكُونَ ٱلدِّينُ لِلَّهِ ۖ فَإِنِ ٱنتَهَوْا۟ فَلَا عُدْوَٰنَ إِلَّا عَلَى ٱلظَّـٰلِمِينَ','Wa qaatiloohum hatta laa takoona fitnatunw wa yakoonad deenu lillaahi fa-inin tahaw falaa \'udwaana illaa \'alaz zaalimeen',193,'2:193',3,12,25,1,0,30,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(201,2,'ٱلشَّهْرُ ٱلْحَرَامُ بِٱلشَّهْرِ ٱلْحَرَامِ وَٱلْحُرُمَـٰتُ قِصَاصٌ ۚ فَمَنِ ٱعْتَدَىٰ عَلَيْكُمْ فَٱعْتَدُوا۟ عَلَيْهِ بِمِثْلِ مَا ٱعْتَدَىٰ عَلَيْكُمْ ۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ','Ash Shahrul Haraamu bish Shahril Haraami wal hurumaatu qisaas; famani\'tadaa \'alaikum fa\'tadoo \'alaihi bimsisli ma\'tadaa \'alaikum; wattaqul laaha wa\'lamooo annal laaha ma\'al muttaqeen',194,'2:194',3,12,25,1,0,30,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(202,2,'وَأَنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ وَلَا تُلْقُوا۟ بِأَيْدِيكُمْ إِلَى ٱلتَّهْلُكَةِ ۛ وَأَحْسِنُوٓا۟ ۛ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُحْسِنِينَ','Wa anfiqoo fee sabeelil laahi wa laa tulqoo bi aydeekum ilat tahlukati wa ahsinoo; innal laaha yuhibbul muhsineen',195,'2:195',3,12,25,1,0,30,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(203,2,'وَأَتِمُّوا۟ ٱلْحَجَّ وَٱلْعُمْرَةَ لِلَّهِ ۚ فَإِنْ أُحْصِرْتُمْ فَمَا ٱسْتَيْسَرَ مِنَ ٱلْهَدْىِ ۖ وَلَا تَحْلِقُوا۟ رُءُوسَكُمْ حَتَّىٰ يَبْلُغَ ٱلْهَدْىُ مَحِلَّهُۥ ۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ بِهِۦٓ أَذًى مِّن رَّأْسِهِۦ فَفِدْيَةٌ مِّن صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ ۚ فَإِذَآ أَمِنتُمْ فَمَن تَمَتَّعَ بِٱلْعُمْرَةِ إِلَى ٱلْحَجِّ فَمَا ٱسْتَيْسَرَ مِنَ ٱلْهَدْىِ ۚ فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَـٰثَةِ أَيَّامٍ فِى ٱلْحَجِّ وَسَبْعَةٍ إِذَا رَجَعْتُمْ ۗ تِلْكَ عَشَرَةٌ كَامِلَةٌ ۗ ذَٰلِكَ لِمَن لَّمْ يَكُنْ أَهْلُهُۥ حَاضِرِى ٱلْمَسْجِدِ ٱلْحَرَامِ ۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ','Wa atimmul Hajja wal Umarata lillaah; fain uhsirtum famas taisara minal hadyi walaa tahliqoo ru\'oosakum hatta yablughal hadyu mahillah; faman kaana minkum mareedan aw biheee azam mir raasihee fafidyatum min Siyaamin aw sadaqatin aw nusuk; fa izaaa amintum faman tamatta\'a bil \'Umrati ilal Hajji famastaisara minal hady; famal lam yajid fa Siyaamu salaasti ayyaamin fil Hajji wa sab\'atin izaa raja\'tum; tilka \'asharatun kaamilah; zaalika limal lam yakun ahluhoo haadiril Masjidil Haraam; wattaqul laaha wa\'lamoo annal laaha shadeedul\'iqaab',196,'2:196',3,12,25,1,0,30,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(204,2,'ٱلْحَجُّ أَشْهُرٌ مَّعْلُومَـٰتٌ ۚ فَمَن فَرَضَ فِيهِنَّ ٱلْحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِى ٱلْحَجِّ ۗ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍ يَعْلَمْهُ ٱللَّهُ ۗ وَتَزَوَّدُوا۟ فَإِنَّ خَيْرَ ٱلزَّادِ ٱلتَّقْوَىٰ ۚ وَٱتَّقُونِ يَـٰٓأُو۟لِى ٱلْأَلْبَـٰبِ','Al-Hajju ashhurum ma\'-loomaat; faman farada feeinnal hajja falaa rafasa wa laa fusooqa wa laa jidaala fil Hajj; wa maa taf\'aloo min khairiny ya\'lamhul laah; wa tazawwadoo fa inna khairaz zaadit taqwaa; wattaqooni yaaa ulil albaab',197,'2:197',3,12,26,1,0,31,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(205,2,'لَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَبْتَغُوا۟ فَضْلًا مِّن رَّبِّكُمْ ۚ فَإِذَآ أَفَضْتُم مِّنْ عَرَفَـٰتٍ فَٱذْكُرُوا۟ ٱللَّهَ عِندَ ٱلْمَشْعَرِ ٱلْحَرَامِ ۖ وَٱذْكُرُوهُ كَمَا هَدَىٰكُمْ وَإِن كُنتُم مِّن قَبْلِهِۦ لَمِنَ ٱلضَّآلِّينَ','Laisa \'alaikum junaahun an tabtaghoo fad lam mir rabbikum; fa izaaa afadtum min \'Arafaatin fazkurul laaha \'indal-Mash\'aril Haraami waz kuroohu kamaa hadaakum wa in kuntum min qablihee laminad daaaleen',198,'2:198',3,12,26,1,0,31,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(206,2,'ثُمَّ أَفِيضُوا۟ مِنْ حَيْثُ أَفَاضَ ٱلنَّاسُ وَٱسْتَغْفِرُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ','Summa afeedoo min haisu afaadan naasu wastagh firullaah; innnal laaha Ghafoo rur-Raheem',199,'2:199',3,12,26,1,0,31,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(207,2,'فَإِذَا قَضَيْتُم مَّنَـٰسِكَكُمْ فَٱذْكُرُوا۟ ٱللَّهَ كَذِكْرِكُمْ ءَابَآءَكُمْ أَوْ أَشَدَّ ذِكْرًا ۗ فَمِنَ ٱلنَّاسِ مَن يَقُولُ رَبَّنَآ ءَاتِنَا فِى ٱلدُّنْيَا وَمَا لَهُۥ فِى ٱلْـَٔاخِرَةِ مِنْ خَلَـٰقٍ','Fa-izan qadaitum manaa sikakum fazkurul laaha kazikrikum aabaaa\'akum aw ashadda zikraa; faminannaasi mai yaqoolu Rabbanaaa aatinaa fiddunyaa wa maa lahoo fil Aakhirati min khalaaq',200,'2:200',3,12,26,1,0,31,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(208,2,'وَمِنْهُم مَّن يَقُولُ رَبَّنَآ ءَاتِنَا فِى ٱلدُّنْيَا حَسَنَةً وَفِى ٱلْـَٔاخِرَةِ حَسَنَةً وَقِنَا عَذَابَ ٱلنَّارِ','Wa minhum mai yaqoolu rabbanaaa aatina fid dunyaa hasanatawn wa fil aakhirati hasanatanw wa qinaa azaaban Naar',201,'2:201',3,12,26,1,0,31,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(209,2,'أُو۟لَـٰٓئِكَ لَهُمْ نَصِيبٌ مِّمَّا كَسَبُوا۟ ۚ وَٱللَّهُ سَرِيعُ ٱلْحِسَابِ','Ulaaa\'ika lahum naseebum mimmaa kasaboo; wal laahu saree\'ul hisaab',202,'2:202',3,12,26,1,0,31,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(210,2,'۞ وَٱذْكُرُوا۟ ٱللَّهَ فِىٓ أَيَّامٍ مَّعْدُودَٰتٍ ۚ فَمَن تَعَجَّلَ فِى يَوْمَيْنِ فَلَآ إِثْمَ عَلَيْهِ وَمَن تَأَخَّرَ فَلَآ إِثْمَ عَلَيْهِ ۚ لِمَنِ ٱتَّقَىٰ ۗ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّكُمْ إِلَيْهِ تُحْشَرُونَ','Wazkurul laaha feee ayyaamim ma\'doodaat; faman ta\'ajjala fee yawmaini falaaa ismaa \'alaihi wa man taakhkhara falaaa isma \'alayh; limanit-taqaa; wattaqul laaha wa\'lamooo annakum ilaihi tuhsharoon',203,'2:203',4,13,26,1,0,32,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(211,2,'وَمِنَ ٱلنَّاسِ مَن يُعْجِبُكَ قَوْلُهُۥ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَيُشْهِدُ ٱللَّهَ عَلَىٰ مَا فِى قَلْبِهِۦ وَهُوَ أَلَدُّ ٱلْخِصَامِ','Wa minan naasi mai yu\'jibuka qawluhoo fil hayaatid dunyaa wa yushhidul laaha \'alaa maa fee qalbihee wa huwa aladdulkhisaam',204,'2:204',4,13,26,1,0,32,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(212,2,'وَإِذَا تَوَلَّىٰ سَعَىٰ فِى ٱلْأَرْضِ لِيُفْسِدَ فِيهَا وَيُهْلِكَ ٱلْحَرْثَ وَٱلنَّسْلَ ۗ وَٱللَّهُ لَا يُحِبُّ ٱلْفَسَادَ','Wa izaa tawallaa sa\'aa fil ardi liyufsida feeha wa yuhlikal harsa wannasl; wallaahu laa yuhibbul fasaad',205,'2:205',4,13,26,1,0,32,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(213,2,'وَإِذَا قِيلَ لَهُ ٱتَّقِ ٱللَّهَ أَخَذَتْهُ ٱلْعِزَّةُ بِٱلْإِثْمِ ۚ فَحَسْبُهُۥ جَهَنَّمُ ۚ وَلَبِئْسَ ٱلْمِهَادُ','Wa izaa qeela lahuttaqil laaha akhazathul izzatu bil-ism; fahasbuhoo jahannam; wa labi\'sal mihaad',206,'2:206',4,13,26,1,0,32,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(214,2,'وَمِنَ ٱلنَّاسِ مَن يَشْرِى نَفْسَهُ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ ۗ وَٱللَّهُ رَءُوفٌۢ بِٱلْعِبَادِ','Wa minan naasi mai yashree nafsahub tighaaa\'a mardaatil laah; wallaahu ra\'oofum bil\'ibaad',207,'2:207',4,13,26,1,0,32,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(215,2,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱدْخُلُوا۟ فِى ٱلسِّلْمِ كَآفَّةً وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَـٰنِ ۚ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ','Yaaa ayyuhal lazeena aamanud khuloo fis silmi kaaaffatanw wa laa tattabi\'oo khutuwaatish Shaitaan; innahoo lakum \'aduwwum mubeen',208,'2:208',4,13,26,1,0,32,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(216,2,'فَإِن زَلَلْتُم مِّنۢ بَعْدِ مَا جَآءَتْكُمُ ٱلْبَيِّنَـٰتُ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ','Fa in zalaltum mimba\'di maa jaaa\'atkumul baiyinaatu fa\'lamoo annallaaha \'Azeezun hakeem',209,'2:209',4,13,26,1,0,32,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(217,2,'هَلْ يَنظُرُونَ إِلَّآ أَن يَأْتِيَهُمُ ٱللَّهُ فِى ظُلَلٍ مِّنَ ٱلْغَمَامِ وَٱلْمَلَـٰٓئِكَةُ وَقُضِىَ ٱلْأَمْرُ ۚ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ','Hal yanzuroona illaaa ai yaatiyahumul laahu fee zulalim minal ghamaami walmalaaa\'ikatu wa qudiyal amr; wa ilal laahi turja\'ulumoor',210,'2:210',4,13,26,1,0,32,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(218,2,'سَلْ بَنِىٓ إِسْرَٰٓءِيلَ كَمْ ءَاتَيْنَـٰهُم مِّنْ ءَايَةٍۭ بَيِّنَةٍ ۗ وَمَن يُبَدِّلْ نِعْمَةَ ٱللَّهِ مِنۢ بَعْدِ مَا جَآءَتْهُ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ','Sal Banee Israaa\'eela kam aatainaahum min aayatim baiyinah; wa mai yubaddil ni\'matal laahi mim ba\'di maa jaaa\'athu fa innallaaha shadeedul\'iqaab',211,'2:211',4,13,27,1,0,33,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(219,2,'زُيِّنَ لِلَّذِينَ كَفَرُوا۟ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَيَسْخَرُونَ مِنَ ٱلَّذِينَ ءَامَنُوا۟ ۘ وَٱلَّذِينَ ٱتَّقَوْا۟ فَوْقَهُمْ يَوْمَ ٱلْقِيَـٰمَةِ ۗ وَٱللَّهُ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍ','Zuyyina lillazeena kafarul hayaatud dunyaa wa yaskharoona minal lazeena aamanoo; wallazeenat taqaw fawqahum yawmal Qiyaamah; wallaahu yarzuqu mai yashaaa\'u bighairi hisaab;',212,'2:212',4,13,27,1,0,33,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(220,2,'كَانَ ٱلنَّاسُ أُمَّةً وَٰحِدَةً فَبَعَثَ ٱللَّهُ ٱلنَّبِيِّـۧنَ مُبَشِّرِينَ وَمُنذِرِينَ وَأَنزَلَ مَعَهُمُ ٱلْكِتَـٰبَ بِٱلْحَقِّ لِيَحْكُمَ بَيْنَ ٱلنَّاسِ فِيمَا ٱخْتَلَفُوا۟ فِيهِ ۚ وَمَا ٱخْتَلَفَ فِيهِ إِلَّا ٱلَّذِينَ أُوتُوهُ مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَـٰتُ بَغْيًۢا بَيْنَهُمْ ۖ فَهَدَى ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ لِمَا ٱخْتَلَفُوا۟ فِيهِ مِنَ ٱلْحَقِّ بِإِذْنِهِۦ ۗ وَٱللَّهُ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ','Kaanan naasu ummatanw waahidatan fab\'asal laahun Nabiyyeena mubashshireena wa munzireena wa anzala ma\'ahumul kitaaba bilhaqqi liyahkuma bainan naasi feemakh talafoo feeh; wa makh talafa feehi \'illallazeena ootoohu mim ba\'di maa jaaa\'athumul baiyinaatu baghyam bainahm fahadal laahul lazeena aamanoo limakh talafoo feehi minal haqqi bi iznih; wallaahu yahdee mai yashaaa\'u ilaa Siraatim Mustaqeem',213,'2:213',4,13,27,1,0,33,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(221,2,'أَمْ حَسِبْتُمْ أَن تَدْخُلُوا۟ ٱلْجَنَّةَ وَلَمَّا يَأْتِكُم مَّثَلُ ٱلَّذِينَ خَلَوْا۟ مِن قَبْلِكُم ۖ مَّسَّتْهُمُ ٱلْبَأْسَآءُ وَٱلضَّرَّآءُ وَزُلْزِلُوا۟ حَتَّىٰ يَقُولَ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ مَتَىٰ نَصْرُ ٱللَّهِ ۗ أَلَآ إِنَّ نَصْرَ ٱللَّهِ قَرِيبٌ','Am hasibtum an tadkhulul jannata wa lammaa yaa-tikum masalul lazeena khalaw min qablikum massathumul baasaaa\'u waddarraaaa\'u wa zulziloo hattaa yaqoolar Rasoolu wallazeena aamanoo ma\'ahoo mataa nasrul laah; alaaa inna nasral laahiqareeb',214,'2:214',4,13,27,1,0,33,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(222,2,'يَسْـَٔلُونَكَ مَاذَا يُنفِقُونَ ۖ قُلْ مَآ أَنفَقْتُم مِّنْ خَيْرٍ فَلِلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ وَٱلْيَتَـٰمَىٰ وَٱلْمَسَـٰكِينِ وَٱبْنِ ٱلسَّبِيلِ ۗ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ','Yas\'aloonaka maazaa yunfiqoona qul maaa anfaqtum min khairin falil waalidaini wal aqrabeena walyataamaa wal masaakeeni wabnis sabeel; wa maa taf\'aloo min khairin fa innal laaha bihee \'Aleem',215,'2:215',4,13,27,1,0,33,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(223,2,'كُتِبَ عَلَيْكُمُ ٱلْقِتَالُ وَهُوَ كُرْهٌ لَّكُمْ ۖ وَعَسَىٰٓ أَن تَكْرَهُوا۟ شَيْـًٔا وَهُوَ خَيْرٌ لَّكُمْ ۖ وَعَسَىٰٓ أَن تُحِبُّوا۟ شَيْـًٔا وَهُوَ شَرٌّ لَّكُمْ ۗ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ','Kutiba alaikumulqitaalu wa huwa kurhullakum wa \'asaaa an takrahoo shai\'anw wa huwa khairullakum wa \'asaaa an tuhibbo shai\'anw wa huwa sharrullakum; wallaahu ya\'lamu wa antum laa ta\'lamoon',216,'2:216',4,13,27,1,0,34,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(224,2,'يَسْـَٔلُونَكَ عَنِ ٱلشَّهْرِ ٱلْحَرَامِ قِتَالٍ فِيهِ ۖ قُلْ قِتَالٌ فِيهِ كَبِيرٌ ۖ وَصَدٌّ عَن سَبِيلِ ٱللَّهِ وَكُفْرٌۢ بِهِۦ وَٱلْمَسْجِدِ ٱلْحَرَامِ وَإِخْرَاجُ أَهْلِهِۦ مِنْهُ أَكْبَرُ عِندَ ٱللَّهِ ۚ وَٱلْفِتْنَةُ أَكْبَرُ مِنَ ٱلْقَتْلِ ۗ وَلَا يَزَالُونَ يُقَـٰتِلُونَكُمْ حَتَّىٰ يَرُدُّوكُمْ عَن دِينِكُمْ إِنِ ٱسْتَطَـٰعُوا۟ ۚ وَمَن يَرْتَدِدْ مِنكُمْ عَن دِينِهِۦ فَيَمُتْ وَهُوَ كَافِرٌ فَأُو۟لَـٰٓئِكَ حَبِطَتْ أَعْمَـٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ ۖ وَأُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ','Yas\'aloonaka \'anish Shahril Haraami qitaalin feehi qul qitaahun feehi kabeerunw wa saddun \'an sabeelil laahi wa kufrum bihee wal Masjidil Haraami wa ikhraaju ahlihee minhu akbaru \'indal laah; walfitnatu akbaru minal qatl; wa laa yazaaloona yuqaatiloonakum hatta yaruddookum \'an deenikum inis tataa\'oo; wa mai yartadid minkum \'an deenihee fayamut wahuwa kaafirun fa ulaaa\'ika habitat a\'maaluhum fid dunyaa wal aakhirati wa ulaaa\'ika ashaabun Naari hum feehaa khaalidoon',217,'2:217',4,13,28,1,0,34,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(225,2,'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَاجَرُوا۟ وَجَـٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ أُو۟لَـٰٓئِكَ يَرْجُونَ رَحْمَتَ ٱللَّهِ ۚ وَٱللَّهُ غَفُورٌ رَّحِيمٌ','Innal lazeena aamanoo wallazeena haajaroo wa jaahadoo fee sabeelil laahi ulaaaika yarjoona rahmatal laah; wallaahu Ghafoorur Raheem',218,'2:218',4,13,28,1,0,34,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(226,2,'۞ يَسْـَٔلُونَكَ عَنِ ٱلْخَمْرِ وَٱلْمَيْسِرِ ۖ قُلْ فِيهِمَآ إِثْمٌ كَبِيرٌ وَمَنَـٰفِعُ لِلنَّاسِ وَإِثْمُهُمَآ أَكْبَرُ مِن نَّفْعِهِمَا ۗ وَيَسْـَٔلُونَكَ مَاذَا يُنفِقُونَ قُلِ ٱلْعَفْوَ ۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْـَٔايَـٰتِ لَعَلَّكُمْ تَتَفَكَّرُونَ','Yas\'aloonaka \'anilkhamri walmaisiri qul feehimaaa ismun kabeerunw wa manaafi\'u linnaasi wa ismuhumaa akbaru min naf\'ihimaa; wa yas\'aloonaka maaza yunfiqoona qulil-\'afw; kazaalika yubaiyinul laahu lakumul-aayaati la\'allakum tatafakkaroon',219,'2:219',4,14,28,1,0,34,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(227,2,'فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ ۗ وَيَسْـَٔلُونَكَ عَنِ ٱلْيَتَـٰمَىٰ ۖ قُلْ إِصْلَاحٌ لَّهُمْ خَيْرٌ ۖ وَإِن تُخَالِطُوهُمْ فَإِخْوَٰنُكُمْ ۚ وَٱللَّهُ يَعْلَمُ ٱلْمُفْسِدَ مِنَ ٱلْمُصْلِحِ ۚ وَلَوْ شَآءَ ٱللَّهُ لَأَعْنَتَكُمْ ۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ','Fid dunyaa wal aakhirah; wa yas\'aloonaka \'anil yataamaa qul islaahullahum khayr, wa in tukhaalitoohum fa ikhwaanukum; wallaahu ya\'lamul mufsida minalmuslih; wa law shaaa\'al laahu la-a\'natakum; innal laaha \'Azeezun Hakeem',220,'2:220',4,14,28,1,0,35,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(228,2,'وَلَا تَنكِحُوا۟ ٱلْمُشْرِكَـٰتِ حَتَّىٰ يُؤْمِنَّ ۚ وَلَأَمَةٌ مُّؤْمِنَةٌ خَيْرٌ مِّن مُّشْرِكَةٍ وَلَوْ أَعْجَبَتْكُمْ ۗ وَلَا تُنكِحُوا۟ ٱلْمُشْرِكِينَ حَتَّىٰ يُؤْمِنُوا۟ ۚ وَلَعَبْدٌ مُّؤْمِنٌ خَيْرٌ مِّن مُّشْرِكٍ وَلَوْ أَعْجَبَكُمْ ۗ أُو۟لَـٰٓئِكَ يَدْعُونَ إِلَى ٱلنَّارِ ۖ وَٱللَّهُ يَدْعُوٓا۟ إِلَى ٱلْجَنَّةِ وَٱلْمَغْفِرَةِ بِإِذْنِهِۦ ۖ وَيُبَيِّنُ ءَايَـٰتِهِۦ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ','Wa laatankihul mushrikaati hattaa yu\'minn; wa la amatum mu\'minatun khairum mim mushrikatinw wa law a\'jabatkum; wa laa tunkihul mushrikeena hattaa yu\'minoo; wa la\'abdummu\'minun khairum mimmushrikinw wa law \'ajabakum; ulaaa\'ika yad\'oona ilan Naari wallaahu yad\'ooo ilal Jannati walmaghfirati biiznihee wa yubaiyinu Aayaatihee linnaasi la\'allahum yatazakkaroon',221,'2:221',4,14,28,1,0,35,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(229,2,'وَيَسْـَٔلُونَكَ عَنِ ٱلْمَحِيضِ ۖ قُلْ هُوَ أَذًى فَٱعْتَزِلُوا۟ ٱلنِّسَآءَ فِى ٱلْمَحِيضِ ۖ وَلَا تَقْرَبُوهُنَّ حَتَّىٰ يَطْهُرْنَ ۖ فَإِذَا تَطَهَّرْنَ فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ ٱللَّهُ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ وَيُحِبُّ ٱلْمُتَطَهِّرِينَ','Wa yas\'aloonaka \'anil maheedi qul huwa azan fa\'tazilun nisaaa\'a fil maheedi wa laa taqraboo hunna hattaa yathurna fa-izaa tathharna faatoohunna min haisu amarakumul laah; innallaaha yuhibbut Tawwaabeena wa yuhibbul mutatahhireen',222,'2:222',4,14,29,1,0,35,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(230,2,'نِسَآؤُكُمْ حَرْثٌ لَّكُمْ فَأْتُوا۟ حَرْثَكُمْ أَنَّىٰ شِئْتُمْ ۖ وَقَدِّمُوا۟ لِأَنفُسِكُمْ ۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّكُم مُّلَـٰقُوهُ ۗ وَبَشِّرِ ٱلْمُؤْمِنِينَ','Nisaaa\'ukum harsullakum faatoo harsakum annaa shi\'tum wa qaddimoo li anfusikum; wattaqul laaha wa\'lamooo annakum mulaaqooh; wa bash shirilmu \'mineen',223,'2:223',4,14,29,1,0,35,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(231,2,'وَلَا تَجْعَلُوا۟ ٱللَّهَ عُرْضَةً لِّأَيْمَـٰنِكُمْ أَن تَبَرُّوا۟ وَتَتَّقُوا۟ وَتُصْلِحُوا۟ بَيْنَ ٱلنَّاسِ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ','Wa laa taj\'alul laaha \'urdatal li aymaanikum an tabarroo wa tattaqoo wa tuslihoo bainan naas; wallaahu Samee\'un \'Aleem',224,'2:224',4,14,29,1,0,35,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(232,2,'لَّا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغْوِ فِىٓ أَيْمَـٰنِكُمْ وَلَـٰكِن يُؤَاخِذُكُم بِمَا كَسَبَتْ قُلُوبُكُمْ ۗ وَٱللَّهُ غَفُورٌ حَلِيمٌ','Laa yu\'aakhi zukumul laahu billaghwi feee aymaa nikum wa laakiny yu\'aakhi zukum bimaa kasabat quloo bukum; wallaahu Ghafoorun Haleem',225,'2:225',4,14,29,1,0,36,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(233,2,'لِّلَّذِينَ يُؤْلُونَ مِن نِّسَآئِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍ ۖ فَإِن فَآءُو فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ','Lillazeena yu\'loona min nisaaa\'ihim tarabbusu arba\'ati ashhurin fain faaa\'oo fa innal laaha Ghafoorur Raheem',226,'2:226',4,14,29,1,0,36,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(234,2,'وَإِنْ عَزَمُوا۟ ٱلطَّلَـٰقَ فَإِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ','Wa in \'azamut talaaqa fa innal laaha Samee\'un \'Aleem',227,'2:227',4,14,29,1,0,36,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(235,2,'وَٱلْمُطَلَّقَـٰتُ يَتَرَبَّصْنَ بِأَنفُسِهِنَّ ثَلَـٰثَةَ قُرُوٓءٍ ۚ وَلَا يَحِلُّ لَهُنَّ أَن يَكْتُمْنَ مَا خَلَقَ ٱللَّهُ فِىٓ أَرْحَامِهِنَّ إِن كُنَّ يُؤْمِنَّ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ ۚ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِى ذَٰلِكَ إِنْ أَرَادُوٓا۟ إِصْلَـٰحًا ۚ وَلَهُنَّ مِثْلُ ٱلَّذِى عَلَيْهِنَّ بِٱلْمَعْرُوفِ ۚ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ ۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ','Walmutallaqaatu yatarab basna bi anfusihinna salaasata qurooo\'; wa laa yahillu lahunna ai yaktumna maa khalaqal laahu feee arhaaminhinna in kunna yu\'minna billaahi wal yawmil aakhir; wa bu\'oola tuhunna ahaqqu biraddihinna fee zaalika in araadooo islaahaa; wa lahunna mislul lazee \'araihinna bilma\'roof; wa lirrijjaali \'alaihinna daraja; wallaahu \'Azeezun Hakeem',228,'2:228',4,14,29,1,0,36,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(236,2,'ٱلطَّلَـٰقُ مَرَّتَانِ ۖ فَإِمْسَاكٌۢ بِمَعْرُوفٍ أَوْ تَسْرِيحٌۢ بِإِحْسَـٰنٍ ۗ وَلَا يَحِلُّ لَكُمْ أَن تَأْخُذُوا۟ مِمَّآ ءَاتَيْتُمُوهُنَّ شَيْـًٔا إِلَّآ أَن يَخَافَآ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ ۖ فَإِنْ خِفْتُمْ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ فَلَا جُنَاحَ عَلَيْهِمَا فِيمَا ٱفْتَدَتْ بِهِۦ ۗ تِلْكَ حُدُودُ ٱللَّهِ فَلَا تَعْتَدُوهَا ۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَأُو۟لَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ','Attalaaqu marrataani fa imsaakum bima\'roofin aw tasreehum bi ihsaan; wa laa yahillu lakum an taakhuzoo mimmaaa aataitumoohunna shai\'an illaaa ai yakhaafaaa alla yuqeemaa hudoodallahi fa in khiftum allaa yuqeemaa budoodal laahi falaa junaaha \'Alaihimaa feemaf tadat bihee tilka hudoodul laahi falaa ta\'tadoohaa; wa mai yata\'adda hudoodal laahi fa ulaaa\'ika humuzzaa limoon',229,'2:229',4,14,30,1,0,36,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(237,2,'فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُۥ مِنۢ بَعْدُ حَتَّىٰ تَنكِحَ زَوْجًا غَيْرَهُۥ ۗ فَإِن طَلَّقَهَا فَلَا جُنَاحَ عَلَيْهِمَآ أَن يَتَرَاجَعَآ إِن ظَنَّآ أَن يُقِيمَا حُدُودَ ٱللَّهِ ۗ وَتِلْكَ حُدُودُ ٱللَّهِ يُبَيِّنُهَا لِقَوْمٍ يَعْلَمُونَ','Fa in tallaqahaa falaa tahillu lahoo mim ba\'du hattaa tankiha zawjan ghairah; fa in tallaqahaa falaa junaaha \'alaihimaaa ai yataraaja\'aaa in zannaaa ai yuqeemaa hudoodal laa; wa tilka hudoodul laahi yubaiyinuhaa liqawminy ya\'lamoon',230,'2:230',4,14,30,1,0,36,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(238,2,'وَإِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَبَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ سَرِّحُوهُنَّ بِمَعْرُوفٍ ۚ وَلَا تُمْسِكُوهُنَّ ضِرَارًا لِّتَعْتَدُوا۟ ۚ وَمَن يَفْعَلْ ذَٰلِكَ فَقَدْ ظَلَمَ نَفْسَهُۥ ۚ وَلَا تَتَّخِذُوٓا۟ ءَايَـٰتِ ٱللَّهِ هُزُوًا ۚ وَٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ وَمَآ أَنزَلَ عَلَيْكُم مِّنَ ٱلْكِتَـٰبِ وَٱلْحِكْمَةِ يَعِظُكُم بِهِۦ ۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ','Wa izaa tallaqtumun nisaaa\'a fabalaghna ajala hunna fa amsikoohunna bima\'roofin law sarrihoo hunna bima\'roof; wa laa tumsikoo hunna diraa rallita\'tadoo; wa mai yaf\'al zaalika faqad zalama nafsah; wa laa tattakhizooo aayaatillaahi huzuwaa; wazkuroo ni\'matal laahi \'alaikum wa maaa anzala \'alaikum minal kitaabi wal ikmati ya\'izukum bih; wattaqul laaha wa\'lamooo annal laaha bikulli shai\'i \'Aleem',231,'2:231',4,14,30,1,0,37,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(239,2,'وَإِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَبَلَغْنَ أَجَلَهُنَّ فَلَا تَعْضُلُوهُنَّ أَن يَنكِحْنَ أَزْوَٰجَهُنَّ إِذَا تَرَٰضَوْا۟ بَيْنَهُم بِٱلْمَعْرُوفِ ۗ ذَٰلِكَ يُوعَظُ بِهِۦ مَن كَانَ مِنكُمْ يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ ۗ ذَٰلِكُمْ أَزْكَىٰ لَكُمْ وَأَطْهَرُ ۗ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ','Wa izaa tallaqtumun nisaaa\'a fabalaghna ajalahunna falaa ta\'duloo hunna ai yankihna azwaaja humna izaa taraadaw bainahum bilma\' roof; zaalika yoo\'azu bihee man kaana minkum yu\'minu billaahi wal yawmil aakhir; zaalikum azkaa lakum wa athar; wallaahu ya\'lamu wa antum laa ta\'lamu wa antum laa ta\'lamoon',232,'2:232',4,14,31,1,0,37,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(240,2,'۞ وَٱلْوَٰلِدَٰتُ يُرْضِعْنَ أَوْلَـٰدَهُنَّ حَوْلَيْنِ كَامِلَيْنِ ۖ لِمَنْ أَرَادَ أَن يُتِمَّ ٱلرَّضَاعَةَ ۚ وَعَلَى ٱلْمَوْلُودِ لَهُۥ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِٱلْمَعْرُوفِ ۚ لَا تُكَلَّفُ نَفْسٌ إِلَّا وُسْعَهَا ۚ لَا تُضَآرَّ وَٰلِدَةٌۢ بِوَلَدِهَا وَلَا مَوْلُودٌ لَّهُۥ بِوَلَدِهِۦ ۚ وَعَلَى ٱلْوَارِثِ مِثْلُ ذَٰلِكَ ۗ فَإِنْ أَرَادَا فِصَالًا عَن تَرَاضٍ مِّنْهُمَا وَتَشَاوُرٍ فَلَا جُنَاحَ عَلَيْهِمَا ۗ وَإِنْ أَرَدتُّمْ أَن تَسْتَرْضِعُوٓا۟ أَوْلَـٰدَكُمْ فَلَا جُنَاحَ عَلَيْكُمْ إِذَا سَلَّمْتُم مَّآ ءَاتَيْتُم بِٱلْمَعْرُوفِ ۗ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ','Walwaa lidaatu yurdi\'na awlaada hunna hawlaini kaamilaini liman araada ai yutimmar radaa\'ah; wa \'alalmawloodi lahoo rizuhunna wa kiswatuhunna bilma\'roof; laatukallafu nafsun illaa wus\'ahaa; laa tudaaarra waalidatum biwaladihaa wa laa mawloodul lahoo biwaladih; wa \'alal waarisi mislu zaalik; fa in araadaa Fisaalan \'an taraadim minhumaa wa tashaawurin falaa junaaha \'alaimaa; wa in arattum an tastardi\'ooo awlaadakum falaa junaaha \'alaikum izaa sallamtum maaa aataitum bilma\'roof; wattaqul laaha wa\'lamooo annal laaha bimaa ta\'maloona baseer',233,'2:233',4,15,31,1,0,37,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(241,2,'وَٱلَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَٰجًا يَتَرَبَّصْنَ بِأَنفُسِهِنَّ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا ۖ فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِىٓ أَنفُسِهِنَّ بِٱلْمَعْرُوفِ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ','Wallazeena yutawaffawna minkum wa yazaroona azwaajai yatarabbasna bi anfusihinna arba\'ata ashhurinw wa \'ashran fa izaa balaghna ajalahunna falaa junaaha \'alaikum feemaa fa\'alna feee anfusihinna bilma\'roof; wallaahu bimaa ta\'maloona Khabeer',234,'2:234',4,15,31,1,0,38,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(242,2,'وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا عَرَّضْتُم بِهِۦ مِنْ خِطْبَةِ ٱلنِّسَآءِ أَوْ أَكْنَنتُمْ فِىٓ أَنفُسِكُمْ ۚ عَلِمَ ٱللَّهُ أَنَّكُمْ سَتَذْكُرُونَهُنَّ وَلَـٰكِن لَّا تُوَاعِدُوهُنَّ سِرًّا إِلَّآ أَن تَقُولُوا۟ قَوْلًا مَّعْرُوفًا ۚ وَلَا تَعْزِمُوا۟ عُقْدَةَ ٱلنِّكَاحِ حَتَّىٰ يَبْلُغَ ٱلْكِتَـٰبُ أَجَلَهُۥ ۚ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِىٓ أَنفُسِكُمْ فَٱحْذَرُوهُ ۚ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَفُورٌ حَلِيمٌ','Wa laa junaaha \'alaikum feema \'arradtum bihee min khitbatin nisaaa\'i aw aknantum feee anfusikum; \'alimal laahu annakum satazkuroonahunna wa laakil laa tuwaa\'idoohunna sirran illaaa an taqooloo qawlamma\'roofaa; wa laa ta\'zimoo \'uqdatan nikaahi hattaa yablughal kitaabu ajalah; wa\'lamooo annal laaha ya\'lamumaa feee anfusikum fahzarooh; wa\'lamooo annallaaha Ghafoorun Haleem',235,'2:235',4,15,31,1,0,38,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(243,2,'لَّا جُنَاحَ عَلَيْكُمْ إِن طَلَّقْتُمُ ٱلنِّسَآءَ مَا لَمْ تَمَسُّوهُنَّ أَوْ تَفْرِضُوا۟ لَهُنَّ فَرِيضَةً ۚ وَمَتِّعُوهُنَّ عَلَى ٱلْمُوسِعِ قَدَرُهُۥ وَعَلَى ٱلْمُقْتِرِ قَدَرُهُۥ مَتَـٰعًۢا بِٱلْمَعْرُوفِ ۖ حَقًّا عَلَى ٱلْمُحْسِنِينَ','Laa junaaha \'alaikum in tallaqtumun nisaaa\'a maa lam tamassoohunna aw tafridoo lahunna fareedah; wa matti\'oona \'alal moosi\'i qadaruhoo wa \'alal muqtiri qadaruhoo matta\'am bilma\'roofi haqqan \'alalmuhsineen',236,'2:236',4,15,32,1,0,38,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(244,2,'وَإِن طَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ وَقَدْ فَرَضْتُمْ لَهُنَّ فَرِيضَةً فَنِصْفُ مَا فَرَضْتُمْ إِلَّآ أَن يَعْفُونَ أَوْ يَعْفُوَا۟ ٱلَّذِى بِيَدِهِۦ عُقْدَةُ ٱلنِّكَاحِ ۚ وَأَن تَعْفُوٓا۟ أَقْرَبُ لِلتَّقْوَىٰ ۚ وَلَا تَنسَوُا۟ ٱلْفَضْلَ بَيْنَكُمْ ۚ إِنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ','Wa in tallaqtumoohunna min qabli an tamassoohunna wa qad farad tum lahunna fareedatan fanisfu maa faradtum illaaa ai ya\'foona aw ya\'fuwallazee biyadihee \'uqdatunnikaah; wa an ta\'foona aw ya\'fuwallazee biyadihee \'uqdatunnikaah; wa an ta\'fooo aqrabu littaqwaa; wa laa tansawulfadla bainakum; innal laaha bimaa ta\'maloona Baseer',237,'2:237',4,15,32,1,0,38,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(245,2,'حَـٰفِظُوا۟ عَلَى ٱلصَّلَوَٰتِ وَٱلصَّلَوٰةِ ٱلْوُسْطَىٰ وَقُومُوا۟ لِلَّهِ قَـٰنِتِينَ','Haafizoo \'alas salawaati was Salaatil Wustaa wa qoomoo lillaahi qaaniteen',238,'2:238',4,15,32,1,0,39,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(246,2,'فَإِنْ خِفْتُمْ فَرِجَالًا أَوْ رُكْبَانًا ۖ فَإِذَآ أَمِنتُمْ فَٱذْكُرُوا۟ ٱللَّهَ كَمَا عَلَّمَكُم مَّا لَمْ تَكُونُوا۟ تَعْلَمُونَ','Fa in khiftum farijaalan aw rukbaanan fa izaaa amintum fazkurul laaha kamaa \'allamakum maa lam takoonoo ta\'lamoon',239,'2:239',4,15,32,1,0,39,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(247,2,'وَٱلَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَٰجًا وَصِيَّةً لِّأَزْوَٰجِهِم مَّتَـٰعًا إِلَى ٱلْحَوْلِ غَيْرَ إِخْرَاجٍ ۚ فَإِنْ خَرَجْنَ فَلَا جُنَاحَ عَلَيْكُمْ فِى مَا فَعَلْنَ فِىٓ أَنفُسِهِنَّ مِن مَّعْرُوفٍ ۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ','Wallazeena yutawaf fawna minkum wa yazaroona azwaajanw wasiyyatal li azwaajihim mataa\'an ilal hawlighaira ikhraaj; fa in kharajna falaa junaaha \'alaikum fee maa fa\'alna junaaha \'alaikum fee maa fa\'alna feee anfusihinna mim ma\'roof; wallaahu Azeezun Hakeem',240,'2:240',4,15,32,1,0,39,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(248,2,'وَلِلْمُطَلَّقَـٰتِ مَتَـٰعٌۢ بِٱلْمَعْرُوفِ ۖ حَقًّا عَلَى ٱلْمُتَّقِينَ','Wa lilmutallaqaati mataa\'um bilma\'roofi haqqan \'alal muttaqeen',241,'2:241',4,15,32,1,0,39,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(249,2,'كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَـٰتِهِۦ لَعَلَّكُمْ تَعْقِلُونَ','Kazaalika yubaiyinul laahu lakum aayaatihee la\'allakum ta\'qiloon',242,'2:242',4,15,32,1,0,39,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(250,2,'۞ أَلَمْ تَرَ إِلَى ٱلَّذِينَ خَرَجُوا۟ مِن دِيَـٰرِهِمْ وَهُمْ أُلُوفٌ حَذَرَ ٱلْمَوْتِ فَقَالَ لَهُمُ ٱللَّهُ مُوتُوا۟ ثُمَّ أَحْيَـٰهُمْ ۚ إِنَّ ٱللَّهَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَشْكُرُونَ','Alam tara ilal lazeena kharajoo min diyaarihim wa hum uloofun hazaral mawti faqaaala lahumul laahu mootoo summa ahyaahum; innal laaha lazoo fadlin \'alannaasi wa laakinna aksarannaasi laa yashkuroon',243,'2:243',4,16,33,1,0,39,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(251,2,'وَقَـٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ','Wa qaatiloo fee sabeelil laahi wa\'lamooo annal laaha Samee\'un \'Aleem',244,'2:244',4,16,33,1,0,39,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(252,2,'مَّن ذَا ٱلَّذِى يُقْرِضُ ٱللَّهَ قَرْضًا حَسَنًا فَيُضَـٰعِفَهُۥ لَهُۥٓ أَضْعَافًا كَثِيرَةً ۚ وَٱللَّهُ يَقْبِضُ وَيَبْصُۜطُ وَإِلَيْهِ تُرْجَعُونَ','Man zal lazee yuqridul laaha qardan hasanan fayudaa \'ifahoo lahoo ad\'aafan kaseerah; wallaahu yaqbidu wa yabsut-u wa ilaihi turja\'oon',245,'2:245',4,16,33,1,0,39,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(253,2,'أَلَمْ تَرَ إِلَى ٱلْمَلَإِ مِنۢ بَنِىٓ إِسْرَٰٓءِيلَ مِنۢ بَعْدِ مُوسَىٰٓ إِذْ قَالُوا۟ لِنَبِىٍّ لَّهُمُ ٱبْعَثْ لَنَا مَلِكًا نُّقَـٰتِلْ فِى سَبِيلِ ٱللَّهِ ۖ قَالَ هَلْ عَسَيْتُمْ إِن كُتِبَ عَلَيْكُمُ ٱلْقِتَالُ أَلَّا تُقَـٰتِلُوا۟ ۖ قَالُوا۟ وَمَا لَنَآ أَلَّا نُقَـٰتِلَ فِى سَبِيلِ ٱللَّهِ وَقَدْ أُخْرِجْنَا مِن دِيَـٰرِنَا وَأَبْنَآئِنَا ۖ فَلَمَّا كُتِبَ عَلَيْهِمُ ٱلْقِتَالُ تَوَلَّوْا۟ إِلَّا قَلِيلًا مِّنْهُمْ ۗ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّـٰلِمِينَ','Alam tara ilal malai mim Baneee Israaa\'eela mim ba\'di Moosaaa iz qaaloo li Nabiyyil lahumub \'as lanaa malikan nuqaatil fee sabeelillaahi qaala hal \'asaitum in kutiba \'alaikumul qitaalu allaa tuqaatiloo qaaloo wa maa lanaaa allaa nuqaatila fee sabeelil laahi wa qad ukhrijnaa min diyaarinaa wa abnaaa\'inaa falammaa kutiba \'alaihimul qitaalu tawallaw illaa qaleelam minhum; wallaahu \'aleemum bizzaalimeen',246,'2:246',4,16,33,1,0,40,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(254,2,'وَقَالَ لَهُمْ نَبِيُّهُمْ إِنَّ ٱللَّهَ قَدْ بَعَثَ لَكُمْ طَالُوتَ مَلِكًا ۚ قَالُوٓا۟ أَنَّىٰ يَكُونُ لَهُ ٱلْمُلْكُ عَلَيْنَا وَنَحْنُ أَحَقُّ بِٱلْمُلْكِ مِنْهُ وَلَمْ يُؤْتَ سَعَةً مِّنَ ٱلْمَالِ ۚ قَالَ إِنَّ ٱللَّهَ ٱصْطَفَىٰهُ عَلَيْكُمْ وَزَادَهُۥ بَسْطَةً فِى ٱلْعِلْمِ وَٱلْجِسْمِ ۖ وَٱللَّهُ يُؤْتِى مُلْكَهُۥ مَن يَشَآءُ ۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ','Wa qaala lahum Nabiy yuhum innal laaha qad ba\'asa lakum Taaloota malikaa; qaalooo annaa yakoonu lahul mulku \'alainaa wa nahnu ahaqqu bilmulki minhu wa lam yu\'ta sa\'atamminal maal; qaala innallaahas tafaahu \'alaikum wa zaadahoo bastatan fil\'ilmi waljismi wallaahu yu\'tee mulkahoo mai yashaaa\'; wallaahu Waasi\'un \'Aleem',247,'2:247',4,16,33,1,0,40,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(255,2,'وَقَالَ لَهُمْ نَبِيُّهُمْ إِنَّ ءَايَةَ مُلْكِهِۦٓ أَن يَأْتِيَكُمُ ٱلتَّابُوتُ فِيهِ سَكِينَةٌ مِّن رَّبِّكُمْ وَبَقِيَّةٌ مِّمَّا تَرَكَ ءَالُ مُوسَىٰ وَءَالُ هَـٰرُونَ تَحْمِلُهُ ٱلْمَلَـٰٓئِكَةُ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ','Wa qaala lahum Nabiyyuhum inna Aayata mulkiheee ai yaatiyakumut Taabootu feei sakeenatummir Rabbikum wa baqiyyatummimmaa taraka Aalu Moosa wa Aalu Haaroona tahmiluhul malaaa\'ikah; inna fee zaalika la Aayatal lakum in kuntum mu\'mineen',248,'2:248',4,16,33,1,0,40,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(256,2,'فَلَمَّا فَصَلَ طَالُوتُ بِٱلْجُنُودِ قَالَ إِنَّ ٱللَّهَ مُبْتَلِيكُم بِنَهَرٍ فَمَن شَرِبَ مِنْهُ فَلَيْسَ مِنِّى وَمَن لَّمْ يَطْعَمْهُ فَإِنَّهُۥ مِنِّىٓ إِلَّا مَنِ ٱغْتَرَفَ غُرْفَةًۢ بِيَدِهِۦ ۚ فَشَرِبُوا۟ مِنْهُ إِلَّا قَلِيلًا مِّنْهُمْ ۚ فَلَمَّا جَاوَزَهُۥ هُوَ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ قَالُوا۟ لَا طَاقَةَ لَنَا ٱلْيَوْمَ بِجَالُوتَ وَجُنُودِهِۦ ۚ قَالَ ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَـٰقُوا۟ ٱللَّهِ كَم مِّن فِئَةٍ قَلِيلَةٍ غَلَبَتْ فِئَةً كَثِيرَةًۢ بِإِذْنِ ٱللَّهِ ۗ وَٱللَّهُ مَعَ ٱلصَّـٰبِرِينَ','Falammaa fasala Taalootu biljunoodi qaala innal laaha mubtaleekum binaharin faman shariba minhu falaisa minnee wa mallam yat\'amhu fa innahoo minneee illaa manigh tarafa ghurfatam biyadih; fashariboo minhu illaa qaleelamminhum; falammaa jaawazahoo huwa wallazeena aamanoo ma\'ahoo qaaloo laa taaqata lanal yawma bi Jaaloota wa junoodih; qaalallazeena yazunnoona annahum mulaaqul laahi kam min fi\'atin qaleelatin ghalabat fi\'atan kaseeratam bi iznil laah; wallaahuma\'as saabireen',249,'2:249',4,16,34,1,0,41,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(257,2,'وَلَمَّا بَرَزُوا۟ لِجَالُوتَ وَجُنُودِهِۦ قَالُوا۟ رَبَّنَآ أَفْرِغْ عَلَيْنَا صَبْرًا وَثَبِّتْ أَقْدَامَنَا وَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَـٰفِرِينَ','Wa lammaa barazoo liJaaloota wa junoodihee qaaloo Rabbanaaa afrigh \'alainaa sabranw wa sabbit aqdaamanaa wansurnaa \'alal qawmil kaafireen',250,'2:250',4,16,34,1,0,41,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(258,2,'فَهَزَمُوهُم بِإِذْنِ ٱللَّهِ وَقَتَلَ دَاوُۥدُ جَالُوتَ وَءَاتَىٰهُ ٱللَّهُ ٱلْمُلْكَ وَٱلْحِكْمَةَ وَعَلَّمَهُۥ مِمَّا يَشَآءُ ۗ وَلَوْلَا دَفْعُ ٱللَّهِ ٱلنَّاسَ بَعْضَهُم بِبَعْضٍ لَّفَسَدَتِ ٱلْأَرْضُ وَلَـٰكِنَّ ٱللَّهَ ذُو فَضْلٍ عَلَى ٱلْعَـٰلَمِينَ','Fahazamoohum bi iznillaahi wa qatala Daawoodu jaaloota wa aataahul laahulmulka Wal Hikmata wa \'allamahoo mimmaa yashaaa\'; wa law laa daf\'ullaahin naasa ba\'dahum biba\'dil lafasadatil ardu wa laakinnal laaha zoo fadlin \'alal\'aalameen',251,'2:251',4,16,34,1,0,41,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(259,2,'تِلْكَ ءَايَـٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ ۚ وَإِنَّكَ لَمِنَ ٱلْمُرْسَلِينَ','Tilka Aayaatul laahi natloohaa \'alaika bilhaqq; wa innaka laminal mursaleen',252,'2:252',4,16,34,1,0,41,2,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(260,2,'۞ تِلْكَ ٱلرُّسُلُ فَضَّلْنَا بَعْضَهُمْ عَلَىٰ بَعْضٍ ۘ مِّنْهُم مَّن كَلَّمَ ٱللَّهُ ۖ وَرَفَعَ بَعْضَهُمْ دَرَجَـٰتٍ ۚ وَءَاتَيْنَا عِيسَى ٱبْنَ مَرْيَمَ ٱلْبَيِّنَـٰتِ وَأَيَّدْنَـٰهُ بِرُوحِ ٱلْقُدُسِ ۗ وَلَوْ شَآءَ ٱللَّهُ مَا ٱقْتَتَلَ ٱلَّذِينَ مِنۢ بَعْدِهِم مِّنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَـٰتُ وَلَـٰكِنِ ٱخْتَلَفُوا۟ فَمِنْهُم مَّنْ ءَامَنَ وَمِنْهُم مَّن كَفَرَ ۚ وَلَوْ شَآءَ ٱللَّهُ مَا ٱقْتَتَلُوا۟ وَلَـٰكِنَّ ٱللَّهَ يَفْعَلُ مَا يُرِيدُ','Tilkar Rusulu faddalnaa ba\'dahum \'alaa ba\'d; minhum man kallamal laahu wa rafa\'a ba\'dahum darajaat; wa aatainaa \'Eesab na Maryamal baiyinaati wa ayyadnaahu bi Roohil Qudus; wa law shaaa\'al laahu maqtatalal lazeena mimba\'dihim mim ba\'di maa jaaa\'athumul baiyinaatu wa laakinikh talafoo faminhum man aamana wa minhum man kafar; wa law shaaa\'al laahu maq tataloo wa laakinnallaaha yaf\'alu maa yureed (',253,'2:253',5,17,34,1,0,42,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(261,2,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَنفِقُوا۟ مِمَّا رَزَقْنَـٰكُم مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا خُلَّةٌ وَلَا شَفَـٰعَةٌ ۗ وَٱلْكَـٰفِرُونَ هُمُ ٱلظَّـٰلِمُونَ','Yaa ayyuhal lazeena aamanoo anfiqoo mimmaa razaqnaakum min qabli ai yaatiya yawmul laa bai\'un fee wa la khullatunw wa laa shafaa\'ah; walkaa firoona humuz zaalimoon',254,'2:254',5,17,35,1,0,42,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(262,2,'ٱللَّهُ لَآ إِلَـٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ ۚ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ ۚ وَسِعَ كُرْسِيُّهُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ ۖ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا ۚ وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ','Allahu laaa ilaaha illaa Huwal Haiyul Qaiyoom; laa taakhuzuhoo sinatunw wa laa nawm; lahoo maa fissamaawaati wa maa fil ard; man zal lazee yashfa\'u indahooo illaa bi-iznih; ya\'lamu maa baina aydeehim wa mww khalfahum wa laa yuheetoona bishai\'im min \'ilmihee illaa bimaa shaaa\'; wasi\'a Kursiyyuhus samaawaati wal arda wa laa ya\'ooduho hifzuhumaa; wa Huwal Aliyyul \'Azeem',255,'2:255',5,17,35,1,0,42,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(263,2,'لَآ إِكْرَاهَ فِى ٱلدِّينِ ۖ قَد تَّبَيَّنَ ٱلرُّشْدُ مِنَ ٱلْغَىِّ ۚ فَمَن يَكْفُرْ بِٱلطَّـٰغُوتِ وَيُؤْمِنۢ بِٱللَّهِ فَقَدِ ٱسْتَمْسَكَ بِٱلْعُرْوَةِ ٱلْوُثْقَىٰ لَا ٱنفِصَامَ لَهَا ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ','Laaa ikraaha fid deeni qat tabiyanar rushdu minal ghayy; famai yakfur bit Taaghooti wa yu\'mim billaahi faqadis tamsaka bil\'urwatil wusqaa lan fisaama lahaa; wallaahu Samee\'un \'Aleem',256,'2:256',5,17,35,1,0,42,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(264,2,'ٱللَّهُ وَلِىُّ ٱلَّذِينَ ءَامَنُوا۟ يُخْرِجُهُم مِّنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ ۖ وَٱلَّذِينَ كَفَرُوٓا۟ أَوْلِيَآؤُهُمُ ٱلطَّـٰغُوتُ يُخْرِجُونَهُم مِّنَ ٱلنُّورِ إِلَى ٱلظُّلُمَـٰتِ ۗ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ','Allaahu waliyyul lazeena aamanoo yukhrijuhum minaz zulumaati ilan noori wallazeena kafarooo awliyaaa\'uhumut Taaghootu yukhrijoonahum minan noori ilaz zulumaat; ulaaa\'ika Ashaabun Naari hum feehaa khaalidoon',257,'2:257',5,17,35,1,0,43,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(265,2,'أَلَمْ تَرَ إِلَى ٱلَّذِى حَآجَّ إِبْرَٰهِـۧمَ فِى رَبِّهِۦٓ أَنْ ءَاتَىٰهُ ٱللَّهُ ٱلْمُلْكَ إِذْ قَالَ إِبْرَٰهِـۧمُ رَبِّىَ ٱلَّذِى يُحْىِۦ وَيُمِيتُ قَالَ أَنَا۠ أُحْىِۦ وَأُمِيتُ ۖ قَالَ إِبْرَٰهِـۧمُ فَإِنَّ ٱللَّهَ يَأْتِى بِٱلشَّمْسِ مِنَ ٱلْمَشْرِقِ فَأْتِ بِهَا مِنَ ٱلْمَغْرِبِ فَبُهِتَ ٱلَّذِى كَفَرَ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ','Alam tara ilal lazee Haaajja Ibraaheema fee Rabbiheee an aataahullaahul mulka iz qaala Ibraaheemu Rabbiyal lazee yuhyee wa yumeetu qaala ana uhyee wa yumeetu qaala ana uhyee wa umeetu qaala Ibraaheemu fa innal laaha yaatee bishshamsi minal mashriqi faati bihaa minal maghribi fabuhital lazee kafar; wallaahu laa yahdil qawmaz zaalimeen',258,'2:258',5,17,36,1,0,43,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(266,2,'أَوْ كَٱلَّذِى مَرَّ عَلَىٰ قَرْيَةٍ وَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَنَّىٰ يُحْىِۦ هَـٰذِهِ ٱللَّهُ بَعْدَ مَوْتِهَا ۖ فَأَمَاتَهُ ٱللَّهُ مِا۟ئَةَ عَامٍ ثُمَّ بَعَثَهُۥ ۖ قَالَ كَمْ لَبِثْتَ ۖ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ ۖ قَالَ بَل لَّبِثْتَ مِا۟ئَةَ عَامٍ فَٱنظُرْ إِلَىٰ طَعَامِكَ وَشَرَابِكَ لَمْ يَتَسَنَّهْ ۖ وَٱنظُرْ إِلَىٰ حِمَارِكَ وَلِنَجْعَلَكَ ءَايَةً لِّلنَّاسِ ۖ وَٱنظُرْ إِلَى ٱلْعِظَامِ كَيْفَ نُنشِزُهَا ثُمَّ نَكْسُوهَا لَحْمًا ۚ فَلَمَّا تَبَيَّنَ لَهُۥ قَالَ أَعْلَمُ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ','Aw kallazee marra \'alaa qaryatinw wa hiya khaawiyatun \'alaa \'urooshihaa qaala annaa yuhyee haazihil laahu ba\'da mawtihaa fa amaatahul laahu mi\'ata \'aamin suumma ba\'asahoo qaala kam labista qaala labistu yawman aw ba\'da yawmin qaala bal labista mi\'ata \'aamin fanzur ilaa ta\'aamika wa sharaabika lam yatasannah wanzur ilaa himaarika wa linaj\'alaka Aayatal linnaasi wanzur ilal\'izaami kaifa nunshizuhaa summa naksoohaa lahmaa; falammaa tabiyana lahoo qaala a\'lamu annal laaha \'alaakulli shai\'in Qadeer',259,'2:259',5,17,36,1,0,43,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(267,2,'وَإِذْ قَالَ إِبْرَٰهِـۧمُ رَبِّ أَرِنِى كَيْفَ تُحْىِ ٱلْمَوْتَىٰ ۖ قَالَ أَوَلَمْ تُؤْمِن ۖ قَالَ بَلَىٰ وَلَـٰكِن لِّيَطْمَئِنَّ قَلْبِى ۖ قَالَ فَخُذْ أَرْبَعَةً مِّنَ ٱلطَّيْرِ فَصُرْهُنَّ إِلَيْكَ ثُمَّ ٱجْعَلْ عَلَىٰ كُلِّ جَبَلٍ مِّنْهُنَّ جُزْءًا ثُمَّ ٱدْعُهُنَّ يَأْتِينَكَ سَعْيًا ۚ وَٱعْلَمْ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ','Wa iz qaala Ibraaheemu Rabbi arinee kaifa tuhyil mawtaa qaala awa lam tu\'min qaala balaa wa laakil liyatma\'inna qalbee qaala fakhuz arab\'atam minal tairi fasurhunna ilaika summaj \'al a\'alaa kulli jabalim minhunna juz\'an sumaad \'uhunna yaateenaka sa\'yaa; wa\'lam annal laaha \'Azeezun Hakeem',260,'2:260',5,17,36,1,0,44,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(268,2,'مَّثَلُ ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ فِى سَبِيلِ ٱللَّهِ كَمَثَلِ حَبَّةٍ أَنۢبَتَتْ سَبْعَ سَنَابِلَ فِى كُلِّ سُنۢبُلَةٍ مِّا۟ئَةُ حَبَّةٍ ۗ وَٱللَّهُ يُضَـٰعِفُ لِمَن يَشَآءُ ۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ','Masalul lazeena yunfiqoona amwaalahum fee sabeelil laahi kamasali habbatin ambatat sab\'a sanaabila fee kulli sumbulatim mi\'atu habbah; wallaahu yudaa\'ifu limai yashaaa; wallaahu Waasi\'un \'Aleem',261,'2:261',5,17,37,1,0,44,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(269,2,'ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ فِى سَبِيلِ ٱللَّهِ ثُمَّ لَا يُتْبِعُونَ مَآ أَنفَقُوا۟ مَنًّا وَلَآ أَذًى ۙ لَّهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ','Allazeena yunfiqoona amwaalahum fee sabeelillaahi summa laa yutbi\'oona maaa anfaqoo mannanw wa laaa azal lahum ajruhum \'inda Rabbihim; wa laa khawfun \'alaihim wa laa hum yahzanoon',262,'2:262',5,17,37,1,0,44,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(270,2,'۞ قَوْلٌ مَّعْرُوفٌ وَمَغْفِرَةٌ خَيْرٌ مِّن صَدَقَةٍ يَتْبَعُهَآ أَذًى ۗ وَٱللَّهُ غَنِىٌّ حَلِيمٌ','Qawlum ma\'roofunw wa maghfiratun khairum min sadaqatiny yatba\'uhaaa azaa; wallaahu Ghaniyyun Haleem',263,'2:263',5,18,37,1,0,44,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(271,2,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُبْطِلُوا۟ صَدَقَـٰتِكُم بِٱلْمَنِّ وَٱلْأَذَىٰ كَٱلَّذِى يُنفِقُ مَالَهُۥ رِئَآءَ ٱلنَّاسِ وَلَا يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ ۖ فَمَثَلُهُۥ كَمَثَلِ صَفْوَانٍ عَلَيْهِ تُرَابٌ فَأَصَابَهُۥ وَابِلٌ فَتَرَكَهُۥ صَلْدًا ۖ لَّا يَقْدِرُونَ عَلَىٰ شَىْءٍ مِّمَّا كَسَبُوا۟ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَـٰفِرِينَ','Yaaa ayyuhal lazeena aamanoo laa tubtiloo sadaqaatikum bilmanni wal azaa kallazee yunfiqu maalahoo ri\'aaa\'an naasi wa laa yu\'minu billaahi wal yawmil aakhiri famasaluhoo kamasali safwaanin \'alaihi turaabun fa asaabahoo waabilun fatara kahoo saldaa; laa yaqdiroona \'alaa shai\'im mimmaa kasaboo; wallaahu laa yahdil qawmal kaafireen',264,'2:264',5,18,37,1,0,44,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(272,2,'وَمَثَلُ ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمُ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ وَتَثْبِيتًا مِّنْ أَنفُسِهِمْ كَمَثَلِ جَنَّةٍۭ بِرَبْوَةٍ أَصَابَهَا وَابِلٌ فَـَٔاتَتْ أُكُلَهَا ضِعْفَيْنِ فَإِن لَّمْ يُصِبْهَا وَابِلٌ فَطَلٌّ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ','Wa masalul lazeena yunfiqoona amwaalahumub ti ghaaaa\'a mardaatil laahi wa tasbeetam min anfusihim kamasali jannatim birabwatin asaabahaa waabilun fa aatat ukulahaa di\'faini fa il lam yusibhaa waabilun fatall; wallaahu bimaa ta\'maloona Baseer',265,'2:265',5,18,37,1,0,45,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(273,2,'أَيَوَدُّ أَحَدُكُمْ أَن تَكُونَ لَهُۥ جَنَّةٌ مِّن نَّخِيلٍ وَأَعْنَابٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ لَهُۥ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَأَصَابَهُ ٱلْكِبَرُ وَلَهُۥ ذُرِّيَّةٌ ضُعَفَآءُ فَأَصَابَهَآ إِعْصَارٌ فِيهِ نَارٌ فَٱحْتَرَقَتْ ۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْـَٔايَـٰتِ لَعَلَّكُمْ تَتَفَكَّرُونَ','Ayawaddu ahadukum an takoona lahoo jannatum min nakheelinw wa a\'naabin tajree min tahtihal anhaaru lahoo feehaa min kullis samaraati wa asaabahul kibaru wa lahoo zurriyyatun du\'afaaa\'u fa asaabahaaa i\'saarun feehi naarun fahtaraqat; kazaalika yubaiyinul laahu lakumul aayaati la\'allakum tatafakkaroon',266,'2:266',5,18,37,1,0,45,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(274,2,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَنفِقُوا۟ مِن طَيِّبَـٰتِ مَا كَسَبْتُمْ وَمِمَّآ أَخْرَجْنَا لَكُم مِّنَ ٱلْأَرْضِ ۖ وَلَا تَيَمَّمُوا۟ ٱلْخَبِيثَ مِنْهُ تُنفِقُونَ وَلَسْتُم بِـَٔاخِذِيهِ إِلَّآ أَن تُغْمِضُوا۟ فِيهِ ۚ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَنِىٌّ حَمِيدٌ','Yaaa \'ayyuhal lazeena aamanooo anfiqoo min taiyibaati maa kasabtum wa mimmaaa akhrajuaa lakum minal ardi wa laa tayammamul khabeesa minhu tunfiqoona wa lastum bi aakhizeehi illaaa an tughmidoo feeh; wa\'lamooo annal laaha Ghaniyyun Hameed',267,'2:267',5,18,38,1,0,45,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(275,2,'ٱلشَّيْطَـٰنُ يَعِدُكُمُ ٱلْفَقْرَ وَيَأْمُرُكُم بِٱلْفَحْشَآءِ ۖ وَٱللَّهُ يَعِدُكُم مَّغْفِرَةً مِّنْهُ وَفَضْلًا ۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ','Ash Shaitaanu ya\'idukumul faqra wa yaamurukum bilfahshaaa\'i wallaahu ya\'idukum maghfiratam minhu wa fadlaa; wallaahu Waasi\'un \'Aleem',268,'2:268',5,18,38,1,0,45,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(276,2,'يُؤْتِى ٱلْحِكْمَةَ مَن يَشَآءُ ۚ وَمَن يُؤْتَ ٱلْحِكْمَةَ فَقَدْ أُوتِىَ خَيْرًا كَثِيرًا ۗ وَمَا يَذَّكَّرُ إِلَّآ أُو۟لُوا۟ ٱلْأَلْبَـٰبِ','Yu\'til Hikmata mai yashaaa\'; wa mai yutal Hikmata faqad ootiya khairan kaseeraa; wa maa yazzakkaru illaaa ulul albaab',269,'2:269',5,18,38,1,0,45,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(277,2,'وَمَآ أَنفَقْتُم مِّن نَّفَقَةٍ أَوْ نَذَرْتُم مِّن نَّذْرٍ فَإِنَّ ٱللَّهَ يَعْلَمُهُۥ ۗ وَمَا لِلظَّـٰلِمِينَ مِنْ أَنصَارٍ','Wa maaa anfaqtum min nafaqatin aw nazartum min nazrin fa innal laaha ya\'lamuh; wa maa lizzaalimeena min ansaar',270,'2:270',5,18,38,1,0,46,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(278,2,'إِن تُبْدُوا۟ ٱلصَّدَقَـٰتِ فَنِعِمَّا هِىَ ۖ وَإِن تُخْفُوهَا وَتُؤْتُوهَا ٱلْفُقَرَآءَ فَهُوَ خَيْرٌ لَّكُمْ ۚ وَيُكَفِّرُ عَنكُم مِّن سَيِّـَٔاتِكُمْ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ','In tubdus sadaqaati fani\'immaa hiya wa in tukhfoohaa wa tu\'toohal fuqaraaa\'a fahuwa khayrul lakum; wa yukaffiru \'ankum min saiyi aatikum; wallaahu bimaa ta\'maloona Khabeer',271,'2:271',5,18,38,1,0,46,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(279,2,'۞ لَّيْسَ عَلَيْكَ هُدَىٰهُمْ وَلَـٰكِنَّ ٱللَّهَ يَهْدِى مَن يَشَآءُ ۗ وَمَا تُنفِقُوا۟ مِنْ خَيْرٍ فَلِأَنفُسِكُمْ ۚ وَمَا تُنفِقُونَ إِلَّا ٱبْتِغَآءَ وَجْهِ ٱللَّهِ ۚ وَمَا تُنفِقُوا۟ مِنْ خَيْرٍ يُوَفَّ إِلَيْكُمْ وَأَنتُمْ لَا تُظْلَمُونَ','Laisa \'alaika hudaahum wa laakinnal laaha yahdee mai yashaaa\'; wa maa tunfiqoo min khairin fali anfusikum; wa maa tunfiqoona illab tighaaa\'a wajhil laah; wa maa tunfiqoo min khairiny yuwaffa ilaikum wa antum laa tuzlamoon',272,'2:272',5,19,38,1,0,46,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(280,2,'لِلْفُقَرَآءِ ٱلَّذِينَ أُحْصِرُوا۟ فِى سَبِيلِ ٱللَّهِ لَا يَسْتَطِيعُونَ ضَرْبًا فِى ٱلْأَرْضِ يَحْسَبُهُمُ ٱلْجَاهِلُ أَغْنِيَآءَ مِنَ ٱلتَّعَفُّفِ تَعْرِفُهُم بِسِيمَـٰهُمْ لَا يَسْـَٔلُونَ ٱلنَّاسَ إِلْحَافًا ۗ وَمَا تُنفِقُوا۟ مِنْ خَيْرٍ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ','Lilfuqaraaa\'il lazeena uhsiroo fee sabeelil laahi laa yastatee\'oona darban fil ardi yah sabuhumul jaahilu aghniyaaa\'a minat ta\'affufi ta\'rifuhum biseemaahum laa yas\'aloonan naasa ilhaafaa; wa maa tunfiqoo min khairin fa innal laaha bihee \'Aleem',273,'2:273',5,19,38,1,0,46,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(281,2,'ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُم بِٱلَّيْلِ وَٱلنَّهَارِ سِرًّا وَعَلَانِيَةً فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ','Allazeena yunfiqoona amwaalahum billaili wan nahaari sirranw wa \'alaaniyatan falahum ajruhum \'inda Rabbihim wa laa khawfun \'alaihim wa laa hum yahzanoon',274,'2:274',5,19,39,1,0,46,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(282,2,'ٱلَّذِينَ يَأْكُلُونَ ٱلرِّبَوٰا۟ لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ ٱلَّذِى يَتَخَبَّطُهُ ٱلشَّيْطَـٰنُ مِنَ ٱلْمَسِّ ۚ ذَٰلِكَ بِأَنَّهُمْ قَالُوٓا۟ إِنَّمَا ٱلْبَيْعُ مِثْلُ ٱلرِّبَوٰا۟ ۗ وَأَحَلَّ ٱللَّهُ ٱلْبَيْعَ وَحَرَّمَ ٱلرِّبَوٰا۟ ۚ فَمَن جَآءَهُۥ مَوْعِظَةٌ مِّن رَّبِّهِۦ فَٱنتَهَىٰ فَلَهُۥ مَا سَلَفَ وَأَمْرُهُۥٓ إِلَى ٱللَّهِ ۖ وَمَنْ عَادَ فَأُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ','Allazeena yaakuloonar ribaa laa yaqoomoona illaa kamaa yaqoomul lazee yatakhabbatuhush shaitaanu minal mass; zaalika bi annahum qaalooo innamal bai\'u mishur ribaa; wa ahallal laahul bai\'a wa harramar ribba; faman jaaa\'ahoo maw\'izatum mir rabbihee fantahaa falahoo maa salafa wa amruhooo ilal laahi wa man \'aada fa ulaaa \'ika Ashaabun naari hum feehaa khaalidoon',275,'2:275',5,19,39,1,0,47,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(283,2,'يَمْحَقُ ٱللَّهُ ٱلرِّبَوٰا۟ وَيُرْبِى ٱلصَّدَقَـٰتِ ۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ','Yamhaqul laahur ribaa wa yurbis sadaqaat; wallaahu laa yuhibbu kulla kaffaarin aseem',276,'2:276',5,19,39,1,0,47,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(284,2,'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ','Innal lazeena aamanoo wa amilus saalihaati wa aqaamus salaata wa aatawuz zakaata lahum ajruhum \'inda rabbihim wa laa khawfun \'alaihim wa laa hum yahzanoon',277,'2:277',5,19,39,1,0,47,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(285,2,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَذَرُوا۟ مَا بَقِىَ مِنَ ٱلرِّبَوٰٓا۟ إِن كُنتُم مُّؤْمِنِينَ','Yaaa ayyuhal lazeena aamanut taqul laaha wa zaroo maa baqiya minar ribaaa in kuntum mu\'mineen',278,'2:278',5,19,39,1,0,47,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(286,2,'فَإِن لَّمْ تَفْعَلُوا۟ فَأْذَنُوا۟ بِحَرْبٍ مِّنَ ٱللَّهِ وَرَسُولِهِۦ ۖ وَإِن تُبْتُمْ فَلَكُمْ رُءُوسُ أَمْوَٰلِكُمْ لَا تَظْلِمُونَ وَلَا تُظْلَمُونَ','Fail lam taf\'aloo faazanoo biharbim minal laahi wa Rasoolihee wa in tubtum falakum ru\'oosu amwaalikum laa tazlimoona wa laa tuzlamoon',279,'2:279',5,19,39,1,0,47,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(287,2,'وَإِن كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَىٰ مَيْسَرَةٍ ۚ وَأَن تَصَدَّقُوا۟ خَيْرٌ لَّكُمْ ۖ إِن كُنتُمْ تَعْلَمُونَ','Wa in kaana zoo \'usratin fanaziratun ilaa maisarah; wa an tasaddaqoo khairul lakum in kuntum ta\'lamoon',280,'2:280',5,19,39,1,0,47,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(288,2,'وَٱتَّقُوا۟ يَوْمًا تُرْجَعُونَ فِيهِ إِلَى ٱللَّهِ ۖ ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ','Wattaqoo yawman turja\'oona feehi ilal laahi summa tuwaffaa kullu nafsim maa kasabat wa hum laa yuzlamoon',281,'2:281',5,19,39,1,0,47,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(289,2,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا تَدَايَنتُم بِدَيْنٍ إِلَىٰٓ أَجَلٍ مُّسَمًّى فَٱكْتُبُوهُ ۚ وَلْيَكْتُب بَّيْنَكُمْ كَاتِبٌۢ بِٱلْعَدْلِ ۚ وَلَا يَأْبَ كَاتِبٌ أَن يَكْتُبَ كَمَا عَلَّمَهُ ٱللَّهُ ۚ فَلْيَكْتُبْ وَلْيُمْلِلِ ٱلَّذِى عَلَيْهِ ٱلْحَقُّ وَلْيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا يَبْخَسْ مِنْهُ شَيْـًٔا ۚ فَإِن كَانَ ٱلَّذِى عَلَيْهِ ٱلْحَقُّ سَفِيهًا أَوْ ضَعِيفًا أَوْ لَا يَسْتَطِيعُ أَن يُمِلَّ هُوَ فَلْيُمْلِلْ وَلِيُّهُۥ بِٱلْعَدْلِ ۚ وَٱسْتَشْهِدُوا۟ شَهِيدَيْنِ مِن رِّجَالِكُمْ ۖ فَإِن لَّمْ يَكُونَا رَجُلَيْنِ فَرَجُلٌ وَٱمْرَأَتَانِ مِمَّن تَرْضَوْنَ مِنَ ٱلشُّهَدَآءِ أَن تَضِلَّ إِحْدَىٰهُمَا فَتُذَكِّرَ إِحْدَىٰهُمَا ٱلْأُخْرَىٰ ۚ وَلَا يَأْبَ ٱلشُّهَدَآءُ إِذَا مَا دُعُوا۟ ۚ وَلَا تَسْـَٔمُوٓا۟ أَن تَكْتُبُوهُ صَغِيرًا أَوْ كَبِيرًا إِلَىٰٓ أَجَلِهِۦ ۚ ذَٰلِكُمْ أَقْسَطُ عِندَ ٱللَّهِ وَأَقْوَمُ لِلشَّهَـٰدَةِ وَأَدْنَىٰٓ أَلَّا تَرْتَابُوٓا۟ ۖ إِلَّآ أَن تَكُونَ تِجَـٰرَةً حَاضِرَةً تُدِيرُونَهَا بَيْنَكُمْ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَلَّا تَكْتُبُوهَا ۗ وَأَشْهِدُوٓا۟ إِذَا تَبَايَعْتُمْ ۚ وَلَا يُضَآرَّ كَاتِبٌ وَلَا شَهِيدٌ ۚ وَإِن تَفْعَلُوا۟ فَإِنَّهُۥ فُسُوقٌۢ بِكُمْ ۗ وَٱتَّقُوا۟ ٱللَّهَ ۖ وَيُعَلِّمُكُمُ ٱللَّهُ ۗ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ','Yaa ayyuhal lazeena aamanoo izaa tadaayantum bidinin ilaa ajalimmusamman faktubooh; walyaktub bainakum kaatibum bil\'adl; wa laa yaaba kaatibun ai yaktuba kamaa \'allamahul laah; falyaktub walyumlilil lazee \'alaihil haqqu walyattaqil laaha rabbahoo wa laa yabkhas minhu shai\'aa; fa in kaanal lazee \'alaihil lhaqqu safeehan aw da\'eefan aw laa yastatee\'u ai yumilla huwa falyumlil waliyyuhoo bil\'adl; wastash hidoo shaheedaini mir rijaalikum fa il lam yakoonaa rajulaini farajulunw wamra ataani mimman tardawna minash shuhadaaa\'i an tadilla ihdaahumaa fatuzakkira ihdaahumal ukhraa; wa laa yaabash shuhadaaa\'u izaa maadu\'oo; wa laa tas\'amooo an taktuboohu sagheeran awkabeeran ilaaa ajalih; zaalikum aqsatu \'indal laahi wa aqwamu lishshahaadati wa adnaaa allaa tartaabooo illaaa an takoona tijaaratan haadiratan tudeeroonahaa bainakum falaisa \'alaikum junaahun allaa taktuboohan; wa ashidooo izaa tabaaya\'tum; wa laa yudaaarra kaatibunw wa laa shaheed; wa in taf\'aloo fa innahoo fusooqum bikum; wattaqul laaha wa yu\'allimu kumul laah; wallaahu bikulli shai\'in \'Aleem',282,'2:282',5,19,40,1,0,48,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(290,2,'۞ وَإِن كُنتُمْ عَلَىٰ سَفَرٍ وَلَمْ تَجِدُوا۟ كَاتِبًا فَرِهَـٰنٌ مَّقْبُوضَةٌ ۖ فَإِنْ أَمِنَ بَعْضُكُم بَعْضًا فَلْيُؤَدِّ ٱلَّذِى ٱؤْتُمِنَ أَمَـٰنَتَهُۥ وَلْيَتَّقِ ٱللَّهَ رَبَّهُۥ ۗ وَلَا تَكْتُمُوا۟ ٱلشَّهَـٰدَةَ ۚ وَمَن يَكْتُمْهَا فَإِنَّهُۥٓ ءَاثِمٌ قَلْبُهُۥ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ عَلِيمٌ','Wa in kuntum \'alaa safarinw wa lam tajidoo kaatiban farihaanum maqboodatun fa in amina ba\'dukum ba\'dan falyu\'addil lazi tumina amaa natahoo walyattaqil laaha Rabbah; wa laa taktumush shahaadah; wa mai yaktumhaa fa innahooo aasimun qalbuh; wallaahu bimaa ta\'maloona \'Aleem',283,'2:283',5,20,40,1,0,49,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(291,2,'لِّلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَإِن تُبْدُوا۟ مَا فِىٓ أَنفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُم بِهِ ٱللَّهُ ۖ فَيَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ','Lillaahi maa fissamaawaati wa maa fil ard; wa in tubdoo maa feee anfusikum aw tukhfoohu yuhaasibkum bihil laa; fayaghfiru li mai yashaaa\'u wa yu\'azzibu mai yashaaa u;wallaahu \'alaa kulli shai in qadeer',284,'2:284',5,20,41,1,0,49,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(292,2,'ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيْهِ مِن رَّبِّهِۦ وَٱلْمُؤْمِنُونَ ۚ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَـٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِۦ ۚ وَقَالُوا۟ سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ ٱلْمَصِيرُ','Aamanar-Rasoolu bimaaa unzila ilaihi mir-Rabbihee walmu\'minoon; kullun aamana billaahi wa Malaaa\'ikathihee wa Kutubhihee wa Rusulih laa nufarriqu baina ahadim-mir-Rusulihee wa qaaloo sami\'naa wa ata\'naa ghufraanaka Rabbanaa wa ilaikal-maseer',285,'2:285',5,20,41,1,0,49,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(293,2,'لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا وُسْعَهَا ۚ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا ٱكْتَسَبَتْ ۗ رَبَّنَا لَا تُؤَاخِذْنَآ إِن نَّسِينَآ أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَآ إِصْرًا كَمَا حَمَلْتَهُۥ عَلَى ٱلَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِۦ ۖ وَٱعْفُ عَنَّا وَٱغْفِرْ لَنَا وَٱرْحَمْنَآ ۚ أَنتَ مَوْلَىٰنَا فَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَـٰفِرِينَ','Laa yukalliful-laahu nafsan illaa wus\'ahaa; lahaa maa kasabat wa \'alaihaa maktasabat; Rabbanaa la tu\'aakhiznaa in naseenaaa aw akhtaanaa; Rabbanaa wa laa tahmil-\'alainaaa isran kamaa hamaltahoo \'alal-lazeena min qablinaa; Rabbanaa wa laa tuhammilnaa maa laa taaqata lanaa bih wa\'fu \'annaa waghfir lanaa warhamnaa; Anta mawlaanaa fansurnaa \'alal qawmil kaafireen',286,'2:286',5,20,41,1,0,49,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(294,3,'الٓمٓ','Alif-Laam-Meeem',1,'3:1',5,20,42,1,0,50,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(295,3,'ٱللَّهُ لَآ إِلَـٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ','Allaahu laaa ilaaha illaa Huwal Haiyul Qaiyoom',2,'3:2',5,20,42,1,0,50,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(296,3,'نَزَّلَ عَلَيْكَ ٱلْكِتَـٰبَ بِٱلْحَقِّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ وَأَنزَلَ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ','Nazzala \'alaikal Kitaaba bilhaqqi musaddiqal limaa baina yadaihi wa anzalat Tawraata wal Injeel',3,'3:3',5,20,42,1,0,50,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(297,3,'مِن قَبْلُ هُدًى لِّلنَّاسِ وَأَنزَلَ ٱلْفُرْقَانَ ۗ إِنَّ ٱلَّذِينَ كَفَرُوا۟ بِـَٔايَـٰتِ ٱللَّهِ لَهُمْ عَذَابٌ شَدِيدٌ ۗ وَٱللَّهُ عَزِيزٌ ذُو ٱنتِقَامٍ','Min qablu hudal linnaasi wa anzalal Furqaan; innallazeena kafaroo bi Aayaatil laahi lahum \'azaabun shadeed; wallaahu \'azeezun zun tiqaam',4,'3:4',5,20,42,1,0,50,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(298,3,'إِنَّ ٱللَّهَ لَا يَخْفَىٰ عَلَيْهِ شَىْءٌ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ','Innal laaha laa yakhfaa \'alaihi shai\'un fil ardi wa laa fis samaaa\'',5,'3:5',5,20,42,1,0,50,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(299,3,'هُوَ ٱلَّذِى يُصَوِّرُكُمْ فِى ٱلْأَرْحَامِ كَيْفَ يَشَآءُ ۚ لَآ إِلَـٰهَ إِلَّا هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ','Huwal lazee yusawwirukum fil arhaami kaifa yashaaa\'; laa ilaaha illaa Huwal \'Azeezul Hakeem',6,'3:6',5,20,42,1,0,50,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(300,3,'هُوَ ٱلَّذِىٓ أَنزَلَ عَلَيْكَ ٱلْكِتَـٰبَ مِنْهُ ءَايَـٰتٌ مُّحْكَمَـٰتٌ هُنَّ أُمُّ ٱلْكِتَـٰبِ وَأُخَرُ مُتَشَـٰبِهَـٰتٌ ۖ فَأَمَّا ٱلَّذِينَ فِى قُلُوبِهِمْ زَيْغٌ فَيَتَّبِعُونَ مَا تَشَـٰبَهَ مِنْهُ ٱبْتِغَآءَ ٱلْفِتْنَةِ وَٱبْتِغَآءَ تَأْوِيلِهِۦ ۗ وَمَا يَعْلَمُ تَأْوِيلَهُۥٓ إِلَّا ٱللَّهُ ۗ وَٱلرَّٰسِخُونَ فِى ٱلْعِلْمِ يَقُولُونَ ءَامَنَّا بِهِۦ كُلٌّ مِّنْ عِندِ رَبِّنَا ۗ وَمَا يَذَّكَّرُ إِلَّآ أُو۟لُوا۟ ٱلْأَلْبَـٰبِ','Huwal lazeee anzala \'alaikal Kitaaba minhu Aayaatum Muh kamaatun hunna Ummul Kitaabi wa ukharu Mutashaabihaatun faammal lazeena fee quloobihim ziyghun fa yattabi\'oona ma tashaabaha minhubtighaaa \'alfitnati wabtighaaa\'a taaweelih; wa maa ya\'lamu taaweelahooo illal laah; warraasikhoona fil \'ilmi yaqooloona aamannaa bihee kullum min \'indi Rabbinaa; wa maa yazzakkaru illaaa ulul albaab',7,'3:7',5,20,42,1,0,50,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(301,3,'رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً ۚ إِنَّكَ أَنتَ ٱلْوَهَّابُ','Rabbanaa laa tuzigh quloobanaa ba\'da iz hadaitanaa wa hab lanaa mil ladunka rahmah; innaka antal Wahhaab',8,'3:8',5,20,42,1,0,50,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(302,3,'رَبَّنَآ إِنَّكَ جَامِعُ ٱلنَّاسِ لِيَوْمٍ لَّا رَيْبَ فِيهِ ۚ إِنَّ ٱللَّهَ لَا يُخْلِفُ ٱلْمِيعَادَ','Rabbanaaa innaka jaami \'un-naasi li Yawmil laa raibafeeh; innal laaha laa yukhliful mee\'aad',9,'3:9',5,20,42,1,0,50,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(303,3,'إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَـٰدُهُم مِّنَ ٱللَّهِ شَيْـًٔا ۖ وَأُو۟لَـٰٓئِكَ هُمْ وَقُودُ ٱلنَّارِ','Innal lazeena kafaroo lan tughniya \'anhum amwaaluhum wa laaa awlaaduhum minal laahi shai\'anw wa ulaaa\'ika hum waqoodun Naar',10,'3:10',5,20,43,1,0,51,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(304,3,'كَدَأْبِ ءَالِ فِرْعَوْنَ وَٱلَّذِينَ مِن قَبْلِهِمْ ۚ كَذَّبُوا۟ بِـَٔايَـٰتِنَا فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ ۗ وَٱللَّهُ شَدِيدُ ٱلْعِقَابِ','Kadaabi Aali Fir\'awna wallazeena min qablihim; kazzaboo bi Aayaatinaa fa akhazahumul laahu bizunoo bihim; wallaahu shadeedul \'iqaab',11,'3:11',5,20,43,1,0,51,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(305,3,'قُل لِّلَّذِينَ كَفَرُوا۟ سَتُغْلَبُونَ وَتُحْشَرُونَ إِلَىٰ جَهَنَّمَ ۚ وَبِئْسَ ٱلْمِهَادُ','Qul lillazeena kafaroosatughlaboona wa tuhsharoona ilaa jahannam; wa bi\'sal mihaad',12,'3:12',5,20,43,1,0,51,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(306,3,'قَدْ كَانَ لَكُمْ ءَايَةٌ فِى فِئَتَيْنِ ٱلْتَقَتَا ۖ فِئَةٌ تُقَـٰتِلُ فِى سَبِيلِ ٱللَّهِ وَأُخْرَىٰ كَافِرَةٌ يَرَوْنَهُم مِّثْلَيْهِمْ رَأْىَ ٱلْعَيْنِ ۚ وَٱللَّهُ يُؤَيِّدُ بِنَصْرِهِۦ مَن يَشَآءُ ۗ إِنَّ فِى ذَٰلِكَ لَعِبْرَةً لِّأُو۟لِى ٱلْأَبْصَـٰرِ','Qad kaana lakum Aayatun fee fi\'atainil taqataa fi\'atun tuqaatilu fee sabeelil laahi wa ukhraa kaafiratuny yarawnahum mislaihim raayal \'ayn; wallaahu yu\'ayyidu bi nasrihee mai yashaaa\'; innaa fee zaalika la \'ibratal li ulil absaar',13,'3:13',5,20,43,1,0,51,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(307,3,'زُيِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَٰتِ مِنَ ٱلنِّسَآءِ وَٱلْبَنِينَ وَٱلْقَنَـٰطِيرِ ٱلْمُقَنطَرَةِ مِنَ ٱلذَّهَبِ وَٱلْفِضَّةِ وَٱلْخَيْلِ ٱلْمُسَوَّمَةِ وَٱلْأَنْعَـٰمِ وَٱلْحَرْثِ ۗ ذَٰلِكَ مَتَـٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَٱللَّهُ عِندَهُۥ حُسْنُ ٱلْمَـَٔابِ','Zuyyina linnaasi hubbush shahawaati minannisaaa\'i wal baneena walqanaateeril muqantarati minaz zahabi walfiddati walkhailil musawwamati wal an\'aami walhars; zaalika mataa\'ul hayaatid dunyaa wallaahu \'indahoo husnul ma-aab',14,'3:14',5,20,43,1,0,51,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(308,3,'۞ قُلْ أَؤُنَبِّئُكُم بِخَيْرٍ مِّن ذَٰلِكُمْ ۚ لِلَّذِينَ ٱتَّقَوْا۟ عِندَ رَبِّهِمْ جَنَّـٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا وَأَزْوَٰجٌ مُّطَهَّرَةٌ وَرِضْوَٰنٌ مِّنَ ٱللَّهِ ۗ وَٱللَّهُ بَصِيرٌۢ بِٱلْعِبَادِ','Qul a\'unabbi \'ukum bikhairim min zaalikum; lillazeenat taqaw \'inda Rabbihim jannaatun tajree min tahtihal anhaaru khaalideena feehaa wa azwaajum mutahharatunw wa ridwaanum minal laah; wallaahu baseerum bil\'ibaad',15,'3:15',6,21,43,1,0,51,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(309,3,'ٱلَّذِينَ يَقُولُونَ رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ','Allazeena yaqooloona Rabbanaaa innanaaa aamannaa faghfir lanaa zunoobanaa wa qinaa \'azaaban Naar',16,'3:16',6,21,43,1,0,52,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(310,3,'ٱلصَّـٰبِرِينَ وَٱلصَّـٰدِقِينَ وَٱلْقَـٰنِتِينَ وَٱلْمُنفِقِينَ وَٱلْمُسْتَغْفِرِينَ بِٱلْأَسْحَارِ','Assaabireena wassaa diqeena walqaaniteena walmunfiqeena walmus taghfireena bil ashaar',17,'3:17',6,21,43,1,0,52,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(311,3,'شَهِدَ ٱللَّهُ أَنَّهُۥ لَآ إِلَـٰهَ إِلَّا هُوَ وَٱلْمَلَـٰٓئِكَةُ وَأُو۟لُوا۟ ٱلْعِلْمِ قَآئِمًۢا بِٱلْقِسْطِ ۚ لَآ إِلَـٰهَ إِلَّا هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ','Shahidal laahu annahoo laa ilaaha illaa Huwa walmalaaa\'ikatu wa ulul \'ilmi qaaa\'imam bilqist; laaa ilaaha illaa Huwal \'Azeezul Hakeem',18,'3:18',6,21,43,1,0,52,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(312,3,'إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلْإِسْلَـٰمُ ۗ وَمَا ٱخْتَلَفَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ ۗ وَمَن يَكْفُرْ بِـَٔايَـٰتِ ٱللَّهِ فَإِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ','Innad deena \'indal laahil Islaam; wa makhtalafal lazeena ootul Kitaaba illaa mim ba\'di maa jaaa\'ahumul \'ilmu baghyam bainahum; wa mai yakfur bi Aayaatil laahi fa innal laaha saree\'ul hisaab',19,'3:19',6,21,43,1,0,52,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(313,3,'فَإِنْ حَآجُّوكَ فَقُلْ أَسْلَمْتُ وَجْهِىَ لِلَّهِ وَمَنِ ٱتَّبَعَنِ ۗ وَقُل لِّلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ وَٱلْأُمِّيِّـۧنَ ءَأَسْلَمْتُمْ ۚ فَإِنْ أَسْلَمُوا۟ فَقَدِ ٱهْتَدَوا۟ ۖ وَّإِن تَوَلَّوْا۟ فَإِنَّمَا عَلَيْكَ ٱلْبَلَـٰغُ ۗ وَٱللَّهُ بَصِيرٌۢ بِٱلْعِبَادِ','Fa in haaajjooka faqul aslamtu wajhiya lillaahi wa manit taba\'an; wa qul lillazeena ootul Kitaaba wal ummiyyeena \'a-aslamtum; fa in aslamoo faqadih tadaw wa in tawallaw fa innamaa \'alaikal balaagh; wallaahu baseerum bil \'ibaad',20,'3:20',6,21,43,1,0,52,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(314,3,'إِنَّ ٱلَّذِينَ يَكْفُرُونَ بِـَٔايَـٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيْرِ حَقٍّ وَيَقْتُلُونَ ٱلَّذِينَ يَأْمُرُونَ بِٱلْقِسْطِ مِنَ ٱلنَّاسِ فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ','Innal lazeena yakfuroona bi Aayaatil laahi wa yaqtuloonan Nabiyyeena bighairi haqqinw wa yaqtuloonal lazeena yaamuroona bilqisti minannaasi fabashirhum bi\'azaabin aleem',21,'3:21',6,21,44,1,0,52,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(315,3,'أُو۟لَـٰٓئِكَ ٱلَّذِينَ حَبِطَتْ أَعْمَـٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَمَا لَهُم مِّن نَّـٰصِرِينَ','Ulaaa\'ikal lazeena habitat a\'maaluhum fid dunyaa wal Aaakhirati wa maa lahum min naasireen',22,'3:22',6,21,44,1,0,52,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(316,3,'أَلَمْ تَرَ إِلَى ٱلَّذِينَ أُوتُوا۟ نَصِيبًا مِّنَ ٱلْكِتَـٰبِ يُدْعَوْنَ إِلَىٰ كِتَـٰبِ ٱللَّهِ لِيَحْكُمَ بَيْنَهُمْ ثُمَّ يَتَوَلَّىٰ فَرِيقٌ مِّنْهُمْ وَهُم مُّعْرِضُونَ','Alam tara ilal lazeena ootoo naseebam minal Kitaabi yud\'awna ilaa Kitaabil laahi liyahkuma bainahum summa yatawallaa fareequm minhum wa hum mu\'ridoon',23,'3:23',6,21,44,1,0,53,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(317,3,'ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًا مَّعْدُودَٰتٍ ۖ وَغَرَّهُمْ فِى دِينِهِم مَّا كَانُوا۟ يَفْتَرُونَ','Zaalika bi annahum qaaloo lan tamassanan naaru illaaa ayyaamam ma\'doodaatinw wa gharrahum fee deenihim maa kaanoo yaftaroon',24,'3:24',6,21,44,1,0,53,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(318,3,'فَكَيْفَ إِذَا جَمَعْنَـٰهُمْ لِيَوْمٍ لَّا رَيْبَ فِيهِ وَوُفِّيَتْ كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ','Fakaifa izaa jama\'naahum li Yawmil laa raiba fee wa wuffiyat kullu nafsim maa kasabat wa hum laa yuzlamoon',25,'3:25',6,21,44,1,0,53,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(319,3,'قُلِ ٱللَّهُمَّ مَـٰلِكَ ٱلْمُلْكِ تُؤْتِى ٱلْمُلْكَ مَن تَشَآءُ وَتَنزِعُ ٱلْمُلْكَ مِمَّن تَشَآءُ وَتُعِزُّ مَن تَشَآءُ وَتُذِلُّ مَن تَشَآءُ ۖ بِيَدِكَ ٱلْخَيْرُ ۖ إِنَّكَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ','Qulil laahumma Maalikal Mulki tu\'til mulka man tashaaa\'u wa tanzi\'ulmulka mimman tashhaaa\'u wa tu\'izzu man tashaaa\'u wa tuzillu man tashaaa\'u biyadikal khairu innaka \'alaa kulli shai\'in Qadeer',26,'3:26',6,21,44,1,0,53,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(320,3,'تُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَتُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ ۖ وَتُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَتُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ ۖ وَتَرْزُقُ مَن تَشَآءُ بِغَيْرِ حِسَابٍ','Toolijul laila fin nahaari wa toolijun nahaara fil laili wa tukhrijul haiya minalmaiyiti wa tukhrijulo maiyita minal haiyi wa tarzuqu man tashaaa\'u bighari hisab',27,'3:27',6,21,44,1,0,53,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(321,3,'لَّا يَتَّخِذِ ٱلْمُؤْمِنُونَ ٱلْكَـٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ ۖ وَمَن يَفْعَلْ ذَٰلِكَ فَلَيْسَ مِنَ ٱللَّهِ فِى شَىْءٍ إِلَّآ أَن تَتَّقُوا۟ مِنْهُمْ تُقَىٰةً ۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفْسَهُۥ ۗ وَإِلَى ٱللَّهِ ٱلْمَصِيرُ','Laa yattakhizil mu\'minoonal kaafireena awliyaaa\'a min doonil mu\'mineena wa mai yaf\'al zaalika falaisa minal laahi fee shai\'in illaaa an tattaqoo minhum tuqaah; wa yuhazzirukumul laahu nafsah; wa ilal laahil maseer',28,'3:28',6,21,44,1,0,53,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(322,3,'قُلْ إِن تُخْفُوا۟ مَا فِى صُدُورِكُمْ أَوْ تُبْدُوهُ يَعْلَمْهُ ٱللَّهُ ۗ وَيَعْلَمُ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ','Qul in tukhfoo maa fee sudoorikum aw tubdoohu ya\'lamhul laah; wa ya\'lamu maa fis samaawaati wa maa fil ard; wallaahu \'alaa kulli shai\'in Qadeer',29,'3:29',6,21,44,1,0,53,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(323,3,'يَوْمَ تَجِدُ كُلُّ نَفْسٍ مَّا عَمِلَتْ مِنْ خَيْرٍ مُّحْضَرًا وَمَا عَمِلَتْ مِن سُوٓءٍ تَوَدُّ لَوْ أَنَّ بَيْنَهَا وَبَيْنَهُۥٓ أَمَدًۢا بَعِيدًا ۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفْسَهُۥ ۗ وَٱللَّهُ رَءُوفٌۢ بِٱلْعِبَادِ','Yawma tajidu kullu nafsim maa\'amilat min khairim muhdaranw wa maa \'amilat min sooo\'in tawaddu law anna bainahaa wa bainahooo amadam ba\'eedaa; wa yuhazzirukumul laahu nafsah; wallaahu ra\'oofum bil\'ibaad',30,'3:30',6,21,44,1,0,54,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(324,3,'قُلْ إِن كُنتُمْ تُحِبُّونَ ٱللَّهَ فَٱتَّبِعُونِى يُحْبِبْكُمُ ٱللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ ۗ وَٱللَّهُ غَفُورٌ رَّحِيمٌ','Qul in kuntum tuhibboonal laaha fattabi\' oonee yuhbibkumul laahu wa yaghfir lakum zunoobakum; wallaahu Ghafoorur Raheem',31,'3:31',6,21,45,1,0,54,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(325,3,'قُلْ أَطِيعُوا۟ ٱللَّهَ وَٱلرَّسُولَ ۖ فَإِن تَوَلَّوْا۟ فَإِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْكَـٰفِرِينَ','Qul atee\'ul laaha war Rasoola fa in tawallaw fa innal laaha laa yuhibbul kaafireen',32,'3:32',6,21,45,1,0,54,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(326,3,'۞ إِنَّ ٱللَّهَ ٱصْطَفَىٰٓ ءَادَمَ وَنُوحًا وَءَالَ إِبْرَٰهِيمَ وَءَالَ عِمْرَٰنَ عَلَى ٱلْعَـٰلَمِينَ','Innal laahas tafaaa Aadama wa Noohanw wa Aala Ibraaheema wa Aala Imraana \'alal \'aalameen',33,'3:33',6,22,45,1,0,54,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(327,3,'ذُرِّيَّةًۢ بَعْضُهَا مِنۢ بَعْضٍ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ','Zurriyyatam ba\'duhaa mim ba\'d; wallaahu Samee\'un \'Aleem',34,'3:34',6,22,45,1,0,54,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(328,3,'إِذْ قَالَتِ ٱمْرَأَتُ عِمْرَٰنَ رَبِّ إِنِّى نَذَرْتُ لَكَ مَا فِى بَطْنِى مُحَرَّرًا فَتَقَبَّلْ مِنِّىٓ ۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلْعَلِيمُ','Iz qaalatim ra atu \'Imraana Rabbi innee nazartu laka maa fee batnee muharraran fataqabbal minnee innaka Antas Samee\'ul \'Aleem',35,'3:35',6,22,45,1,0,54,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(329,3,'فَلَمَّا وَضَعَتْهَا قَالَتْ رَبِّ إِنِّى وَضَعْتُهَآ أُنثَىٰ وَٱللَّهُ أَعْلَمُ بِمَا وَضَعَتْ وَلَيْسَ ٱلذَّكَرُ كَٱلْأُنثَىٰ ۖ وَإِنِّى سَمَّيْتُهَا مَرْيَمَ وَإِنِّىٓ أُعِيذُهَا بِكَ وَذُرِّيَّتَهَا مِنَ ٱلشَّيْطَـٰنِ ٱلرَّجِيمِ','Falammaa waqa\'athaa qaalat Rabbi innee wada\'tuhaaa unsaa wallaahu a\'lamu bimaa wada\'at wa laisaz zakaru kalunsaa wa innee sammaituhaa Maryama wa innee u\'eezuhaa bika wa zurriyyatahaa minash Shaitaanir Rajeem',36,'3:36',6,22,45,1,0,54,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(330,3,'فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ حَسَنٍ وَأَنۢبَتَهَا نَبَاتًا حَسَنًا وَكَفَّلَهَا زَكَرِيَّا ۖ كُلَّمَا دَخَلَ عَلَيْهَا زَكَرِيَّا ٱلْمِحْرَابَ وَجَدَ عِندَهَا رِزْقًا ۖ قَالَ يَـٰمَرْيَمُ أَنَّىٰ لَكِ هَـٰذَا ۖ قَالَتْ هُوَ مِنْ عِندِ ٱللَّهِ ۖ إِنَّ ٱللَّهَ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍ','Fataqabbalahaa Rabbuhaa biqaboolin hasaninw wa ambatahaa nabaatan hasananw wa kaffalahaa Zakariyyaa kullamaa dakhala \'alaihaa Zakariyyal Mihraaba wajada \'indahaa rizqan qaala yaa Maryamu annaa laki haazaa qaalat huwa min \'indil laahi innal laaha yarzuqu mai yashaaa\'u bighairi hisaab',37,'3:37',6,22,45,1,0,54,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(331,3,'هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُۥ ۖ قَالَ رَبِّ هَبْ لِى مِن لَّدُنكَ ذُرِّيَّةً طَيِّبَةً ۖ إِنَّكَ سَمِيعُ ٱلدُّعَآءِ','Hunaaalika da\'aa Zakariyyaa Rabbahoo qaala Rabbi hab lee mil ladunka zurriyyatan taiyibatan innaka samee\'ud du\'aaa\'',38,'3:38',6,22,45,1,0,55,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(332,3,'فَنَادَتْهُ ٱلْمَلَـٰٓئِكَةُ وَهُوَ قَآئِمٌ يُصَلِّى فِى ٱلْمِحْرَابِ أَنَّ ٱللَّهَ يُبَشِّرُكَ بِيَحْيَىٰ مُصَدِّقًۢا بِكَلِمَةٍ مِّنَ ٱللَّهِ وَسَيِّدًا وَحَصُورًا وَنَبِيًّا مِّنَ ٱلصَّـٰلِحِينَ','Fanaadat hul malaaa\'ikatu wa huwa qaaa\'imuny yusallee fil Mihraabi annal laaha yubashshiruka bi Yahyaa musaddiqam bi Kalimatim minal laahi wa saiyidanw wa hasooranw wa Nabiyyam minas saaliheen',39,'3:39',6,22,45,1,0,55,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(333,3,'قَالَ رَبِّ أَنَّىٰ يَكُونُ لِى غُلَـٰمٌ وَقَدْ بَلَغَنِىَ ٱلْكِبَرُ وَٱمْرَأَتِى عَاقِرٌ ۖ قَالَ كَذَٰلِكَ ٱللَّهُ يَفْعَلُ مَا يَشَآءُ','Qaala Rabbi annaa yakoonu lee ghulaamunw wa qad balaghaniyal kibaru wamraatee \'aaqirun qaala kazaalikal laahu yaf\'alu maa yashaaa\'',40,'3:40',6,22,45,1,0,55,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(334,3,'قَالَ رَبِّ ٱجْعَل لِّىٓ ءَايَةً ۖ قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَـٰثَةَ أَيَّامٍ إِلَّا رَمْزًا ۗ وَٱذْكُر رَّبَّكَ كَثِيرًا وَسَبِّحْ بِٱلْعَشِىِّ وَٱلْإِبْكَـٰرِ','Qaala Rabbij \'al leee Aayatan qaala Aaayatuka allaa tukalliman naasa salaasata ayyaamin illa ramzaa; wzkur Rabbaka kaseeranw wa sabbih bil\'ashiyyi wal ibkaar',41,'3:41',6,22,45,1,0,55,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(335,3,'وَإِذْ قَالَتِ ٱلْمَلَـٰٓئِكَةُ يَـٰمَرْيَمُ إِنَّ ٱللَّهَ ٱصْطَفَىٰكِ وَطَهَّرَكِ وَٱصْطَفَىٰكِ عَلَىٰ نِسَآءِ ٱلْعَـٰلَمِينَ','Wa iz qaalatil malaaa\'ikatu yaa Ya Maryamu innal laahas tafaaki wa tahharaki wastafaaki \'alaa nisaaa\'il \'aalameen',42,'3:42',6,22,46,1,0,55,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(336,3,'يَـٰمَرْيَمُ ٱقْنُتِى لِرَبِّكِ وَٱسْجُدِى وَٱرْكَعِى مَعَ ٱلرَّٰكِعِينَ','Yaa Maryamuq nutee li Rabbiki wasjudee warka\'ee ma\'ar raaki\'een',43,'3:43',6,22,46,1,0,55,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(337,3,'ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهِ إِلَيْكَ ۚ وَمَا كُنتَ لَدَيْهِمْ إِذْ يُلْقُونَ أَقْلَـٰمَهُمْ أَيُّهُمْ يَكْفُلُ مَرْيَمَ وَمَا كُنتَ لَدَيْهِمْ إِذْ يَخْتَصِمُونَ','Zaalika min ambaaa\'il ghaibi nooheehi ilaik; wa maa kunta ladaihim iz yulqoona aqlaamahum ayyuhum yakfulu Maryama wa maa kunta ladaihim iz yakhtasimoon',44,'3:44',6,22,46,1,0,55,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(338,3,'إِذْ قَالَتِ ٱلْمَلَـٰٓئِكَةُ يَـٰمَرْيَمُ إِنَّ ٱللَّهَ يُبَشِّرُكِ بِكَلِمَةٍ مِّنْهُ ٱسْمُهُ ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ وَجِيهًا فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَمِنَ ٱلْمُقَرَّبِينَ','Iz qaalatil malaaa\'ikatu yaa Maryamu innal laaha yubashshiruki bi Kalimatim minhus muhul Maseeh u \'Eesab nu Maryama wajeehan fid dunyaa wal Aakhirati wa minal muqarrabeen',45,'3:45',6,22,46,1,0,55,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(339,3,'وَيُكَلِّمُ ٱلنَّاسَ فِى ٱلْمَهْدِ وَكَهْلًا وَمِنَ ٱلصَّـٰلِحِينَ','Wa yukallimun naasa filmahdi wa kahlanw wa minassaaliheen',46,'3:46',6,22,46,1,0,56,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(340,3,'قَالَتْ رَبِّ أَنَّىٰ يَكُونُ لِى وَلَدٌ وَلَمْ يَمْسَسْنِى بَشَرٌ ۖ قَالَ كَذَٰلِكِ ٱللَّهُ يَخْلُقُ مَا يَشَآءُ ۚ إِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ','Qaalat Rabbi annaa yakoonu ee waladunw wa lam yamsasnee basharun qaala kazaalikil laahu yakhluqu maa yashaaa\'; izaa qadaaa amran fa innamaa yaqoolu lahoo kun fayakoon',47,'3:47',6,22,46,1,0,56,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(341,3,'وَيُعَلِّمُهُ ٱلْكِتَـٰبَ وَٱلْحِكْمَةَ وَٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ','Wa yu\'allimuhul Kitaaba wal Hikmata wat Tawraata wal Injeel',48,'3:48',6,22,46,1,0,56,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(342,3,'وَرَسُولًا إِلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَنِّى قَدْ جِئْتُكُم بِـَٔايَةٍ مِّن رَّبِّكُمْ ۖ أَنِّىٓ أَخْلُقُ لَكُم مِّنَ ٱلطِّينِ كَهَيْـَٔةِ ٱلطَّيْرِ فَأَنفُخُ فِيهِ فَيَكُونُ طَيْرًۢا بِإِذْنِ ٱللَّهِ ۖ وَأُبْرِئُ ٱلْأَكْمَهَ وَٱلْأَبْرَصَ وَأُحْىِ ٱلْمَوْتَىٰ بِإِذْنِ ٱللَّهِ ۖ وَأُنَبِّئُكُم بِمَا تَأْكُلُونَ وَمَا تَدَّخِرُونَ فِى بُيُوتِكُمْ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ','Wa Rasoolan ilaa Baneee Israaa\'eela annee qad ji\'tukum bi Aayatim mir Rabbikum annee akhluqu lakum minatteeni kahai \'atittairi fa anfukhu feehi fayakoonu tairam bi iznil laahi wa ubri\'ul akmaha wal abrasa wa uhyil mawtaa bi iznil laahi wa unabbi\'ukum bimaa taakuloona wa maa taddakhiroona fee buyootikum; inna fee zaalika la Aayatal lakum in kuntum mu\'mineen',49,'3:49',6,22,46,1,0,56,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(343,3,'وَمُصَدِّقًا لِّمَا بَيْنَ يَدَىَّ مِنَ ٱلتَّوْرَىٰةِ وَلِأُحِلَّ لَكُم بَعْضَ ٱلَّذِى حُرِّمَ عَلَيْكُمْ ۚ وَجِئْتُكُم بِـَٔايَةٍ مِّن رَّبِّكُمْ فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ','Wa musaddiqal limaa baina yadaiya minat Tawraati wa liuhilla lakum ba\'dal lazee hurrima \'alaikum; wa ji\'tukum bi Aayatim mir Rabbikum fattaqul laaha wa atee\'oon',50,'3:50',6,22,46,1,0,56,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(344,3,'إِنَّ ٱللَّهَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ ۗ هَـٰذَا صِرَٰطٌ مُّسْتَقِيمٌ','Innal laaha Rabbee wa Rabbukum fa\'budooh; haazaa Siraatum Mustaqeem',51,'3:51',6,22,46,1,0,56,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(345,3,'۞ فَلَمَّآ أَحَسَّ عِيسَىٰ مِنْهُمُ ٱلْكُفْرَ قَالَ مَنْ أَنصَارِىٓ إِلَى ٱللَّهِ ۖ قَالَ ٱلْحَوَارِيُّونَ نَحْنُ أَنصَارُ ٱللَّهِ ءَامَنَّا بِٱللَّهِ وَٱشْهَدْ بِأَنَّا مُسْلِمُونَ','Falammaaa ahassa \'Eesaa minhumul kufra qaala man ansaaree ilal laahi qaalal Hawaariyyoona nahnu ansaarul laahi aamannaa billaahi washhad bi annaa muslimoon',52,'3:52',6,23,46,1,0,56,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(346,3,'رَبَّنَآ ءَامَنَّا بِمَآ أَنزَلْتَ وَٱتَّبَعْنَا ٱلرَّسُولَ فَٱكْتُبْنَا مَعَ ٱلشَّـٰهِدِينَ','Rabbanaaa aamannaa bimaaa anzalta wattaba\'nar Rasoola faktubnaa ma\'ash shaahideen',53,'3:53',6,23,46,1,0,57,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(347,3,'وَمَكَرُوا۟ وَمَكَرَ ٱللَّهُ ۖ وَٱللَّهُ خَيْرُ ٱلْمَـٰكِرِينَ','Wa makaroo wa makaral laahu wallaahu khairul maakireen',54,'3:54',6,23,46,1,0,57,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(348,3,'إِذْ قَالَ ٱللَّهُ يَـٰعِيسَىٰٓ إِنِّى مُتَوَفِّيكَ وَرَافِعُكَ إِلَىَّ وَمُطَهِّرُكَ مِنَ ٱلَّذِينَ كَفَرُوا۟ وَجَاعِلُ ٱلَّذِينَ ٱتَّبَعُوكَ فَوْقَ ٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ ۖ ثُمَّ إِلَىَّ مَرْجِعُكُمْ فَأَحْكُمُ بَيْنَكُمْ فِيمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ','Iz qaalal laahu yaa \'Eesaaa innee mutawaffeeka wa raafi\'uka ilaiya wa mutah hiruka minal lazeena kafaroo wa jaa\'ilul lazeenattaba ooka fawqal lazeena kafarooo ilaa Yawmil Qiyaamati summa ilaiya marji\'ukum fa ahkumu bainakum feemaa kuntum feehi takhtaliifoon',55,'3:55',6,23,47,1,0,57,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(349,3,'فَأَمَّا ٱلَّذِينَ كَفَرُوا۟ فَأُعَذِّبُهُمْ عَذَابًا شَدِيدًا فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَمَا لَهُم مِّن نَّـٰصِرِينَ','Fa ammal lazeena kafaroo fa u\'az zibuhum \'azaaban shadeedan fiddunyaa wal Aakhirati wa maa lahum min naasireen',56,'3:56',6,23,47,1,0,57,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(350,3,'وَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَيُوَفِّيهِمْ أُجُورَهُمْ ۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّـٰلِمِينَ','Wa ammal lazeena aamanoo wa \'amilus saalihaati fa yuwaffeehim ujoorahum; wallaahu laa yuhibbuz zaalimeen',57,'3:57',6,23,47,1,0,57,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(351,3,'ذَٰلِكَ نَتْلُوهُ عَلَيْكَ مِنَ ٱلْـَٔايَـٰتِ وَٱلذِّكْرِ ٱلْحَكِيمِ','Zaalika natloohu \'alaika minal Aayaati wa Zikril Hakeem',58,'3:58',6,23,47,1,0,57,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(352,3,'إِنَّ مَثَلَ عِيسَىٰ عِندَ ٱللَّهِ كَمَثَلِ ءَادَمَ ۖ خَلَقَهُۥ مِن تُرَابٍ ثُمَّ قَالَ لَهُۥ كُن فَيَكُونُ','Inna masala \'Eesaa \'indal laahi kamasali Aadama khalaqahoo min turaabin summa qaala lahoo kun fayakoon',59,'3:59',6,23,47,1,0,57,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(353,3,'ٱلْحَقُّ مِن رَّبِّكَ فَلَا تَكُن مِّنَ ٱلْمُمْتَرِينَ','Alhaqqu mir Rabbika falaa takum minal mumtareen',60,'3:60',6,23,47,1,0,57,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(354,3,'فَمَنْ حَآجَّكَ فِيهِ مِنۢ بَعْدِ مَا جَآءَكَ مِنَ ٱلْعِلْمِ فَقُلْ تَعَالَوْا۟ نَدْعُ أَبْنَآءَنَا وَأَبْنَآءَكُمْ وَنِسَآءَنَا وَنِسَآءَكُمْ وَأَنفُسَنَا وَأَنفُسَكُمْ ثُمَّ نَبْتَهِلْ فَنَجْعَل لَّعْنَتَ ٱللَّهِ عَلَى ٱلْكَـٰذِبِينَ','Faman haaajjaka feehi mim ba\'di maa jaaa\'aka minal \'ilmi faqul ta\'aalaw nad\'u abnaaa\'anaa wa abnaaa\'akum wa nisaaa\'anaa wa nisaaa\'akum wa anfusanaa wa anfusakum summa nabtahil fanaj\'al la\'natal laahi \'alal kaazibeen',61,'3:61',6,23,47,1,0,57,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(355,3,'إِنَّ هَـٰذَا لَهُوَ ٱلْقَصَصُ ٱلْحَقُّ ۚ وَمَا مِنْ إِلَـٰهٍ إِلَّا ٱللَّهُ ۚ وَإِنَّ ٱللَّهَ لَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ','Innaa haazaa lahuwal qasasul haqq; wa maa min ilaahin illal laah; wa innal laahaa la Huwal \'Azeezul Hakeem',62,'3:62',6,23,47,1,0,58,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(356,3,'فَإِن تَوَلَّوْا۟ فَإِنَّ ٱللَّهَ عَلِيمٌۢ بِٱلْمُفْسِدِينَ','Fa in tawallaw fa innal laaha\'aleemun bil mufsideen',63,'3:63',6,23,47,1,0,58,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(357,3,'قُلْ يَـٰٓأَهْلَ ٱلْكِتَـٰبِ تَعَالَوْا۟ إِلَىٰ كَلِمَةٍ سَوَآءٍۭ بَيْنَنَا وَبَيْنَكُمْ أَلَّا نَعْبُدَ إِلَّا ٱللَّهَ وَلَا نُشْرِكَ بِهِۦ شَيْـًٔا وَلَا يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَابًا مِّن دُونِ ٱللَّهِ ۚ فَإِن تَوَلَّوْا۟ فَقُولُوا۟ ٱشْهَدُوا۟ بِأَنَّا مُسْلِمُونَ','Qul yaa Ahlal Kitaabi ta\'aalaw ilaa Kalimatin sawaaa\'im bainanaa wa bainakum allaa na\'buda illal laaha wa laa nushrika bihee shai\'anw wa laa yattakhiza ba\'dunaa ba\'dan arbaabam min doonil laah; fa in tawallaw faqoolush hadoo bi annaa muslimoon',64,'3:64',6,23,48,1,0,58,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(358,3,'يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لِمَ تُحَآجُّونَ فِىٓ إِبْرَٰهِيمَ وَمَآ أُنزِلَتِ ٱلتَّوْرَىٰةُ وَٱلْإِنجِيلُ إِلَّا مِنۢ بَعْدِهِۦٓ ۚ أَفَلَا تَعْقِلُونَ','Yaaa Ahlal Kitaabi limaa tuhaaajjoona feee Ibraaheema wa maaa unzilatit Tawraatu wal Injeelu illaa mim ba\'dih; afala ta\'qiloon',65,'3:65',6,23,48,1,0,58,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(359,3,'هَـٰٓأَنتُمْ هَـٰٓؤُلَآءِ حَـٰجَجْتُمْ فِيمَا لَكُم بِهِۦ عِلْمٌ فَلِمَ تُحَآجُّونَ فِيمَا لَيْسَ لَكُم بِهِۦ عِلْمٌ ۚ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ','Haaa antum haaa\'ulaaa\'i baajajtum feemaa lakum bihee \'ilmun falima tuhaaajjoonaa feemaa laisa lakum bihee \'ilm; wallaahu ya\'lamu wa antum laa ta\'lamoon',66,'3:66',6,23,48,1,0,58,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(360,3,'مَا كَانَ إِبْرَٰهِيمُ يَهُودِيًّا وَلَا نَصْرَانِيًّا وَلَـٰكِن كَانَ حَنِيفًا مُّسْلِمًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ','Maa kaana Ibraaheemu Yahoodiyyanw wa laa Nasraa niyyanw wa laakin kaana Haneefam Muslimanw wa maa kaana minal mushrikeen',67,'3:67',6,23,48,1,0,58,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(361,3,'إِنَّ أَوْلَى ٱلنَّاسِ بِإِبْرَٰهِيمَ لَلَّذِينَ ٱتَّبَعُوهُ وَهَـٰذَا ٱلنَّبِىُّ وَٱلَّذِينَ ءَامَنُوا۟ ۗ وَٱللَّهُ وَلِىُّ ٱلْمُؤْمِنِينَ','Innaa awlan naasi bi Ibraaheema lallazeenat taba \'oohu wa haazan nabiyyu wallazeena aamanoo; wallaahu waliyyul mu\'mineen',68,'3:68',6,23,48,1,0,58,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(362,3,'وَدَّت طَّآئِفَةٌ مِّنْ أَهْلِ ٱلْكِتَـٰبِ لَوْ يُضِلُّونَكُمْ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ','Waddat taaa\'ifatum min Ahlil Kitaabi law yudil loonakum wa maa yudilloona illaaa anfusahum wa maa yash\'uroon',69,'3:69',6,23,48,1,0,58,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(363,3,'يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لِمَ تَكْفُرُونَ بِـَٔايَـٰتِ ٱللَّهِ وَأَنتُمْ تَشْهَدُونَ','Yaaa Ahlal Kitaabi lima takfuroona bi Aayaatil laahi wan antum tashadoon',70,'3:70',6,23,48,1,0,58,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(364,3,'يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لِمَ تَلْبِسُونَ ٱلْحَقَّ بِٱلْبَـٰطِلِ وَتَكْتُمُونَ ٱلْحَقَّ وَأَنتُمْ تَعْلَمُونَ','Yaaa Ahalal Kitaabi lima talbisoonal haqqa bilbaatili wa taktumoonal haqqa wa antum ta\'lamoon',71,'3:71',6,23,48,1,0,59,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(365,3,'وَقَالَت طَّآئِفَةٌ مِّنْ أَهْلِ ٱلْكِتَـٰبِ ءَامِنُوا۟ بِٱلَّذِىٓ أُنزِلَ عَلَى ٱلَّذِينَ ءَامَنُوا۟ وَجْهَ ٱلنَّهَارِ وَٱكْفُرُوٓا۟ ءَاخِرَهُۥ لَعَلَّهُمْ يَرْجِعُونَ','Wa qaalat taaa\'ifatum min Ahlil Kitaabi aaminoo billazeee unzila \'alal lazeena aamanoo wajhan nahaari wakfurooo aakhirahoo la\'alla hum yarji\'oon',72,'3:72',6,23,49,1,0,59,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(366,3,'وَلَا تُؤْمِنُوٓا۟ إِلَّا لِمَن تَبِعَ دِينَكُمْ قُلْ إِنَّ ٱلْهُدَىٰ هُدَى ٱللَّهِ أَن يُؤْتَىٰٓ أَحَدٌ مِّثْلَ مَآ أُوتِيتُمْ أَوْ يُحَآجُّوكُمْ عِندَ رَبِّكُمْ ۗ قُلْ إِنَّ ٱلْفَضْلَ بِيَدِ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ','Wa laa tu\'minooo illaa liman tabi\'a deenakum qul innal hudaa hudal laahi ai yu\'taaa ahadum misla maaa ooteetum aw yuhaaajjookum \'inda Rabbikum, qul innal fadla biyadil laah; yu\'teehi mai yashaaa\'; wallaahu Waasi\'un \'Aleem',73,'3:73',6,23,49,1,0,59,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(367,3,'يَخْتَصُّ بِرَحْمَتِهِۦ مَن يَشَآءُ ۗ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ','Yakhtassu birahmatihee mai yashaaa\'; wallaahu zulfadil \'azeem',74,'3:74',6,23,49,1,0,59,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(368,3,'۞ وَمِنْ أَهْلِ ٱلْكِتَـٰبِ مَنْ إِن تَأْمَنْهُ بِقِنطَارٍ يُؤَدِّهِۦٓ إِلَيْكَ وَمِنْهُم مَّنْ إِن تَأْمَنْهُ بِدِينَارٍ لَّا يُؤَدِّهِۦٓ إِلَيْكَ إِلَّا مَا دُمْتَ عَلَيْهِ قَآئِمًا ۗ ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لَيْسَ عَلَيْنَا فِى ٱلْأُمِّيِّـۧنَ سَبِيلٌ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُمْ يَعْلَمُونَ','Wa min Ahlil Kitaabi man in taamanhu biqintaariny yu\'addihee ilaika wa minhum man in taamanhu bideenaaril laa yu\'addiheee ilaika illaa maa dumta \'alaihi qaaa\' imaa; zaalika biannahum qaaloo laisa \'alainaa fil ummiyyeena sabeelunw wa yaqooloona \'alal laahil kaziba wa hum ya\'lamoon',75,'3:75',6,24,49,1,0,59,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(369,3,'بَلَىٰ مَنْ أَوْفَىٰ بِعَهْدِهِۦ وَٱتَّقَىٰ فَإِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ','Balaa man awfaa bi\'ahdihee wattaqaa fainnal laaha yuhibbul muttaqeen',76,'3:76',6,24,49,1,0,59,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(370,3,'إِنَّ ٱلَّذِينَ يَشْتَرُونَ بِعَهْدِ ٱللَّهِ وَأَيْمَـٰنِهِمْ ثَمَنًا قَلِيلًا أُو۟لَـٰٓئِكَ لَا خَلَـٰقَ لَهُمْ فِى ٱلْـَٔاخِرَةِ وَلَا يُكَلِّمُهُمُ ٱللَّهُ وَلَا يَنظُرُ إِلَيْهِمْ يَوْمَ ٱلْقِيَـٰمَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ','Innal lazeena yashtaroona bi\'ahdil laahi wa aymaanihim samanan qaleelan ulaaa\'ika laa khalaaqa lahum fil Aakhirati wa laa yukallimuhumul laahu wa laa yanzuru ilaihim Yawmal Qiyaamati wa laa yuzakkeehim wa lahum \'azabun \'aleem',77,'3:77',6,24,49,1,0,59,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(371,3,'وَإِنَّ مِنْهُمْ لَفَرِيقًا يَلْوُۥنَ أَلْسِنَتَهُم بِٱلْكِتَـٰبِ لِتَحْسَبُوهُ مِنَ ٱلْكِتَـٰبِ وَمَا هُوَ مِنَ ٱلْكِتَـٰبِ وَيَقُولُونَ هُوَ مِنْ عِندِ ٱللَّهِ وَمَا هُوَ مِنْ عِندِ ٱللَّهِ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُمْ يَعْلَمُونَ','Wa inna minhum lafaree qany yalwoona alsinatahum bil Kitaabi litahsaboohu minal Kitaab, wa maa huwa minal Kitaabi wa yaqooloon huwa min \'indillaahi wa maa huwa min \'indillaahi wa yaqooloona \'alal laahil kaziba wa hum ya\'lamoon',78,'3:78',6,24,49,1,0,60,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(372,3,'مَا كَانَ لِبَشَرٍ أَن يُؤْتِيَهُ ٱللَّهُ ٱلْكِتَـٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ ثُمَّ يَقُولَ لِلنَّاسِ كُونُوا۟ عِبَادًا لِّى مِن دُونِ ٱللَّهِ وَلَـٰكِن كُونُوا۟ رَبَّـٰنِيِّـۧنَ بِمَا كُنتُمْ تُعَلِّمُونَ ٱلْكِتَـٰبَ وَبِمَا كُنتُمْ تَدْرُسُونَ','Maa kaana libasharin ai yu\'tiyahul laahul Kitaaba walhukma wan Nubuwwata summa yaqoola linnaasi koonoo \'ibaadal lee min doonil laahi wa laakin koonoo rabbaaniy yeena bimaa kuntum tu\'allimoonal Kitaaba wa bimaa kuntum tadrusoon',79,'3:79',6,24,49,1,0,60,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(373,3,'وَلَا يَأْمُرَكُمْ أَن تَتَّخِذُوا۟ ٱلْمَلَـٰٓئِكَةَ وَٱلنَّبِيِّـۧنَ أَرْبَابًا ۗ أَيَأْمُرُكُم بِٱلْكُفْرِ بَعْدَ إِذْ أَنتُم مُّسْلِمُونَ','Wa laa yaamurakum an tattakhizul malaaa \'ikata wan Nabiyyeena arbaabaa; a yaamurukum bilkufri ba\'da iz antum muslimoon',80,'3:80',6,24,49,1,0,60,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(374,3,'وَإِذْ أَخَذَ ٱللَّهُ مِيثَـٰقَ ٱلنَّبِيِّـۧنَ لَمَآ ءَاتَيْتُكُم مِّن كِتَـٰبٍ وَحِكْمَةٍ ثُمَّ جَآءَكُمْ رَسُولٌ مُّصَدِّقٌ لِّمَا مَعَكُمْ لَتُؤْمِنُنَّ بِهِۦ وَلَتَنصُرُنَّهُۥ ۚ قَالَ ءَأَقْرَرْتُمْ وَأَخَذْتُمْ عَلَىٰ ذَٰلِكُمْ إِصْرِى ۖ قَالُوٓا۟ أَقْرَرْنَا ۚ قَالَ فَٱشْهَدُوا۟ وَأَنَا۠ مَعَكُم مِّنَ ٱلشَّـٰهِدِينَ','Wa iz akhazal laahu meesaaqan Nabiyyeena lamaaa aataitukum min Kitaabinw wa Hikmatin summa jaaa\'akum Rasoolum musaddiqul limaa ma\'akum latu\'minunna bihee wa latansurunnah; qaala \'aaqrartum wa akhaztum alaa zaalikum isree qaalooo aqrarnaa; qaala fashhadoo wa ana ma\'akum minash shaahideen',81,'3:81',6,24,50,1,0,60,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(375,3,'فَمَن تَوَلَّىٰ بَعْدَ ذَٰلِكَ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْفَـٰسِقُونَ','Faman tawallaa ba\'da zaalika fa ulaaa\'ika humul faasiqoon',82,'3:82',6,24,50,1,0,60,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(376,3,'أَفَغَيْرَ دِينِ ٱللَّهِ يَبْغُونَ وَلَهُۥٓ أَسْلَمَ مَن فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ طَوْعًا وَكَرْهًا وَإِلَيْهِ يُرْجَعُونَ','Afaghaira deenil laahi yabghoona wa lahooo aslama man fis samaawaati wal ardi taw\'anw wa karhanw wa ilaihi yurja\'oon',83,'3:83',6,24,50,1,0,60,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(377,3,'قُلْ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ عَلَيْنَا وَمَآ أُنزِلَ عَلَىٰٓ إِبْرَٰهِيمَ وَإِسْمَـٰعِيلَ وَإِسْحَـٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَمَآ أُوتِىَ مُوسَىٰ وَعِيسَىٰ وَٱلنَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّنْهُمْ وَنَحْنُ لَهُۥ مُسْلِمُونَ','Qul aamannaa billaahi wa maaa unzila \'alainaa wa maaa unzila \'alaaa Ibraaheema wa Ismaa\'eela wa Ishaaqa wa Ya\'qooba wal Asbaati wa maaa ootiya Moosaa wa \'Eesaa wan Nabiyyoona mir Rabbihim laa nufarriqu baina ahadim minhum wa nahnu lahoo muslimoon',84,'3:84',6,24,50,1,0,61,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(378,3,'وَمَن يَبْتَغِ غَيْرَ ٱلْإِسْلَـٰمِ دِينًا فَلَن يُقْبَلَ مِنْهُ وَهُوَ فِى ٱلْـَٔاخِرَةِ مِنَ ٱلْخَـٰسِرِينَ','Wa mai yabtaghi ghairal Islaami deenan falany yuqbala minhu wa huwa fil Aakhirati minal khaasireen',85,'3:85',6,24,50,1,0,61,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(379,3,'كَيْفَ يَهْدِى ٱللَّهُ قَوْمًا كَفَرُوا۟ بَعْدَ إِيمَـٰنِهِمْ وَشَهِدُوٓا۟ أَنَّ ٱلرَّسُولَ حَقٌّ وَجَآءَهُمُ ٱلْبَيِّنَـٰتُ ۚ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ','Kaifa yahdil laahu qawman kafaroo ba\'da eemaanihim wa shahidooo annar Rasoola haqqunw wa jaaa\'ahumul baiyinaat; wallaahu laa yahdil qawmaz zaalimeen',86,'3:86',6,24,50,1,0,61,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(380,3,'أُو۟لَـٰٓئِكَ جَزَآؤُهُمْ أَنَّ عَلَيْهِمْ لَعْنَةَ ٱللَّهِ وَٱلْمَلَـٰٓئِكَةِ وَٱلنَّاسِ أَجْمَعِينَ','Ulaaa\'ika jazaaa\'uhum anna \'alaihim la\'natal laahi walmalaaa\'ikati wannaasi ajma\'een',87,'3:87',6,24,50,1,0,61,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(381,3,'خَـٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنظَرُونَ','Khaalideena feehaa laa yukhaffafu \'anhumul \'azaabu wa laa hum yunzaroon',88,'3:88',6,24,50,1,0,61,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(382,3,'إِلَّا ٱلَّذِينَ تَابُوا۟ مِنۢ بَعْدِ ذَٰلِكَ وَأَصْلَحُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ','Illal lazeena taaboo mim ba\'di zaalika wa aslahoo fa innal laaha Ghafoorur Raheem',89,'3:89',6,24,50,1,0,61,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(383,3,'إِنَّ ٱلَّذِينَ كَفَرُوا۟ بَعْدَ إِيمَـٰنِهِمْ ثُمَّ ٱزْدَادُوا۟ كُفْرًا لَّن تُقْبَلَ تَوْبَتُهُمْ وَأُو۟لَـٰٓئِكَ هُمُ ٱلضَّآلُّونَ','Innal lazeena kafaroo ba\'da eemaanihim summaz daadoo kufral lan tuqbala tawbatuhum wa ulaaa\'ika humud daaalloon',90,'3:90',6,24,50,1,0,61,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(384,3,'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَمَاتُوا۟ وَهُمْ كُفَّارٌ فَلَن يُقْبَلَ مِنْ أَحَدِهِم مِّلْءُ ٱلْأَرْضِ ذَهَبًا وَلَوِ ٱفْتَدَىٰ بِهِۦٓ ۗ أُو۟لَـٰٓئِكَ لَهُمْ عَذَابٌ أَلِيمٌ وَمَا لَهُم مِّن نَّـٰصِرِينَ','Innal lazeena kafaroo wa maatoo wa hum kuffaarun falany yuqbala min ahadihim mil\'ul ardi zahabanw wa lawiftadaa bih; ulaaa \'ika lahum \'azaabun aleemunw wa maa lahum min naasireen',91,'3:91',6,24,50,1,0,61,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(385,3,'لَن تَنَالُوا۟ ٱلْبِرَّ حَتَّىٰ تُنفِقُوا۟ مِمَّا تُحِبُّونَ ۚ وَمَا تُنفِقُوا۟ مِن شَىْءٍ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ','Lan tanaalul birra hattaa tunfiqoo mimmaa tuhibboon; wa maa tunfiqoo min shai\'in fa innal laaha bihee \'Aleem',92,'3:92',6,24,51,1,0,62,3,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(386,3,'۞ كُلُّ ٱلطَّعَامِ كَانَ حِلًّا لِّبَنِىٓ إِسْرَٰٓءِيلَ إِلَّا مَا حَرَّمَ إِسْرَٰٓءِيلُ عَلَىٰ نَفْسِهِۦ مِن قَبْلِ أَن تُنَزَّلَ ٱلتَّوْرَىٰةُ ۗ قُلْ فَأْتُوا۟ بِٱلتَّوْرَىٰةِ فَٱتْلُوهَآ إِن كُنتُمْ صَـٰدِقِينَ','Kullut ta\'aami kaana hillal li Baneee Israaa\'eela illaa maa harrama Israaa\'eelu \'alaa nafsihee min qabli an tunzzalat Tawraah; qul faatoo bit Tawraati fatloohaaa in kuntum saadiqeen',93,'3:93',7,25,51,1,0,62,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(387,3,'فَمَنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ ٱلْكَذِبَ مِنۢ بَعْدِ ذَٰلِكَ فَأُو۟لَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ','Famanif taraa \'alal laahilkaziba mim ba\'di zaalika fa ulaaa\'ika humuz zaalimoon',94,'3:94',7,25,51,1,0,62,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(388,3,'قُلْ صَدَقَ ٱللَّهُ ۗ فَٱتَّبِعُوا۟ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ','Qul sadaqal laah; fattabi\'oo Millata Ibraaheema Haneefanw wa maa kaana minal mush rikeen',95,'3:95',7,25,51,1,0,62,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(389,3,'إِنَّ أَوَّلَ بَيْتٍ وُضِعَ لِلنَّاسِ لَلَّذِى بِبَكَّةَ مُبَارَكًا وَهُدًى لِّلْعَـٰلَمِينَ','Inna awwala Baitinw wudi\'a linnaasi lallazee bi Bakkata mubaarakanw wa hudal lil \'aalameen',96,'3:96',7,25,51,1,0,62,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(390,3,'فِيهِ ءَايَـٰتٌۢ بَيِّنَـٰتٌ مَّقَامُ إِبْرَٰهِيمَ ۖ وَمَن دَخَلَهُۥ كَانَ ءَامِنًا ۗ وَلِلَّهِ عَلَى ٱلنَّاسِ حِجُّ ٱلْبَيْتِ مَنِ ٱسْتَطَاعَ إِلَيْهِ سَبِيلًا ۚ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِىٌّ عَنِ ٱلْعَـٰلَمِينَ','Feehi Aayaatum baiyinaatum Maqaamu Ibraaheema wa man dakhalahoo kaana aaminaa; wa lillaahi \'alan naasi Hijjul Baiti manis tataa\'a ilaihi sabeelaa; wa man kafara fa innal laaha ghaniyyun \'anil \'aalameen',97,'3:97',7,25,51,1,0,62,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(391,3,'قُلْ يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لِمَ تَكْفُرُونَ بِـَٔايَـٰتِ ٱللَّهِ وَٱللَّهُ شَهِيدٌ عَلَىٰ مَا تَعْمَلُونَ','Qul yaaa Ahlal Kitaabi lima takfuroona bi Aayaatillaahi wallaahu shaheedun \'alaa maa ta\'maloon',98,'3:98',7,25,51,1,0,62,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(392,3,'قُلْ يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لِمَ تَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنْ ءَامَنَ تَبْغُونَهَا عِوَجًا وَأَنتُمْ شُهَدَآءُ ۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعْمَلُونَ','Qul yaaa Ahlal Kitaabi lima tusuddoona \'an sabeelil laahi man aamana tabghoonahaa \'iwajanw wa antum shuhadaaa\'; wa mallaahu bighaafilin \'ammaa ta\'maloon',99,'3:99',7,25,51,1,0,62,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(393,3,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تُطِيعُوا۟ فَرِيقًا مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ يَرُدُّوكُم بَعْدَ إِيمَـٰنِكُمْ كَـٰفِرِينَ','Yaaa ayyuhal lazeena aamanoo in tutee\'oo fareeqam minal lazeena ootul Kitaaba yaruddookum ba\'da eemaanikum kaafireen',100,'3:100',7,25,51,1,0,62,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(394,3,'وَكَيْفَ تَكْفُرُونَ وَأَنتُمْ تُتْلَىٰ عَلَيْكُمْ ءَايَـٰتُ ٱللَّهِ وَفِيكُمْ رَسُولُهُۥ ۗ وَمَن يَعْتَصِم بِٱللَّهِ فَقَدْ هُدِىَ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ','Wa kaifa takfuroona wa antum tutlaa \'alaikum Aayaatul laahi wa feekum Rasooluh; wa mai ya\'tasim baillaahi faqad hudiya ilaa Siraatim Mustaqeem',101,'3:101',7,25,51,1,0,63,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(395,3,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ حَقَّ تُقَاتِهِۦ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ','Yaaa ayyuhal lazeena aamanut taqul laaha haqqa tuqaatihee wa laa tamoontunna illaa wa antum muslimoon',102,'3:102',7,25,52,1,0,63,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(396,3,'وَٱعْتَصِمُوا۟ بِحَبْلِ ٱللَّهِ جَمِيعًا وَلَا تَفَرَّقُوا۟ ۚ وَٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ إِذْ كُنتُمْ أَعْدَآءً فَأَلَّفَ بَيْنَ قُلُوبِكُمْ فَأَصْبَحْتُم بِنِعْمَتِهِۦٓ إِخْوَٰنًا وَكُنتُمْ عَلَىٰ شَفَا حُفْرَةٍ مِّنَ ٱلنَّارِ فَأَنقَذَكُم مِّنْهَا ۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَـٰتِهِۦ لَعَلَّكُمْ تَهْتَدُونَ','Wa\'tasimoo bi Hablil laahi jamee\'anw wa laa tafarraqoo; wazkuroo ni\'matal laahi alaikum iz kuntum a\'daaa\'an fa allafa baina quloobikum fa asbah tum bini\'matiheee ikhwaananw wa kuntum \'alaa shafaa hufratim minan Naari fa anqazakum minhaa; kazaalika yubaiyinul laahu lakum aayaatihee la\'allakum tahtadoon',103,'3:103',7,25,52,1,0,63,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(397,3,'وَلْتَكُن مِّنكُمْ أُمَّةٌ يَدْعُونَ إِلَى ٱلْخَيْرِ وَيَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ ۚ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ','Waltakum minkum ummatuny yad\'oona ilal khairi wa yaamuroona bilma \'roofi wa yanhawna \'anil munkar; wa ulaaa\'ika humul muflihoon',104,'3:104',7,25,52,1,0,63,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(398,3,'وَلَا تَكُونُوا۟ كَٱلَّذِينَ تَفَرَّقُوا۟ وَٱخْتَلَفُوا۟ مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْبَيِّنَـٰتُ ۚ وَأُو۟لَـٰٓئِكَ لَهُمْ عَذَابٌ عَظِيمٌ','Wa laa takoonoo kallazeena tafarraqoo wakhtalafoo mim ba\'di maa jaaa\'ahumul baiyinaat; wa ulaaa\'ika lahum \'azaabun \'azeem',105,'3:105',7,25,52,1,0,63,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(399,3,'يَوْمَ تَبْيَضُّ وُجُوهٌ وَتَسْوَدُّ وُجُوهٌ ۚ فَأَمَّا ٱلَّذِينَ ٱسْوَدَّتْ وُجُوهُهُمْ أَكَفَرْتُم بَعْدَ إِيمَـٰنِكُمْ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ','Yawma tabyaddu wujoohunw wa taswaddu wujooh; faammal lazeenas waddat wujoohum akafartum ba\'da eemaanikum fazooqul \'azaaba bimaa kuntum takfuroon',106,'3:106',7,25,52,1,0,63,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(400,3,'وَأَمَّا ٱلَّذِينَ ٱبْيَضَّتْ وُجُوهُهُمْ فَفِى رَحْمَةِ ٱللَّهِ هُمْ فِيهَا خَـٰلِدُونَ','Wa ammal lazeenabyadd at wujoohuhum fafee rahmatil laahi hum feehaa khaalidoon',107,'3:107',7,25,52,1,0,63,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(401,3,'تِلْكَ ءَايَـٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ ۗ وَمَا ٱللَّهُ يُرِيدُ ظُلْمًا لِّلْعَـٰلَمِينَ','Tilka Aayaatul laahi natloohaa \'alaika bilhaqq; wa mal laahu yureedu zulmallil \'aalameen',108,'3:108',7,25,52,1,0,63,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(402,3,'وَلِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ','Wa lillaahi maa fissamaawaati wa maa fil ard; wa ilal laahi turja;ul umoor',109,'3:109',7,25,52,1,0,64,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(403,3,'كُنتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِٱلْمَعْرُوفِ وَتَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَتُؤْمِنُونَ بِٱللَّهِ ۗ وَلَوْ ءَامَنَ أَهْلُ ٱلْكِتَـٰبِ لَكَانَ خَيْرًا لَّهُم ۚ مِّنْهُمُ ٱلْمُؤْمِنُونَ وَأَكْثَرُهُمُ ٱلْفَـٰسِقُونَ','Kuntum khaira ummatin ukhrijat linnaasi taamuroona bilma\'roofi wa tanhawna \'anil munkari wa tu\'minoona billaah; wa law aamana Ahlul Kitaabi lakaana khairal lahum minhumul mu\'minoona wa aksaruhumul faasiqoon',110,'3:110',7,25,53,1,0,64,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(404,3,'لَن يَضُرُّوكُمْ إِلَّآ أَذًى ۖ وَإِن يُقَـٰتِلُوكُمْ يُوَلُّوكُمُ ٱلْأَدْبَارَ ثُمَّ لَا يُنصَرُونَ','Lai yadurrookum \'illaaa azanw wa ai yuqaatilookum yuwallookumul adbaara summa laa yunsaroon',111,'3:111',7,25,53,1,0,64,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(405,3,'ضُرِبَتْ عَلَيْهِمُ ٱلذِّلَّةُ أَيْنَ مَا ثُقِفُوٓا۟ إِلَّا بِحَبْلٍ مِّنَ ٱللَّهِ وَحَبْلٍ مِّنَ ٱلنَّاسِ وَبَآءُو بِغَضَبٍ مِّنَ ٱللَّهِ وَضُرِبَتْ عَلَيْهِمُ ٱلْمَسْكَنَةُ ۚ ذَٰلِكَ بِأَنَّهُمْ كَانُوا۟ يَكْفُرُونَ بِـَٔايَـٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّ ۚ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ','Duribat \'alaihimuz zillatu aina maa suqifooo illaa bihablim minal laahi wa hablim minan naasi wa baaa\'oo bighadabim minallaahi wa duribat \'alaihimul maskanah; zaalika bi-annahum kaanoo yakfuroona bi Aayaatil laahi wa yaqtuloonal Ambiyaaa\'a bighairi haqq; zaalika bimaa \'asaw wa kaanoo ya\'tadoon',112,'3:112',7,25,53,1,0,64,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(406,3,'۞ لَيْسُوا۟ سَوَآءً ۗ مِّنْ أَهْلِ ٱلْكِتَـٰبِ أُمَّةٌ قَآئِمَةٌ يَتْلُونَ ءَايَـٰتِ ٱللَّهِ ءَانَآءَ ٱلَّيْلِ وَهُمْ يَسْجُدُونَ','Laisoo sawaaa\'a; min Ahlil Kitaabi ummatun qaaa\'imatuny yatloona Aayaatil laahi aanaaa\'al laili wa hum yasjudoon',113,'3:113',7,26,53,1,0,64,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(407,3,'يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَيَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَيُسَـٰرِعُونَ فِى ٱلْخَيْرَٰتِ وَأُو۟لَـٰٓئِكَ مِنَ ٱلصَّـٰلِحِينَ','Yu\'minoona billaahi wal Yawmil Aakhiri wa yaa muroona bilma\'roofi wa yanhawna \'anil munkari wa yusaari\'oona fil khairaati wa ulaa\'ika minas saaliheen',114,'3:114',7,26,53,1,0,64,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(408,3,'وَمَا يَفْعَلُوا۟ مِنْ خَيْرٍ فَلَن يُكْفَرُوهُ ۗ وَٱللَّهُ عَلِيمٌۢ بِٱلْمُتَّقِينَ','Wa maa yaf\'aloo min khairin falai yukfarooh; wallaahu \'aleemun bilmuttaqeen',115,'3:115',7,26,53,1,0,64,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(409,3,'إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَـٰدُهُم مِّنَ ٱللَّهِ شَيْـًٔا ۖ وَأُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۚ هُمْ فِيهَا خَـٰلِدُونَ','Innal lazeena kafaroo lan tughniya \'anhum amwaalum wa laaa awlaaduhum minal laahi shai anw wa ulaaa\'ika Ashaabun Naar; hum feehaa khaalidoon',116,'3:116',7,26,53,1,0,65,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(410,3,'مَثَلُ مَا يُنفِقُونَ فِى هَـٰذِهِ ٱلْحَيَوٰةِ ٱلدُّنْيَا كَمَثَلِ رِيحٍ فِيهَا صِرٌّ أَصَابَتْ حَرْثَ قَوْمٍ ظَلَمُوٓا۟ أَنفُسَهُمْ فَأَهْلَكَتْهُ ۚ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَـٰكِنْ أَنفُسَهُمْ يَظْلِمُونَ','Masalu maa yunfiqoona fee haazihil hayaatid dunyaa kamasali reehin feehaa sirrun as aabat harsa qawmin zalamooo anfusahum fa ahlakath; wa maa zalamahumul laahu wa laakin anfusahum yazlimoon',117,'3:117',7,26,53,1,0,65,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(411,3,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ بِطَانَةً مِّن دُونِكُمْ لَا يَأْلُونَكُمْ خَبَالًا وَدُّوا۟ مَا عَنِتُّمْ قَدْ بَدَتِ ٱلْبَغْضَآءُ مِنْ أَفْوَٰهِهِمْ وَمَا تُخْفِى صُدُورُهُمْ أَكْبَرُ ۚ قَدْ بَيَّنَّا لَكُمُ ٱلْـَٔايَـٰتِ ۖ إِن كُنتُمْ تَعْقِلُونَ','Yaaa ayyuhal lazeena aamanoo laa tattakhizoo bitaanatam min doonikum laa yaaloonakum khabaalanw waddoo maa \'anittum qad badatil baghdaaa\'u min afwaahihim; wa maa tukhfee sudooruhum akbar; qad baiyannaa lakumul Aayaati in kuntum ta\'qiloon',118,'3:118',7,26,53,1,0,65,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(412,3,'هَـٰٓأَنتُمْ أُو۟لَآءِ تُحِبُّونَهُمْ وَلَا يُحِبُّونَكُمْ وَتُؤْمِنُونَ بِٱلْكِتَـٰبِ كُلِّهِۦ وَإِذَا لَقُوكُمْ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَوْا۟ عَضُّوا۟ عَلَيْكُمُ ٱلْأَنَامِلَ مِنَ ٱلْغَيْظِ ۚ قُلْ مُوتُوا۟ بِغَيْظِكُمْ ۗ إِنَّ ٱللَّهَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ','Haaa antum ulaaa\'i tuhibboonahum wa laa yuhibboonakum wa tu\'minoona bil kitaabi kullihee wa izaa laqookum qaalooo aamannaa wa izaa khalaw \'addoo \'alaikumul anaamila minal ghaiz; qul mootoo bighai zikum; innal laaha \'aleemum bizaatis sudoor',119,'3:119',7,26,53,1,0,65,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(413,3,'إِن تَمْسَسْكُمْ حَسَنَةٌ تَسُؤْهُمْ وَإِن تُصِبْكُمْ سَيِّئَةٌ يَفْرَحُوا۟ بِهَا ۖ وَإِن تَصْبِرُوا۟ وَتَتَّقُوا۟ لَا يَضُرُّكُمْ كَيْدُهُمْ شَيْـًٔا ۗ إِنَّ ٱللَّهَ بِمَا يَعْمَلُونَ مُحِيطٌ','In tamsaskum hasanatun tasu\'hum wa in tusibkum saiyi\'atuny yafrahoo bihaa wa in tasbiroo wa tattaqoo laa yad urrukum kaiduhum shai\'aa; innal laaha bimaa ya\'maloona muheet',120,'3:120',7,26,53,1,0,65,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(414,3,'وَإِذْ غَدَوْتَ مِنْ أَهْلِكَ تُبَوِّئُ ٱلْمُؤْمِنِينَ مَقَـٰعِدَ لِلْقِتَالِ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ','Wa iz ghadawta min ahlika tubawwi\'ul mu\'mineena maqaa\'ida lilqitaal; wallaahu samee\'un \'aleem',121,'3:121',7,26,54,1,0,65,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(415,3,'إِذْ هَمَّت طَّآئِفَتَانِ مِنكُمْ أَن تَفْشَلَا وَٱللَّهُ وَلِيُّهُمَا ۗ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ','Iz hammat taaa\'ifataani minkum an tafshalaa wallaahu waliyyuhumaa; wa \'alal laahi falyatawakkalil mu\'minoon',122,'3:122',7,26,54,1,0,66,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(416,3,'وَلَقَدْ نَصَرَكُمُ ٱللَّهُ بِبَدْرٍ وَأَنتُمْ أَذِلَّةٌ ۖ فَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تَشْكُرُونَ','Wa laqad nasarakumul laahu bi-Badrinw wa antum azillatun fattaqul laaha la\'allakum tashkuroon',123,'3:123',7,26,54,1,0,66,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(417,3,'إِذْ تَقُولُ لِلْمُؤْمِنِينَ أَلَن يَكْفِيَكُمْ أَن يُمِدَّكُمْ رَبُّكُم بِثَلَـٰثَةِ ءَالَـٰفٍ مِّنَ ٱلْمَلَـٰٓئِكَةِ مُنزَلِينَ','Iz taqoolu lilmu\'mineena alai yakfiyakum ai-yumiddakum Rabbukum bisalaasati aalaafim minal malaaa\'ikati munzaleen',124,'3:124',7,26,54,1,0,66,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(418,3,'بَلَىٰٓ ۚ إِن تَصْبِرُوا۟ وَتَتَّقُوا۟ وَيَأْتُوكُم مِّن فَوْرِهِمْ هَـٰذَا يُمْدِدْكُمْ رَبُّكُم بِخَمْسَةِ ءَالَـٰفٍ مِّنَ ٱلْمَلَـٰٓئِكَةِ مُسَوِّمِينَ','Balaaa; in tasbiroo wa tattaqoo wa yaatookum min fawrihim haazaa yumdidkum Rabbukum bikhamsati aalaafim minal malaaa\'ikati musawwaimeen',125,'3:125',7,26,54,1,0,66,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(419,3,'وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشْرَىٰ لَكُمْ وَلِتَطْمَئِنَّ قُلُوبُكُم بِهِۦ ۗ وَمَا ٱلنَّصْرُ إِلَّا مِنْ عِندِ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ','Wa maa ja\'alahul laahu illaa bushraa lakum wa litatma\'inna quloobukum bih\' wa man-nasru illaa min \'indilllaahil \'Azeezil Hakeem',126,'3:126',7,26,54,1,0,66,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(420,3,'لِيَقْطَعَ طَرَفًا مِّنَ ٱلَّذِينَ كَفَرُوٓا۟ أَوْ يَكْبِتَهُمْ فَيَنقَلِبُوا۟ خَآئِبِينَ','Laiyaqta\'a tarafam minal lazeena kafarooo aw yakbitahum fayanqaliboo khaaa\'ibeen',127,'3:127',7,26,54,1,0,66,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(421,3,'لَيْسَ لَكَ مِنَ ٱلْأَمْرِ شَىْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَـٰلِمُونَ','Laisa laka minal amrishai\'un aw yatooba \'alaihim aw yu\'az zi bahum fa innahum zaalimoon',128,'3:128',7,26,54,1,0,66,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(422,3,'وَلِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ ۚ وَٱللَّهُ غَفُورٌ رَّحِيمٌ','Wa lilaahi maa fissamaawaati wa maa fil-ard; yaghfiru limai-yashaaa\'u wa yu\'azzibu mai-yashaaa\'; wallaahu Ghafoorur Raheem',129,'3:129',7,26,54,1,0,66,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(423,3,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَأْكُلُوا۟ ٱلرِّبَوٰٓا۟ أَضْعَـٰفًا مُّضَـٰعَفَةً ۖ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ','Yaaa ayyuhal lazeena aamanoo la taakuhur ribaaa ad\'aafam mudaa\'afatanw wattaqul laaha la\'allakum tuflihoon',130,'3:130',7,26,55,1,0,66,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(424,3,'وَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِىٓ أُعِدَّتْ لِلْكَـٰفِرِينَ','Wattaqun Naaral lateee u\'iddat lilkaafireen',131,'3:131',7,26,55,1,0,66,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(425,3,'وَأَطِيعُوا۟ ٱللَّهَ وَٱلرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ','Wa atee\'ul laaha war Rasoola la\'allakum turhamoon',132,'3:132',7,26,55,1,0,66,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(426,3,'۞ وَسَارِعُوٓا۟ إِلَىٰ مَغْفِرَةٍ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا ٱلسَّمَـٰوَٰتُ وَٱلْأَرْضُ أُعِدَّتْ لِلْمُتَّقِينَ','Wa saari\'ooo ilaa maghfiratim mir Rabbikum wa Jannatin arduhassamaawaatu wal ardu u\'iddat lilmuttaqeen',133,'3:133',7,27,55,1,0,67,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(427,3,'ٱلَّذِينَ يُنفِقُونَ فِى ٱلسَّرَّآءِ وَٱلضَّرَّآءِ وَٱلْكَـٰظِمِينَ ٱلْغَيْظَ وَٱلْعَافِينَ عَنِ ٱلنَّاسِ ۗ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ','Allazeena yunfiqoona fissarraaa\'i waddarraaa\'i wal kaazimeenal ghaiza wal aafeena \'anin-naas; wallaahu yuhibbul muhsineen',134,'3:134',7,27,55,1,0,67,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(428,3,'وَٱلَّذِينَ إِذَا فَعَلُوا۟ فَـٰحِشَةً أَوْ ظَلَمُوٓا۟ أَنفُسَهُمْ ذَكَرُوا۟ ٱللَّهَ فَٱسْتَغْفَرُوا۟ لِذُنُوبِهِمْ وَمَن يَغْفِرُ ٱلذُّنُوبَ إِلَّا ٱللَّهُ وَلَمْ يُصِرُّوا۟ عَلَىٰ مَا فَعَلُوا۟ وَهُمْ يَعْلَمُونَ','Wallazeena izaa fa\'aloo faahishatan aw zalamooo anfusahum zakarul laaha fastaghfaroo lizunoobihim; wa mai yaghfiruz zunooba illal laahu wa lam yusirroo \'alaa maa fa\'aloo wa hum ya\'lamooo',135,'3:135',7,27,55,1,0,67,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(429,3,'أُو۟لَـٰٓئِكَ جَزَآؤُهُم مَّغْفِرَةٌ مِّن رَّبِّهِمْ وَجَنَّـٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا ۚ وَنِعْمَ أَجْرُ ٱلْعَـٰمِلِينَ','Ulaaa\'ika jazaaa\'uhum maghfiratum mir Rabbihim wa Jannaatun tajree min tahtihal anhaaru khaalideena feeha; wa ni\'ma ajrul \'aamileen',136,'3:136',7,27,55,1,0,67,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(430,3,'قَدْ خَلَتْ مِن قَبْلِكُمْ سُنَنٌ فَسِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُكَذِّبِينَ','Qad khalat min qablikum sunanum faseeroo fil ardi fanzuroo kaifa kaana \'aaqiba tul mukazzibeen',137,'3:137',7,27,55,1,0,67,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(431,3,'هَـٰذَا بَيَانٌ لِّلنَّاسِ وَهُدًى وَمَوْعِظَةٌ لِّلْمُتَّقِينَ','Haazaa bayaanul linnaasi wa hudanw wa maw\'izatul lilmuttaqeen',138,'3:138',7,27,55,1,0,67,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(432,3,'وَلَا تَهِنُوا۟ وَلَا تَحْزَنُوا۟ وَأَنتُمُ ٱلْأَعْلَوْنَ إِن كُنتُم مُّؤْمِنِينَ','Wa laa tahinoo wa laa tahzanoo wa antumul a\'lawna in kuntum mu\'mineen',139,'3:139',7,27,55,1,0,67,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(433,3,'إِن يَمْسَسْكُمْ قَرْحٌ فَقَدْ مَسَّ ٱلْقَوْمَ قَرْحٌ مِّثْلُهُۥ ۚ وَتِلْكَ ٱلْأَيَّامُ نُدَاوِلُهَا بَيْنَ ٱلنَّاسِ وَلِيَعْلَمَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَيَتَّخِذَ مِنكُمْ شُهَدَآءَ ۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّـٰلِمِينَ','Iny-yamsaskum qarhum faqad massal qawma qarhum misluh; wa tilkal ayyaamu nudaawiluhaa bainan naasi wa liya\'lamal laahul lazeena aamanoo wa yattakhiza minkum shuhadaaa\'; wallaahu laa yuh ibbuz zaalimeen',140,'3:140',7,27,55,1,0,67,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(434,3,'وَلِيُمَحِّصَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَيَمْحَقَ ٱلْكَـٰفِرِينَ','Wa liyumahhisal laahul lazeena aamanoo wa yamhaqal kaafireen',141,'3:141',7,27,55,1,0,68,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(435,3,'أَمْ حَسِبْتُمْ أَن تَدْخُلُوا۟ ٱلْجَنَّةَ وَلَمَّا يَعْلَمِ ٱللَّهُ ٱلَّذِينَ جَـٰهَدُوا۟ مِنكُمْ وَيَعْلَمَ ٱلصَّـٰبِرِينَ','Am hasibtum an tadkhulul Jannnata wa lammaa ya\'lamil laahul lazeena jaahadoo minkum wa ya\'lamas saabireen',142,'3:142',7,27,55,1,0,68,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(436,3,'وَلَقَدْ كُنتُمْ تَمَنَّوْنَ ٱلْمَوْتَ مِن قَبْلِ أَن تَلْقَوْهُ فَقَدْ رَأَيْتُمُوهُ وَأَنتُمْ تَنظُرُونَ','Wa laqad kuntum tamannnawnal mawta min qabli an talqawhu faqad ra aitumoohu wa antum tanzuroon',143,'3:143',7,27,55,1,0,68,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(437,3,'وَمَا مُحَمَّدٌ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ ٱلرُّسُلُ ۚ أَفَإِي۟ن مَّاتَ أَوْ قُتِلَ ٱنقَلَبْتُمْ عَلَىٰٓ أَعْقَـٰبِكُمْ ۚ وَمَن يَنقَلِبْ عَلَىٰ عَقِبَيْهِ فَلَن يَضُرَّ ٱللَّهَ شَيْـًٔا ۗ وَسَيَجْزِى ٱللَّهُ ٱلشَّـٰكِرِينَ','Wa maa Muhammadun illaa Rasoolun qad khalat min qablihir Rusul; afa\'im maata aw qutilan qalabtum \'alaaa a\'qaabikum; wa mai yanqalib \'alaa aqibihi falai yadurral laaha shai\'aa; wa sayajzil laahush shaakireen',144,'3:144',7,27,56,1,0,68,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(438,3,'وَمَا كَانَ لِنَفْسٍ أَن تَمُوتَ إِلَّا بِإِذْنِ ٱللَّهِ كِتَـٰبًا مُّؤَجَّلًا ۗ وَمَن يُرِدْ ثَوَابَ ٱلدُّنْيَا نُؤْتِهِۦ مِنْهَا وَمَن يُرِدْ ثَوَابَ ٱلْـَٔاخِرَةِ نُؤْتِهِۦ مِنْهَا ۚ وَسَنَجْزِى ٱلشَّـٰكِرِينَ','Wa maa kaana linafsin an tamoota illaa bi iznillaahi kitaabam mu\'ajjalaa; wa mai yurid sawaabad dunyaa nu\'tihee minhaa wa mai yurid sawaabal Aakhirati nu\'tihee minhaa; wa sanajzish shaakireen',145,'3:145',7,27,56,1,0,68,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(439,3,'وَكَأَيِّن مِّن نَّبِىٍّ قَـٰتَلَ مَعَهُۥ رِبِّيُّونَ كَثِيرٌ فَمَا وَهَنُوا۟ لِمَآ أَصَابَهُمْ فِى سَبِيلِ ٱللَّهِ وَمَا ضَعُفُوا۟ وَمَا ٱسْتَكَانُوا۟ ۗ وَٱللَّهُ يُحِبُّ ٱلصَّـٰبِرِينَ','Wa ka aiyim min Nabiyyin qaatala ma\'ahoo ribbiyyoona kaseerun famaa wahanoo limaaa Asaabahum fee sabeelil laahi wa maa da\'ufoo wa mas takaanoo; wallaahu yuhibbus saabireen',146,'3:146',7,27,56,1,0,68,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(440,3,'وَمَا كَانَ قَوْلَهُمْ إِلَّآ أَن قَالُوا۟ رَبَّنَا ٱغْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا فِىٓ أَمْرِنَا وَثَبِّتْ أَقْدَامَنَا وَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَـٰفِرِينَ','Wa maa kaana qawlahum illaa an qaaloo Rabbanagh fir lanaa zunoobanaa wa israafanaa feee amirnaa wa sabbit aqdaamanaa wansurnaa \'alal qawmil kaafireen',147,'3:147',7,27,56,1,0,68,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(441,3,'فَـَٔاتَىٰهُمُ ٱللَّهُ ثَوَابَ ٱلدُّنْيَا وَحُسْنَ ثَوَابِ ٱلْـَٔاخِرَةِ ۗ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ','Fa aataahumul laahu sawaabad dunyaa wa husna sawaabil Aakhirah; wallaahu yuhibbul muhsineen',148,'3:148',7,27,56,1,0,68,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(442,3,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تُطِيعُوا۟ ٱلَّذِينَ كَفَرُوا۟ يَرُدُّوكُمْ عَلَىٰٓ أَعْقَـٰبِكُمْ فَتَنقَلِبُوا۟ خَـٰسِرِينَ','Yaaa \'aiyuhal lazeena aamanoo in tutee\'ullazeena kafaroo yaruddookum \'alaaa a\'qaabkum fatanqaliboo khaasireen',149,'3:149',7,27,57,1,0,69,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(443,3,'بَلِ ٱللَّهُ مَوْلَىٰكُمْ ۖ وَهُوَ خَيْرُ ٱلنَّـٰصِرِينَ','Balil laahu mawlaakum wa Huwa khairun naasireen',150,'3:150',7,27,57,1,0,69,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(444,3,'سَنُلْقِى فِى قُلُوبِ ٱلَّذِينَ كَفَرُوا۟ ٱلرُّعْبَ بِمَآ أَشْرَكُوا۟ بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَـٰنًا ۖ وَمَأْوَىٰهُمُ ٱلنَّارُ ۚ وَبِئْسَ مَثْوَى ٱلظَّـٰلِمِينَ','Sanulqee fee quloobil lazeena kafarur ru\'ba bimaaa ashrakoo billaahi maa lam yunazzil bihee sultaana-nw wa maawaahumun Naar; wa bi\'sa maswaz zaalimeen',151,'3:151',7,27,57,1,0,69,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(445,3,'وَلَقَدْ صَدَقَكُمُ ٱللَّهُ وَعْدَهُۥٓ إِذْ تَحُسُّونَهُم بِإِذْنِهِۦ ۖ حَتَّىٰٓ إِذَا فَشِلْتُمْ وَتَنَـٰزَعْتُمْ فِى ٱلْأَمْرِ وَعَصَيْتُم مِّنۢ بَعْدِ مَآ أَرَىٰكُم مَّا تُحِبُّونَ ۚ مِنكُم مَّن يُرِيدُ ٱلدُّنْيَا وَمِنكُم مَّن يُرِيدُ ٱلْـَٔاخِرَةَ ۚ ثُمَّ صَرَفَكُمْ عَنْهُمْ لِيَبْتَلِيَكُمْ ۖ وَلَقَدْ عَفَا عَنكُمْ ۗ وَٱللَّهُ ذُو فَضْلٍ عَلَى ٱلْمُؤْمِنِينَ','Wa laqad sadaqakumul laahu wa\'dahooo iz tahussoo nahum bi iznihee hattaaa izaa fashiltim wa tanaaza\'tum fil amri wa \'asaitum mim ba\'di maaa araakum maa tuhibboon; minkum mai yureedud dunyaa wa minkum mai yureedul Aakhirah; summa sarafakum \'anhum sarafakum \'anhum liyabtaliyakum wa laqad \'afaa \'ankum; wallaahu zoo fadlin \'alal mu\'mineen',152,'3:152',7,27,57,1,0,69,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(446,3,'۞ إِذْ تُصْعِدُونَ وَلَا تَلْوُۥنَ عَلَىٰٓ أَحَدٍ وَٱلرَّسُولُ يَدْعُوكُمْ فِىٓ أُخْرَىٰكُمْ فَأَثَـٰبَكُمْ غَمًّۢا بِغَمٍّ لِّكَيْلَا تَحْزَنُوا۟ عَلَىٰ مَا فَاتَكُمْ وَلَا مَآ أَصَـٰبَكُمْ ۗ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ','Iz tus\'idoona wa laa talwoona \'alaaa ahadinw war Rasoolu yad\'ookum feee ukhraakum fa asaabakum ghammam bighammil likailaa tahzanoo \'alaa maa faatakum wa laa maaa asaabakum; wallaahu khabeerum bimaa ta\'maloon',153,'3:153',7,28,57,1,0,69,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(447,3,'ثُمَّ أَنزَلَ عَلَيْكُم مِّنۢ بَعْدِ ٱلْغَمِّ أَمَنَةً نُّعَاسًا يَغْشَىٰ طَآئِفَةً مِّنكُمْ ۖ وَطَآئِفَةٌ قَدْ أَهَمَّتْهُمْ أَنفُسُهُمْ يَظُنُّونَ بِٱللَّهِ غَيْرَ ٱلْحَقِّ ظَنَّ ٱلْجَـٰهِلِيَّةِ ۖ يَقُولُونَ هَل لَّنَا مِنَ ٱلْأَمْرِ مِن شَىْءٍ ۗ قُلْ إِنَّ ٱلْأَمْرَ كُلَّهُۥ لِلَّهِ ۗ يُخْفُونَ فِىٓ أَنفُسِهِم مَّا لَا يُبْدُونَ لَكَ ۖ يَقُولُونَ لَوْ كَانَ لَنَا مِنَ ٱلْأَمْرِ شَىْءٌ مَّا قُتِلْنَا هَـٰهُنَا ۗ قُل لَّوْ كُنتُمْ فِى بُيُوتِكُمْ لَبَرَزَ ٱلَّذِينَ كُتِبَ عَلَيْهِمُ ٱلْقَتْلُ إِلَىٰ مَضَاجِعِهِمْ ۖ وَلِيَبْتَلِىَ ٱللَّهُ مَا فِى صُدُورِكُمْ وَلِيُمَحِّصَ مَا فِى قُلُوبِكُمْ ۗ وَٱللَّهُ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ','Summa anzala \'alaikum mim ba\'dil ghammi amanatan nu\'aasai yaghshaa taaa\' ifatam minkum wa taaa\'ifatun qad ahammathum anfusuhum yazunnoona billaahi ghairal haqqi zannal jaahiliyyati yaqooloona hal lanaa minal amri min shai\'; qul innal amra kullahoo lillaah; yukhfoona fee anfusihim maa laa yubdoona laka yaqooloona law kaana lanaa minal amri shai\'ummaa qutilnaa haahunaa; qul law kuntum fee buyootikum labarazal lazeena kutiba \'alaihimul qatlu ilaa madaaji\'ihim wa liyabtaliyal laahu maa fee sudoorikum wa liyumah hisa maa fee quloobikum; wallaahu \'aleemum bizaatis sudoor',154,'3:154',7,28,57,1,0,70,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(448,3,'إِنَّ ٱلَّذِينَ تَوَلَّوْا۟ مِنكُمْ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ إِنَّمَا ٱسْتَزَلَّهُمُ ٱلشَّيْطَـٰنُ بِبَعْضِ مَا كَسَبُوا۟ ۖ وَلَقَدْ عَفَا ٱللَّهُ عَنْهُمْ ۗ إِنَّ ٱللَّهَ غَفُورٌ حَلِيمٌ','Innal lazeena tawallaw minkum yawmal taqal jam\'aani innamas tazallahumush Shaitaanu biba\'di maa kasaboo wa laqad \'afal laahu \'anhum; innnal laaha Ghafoorum Haleem',155,'3:155',7,28,57,1,0,70,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(449,3,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَكُونُوا۟ كَٱلَّذِينَ كَفَرُوا۟ وَقَالُوا۟ لِإِخْوَٰنِهِمْ إِذَا ضَرَبُوا۟ فِى ٱلْأَرْضِ أَوْ كَانُوا۟ غُزًّى لَّوْ كَانُوا۟ عِندَنَا مَا مَاتُوا۟ وَمَا قُتِلُوا۟ لِيَجْعَلَ ٱللَّهُ ذَٰلِكَ حَسْرَةً فِى قُلُوبِهِمْ ۗ وَٱللَّهُ يُحْىِۦ وَيُمِيتُ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ','Yaaa ayyuhul lazeena aamanoo laa takoonoo kallazeena kafaroo wa qaaloo li ikhwaanihim izaa daraboo fil ardi aw kaanoo ghuzzal law kaanoo \'indanaa maa maatoo wa maa qutiloo liyaj\'alal laahu zaalika hasratan fee quloobihim; qallaahu yuhyee wa yumeet; wallaahu bimaa ta\'maloona Baseer',156,'3:156',7,28,58,1,0,70,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(450,3,'وَلَئِن قُتِلْتُمْ فِى سَبِيلِ ٱللَّهِ أَوْ مُتُّمْ لَمَغْفِرَةٌ مِّنَ ٱللَّهِ وَرَحْمَةٌ خَيْرٌ مِّمَّا يَجْمَعُونَ','Wa la\'in qutiltum fee sabeelil laahi aw muttum lamaghfiratum minal laahi wa rahmatun khairum mimmaa yajma\'oon',157,'3:157',7,28,58,1,0,70,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(451,3,'وَلَئِن مُّتُّمْ أَوْ قُتِلْتُمْ لَإِلَى ٱللَّهِ تُحْشَرُونَ','Wa la\'im muttum \'aw qutiltumla ilal laahi tuhsharoon',158,'3:158',7,28,58,1,0,71,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(452,3,'فَبِمَا رَحْمَةٍ مِّنَ ٱللَّهِ لِنتَ لَهُمْ ۖ وَلَوْ كُنتَ فَظًّا غَلِيظَ ٱلْقَلْبِ لَٱنفَضُّوا۟ مِنْ حَوْلِكَ ۖ فَٱعْفُ عَنْهُمْ وَٱسْتَغْفِرْ لَهُمْ وَشَاوِرْهُمْ فِى ٱلْأَمْرِ ۖ فَإِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى ٱللَّهِ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَوَكِّلِينَ','Fabimaa rahmatim minal laahi linta lahum wa law kunta fazzan ghaleezal qalbi lanfaddoo min hawlika fafu \'anhum wastaghfir lahum wa shaawirhum fil amri fa izaa \'azamta fatawakkal \'alal laah; innallaaha yuhibbul mutawak kileen',159,'3:159',7,28,58,1,0,71,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(453,3,'إِن يَنصُرْكُمُ ٱللَّهُ فَلَا غَالِبَ لَكُمْ ۖ وَإِن يَخْذُلْكُمْ فَمَن ذَا ٱلَّذِى يَنصُرُكُم مِّنۢ بَعْدِهِۦ ۗ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ','Iny-yansurkumul laahu falaa ghaaliba lakum wa iny-yakhzulkum faman zal lazee yansurukum mim ba\'dih; wa \'alal laahi falyatawakkalil mu\'minoon',160,'3:160',7,28,58,1,0,71,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(454,3,'وَمَا كَانَ لِنَبِىٍّ أَن يَغُلَّ ۚ وَمَن يَغْلُلْ يَأْتِ بِمَا غَلَّ يَوْمَ ٱلْقِيَـٰمَةِ ۚ ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ','Wa maa kaana li Nabiyyin ai yaghull; wa mai yaghlul yaati bimaa ghalla Yawmal Qiyaamah; summa tuwaffaa kullu nafsim maa kasabat wa hum laa yuzlamoon',161,'3:161',7,28,58,1,0,71,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(455,3,'أَفَمَنِ ٱتَّبَعَ رِضْوَٰنَ ٱللَّهِ كَمَنۢ بَآءَ بِسَخَطٍ مِّنَ ٱللَّهِ وَمَأْوَىٰهُ جَهَنَّمُ ۚ وَبِئْسَ ٱلْمَصِيرُ','Afamanit taba\'a Ridwaanal laahi kamam baaa\'a bisakhatim minal laahi wa maawaahu Jahannam; wa bi\'sal maseer',162,'3:162',7,28,58,1,0,71,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(456,3,'هُمْ دَرَجَـٰتٌ عِندَ ٱللَّهِ ۗ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ','Hum darajaatun \'indal laah; wallaahu baseerum bimaa ya\'maloon',163,'3:163',7,28,58,1,0,71,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(457,3,'لَقَدْ مَنَّ ٱللَّهُ عَلَى ٱلْمُؤْمِنِينَ إِذْ بَعَثَ فِيهِمْ رَسُولًا مِّنْ أَنفُسِهِمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَـٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ٱلْكِتَـٰبَ وَٱلْحِكْمَةَ وَإِن كَانُوا۟ مِن قَبْلُ لَفِى ضَلَـٰلٍ مُّبِينٍ','Laqad mannal laahu \'alal mu\'mineena iz ba\'asa feehim Rasoolam min anfusihim yatloo \'alaihim Aayaatihee wa yuzakkeehim wa yu\'allimu humul Kitaaba wal Hikmata wa in kaanoo min qablu lafee dalaalim mubeen',164,'3:164',7,28,58,1,0,71,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(458,3,'أَوَلَمَّآ أَصَـٰبَتْكُم مُّصِيبَةٌ قَدْ أَصَبْتُم مِّثْلَيْهَا قُلْتُمْ أَنَّىٰ هَـٰذَا ۖ قُلْ هُوَ مِنْ عِندِ أَنفُسِكُمْ ۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ','Awa lammaaa asaabatkum museebatun qad asabtum mislaihaa qultum annaa haazaa qul huwa min \'indi anfusikum; innal laaha \'alaa kulli shai\'in Qadeer',165,'3:165',7,28,58,1,0,71,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(459,3,'وَمَآ أَصَـٰبَكُمْ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ فَبِإِذْنِ ٱللَّهِ وَلِيَعْلَمَ ٱلْمُؤْمِنِينَ','Wa maa asaabakum yawmal taqal jam\'aani fabiiznil laahi wa liya\'lamal mu\'mineen',166,'3:166',7,28,58,1,0,72,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(460,3,'وَلِيَعْلَمَ ٱلَّذِينَ نَافَقُوا۟ ۚ وَقِيلَ لَهُمْ تَعَالَوْا۟ قَـٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ أَوِ ٱدْفَعُوا۟ ۖ قَالُوا۟ لَوْ نَعْلَمُ قِتَالًا لَّٱتَّبَعْنَـٰكُمْ ۗ هُمْ لِلْكُفْرِ يَوْمَئِذٍ أَقْرَبُ مِنْهُمْ لِلْإِيمَـٰنِ ۚ يَقُولُونَ بِأَفْوَٰهِهِم مَّا لَيْسَ فِى قُلُوبِهِمْ ۗ وَٱللَّهُ أَعْلَمُ بِمَا يَكْتُمُونَ','Wa liya\'lamal lazeena naafaqoo; wa qeela lahum ta\'aalaw qaatiloo fee sabeelil laahi awid fa\'oo qaaloo law na\'lamu qitaalallat taba\'naakum; hum lilkufri yawma\'izin aqrabu minhum lil eemaan; yaqooloona bi afwaahihim maa laisa fee quloobihim; wallaahu a\'lamu bimaa yaktumoon',167,'3:167',7,28,58,1,0,72,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(461,3,'ٱلَّذِينَ قَالُوا۟ لِإِخْوَٰنِهِمْ وَقَعَدُوا۟ لَوْ أَطَاعُونَا مَا قُتِلُوا۟ ۗ قُلْ فَٱدْرَءُوا۟ عَنْ أَنفُسِكُمُ ٱلْمَوْتَ إِن كُنتُمْ صَـٰدِقِينَ','Allazeena qaaloo liikhwaanihim wa qa\'adoo law ataa\'oonaa maa qutiloo; qul fadra\'oo\'an anfusikumul mawta in kuntum saadiqeen',168,'3:168',7,28,58,1,0,72,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(462,3,'وَلَا تَحْسَبَنَّ ٱلَّذِينَ قُتِلُوا۟ فِى سَبِيلِ ٱللَّهِ أَمْوَٰتًۢا ۚ بَلْ أَحْيَآءٌ عِندَ رَبِّهِمْ يُرْزَقُونَ','Wa laa tahsabannal lazeena qutiloo fee sabeelillaahi amwaata; bal ahyaaa\'un \'inda Rabbihim yurzaqoon',169,'3:169',7,28,58,1,0,72,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(463,3,'فَرِحِينَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ وَيَسْتَبْشِرُونَ بِٱلَّذِينَ لَمْ يَلْحَقُوا۟ بِهِم مِّنْ خَلْفِهِمْ أَلَّا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ','Fariheena bimaaa aataa humul laahu min fadlihee wa yastabshiroona billazeena lam yalhaqoo bihim min fadlihee wa yastabshiroona billazeena lam yalhaqoo bihim min khalfihim allaa khawfun \'alaihim wa laa hum yahzanoon',170,'3:170',7,28,58,1,0,72,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(464,3,'۞ يَسْتَبْشِرُونَ بِنِعْمَةٍ مِّنَ ٱللَّهِ وَفَضْلٍ وَأَنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُؤْمِنِينَ','Yastabshiroona bini\'matim minal laahi wa fad linw wa annal laaha laa yudee\'u ajral mu\'mineen',171,'3:171',8,29,58,1,0,72,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(465,3,'ٱلَّذِينَ ٱسْتَجَابُوا۟ لِلَّهِ وَٱلرَّسُولِ مِنۢ بَعْدِ مَآ أَصَابَهُمُ ٱلْقَرْحُ ۚ لِلَّذِينَ أَحْسَنُوا۟ مِنْهُمْ وَٱتَّقَوْا۟ أَجْرٌ عَظِيمٌ','Allazeenas tajaaboo lil laahi war Rasooli mim ba\'di maaa asaabahumulqarh; lillazeena ahsanoo minhum wattaqaw ajrun \'azeem',172,'3:172',8,29,59,1,0,72,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(466,3,'ٱلَّذِينَ قَالَ لَهُمُ ٱلنَّاسُ إِنَّ ٱلنَّاسَ قَدْ جَمَعُوا۟ لَكُمْ فَٱخْشَوْهُمْ فَزَادَهُمْ إِيمَـٰنًا وَقَالُوا۟ حَسْبُنَا ٱللَّهُ وَنِعْمَ ٱلْوَكِيلُ','Allazeena qaala lahumun naasu innan naasa qad jama\'oo lakum fakhshawhuin fazaadahum eemaannanwa wa qaaloo hasbunal laahu wa ni\'malwakeel',173,'3:173',8,29,59,1,0,72,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(467,3,'فَٱنقَلَبُوا۟ بِنِعْمَةٍ مِّنَ ٱللَّهِ وَفَضْلٍ لَّمْ يَمْسَسْهُمْ سُوٓءٌ وَٱتَّبَعُوا۟ رِضْوَٰنَ ٱللَّهِ ۗ وَٱللَّهُ ذُو فَضْلٍ عَظِيمٍ','Fanqalaboo bini\'matim minal laahi wa fadlil lam yamsashum sooo\'unw wattaba\'oo ridwaanal laah; wallaahu zoo fadlin \'azeem',174,'3:174',8,29,59,1,0,73,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(468,3,'إِنَّمَا ذَٰلِكُمُ ٱلشَّيْطَـٰنُ يُخَوِّفُ أَوْلِيَآءَهُۥ فَلَا تَخَافُوهُمْ وَخَافُونِ إِن كُنتُم مُّؤْمِنِينَ','Innamaa zaalikumush Shaitaanu yukhawwifu awliyaaa\'ahoo falaa takhaafoohum wa khaafooni in kuntum mu\'mineen',175,'3:175',8,29,59,1,0,73,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(469,3,'وَلَا يَحْزُنكَ ٱلَّذِينَ يُسَـٰرِعُونَ فِى ٱلْكُفْرِ ۚ إِنَّهُمْ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًٔا ۗ يُرِيدُ ٱللَّهُ أَلَّا يَجْعَلَ لَهُمْ حَظًّا فِى ٱلْـَٔاخِرَةِ ۖ وَلَهُمْ عَذَابٌ عَظِيمٌ','Wa laa yahzunkal lazeena yusaari\'oona fil Kufr; innahum lai yadurrul laaha shai\'aa; yureedul laahu allaa yaj\'ala lahum hazzan fil Aakhirati wa lahum \'azaabun \'azeem',176,'3:176',8,29,59,1,0,73,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(470,3,'إِنَّ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلْكُفْرَ بِٱلْإِيمَـٰنِ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًٔا وَلَهُمْ عَذَابٌ أَلِيمٌ','Innal lazeenash tarawul kufra bil eemaani lai yadurrul laaha shai anw wa lahum \'azdaabun aleem',177,'3:177',8,29,59,1,0,73,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(471,3,'وَلَا يَحْسَبَنَّ ٱلَّذِينَ كَفَرُوٓا۟ أَنَّمَا نُمْلِى لَهُمْ خَيْرٌ لِّأَنفُسِهِمْ ۚ إِنَّمَا نُمْلِى لَهُمْ لِيَزْدَادُوٓا۟ إِثْمًا ۚ وَلَهُمْ عَذَابٌ مُّهِينٌ','Wa laa yahsabannal lazeena kafarooo annamaa numlee lahum khairulli anfusihim; innamaa numlee lahum liyazdaadooo ismaa wa lahum \'azaabum muheen',178,'3:178',8,29,59,1,0,73,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(472,3,'مَّا كَانَ ٱللَّهُ لِيَذَرَ ٱلْمُؤْمِنِينَ عَلَىٰ مَآ أَنتُمْ عَلَيْهِ حَتَّىٰ يَمِيزَ ٱلْخَبِيثَ مِنَ ٱلطَّيِّبِ ۗ وَمَا كَانَ ٱللَّهُ لِيُطْلِعَكُمْ عَلَى ٱلْغَيْبِ وَلَـٰكِنَّ ٱللَّهَ يَجْتَبِى مِن رُّسُلِهِۦ مَن يَشَآءُ ۖ فَـَٔامِنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ ۚ وَإِن تُؤْمِنُوا۟ وَتَتَّقُوا۟ فَلَكُمْ أَجْرٌ عَظِيمٌ','Maa kaanal laahu liyazaral mu\'mineena \'alaa maaa antum \'alaihi hattaa yameezal khabeesa minat taiyib; wa maa kaanal laahu liyutli\'akum \'alal ghaibi wa laakinnal laaha yajtabee mir Rusulihii mai yashaaa\'u fa aaminoo billaahi wa Rusulih; wa in tu \'minoo wa tattaqoo falakum ajrun \'azeem',179,'3:179',8,29,59,1,0,73,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(473,3,'وَلَا يَحْسَبَنَّ ٱلَّذِينَ يَبْخَلُونَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ هُوَ خَيْرًا لَّهُم ۖ بَلْ هُوَ شَرٌّ لَّهُمْ ۖ سَيُطَوَّقُونَ مَا بَخِلُوا۟ بِهِۦ يَوْمَ ٱلْقِيَـٰمَةِ ۗ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ','Wa laa yahsabannal lazeena yabkhaloon bimaa aataahumul lahu min fadilhee huwa khairal lahum bal huwa sharrul lahum sayutaw waqoona maa bakhiloo bihee Yawmal Qiyaamah; wa lillaahi meeraasus samaawaati wal ard; wallaahu bimaa ta\'maloona Khabeer',180,'3:180',8,29,59,1,0,73,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(474,3,'لَّقَدْ سَمِعَ ٱللَّهُ قَوْلَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ فَقِيرٌ وَنَحْنُ أَغْنِيَآءُ ۘ سَنَكْتُبُ مَا قَالُوا۟ وَقَتْلَهُمُ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّ وَنَقُولُ ذُوقُوا۟ عَذَابَ ٱلْحَرِيقِ','Laqad sami\'al laahu qawlal lazeena qaalooo innal laaha faqeerunw wa nahnu aghniyaaa\'; sanaktubu maa qaaloo wa qatlahumul Ambiyaa\'a bighairi haqqinw wa naqoolu zooqoo \'azaaba Ihreeq',181,'3:181',8,29,60,1,0,74,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(475,3,'ذَٰلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ ٱللَّهَ لَيْسَ بِظَلَّامٍ لِّلْعَبِيدِ','Zaalika bimaa qaddamat aideekum wa annal laaha laisa bizallaamil lil\'abeed',182,'3:182',8,29,60,1,0,74,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(476,3,'ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ عَهِدَ إِلَيْنَآ أَلَّا نُؤْمِنَ لِرَسُولٍ حَتَّىٰ يَأْتِيَنَا بِقُرْبَانٍ تَأْكُلُهُ ٱلنَّارُ ۗ قُلْ قَدْ جَآءَكُمْ رُسُلٌ مِّن قَبْلِى بِٱلْبَيِّنَـٰتِ وَبِٱلَّذِى قُلْتُمْ فَلِمَ قَتَلْتُمُوهُمْ إِن كُنتُمْ صَـٰدِقِينَ','Allazeena qaalooo innal laaha \'ahida ilainaaa allaa nu\'mina liRasoolin hatta yaa tiyanaa biqurbaanin taa kuluhun naar; qul qad jaaa\'akum Rusulum min qablee bilbaiyinaati wa billazee qultum falima qataltumoohum in kuntum saadiqeen',183,'3:183',8,29,60,1,0,74,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(477,3,'فَإِن كَذَّبُوكَ فَقَدْ كُذِّبَ رُسُلٌ مِّن قَبْلِكَ جَآءُو بِٱلْبَيِّنَـٰتِ وَٱلزُّبُرِ وَٱلْكِتَـٰبِ ٱلْمُنِيرِ','Fa in kaz zabooka faqad kuz ziba Rusulum min qablika jaaa\'oo bilbaiyinaati waz Zuburi wal Kitaabil Muneer',184,'3:184',8,29,60,1,0,74,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(478,3,'كُلُّ نَفْسٍ ذَآئِقَةُ ٱلْمَوْتِ ۗ وَإِنَّمَا تُوَفَّوْنَ أُجُورَكُمْ يَوْمَ ٱلْقِيَـٰمَةِ ۖ فَمَن زُحْزِحَ عَنِ ٱلنَّارِ وَأُدْخِلَ ٱلْجَنَّةَ فَقَدْ فَازَ ۗ وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا مَتَـٰعُ ٱلْغُرُورِ','Kulu nafsin zaaa\'iqatul mawt; wa innamaa tuwaffawna ujoorakum Yawmal Qiyaamati faman zuhziha \'anin Naari waudkhilal Jannata faqad faaz; wa mal hayaatud dunyaaa illaa mataa\'ul ghuroor',185,'3:185',8,29,60,1,0,74,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(479,3,'۞ لَتُبْلَوُنَّ فِىٓ أَمْوَٰلِكُمْ وَأَنفُسِكُمْ وَلَتَسْمَعُنَّ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ مِن قَبْلِكُمْ وَمِنَ ٱلَّذِينَ أَشْرَكُوٓا۟ أَذًى كَثِيرًا ۚ وَإِن تَصْبِرُوا۟ وَتَتَّقُوا۟ فَإِنَّ ذَٰلِكَ مِنْ عَزْمِ ٱلْأُمُورِ','Latublawunna feee amwaalikum wa anfusikum wa latasma\'unna minal lazeena ootul Kitaaba min qablikum wa minal lazeena ashrakooo azan kaseeraa; wa in tasbiroo wa tattaqoo fa inna zaalika min \'azmil umoor',186,'3:186',8,30,60,1,0,74,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(480,3,'وَإِذْ أَخَذَ ٱللَّهُ مِيثَـٰقَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ لَتُبَيِّنُنَّهُۥ لِلنَّاسِ وَلَا تَكْتُمُونَهُۥ فَنَبَذُوهُ وَرَآءَ ظُهُورِهِمْ وَٱشْتَرَوْا۟ بِهِۦ ثَمَنًا قَلِيلًا ۖ فَبِئْسَ مَا يَشْتَرُونَ','Wa iz akhazal laahu meesaaqal lazeena ootul Kitaaba latubaiyinunnahoo linnaasi wa laa taktumoona hoo fanabazoohu waraaa\'a zuhoorihim washtaraw bihee samanan qaleelan fabi\'sa maa yashtaroon',187,'3:187',8,30,60,1,0,75,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(481,3,'لَا تَحْسَبَنَّ ٱلَّذِينَ يَفْرَحُونَ بِمَآ أَتَوا۟ وَّيُحِبُّونَ أَن يُحْمَدُوا۟ بِمَا لَمْ يَفْعَلُوا۟ فَلَا تَحْسَبَنَّهُم بِمَفَازَةٍ مِّنَ ٱلْعَذَابِ ۖ وَلَهُمْ عَذَابٌ أَلِيمٌ','Laa tahsabannal lazeena yafrahoona bimaaa ataw wa yuhibbona ai yuhmadoo bimaa lam yaf\'aloo falaa tahsabunnahum bimafaazatim minal \'azaabi wa lahum \'azaabun aleem',188,'3:188',8,30,60,1,0,75,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(482,3,'وَلِلَّهِ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ','Wa lillaahi mulkus samaawaati wal ard; wallaahu \'alaa kulli shai\'in Qadeer',189,'3:189',8,30,60,1,0,75,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(483,3,'إِنَّ فِى خَلْقِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَـٰفِ ٱلَّيْلِ وَٱلنَّهَارِ لَـَٔايَـٰتٍ لِّأُو۟لِى ٱلْأَلْبَـٰبِ','Inna fee khalqis samaawati wal ardi wakhtilaafil laili wannahaari la Aayaatil liulil albaab',190,'3:190',8,30,61,1,0,75,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(484,3,'ٱلَّذِينَ يَذْكُرُونَ ٱللَّهَ قِيَـٰمًا وَقُعُودًا وَعَلَىٰ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِى خَلْقِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ رَبَّنَا مَا خَلَقْتَ هَـٰذَا بَـٰطِلًا سُبْحَـٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ','Allazeena yazkuroonal laaha qiyaamaiw-wa qu\'oodanw-wa \'alaa juno obihim wa yatafakkaroona fee khalqis samaawaati wal ardi Rabbanaa maa khalaqta haaza baatilan Subhaanak faqinaa \'azaaban Naar',191,'3:191',8,30,61,1,0,75,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(485,3,'رَبَّنَآ إِنَّكَ مَن تُدْخِلِ ٱلنَّارَ فَقَدْ أَخْزَيْتَهُۥ ۖ وَمَا لِلظَّـٰلِمِينَ مِنْ أَنصَارٍ','Rabbanaaa innaka man tudkhilin Naara faqad akhzai tahoo wa maa lizzaalimeena min ansaar',192,'3:192',8,30,61,1,0,75,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(486,3,'رَّبَّنَآ إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِى لِلْإِيمَـٰنِ أَنْ ءَامِنُوا۟ بِرَبِّكُمْ فَـَٔامَنَّا ۚ رَبَّنَا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلْأَبْرَارِ','Rabbanaaa innanaa sami\'naa munaadiyai yunaadee lil eemaani an aaminoo bi Rabbikum fa aamannaa; Rabbanaa faghfir lanaa zunoobanaa wa kaffir \'annaa saiyi aatina wa tawaffanaa ma\'al abraar',193,'3:193',8,30,61,1,0,75,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(487,3,'رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ ٱلْقِيَـٰمَةِ ۗ إِنَّكَ لَا تُخْلِفُ ٱلْمِيعَادَ','Rabbanaa wa aatinaa maa wa\'attanaa \'alaa Rusulika wa laa tukhzinaa Yawmal Qiyaamah; innaka laa tukhliful mee\'aad',194,'3:194',8,30,61,1,0,75,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(488,3,'فَٱسْتَجَابَ لَهُمْ رَبُّهُمْ أَنِّى لَآ أُضِيعُ عَمَلَ عَـٰمِلٍ مِّنكُم مِّن ذَكَرٍ أَوْ أُنثَىٰ ۖ بَعْضُكُم مِّنۢ بَعْضٍ ۖ فَٱلَّذِينَ هَاجَرُوا۟ وَأُخْرِجُوا۟ مِن دِيَـٰرِهِمْ وَأُوذُوا۟ فِى سَبِيلِى وَقَـٰتَلُوا۟ وَقُتِلُوا۟ لَأُكَفِّرَنَّ عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ثَوَابًا مِّنْ عِندِ ٱللَّهِ ۗ وَٱللَّهُ عِندَهُۥ حُسْنُ ٱلثَّوَابِ','Fastajaaba lahum Rabbuhum annee laaa Udee\'u \'amala \'aamilim minkum min zakarin aw unsaa ba\'dukum mim ba\'din fal lazeena haajaroo wa ukhrijoo min diyaarihim wa oozoo fee sabeelee wa qaataloo wa qutiloo la ukaffiranna \'anhum saiyi aatihim wa la udkhilanna hum Jannnatin tajree min tahtihal anhaaru sawaabam min \'indil laah; wallaahu \'indahoo husnus sawaab',195,'3:195',8,30,61,1,0,76,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(489,3,'لَا يَغُرَّنَّكَ تَقَلُّبُ ٱلَّذِينَ كَفَرُوا۟ فِى ٱلْبِلَـٰدِ','Laa yaghurrannaka taqal lubul lazeena kafaroo fil bilaad',196,'3:196',8,30,61,1,0,76,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(490,3,'مَتَـٰعٌ قَلِيلٌ ثُمَّ مَأْوَىٰهُمْ جَهَنَّمُ ۚ وَبِئْسَ ٱلْمِهَادُ','Mataa\'un qaleelun summa maawaahum Jahannam; wa bi\'sal mihaad',197,'3:197',8,30,61,1,0,76,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(491,3,'لَـٰكِنِ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ لَهُمْ جَنَّـٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا نُزُلًا مِّنْ عِندِ ٱللَّهِ ۗ وَمَا عِندَ ٱللَّهِ خَيْرٌ لِّلْأَبْرَارِ','Laakinil lazeenat taqaw Rabbahum lahum Jannnaatun tajree min tahtihal anhaaru khaalideena feehaa nuzulammin \'indil laah; wa maa \'indal laahi khairul lil abraar',198,'3:198',8,30,61,1,0,76,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(492,3,'وَإِنَّ مِنْ أَهْلِ ٱلْكِتَـٰبِ لَمَن يُؤْمِنُ بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْكُمْ وَمَآ أُنزِلَ إِلَيْهِمْ خَـٰشِعِينَ لِلَّهِ لَا يَشْتَرُونَ بِـَٔايَـٰتِ ٱللَّهِ ثَمَنًا قَلِيلًا ۗ أُو۟لَـٰٓئِكَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ ۗ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ','Wa inna min Ahlil Kitaabi lamai yu minu billaahi wa maaa unzila ilaikum wa maaa unzila ilaihim khaashi \'eena lillaahi laa yashtaroona bi Aayaatil laahi samanan qaleelaa; ulaaa\'ika lahum ajruhum \'inda Rabbihim; innal laaha saree\'ul hisaab',199,'3:199',8,30,61,1,0,76,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(493,3,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱصْبِرُوا۟ وَصَابِرُوا۟ وَرَابِطُوا۟ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ','Yaaa aiyuhal lazeena aamanus biroo wa saabiroo wa raabitoo wattaqul laaha la\'allakum tuflihoon',200,'3:200',8,30,61,1,0,76,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(494,4,'يَـٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمُ ٱلَّذِى خَلَقَكُم مِّن نَّفْسٍ وَٰحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالًا كَثِيرًا وَنِسَآءً ۚ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِى تَسَآءَلُونَ بِهِۦ وَٱلْأَرْحَامَ ۚ إِنَّ ٱللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا','Yaaa aiyuhan naasut taqoo Rabbakumul lazee khalaqakum min nafsinw waahidatinw wa khalaqa minhaa zawjahaa wa bas sa minhumaa rijaalan kaseeranw wa nisaaa\'aa; wattaqul laahallazee tasaaa \'aloona bihee wal arhaam; innal laaha kaana \'alaikum Raqeeba',1,'4:1',8,31,62,1,0,77,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(495,4,'وَءَاتُوا۟ ٱلْيَتَـٰمَىٰٓ أَمْوَٰلَهُمْ ۖ وَلَا تَتَبَدَّلُوا۟ ٱلْخَبِيثَ بِٱلطَّيِّبِ ۖ وَلَا تَأْكُلُوٓا۟ أَمْوَٰلَهُمْ إِلَىٰٓ أَمْوَٰلِكُمْ ۚ إِنَّهُۥ كَانَ حُوبًا كَبِيرًا','Wa aatul yataamaaa amwaalahum wa laa tatabad dalul khabeesa bittaiyibi wa laa taakulooo amwaalahum ilaaa amwaalikum; innahoo kaana hooban kabeeraa',2,'4:2',8,31,62,1,0,77,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(496,4,'وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا۟ فِى ٱلْيَتَـٰمَىٰ فَٱنكِحُوا۟ مَا طَابَ لَكُم مِّنَ ٱلنِّسَآءِ مَثْنَىٰ وَثُلَـٰثَ وَرُبَـٰعَ ۖ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا۟ فَوَٰحِدَةً أَوْ مَا مَلَكَتْ أَيْمَـٰنُكُمْ ۚ ذَٰلِكَ أَدْنَىٰٓ أَلَّا تَعُولُوا۟','Wa in khiftum allaa tuqsitoo fil yataamaa fankihoo maa taaba lakum minan nisaaa\'i masnaa wa sulaasa wa rubaa\'a fa\'in khiftum allaa ta\'diloo fawaahidatan aw maa malakat aimaanukum; zaalika adnaaa allaa ta\'ooloo',3,'4:3',8,31,62,1,0,77,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(497,4,'وَءَاتُوا۟ ٱلنِّسَآءَ صَدُقَـٰتِهِنَّ نِحْلَةً ۚ فَإِن طِبْنَ لَكُمْ عَن شَىْءٍ مِّنْهُ نَفْسًا فَكُلُوهُ هَنِيٓـًٔا مَّرِيٓـًٔا','Wa aatun nisaaa\'a sadu qaatihinna nihlah; fa in tibna lakum \'an shai\'im minhu nafsan fakuloohu hanee\'am mareee\'aa',4,'4:4',8,31,62,1,0,77,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(498,4,'وَلَا تُؤْتُوا۟ ٱلسُّفَهَآءَ أَمْوَٰلَكُمُ ٱلَّتِى جَعَلَ ٱللَّهُ لَكُمْ قِيَـٰمًا وَٱرْزُقُوهُمْ فِيهَا وَٱكْسُوهُمْ وَقُولُوا۟ لَهُمْ قَوْلًا مَّعْرُوفًا','Wa laa tu\'tus sufahaaa\'a amwaalakumul latee ja\'alal laahu lakum qiyaamanw-warzuqoohum feehaa waksoohum wa qooloo lahum qawlam ma\'roofaa',5,'4:5',8,31,62,1,0,77,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(499,4,'وَٱبْتَلُوا۟ ٱلْيَتَـٰمَىٰ حَتَّىٰٓ إِذَا بَلَغُوا۟ ٱلنِّكَاحَ فَإِنْ ءَانَسْتُم مِّنْهُمْ رُشْدًا فَٱدْفَعُوٓا۟ إِلَيْهِمْ أَمْوَٰلَهُمْ ۖ وَلَا تَأْكُلُوهَآ إِسْرَافًا وَبِدَارًا أَن يَكْبَرُوا۟ ۚ وَمَن كَانَ غَنِيًّا فَلْيَسْتَعْفِفْ ۖ وَمَن كَانَ فَقِيرًا فَلْيَأْكُلْ بِٱلْمَعْرُوفِ ۚ فَإِذَا دَفَعْتُمْ إِلَيْهِمْ أَمْوَٰلَهُمْ فَأَشْهِدُوا۟ عَلَيْهِمْ ۚ وَكَفَىٰ بِٱللَّهِ حَسِيبًا','Wabtalul yataamaa hattaaa izaa balaghun nikaaha fa in aanastum minhum rushdan fad fa\'ooo ilaihim amwaalahum wa laa taa kuloohaaa israafanw wa bidaaran ai yakbaroo; wa mai kaana ghaniyyan falyasta\' fif wa mai kaana faqeeran falyaakul bilma\'roof; fa izaa dafa\'tum ilaihim amwaalahum fa\'ashhidoo \'alaihim; wa kafaa billaahi Haseeba',6,'4:6',8,31,62,1,0,77,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(500,4,'لِّلرِّجَالِ نَصِيبٌ مِّمَّا تَرَكَ ٱلْوَٰلِدَانِ وَٱلْأَقْرَبُونَ وَلِلنِّسَآءِ نَصِيبٌ مِّمَّا تَرَكَ ٱلْوَٰلِدَانِ وَٱلْأَقْرَبُونَ مِمَّا قَلَّ مِنْهُ أَوْ كَثُرَ ۚ نَصِيبًا مَّفْرُوضًا','Lirrijaali naseebum mimmaa tarakal waalidaani wal aqraboona wa lin nisaaa\'i naseebum mimmaa tarakal waalidaani wal aqraboona mimmaa qalla minhu aw kasur; naseebam mafroodaa',7,'4:7',8,31,62,1,0,78,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(501,4,'وَإِذَا حَضَرَ ٱلْقِسْمَةَ أُو۟لُوا۟ ٱلْقُرْبَىٰ وَٱلْيَتَـٰمَىٰ وَٱلْمَسَـٰكِينُ فَٱرْزُقُوهُم مِّنْهُ وَقُولُوا۟ لَهُمْ قَوْلًا مَّعْرُوفًا','Wa izaa hadaral qismata ulul qurbaa walyataamaa walmasaakeenu farzuqoohum minhu wa qooloo lahum qawlam ma\'roofaa',8,'4:8',8,31,62,1,0,78,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(502,4,'وَلْيَخْشَ ٱلَّذِينَ لَوْ تَرَكُوا۟ مِنْ خَلْفِهِمْ ذُرِّيَّةً ضِعَـٰفًا خَافُوا۟ عَلَيْهِمْ فَلْيَتَّقُوا۟ ٱللَّهَ وَلْيَقُولُوا۟ قَوْلًا سَدِيدًا','Walyakhshal lazeena law tarakoo min khalfihim zurriyyatan di\'aafan khaafoo \'alaihim falyattaqul laaha walyaqooloo qawlan sadeedaa',9,'4:9',8,31,62,1,0,78,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(503,4,'إِنَّ ٱلَّذِينَ يَأْكُلُونَ أَمْوَٰلَ ٱلْيَتَـٰمَىٰ ظُلْمًا إِنَّمَا يَأْكُلُونَ فِى بُطُونِهِمْ نَارًا ۖ وَسَيَصْلَوْنَ سَعِيرًا','Innal lazeena yaakuloona amwaalal yataamaa zulman innamaa yaakuloona fee butoonihim Naaranw-wa sayaslawna sa\'eeraa',10,'4:10',8,31,62,1,0,78,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(504,4,'يُوصِيكُمُ ٱللَّهُ فِىٓ أَوْلَـٰدِكُمْ ۖ لِلذَّكَرِ مِثْلُ حَظِّ ٱلْأُنثَيَيْنِ ۚ فَإِن كُنَّ نِسَآءً فَوْقَ ٱثْنَتَيْنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَ ۖ وَإِن كَانَتْ وَٰحِدَةً فَلَهَا ٱلنِّصْفُ ۚ وَلِأَبَوَيْهِ لِكُلِّ وَٰحِدٍ مِّنْهُمَا ٱلسُّدُسُ مِمَّا تَرَكَ إِن كَانَ لَهُۥ وَلَدٌ ۚ فَإِن لَّمْ يَكُن لَّهُۥ وَلَدٌ وَوَرِثَهُۥٓ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُ ۚ فَإِن كَانَ لَهُۥٓ إِخْوَةٌ فَلِأُمِّهِ ٱلسُّدُسُ ۚ مِنۢ بَعْدِ وَصِيَّةٍ يُوصِى بِهَآ أَوْ دَيْنٍ ۗ ءَابَآؤُكُمْ وَأَبْنَآؤُكُمْ لَا تَدْرُونَ أَيُّهُمْ أَقْرَبُ لَكُمْ نَفْعًا ۚ فَرِيضَةً مِّنَ ٱللَّهِ ۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًا','Yooseekumul laahu feee awlaadikum liz zakari mislu hazzil unsayayn; fa in kunna nisaaa\'an fawqas nataini falahunna suhusaa maa taraka wa in kaanat waahidatan falahan nisf; wa li abawaihi likulli waahidim minhumas sudusu mimmma taraka in kaana lahoo walad; fa il lam yakul lahowaladunw wa warisahooo abawaahu fali ummihis sulus; fa in kaana lahoo ikhwatun fali ummihis sudus; mim ba\'di wasiyyatiny yoosee bihaaa aw dayn; aabaaa\'ukum wa abnaaa\'ukum laa tadroona aiyuhum aqrabu lakum naf\'aa; fareedatam minallaah; innal laaha kaana \'Aleeman Hakeemaa',11,'4:11',8,31,63,1,0,78,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(505,4,'۞ وَلَكُمْ نِصْفُ مَا تَرَكَ أَزْوَٰجُكُمْ إِن لَّمْ يَكُن لَّهُنَّ وَلَدٌ ۚ فَإِن كَانَ لَهُنَّ وَلَدٌ فَلَكُمُ ٱلرُّبُعُ مِمَّا تَرَكْنَ ۚ مِنۢ بَعْدِ وَصِيَّةٍ يُوصِينَ بِهَآ أَوْ دَيْنٍ ۚ وَلَهُنَّ ٱلرُّبُعُ مِمَّا تَرَكْتُمْ إِن لَّمْ يَكُن لَّكُمْ وَلَدٌ ۚ فَإِن كَانَ لَكُمْ وَلَدٌ فَلَهُنَّ ٱلثُّمُنُ مِمَّا تَرَكْتُم ۚ مِّنۢ بَعْدِ وَصِيَّةٍ تُوصُونَ بِهَآ أَوْ دَيْنٍ ۗ وَإِن كَانَ رَجُلٌ يُورَثُ كَلَـٰلَةً أَوِ ٱمْرَأَةٌ وَلَهُۥٓ أَخٌ أَوْ أُخْتٌ فَلِكُلِّ وَٰحِدٍ مِّنْهُمَا ٱلسُّدُسُ ۚ فَإِن كَانُوٓا۟ أَكْثَرَ مِن ذَٰلِكَ فَهُمْ شُرَكَآءُ فِى ٱلثُّلُثِ ۚ مِنۢ بَعْدِ وَصِيَّةٍ يُوصَىٰ بِهَآ أَوْ دَيْنٍ غَيْرَ مُضَآرٍّ ۚ وَصِيَّةً مِّنَ ٱللَّهِ ۗ وَٱللَّهُ عَلِيمٌ حَلِيمٌ','Wa lakum nisfu maa taraka azwaajukum il lam yakul lahunna walad; fa in kaana lahunna waladun falakumur rub\'u mimmaa tarakna mim ba\'di wasiyyatiny yooseena bihaaa aw dayn; wa lahunnar rubu\'u mimmaa tarakum il lam yakul lakum walad; fa in kaana lakum waladun falahunnas sumunu mimmaa taraktum; mim ba\'di wasiyyatin toosoona bihaaa aw dayn; wa in kaana rajuluny yoorasu kalaalatan awim ra atunw wa lahooo akhun aw ukhtun falikulli waahidim minhumas sudus; fa in kaanooo aksara min zaalika fahum shurakaaa\'u fissulusi mim ba\'di wasiyyatiny yoosaa bihaaa aw dainin ghaira mudaaarr; wasiyyatam minal laah; wallaahu \'Aleemun Haleem',12,'4:12',8,32,63,1,0,79,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(506,4,'تِلْكَ حُدُودُ ٱللَّهِ ۚ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدْخِلْهُ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا ۚ وَذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ','Tilka hudoodul laah; wa mai yuti\'il laaha wa Rasoolahoo yudkhilhu Jannaatin tajree min tahtihal anhaaru khaalideena feehaa; wa zaalikal fawzul \'azeem',13,'4:13',8,32,63,1,0,79,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(507,4,'وَمَن يَعْصِ ٱللَّهَ وَرَسُولَهُۥ وَيَتَعَدَّ حُدُودَهُۥ يُدْخِلْهُ نَارًا خَـٰلِدًا فِيهَا وَلَهُۥ عَذَابٌ مُّهِينٌ','Wa mai ya\'sil laaha wa Rasoolahoo wa yata\'adda hudoodahoo yudkhilhu Naaran khaalidan feehaa wa lahoo \'azaabum muheen',14,'4:14',8,32,63,1,0,79,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(508,4,'وَٱلَّـٰتِى يَأْتِينَ ٱلْفَـٰحِشَةَ مِن نِّسَآئِكُمْ فَٱسْتَشْهِدُوا۟ عَلَيْهِنَّ أَرْبَعَةً مِّنكُمْ ۖ فَإِن شَهِدُوا۟ فَأَمْسِكُوهُنَّ فِى ٱلْبُيُوتِ حَتَّىٰ يَتَوَفَّىٰهُنَّ ٱلْمَوْتُ أَوْ يَجْعَلَ ٱللَّهُ لَهُنَّ سَبِيلًا','Wallaatee yaateenal faahishata min nisaaa\'ikum fastashhidoo \'alaihinna arba\'atam minkum fa in shahidoo fa amsikoohunna fil buyooti hatta yatawaffaa hunnal mawtu aw yaj\'alal laahu lahunna sabeelaa',15,'4:15',8,32,64,1,0,80,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(509,4,'وَٱلَّذَانِ يَأْتِيَـٰنِهَا مِنكُمْ فَـَٔاذُوهُمَا ۖ فَإِن تَابَا وَأَصْلَحَا فَأَعْرِضُوا۟ عَنْهُمَآ ۗ إِنَّ ٱللَّهَ كَانَ تَوَّابًا رَّحِيمًا','Wallazaani yaatiyaanihaa minkum fa aazoohumaa fa in taabaa wa aslahaa fa a\'ridoo \'anhumaaa; innal laaha kaana Tawwaabar Raheema',16,'4:16',8,32,64,1,0,80,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(510,4,'إِنَّمَا ٱلتَّوْبَةُ عَلَى ٱللَّهِ لِلَّذِينَ يَعْمَلُونَ ٱلسُّوٓءَ بِجَهَـٰلَةٍ ثُمَّ يَتُوبُونَ مِن قَرِيبٍ فَأُو۟لَـٰٓئِكَ يَتُوبُ ٱللَّهُ عَلَيْهِمْ ۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا','Innamat tawbatu \'alallaahi lillazeena ya\'maloonas sooo\'a bijahaalatin summa yatooboona min qareebin faulaaika yatoobul laahu \'alaihim; wa kaanal laahu \'Aleeman Hakeemaa',17,'4:17',8,32,64,1,0,80,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(511,4,'وَلَيْسَتِ ٱلتَّوْبَةُ لِلَّذِينَ يَعْمَلُونَ ٱلسَّيِّـَٔاتِ حَتَّىٰٓ إِذَا حَضَرَ أَحَدَهُمُ ٱلْمَوْتُ قَالَ إِنِّى تُبْتُ ٱلْـَٔـٰنَ وَلَا ٱلَّذِينَ يَمُوتُونَ وَهُمْ كُفَّارٌ ۚ أُو۟لَـٰٓئِكَ أَعْتَدْنَا لَهُمْ عَذَابًا أَلِيمًا','Wa laisatit tawbatu lillazeena ya\'maloonas saiyiaati hattaaa izaa hadara ahadahumul mawtu qaala innee tubtul \'aana wa lallazeena yamootoona wa hum kuffaar; ulaaa\'ika a\'tadnaa lahum \'azaaban aleemaa',18,'4:18',8,32,64,1,0,80,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(512,4,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا يَحِلُّ لَكُمْ أَن تَرِثُوا۟ ٱلنِّسَآءَ كَرْهًا ۖ وَلَا تَعْضُلُوهُنَّ لِتَذْهَبُوا۟ بِبَعْضِ مَآ ءَاتَيْتُمُوهُنَّ إِلَّآ أَن يَأْتِينَ بِفَـٰحِشَةٍ مُّبَيِّنَةٍ ۚ وَعَاشِرُوهُنَّ بِٱلْمَعْرُوفِ ۚ فَإِن كَرِهْتُمُوهُنَّ فَعَسَىٰٓ أَن تَكْرَهُوا۟ شَيْـًٔا وَيَجْعَلَ ٱللَّهُ فِيهِ خَيْرًا كَثِيرًا','Yaaa aiyuhal lazeena aamanoo laa yahillu lakum an tarisun nisaaa\'a karhan wa laa ta\'duloohunna litazhaboo biba\'di maaa aataitumoohunna illaaa ai yaateena bifaahishatim bubaiyinah; wa \'aashiroo hunna bilma\'roof; fa in karihtumoohunna fa\'asaaa an takrahoo shai\'anw wa yaj\'alal laahu feehi khairan kaseeraa',19,'4:19',8,32,64,1,0,80,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(513,4,'وَإِنْ أَرَدتُّمُ ٱسْتِبْدَالَ زَوْجٍ مَّكَانَ زَوْجٍ وَءَاتَيْتُمْ إِحْدَىٰهُنَّ قِنطَارًا فَلَا تَأْخُذُوا۟ مِنْهُ شَيْـًٔا ۚ أَتَأْخُذُونَهُۥ بُهْتَـٰنًا وَإِثْمًا مُّبِينًا','Wa in arattumustib daala zawjim makaana zawjin wa aataitum ihdaahunna qintaaran falaa taakhuzoo minhu shai\'aa; ataakhuzoonahoo buhtaannanw wa ismam mubeenaa',20,'4:20',8,32,64,1,0,81,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(514,4,'وَكَيْفَ تَأْخُذُونَهُۥ وَقَدْ أَفْضَىٰ بَعْضُكُمْ إِلَىٰ بَعْضٍ وَأَخَذْنَ مِنكُم مِّيثَـٰقًا غَلِيظًا','Wa kaifa taakhuzoonahoo wa qad afdaa ba\'dukum ilaa ba\'dinw wa akhazna minkum meesaaqan ghaleezaa',21,'4:21',8,32,64,1,0,81,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(515,4,'وَلَا تَنكِحُوا۟ مَا نَكَحَ ءَابَآؤُكُم مِّنَ ٱلنِّسَآءِ إِلَّا مَا قَدْ سَلَفَ ۚ إِنَّهُۥ كَانَ فَـٰحِشَةً وَمَقْتًا وَسَآءَ سَبِيلًا','Wa laa tankihoo maa nakaha aabaaa\'ukum minan nisaaa\'i illaa maa qad salaf; inahoo kaana faahishatanw wa maqtanw wa saaa\'a sabeelaa',22,'4:22',8,32,64,1,0,81,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(516,4,'حُرِّمَتْ عَلَيْكُمْ أُمَّهَـٰتُكُمْ وَبَنَاتُكُمْ وَأَخَوَٰتُكُمْ وَعَمَّـٰتُكُمْ وَخَـٰلَـٰتُكُمْ وَبَنَاتُ ٱلْأَخِ وَبَنَاتُ ٱلْأُخْتِ وَأُمَّهَـٰتُكُمُ ٱلَّـٰتِىٓ أَرْضَعْنَكُمْ وَأَخَوَٰتُكُم مِّنَ ٱلرَّضَـٰعَةِ وَأُمَّهَـٰتُ نِسَآئِكُمْ وَرَبَـٰٓئِبُكُمُ ٱلَّـٰتِى فِى حُجُورِكُم مِّن نِّسَآئِكُمُ ٱلَّـٰتِى دَخَلْتُم بِهِنَّ فَإِن لَّمْ تَكُونُوا۟ دَخَلْتُم بِهِنَّ فَلَا جُنَاحَ عَلَيْكُمْ وَحَلَـٰٓئِلُ أَبْنَآئِكُمُ ٱلَّذِينَ مِنْ أَصْلَـٰبِكُمْ وَأَن تَجْمَعُوا۟ بَيْنَ ٱلْأُخْتَيْنِ إِلَّا مَا قَدْ سَلَفَ ۗ إِنَّ ٱللَّهَ كَانَ غَفُورًا رَّحِيمًا','Hurrimat \'alaikum umma haatukum wa bannaatukum wa akhawaatukum wa \'ammaatukum wa khaalaatukum wa banaatul akhi wa banaatul ukhti wa ummahaatu kumul laateee arda\' nakum wa akhawaatukum minarradaa\'ati wa ummahaatu nisaaa\'ikum wa rabaaa\'i bukumul laatee fee hujoorikum min nisaaa\'ikumul laatee dakhaltum bihinna Fa il lam takoonoo dakhaltum bihina falaa junaaha \'alaikum wa halaaa\'ilu abnaaa\'ikumul lazeena min aslaabikum wa an tajma\'oo bainal ukhtaini illaa maa qad salaf; innallaaha kaana Ghafoorar Raheema',23,'4:23',8,32,65,1,0,81,4,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(517,4,'۞ وَٱلْمُحْصَنَـٰتُ مِنَ ٱلنِّسَآءِ إِلَّا مَا مَلَكَتْ أَيْمَـٰنُكُمْ ۖ كِتَـٰبَ ٱللَّهِ عَلَيْكُمْ ۚ وَأُحِلَّ لَكُم مَّا وَرَآءَ ذَٰلِكُمْ أَن تَبْتَغُوا۟ بِأَمْوَٰلِكُم مُّحْصِنِينَ غَيْرَ مُسَـٰفِحِينَ ۚ فَمَا ٱسْتَمْتَعْتُم بِهِۦ مِنْهُنَّ فَـَٔاتُوهُنَّ أُجُورَهُنَّ فَرِيضَةً ۚ وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا تَرَٰضَيْتُم بِهِۦ مِنۢ بَعْدِ ٱلْفَرِيضَةِ ۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًا','Walmuhsanaatu minan nisaaa\'i illaa maa malakat aimaanukum kitaabal laahi \'alaikum; wa uhilla lakum maa waraaa\'a zaalikum an tabtaghoo bi amwaali kum muhsineena ghaira musaa fiheen; famastamta\'tum bihee minhunna fa aatoohunna ujoorahunna fareedah; wa laa junaaha \'alaikum feemaa taraadaitum bihee mim ba\'dil fareedah; innal laaha kaana \'Aleeman Hakeemaa',24,'4:24',9,33,65,1,0,82,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(518,4,'وَمَن لَّمْ يَسْتَطِعْ مِنكُمْ طَوْلًا أَن يَنكِحَ ٱلْمُحْصَنَـٰتِ ٱلْمُؤْمِنَـٰتِ فَمِن مَّا مَلَكَتْ أَيْمَـٰنُكُم مِّن فَتَيَـٰتِكُمُ ٱلْمُؤْمِنَـٰتِ ۚ وَٱللَّهُ أَعْلَمُ بِإِيمَـٰنِكُم ۚ بَعْضُكُم مِّنۢ بَعْضٍ ۚ فَٱنكِحُوهُنَّ بِإِذْنِ أَهْلِهِنَّ وَءَاتُوهُنَّ أُجُورَهُنَّ بِٱلْمَعْرُوفِ مُحْصَنَـٰتٍ غَيْرَ مُسَـٰفِحَـٰتٍ وَلَا مُتَّخِذَٰتِ أَخْدَانٍ ۚ فَإِذَآ أُحْصِنَّ فَإِنْ أَتَيْنَ بِفَـٰحِشَةٍ فَعَلَيْهِنَّ نِصْفُ مَا عَلَى ٱلْمُحْصَنَـٰتِ مِنَ ٱلْعَذَابِ ۚ ذَٰلِكَ لِمَنْ خَشِىَ ٱلْعَنَتَ مِنكُمْ ۚ وَأَن تَصْبِرُوا۟ خَيْرٌ لَّكُمْ ۗ وَٱللَّهُ غَفُورٌ رَّحِيمٌ','Wa mal lam yastati\' minkum tawlan ai yankihal muhsanaatil mu\'minaati famimmaa malakat aimaanukum min fatayaatikumul mu\'minaat; wallaahu a\'lamu bi eemaanikum; ba\'dukum mim ba\'d; fankihoohunna bi izni ahlihinna wa aatoohunna ujoorahunna bilma\'roofi muhsanaatin ghaira musaa fihaatinw wa laa muttakhizaati akhdaan; fa izaaa uhsinna fa in ataina bifaahi shatin fa\'alaihinnna nisfu maa \'alal muhsanaati minal \'azaab; zaalika liman khashiyal \'anata minkum; wa an tasbiroo khairul lakum; wallaahu Ghafoorur Raheem',25,'4:25',9,33,65,1,0,82,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(519,4,'يُرِيدُ ٱللَّهُ لِيُبَيِّنَ لَكُمْ وَيَهْدِيَكُمْ سُنَنَ ٱلَّذِينَ مِن قَبْلِكُمْ وَيَتُوبَ عَلَيْكُمْ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ','Yureedul laahu liyubai yina lakum wa yahdiyakum sunanal lazeena min qablikum wa yatooba \'alaikum; wallaahu \'Aleemun Hakeem',26,'4:26',9,33,66,1,0,82,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(520,4,'وَٱللَّهُ يُرِيدُ أَن يَتُوبَ عَلَيْكُمْ وَيُرِيدُ ٱلَّذِينَ يَتَّبِعُونَ ٱلشَّهَوَٰتِ أَن تَمِيلُوا۟ مَيْلًا عَظِيمًا','Wallaahu yureedu ai yatooba \'alaikum wa yureedul lazeena yattabi \'oonash shahawaati an tameeloo mailan \'azeemaa',27,'4:27',9,33,66,1,0,83,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(521,4,'يُرِيدُ ٱللَّهُ أَن يُخَفِّفَ عَنكُمْ ۚ وَخُلِقَ ٱلْإِنسَـٰنُ ضَعِيفًا','Yureedul laahu ai yukhaffifa \'ankum; wa khuliqal insaanu da\'eefaa',28,'4:28',9,33,66,1,0,83,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(522,4,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَأْكُلُوٓا۟ أَمْوَٰلَكُم بَيْنَكُم بِٱلْبَـٰطِلِ إِلَّآ أَن تَكُونَ تِجَـٰرَةً عَن تَرَاضٍ مِّنكُمْ ۚ وَلَا تَقْتُلُوٓا۟ أَنفُسَكُمْ ۚ إِنَّ ٱللَّهَ كَانَ بِكُمْ رَحِيمًا','Yaaa aiyuhal lazeena aamanoo laa taakulooo amwaalakum bainakum bilbaatili \'illaaa an takoona tijaaratan \'an taraadim minkum; wa laa taqtulooo anfusakum; innal laaha kaana bikum Raheemaa',29,'4:29',9,33,66,1,0,83,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(523,4,'وَمَن يَفْعَلْ ذَٰلِكَ عُدْوَٰنًا وَظُلْمًا فَسَوْفَ نُصْلِيهِ نَارًا ۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا','Wa mai yaf\'al zaalika \'udwaananw wa zulman fasawfa nusleehi Naaraa; wa kaana zaalika \'alal laahi yaseeraa',30,'4:30',9,33,66,1,0,83,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(524,4,'إِن تَجْتَنِبُوا۟ كَبَآئِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنكُمْ سَيِّـَٔاتِكُمْ وَنُدْخِلْكُم مُّدْخَلًا كَرِيمًا','In tajtaniboo kabaaa\'ira maa tunhawna \'anhu nukaffir \'ankum saiyiaatikum wa nudkhilkum mudkhalan kareemaa',31,'4:31',9,33,66,1,0,83,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(525,4,'وَلَا تَتَمَنَّوْا۟ مَا فَضَّلَ ٱللَّهُ بِهِۦ بَعْضَكُمْ عَلَىٰ بَعْضٍ ۚ لِّلرِّجَالِ نَصِيبٌ مِّمَّا ٱكْتَسَبُوا۟ ۖ وَلِلنِّسَآءِ نَصِيبٌ مِّمَّا ٱكْتَسَبْنَ ۚ وَسْـَٔلُوا۟ ٱللَّهَ مِن فَضْلِهِۦٓ ۗ إِنَّ ٱللَّهَ كَانَ بِكُلِّ شَىْءٍ عَلِيمًا','Wa laa tatamannaw maa faddalal laahu bihee ba\'dakum \'alaa ba\'d; lirrijaali naseebum mimak tasaboo wa linnisaaa\'i naseebum mimmak tasabna; was\'alullaaha min fadlih; innal laaha kaana bikulli shai\'in \'Aleemaa',32,'4:32',9,33,66,1,0,83,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(526,4,'وَلِكُلٍّ جَعَلْنَا مَوَٰلِىَ مِمَّا تَرَكَ ٱلْوَٰلِدَانِ وَٱلْأَقْرَبُونَ ۚ وَٱلَّذِينَ عَقَدَتْ أَيْمَـٰنُكُمْ فَـَٔاتُوهُمْ نَصِيبَهُمْ ۚ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدًا','Wa likullin ja\'alnaa ma waaliya mimmaa tarakal waalidaani wal aqraboon; wallazeena \'aqadat aimaanukum fa aatoohum naseebahum; innal laaha kaana \'alaa kulli shai\'in Shaheedaa',33,'4:33',9,33,66,1,0,83,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(527,4,'ٱلرِّجَالُ قَوَّٰمُونَ عَلَى ٱلنِّسَآءِ بِمَا فَضَّلَ ٱللَّهُ بَعْضَهُمْ عَلَىٰ بَعْضٍ وَبِمَآ أَنفَقُوا۟ مِنْ أَمْوَٰلِهِمْ ۚ فَٱلصَّـٰلِحَـٰتُ قَـٰنِتَـٰتٌ حَـٰفِظَـٰتٌ لِّلْغَيْبِ بِمَا حَفِظَ ٱللَّهُ ۚ وَٱلَّـٰتِى تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَٱهْجُرُوهُنَّ فِى ٱلْمَضَاجِعِ وَٱضْرِبُوهُنَّ ۖ فَإِنْ أَطَعْنَكُمْ فَلَا تَبْغُوا۟ عَلَيْهِنَّ سَبِيلًا ۗ إِنَّ ٱللَّهَ كَانَ عَلِيًّا كَبِيرًا','Arrijaalu qawwaamoona \'alan nisaaa\'i bimaa fad dalallaahu ba\'dahum \'alaa ba\'dinw wa bimaaa anfoqoo min amwaalihim; fassaalihaatu qaanitaatun haafizaatul lil ghaibi bimaa hafizal laah; wallaatee takhaafoona nushoo zahunna fa \'izoohunna wahjuroohunna fil madaaji\'i wadriboohunna fa in ata\'nakum falaa tabghoo \'alaihinna sabeelaa; innallaaha kaana \'Aliyyan Kabeeraa',34,'4:34',9,33,67,1,0,84,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(528,4,'وَإِنْ خِفْتُمْ شِقَاقَ بَيْنِهِمَا فَٱبْعَثُوا۟ حَكَمًا مِّنْ أَهْلِهِۦ وَحَكَمًا مِّنْ أَهْلِهَآ إِن يُرِيدَآ إِصْلَـٰحًا يُوَفِّقِ ٱللَّهُ بَيْنَهُمَآ ۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا خَبِيرًا','Wa in khiftum shiqaaqa baini himaa fab\'asoo haka mam min ahlihee wa hakamam min ahlihaa; iny-yureedaaa islaah ai-yuwaffiqil laahu bainahumaa; innal laaha kaana \'Aleeman Khabeeraa',35,'4:35',9,33,67,1,0,84,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(529,4,'۞ وَٱعْبُدُوا۟ ٱللَّهَ وَلَا تُشْرِكُوا۟ بِهِۦ شَيْـًٔا ۖ وَبِٱلْوَٰلِدَيْنِ إِحْسَـٰنًا وَبِذِى ٱلْقُرْبَىٰ وَٱلْيَتَـٰمَىٰ وَٱلْمَسَـٰكِينِ وَٱلْجَارِ ذِى ٱلْقُرْبَىٰ وَٱلْجَارِ ٱلْجُنُبِ وَٱلصَّاحِبِ بِٱلْجَنۢبِ وَٱبْنِ ٱلسَّبِيلِ وَمَا مَلَكَتْ أَيْمَـٰنُكُمْ ۗ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ مُخْتَالًا فَخُورًا','Wa\'budul laaha wa laa tushrikoo bihee shai\'anw wa bilwaalidaini ihsaananw wa bizil qurbaa walyataamaa walmasaakeeni waljaari zilqurbaa waljaaril junubi wassaahibi biljambi wabnis sabeeli wa maa malakat aimaanukum; innal laaha laa yuhibbu man kaana mukhtaalan fakhooraa',36,'4:36',9,34,67,1,0,84,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(530,4,'ٱلَّذِينَ يَبْخَلُونَ وَيَأْمُرُونَ ٱلنَّاسَ بِٱلْبُخْلِ وَيَكْتُمُونَ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ ۗ وَأَعْتَدْنَا لِلْكَـٰفِرِينَ عَذَابًا مُّهِينًا','Allazeena yabkhaloona wa yaamuroonan naasa bilbukhli wa yaktumoona maaa aataahu mullaahu min fadlih; wa a\'tadnaa lilkaafireena \'azaabam muheenaa',37,'4:37',9,34,67,1,0,84,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(531,4,'وَٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ رِئَآءَ ٱلنَّاسِ وَلَا يُؤْمِنُونَ بِٱللَّهِ وَلَا بِٱلْيَوْمِ ٱلْـَٔاخِرِ ۗ وَمَن يَكُنِ ٱلشَّيْطَـٰنُ لَهُۥ قَرِينًا فَسَآءَ قَرِينًا','Wallazeena yunfiqoona amwaalahum ri\'aaa\'an naasi wa laa yu\'minoona billaahi wa laa bil Yawmil Aakhir; wa mai yakunish shaitaanu lahoo qareenan fasaaa\'a qareenaa',38,'4:38',9,34,67,1,0,85,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(532,4,'وَمَاذَا عَلَيْهِمْ لَوْ ءَامَنُوا۟ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَأَنفَقُوا۟ مِمَّا رَزَقَهُمُ ٱللَّهُ ۚ وَكَانَ ٱللَّهُ بِهِمْ عَلِيمًا','Wa maazaa \'alaihim law aamanoo billaahi wal Yawmil Aakhiri wa anfaqoo mimmaa razaqahumul laah; wa kaanallaahu bihim Aaleemaa',39,'4:39',9,34,67,1,0,85,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(533,4,'إِنَّ ٱللَّهَ لَا يَظْلِمُ مِثْقَالَ ذَرَّةٍ ۖ وَإِن تَكُ حَسَنَةً يُضَـٰعِفْهَا وَيُؤْتِ مِن لَّدُنْهُ أَجْرًا عَظِيمًا','Innal laaha laa yazlimu misqaala zarratinw wa in taku hasanatany yudaa\'ifhaa wa yu\'ti mil ladunhu ajran \'azeemaa',40,'4:40',9,34,67,1,0,85,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(534,4,'فَكَيْفَ إِذَا جِئْنَا مِن كُلِّ أُمَّةٍۭ بِشَهِيدٍ وَجِئْنَا بِكَ عَلَىٰ هَـٰٓؤُلَآءِ شَهِيدًا','Fakaifa izaa ji\'naa min kulli ummatim bishaheedinw wa ji\'naabika \'alaa haaa\'ulaaa \'i Shaheedan',41,'4:41',9,34,67,1,0,85,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(535,4,'يَوْمَئِذٍ يَوَدُّ ٱلَّذِينَ كَفَرُوا۟ وَعَصَوُا۟ ٱلرَّسُولَ لَوْ تُسَوَّىٰ بِهِمُ ٱلْأَرْضُ وَلَا يَكْتُمُونَ ٱللَّهَ حَدِيثًا','Yawma\'iziny yawad dullazeena kafaroo wa\'asawur Rasoola law tusawwaa bihimul ardu wa laa yaktumoonal laaha hadeesaa',42,'4:42',9,34,67,1,0,85,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(536,4,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقْرَبُوا۟ ٱلصَّلَوٰةَ وَأَنتُمْ سُكَـٰرَىٰ حَتَّىٰ تَعْلَمُوا۟ مَا تَقُولُونَ وَلَا جُنُبًا إِلَّا عَابِرِى سَبِيلٍ حَتَّىٰ تَغْتَسِلُوا۟ ۚ وَإِن كُنتُم مَّرْضَىٰٓ أَوْ عَلَىٰ سَفَرٍ أَوْ جَآءَ أَحَدٌ مِّنكُم مِّنَ ٱلْغَآئِطِ أَوْ لَـٰمَسْتُمُ ٱلنِّسَآءَ فَلَمْ تَجِدُوا۟ مَآءً فَتَيَمَّمُوا۟ صَعِيدًا طَيِّبًا فَٱمْسَحُوا۟ بِوُجُوهِكُمْ وَأَيْدِيكُمْ ۗ إِنَّ ٱللَّهَ كَانَ عَفُوًّا غَفُورًا','yaaa aiyuhal lazeena aamanoo laa taqrabus Salaata wa antum sukaaraa hatta ta\'lamoo ma taqooloona wa la junuban illaa \'aabiree sabeelin hatta taghtasiloo; wa in kuntum mardaaa aw \'alaa safarin aw jaaa\'a ahadum minkum minal ghaaa\'iti aw laamastumun nisaaa\'a falam tajidoo maaa\'an fatayam mamoo sa\'eedan taiyiban famsahoo biwujoohikum wa aideekum; innal laaha kaana \'Afuwwan Ghafooraa',43,'4:43',9,34,68,1,0,85,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(537,4,'أَلَمْ تَرَ إِلَى ٱلَّذِينَ أُوتُوا۟ نَصِيبًا مِّنَ ٱلْكِتَـٰبِ يَشْتَرُونَ ٱلضَّلَـٰلَةَ وَيُرِيدُونَ أَن تَضِلُّوا۟ ٱلسَّبِيلَ','Alam tara ilal lazeena ootoo naseebam minal Kitaabi yashtaroonad dalaalata wa yureedoona an tadillus sabeel',44,'4:44',9,34,68,1,0,85,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(538,4,'وَٱللَّهُ أَعْلَمُ بِأَعْدَآئِكُمْ ۚ وَكَفَىٰ بِٱللَّهِ وَلِيًّا وَكَفَىٰ بِٱللَّهِ نَصِيرًا','Wallaahu a\'lamu bi a\'daaa\'i-kum; wa kafaa billaahi waliyyanw wa kafaa billaahi naseera',45,'4:45',9,34,68,1,0,86,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(539,4,'مِّنَ ٱلَّذِينَ هَادُوا۟ يُحَرِّفُونَ ٱلْكَلِمَ عَن مَّوَاضِعِهِۦ وَيَقُولُونَ سَمِعْنَا وَعَصَيْنَا وَٱسْمَعْ غَيْرَ مُسْمَعٍ وَرَٰعِنَا لَيًّۢا بِأَلْسِنَتِهِمْ وَطَعْنًا فِى ٱلدِّينِ ۚ وَلَوْ أَنَّهُمْ قَالُوا۟ سَمِعْنَا وَأَطَعْنَا وَٱسْمَعْ وَٱنظُرْنَا لَكَانَ خَيْرًا لَّهُمْ وَأَقْوَمَ وَلَـٰكِن لَّعَنَهُمُ ٱللَّهُ بِكُفْرِهِمْ فَلَا يُؤْمِنُونَ إِلَّا قَلِيلًا','Minal lazeena haadoo yuharrifoonal Kalima \'am mawaadi\'ihee wa yaqooloona sami\'naa wa \'asainaa wasma\' ghaira musma\'inw wa raa\'inaa laiyam bi alsinatihim wa ta\'nan fiddeen; wa law annahum qaaloo sami\'naa wa ata\'naa wasma\' wanzurnaa lakaana khairal lahum wa aqwama wa laakil la \'\'anahumul laahu bikufrihim falaa yu\'minoona illaa qaleela',46,'4:46',9,34,68,1,0,86,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(540,4,'يَـٰٓأَيُّهَا ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ ءَامِنُوا۟ بِمَا نَزَّلْنَا مُصَدِّقًا لِّمَا مَعَكُم مِّن قَبْلِ أَن نَّطْمِسَ وُجُوهًا فَنَرُدَّهَا عَلَىٰٓ أَدْبَارِهَآ أَوْ نَلْعَنَهُمْ كَمَا لَعَنَّآ أَصْحَـٰبَ ٱلسَّبْتِ ۚ وَكَانَ أَمْرُ ٱللَّهِ مَفْعُولًا','yaaa aiyuha lazeena ootu Kitaaba aaminoo bimaa nazzalnaa musadiqallimaa ma\'akum min qabli an natmisa wujoohan fanaruddahaa \'alaaa adbaarihaaa aw nal\'anahum kamaa la\'annaaa Ashaabas Sabt; wa kaana amrul laahi maf\'oolaa',47,'4:47',9,34,68,1,0,86,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(541,4,'إِنَّ ٱللَّهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِۦ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُ ۚ وَمَن يُشْرِكْ بِٱللَّهِ فَقَدِ ٱفْتَرَىٰٓ إِثْمًا عَظِيمًا','Innal laaha laa yaghfiru ai yushraka bihee wa yaghfiru maa doona zaalika limai yashaaa\'; wa mai yushrik billaahi faqadif taraaa isman \'azeemaa',48,'4:48',9,34,68,1,0,86,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(542,4,'أَلَمْ تَرَ إِلَى ٱلَّذِينَ يُزَكُّونَ أَنفُسَهُم ۚ بَلِ ٱللَّهُ يُزَكِّى مَن يَشَآءُ وَلَا يُظْلَمُونَ فَتِيلًا','Alam tara ilal lazeena yuzakkoona anfusahum; balil laahu yuzakkee mai yashaaa\'u wa laa yuzlamoona fateelaa',49,'4:49',9,34,68,1,0,86,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(543,4,'ٱنظُرْ كَيْفَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ ۖ وَكَفَىٰ بِهِۦٓ إِثْمًا مُّبِينًا','Unzur kaifa yaftaroona \'alal laahil kazib, wakafaa biheee ismamm mubeenaa',50,'4:50',9,34,68,1,0,86,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(544,4,'أَلَمْ تَرَ إِلَى ٱلَّذِينَ أُوتُوا۟ نَصِيبًا مِّنَ ٱلْكِتَـٰبِ يُؤْمِنُونَ بِٱلْجِبْتِ وَٱلطَّـٰغُوتِ وَيَقُولُونَ لِلَّذِينَ كَفَرُوا۟ هَـٰٓؤُلَآءِ أَهْدَىٰ مِنَ ٱلَّذِينَ ءَامَنُوا۟ سَبِيلًا','Alam tara ilal lazeena \'ootoo naseebam minal kitaabi yu\'minoona bil Jibti wat Taaghooti wa yaqooloona lillazeena kafaroo haaa ulaaa\'i ahdaa minal lazeena aamanoo sabeelaa',51,'4:51',9,34,69,1,0,86,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(545,4,'أُو۟لَـٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُ ۖ وَمَن يَلْعَنِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ نَصِيرًا','Ulaaa\'ikal lazeena la\'ana humul laahu wa mai yal\'anil laahu falan tajida lahoo naseeraa',52,'4:52',9,34,69,1,0,87,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(546,4,'أَمْ لَهُمْ نَصِيبٌ مِّنَ ٱلْمُلْكِ فَإِذًا لَّا يُؤْتُونَ ٱلنَّاسَ نَقِيرًا','Am lahum naseebum minal mulki fa izal laa yu\'toonan naasa naqeeraa',53,'4:53',9,34,69,1,0,87,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(547,4,'أَمْ يَحْسُدُونَ ٱلنَّاسَ عَلَىٰ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ ۖ فَقَدْ ءَاتَيْنَآ ءَالَ إِبْرَٰهِيمَ ٱلْكِتَـٰبَ وَٱلْحِكْمَةَ وَءَاتَيْنَـٰهُم مُّلْكًا عَظِيمًا','Am yahsudoonan naasa \'alaa maaa aataahumul laahu min fadlihee faqad aatainaaa Aala Ibraaheemal Kitaaba wal Hikmata wa aatainaahum mulkan \'azeemaa',54,'4:54',9,34,69,1,0,87,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(548,4,'فَمِنْهُم مَّنْ ءَامَنَ بِهِۦ وَمِنْهُم مَّن صَدَّ عَنْهُ ۚ وَكَفَىٰ بِجَهَنَّمَ سَعِيرًا','Faminhum man aamana bihee wa minhum man sadda \'anh; wa kafaa bi Jahannama sa\'eeraa',55,'4:55',9,34,69,1,0,87,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(549,4,'إِنَّ ٱلَّذِينَ كَفَرُوا۟ بِـَٔايَـٰتِنَا سَوْفَ نُصْلِيهِمْ نَارًا كُلَّمَا نَضِجَتْ جُلُودُهُم بَدَّلْنَـٰهُمْ جُلُودًا غَيْرَهَا لِيَذُوقُوا۟ ٱلْعَذَابَ ۗ إِنَّ ٱللَّهَ كَانَ عَزِيزًا حَكِيمًا','Innal lazeena kafaroo bi Aayaatinaa sawfa nusleehim Naaran kullamaa nadijat julooduhum baddalnaahum juloodan ghairahaa liyazooqul \'azaab; innallaaha kaana \'Azeezan Hakeemaa',56,'4:56',9,34,69,1,0,87,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(550,4,'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ سَنُدْخِلُهُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَآ أَبَدًا ۖ لَّهُمْ فِيهَآ أَزْوَٰجٌ مُّطَهَّرَةٌ ۖ وَنُدْخِلُهُمْ ظِلًّا ظَلِيلًا','Wallazeena aamanoo wa \'amilus saalihaati sanud khiluum jannaatin tajree min tahtihal anhaaru khaalideena feehaaa abadaa, lahum feehaaa azwaajum mutahharatun wa nudkhiluhum zillan zaleelaa',57,'4:57',9,34,69,1,0,87,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(551,4,'۞ إِنَّ ٱللَّهَ يَأْمُرُكُمْ أَن تُؤَدُّوا۟ ٱلْأَمَـٰنَـٰتِ إِلَىٰٓ أَهْلِهَا وَإِذَا حَكَمْتُم بَيْنَ ٱلنَّاسِ أَن تَحْكُمُوا۟ بِٱلْعَدْلِ ۚ إِنَّ ٱللَّهَ نِعِمَّا يَعِظُكُم بِهِۦٓ ۗ إِنَّ ٱللَّهَ كَانَ سَمِيعًۢا بَصِيرًا','Innal laaha yaamurukum an tu\'addul amaanaati ilaaa ahlihaa wa izaa hakamtum bainan naasi an tahkumoo bil \'adl; innal laaha yaamurukum an tu\'addul amaanaati ilaaa ahlihaa wa izaa hakamtum bainan naasi an tahkumoo bil \'adl; innal laaha ni\'immaa ya\'izukum bih; innal laaha kaana Samee\'am Baseera',58,'4:58',9,35,69,1,0,87,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(552,4,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَأُو۟لِى ٱلْأَمْرِ مِنكُمْ ۖ فَإِن تَنَـٰزَعْتُمْ فِى شَىْءٍ فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ إِن كُنتُمْ تُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ ۚ ذَٰلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا','Yaaa aiyuhal lazeena aamanooo atee\'ul laaha wa atee\'ur Rasoola wa ulil amri minkum fa in tanaaza\'tum fee shai\'in faruddoohu ilal laahi war Rasooli in kuntum tu\'minoona billaahi wal yawmil Aakhir; zaalika khairunw wa ahsanu taaweelaa',59,'4:59',9,35,69,1,0,87,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(553,4,'أَلَمْ تَرَ إِلَى ٱلَّذِينَ يَزْعُمُونَ أَنَّهُمْ ءَامَنُوا۟ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ يُرِيدُونَ أَن يَتَحَاكَمُوٓا۟ إِلَى ٱلطَّـٰغُوتِ وَقَدْ أُمِرُوٓا۟ أَن يَكْفُرُوا۟ بِهِۦ وَيُرِيدُ ٱلشَّيْطَـٰنُ أَن يُضِلَّهُمْ ضَلَـٰلًۢا بَعِيدًا','Alam tara ilal lazeena yaz\'umoona annahum aarmanoo bimaa unzilaa ilaika wa maaa unzila min qablika yureedoona ai yatahaakamooo ilat Taaghooti wa qad umirooo ai yakfuroo bih, wa yureedush Shaitaanu ai yudillahum dalaalam ba\'eedaa',60,'4:60',9,35,70,1,0,88,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(554,4,'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ رَأَيْتَ ٱلْمُنَـٰفِقِينَ يَصُدُّونَ عَنكَ صُدُودًا','Wa izaa qeela lahum ta\'aalaw ilaa maaa anzalallaahu wa ilar Rasooli ra aital munaafiqeena yasuddoona \'anka sudoodaa',61,'4:61',9,35,70,1,0,88,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(555,4,'فَكَيْفَ إِذَآ أَصَـٰبَتْهُم مُّصِيبَةٌۢ بِمَا قَدَّمَتْ أَيْدِيهِمْ ثُمَّ جَآءُوكَ يَحْلِفُونَ بِٱللَّهِ إِنْ أَرَدْنَآ إِلَّآ إِحْسَـٰنًا وَتَوْفِيقًا','Fakaifa izaaa asaabathum museebatum summa jaaa\'ooka yahlifoona billaahi in aradnaaa illaaa ihsaananw wa tawfeeqaa',62,'4:62',9,35,70,1,0,88,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(556,4,'أُو۟لَـٰٓئِكَ ٱلَّذِينَ يَعْلَمُ ٱللَّهُ مَا فِى قُلُوبِهِمْ فَأَعْرِضْ عَنْهُمْ وَعِظْهُمْ وَقُل لَّهُمْ فِىٓ أَنفُسِهِمْ قَوْلًۢا بَلِيغًا','Ulaaa\'ikal lazeena ya\'la mullaahu maa fee quloobihim fa a\'rid \'anhum wa \'izhum wa qul lahum feee anfusihim qawlam baleeghaa',63,'4:63',9,35,70,1,0,88,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(557,4,'وَمَآ أَرْسَلْنَا مِن رَّسُولٍ إِلَّا لِيُطَاعَ بِإِذْنِ ٱللَّهِ ۚ وَلَوْ أَنَّهُمْ إِذ ظَّلَمُوٓا۟ أَنفُسَهُمْ جَآءُوكَ فَٱسْتَغْفَرُوا۟ ٱللَّهَ وَٱسْتَغْفَرَ لَهُمُ ٱلرَّسُولُ لَوَجَدُوا۟ ٱللَّهَ تَوَّابًا رَّحِيمًا','Wa maa arsalnaa mir Rasoolin illaa liyutaa\'a bi iznil laah; wa law annahum \'iz zalamooo anfusahum jaaa\'ooka fastaghfarul laaha wastaghfara lahumur Rasoolu la wajadul laaha Tawwaabar Raheemaa',64,'4:64',9,35,70,1,0,88,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(558,4,'فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لَا يَجِدُوا۟ فِىٓ أَنفُسِهِمْ حَرَجًا مِّمَّا قَضَيْتَ وَيُسَلِّمُوا۟ تَسْلِيمًا','Falaa wa Rabbika laa yu\'minoona hattaa yuhakkimooka fe emaa shajara bainahum summa laa yajidoo fee anfusihim harajam mimmaa qadaita wa yusal limoo tasleemaa',65,'4:65',9,35,70,1,0,88,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(559,4,'وَلَوْ أَنَّا كَتَبْنَا عَلَيْهِمْ أَنِ ٱقْتُلُوٓا۟ أَنفُسَكُمْ أَوِ ٱخْرُجُوا۟ مِن دِيَـٰرِكُم مَّا فَعَلُوهُ إِلَّا قَلِيلٌ مِّنْهُمْ ۖ وَلَوْ أَنَّهُمْ فَعَلُوا۟ مَا يُوعَظُونَ بِهِۦ لَكَانَ خَيْرًا لَّهُمْ وَأَشَدَّ تَثْبِيتًا','Wa law annaa katabnaa \'alaihim aniq tulooo anfusakum awikh rujoo min diyaarikum maa fa\'aloohu illaa qaleelum minhum wa law annahum fa\'aloo maa yoo\'azoona bihee lakaana khairal lahum wa ashadda tasbeetaa',66,'4:66',9,35,70,1,0,89,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(560,4,'وَإِذًا لَّـَٔاتَيْنَـٰهُم مِّن لَّدُنَّآ أَجْرًا عَظِيمًا','Wa izal la aatainaahum mil ladunnaaa ajran \'azeemaa',67,'4:67',9,35,70,1,0,89,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(561,4,'وَلَهَدَيْنَـٰهُمْ صِرَٰطًا مُّسْتَقِيمًا','Wa lahadainaahum Siraatam mustaqeemaa',68,'4:68',9,35,70,1,0,89,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(562,4,'وَمَن يُطِعِ ٱللَّهَ وَٱلرَّسُولَ فَأُو۟لَـٰٓئِكَ مَعَ ٱلَّذِينَ أَنْعَمَ ٱللَّهُ عَلَيْهِم مِّنَ ٱلنَّبِيِّـۧنَ وَٱلصِّدِّيقِينَ وَٱلشُّهَدَآءِ وَٱلصَّـٰلِحِينَ ۚ وَحَسُنَ أُو۟لَـٰٓئِكَ رَفِيقًا','Wa many-yuti\'il laaha war Rasoola fa ulaaa\'ika ma\'al lazeena an\'amal laahu \'alaihim minan nabiyyeena wassiddeeqeena washshuhadaaa\'i wassaaliheen; wa hasuna ulaaa\'ika rafeeqaa',69,'4:69',9,35,70,1,0,89,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(563,4,'ذَٰلِكَ ٱلْفَضْلُ مِنَ ٱللَّهِ ۚ وَكَفَىٰ بِٱللَّهِ عَلِيمًا','Zaalikal fadlu minal laah; wa kafaa billaahi \'Aleemaa',70,'4:70',9,35,70,1,0,89,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(564,4,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ خُذُوا۟ حِذْرَكُمْ فَٱنفِرُوا۟ ثُبَاتٍ أَوِ ٱنفِرُوا۟ جَمِيعًا','Yaaa aiyuhal lazeena aamanoo khuzoo hizrakum fanfiroo subaain awin firoo jamee\'aa',71,'4:71',9,35,71,1,0,89,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(565,4,'وَإِنَّ مِنكُمْ لَمَن لَّيُبَطِّئَنَّ فَإِنْ أَصَـٰبَتْكُم مُّصِيبَةٌ قَالَ قَدْ أَنْعَمَ ٱللَّهُ عَلَىَّ إِذْ لَمْ أَكُن مَّعَهُمْ شَهِيدًا','Wa inna minkum lamal la yubatti\'anna fa in asaabatkum museebatun qaala qad an\'amal laahu \'alaiya iz lam akum ma\'ahum shaheeda',72,'4:72',9,35,71,1,0,89,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(566,4,'وَلَئِنْ أَصَـٰبَكُمْ فَضْلٌ مِّنَ ٱللَّهِ لَيَقُولَنَّ كَأَن لَّمْ تَكُنۢ بَيْنَكُمْ وَبَيْنَهُۥ مَوَدَّةٌ يَـٰلَيْتَنِى كُنتُ مَعَهُمْ فَأَفُوزَ فَوْزًا عَظِيمًا','Wa la\'in asaabakum fadlum minal laahi la yaqoolanna ka al lam takum bainakum wa bainahoo mawaddatuny yaa laitanee kuntu ma\'ahum fa afooza fawzan \'azeemaa',73,'4:73',9,35,71,1,0,89,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(567,4,'۞ فَلْيُقَـٰتِلْ فِى سَبِيلِ ٱللَّهِ ٱلَّذِينَ يَشْرُونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا بِٱلْـَٔاخِرَةِ ۚ وَمَن يُقَـٰتِلْ فِى سَبِيلِ ٱللَّهِ فَيُقْتَلْ أَوْ يَغْلِبْ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا','Falyuqaatil fee sabeelil laahil lazeena yashroonal hayaatad dunyaa bil Aakhirah; wa many-uqaatil fee sabeelil laahi fa yuqtal aw yaghlib fasawfa nu\'teehi ajran \'azeemaa',74,'4:74',9,36,71,1,0,89,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(568,4,'وَمَا لَكُمْ لَا تُقَـٰتِلُونَ فِى سَبِيلِ ٱللَّهِ وَٱلْمُسْتَضْعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلْوِلْدَٰنِ ٱلَّذِينَ يَقُولُونَ رَبَّنَآ أَخْرِجْنَا مِنْ هَـٰذِهِ ٱلْقَرْيَةِ ٱلظَّالِمِ أَهْلُهَا وَٱجْعَل لَّنَا مِن لَّدُنكَ وَلِيًّا وَٱجْعَل لَّنَا مِن لَّدُنكَ نَصِيرًا','Wa maa lakum laa tuqaatiloona fee sabeelil laahi walmustad\'afeena minar rijaali wannisaaa\'i walwildaanil lazeena yaqooloona Rabbanaaa akhrijnaa min haazihil qaryatiz zaalimi ahluhaa waj\'al lanaa mil ladunka waliyanw waj\'al lanaa mil ladunka naseeraa',75,'4:75',9,36,71,1,0,90,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(569,4,'ٱلَّذِينَ ءَامَنُوا۟ يُقَـٰتِلُونَ فِى سَبِيلِ ٱللَّهِ ۖ وَٱلَّذِينَ كَفَرُوا۟ يُقَـٰتِلُونَ فِى سَبِيلِ ٱلطَّـٰغُوتِ فَقَـٰتِلُوٓا۟ أَوْلِيَآءَ ٱلشَّيْطَـٰنِ ۖ إِنَّ كَيْدَ ٱلشَّيْطَـٰنِ كَانَ ضَعِيفًا','Allazeena aamanoo yuqaatiloona fee sabeelil laahi wallazeena kafaroo yuqaatiloona fee sabeelit Taaghoot faqaatiloo awliyaaa\'ash Shaitaan; inna kaidash Shairaani kaana da\'eefa',76,'4:76',9,36,71,1,0,90,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(570,4,'أَلَمْ تَرَ إِلَى ٱلَّذِينَ قِيلَ لَهُمْ كُفُّوٓا۟ أَيْدِيَكُمْ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ فَلَمَّا كُتِبَ عَلَيْهِمُ ٱلْقِتَالُ إِذَا فَرِيقٌ مِّنْهُمْ يَخْشَوْنَ ٱلنَّاسَ كَخَشْيَةِ ٱللَّهِ أَوْ أَشَدَّ خَشْيَةً ۚ وَقَالُوا۟ رَبَّنَا لِمَ كَتَبْتَ عَلَيْنَا ٱلْقِتَالَ لَوْلَآ أَخَّرْتَنَآ إِلَىٰٓ أَجَلٍ قَرِيبٍ ۗ قُلْ مَتَـٰعُ ٱلدُّنْيَا قَلِيلٌ وَٱلْـَٔاخِرَةُ خَيْرٌ لِّمَنِ ٱتَّقَىٰ وَلَا تُظْلَمُونَ فَتِيلًا','Alam tara ilal lazeena qeela lahum kuffooo aidiyakum wa aqeemus Salaata w aaatuz Zakaata falammaa kutiba \'alaihimul qitaalu izaa fareequm minhum yakhshawnnan naasa kakhashyatil laahi aw ashadda khashyah; wa qaaloo Rabbanaa lima katabta \'alainal qitaala law laaa akhkhartanaa ilaaa ajalin qareeb; qul mataa\'ud dunyaa qaleelunw wal Aakhiratu khairul limanit taqaa wa laa tuzlamoona fateelaa',77,'4:77',9,36,72,1,0,90,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(571,4,'أَيْنَمَا تَكُونُوا۟ يُدْرِككُّمُ ٱلْمَوْتُ وَلَوْ كُنتُمْ فِى بُرُوجٍ مُّشَيَّدَةٍ ۗ وَإِن تُصِبْهُمْ حَسَنَةٌ يَقُولُوا۟ هَـٰذِهِۦ مِنْ عِندِ ٱللَّهِ ۖ وَإِن تُصِبْهُمْ سَيِّئَةٌ يَقُولُوا۟ هَـٰذِهِۦ مِنْ عِندِكَ ۚ قُلْ كُلٌّ مِّنْ عِندِ ٱللَّهِ ۖ فَمَالِ هَـٰٓؤُلَآءِ ٱلْقَوْمِ لَا يَكَادُونَ يَفْقَهُونَ حَدِيثًا','Ainamaa takoonoo yudrikkumul mawtu wa law kuntum fee buroojim mushai yadah; wa in tusibhum hasanatuny yaqooloo haazihee min indil laahi wa in tusibhum saiyi\'atuny yaqooloo haazihee min \'indik; qul kullum min \'indillaahi famaa lihaaa \'ulaaa\'il qawmi laa yakkaadoona yafqahoona hadeesaa',78,'4:78',9,36,72,1,0,90,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(572,4,'مَّآ أَصَابَكَ مِنْ حَسَنَةٍ فَمِنَ ٱللَّهِ ۖ وَمَآ أَصَابَكَ مِن سَيِّئَةٍ فَمِن نَّفْسِكَ ۚ وَأَرْسَلْنَـٰكَ لِلنَّاسِ رَسُولًا ۚ وَكَفَىٰ بِٱللَّهِ شَهِيدًا','Maaa asaabaka min hasanatin faminal laahi wa maaa asaaabaka min saiyi\'atin famin nafsik; wa arsalnaaka linnaasi Rasoolaa; wa kafaa billaahi Shaheedaa',79,'4:79',9,36,72,1,0,90,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(573,4,'مَّن يُطِعِ ٱلرَّسُولَ فَقَدْ أَطَاعَ ٱللَّهَ ۖ وَمَن تَوَلَّىٰ فَمَآ أَرْسَلْنَـٰكَ عَلَيْهِمْ حَفِيظًا','Man yuti\'ir Rasoola faqad ataa\'al laaha wa man tawallaa famaaa arsalnaaka \'alaihim hafeezaa',80,'4:80',9,36,72,1,0,91,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(574,4,'وَيَقُولُونَ طَاعَةٌ فَإِذَا بَرَزُوا۟ مِنْ عِندِكَ بَيَّتَ طَآئِفَةٌ مِّنْهُمْ غَيْرَ ٱلَّذِى تَقُولُ ۖ وَٱللَّهُ يَكْتُبُ مَا يُبَيِّتُونَ ۖ فَأَعْرِضْ عَنْهُمْ وَتَوَكَّلْ عَلَى ٱللَّهِ ۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا','Wa yaqooloona taa\'antun fa izaa barazoo min \'indika baiyata taaa\'ifatum minhum ghairal lazee taqoolu wallaahu yaktubu maa yubaiyitoona faa\'rid \'anhum wa tawakkal \'alal laah; wa kafaa billaahi Wakeelaa',81,'4:81',9,36,72,1,0,91,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(575,4,'أَفَلَا يَتَدَبَّرُونَ ٱلْقُرْءَانَ ۚ وَلَوْ كَانَ مِنْ عِندِ غَيْرِ ٱللَّهِ لَوَجَدُوا۟ فِيهِ ٱخْتِلَـٰفًا كَثِيرًا','Afalaa yatadabbaroonal Qur\'aan; wa law kaana min \'indi ghairil laahi la wajadoo fee hikh tilaafan kaseeraa',82,'4:82',9,36,72,1,0,91,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(576,4,'وَإِذَا جَآءَهُمْ أَمْرٌ مِّنَ ٱلْأَمْنِ أَوِ ٱلْخَوْفِ أَذَاعُوا۟ بِهِۦ ۖ وَلَوْ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰٓ أُو۟لِى ٱلْأَمْرِ مِنْهُمْ لَعَلِمَهُ ٱلَّذِينَ يَسْتَنۢبِطُونَهُۥ مِنْهُمْ ۗ وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ لَٱتَّبَعْتُمُ ٱلشَّيْطَـٰنَ إِلَّا قَلِيلًا','Wa izaa jaaa\'ahum amrum minal amni awil kkhawfi azaa\'oo bihee wa law raddoohu ilar Rasooli wa ilaaa ulil amri minhum la\'alimahul lazeena yastambitoonahoo minhum; wa law laa fadlul laahi \'alaikum wa rahmatuhoo lattaba\'tumush Shaitaana illaa qaleelaa',83,'4:83',9,36,72,1,0,91,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(577,4,'فَقَـٰتِلْ فِى سَبِيلِ ٱللَّهِ لَا تُكَلَّفُ إِلَّا نَفْسَكَ ۚ وَحَرِّضِ ٱلْمُؤْمِنِينَ ۖ عَسَى ٱللَّهُ أَن يَكُفَّ بَأْسَ ٱلَّذِينَ كَفَرُوا۟ ۚ وَٱللَّهُ أَشَدُّ بَأْسًا وَأَشَدُّ تَنكِيلًا','Faqaatil fee sabeelil laahi laa tukallafu illa nafsaka wa harridil mu\'mineena \'asallaahu ai yakuffa baasallazeena kafaroo; wallaahu ashaddu baasanw wa ashaaddu tanakeelaa',84,'4:84',9,36,72,1,0,91,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(578,4,'مَّن يَشْفَعْ شَفَـٰعَةً حَسَنَةً يَكُن لَّهُۥ نَصِيبٌ مِّنْهَا ۖ وَمَن يَشْفَعْ شَفَـٰعَةً سَيِّئَةً يَكُن لَّهُۥ كِفْلٌ مِّنْهَا ۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ مُّقِيتًا','Mai yashfa\' shafaa\'atan hasanatay yakul lahoo naseebum minhaa wa mai yashfa\' shafaa\'tan saiyi\'atanny-yakul lahoo kiflum minhaa; wa kaanal laahu \'alaa kulli shai\'im Muqeetaa',85,'4:85',9,36,72,1,0,91,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(579,4,'وَإِذَا حُيِّيتُم بِتَحِيَّةٍ فَحَيُّوا۟ بِأَحْسَنَ مِنْهَآ أَوْ رُدُّوهَآ ۗ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍ حَسِيبًا','Wa izaa huyyeetum bitahiy yatin fahaiyoo bi ahsana minhaaa aw ruddoohaa; innal laaha kaana \'alaa kulli shai\'in Haseeba',86,'4:86',9,36,72,1,0,91,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(580,4,'ٱللَّهُ لَآ إِلَـٰهَ إِلَّا هُوَ ۚ لَيَجْمَعَنَّكُمْ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ لَا رَيْبَ فِيهِ ۗ وَمَنْ أَصْدَقُ مِنَ ٱللَّهِ حَدِيثًا','Allaahu laaa ilaaha illaa huwa la yajma\'annakum ilaa Yawmil Qiyaamati laa raiba feeh; wa man asdaqu mminallaahi hadeesaa',87,'4:87',9,36,72,1,0,92,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(581,4,'۞ فَمَا لَكُمْ فِى ٱلْمُنَـٰفِقِينَ فِئَتَيْنِ وَٱللَّهُ أَرْكَسَهُم بِمَا كَسَبُوٓا۟ ۚ أَتُرِيدُونَ أَن تَهْدُوا۟ مَنْ أَضَلَّ ٱللَّهُ ۖ وَمَن يُضْلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلًا','Famaa lakum filmuna afiqeena fi\'ataini wallaahu arkasahum bimaa kasaboo; atureedoona an tahdoo man adallal laahu wa mmai yudlilil laahu falan tajida lahoo sabeelaa',88,'4:88',10,37,73,1,0,92,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(582,4,'وَدُّوا۟ لَوْ تَكْفُرُونَ كَمَا كَفَرُوا۟ فَتَكُونُونَ سَوَآءً ۖ فَلَا تَتَّخِذُوا۟ مِنْهُمْ أَوْلِيَآءَ حَتَّىٰ يُهَاجِرُوا۟ فِى سَبِيلِ ٱللَّهِ ۚ فَإِن تَوَلَّوْا۟ فَخُذُوهُمْ وَٱقْتُلُوهُمْ حَيْثُ وَجَدتُّمُوهُمْ ۖ وَلَا تَتَّخِذُوا۟ مِنْهُمْ وَلِيًّا وَلَا نَصِيرًا','Wadoo law takfuroona kamaa kafaroo fatakoonoona sawaaa\'an falaa tattakhizoo minhum awliyaaa\'a hattaa yuhaajiroo fee sabeelil laah; fa in tawallaw fa khuzoohum waqtuloohum haisu wajat tumoohum wa laa tattakhizoo minhum waliyyanw wa laa naseeraa',89,'4:89',10,37,73,1,0,92,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(583,4,'إِلَّا ٱلَّذِينَ يَصِلُونَ إِلَىٰ قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُم مِّيثَـٰقٌ أَوْ جَآءُوكُمْ حَصِرَتْ صُدُورُهُمْ أَن يُقَـٰتِلُوكُمْ أَوْ يُقَـٰتِلُوا۟ قَوْمَهُمْ ۚ وَلَوْ شَآءَ ٱللَّهُ لَسَلَّطَهُمْ عَلَيْكُمْ فَلَقَـٰتَلُوكُمْ ۚ فَإِنِ ٱعْتَزَلُوكُمْ فَلَمْ يُقَـٰتِلُوكُمْ وَأَلْقَوْا۟ إِلَيْكُمُ ٱلسَّلَمَ فَمَا جَعَلَ ٱللَّهُ لَكُمْ عَلَيْهِمْ سَبِيلًا','Illal lazeena yasiloona ilaa qawmim binakum wa bainahum meesaaqun aw jaaa\'ookum hasirat sudooruhum ai yuqaatilookum aw yuqaatiloo qawmahum, wa law shaaa\'al laahu lasallatahum \'alaikum falaqaatalookum; fa ini\' tazalookum falam yuqaatilookum wa alqaw ilaikumus salama famaa ja\'alal laahu lakum \'alaihim sabeelaa',90,'4:90',10,37,73,1,0,92,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(584,4,'سَتَجِدُونَ ءَاخَرِينَ يُرِيدُونَ أَن يَأْمَنُوكُمْ وَيَأْمَنُوا۟ قَوْمَهُمْ كُلَّ مَا رُدُّوٓا۟ إِلَى ٱلْفِتْنَةِ أُرْكِسُوا۟ فِيهَا ۚ فَإِن لَّمْ يَعْتَزِلُوكُمْ وَيُلْقُوٓا۟ إِلَيْكُمُ ٱلسَّلَمَ وَيَكُفُّوٓا۟ أَيْدِيَهُمْ فَخُذُوهُمْ وَٱقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ ۚ وَأُو۟لَـٰٓئِكُمْ جَعَلْنَا لَكُمْ عَلَيْهِمْ سُلْطَـٰنًا مُّبِينًا','Satajidoona aakhareena yureedoona ai yaamanookum wa yaamanoo qawmahum kullamaa ruddooo ilal itnati urkisoo feehaa; fa il lam ya\'tazilookum wa yulqooo ilai kumus salama wa yakuffooo aidiyahum fakhuzoohum waqtuloohum haisu saqif tumoohum; wa ulaaa\'ikum ja\'alnaa lakum \'alaihim sultaanam mubeenaa',91,'4:91',10,37,73,1,0,92,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(585,4,'وَمَا كَانَ لِمُؤْمِنٍ أَن يَقْتُلَ مُؤْمِنًا إِلَّا خَطَـًٔا ۚ وَمَن قَتَلَ مُؤْمِنًا خَطَـًٔا فَتَحْرِيرُ رَقَبَةٍ مُّؤْمِنَةٍ وَدِيَةٌ مُّسَلَّمَةٌ إِلَىٰٓ أَهْلِهِۦٓ إِلَّآ أَن يَصَّدَّقُوا۟ ۚ فَإِن كَانَ مِن قَوْمٍ عَدُوٍّ لَّكُمْ وَهُوَ مُؤْمِنٌ فَتَحْرِيرُ رَقَبَةٍ مُّؤْمِنَةٍ ۖ وَإِن كَانَ مِن قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُم مِّيثَـٰقٌ فَدِيَةٌ مُّسَلَّمَةٌ إِلَىٰٓ أَهْلِهِۦ وَتَحْرِيرُ رَقَبَةٍ مُّؤْمِنَةٍ ۖ فَمَن لَّمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ تَوْبَةً مِّنَ ٱللَّهِ ۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا','Wa maa kaana limu\'minin ai yaqtula mu\'minan illaa khata\'aa; waman qatala mu\'minan khata\'an fatabreeru raqabatim mu\'minatinw wa diyatum mmusallamatun ilaaa ahliheee illaaa ai yassaddaqoo; fa in kaana min qawmin \'aduwwil lakum wa huwa mu\'minun fatabreeru raqabatim mu\'minah; wa in kaana min qawmim bainakum wa bainahum meesaaqun fadiyatum mmusallamatun ilaaa ahlihee wa tahreeru raqabatim mu\'minatin famal lam yajid fa Siyaamu shahraini mutataabi\'aini tawhatam minal laah; wa kaanal laahu \'Aleeman hakeemaa',92,'4:92',10,37,74,1,0,93,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(586,4,'وَمَن يَقْتُلْ مُؤْمِنًا مُّتَعَمِّدًا فَجَزَآؤُهُۥ جَهَنَّمُ خَـٰلِدًا فِيهَا وَغَضِبَ ٱللَّهُ عَلَيْهِ وَلَعَنَهُۥ وَأَعَدَّ لَهُۥ عَذَابًا عَظِيمًا','Wa mai yaqtul mu\'minammuta \'ammidan fajazaaa\'uhoo Jahannamu khaalidan feehaa wa ghadibal laahu\' alaihi wa la\'anahoo wa a\'adda lahoo \'azaaban \'azeemaa',93,'4:93',10,37,74,1,0,93,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(587,4,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا ضَرَبْتُمْ فِى سَبِيلِ ٱللَّهِ فَتَبَيَّنُوا۟ وَلَا تَقُولُوا۟ لِمَنْ أَلْقَىٰٓ إِلَيْكُمُ ٱلسَّلَـٰمَ لَسْتَ مُؤْمِنًا تَبْتَغُونَ عَرَضَ ٱلْحَيَوٰةِ ٱلدُّنْيَا فَعِندَ ٱللَّهِ مَغَانِمُ كَثِيرَةٌ ۚ كَذَٰلِكَ كُنتُم مِّن قَبْلُ فَمَنَّ ٱللَّهُ عَلَيْكُمْ فَتَبَيَّنُوٓا۟ ۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا','Yaaa aiyuhal lazeena aamanoo izaa darabtum fee sabeelil laahi fatabaiyanoo wa laa taqooloo liman alqaaa ilaikumus salaama lasta mu\'minan tabtaghoona \'aradal hayaatid dunyaa fa\'indal laahi maghaanimu kaseerah; kazaalika kuntum min qablu famannnal laahu \'alaikum fatabaiyanoo; innallaaha kaana bimaa ta\'maloona Khabeeraa',94,'4:94',10,37,74,1,0,93,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(588,4,'لَّا يَسْتَوِى ٱلْقَـٰعِدُونَ مِنَ ٱلْمُؤْمِنِينَ غَيْرُ أُو۟لِى ٱلضَّرَرِ وَٱلْمُجَـٰهِدُونَ فِى سَبِيلِ ٱللَّهِ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ ۚ فَضَّلَ ٱللَّهُ ٱلْمُجَـٰهِدِينَ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ عَلَى ٱلْقَـٰعِدِينَ دَرَجَةً ۚ وَكُلًّا وَعَدَ ٱللَّهُ ٱلْحُسْنَىٰ ۚ وَفَضَّلَ ٱللَّهُ ٱلْمُجَـٰهِدِينَ عَلَى ٱلْقَـٰعِدِينَ أَجْرًا عَظِيمًا','Laa yastawil qaa\'idoona Minal mu\'mineena ghairu ulid darari walmujaahidoona fee sabeelil laahi bi amwaalihim wa anfusihim; faddalal laahul mujaahideena bi amwaalihim wa anfusihim; faddalal laahul mujaahideena bi am waalihim wa anfusihim \'alalqaa\'ideena darajab; wa kullanw wa\'adal laahul husnaa; wa faddalal laahul mujaahideena \'alal qaa\'ideena ajran \'azeemaa',95,'4:95',10,37,74,1,0,94,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(589,4,'دَرَجَـٰتٍ مِّنْهُ وَمَغْفِرَةً وَرَحْمَةً ۚ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا','Darajaatim minhu wa maghfiratanw wa rahmah; wa kaanal laahu Ghafoorar Raheema',96,'4:96',10,37,74,1,0,94,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(590,4,'إِنَّ ٱلَّذِينَ تَوَفَّىٰهُمُ ٱلْمَلَـٰٓئِكَةُ ظَالِمِىٓ أَنفُسِهِمْ قَالُوا۟ فِيمَ كُنتُمْ ۖ قَالُوا۟ كُنَّا مُسْتَضْعَفِينَ فِى ٱلْأَرْضِ ۚ قَالُوٓا۟ أَلَمْ تَكُنْ أَرْضُ ٱللَّهِ وَٰسِعَةً فَتُهَاجِرُوا۟ فِيهَا ۚ فَأُو۟لَـٰٓئِكَ مَأْوَىٰهُمْ جَهَنَّمُ ۖ وَسَآءَتْ مَصِيرًا','Innal lazeena tawaffaa humul malaaa\'ikatu zaalimeee anfusihim qaaloo feema kuntum qaaloo kunnaa mustad\'afeena fil-ard; qaalooo alam takun ardul laahi waasi\'atan fatuhaajiroo feehaa; fa ulaaa\'ika maawaahum Jahannamu wa saaa\'at maseeraa',97,'4:97',10,37,75,1,0,94,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(591,4,'إِلَّا ٱلْمُسْتَضْعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلْوِلْدَٰنِ لَا يَسْتَطِيعُونَ حِيلَةً وَلَا يَهْتَدُونَ سَبِيلًا','Illal mustad \'afeena minar rijaali wannisaaa\'i walwildaani laa yastatee\'oona heelatanw wa laa yahtadoona sabeela',98,'4:98',10,37,75,1,0,94,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(592,4,'فَأُو۟لَـٰٓئِكَ عَسَى ٱللَّهُ أَن يَعْفُوَ عَنْهُمْ ۚ وَكَانَ ٱللَّهُ عَفُوًّا غَفُورًا','Fa ulaaa\'ika \'asal laahu ai ya\'fuwa \'anhum; wa kaanal laahu \'Afuwwan Ghafooraa',99,'4:99',10,37,75,1,0,94,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(593,4,'۞ وَمَن يُهَاجِرْ فِى سَبِيلِ ٱللَّهِ يَجِدْ فِى ٱلْأَرْضِ مُرَٰغَمًا كَثِيرًا وَسَعَةً ۚ وَمَن يَخْرُجْ مِنۢ بَيْتِهِۦ مُهَاجِرًا إِلَى ٱللَّهِ وَرَسُولِهِۦ ثُمَّ يُدْرِكْهُ ٱلْمَوْتُ فَقَدْ وَقَعَ أَجْرُهُۥ عَلَى ٱللَّهِ ۗ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا','Wa mai yuhaajir fee sabeelil laahi yajid fil ardi mmuraaghaman kaseeranw wa sa\'ah; wa mai yakhruj mim baitihee muhaajiran ilal laahi wa Rasoolihee summa yudrikhul mawtu faqad waqa\'a ajruhoo \'alal laah; wa kaanal laahu Ghafoorar Raheemaa',100,'4:100',10,38,75,1,0,94,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(594,4,'وَإِذَا ضَرَبْتُمْ فِى ٱلْأَرْضِ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَقْصُرُوا۟ مِنَ ٱلصَّلَوٰةِ إِنْ خِفْتُمْ أَن يَفْتِنَكُمُ ٱلَّذِينَ كَفَرُوٓا۟ ۚ إِنَّ ٱلْكَـٰفِرِينَ كَانُوا۟ لَكُمْ عَدُوًّا مُّبِينًا','Wa izaa darabtum fil ardi falaisa \'alaikum junaahun an taqsuroo minas Salaati in khiftum ai yaftinakumul lazeena kafarooo; innal kaafireena kaanoo lakum aduwwam mubeenaa',101,'4:101',10,38,76,1,0,94,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(595,4,'وَإِذَا كُنتَ فِيهِمْ فَأَقَمْتَ لَهُمُ ٱلصَّلَوٰةَ فَلْتَقُمْ طَآئِفَةٌ مِّنْهُم مَّعَكَ وَلْيَأْخُذُوٓا۟ أَسْلِحَتَهُمْ فَإِذَا سَجَدُوا۟ فَلْيَكُونُوا۟ مِن وَرَآئِكُمْ وَلْتَأْتِ طَآئِفَةٌ أُخْرَىٰ لَمْ يُصَلُّوا۟ فَلْيُصَلُّوا۟ مَعَكَ وَلْيَأْخُذُوا۟ حِذْرَهُمْ وَأَسْلِحَتَهُمْ ۗ وَدَّ ٱلَّذِينَ كَفَرُوا۟ لَوْ تَغْفُلُونَ عَنْ أَسْلِحَتِكُمْ وَأَمْتِعَتِكُمْ فَيَمِيلُونَ عَلَيْكُم مَّيْلَةً وَٰحِدَةً ۚ وَلَا جُنَاحَ عَلَيْكُمْ إِن كَانَ بِكُمْ أَذًى مِّن مَّطَرٍ أَوْ كُنتُم مَّرْضَىٰٓ أَن تَضَعُوٓا۟ أَسْلِحَتَكُمْ ۖ وَخُذُوا۟ حِذْرَكُمْ ۗ إِنَّ ٱللَّهَ أَعَدَّ لِلْكَـٰفِرِينَ عَذَابًا مُّهِينًا','Wa izaa kunta feehim fa aqamta lahumus Salaata faltaqum taaa\'ifatum minhum ma\'aka walyaakhuzooo aslihatahum fa izaa sajadoo fal yakoonoo minw waraaa\'ikum waltaati taaa\'ifatun ukhraa lam yusalloo falyusallo ma\'aka walyaakhuzoo hizrahum wa aslihatahum; waddal lazeena kafaroo law taghfuloona \'anaslihatikum wa amti\'atikum fa yameeloona \'alaikum mailatanw waahidah; wa laa junaaha \'alaikum in kaana bikum azam mimmatarin aw kuntum mmardaaa an tada\'ooo aslihatakum wa khuzoo hizrakum; innal laaha a\'adda lilkaafireena \'azaabam muheenaa',102,'4:102',10,38,76,1,0,95,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(596,4,'فَإِذَا قَضَيْتُمُ ٱلصَّلَوٰةَ فَٱذْكُرُوا۟ ٱللَّهَ قِيَـٰمًا وَقُعُودًا وَعَلَىٰ جُنُوبِكُمْ ۚ فَإِذَا ٱطْمَأْنَنتُمْ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ ۚ إِنَّ ٱلصَّلَوٰةَ كَانَتْ عَلَى ٱلْمُؤْمِنِينَ كِتَـٰبًا مَّوْقُوتًا','Fa izaa qadaitumus Salaata fazkurul laaha qiyaamanw wa qu\'oodanw wa \'alaa junoobikum; fa izat maanantum fa aqeemus Salaah; innas Salaata kaanat \'alal mu\'mineena kitaabam mawqootaa',103,'4:103',10,38,76,1,0,95,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(597,4,'وَلَا تَهِنُوا۟ فِى ٱبْتِغَآءِ ٱلْقَوْمِ ۖ إِن تَكُونُوا۟ تَأْلَمُونَ فَإِنَّهُمْ يَأْلَمُونَ كَمَا تَأْلَمُونَ ۖ وَتَرْجُونَ مِنَ ٱللَّهِ مَا لَا يَرْجُونَ ۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا','Wa laa tahinoo fibtighaaa\'il qawmi in takoonoo taalamoona fa innahum yaalamoona kamaa taalamoona wa tarjoona minal laahi maa laa yarjoon; wa kaanal laahu \'Aleeman Hakeemaa',104,'4:104',10,38,76,1,0,95,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(598,4,'إِنَّآ أَنزَلْنَآ إِلَيْكَ ٱلْكِتَـٰبَ بِٱلْحَقِّ لِتَحْكُمَ بَيْنَ ٱلنَّاسِ بِمَآ أَرَىٰكَ ٱللَّهُ ۚ وَلَا تَكُن لِّلْخَآئِنِينَ خَصِيمًا','Innaaa anzalnaaa ilaikal Kitaaba bilhaqqi litahkuma bainan naasi bimaaa araakal laah; wa laa takul lilkhaaa\'ineena khaseemaa',105,'4:105',10,38,77,1,0,95,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(599,4,'وَٱسْتَغْفِرِ ٱللَّهَ ۖ إِنَّ ٱللَّهَ كَانَ غَفُورًا رَّحِيمًا','Wastaghfiril laaha innal laaha kaana Ghafoorar Raheema',106,'4:106',10,38,77,1,0,96,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(600,4,'وَلَا تُجَـٰدِلْ عَنِ ٱلَّذِينَ يَخْتَانُونَ أَنفُسَهُمْ ۚ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ خَوَّانًا أَثِيمًا','Wa laa tujaadil \'anil lazeena yakhtaanoona anfusahum; innal laaha laa yuhibbuman kaana khawwaanan aseemaa',107,'4:107',10,38,77,1,0,96,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(601,4,'يَسْتَخْفُونَ مِنَ ٱلنَّاسِ وَلَا يَسْتَخْفُونَ مِنَ ٱللَّهِ وَهُوَ مَعَهُمْ إِذْ يُبَيِّتُونَ مَا لَا يَرْضَىٰ مِنَ ٱلْقَوْلِ ۚ وَكَانَ ٱللَّهُ بِمَا يَعْمَلُونَ مُحِيطًا','Yastakhfoona minannaasi wa laa yastakh foona minal laahi wa huwa ma\'ahum iz yubaiyitoona maa laa yardaa minal qawl; wa kaanal laahu bimaa ya\'maloona muheetaa',108,'4:108',10,38,77,1,0,96,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(602,4,'هَـٰٓأَنتُمْ هَـٰٓؤُلَآءِ جَـٰدَلْتُمْ عَنْهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا فَمَن يُجَـٰدِلُ ٱللَّهَ عَنْهُمْ يَوْمَ ٱلْقِيَـٰمَةِ أَم مَّن يَكُونُ عَلَيْهِمْ وَكِيلًا','haaa antum haaa\'ulaaa\'i jaadaltum \'anhum fil hayaatid dunyaa famai yujaadilul laaha \'anhum Yawmal Qiyaamati am mai yakoonu \'alaihim wakeelaa',109,'4:109',10,38,77,1,0,96,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(603,4,'وَمَن يَعْمَلْ سُوٓءًا أَوْ يَظْلِمْ نَفْسَهُۥ ثُمَّ يَسْتَغْفِرِ ٱللَّهَ يَجِدِ ٱللَّهَ غَفُورًا رَّحِيمًا','Wa mai ya\'mal sooo\'an aw yazlim nafsahoo summa yastaghfiril laaha yajidil laaha Ghafoorar Raheemaa',110,'4:110',10,38,77,1,0,96,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(604,4,'وَمَن يَكْسِبْ إِثْمًا فَإِنَّمَا يَكْسِبُهُۥ عَلَىٰ نَفْسِهِۦ ۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا','Wa mai yaksib isman fa innamaa yaksibuhoo \'alaa nafsih; wa kaanal laahu \'Aleeman hakeemaa',111,'4:111',10,38,77,1,0,96,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(605,4,'وَمَن يَكْسِبْ خَطِيٓـَٔةً أَوْ إِثْمًا ثُمَّ يَرْمِ بِهِۦ بَرِيٓـًٔا فَقَدِ ٱحْتَمَلَ بُهْتَـٰنًا وَإِثْمًا مُّبِينًا','Wa mai yaksib khateee\'atan aw isman summa yarmi bihee bareee\'an faqadih tamala buhtaananw wa ismam mubeenaa',112,'4:112',10,38,77,1,0,96,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(606,4,'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكَ وَرَحْمَتُهُۥ لَهَمَّت طَّآئِفَةٌ مِّنْهُمْ أَن يُضِلُّوكَ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمْ ۖ وَمَا يَضُرُّونَكَ مِن شَىْءٍ ۚ وَأَنزَلَ ٱللَّهُ عَلَيْكَ ٱلْكِتَـٰبَ وَٱلْحِكْمَةَ وَعَلَّمَكَ مَا لَمْ تَكُن تَعْلَمُ ۚ وَكَانَ فَضْلُ ٱللَّهِ عَلَيْكَ عَظِيمًا','Wa law laa fadlul laahi \'alaika wa rahmatuhoo lahammat taaa\'ifatum minhum ai yudillooka wa maa yudilloona illaaa anfusahum wa maa yadurroonaka min shai\'; wa anzalal laahu \'alaikal Kitaaba wal Hikmata wa \'allamaka maa lam takun ta\'lam; wa kaana fadlul laahi \'alaika \'azeemaa',113,'4:113',10,38,78,1,0,96,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(607,4,'۞ لَّا خَيْرَ فِى كَثِيرٍ مِّن نَّجْوَىٰهُمْ إِلَّا مَنْ أَمَرَ بِصَدَقَةٍ أَوْ مَعْرُوفٍ أَوْ إِصْلَـٰحٍۭ بَيْنَ ٱلنَّاسِ ۚ وَمَن يَفْعَلْ ذَٰلِكَ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا','laa khaira fee kaseerim min najwaahum illaa man amara bisadaqatin aw ma\'roofin aw islaahim bainan naas; wa mai yaf\'al zaalikab tighaaa\'a mardaatil laahi fa sawfa nu\'teehi ajran \'azeemaa',114,'4:114',10,39,78,1,0,97,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(608,4,'وَمَن يُشَاقِقِ ٱلرَّسُولَ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُ ٱلْهُدَىٰ وَيَتَّبِعْ غَيْرَ سَبِيلِ ٱلْمُؤْمِنِينَ نُوَلِّهِۦ مَا تَوَلَّىٰ وَنُصْلِهِۦ جَهَنَّمَ ۖ وَسَآءَتْ مَصِيرًا','Wa mai yushaaqiqir Rasoola mim ba\'di maa tabaiyana lahul hudaa wa tattabi\' ghaira sabeelil mu\'mineena nuwallihee ma tawallaa wa nuslihee Jahannama wa saaa\'at maseeraa',115,'4:115',10,39,78,1,0,97,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(609,4,'إِنَّ ٱللَّهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِۦ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُ ۚ وَمَن يُشْرِكْ بِٱللَّهِ فَقَدْ ضَلَّ ضَلَـٰلًۢا بَعِيدًا','Innal laaha laa yaghfiru ai yushraka bihee wayaghfiru maa doona zaalika limai yashaaa\'; wa mai yushrik billaahi faqad dalla dalaalam ba\'eedaa',116,'4:116',10,39,79,1,0,97,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(610,4,'إِن يَدْعُونَ مِن دُونِهِۦٓ إِلَّآ إِنَـٰثًا وَإِن يَدْعُونَ إِلَّا شَيْطَـٰنًا مَّرِيدًا','iny yad\'oona min dooniheee illaaa inaasanw wa iny yad\'oona illaa Shaitaanam mareedaa',117,'4:117',10,39,79,1,0,97,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(611,4,'لَّعَنَهُ ٱللَّهُ ۘ وَقَالَ لَأَتَّخِذَنَّ مِنْ عِبَادِكَ نَصِيبًا مَّفْرُوضًا','La\'anahul laah; wa qaala la attakhizanna min \'ibaadika naseebam mafroodaa',118,'4:118',10,39,79,1,0,97,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(612,4,'وَلَأُضِلَّنَّهُمْ وَلَأُمَنِّيَنَّهُمْ وَلَـَٔامُرَنَّهُمْ فَلَيُبَتِّكُنَّ ءَاذَانَ ٱلْأَنْعَـٰمِ وَلَـَٔامُرَنَّهُمْ فَلَيُغَيِّرُنَّ خَلْقَ ٱللَّهِ ۚ وَمَن يَتَّخِذِ ٱلشَّيْطَـٰنَ وَلِيًّا مِّن دُونِ ٱللَّهِ فَقَدْ خَسِرَ خُسْرَانًا مُّبِينًا','Wa la udillannahum wa la umanni yannnahum wa la aamurannahum fala yubat tikunna aazaanal lan\'aami wa la aamurannahum fala yughai yirunna khalqal laah; wa mai yattakhizish Shaitaana waliyyam mmin doonil laahi faqad khasira khusraanam mubeena',119,'4:119',10,39,79,1,0,97,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(613,4,'يَعِدُهُمْ وَيُمَنِّيهِمْ ۖ وَمَا يَعِدُهُمُ ٱلشَّيْطَـٰنُ إِلَّا غُرُورًا','Ya\'iduhum wa yuman neehim wa maa ya\'iduhumush Shaitaanu illaa ghurooraa',120,'4:120',10,39,79,1,0,97,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(614,4,'أُو۟لَـٰٓئِكَ مَأْوَىٰهُمْ جَهَنَّمُ وَلَا يَجِدُونَ عَنْهَا مَحِيصًا','Ulaaa\'ika maawaahum Jahannamu wa laa yajidoona \'anhaa maheesaa',121,'4:121',10,39,79,1,0,97,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(615,4,'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ سَنُدْخِلُهُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَآ أَبَدًا ۖ وَعْدَ ٱللَّهِ حَقًّا ۚ وَمَنْ أَصْدَقُ مِنَ ٱللَّهِ قِيلًا','Wallazeena aamanoo wa \'amilus saalihaati sanud khiluhum Jannaatin tajree min tahtihal anhaaru khaalideena feehaaa abadaa; wa\'dal laahi haqqaa; wa man asdaqu minal laahi qeelaa',122,'4:122',10,39,79,1,0,98,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(616,4,'لَّيْسَ بِأَمَانِيِّكُمْ وَلَآ أَمَانِىِّ أَهْلِ ٱلْكِتَـٰبِ ۗ مَن يَعْمَلْ سُوٓءًا يُجْزَ بِهِۦ وَلَا يَجِدْ لَهُۥ مِن دُونِ ٱللَّهِ وَلِيًّا وَلَا نَصِيرًا','Laisa bi amaaniyyikum wa laaa amaaniyyi Ahlil Kitaab; mai ya\'mal sooo\'ai yujza bihee wa laa yajid lahoo min doonil laahi waliyanw wa laa naseeraa',123,'4:123',10,39,79,1,0,98,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(617,4,'وَمَن يَعْمَلْ مِنَ ٱلصَّـٰلِحَـٰتِ مِن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَأُو۟لَـٰٓئِكَ يَدْخُلُونَ ٱلْجَنَّةَ وَلَا يُظْلَمُونَ نَقِيرًا','Wa mai ya\'mal minas saalihaati min zakarin aw unsaa wa huwa mu\'minun fa ulaaa\'ika yadkhuloonal Jannata wa laa yuzlamoona naqeeraa',124,'4:124',10,39,79,1,0,98,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(618,4,'وَمَنْ أَحْسَنُ دِينًا مِّمَّنْ أَسْلَمَ وَجْهَهُۥ لِلَّهِ وَهُوَ مُحْسِنٌ وَٱتَّبَعَ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًا ۗ وَٱتَّخَذَ ٱللَّهُ إِبْرَٰهِيمَ خَلِيلًا','Wa man ahsanu deenam mimmman aslama wajhahoo lillaahi wa huwa muhsinunw wattaba\'a Millata Ibraaheema haneefaa; wattakhazal laahu Ibraaheema khaleelaa',125,'4:125',10,39,79,1,0,98,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(619,4,'وَلِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ وَكَانَ ٱللَّهُ بِكُلِّ شَىْءٍ مُّحِيطًا','Wa lillaahi maa fis samaawaati wa maa fil ard; wa kaanal laahu bikulli shai\'im muheetaa',126,'4:126',10,39,79,1,0,98,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(620,4,'وَيَسْتَفْتُونَكَ فِى ٱلنِّسَآءِ ۖ قُلِ ٱللَّهُ يُفْتِيكُمْ فِيهِنَّ وَمَا يُتْلَىٰ عَلَيْكُمْ فِى ٱلْكِتَـٰبِ فِى يَتَـٰمَى ٱلنِّسَآءِ ٱلَّـٰتِى لَا تُؤْتُونَهُنَّ مَا كُتِبَ لَهُنَّ وَتَرْغَبُونَ أَن تَنكِحُوهُنَّ وَٱلْمُسْتَضْعَفِينَ مِنَ ٱلْوِلْدَٰنِ وَأَن تَقُومُوا۟ لِلْيَتَـٰمَىٰ بِٱلْقِسْطِ ۚ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍ فَإِنَّ ٱللَّهَ كَانَ بِهِۦ عَلِيمًا','Wa yastaftoonaka finnisaaa\'i qulil laahu yufteekum feehinna wa maa yutlaa \'alaikum fil Kitaabi fee yataaman nisaaa\'il laatee laa tu\'toonahunna mmaa kutiba lahunnna wa targhaboona an tankihoohunna wal mustad\'a feena minal wildaani wa an taqoomoo lilyataamaa bilqist; wa maa taf\'aloo min khairin fa innal laaha kaana bihee \'Aleemaa',127,'4:127',10,39,80,1,0,98,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(621,4,'وَإِنِ ٱمْرَأَةٌ خَافَتْ مِنۢ بَعْلِهَا نُشُوزًا أَوْ إِعْرَاضًا فَلَا جُنَاحَ عَلَيْهِمَآ أَن يُصْلِحَا بَيْنَهُمَا صُلْحًا ۚ وَٱلصُّلْحُ خَيْرٌ ۗ وَأُحْضِرَتِ ٱلْأَنفُسُ ٱلشُّحَّ ۚ وَإِن تُحْسِنُوا۟ وَتَتَّقُوا۟ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا','Wa inimra atun khaafat mim ba\'lihaa nushoozan aw i\'raadan falaa junaaha \'alaihi maaa ai yuslihaa bainahumaa sulhaa; wassulhu khair; wa uhdiratil anfusush shuhh; wa in tuhsinoo wa tattaqoo fa innal laaha kaana bimaa ta\'maloona Khabeeraa',128,'4:128',10,39,80,1,0,99,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(622,4,'وَلَن تَسْتَطِيعُوٓا۟ أَن تَعْدِلُوا۟ بَيْنَ ٱلنِّسَآءِ وَلَوْ حَرَصْتُمْ ۖ فَلَا تَمِيلُوا۟ كُلَّ ٱلْمَيْلِ فَتَذَرُوهَا كَٱلْمُعَلَّقَةِ ۚ وَإِن تُصْلِحُوا۟ وَتَتَّقُوا۟ فَإِنَّ ٱللَّهَ كَانَ غَفُورًا رَّحِيمًا','Wa lan tastatee\'ooo an ta\'diloo bainan nisaaa\'i wa law harastum falaa tameeloo kullal maili fatazaroohaa kalmu\'al laqah; wa in tuslihoo wa tattaqoo fa innal laaha kaana Ghafoorar Raheema',129,'4:129',10,39,80,1,0,99,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(623,4,'وَإِن يَتَفَرَّقَا يُغْنِ ٱللَّهُ كُلًّا مِّن سَعَتِهِۦ ۚ وَكَانَ ٱللَّهُ وَٰسِعًا حَكِيمًا','Wa iny-yatafarraqaa yughnil laahu kullam min sa\'atih; wa kaanal laahu Waasi\'an Hakeemaa',130,'4:130',10,39,80,1,0,99,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(624,4,'وَلِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَلَقَدْ وَصَّيْنَا ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ مِن قَبْلِكُمْ وَإِيَّاكُمْ أَنِ ٱتَّقُوا۟ ٱللَّهَ ۚ وَإِن تَكْفُرُوا۟ فَإِنَّ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ وَكَانَ ٱللَّهُ غَنِيًّا حَمِيدًا','Wa lillaahi maafis samaawaati wa maa fil ard; wa laqad wassainal lazeena ootul Kitaaba min qablikum wa iyyaakum anit taqul laah; wa intakfuroo fa inna lillaahi maa fis samaawaati wa maa fil ard; wa kaanal laahu Ghaniyyan hameedaa',131,'4:131',10,39,80,1,0,99,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(625,4,'وَلِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا','Wa lillaahi maa fis samaawaati wa maa fil ard; wa kafaa billaahi Wakeelaa',132,'4:132',10,39,80,1,0,99,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(626,4,'إِن يَشَأْ يُذْهِبْكُمْ أَيُّهَا ٱلنَّاسُ وَيَأْتِ بِـَٔاخَرِينَ ۚ وَكَانَ ٱللَّهُ عَلَىٰ ذَٰلِكَ قَدِيرًا','Iny-yashaa yuzhibkum aiyuhan naasu wa yaati bi aakhareen; wa kaanal laahu \'alaa zaalika Qadeeraa',133,'4:133',10,39,80,1,0,99,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(627,4,'مَّن كَانَ يُرِيدُ ثَوَابَ ٱلدُّنْيَا فَعِندَ ٱللَّهِ ثَوَابُ ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ ۚ وَكَانَ ٱللَّهُ سَمِيعًۢا بَصِيرًا','man kaana yureedu sawaabad dunyaa fa\'indallaahi sawaabud dunyaa wal Aakhirah; wa kaanal laahu Samee\'am Baseeraa',134,'4:134',10,39,80,1,0,99,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(628,4,'۞ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوا۟ قَوَّٰمِينَ بِٱلْقِسْطِ شُهَدَآءَ لِلَّهِ وَلَوْ عَلَىٰٓ أَنفُسِكُمْ أَوِ ٱلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ ۚ إِن يَكُنْ غَنِيًّا أَوْ فَقِيرًا فَٱللَّهُ أَوْلَىٰ بِهِمَا ۖ فَلَا تَتَّبِعُوا۟ ٱلْهَوَىٰٓ أَن تَعْدِلُوا۟ ۚ وَإِن تَلْوُۥٓا۟ أَوْ تُعْرِضُوا۟ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا','Yaa aiyuhal lazeena aamanoo koonoo qawwa ameena bilqisti shuhadaaa\'a lillaahi wa law \'alaa anfusikum awil waalidaini wal aqrabeen iny yakun ghaniyyan aw faqeeran fallaahu awlaa bihimaa falaaa tattabi\'ul hawaaa an ta\'diloo; wa in talwooo aw tu\'ridoo fa innal laaha kaana bimaa ta\'maloona Khabeera',135,'4:135',10,40,81,1,0,100,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(629,4,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ ءَامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱلْكِتَـٰبِ ٱلَّذِى نَزَّلَ عَلَىٰ رَسُولِهِۦ وَٱلْكِتَـٰبِ ٱلَّذِىٓ أَنزَلَ مِن قَبْلُ ۚ وَمَن يَكْفُرْ بِٱللَّهِ وَمَلَـٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ وَٱلْيَوْمِ ٱلْـَٔاخِرِ فَقَدْ ضَلَّ ضَلَـٰلًۢا بَعِيدًا','Yaaa aiyuhal lazeena aamanooo aaminoo billaahi wa Rasoolihee wal Kitaabil lazee nazzala \'alaa Rasoolihee wal Kitaabil lazeee anzala min qabl; wa mai yakfur billaahi wa Malaaa\'ikatihee wa Kutubihee wa Rusulihee wal Yawmil Aakhiri faqad dalla dalaalam ba\'eedaa',136,'4:136',10,40,81,1,0,100,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(630,4,'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ ثُمَّ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ ثُمَّ ٱزْدَادُوا۟ كُفْرًا لَّمْ يَكُنِ ٱللَّهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ سَبِيلًۢا','Innal lazeena aamanoo summa kafaroo summa aamanoo summa kafaroo summaz daado kufral lam yakunil laahu liyaghfira lahum wa laa liyahdiyahum sabeelaa',137,'4:137',10,40,81,1,0,100,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(631,4,'بَشِّرِ ٱلْمُنَـٰفِقِينَ بِأَنَّ لَهُمْ عَذَابًا أَلِيمًا','Bashshiril munaafiqeena bi anna lahum \'azaaban aleemaa',138,'4:138',10,40,81,1,0,100,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(632,4,'ٱلَّذِينَ يَتَّخِذُونَ ٱلْكَـٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ ۚ أَيَبْتَغُونَ عِندَهُمُ ٱلْعِزَّةَ فَإِنَّ ٱلْعِزَّةَ لِلَّهِ جَمِيعًا','Allazeena yattakhizoo nal kaafireena awliyaaa\'a min doonil mu\'mineen; a-yabta ghoona \'indahumul \'izzata fainnnal \'izzata lillaahi jamee\'aa',139,'4:139',10,40,81,1,0,100,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(633,4,'وَقَدْ نَزَّلَ عَلَيْكُمْ فِى ٱلْكِتَـٰبِ أَنْ إِذَا سَمِعْتُمْ ءَايَـٰتِ ٱللَّهِ يُكْفَرُ بِهَا وَيُسْتَهْزَأُ بِهَا فَلَا تَقْعُدُوا۟ مَعَهُمْ حَتَّىٰ يَخُوضُوا۟ فِى حَدِيثٍ غَيْرِهِۦٓ ۚ إِنَّكُمْ إِذًا مِّثْلُهُمْ ۗ إِنَّ ٱللَّهَ جَامِعُ ٱلْمُنَـٰفِقِينَ وَٱلْكَـٰفِرِينَ فِى جَهَنَّمَ جَمِيعًا','Wa qad nazzala \'alaikum fil Kitaabi an izaa sami\'tum Aayaatil laahi yukfaru bihaa wa yustahza u bihaa falaa taq\'udoo ma\'ahum hattaa yakhoodoo fee hadeesin ghairih; innakum izam misluhum; innal laaha jaami\'ul munaafiqeena wal kaafireena fee jahannama jamee\'aa',140,'4:140',10,40,81,1,0,100,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(634,4,'ٱلَّذِينَ يَتَرَبَّصُونَ بِكُمْ فَإِن كَانَ لَكُمْ فَتْحٌ مِّنَ ٱللَّهِ قَالُوٓا۟ أَلَمْ نَكُن مَّعَكُمْ وَإِن كَانَ لِلْكَـٰفِرِينَ نَصِيبٌ قَالُوٓا۟ أَلَمْ نَسْتَحْوِذْ عَلَيْكُمْ وَنَمْنَعْكُم مِّنَ ٱلْمُؤْمِنِينَ ۚ فَٱللَّهُ يَحْكُمُ بَيْنَكُمْ يَوْمَ ٱلْقِيَـٰمَةِ ۗ وَلَن يَجْعَلَ ٱللَّهُ لِلْكَـٰفِرِينَ عَلَى ٱلْمُؤْمِنِينَ سَبِيلًا','Allazeena yatarab basoona bikum fa in kaana lakum fathum minal laahi qaalooo alam nakum ma\'akum wa in kaana lilkaafireena naseebun qaalooo alam nastah wiz \'alaikum wa nammna\'kum minal mu\'mineen; fallaahu yahkumu bainakum Yawmal Qiyaamah; wa lai yaj\'alal laahu lilkaafireena \'alal mu\'mineena sabeelaa',141,'4:141',10,40,81,1,0,101,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(635,4,'إِنَّ ٱلْمُنَـٰفِقِينَ يُخَـٰدِعُونَ ٱللَّهَ وَهُوَ خَـٰدِعُهُمْ وَإِذَا قَامُوٓا۟ إِلَى ٱلصَّلَوٰةِ قَامُوا۟ كُسَالَىٰ يُرَآءُونَ ٱلنَّاسَ وَلَا يَذْكُرُونَ ٱللَّهَ إِلَّا قَلِيلًا','Innal munaafiqeena yukhaadi\'oonal laaha wa huwa khaadi\'uhum wa izaa qaamooo ilas Salaati qaamoo kusaalaa yuraaa\'oonan naasa wa laa yazkuroonal laaha illaa qaleelaa',142,'4:142',10,40,82,1,0,101,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(636,4,'مُّذَبْذَبِينَ بَيْنَ ذَٰلِكَ لَآ إِلَىٰ هَـٰٓؤُلَآءِ وَلَآ إِلَىٰ هَـٰٓؤُلَآءِ ۚ وَمَن يُضْلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلًا','Muzabzabeena baina zaalika laaa ilaa haaa\' ulaaa\'i wa laaa ilaa haaa\'ulaaa\'; wa mai yudlilil laahu falan tajida lahoo sabeela',143,'4:143',10,40,82,1,0,101,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(637,4,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلْكَـٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ ۚ أَتُرِيدُونَ أَن تَجْعَلُوا۟ لِلَّهِ عَلَيْكُمْ سُلْطَـٰنًا مُّبِينًا','Yaaa aiyuhal lazeena aamanoo laa tattakhizul kaafireena awliyaaa\'a min doonil mu\'mineen; aturee doona an taj\'aloo lillaahi \'alaikum sultaanam mubeenaa',144,'4:144',10,40,82,1,0,101,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(638,4,'إِنَّ ٱلْمُنَـٰفِقِينَ فِى ٱلدَّرْكِ ٱلْأَسْفَلِ مِنَ ٱلنَّارِ وَلَن تَجِدَ لَهُمْ نَصِيرًا','Innal munaafiqeena fiddarkil asfali minan Naari wa lan tajjida lahum naseeraa',145,'4:145',10,40,82,1,0,101,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(639,4,'إِلَّا ٱلَّذِينَ تَابُوا۟ وَأَصْلَحُوا۟ وَٱعْتَصَمُوا۟ بِٱللَّهِ وَأَخْلَصُوا۟ دِينَهُمْ لِلَّهِ فَأُو۟لَـٰٓئِكَ مَعَ ٱلْمُؤْمِنِينَ ۖ وَسَوْفَ يُؤْتِ ٱللَّهُ ٱلْمُؤْمِنِينَ أَجْرًا عَظِيمًا','Illal lazeena taaboo wa aslahoo wa\'tasamoo billaahi wa akhlasoo deenahum lillaahi faulaaa\'ika ma\'al mu\'mineena wa sawfa yu\'til laahul mu\'mineena ajran \'azeemaa',146,'4:146',10,40,82,1,0,101,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(640,4,'مَّا يَفْعَلُ ٱللَّهُ بِعَذَابِكُمْ إِن شَكَرْتُمْ وَءَامَنتُمْ ۚ وَكَانَ ٱللَّهُ شَاكِرًا عَلِيمًا','maa yafa\'lul laahu bi \'azaabikum in shakartum wa aamantum; wa kaanal laahu Shaakiran \'Aleema',147,'4:147',10,40,82,1,0,101,5,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(641,4,'۞ لَّا يُحِبُّ ٱللَّهُ ٱلْجَهْرَ بِٱلسُّوٓءِ مِنَ ٱلْقَوْلِ إِلَّا مَن ظُلِمَ ۚ وَكَانَ ٱللَّهُ سَمِيعًا عَلِيمًا','Laa yuhibbullaahul jahra bis sooo\'i minal qawli illaa man zulim; wa kaanallaahu Samee\'an \'Aleeman',148,'4:148',11,41,82,1,0,102,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(642,4,'إِن تُبْدُوا۟ خَيْرًا أَوْ تُخْفُوهُ أَوْ تَعْفُوا۟ عَن سُوٓءٍ فَإِنَّ ٱللَّهَ كَانَ عَفُوًّا قَدِيرًا','in tubdoo khairann aw tukhfoohu aw ta\'foo \'an sooo\'in fa innal laaha kaana \'afuwwan Qadeeraa',149,'4:149',11,41,82,1,0,102,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(643,4,'إِنَّ ٱلَّذِينَ يَكْفُرُونَ بِٱللَّهِ وَرُسُلِهِۦ وَيُرِيدُونَ أَن يُفَرِّقُوا۟ بَيْنَ ٱللَّهِ وَرُسُلِهِۦ وَيَقُولُونَ نُؤْمِنُ بِبَعْضٍ وَنَكْفُرُ بِبَعْضٍ وَيُرِيدُونَ أَن يَتَّخِذُوا۟ بَيْنَ ذَٰلِكَ سَبِيلًا','Innal lazeena yakkfuroona billaahi wa Rusulihee wa yureedoona ai yufarriqoo bainal laahi wa Rusulihee wa yaqooloona nu\'minu biba\'dinw wa nakfuru biba\' dinw wa yureedoona ai yattakhizoo baina zaalika sabeelaa',150,'4:150',11,41,82,1,0,102,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(644,4,'أُو۟لَـٰٓئِكَ هُمُ ٱلْكَـٰفِرُونَ حَقًّا ۚ وَأَعْتَدْنَا لِلْكَـٰفِرِينَ عَذَابًا مُّهِينًا','Ulaaa\'ika humul kaafiroona haqqaa; wa a\'tadnaa lilkaafireena \'azaabam muheenaa',151,'4:151',11,41,82,1,0,102,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(645,4,'وَٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ وَلَمْ يُفَرِّقُوا۟ بَيْنَ أَحَدٍ مِّنْهُمْ أُو۟لَـٰٓئِكَ سَوْفَ يُؤْتِيهِمْ أُجُورَهُمْ ۗ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا','Wallazeena aamanoo billaahi wa Rusulihee wa lam yufarriqoo baina ahadim minhum ulaaa\'ika sawfa yu\'teehim ujoorahum; wa kaanal laahu Ghafoorar Raheema',152,'4:152',11,41,82,1,0,102,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(646,4,'يَسْـَٔلُكَ أَهْلُ ٱلْكِتَـٰبِ أَن تُنَزِّلَ عَلَيْهِمْ كِتَـٰبًا مِّنَ ٱلسَّمَآءِ ۚ فَقَدْ سَأَلُوا۟ مُوسَىٰٓ أَكْبَرَ مِن ذَٰلِكَ فَقَالُوٓا۟ أَرِنَا ٱللَّهَ جَهْرَةً فَأَخَذَتْهُمُ ٱلصَّـٰعِقَةُ بِظُلْمِهِمْ ۚ ثُمَّ ٱتَّخَذُوا۟ ٱلْعِجْلَ مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَـٰتُ فَعَفَوْنَا عَن ذَٰلِكَ ۚ وَءَاتَيْنَا مُوسَىٰ سُلْطَـٰنًا مُّبِينًا','yas\'aluka Ahlul Kitaabi an tunazzila \'alaihim Kitaabam minas samaaa\'i faqad sa aloo Moosaa akbara min zaalika faqaaloo arinal laaha jahratan fa akhazat humus saa\'iqatu bizulmihim; summat takhazul \'ijla mim ba\'di maa jaa\'at humul baiyinaatu fa\'afawnaa \'ann zaalik; wa aatainaa Moosaa sultaanam mubeenaa',153,'4:153',11,41,83,1,0,102,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(647,4,'وَرَفَعْنَا فَوْقَهُمُ ٱلطُّورَ بِمِيثَـٰقِهِمْ وَقُلْنَا لَهُمُ ٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًا وَقُلْنَا لَهُمْ لَا تَعْدُوا۟ فِى ٱلسَّبْتِ وَأَخَذْنَا مِنْهُم مِّيثَـٰقًا غَلِيظًا','Wa rafa\'naa fawqahumut Toora bimeesaaqihim wa qulnaa lahumud khulul baaba sujjadanw wa qulnaa lahum laa ta\'doo fis Sabti wa akhaznaa minhum meesaaqan ghaleezaa',154,'4:154',11,41,83,1,0,102,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(648,4,'فَبِمَا نَقْضِهِم مِّيثَـٰقَهُمْ وَكُفْرِهِم بِـَٔايَـٰتِ ٱللَّهِ وَقَتْلِهِمُ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّ وَقَوْلِهِمْ قُلُوبُنَا غُلْفٌۢ ۚ بَلْ طَبَعَ ٱللَّهُ عَلَيْهَا بِكُفْرِهِمْ فَلَا يُؤْمِنُونَ إِلَّا قَلِيلًا','Fabimaa naqdihim meesaaqahum wa kufrihim bi Aayaatil laahi wa qatlihimul Ambiyaaa\'a bighairi haqqinw wa qawlihim quloobunna ghulf; bal taba\'al laahu \'alaihaa bikufrihim falaa yu\'minoona illaa qaleelaa',155,'4:155',11,41,83,1,0,103,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(649,4,'وَبِكُفْرِهِمْ وَقَوْلِهِمْ عَلَىٰ مَرْيَمَ بُهْتَـٰنًا عَظِيمًا','Wa bikufrihim wa qawlihim \'alaa Maryama buh taanan \'azeema',156,'4:156',11,41,83,1,0,103,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(650,4,'وَقَوْلِهِمْ إِنَّا قَتَلْنَا ٱلْمَسِيحَ عِيسَى ٱبْنَ مَرْيَمَ رَسُولَ ٱللَّهِ وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَـٰكِن شُبِّهَ لَهُمْ ۚ وَإِنَّ ٱلَّذِينَ ٱخْتَلَفُوا۟ فِيهِ لَفِى شَكٍّ مِّنْهُ ۚ مَا لَهُم بِهِۦ مِنْ عِلْمٍ إِلَّا ٱتِّبَاعَ ٱلظَّنِّ ۚ وَمَا قَتَلُوهُ يَقِينًۢا','Wa qawlihim innaa qatal nal maseeha \'Eesab-na-Maryama Rasoolal laahi wa maa qataloohu wa maa salaboohu wa laakin shubbiha lahum; wa innal lazeenakh talafoo fee lafee shakkim minh; maa lahum bihee min \'ilmin illat tibaa\'az zann; wa maa qataloohu yaqeenaa',157,'4:157',11,41,83,1,0,103,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(651,4,'بَل رَّفَعَهُ ٱللَّهُ إِلَيْهِ ۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا','Bar rafa\'ahul laahu ilayh; wa kaanal laahu \'Azeezan Hakeemaa',158,'4:158',11,41,83,1,0,103,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(652,4,'وَإِن مِّنْ أَهْلِ ٱلْكِتَـٰبِ إِلَّا لَيُؤْمِنَنَّ بِهِۦ قَبْلَ مَوْتِهِۦ ۖ وَيَوْمَ ٱلْقِيَـٰمَةِ يَكُونُ عَلَيْهِمْ شَهِيدًا','Wa im min Ahlil Kitaabi illaa layu\'minanna bihee qabla mawtihee wa Yawmal Qiyaamati yakoonu \'alaihim shaheedaa',159,'4:159',11,41,83,1,0,103,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(653,4,'فَبِظُلْمٍ مِّنَ ٱلَّذِينَ هَادُوا۟ حَرَّمْنَا عَلَيْهِمْ طَيِّبَـٰتٍ أُحِلَّتْ لَهُمْ وَبِصَدِّهِمْ عَن سَبِيلِ ٱللَّهِ كَثِيرًا','Fabizulmin minal lazeena haadoo harramnaa \'alaihim taiyibaatin uhillat lahum wa bisadihim \'an sabeelil laahi kaseeraa',160,'4:160',11,41,83,1,0,103,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(654,4,'وَأَخْذِهِمُ ٱلرِّبَوٰا۟ وَقَدْ نُهُوا۟ عَنْهُ وَأَكْلِهِمْ أَمْوَٰلَ ٱلنَّاسِ بِٱلْبَـٰطِلِ ۚ وَأَعْتَدْنَا لِلْكَـٰفِرِينَ مِنْهُمْ عَذَابًا أَلِيمًا','Wa akhzihimur ribaa wa qad nuhoo \'anhu wa aklihim amwaalan naasi bilbaatil; wa a\'tadnaa lilkaafireena minhum \'azaaban aleema',161,'4:161',11,41,83,1,0,103,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(655,4,'لَّـٰكِنِ ٱلرَّٰسِخُونَ فِى ٱلْعِلْمِ مِنْهُمْ وَٱلْمُؤْمِنُونَ يُؤْمِنُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ ۚ وَٱلْمُقِيمِينَ ٱلصَّلَوٰةَ ۚ وَٱلْمُؤْتُونَ ٱلزَّكَوٰةَ وَٱلْمُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ أُو۟لَـٰٓئِكَ سَنُؤْتِيهِمْ أَجْرًا عَظِيمًا','Laakinir raasikhoona fil\'ilmi minhum walmu\'minoona yu\'minoona bimaaa unzila ilaika wa maaa unzila min qablika walmuqeemeenas Salaata walmu\'toonaz Zakaata walmu \'minoona billaahi wal yawmil Aakhir; ulaaa\'ika sanu\'teehim ajran \'azeemaa',162,'4:162',11,41,83,1,0,103,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(656,4,'۞ إِنَّآ أَوْحَيْنَآ إِلَيْكَ كَمَآ أَوْحَيْنَآ إِلَىٰ نُوحٍ وَٱلنَّبِيِّـۧنَ مِنۢ بَعْدِهِۦ ۚ وَأَوْحَيْنَآ إِلَىٰٓ إِبْرَٰهِيمَ وَإِسْمَـٰعِيلَ وَإِسْحَـٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَعِيسَىٰ وَأَيُّوبَ وَيُونُسَ وَهَـٰرُونَ وَسُلَيْمَـٰنَ ۚ وَءَاتَيْنَا دَاوُۥدَ زَبُورًا','innaaa awhainaaa ilaika kamaaa awhainaaa ilaa Noohinw wan nabiyyeena mim ba\'dih; wa awhainaaa ilaaa ibraaheema wa Ismaaa\'eela wa Ishaaqa wa Ya\'qooba wal Asbaati wa \'Eesaa wa Ayyooba wa Yoonusa wa haaroona wa Sulaimaan; wa aatainaa Daawooda Zabooraa',163,'4:163',11,42,84,1,0,104,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(657,4,'وَرُسُلًا قَدْ قَصَصْنَـٰهُمْ عَلَيْكَ مِن قَبْلُ وَرُسُلًا لَّمْ نَقْصُصْهُمْ عَلَيْكَ ۚ وَكَلَّمَ ٱللَّهُ مُوسَىٰ تَكْلِيمًا','Wa Rusulan qad qasas naahum \'alaika min qablu wa Rusulal lam naqsushum \'alaik; wa kallamallaahu Moosaa takleemaa',164,'4:164',11,42,84,1,0,104,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(658,4,'رُّسُلًا مُّبَشِّرِينَ وَمُنذِرِينَ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَى ٱللَّهِ حُجَّةٌۢ بَعْدَ ٱلرُّسُلِ ۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا','Rusulam mubashshireena wa munzireena li\'allaa yakoona linnaasi \'alal laahi hujjatum ba\'dar Rusul; wa kaanallaahu \'Azeezan Hakeema',165,'4:165',11,42,84,1,0,104,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(659,4,'لَّـٰكِنِ ٱللَّهُ يَشْهَدُ بِمَآ أَنزَلَ إِلَيْكَ ۖ أَنزَلَهُۥ بِعِلْمِهِۦ ۖ وَٱلْمَلَـٰٓئِكَةُ يَشْهَدُونَ ۚ وَكَفَىٰ بِٱللَّهِ شَهِيدًا','Laakinil laahu yashhadu bimaaa anzala ilaika anzalahoo bi\'ilmihee wal malaaa\'ikatu yashhadoon; wa kafaa billaahi Shaheeda',166,'4:166',11,42,84,1,0,104,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(660,4,'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ قَدْ ضَلُّوا۟ ضَلَـٰلًۢا بَعِيدًا','Innal lazeena kafaroo wa saddoo \'an sabeelil laahi qad dalloo dalaalam ba\'eedaa',167,'4:167',11,42,84,1,0,104,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(661,4,'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَظَلَمُوا۟ لَمْ يَكُنِ ٱللَّهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ طَرِيقًا','Innal lazeenakafaroo wa zalamoo lam yakkunillaahu liyaghfira lahum wa laa liyahdiyahum tareeqaa',168,'4:168',11,42,84,1,0,104,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(662,4,'إِلَّا طَرِيقَ جَهَنَّمَ خَـٰلِدِينَ فِيهَآ أَبَدًا ۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا','Illaa tareeqa jahannamma khaalideena feehaa abadaa; wa kaana zaalika \'alal laahi yaseeraa',169,'4:169',11,42,84,1,0,104,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(663,4,'يَـٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَكُمُ ٱلرَّسُولُ بِٱلْحَقِّ مِن رَّبِّكُمْ فَـَٔامِنُوا۟ خَيْرًا لَّكُمْ ۚ وَإِن تَكْفُرُوا۟ فَإِنَّ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا','Yaaa aiyuhan naasu qad jaaa\'akumur Rasoolu bilhaqqi mir Rabbikum fa ammminoo khairal lakum; wa in takfuroo fainnna lillaahi maa fis samaawaati wal ard; wa kaanal laahu \'Aleemann hakeemaa',170,'4:170',11,42,84,1,0,104,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(664,4,'يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لَا تَغْلُوا۟ فِى دِينِكُمْ وَلَا تَقُولُوا۟ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ ۚ إِنَّمَا ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ رَسُولُ ٱللَّهِ وَكَلِمَتُهُۥٓ أَلْقَىٰهَآ إِلَىٰ مَرْيَمَ وَرُوحٌ مِّنْهُ ۖ فَـَٔامِنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ ۖ وَلَا تَقُولُوا۟ ثَلَـٰثَةٌ ۚ ٱنتَهُوا۟ خَيْرًا لَّكُمْ ۚ إِنَّمَا ٱللَّهُ إِلَـٰهٌ وَٰحِدٌ ۖ سُبْحَـٰنَهُۥٓ أَن يَكُونَ لَهُۥ وَلَدٌ ۘ لَّهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَكَفَىٰ بِٱللَّهِ وَكِيلًا','Yaaa Ahlal Kitaabi laa taghloo fee deenikum wa laa taqooloo \'alal laahi illalhaqq; innamal Maseehu \'Eesab-nu-Maryamma Rasoolul laahi wa Kalimatuhooo alqaahaaa ilaa Maryamma wa roohum minhum fa aaminoo billaahi wa Rusulihee wa laa taqooloo salaasah; intahoo khairallakum; innamal laahu Ilaahunw Waahid, Subhaanahooo ani yakoona lahoo walad; lahoo maa fissamaawaati wa maa fil ard; wa kafaa billaahi Wakeelaa',171,'4:171',11,42,84,1,0,105,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(665,4,'لَّن يَسْتَنكِفَ ٱلْمَسِيحُ أَن يَكُونَ عَبْدًا لِّلَّهِ وَلَا ٱلْمَلَـٰٓئِكَةُ ٱلْمُقَرَّبُونَ ۚ وَمَن يَسْتَنكِفْ عَنْ عِبَادَتِهِۦ وَيَسْتَكْبِرْ فَسَيَحْشُرُهُمْ إِلَيْهِ جَمِيعًا','Lanny yastankifal Maseehu ai yakoona \'abdal lillaahi wa lal malaaa\'ikatul muqarraboon; wa mai yastankif \'an ibaadatihee wa yastakbir fasa yahshuruhum ilaihi jamee\'aa',172,'4:172',11,42,85,1,0,105,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(666,4,'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَيُوَفِّيهِمْ أُجُورَهُمْ وَيَزِيدُهُم مِّن فَضْلِهِۦ ۖ وَأَمَّا ٱلَّذِينَ ٱسْتَنكَفُوا۟ وَٱسْتَكْبَرُوا۟ فَيُعَذِّبُهُمْ عَذَابًا أَلِيمًا وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيًّا وَلَا نَصِيرًا','Fa ammal lazeena aamanoo wa \'amilus saalihaati fa yuwaffeehim ujoorahum wa yazeeduhum min fadlihee wa ammal lazeenas tankafoo wastakbaroo fa yu\'azzibuhum \'azaaban aleemanw wa laa yajidoona lahum min doonil laahi waliyyanw wa laa naseeraa',173,'4:173',11,42,85,1,0,105,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(667,4,'يَـٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَكُم بُرْهَـٰنٌ مِّن رَّبِّكُمْ وَأَنزَلْنَآ إِلَيْكُمْ نُورًا مُّبِينًا','yaa aiyuhan naasu qad jaaa\'akum burhaanum mir Rabbikum wa anzalnaaa ilaikum Nooram Mubeena',174,'4:174',11,42,85,1,0,105,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(668,4,'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَٱعْتَصَمُوا۟ بِهِۦ فَسَيُدْخِلُهُمْ فِى رَحْمَةٍ مِّنْهُ وَفَضْلٍ وَيَهْدِيهِمْ إِلَيْهِ صِرَٰطًا مُّسْتَقِيمًا','Fa ammal lazeena aamanoo billaahi wa\'tasamoo bihee fasa yudkhiluhum fee rah matim minhu wa fadlinw wa yahdeehim ilaihi Siraatam Mustaqeema',175,'4:175',11,42,85,1,0,105,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(669,4,'يَسْتَفْتُونَكَ قُلِ ٱللَّهُ يُفْتِيكُمْ فِى ٱلْكَلَـٰلَةِ ۚ إِنِ ٱمْرُؤٌا۟ هَلَكَ لَيْسَ لَهُۥ وَلَدٌ وَلَهُۥٓ أُخْتٌ فَلَهَا نِصْفُ مَا تَرَكَ ۚ وَهُوَ يَرِثُهَآ إِن لَّمْ يَكُن لَّهَا وَلَدٌ ۚ فَإِن كَانَتَا ٱثْنَتَيْنِ فَلَهُمَا ٱلثُّلُثَانِ مِمَّا تَرَكَ ۚ وَإِن كَانُوٓا۟ إِخْوَةً رِّجَالًا وَنِسَآءً فَلِلذَّكَرِ مِثْلُ حَظِّ ٱلْأُنثَيَيْنِ ۗ يُبَيِّنُ ٱللَّهُ لَكُمْ أَن تَضِلُّوا۟ ۗ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌۢ','Yastaftoonaka qulillaahu yafteekum fil kalaalah; inimru\'un halaka laisa lahoo waladunw wa lahoo ukhtun falahaa nisfu maa tarak; wa huwa yarisuhaaa il lam yakkul lahaa walad; fa in kaanatas nataini falahumas sulusaani mimmmaa tarak; wa in kaanooo ikhwatar rijaalanw wa nisaaa\'an faliz zakari mislu hazzil unsayayn; yubaiyinullaahu lakum an tadilloo; wallaahu bikulli shai\'in Aleem',176,'4:176',11,42,85,1,0,106,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(670,5,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَوْفُوا۟ بِٱلْعُقُودِ ۚ أُحِلَّتْ لَكُم بَهِيمَةُ ٱلْأَنْعَـٰمِ إِلَّا مَا يُتْلَىٰ عَلَيْكُمْ غَيْرَ مُحِلِّى ٱلصَّيْدِ وَأَنتُمْ حُرُمٌ ۗ إِنَّ ٱللَّهَ يَحْكُمُ مَا يُرِيدُ','Yaaa aiyuhal lazeena aamanoo awfoo bil\'uqood; uhillat lakum baheematul an\'aami illaa maa yutlaa \'alaikum ghaira muhillis saidi wa antum hurum; innal laaha yahkumu maa yureed',1,'5:1',11,43,86,2,0,106,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(671,5,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُحِلُّوا۟ شَعَـٰٓئِرَ ٱللَّهِ وَلَا ٱلشَّهْرَ ٱلْحَرَامَ وَلَا ٱلْهَدْىَ وَلَا ٱلْقَلَـٰٓئِدَ وَلَآ ءَآمِّينَ ٱلْبَيْتَ ٱلْحَرَامَ يَبْتَغُونَ فَضْلًا مِّن رَّبِّهِمْ وَرِضْوَٰنًا ۚ وَإِذَا حَلَلْتُمْ فَٱصْطَادُوا۟ ۚ وَلَا يَجْرِمَنَّكُمْ شَنَـَٔانُ قَوْمٍ أَن صَدُّوكُمْ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ أَن تَعْتَدُوا۟ ۘ وَتَعَاوَنُوا۟ عَلَى ٱلْبِرِّ وَٱلتَّقْوَىٰ ۖ وَلَا تَعَاوَنُوا۟ عَلَى ٱلْإِثْمِ وَٱلْعُدْوَٰنِ ۚ وَٱتَّقُوا۟ ٱللَّهَ ۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ','Yaaa aiyuhal lazeena aamanoo laa tuhilloo sha\'aaa \'iral laahi wa lash Shahral Haraama wa lal hadya wa lal qalaaa\'ida wa laa aaammeenal Baital Haraama yabtaghoona fadlam mir Rabbihim wa ridwaanaa; wa izaa halaltum fastaadoo; wa laa yajrimannakum shana aanu qawmin an saddookum \'anil Masjidil-Haraami an ta\'tadoo; wa ta\'aawanoo \'alalbirri wattaqwaa; wa laa ta\'aawanoo \'alal ismi wal\'udwaan; wattaqul laah; innal laaha shadeedul \'iqaab',2,'5:2',11,43,86,2,0,106,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(672,5,'حُرِّمَتْ عَلَيْكُمُ ٱلْمَيْتَةُ وَٱلدَّمُ وَلَحْمُ ٱلْخِنزِيرِ وَمَآ أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ وَٱلْمُنْخَنِقَةُ وَٱلْمَوْقُوذَةُ وَٱلْمُتَرَدِّيَةُ وَٱلنَّطِيحَةُ وَمَآ أَكَلَ ٱلسَّبُعُ إِلَّا مَا ذَكَّيْتُمْ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ وَأَن تَسْتَقْسِمُوا۟ بِٱلْأَزْلَـٰمِ ۚ ذَٰلِكُمْ فِسْقٌ ۗ ٱلْيَوْمَ يَئِسَ ٱلَّذِينَ كَفَرُوا۟ مِن دِينِكُمْ فَلَا تَخْشَوْهُمْ وَٱخْشَوْنِ ۚ ٱلْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِى وَرَضِيتُ لَكُمُ ٱلْإِسْلَـٰمَ دِينًا ۚ فَمَنِ ٱضْطُرَّ فِى مَخْمَصَةٍ غَيْرَ مُتَجَانِفٍ لِّإِثْمٍ ۙ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ','Hurrimat \'alaikumul maitatu waddamu wa lahmul khinzeeri wa maaa uhilla lighiril laahi bihee walmun khani qatu wal mawqoozatu wal mutarad diyatu wanna teehatu wa maaa akalas sabu\'u illaa maa zakkaitum wa maa zubiha \'alan nusubi wa an tastaqsimoo bil azlaam; zaalikum fisq; alyawma ya\'isal lazeena kafaroo min deenikum falaa takhshawhum wakh shawn; alyawma akmaltu lakum deenakum wa atmamtu \'alaikum ni\'matee wa radeetu lakumul Islaama deenaa; famanidturra fee makhmasatin ghaira mutajaanifil li ismin fa innallaaha Ghafoorur Raheem',3,'5:3',11,43,86,2,0,107,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(673,5,'يَسْـَٔلُونَكَ مَاذَآ أُحِلَّ لَهُمْ ۖ قُلْ أُحِلَّ لَكُمُ ٱلطَّيِّبَـٰتُ ۙ وَمَا عَلَّمْتُم مِّنَ ٱلْجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ ٱللَّهُ ۖ فَكُلُوا۟ مِمَّآ أَمْسَكْنَ عَلَيْكُمْ وَٱذْكُرُوا۟ ٱسْمَ ٱللَّهِ عَلَيْهِ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ','Yas\'aloonaka maazaaa uhilla lahum; qul uhilla lakumuttaiyibaatu wa maa\'allamtum minal jawaarihi mukallibeena tu\'allimoonahunnamimmaa \'allamakumul laahu fakuloo mimmaaa amsakna \'alaikum wazkurus mal laahi \'alaih; wattaqul laah; innal laaha saree\'ul hisaab',4,'5:4',11,43,86,2,0,107,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(674,5,'ٱلْيَوْمَ أُحِلَّ لَكُمُ ٱلطَّيِّبَـٰتُ ۖ وَطَعَامُ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ حِلٌّ لَّكُمْ وَطَعَامُكُمْ حِلٌّ لَّهُمْ ۖ وَٱلْمُحْصَنَـٰتُ مِنَ ٱلْمُؤْمِنَـٰتِ وَٱلْمُحْصَنَـٰتُ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ مِن قَبْلِكُمْ إِذَآ ءَاتَيْتُمُوهُنَّ أُجُورَهُنَّ مُحْصِنِينَ غَيْرَ مُسَـٰفِحِينَ وَلَا مُتَّخِذِىٓ أَخْدَانٍ ۗ وَمَن يَكْفُرْ بِٱلْإِيمَـٰنِ فَقَدْ حَبِطَ عَمَلُهُۥ وَهُوَ فِى ٱلْـَٔاخِرَةِ مِنَ ٱلْخَـٰسِرِينَ','Alyawma uhilla lakumut taiyibaatu wa ta\'aamul lazeena ootul Kitaaba hillul lakum wa ta\'aamukum hillul lahum wal muhsanaatu minal mu\'minaati walmuhsanaatu minal lazeena ootul Kitaaba min qablikum izaaa aataitumoohunna ujoorahunna muhsineena ghaira musaafiheena wa laa muttakhizeee akhdaan; wa mai yakfur bil eemaani faqad habita \'amaluhoo wa huwa fil Aaakhirati minal khaasireen',5,'5:5',11,43,86,2,0,107,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(675,5,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا قُمْتُمْ إِلَى ٱلصَّلَوٰةِ فَٱغْسِلُوا۟ وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى ٱلْمَرَافِقِ وَٱمْسَحُوا۟ بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى ٱلْكَعْبَيْنِ ۚ وَإِن كُنتُمْ جُنُبًا فَٱطَّهَّرُوا۟ ۚ وَإِن كُنتُم مَّرْضَىٰٓ أَوْ عَلَىٰ سَفَرٍ أَوْ جَآءَ أَحَدٌ مِّنكُم مِّنَ ٱلْغَآئِطِ أَوْ لَـٰمَسْتُمُ ٱلنِّسَآءَ فَلَمْ تَجِدُوا۟ مَآءً فَتَيَمَّمُوا۟ صَعِيدًا طَيِّبًا فَٱمْسَحُوا۟ بِوُجُوهِكُمْ وَأَيْدِيكُم مِّنْهُ ۚ مَا يُرِيدُ ٱللَّهُ لِيَجْعَلَ عَلَيْكُم مِّنْ حَرَجٍ وَلَـٰكِن يُرِيدُ لِيُطَهِّرَكُمْ وَلِيُتِمَّ نِعْمَتَهُۥ عَلَيْكُمْ لَعَلَّكُمْ تَشْكُرُونَ','Yaaa aiyuhal lazeena aamanoo izaa qumtum ilas Salaati faghsiloo wujoohakum wa Aidiyakum ilal maraafiqi wamsahoo biru\'oosikum wa arjulakum ilal ka\'bayn; wa in kuntum junuban fattahharoo; wain kuntum mardaaa aw\'alaa safarin aw jaaa\'a ahadum minkum minal ghaaa\'iti aw laamastumunnisaaa\'a falam tajidoo maaa\'an fatayammamoo sa\'eedan taiyiban famsahoo biwujoohikum wa aideekum minh; ma yureedul laahu liyaj\'ala \'alaikum min harajinw wa laakidy yureedu liyutahhirakum wa liyutimma m\'matahoo \'alaikum la\'allakum tashkuroon',6,'5:6',11,43,87,2,0,108,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(676,5,'وَٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ وَمِيثَـٰقَهُ ٱلَّذِى وَاثَقَكُم بِهِۦٓ إِذْ قُلْتُمْ سَمِعْنَا وَأَطَعْنَا ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ','Wazkuroo ni\'matal laahi \'alaikum wa meesaaqahul lazee waasaqakum biheee iz qultum sami\'naa wa ata\'naa wattaqul laah; innal laaha \'aleemum bizaatis sudoor',7,'5:7',11,43,87,2,0,108,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(677,5,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوا۟ قَوَّٰمِينَ لِلَّهِ شُهَدَآءَ بِٱلْقِسْطِ ۖ وَلَا يَجْرِمَنَّكُمْ شَنَـَٔانُ قَوْمٍ عَلَىٰٓ أَلَّا تَعْدِلُوا۟ ۚ ٱعْدِلُوا۟ هُوَ أَقْرَبُ لِلتَّقْوَىٰ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ','Yaaa aiyuhal lazeena aamaanoo koonoo qawwaa meena lillaahi shuhadaaa\'a bilqist, wa laa yajrimannakum shana aanu qawmin \'alaaa allaa ta\'diloo; i\'diloo; huwa aqrabu littaqwaa wattaqul laah; innal laaha khabeerum bimaa ta\'maloon',8,'5:8',11,43,87,2,0,108,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(678,5,'وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ ۙ لَهُم مَّغْفِرَةٌ وَأَجْرٌ عَظِيمٌ','Wa\'adal laahul lazeena aamanoo wa \'amilus saalihaati lahum maghfiratunw wa ajrun \'azeem',9,'5:9',11,43,87,2,0,108,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(679,5,'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَـٰتِنَآ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْجَحِيمِ','Wallazeena kafaroo wa kazzaboo bi Aayaatinaaa ulaaa\'ika Ashaabul Jaheem',10,'5:10',11,43,87,2,0,109,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(680,5,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ إِذْ هَمَّ قَوْمٌ أَن يَبْسُطُوٓا۟ إِلَيْكُمْ أَيْدِيَهُمْ فَكَفَّ أَيْدِيَهُمْ عَنكُمْ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ','Yaa aiyuhal lazeena aamanuz kuroo ni\'matallaahi \'alaikum iz hamma qawmun ai yabsutooo ilaikum aidiyahm fakaffa aidiyahum \'ankum wattaqullaah; wa\'alal laahi fal yatawakalil mu\'minoon',11,'5:11',11,43,87,2,0,109,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(681,5,'۞ وَلَقَدْ أَخَذَ ٱللَّهُ مِيثَـٰقَ بَنِىٓ إِسْرَٰٓءِيلَ وَبَعَثْنَا مِنْهُمُ ٱثْنَىْ عَشَرَ نَقِيبًا ۖ وَقَالَ ٱللَّهُ إِنِّى مَعَكُمْ ۖ لَئِنْ أَقَمْتُمُ ٱلصَّلَوٰةَ وَءَاتَيْتُمُ ٱلزَّكَوٰةَ وَءَامَنتُم بِرُسُلِى وَعَزَّرْتُمُوهُمْ وَأَقْرَضْتُمُ ٱللَّهَ قَرْضًا حَسَنًا لَّأُكَفِّرَنَّ عَنكُمْ سَيِّـَٔاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ۚ فَمَن كَفَرَ بَعْدَ ذَٰلِكَ مِنكُمْ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ','Wa laqad akhazal laahu meesaaqa Banee Israaa\'eela wa ba\'sanaa minhumus ani \'ashara naqeebanw wa qaalal laahu innee ma\'akum la\'in aqamtumus Salaata wa aataitumuz Zakaata wa aamantum bi Rusulee wa\'azzartumoohum wa aqradtumul laaha qardan hasanal la ukaffiranna \'ankum saiyiaatikum wa la udkhilan nakum Jannaatin tajree min tahtihal anhaar; faman kafara ba\'da zaalika minkum faqad dalla sawaaa\'as Sabeel',12,'5:12',11,44,88,2,0,109,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(682,5,'فَبِمَا نَقْضِهِم مِّيثَـٰقَهُمْ لَعَنَّـٰهُمْ وَجَعَلْنَا قُلُوبَهُمْ قَـٰسِيَةً ۖ يُحَرِّفُونَ ٱلْكَلِمَ عَن مَّوَاضِعِهِۦ ۙ وَنَسُوا۟ حَظًّا مِّمَّا ذُكِّرُوا۟ بِهِۦ ۚ وَلَا تَزَالُ تَطَّلِعُ عَلَىٰ خَآئِنَةٍ مِّنْهُمْ إِلَّا قَلِيلًا مِّنْهُمْ ۖ فَٱعْفُ عَنْهُمْ وَٱصْفَحْ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُحْسِنِينَ','Fabimaa naqdihim meesaa qahum la\'annaahum wa ja\'alnaa quloobahum qaasiyatany yuharrifoonal kalima \'ammawaadi\'ihee wa nasoo hazzam mimmaa zukkiroo bih; khaaa\'inatim minhum illaa qaleelam minhum fa\'fu \'anhum wasfah; innal laaha yuhibbul muhsineen',13,'5:13',11,44,88,2,0,109,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(683,5,'وَمِنَ ٱلَّذِينَ قَالُوٓا۟ إِنَّا نَصَـٰرَىٰٓ أَخَذْنَا مِيثَـٰقَهُمْ فَنَسُوا۟ حَظًّا مِّمَّا ذُكِّرُوا۟ بِهِۦ فَأَغْرَيْنَا بَيْنَهُمُ ٱلْعَدَاوَةَ وَٱلْبَغْضَآءَ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ ۚ وَسَوْفَ يُنَبِّئُهُمُ ٱللَّهُ بِمَا كَانُوا۟ يَصْنَعُونَ','Wa minal lazeena qaalooo innaa nasaaraaa akhaznaa meesaaqahum fanasoo hazzam mimmaa zukkiroo bihee fa aghrainaa binahumul \'adaawata walbaghdaaa\'a ilaa yawmil Qiyaamah; wa sawfa yunabbi\'uhumul laahu bimaa kaanoo yasna\'oon',14,'5:14',11,44,88,2,0,110,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(684,5,'يَـٰٓأَهْلَ ٱلْكِتَـٰبِ قَدْ جَآءَكُمْ رَسُولُنَا يُبَيِّنُ لَكُمْ كَثِيرًا مِّمَّا كُنتُمْ تُخْفُونَ مِنَ ٱلْكِتَـٰبِ وَيَعْفُوا۟ عَن كَثِيرٍ ۚ قَدْ جَآءَكُم مِّنَ ٱللَّهِ نُورٌ وَكِتَـٰبٌ مُّبِينٌ','yaaa Ahlal kitaabi qad jaaa\'akum Rasoolunaa yubaiyinu lakum kaseeram mimmmaa kuntum tukhfoona minal Kitaabi wa ya\'foo \'an kaseer; qad jaaa\'akum minal laahi noorunw wa Kitaabum Mubeen',15,'5:15',11,44,88,2,0,110,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(685,5,'يَهْدِى بِهِ ٱللَّهُ مَنِ ٱتَّبَعَ رِضْوَٰنَهُۥ سُبُلَ ٱلسَّلَـٰمِ وَيُخْرِجُهُم مِّنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ بِإِذْنِهِۦ وَيَهْدِيهِمْ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ','Yahdee bihil laahu manit taba\'a ridwaanahoo subulas salaami wa yukhrijuhum minaz zulumaati ilan noori bi iznihee wa yahdeehim ilaa Siraatim Mustaqeem',16,'5:16',11,44,88,2,0,110,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(686,5,'لَّقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ هُوَ ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ ۚ قُلْ فَمَن يَمْلِكُ مِنَ ٱللَّهِ شَيْـًٔا إِنْ أَرَادَ أَن يُهْلِكَ ٱلْمَسِيحَ ٱبْنَ مَرْيَمَ وَأُمَّهُۥ وَمَن فِى ٱلْأَرْضِ جَمِيعًا ۗ وَلِلَّهِ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ۚ يَخْلُقُ مَا يَشَآءُ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ','Laqad kafaral lazeena qaalooo innal laaha huwal maseehub nu Maryam; qul famany-yamliku minal laahi shai\'an in araada ai yuhlikal Maseehab na Maryama wa ummahoo wa man fil ardi jamee\'aa, wa lillaahi mmulkus samaawaati wal ardi wa maa bainahumaa; yakhluqu maa Yashaaa\'; wakhluqu maa yashaaa\'; wallaahu \'alaa kulli shai\'in Qadeer',17,'5:17',11,44,88,2,0,110,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(687,5,'وَقَالَتِ ٱلْيَهُودُ وَٱلنَّصَـٰرَىٰ نَحْنُ أَبْنَـٰٓؤُا۟ ٱللَّهِ وَأَحِبَّـٰٓؤُهُۥ ۚ قُلْ فَلِمَ يُعَذِّبُكُم بِذُنُوبِكُم ۖ بَلْ أَنتُم بَشَرٌ مِّمَّنْ خَلَقَ ۚ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ ۚ وَلِلَّهِ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ۖ وَإِلَيْهِ ٱلْمَصِيرُ','Wa qaalatil Yahoodu wan Nasaaraa nahnu abnaaa\'ul laahi wa ahibbaaa\'uh; qul falima yu\'azzibukum bizunoobikum bal antum basharum mimmman khalaq; yaghfiru limai yashaaa\'u wa yu\'azzibu mai yashaaa\'; wa lillaahi mulkus samaawaati wal ardi wa maa bainahumaa wa ilaihil maseer',18,'5:18',11,44,88,2,0,111,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(688,5,'يَـٰٓأَهْلَ ٱلْكِتَـٰبِ قَدْ جَآءَكُمْ رَسُولُنَا يُبَيِّنُ لَكُمْ عَلَىٰ فَتْرَةٍ مِّنَ ٱلرُّسُلِ أَن تَقُولُوا۟ مَا جَآءَنَا مِنۢ بَشِيرٍ وَلَا نَذِيرٍ ۖ فَقَدْ جَآءَكُم بَشِيرٌ وَنَذِيرٌ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ','Yaaa Ahlal Kitaabi qad jaaa\'akum Rasoolunaa yubaiyinu lakum \'alaa fatratim minal Rusuli an taqooloo maa jaaa\'anaa mim basheerinw wa laa nazeerin faqad jaaa\'akum basheerunw wa nazeer; wallaahu \'alaa kulli shai\'in Qadeer',19,'5:19',11,44,88,2,0,111,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(689,5,'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَـٰقَوْمِ ٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ إِذْ جَعَلَ فِيكُمْ أَنۢبِيَآءَ وَجَعَلَكُم مُّلُوكًا وَءَاتَىٰكُم مَّا لَمْ يُؤْتِ أَحَدًا مِّنَ ٱلْعَـٰلَمِينَ','Qa iz qaala Moosaa liqawmihee yaa qawmiz kuroo ni\'matal laahi \'alaikum iz ja\'ala feekum mulookanw wa aataakum maa lam yu\'ti ahadam minal \'aalameen',20,'5:20',11,44,89,2,0,111,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(690,5,'يَـٰقَوْمِ ٱدْخُلُوا۟ ٱلْأَرْضَ ٱلْمُقَدَّسَةَ ٱلَّتِى كَتَبَ ٱللَّهُ لَكُمْ وَلَا تَرْتَدُّوا۟ عَلَىٰٓ أَدْبَارِكُمْ فَتَنقَلِبُوا۟ خَـٰسِرِينَ','Yaa qawmid khulul Ardal MMuqaddasatal latee katabal laahu lakum wa laa tartaddoo \'alaaa adbaarikum fatanqaliboo khaasireen',21,'5:21',11,44,89,2,0,111,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(691,5,'قَالُوا۟ يَـٰمُوسَىٰٓ إِنَّ فِيهَا قَوْمًا جَبَّارِينَ وَإِنَّا لَن نَّدْخُلَهَا حَتَّىٰ يَخْرُجُوا۟ مِنْهَا فَإِن يَخْرُجُوا۟ مِنْهَا فَإِنَّا دَٰخِلُونَ','Qaaloo yaa Moosaaa innaa feehaa qwman jabbaareena wa innaa lan nadkhulahaa hattaa yakhrujoo minhaa fa innaa daakhiloon',22,'5:22',11,44,89,2,0,111,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(692,5,'قَالَ رَجُلَانِ مِنَ ٱلَّذِينَ يَخَافُونَ أَنْعَمَ ٱللَّهُ عَلَيْهِمَا ٱدْخُلُوا۟ عَلَيْهِمُ ٱلْبَابَ فَإِذَا دَخَلْتُمُوهُ فَإِنَّكُمْ غَـٰلِبُونَ ۚ وَعَلَى ٱللَّهِ فَتَوَكَّلُوٓا۟ إِن كُنتُم مُّؤْمِنِينَ','Qaala rajulaani minal lazeena yakhaafoona an\'amal laahu \'alaihimad khuloo \'alaihimul baab, fa izaa dakhaltumoohu fa innakum ghaaliboon; wa \'alal laahi fatawakkalooo in kuntum mu\'mineen',23,'5:23',11,44,89,2,0,111,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(693,5,'قَالُوا۟ يَـٰمُوسَىٰٓ إِنَّا لَن نَّدْخُلَهَآ أَبَدًا مَّا دَامُوا۟ فِيهَا ۖ فَٱذْهَبْ أَنتَ وَرَبُّكَ فَقَـٰتِلَآ إِنَّا هَـٰهُنَا قَـٰعِدُونَ','Qaaloo yaa Moosaaa innaa lan nadkhulahaa abadam maa daamoo feehaa fazhab anta wa Rabbuka faqaatilaaa innaa haahunaa qaa\'idoon',24,'5:24',11,44,89,2,0,112,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(694,5,'قَالَ رَبِّ إِنِّى لَآ أَمْلِكُ إِلَّا نَفْسِى وَأَخِى ۖ فَٱفْرُقْ بَيْنَنَا وَبَيْنَ ٱلْقَوْمِ ٱلْفَـٰسِقِينَ','Qaala Rabbi innee laaa amliku illaa nafsee wa akhee fafruq bainanaa wa bainal qawmil faasiqeen',25,'5:25',11,44,89,2,0,112,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(695,5,'قَالَ فَإِنَّهَا مُحَرَّمَةٌ عَلَيْهِمْ ۛ أَرْبَعِينَ سَنَةً ۛ يَتِيهُونَ فِى ٱلْأَرْضِ ۚ فَلَا تَأْسَ عَلَى ٱلْقَوْمِ ٱلْفَـٰسِقِينَ','Qaala fa innahaa muhar ramatun \'alaihim arba\'eena sanah; yateehoona fil ard; falaa taasa \'alal qawmil faasiqeen',26,'5:26',11,44,89,2,0,112,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(696,5,'۞ وَٱتْلُ عَلَيْهِمْ نَبَأَ ٱبْنَىْ ءَادَمَ بِٱلْحَقِّ إِذْ قَرَّبَا قُرْبَانًا فَتُقُبِّلَ مِنْ أَحَدِهِمَا وَلَمْ يُتَقَبَّلْ مِنَ ٱلْـَٔاخَرِ قَالَ لَأَقْتُلَنَّكَ ۖ قَالَ إِنَّمَا يَتَقَبَّلُ ٱللَّهُ مِنَ ٱلْمُتَّقِينَ','Watlu \'alaihim naba abnai Aadama bilhaqq; iz qarrabaa qurbaanan fatuqubbila min ahadihimaa wa lam yutaqabbal minal aakhari qaala la aqtulannnaka qaala innamaa yataqabbalul laahu minal muttaqeen',27,'5:27',12,45,90,2,0,112,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(697,5,'لَئِنۢ بَسَطتَ إِلَىَّ يَدَكَ لِتَقْتُلَنِى مَآ أَنَا۠ بِبَاسِطٍ يَدِىَ إِلَيْكَ لِأَقْتُلَكَ ۖ إِنِّىٓ أَخَافُ ٱللَّهَ رَبَّ ٱلْعَـٰلَمِينَ','La\'im basatta ilaiya yadaka litaqtulanee maaa ana bibaasitiny yadiya ilaika li aqtulaka inneee akhaaful laaha Rabbal \'aalameen',28,'5:28',12,45,90,2,0,112,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(698,5,'إِنِّىٓ أُرِيدُ أَن تَبُوٓأَ بِإِثْمِى وَإِثْمِكَ فَتَكُونَ مِنْ أَصْحَـٰبِ ٱلنَّارِ ۚ وَذَٰلِكَ جَزَٰٓؤُا۟ ٱلظَّـٰلِمِينَ','Inee ureedu an tabooo\'a bi ismee wa ismika fatakoona min Ashaabin Naar; wa zaalika jazaaa\'uz zaalimeen',29,'5:29',12,45,90,2,0,112,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(699,5,'فَطَوَّعَتْ لَهُۥ نَفْسُهُۥ قَتْلَ أَخِيهِ فَقَتَلَهُۥ فَأَصْبَحَ مِنَ ٱلْخَـٰسِرِينَ','Fatawwa\'at lahoo nafsu hoo qatla akheehi faqatalahoo fa asbaha minal khaasireen',30,'5:30',12,45,90,2,0,112,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(700,5,'فَبَعَثَ ٱللَّهُ غُرَابًا يَبْحَثُ فِى ٱلْأَرْضِ لِيُرِيَهُۥ كَيْفَ يُوَٰرِى سَوْءَةَ أَخِيهِ ۚ قَالَ يَـٰوَيْلَتَىٰٓ أَعَجَزْتُ أَنْ أَكُونَ مِثْلَ هَـٰذَا ٱلْغُرَابِ فَأُوَٰرِىَ سَوْءَةَ أَخِى ۖ فَأَصْبَحَ مِنَ ٱلنَّـٰدِمِينَ','Faba\'asal laahu ghuraabai yabhasu fil ardi liyuriyahoo kaifa yuwaaree sawata akheeh; qaala yaa wailataaa a\'ajaztu an akoona misla haazal ghuraabi fa uwaariya saw ata akhee fa asbaha minan naadimeen',31,'5:31',12,45,90,2,0,112,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(701,5,'مِنْ أَجْلِ ذَٰلِكَ كَتَبْنَا عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَنَّهُۥ مَن قَتَلَ نَفْسًۢا بِغَيْرِ نَفْسٍ أَوْ فَسَادٍ فِى ٱلْأَرْضِ فَكَأَنَّمَا قَتَلَ ٱلنَّاسَ جَمِيعًا وَمَنْ أَحْيَاهَا فَكَأَنَّمَآ أَحْيَا ٱلنَّاسَ جَمِيعًا ۚ وَلَقَدْ جَآءَتْهُمْ رُسُلُنَا بِٱلْبَيِّنَـٰتِ ثُمَّ إِنَّ كَثِيرًا مِّنْهُم بَعْدَ ذَٰلِكَ فِى ٱلْأَرْضِ لَمُسْرِفُونَ','min ajli zaalika katabnaa \'alaa Banee Israaa\'eela annahoo man qatala nnafsam bighairi nafsin aw fasaadin fil ardi faka annnamaa qatalan fil ardi faka annammaa qatalan naasa jamee\'anw wa man ahyaahaa faka annamaaa ahyan naasa jamee\'aa; wa laqad jaaa\'at hum Rusulunaa bilbaiyinaati summa inna kaseeram minhum ba\'da zaalika fil ardi lamusrifoon',32,'5:32',12,45,90,2,0,113,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(702,5,'إِنَّمَا جَزَٰٓؤُا۟ ٱلَّذِينَ يُحَارِبُونَ ٱللَّهَ وَرَسُولَهُۥ وَيَسْعَوْنَ فِى ٱلْأَرْضِ فَسَادًا أَن يُقَتَّلُوٓا۟ أَوْ يُصَلَّبُوٓا۟ أَوْ تُقَطَّعَ أَيْدِيهِمْ وَأَرْجُلُهُم مِّنْ خِلَـٰفٍ أَوْ يُنفَوْا۟ مِنَ ٱلْأَرْضِ ۚ ذَٰلِكَ لَهُمْ خِزْىٌ فِى ٱلدُّنْيَا ۖ وَلَهُمْ فِى ٱلْـَٔاخِرَةِ عَذَابٌ عَظِيمٌ','Innamaa jazaaa\'ul lazeena yuhaariboonal laaha wa Rasoolahoo wa yas\'awna fil ardi fasaadan ai yuqattalooo aw yusallabooo aw tuqatta\'a aideehim wa arjuluhum min khilaafin aw yunfaw minalard; zaalika lahum khizyun fid dunyaa wa lahum fil Aakhirati \'azaabun \'azeem',33,'5:33',12,45,90,2,0,113,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(703,5,'إِلَّا ٱلَّذِينَ تَابُوا۟ مِن قَبْلِ أَن تَقْدِرُوا۟ عَلَيْهِمْ ۖ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ','Illal lazeena taaboo min qabli an taqdiroo \'alaihim fa\'lamooo annnal laaha Ghafoorur Raheem',34,'5:34',12,45,90,2,0,113,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(704,5,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَٱبْتَغُوٓا۟ إِلَيْهِ ٱلْوَسِيلَةَ وَجَـٰهِدُوا۟ فِى سَبِيلِهِۦ لَعَلَّكُمْ تُفْلِحُونَ','yaaa aiyuhal lazeena aamanut taqul laaha wabtaghooo ilaihil waseelata wa jaahidoo fee sabeelihee la\'allakum tuflihoon',35,'5:35',12,45,91,2,0,113,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(705,5,'إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَوْ أَنَّ لَهُم مَّا فِى ٱلْأَرْضِ جَمِيعًا وَمِثْلَهُۥ مَعَهُۥ لِيَفْتَدُوا۟ بِهِۦ مِنْ عَذَابِ يَوْمِ ٱلْقِيَـٰمَةِ مَا تُقُبِّلَ مِنْهُمْ ۖ وَلَهُمْ عَذَابٌ أَلِيمٌ','Innal lazeena kafaroo law anna lahum maa fil ardi jamee\'anw wa mislahoo ma\'ahoo liyaftadoo bihee min \'azaabi Yawmil Qiyaamati maa tuqubbila minhum wa lahum azaabun aleem',36,'5:36',12,45,91,2,0,113,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(706,5,'يُرِيدُونَ أَن يَخْرُجُوا۟ مِنَ ٱلنَّارِ وَمَا هُم بِخَـٰرِجِينَ مِنْهَا ۖ وَلَهُمْ عَذَابٌ مُّقِيمٌ','Yureedoona ai yakhrujoo minan Naari wa maa hum bikhaari jeena minhaa wa lahum \'azaabum muqeem',37,'5:37',12,45,91,2,0,114,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(707,5,'وَٱلسَّارِقُ وَٱلسَّارِقَةُ فَٱقْطَعُوٓا۟ أَيْدِيَهُمَا جَزَآءًۢ بِمَا كَسَبَا نَكَـٰلًا مِّنَ ٱللَّهِ ۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ','Wassaariqu qassaariqatu faqta\'oo aidiyahumma jazaaa\'am bimaa kasabaa nakaalam minal laah; wallaahu \'Azeezun hakeem',38,'5:38',12,45,91,2,0,114,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(708,5,'فَمَن تَابَ مِنۢ بَعْدِ ظُلْمِهِۦ وَأَصْلَحَ فَإِنَّ ٱللَّهَ يَتُوبُ عَلَيْهِ ۗ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ','Faman taaba mim ba\'di zulmihee wa aslaha fa innal laaha yatoobu \'alaih; innal laaha Ghafoorur Raheem',39,'5:39',12,45,91,2,0,114,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(709,5,'أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ يُعَذِّبُ مَن يَشَآءُ وَيَغْفِرُ لِمَن يَشَآءُ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ','Alam ta\'lam annal laaha lahoo mulkus samaawaati wal ardi yu\'az zibu many-yashaa\'u wa yaghfiru limany-yashaaa\'; wallaahu \'alaa kulli shai\'in Qadeer',40,'5:40',12,45,91,2,0,114,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(710,5,'۞ يَـٰٓأَيُّهَا ٱلرَّسُولُ لَا يَحْزُنكَ ٱلَّذِينَ يُسَـٰرِعُونَ فِى ٱلْكُفْرِ مِنَ ٱلَّذِينَ قَالُوٓا۟ ءَامَنَّا بِأَفْوَٰهِهِمْ وَلَمْ تُؤْمِن قُلُوبُهُمْ ۛ وَمِنَ ٱلَّذِينَ هَادُوا۟ ۛ سَمَّـٰعُونَ لِلْكَذِبِ سَمَّـٰعُونَ لِقَوْمٍ ءَاخَرِينَ لَمْ يَأْتُوكَ ۖ يُحَرِّفُونَ ٱلْكَلِمَ مِنۢ بَعْدِ مَوَاضِعِهِۦ ۖ يَقُولُونَ إِنْ أُوتِيتُمْ هَـٰذَا فَخُذُوهُ وَإِن لَّمْ تُؤْتَوْهُ فَٱحْذَرُوا۟ ۚ وَمَن يُرِدِ ٱللَّهُ فِتْنَتَهُۥ فَلَن تَمْلِكَ لَهُۥ مِنَ ٱللَّهِ شَيْـًٔا ۚ أُو۟لَـٰٓئِكَ ٱلَّذِينَ لَمْ يُرِدِ ٱللَّهُ أَن يُطَهِّرَ قُلُوبَهُمْ ۚ لَهُمْ فِى ٱلدُّنْيَا خِزْىٌ ۖ وَلَهُمْ فِى ٱلْـَٔاخِرَةِ عَذَابٌ عَظِيمٌ','Yaaa ayyuhar Rasoolu laa yahzukal lazeena yusaa ri\'oona fil kufri minal lazeena qaaloo aamannaa bi afwaahihim wa lam tu\'min quloobuhum; wa minal lazeena haadoo sammaa\'oona lilkazibi sammaa\'oona liqawmin aakhareena lam yaatooka yuharifoonal kalima mim ba\'di mawaadi\'ihee yaqooloona in ooteetum haazaa fakhuzoohu wa il lam tu\'tawhu fahzaroo; wa many-yuridil laahu fitnatahoo falan tamlika lahoo minal laahi shai\'aa; ulaaa \'ikal lazeena lam yuridil laahu any-yutahhira quloobahum; lahum fid dunyaa khizyunw wa lahum fil Aakhirati\'azaabun \'azeem',41,'5:41',12,46,91,2,0,114,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(711,5,'سَمَّـٰعُونَ لِلْكَذِبِ أَكَّـٰلُونَ لِلسُّحْتِ ۚ فَإِن جَآءُوكَ فَٱحْكُم بَيْنَهُمْ أَوْ أَعْرِضْ عَنْهُمْ ۖ وَإِن تُعْرِضْ عَنْهُمْ فَلَن يَضُرُّوكَ شَيْـًٔا ۖ وَإِنْ حَكَمْتَ فَٱحْكُم بَيْنَهُم بِٱلْقِسْطِ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ','Sammaa\'oona lilkazibi akkaaloona lissuht; fa in jaaa\'ooka fahkum bainahum aw a\'rid anhum wa in tu\'rid \'anhum falany-yadurrooka shai\'anw wa in hakamta fahkum bainahum bilqist; innal laaha yuhibbul muqsiteen',42,'5:42',12,46,91,2,0,115,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(712,5,'وَكَيْفَ يُحَكِّمُونَكَ وَعِندَهُمُ ٱلتَّوْرَىٰةُ فِيهَا حُكْمُ ٱللَّهِ ثُمَّ يَتَوَلَّوْنَ مِنۢ بَعْدِ ذَٰلِكَ ۚ وَمَآ أُو۟لَـٰٓئِكَ بِٱلْمُؤْمِنِينَ','Wa kaifa yuhakkimoonaka wa \'indahumut Tawraatu feehaa hukmul laahi summa yatawallawna mim ba\'di zaalik; wa maaa ulaaa\'ika bilmu\'mineen',43,'5:43',12,46,91,2,0,115,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(713,5,'إِنَّآ أَنزَلْنَا ٱلتَّوْرَىٰةَ فِيهَا هُدًى وَنُورٌ ۚ يَحْكُمُ بِهَا ٱلنَّبِيُّونَ ٱلَّذِينَ أَسْلَمُوا۟ لِلَّذِينَ هَادُوا۟ وَٱلرَّبَّـٰنِيُّونَ وَٱلْأَحْبَارُ بِمَا ٱسْتُحْفِظُوا۟ مِن كِتَـٰبِ ٱللَّهِ وَكَانُوا۟ عَلَيْهِ شُهَدَآءَ ۚ فَلَا تَخْشَوُا۟ ٱلنَّاسَ وَٱخْشَوْنِ وَلَا تَشْتَرُوا۟ بِـَٔايَـٰتِى ثَمَنًا قَلِيلًا ۚ وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْكَـٰفِرُونَ','Innaaa anzalnat Tawraata feehaa hudanw wa noor; yahkumu bihan Nabiyyoonal lazeena aslamoo lillazeena haadoo war rabbaaniyyoona wal ahbaaru bimas tuhfizoo min Kitaabil laahi wa kaanoo \'alaihi shuhadaaa\'; falaa takhshawun naasa wakhshawni wa laa tashtaroo bi aayaatee samanan qaleelaa; wa mal lam yahkum bimaaa anzalal laahu fa ulaaa\'ika humul kaafiroon',44,'5:44',12,46,92,2,0,115,6,'2023-12-01 11:30:04','2026-09-22 00:06:41'),(714,5,'وَكَتَبْنَا عَلَيْهِمْ فِيهَآ أَنَّ ٱلنَّفْسَ بِٱلنَّفْسِ وَٱلْعَيْنَ بِٱلْعَيْنِ وَٱلْأَنفَ بِٱلْأَنفِ وَٱلْأُذُنَ بِٱلْأُذُنِ وَٱلسِّنَّ بِٱلسِّنِّ وَٱلْجُرُوحَ قِصَاصٌ ۚ فَمَن تَصَدَّقَ بِهِۦ فَهُوَ كَفَّارَةٌ لَّهُۥ ۚ وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ','Wa katabnaa \'alaihim feehaaa annan nafsa binnafsi wal\'aina bil\'aini wal anfa bilanfi wal uzuna bil uzuni wassinna bissinni waljurooha qisaas; faman tasaddaqa bihee fahuwa kaffaaratul lah; wa mal lam yahkum bimaaa anzalal laahu fa ulaaa\'ika humuz zalimoon',45,'5:45',12,46,92,2,0,115,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(715,5,'وَقَفَّيْنَا عَلَىٰٓ ءَاثَـٰرِهِم بِعِيسَى ٱبْنِ مَرْيَمَ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلتَّوْرَىٰةِ ۖ وَءَاتَيْنَـٰهُ ٱلْإِنجِيلَ فِيهِ هُدًى وَنُورٌ وَمُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلتَّوْرَىٰةِ وَهُدًى وَمَوْعِظَةً لِّلْمُتَّقِينَ','Wa qaffainaa \'alaaa aasaaarihim bi \'Eesab ni Maryama musaddiqal limaa baina yadihi minat Tawraati wa aatainaahul Injeela feehi hudanw wa noorunw wa musaddiqal limaa baina yadaihi minat Tawraati wa hudanw wa maw\'izatal lilmuttaqeen',46,'5:46',12,46,92,2,0,116,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(716,5,'وَلْيَحْكُمْ أَهْلُ ٱلْإِنجِيلِ بِمَآ أَنزَلَ ٱللَّهُ فِيهِ ۚ وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْفَـٰسِقُونَ','Walyahkum Ahlul Injeeli bimaaa anzalal laahu feeh; wa mal lam yahkum bimaaa anzalal laahu fa ulaaa\'ika humul faasiqoon',47,'5:47',12,46,92,2,0,116,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(717,5,'وَأَنزَلْنَآ إِلَيْكَ ٱلْكِتَـٰبَ بِٱلْحَقِّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلْكِتَـٰبِ وَمُهَيْمِنًا عَلَيْهِ ۖ فَٱحْكُم بَيْنَهُم بِمَآ أَنزَلَ ٱللَّهُ ۖ وَلَا تَتَّبِعْ أَهْوَآءَهُمْ عَمَّا جَآءَكَ مِنَ ٱلْحَقِّ ۚ لِكُلٍّ جَعَلْنَا مِنكُمْ شِرْعَةً وَمِنْهَاجًا ۚ وَلَوْ شَآءَ ٱللَّهُ لَجَعَلَكُمْ أُمَّةً وَٰحِدَةً وَلَـٰكِن لِّيَبْلُوَكُمْ فِى مَآ ءَاتَىٰكُمْ ۖ فَٱسْتَبِقُوا۟ ٱلْخَيْرَٰتِ ۚ إِلَى ٱللَّهِ مَرْجِعُكُمْ جَمِيعًا فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ','Wa anzalnaa ilaikal Kitaaba bilhaqqi musaddiqallimaa baina yadaihi minal Kitaabi wa muhaiminan \'alaihi fahkum bainahum bimaa anzalal laahu wa laa tattabi ahwaaa\'ahum \'ammaa jaaa\'aka minal haqq; likullin ja\'alnaa minkum shir\'atanw wa minhaajaa; wa law shaaa\'al laahu laja\'alakum ummatanw waahidatanw wa laakil liyabluwakum fee maa aataakum fastabiqul khairaat; ilal laahi arji\'ukum jamee\'an fayunab bi\'ukum bimaa kuntum feehi takhtalifoon',48,'5:48',12,46,92,2,0,116,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(718,5,'وَأَنِ ٱحْكُم بَيْنَهُم بِمَآ أَنزَلَ ٱللَّهُ وَلَا تَتَّبِعْ أَهْوَآءَهُمْ وَٱحْذَرْهُمْ أَن يَفْتِنُوكَ عَنۢ بَعْضِ مَآ أَنزَلَ ٱللَّهُ إِلَيْكَ ۖ فَإِن تَوَلَّوْا۟ فَٱعْلَمْ أَنَّمَا يُرِيدُ ٱللَّهُ أَن يُصِيبَهُم بِبَعْضِ ذُنُوبِهِمْ ۗ وَإِنَّ كَثِيرًا مِّنَ ٱلنَّاسِ لَفَـٰسِقُونَ','Wa anih kum bainahum bimaaa anzalal laahu wa laa tattabi\' ahwaaa\'ahum wahzarhum ai yaftinooka \'am ba\'di maaa anzalal laahu ilaika fa in tawallaw fa\'lam annamaa yureedul laahu ai yuseebahum biba\'di zunoobihim; wa inna kaseeram minan naasi lafaasiqoon',49,'5:49',12,46,92,2,0,116,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(719,5,'أَفَحُكْمَ ٱلْجَـٰهِلِيَّةِ يَبْغُونَ ۚ وَمَنْ أَحْسَنُ مِنَ ٱللَّهِ حُكْمًا لِّقَوْمٍ يُوقِنُونَ','Afahukmal jaahiliyyati yabghoon; wa man ahsanu minal laahi hukmal liqawminy yooqinoon',50,'5:50',12,46,92,2,0,116,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(720,5,'۞ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلْيَهُودَ وَٱلنَّصَـٰرَىٰٓ أَوْلِيَآءَ ۘ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ ۚ وَمَن يَتَوَلَّهُم مِّنكُمْ فَإِنَّهُۥ مِنْهُمْ ۗ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ','Yaaa aiyuhal lazeena aamanoo laa tattakhizul Yahooda wan nasaaraaa awliyaaa\'; ba\'duhum awliyaaa\'u ba\'d; wa mai yatawallahum minkum fa innahoo minhum; innal laaha laa yahdil qawmaz zaalimeen',51,'5:51',12,47,93,2,0,117,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(721,5,'فَتَرَى ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ يُسَـٰرِعُونَ فِيهِمْ يَقُولُونَ نَخْشَىٰٓ أَن تُصِيبَنَا دَآئِرَةٌ ۚ فَعَسَى ٱللَّهُ أَن يَأْتِىَ بِٱلْفَتْحِ أَوْ أَمْرٍ مِّنْ عِندِهِۦ فَيُصْبِحُوا۟ عَلَىٰ مَآ أَسَرُّوا۟ فِىٓ أَنفُسِهِمْ نَـٰدِمِينَ','Fataral lazeena fee quloobihim maraduny yusaari\'oona feehim yaqooloona nakhshaaa an tuseebanaa daaa\'irah; fa\'asallaahu ai yaatiya bilfathi aw amrim min \'indihee fa yusbihoo \'alaa maaa asarroo feee anfusihim naadimeen',52,'5:52',12,47,93,2,0,117,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(722,5,'وَيَقُولُ ٱلَّذِينَ ءَامَنُوٓا۟ أَهَـٰٓؤُلَآءِ ٱلَّذِينَ أَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَـٰنِهِمْ ۙ إِنَّهُمْ لَمَعَكُمْ ۚ حَبِطَتْ أَعْمَـٰلُهُمْ فَأَصْبَحُوا۟ خَـٰسِرِينَ','Wa yaqoolul lazeena aamanooo ahaaa\'ulaaa\'il lazeena aqsamoo billaahi jahda aimaanihim innahum lama\'akum; habitat a\'maaluhum fa asbahoo khaasireen',53,'5:53',12,47,93,2,0,117,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(723,5,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ مَن يَرْتَدَّ مِنكُمْ عَن دِينِهِۦ فَسَوْفَ يَأْتِى ٱللَّهُ بِقَوْمٍ يُحِبُّهُمْ وَيُحِبُّونَهُۥٓ أَذِلَّةٍ عَلَى ٱلْمُؤْمِنِينَ أَعِزَّةٍ عَلَى ٱلْكَـٰفِرِينَ يُجَـٰهِدُونَ فِى سَبِيلِ ٱللَّهِ وَلَا يَخَافُونَ لَوْمَةَ لَآئِمٍ ۚ ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ','Yaa aiyuhal lazeena aamanoo mai yartadda minkum \'an deenihee fasawfa yaatil laahu biqawminy yuhibbuhum wa yuhibboonahoo azillatin \'alal mu\'mineena a\'izzatin \'alal kaafireena yujaahidoona fee sabeelil laahi wa laa yakhaafoona lawmata laaa\'im; zaalika fadlul laahi yu\'teehi mai yashaaa\'; wallaahu Waasi\'un \'Aleem',54,'5:54',12,47,93,2,0,117,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(724,5,'إِنَّمَا وَلِيُّكُمُ ٱللَّهُ وَرَسُولُهُۥ وَٱلَّذِينَ ءَامَنُوا۟ ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَهُمْ رَٰكِعُونَ','Innamaa waliyyukumul laahu wa Rasooluhoo wal lazeena aamanul lazeena yuqeemoonas Salaata wa yu\'toonaz Zakaata wa hum raaki\'oon',55,'5:55',12,47,93,2,0,117,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(725,5,'وَمَن يَتَوَلَّ ٱللَّهَ وَرَسُولَهُۥ وَٱلَّذِينَ ءَامَنُوا۟ فَإِنَّ حِزْبَ ٱللَّهِ هُمُ ٱلْغَـٰلِبُونَ','Wa mai yatawallal laaha wa Rasoolahoo wallazeena aamanoo fa inna hizbal laahi humul ghaaliboon',56,'5:56',12,47,93,2,0,117,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(726,5,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَكُمْ هُزُوًا وَلَعِبًا مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ مِن قَبْلِكُمْ وَٱلْكُفَّارَ أَوْلِيَآءَ ۚ وَٱتَّقُوا۟ ٱللَّهَ إِن كُنتُم مُّؤْمِنِينَ','Yaaa aiyuhal lazeena aamanoo laa tattakhizul lazeenat takhazoo deenakum huzuwanw wa la\'ibam minal lazeena ootul Kitaaba min qablikum walkuffaara awliyaaa\'; wattaqul laaha in kuntum muu\'mineen',57,'5:57',12,47,94,2,0,117,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(727,5,'وَإِذَا نَادَيْتُمْ إِلَى ٱلصَّلَوٰةِ ٱتَّخَذُوهَا هُزُوًا وَلَعِبًا ۚ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَعْقِلُونَ','Wa izaa naadaitum ilas Salaatit takhazoohaa huzu wan\'w wa la\'ibaa; zaalika biannnahum qawmul laa ya\'qiloon',58,'5:58',12,47,94,2,0,118,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(728,5,'قُلْ يَـٰٓأَهْلَ ٱلْكِتَـٰبِ هَلْ تَنقِمُونَ مِنَّآ إِلَّآ أَنْ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْنَا وَمَآ أُنزِلَ مِن قَبْلُ وَأَنَّ أَكْثَرَكُمْ فَـٰسِقُونَ','Qul yaaa Ahlal Kitaabi hal tanqimoona minnaaa illaaa an aamannaa billaahi wa maaa unzila ilainaa wa maa unzila min qablu wa annna aksarakum faasiqoon',59,'5:59',12,47,94,2,0,118,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(729,5,'قُلْ هَلْ أُنَبِّئُكُم بِشَرٍّ مِّن ذَٰلِكَ مَثُوبَةً عِندَ ٱللَّهِ ۚ مَن لَّعَنَهُ ٱللَّهُ وَغَضِبَ عَلَيْهِ وَجَعَلَ مِنْهُمُ ٱلْقِرَدَةَ وَٱلْخَنَازِيرَ وَعَبَدَ ٱلطَّـٰغُوتَ ۚ أُو۟لَـٰٓئِكَ شَرٌّ مَّكَانًا وَأَضَلُّ عَن سَوَآءِ ٱلسَّبِيلِ','Qul hal unabbi\'ukum bisharrim min zaalika masoobatan \'indal laah; malla\'ana hul laahu wa ghadiba \'alaihi wa ja\'ala minhumul qiradata wal khanaazeera wa \'abadat Taaghoot; ulaaa\'ika sharrum makaananw wa adallu \'an Sawaaa\'is Sabeel',60,'5:60',12,47,94,2,0,118,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(730,5,'وَإِذَا جَآءُوكُمْ قَالُوٓا۟ ءَامَنَّا وَقَد دَّخَلُوا۟ بِٱلْكُفْرِ وَهُمْ قَدْ خَرَجُوا۟ بِهِۦ ۚ وَٱللَّهُ أَعْلَمُ بِمَا كَانُوا۟ يَكْتُمُونَ','Wa izaa jaaa\'ookum qaalooo aamannaa wa qad dakhaloo bilkufri wa hum qad kharajoo bih; wallaahu a\'lamu bimaa kaanoo yaktumoon',61,'5:61',12,47,94,2,0,118,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(731,5,'وَتَرَىٰ كَثِيرًا مِّنْهُمْ يُسَـٰرِعُونَ فِى ٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَأَكْلِهِمُ ٱلسُّحْتَ ۚ لَبِئْسَ مَا كَانُوا۟ يَعْمَلُونَ','Wa taraa kaseeram minhum yusaari\'oona fil ismi wal\'udwaani wa aklihimus suht; labi\'sa maa kaanoo ya\'maloon',62,'5:62',12,47,94,2,0,118,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(732,5,'لَوْلَا يَنْهَىٰهُمُ ٱلرَّبَّـٰنِيُّونَ وَٱلْأَحْبَارُ عَن قَوْلِهِمُ ٱلْإِثْمَ وَأَكْلِهِمُ ٱلسُّحْتَ ۚ لَبِئْسَ مَا كَانُوا۟ يَصْنَعُونَ','Law laa yanhaahumur rabbaaniyyoona wal ahbaaru \'an qawlihimul ismaa wa aklihimus suht; labi\'sa maa kaanoo yasna\'oon',63,'5:63',12,47,94,2,0,118,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(733,5,'وَقَالَتِ ٱلْيَهُودُ يَدُ ٱللَّهِ مَغْلُولَةٌ ۚ غُلَّتْ أَيْدِيهِمْ وَلُعِنُوا۟ بِمَا قَالُوا۟ ۘ بَلْ يَدَاهُ مَبْسُوطَتَانِ يُنفِقُ كَيْفَ يَشَآءُ ۚ وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَـٰنًا وَكُفْرًا ۚ وَأَلْقَيْنَا بَيْنَهُمُ ٱلْعَدَٰوَةَ وَٱلْبَغْضَآءَ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ ۚ كُلَّمَآ أَوْقَدُوا۟ نَارًا لِّلْحَرْبِ أَطْفَأَهَا ٱللَّهُ ۚ وَيَسْعَوْنَ فِى ٱلْأَرْضِ فَسَادًا ۚ وَٱللَّهُ لَا يُحِبُّ ٱلْمُفْسِدِينَ','Wa qaalatil Yahoodu Yadullaahi maghloolah; ghulla aideehim wa lu\'inoo bimaa qaaloo; bal yadaahu mabsoo tataani yunfiqu kaifa yashaaa\'; wa la yazeedanna kaseeramm minhum maaa unzila ilaika mir Rabbika tughyaananw wa kufraa; wa alqainaa bainahumul \'adaawata wal baghdaaa a\' ilaa Yawmil Qiyaamah; kullamaaa awqadoo naaral lilharbi at fa-ahal laah; wa yas\'awna fil ardi fasaadaa; wal laahu laa yuhibbul mufsideen',64,'5:64',12,47,94,2,0,118,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(734,5,'وَلَوْ أَنَّ أَهْلَ ٱلْكِتَـٰبِ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَكَفَّرْنَا عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَأَدْخَلْنَـٰهُمْ جَنَّـٰتِ ٱلنَّعِيمِ','Wa law anna Ahlal Kitaabi aamanoo wattaqaw lakaffarnaa \'anhum saiyiaatihim wa la adkhalnaahu Jannaatin Na\'eem',65,'5:65',12,47,94,2,0,119,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(735,5,'وَلَوْ أَنَّهُمْ أَقَامُوا۟ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ وَمَآ أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ لَأَكَلُوا۟ مِن فَوْقِهِمْ وَمِن تَحْتِ أَرْجُلِهِم ۚ مِّنْهُمْ أُمَّةٌ مُّقْتَصِدَةٌ ۖ وَكَثِيرٌ مِّنْهُمْ سَآءَ مَا يَعْمَلُونَ','Wa law annahum aqaamut Tawraata wal Injeela wa maaa unzila ilaihim mir Rabbihim la akaloo min fawqihim wa min tahti arjulihim; minhum ummatum muqta sidatunw wa kaseerum minhum saaa\'a maa ya\'maloon',66,'5:66',12,47,94,2,0,119,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(736,5,'۞ يَـٰٓأَيُّهَا ٱلرَّسُولُ بَلِّغْ مَآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ ۖ وَإِن لَّمْ تَفْعَلْ فَمَا بَلَّغْتَ رِسَالَتَهُۥ ۚ وَٱللَّهُ يَعْصِمُكَ مِنَ ٱلنَّاسِ ۗ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَـٰفِرِينَ','Yaaa aiyuhar Rasoolu balligh maaa unzila ilaika mir Rabbika wa il lam taf\'al famaaa ballaghta Risaalatah; wallaahu ya\'simuka minan naas; innal laaha laa yahdil qawmal kaafireen',67,'5:67',12,48,95,2,0,119,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(737,5,'قُلْ يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لَسْتُمْ عَلَىٰ شَىْءٍ حَتَّىٰ تُقِيمُوا۟ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ وَمَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُمْ ۗ وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَـٰنًا وَكُفْرًا ۖ فَلَا تَأْسَ عَلَى ٱلْقَوْمِ ٱلْكَـٰفِرِينَ','Qul yaaa Ahlal Kitaabi lastum \'alaa shai\'in hattaa tuqeemut Tawraata wal Injeela wa maaa unzila ilaikum mir Rabbikum; wa layazeedanna kaseeram minhum maa unzila ilaika mir Rabbika tugh yaananw wa kufran falaa taasa \'alal qawmil kaafireen',68,'5:68',12,48,95,2,0,119,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(738,5,'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَادُوا۟ وَٱلصَّـٰبِـُٔونَ وَٱلنَّصَـٰرَىٰ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَعَمِلَ صَـٰلِحًا فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ','Innal lazeena aamanoo wallazeena haadoo was saabi\'oona wan Nasaaraa man aamana billaahi wal yawmil Aakhiri wa \'amila saalihan falaa khawfun \'alaihim wa laa hum yahzanoon',69,'5:69',12,48,95,2,0,119,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(739,5,'لَقَدْ أَخَذْنَا مِيثَـٰقَ بَنِىٓ إِسْرَٰٓءِيلَ وَأَرْسَلْنَآ إِلَيْهِمْ رُسُلًا ۖ كُلَّمَا جَآءَهُمْ رَسُولٌۢ بِمَا لَا تَهْوَىٰٓ أَنفُسُهُمْ فَرِيقًا كَذَّبُوا۟ وَفَرِيقًا يَقْتُلُونَ','Laqad akhaznaa meesaaqa Banee Israaa\'eela wa arsalnaaa ilaihim Rusulan kullamaa jaaa\'ahum Rasoolum bimaa laa tahwaaa anfusuhum fareeqan kazzaboo wa fareeqany yaqtuloon',70,'5:70',12,48,95,2,0,119,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(740,5,'وَحَسِبُوٓا۟ أَلَّا تَكُونَ فِتْنَةٌ فَعَمُوا۟ وَصَمُّوا۟ ثُمَّ تَابَ ٱللَّهُ عَلَيْهِمْ ثُمَّ عَمُوا۟ وَصَمُّوا۟ كَثِيرٌ مِّنْهُمْ ۚ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ','Wa hasibooo allaa takoona fitnaun fa\'amoo wa sammoo summa taabal laahu \'alaihim summa \'amoo wa sammoo kaseerum minhum; wallaahu baseerum bimaa ya\'maloon',71,'5:71',12,48,95,2,0,120,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(741,5,'لَقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ هُوَ ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ ۖ وَقَالَ ٱلْمَسِيحُ يَـٰبَنِىٓ إِسْرَٰٓءِيلَ ٱعْبُدُوا۟ ٱللَّهَ رَبِّى وَرَبَّكُمْ ۖ إِنَّهُۥ مَن يُشْرِكْ بِٱللَّهِ فَقَدْ حَرَّمَ ٱللَّهُ عَلَيْهِ ٱلْجَنَّةَ وَمَأْوَىٰهُ ٱلنَّارُ ۖ وَمَا لِلظَّـٰلِمِينَ مِنْ أَنصَارٍ','Laqad kafaral lazeena qaalooo innal laaha Huwal maseehub nu Maryama wa qaalal Maseehu yaa Baneee Israaa\'eela budul laaha Rabbee wa Rabbakum innnahoo many-yushrik ballaahi faqad harramal laahu \'alaihil jannata wa maa waahun Naaru wa maa lizzaalimeena min ansaar',72,'5:72',12,48,95,2,0,120,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(742,5,'لَّقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ ثَالِثُ ثَلَـٰثَةٍ ۘ وَمَا مِنْ إِلَـٰهٍ إِلَّآ إِلَـٰهٌ وَٰحِدٌ ۚ وَإِن لَّمْ يَنتَهُوا۟ عَمَّا يَقُولُونَ لَيَمَسَّنَّ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ عَذَابٌ أَلِيمٌ','laqad kafaral lazeena qaalooo innal laaha saalisu salaasah; wa maa min ilaahin illaaa Ilaahunw Waahid; wa illam yantahoo \'ammaa yaqooloona layamas sannal lazeena kafaroo minhum \'azaabun aleem',73,'5:73',12,48,95,2,0,120,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(743,5,'أَفَلَا يَتُوبُونَ إِلَى ٱللَّهِ وَيَسْتَغْفِرُونَهُۥ ۚ وَٱللَّهُ غَفُورٌ رَّحِيمٌ','Afalaa yatooboona ilal laahi wa yastaghfiroonah; wallaahu Ghafoorur Raheem',74,'5:74',12,48,95,2,0,120,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(744,5,'مَّا ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ ٱلرُّسُلُ وَأُمُّهُۥ صِدِّيقَةٌ ۖ كَانَا يَأْكُلَانِ ٱلطَّعَامَ ۗ ٱنظُرْ كَيْفَ نُبَيِّنُ لَهُمُ ٱلْـَٔايَـٰتِ ثُمَّ ٱنظُرْ أَنَّىٰ يُؤْفَكُونَ','Mal Maseehub nu Maryama illaa Rasoolun qad khalat min qablihir Rusulu wa ummuhoo siddeeqatun kaanaa yaa kulaanit ta\'aam; unzur kaifa nubaiyinu lahumul Aayaati suman zur annaa yu\'fakoon',75,'5:75',12,48,95,2,0,120,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(745,5,'قُلْ أَتَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمْلِكُ لَكُمْ ضَرًّا وَلَا نَفْعًا ۚ وَٱللَّهُ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ','Qul ata\'budoona min doonil laahi maa laa yamliku lakum darranw wa laa naf\'aa; wallaahu Huwas Samee\'ul \'Aleem',76,'5:76',12,48,95,2,0,120,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(746,5,'قُلْ يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لَا تَغْلُوا۟ فِى دِينِكُمْ غَيْرَ ٱلْحَقِّ وَلَا تَتَّبِعُوٓا۟ أَهْوَآءَ قَوْمٍ قَدْ ضَلُّوا۟ مِن قَبْلُ وَأَضَلُّوا۟ كَثِيرًا وَضَلُّوا۟ عَن سَوَآءِ ٱلسَّبِيلِ','Qul yaaa Ahlal Kitaabi laa taghloo fee deenikum ghairal haqqi wa laa tattabi\'ooo ahwaaa\'a qawmin qad dalloo min qablu wa adalloo kaseeranw wa dalloo \'an Sawaaa\'is Sabeel',77,'5:77',12,48,95,2,0,121,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(747,5,'لُعِنَ ٱلَّذِينَ كَفَرُوا۟ مِنۢ بَنِىٓ إِسْرَٰٓءِيلَ عَلَىٰ لِسَانِ دَاوُۥدَ وَعِيسَى ٱبْنِ مَرْيَمَ ۚ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ','Lu\'inal lazeena kafaroo mim Baneee israaa\'eela \'alaa lisaani Daawooda wa \'Eesab ni Maryam; zaalika bimaa \'asaw wa kaanoo ya tadoon',78,'5:78',12,48,96,2,0,121,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(748,5,'كَانُوا۟ لَا يَتَنَاهَوْنَ عَن مُّنكَرٍ فَعَلُوهُ ۚ لَبِئْسَ مَا كَانُوا۟ يَفْعَلُونَ','Kaanoo laa yatanaahawna \'am munkarin fa\'aluhoo; labi\'sa maa kaanoo yafa\'loon',79,'5:79',12,48,96,2,0,121,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(749,5,'تَرَىٰ كَثِيرًا مِّنْهُمْ يَتَوَلَّوْنَ ٱلَّذِينَ كَفَرُوا۟ ۚ لَبِئْسَ مَا قَدَّمَتْ لَهُمْ أَنفُسُهُمْ أَن سَخِطَ ٱللَّهُ عَلَيْهِمْ وَفِى ٱلْعَذَابِ هُمْ خَـٰلِدُونَ','Taraa kaseeram minhum yatawallawnal lazeena kafaroo; labi\'sa maa qaddamat lahum anfusuhum an sakhital laahu \'alaihim wa fil \'azaabi hum khaalidoon',80,'5:80',12,48,96,2,0,121,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(750,5,'وَلَوْ كَانُوا۟ يُؤْمِنُونَ بِٱللَّهِ وَٱلنَّبِىِّ وَمَآ أُنزِلَ إِلَيْهِ مَا ٱتَّخَذُوهُمْ أَوْلِيَآءَ وَلَـٰكِنَّ كَثِيرًا مِّنْهُمْ فَـٰسِقُونَ','Wa law kaanoo yu\'minoona billaahi wan nabiyyi wa maaa unzila ilaihi attakhazoohum awliyaaa\'a wa laakinna kaseeram minhum faasiqoon',81,'5:81',12,48,96,2,0,121,6,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(751,5,'۞ لَتَجِدَنَّ أَشَدَّ ٱلنَّاسِ عَدَٰوَةً لِّلَّذِينَ ءَامَنُوا۟ ٱلْيَهُودَ وَٱلَّذِينَ أَشْرَكُوا۟ ۖ وَلَتَجِدَنَّ أَقْرَبَهُم مَّوَدَّةً لِّلَّذِينَ ءَامَنُوا۟ ٱلَّذِينَ قَالُوٓا۟ إِنَّا نَصَـٰرَىٰ ۚ ذَٰلِكَ بِأَنَّ مِنْهُمْ قِسِّيسِينَ وَرُهْبَانًا وَأَنَّهُمْ لَا يَسْتَكْبِرُونَ','Latajidanna ashad dan naasi \'adaawatal lillazeena aamanul Yahooda wallazeena ashrakoo wa latajidanna aqrabahum mawaddatal lil lazeena aamanul lazeena qaalooo innaa Nasaaraa; zaalika bi anna mminhum qiseeseena wa ruhbaananw wa annahum laa yastakbiroon',82,'5:82',13,49,96,2,0,121,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(752,5,'وَإِذَا سَمِعُوا۟ مَآ أُنزِلَ إِلَى ٱلرَّسُولِ تَرَىٰٓ أَعْيُنَهُمْ تَفِيضُ مِنَ ٱلدَّمْعِ مِمَّا عَرَفُوا۟ مِنَ ٱلْحَقِّ ۖ يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱكْتُبْنَا مَعَ ٱلشَّـٰهِدِينَ','Wa izaa sami\'oo maaa unzila ilar Rasooli taraaa a\'yunahum tafeedu minad dam\'i mimmmaa \'arafoo minalhaqq; yaqooloona Rabbanaaa aamannaa faktubnaa ma\'ash shaahideen',83,'5:83',13,49,96,2,0,122,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(753,5,'وَمَا لَنَا لَا نُؤْمِنُ بِٱللَّهِ وَمَا جَآءَنَا مِنَ ٱلْحَقِّ وَنَطْمَعُ أَن يُدْخِلَنَا رَبُّنَا مَعَ ٱلْقَوْمِ ٱلصَّـٰلِحِينَ','Wa maa lanaa laa nu\'minu billaahi wa maa jaaa\'anaa minal haqqi wa natma\'u ai yudkhilanaa Rabbunaa ma\'al qawmis saaliheen',84,'5:84',13,49,96,2,0,122,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(754,5,'فَأَثَـٰبَهُمُ ٱللَّهُ بِمَا قَالُوا۟ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا ۚ وَذَٰلِكَ جَزَآءُ ٱلْمُحْسِنِينَ','Fa asaabahumul laahu bimaa qaaloo Jannnaatin tajree min tahtihal anhaaru khaalideena feehaa; wa zaalika jazaaa\'ul muhsineen',85,'5:85',13,49,96,2,0,122,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(755,5,'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَـٰتِنَآ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْجَحِيمِ','Wallazeena kafaroo wa kazzaboo bi Aayaatinaaa ulaaa\'ika Ashaabul Jaheem',86,'5:86',13,49,96,2,0,122,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(756,5,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُحَرِّمُوا۟ طَيِّبَـٰتِ مَآ أَحَلَّ ٱللَّهُ لَكُمْ وَلَا تَعْتَدُوٓا۟ ۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُعْتَدِينَ','Yaaa aiyuhal lazeena aamanoo laa tuharrimoo taiyibaati maaa ahallal laahu lakum wa laa ta\'tadooo; innal laaha laa yuhibbul mu\'tadeen',87,'5:87',13,49,97,2,0,122,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(757,5,'وَكُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَـٰلًا طَيِّبًا ۚ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ أَنتُم بِهِۦ مُؤْمِنُونَ','Wa kuloo mimmaa razaqakumul laahu halaalan taiyibaa; wattaqul laahallazeee antum bihee mu\'minon',88,'5:88',13,49,97,2,0,122,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(758,5,'لَا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغْوِ فِىٓ أَيْمَـٰنِكُمْ وَلَـٰكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ ٱلْأَيْمَـٰنَ ۖ فَكَفَّـٰرَتُهُۥٓ إِطْعَامُ عَشَرَةِ مَسَـٰكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ ۖ فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَـٰثَةِ أَيَّامٍ ۚ ذَٰلِكَ كَفَّـٰرَةُ أَيْمَـٰنِكُمْ إِذَا حَلَفْتُمْ ۚ وَٱحْفَظُوٓا۟ أَيْمَـٰنَكُمْ ۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَـٰتِهِۦ لَعَلَّكُمْ تَشْكُرُونَ','Laa yu\'aakhizukumul laahu billaghwi feee aimaanikum wa laakiny ya\'aakhizukum bimaa \'aqqattumul aimaana fakaf faaratuhooo it\'aamu \'asharati masaakeena min awsati maa tut\'imoona ahleekum aw kiswatuhum aw tahreeru raqabatin famallam yajid fa Siyaamu salaasati aiyaam; zaalika kaffaaratu aimaanikum izaa halaftum; wahfazooo aimaanakum; kazaalika yubaiyinul laahu lakum Aayaatihee la\'allakum tashkuroon',89,'5:89',13,49,97,2,0,122,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(759,5,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّمَا ٱلْخَمْرُ وَٱلْمَيْسِرُ وَٱلْأَنصَابُ وَٱلْأَزْلَـٰمُ رِجْسٌ مِّنْ عَمَلِ ٱلشَّيْطَـٰنِ فَٱجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ','yaaa aiyuhal lazeena aamanooo innamal khamru walmaisiru wal ansaabu wal azlaamu rijsum min \'amalish shaitaani fajtaniboohu la\'al lakum tuflihoon',90,'5:90',13,49,97,2,0,123,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(760,5,'إِنَّمَا يُرِيدُ ٱلشَّيْطَـٰنُ أَن يُوقِعَ بَيْنَكُمُ ٱلْعَدَٰوَةَ وَٱلْبَغْضَآءَ فِى ٱلْخَمْرِ وَٱلْمَيْسِرِ وَيَصُدَّكُمْ عَن ذِكْرِ ٱللَّهِ وَعَنِ ٱلصَّلَوٰةِ ۖ فَهَلْ أَنتُم مُّنتَهُونَ','Innamaa yureedush Shaitaanu ai yooqi\'a bainakumul \'adaawata wal baghdaaa\'a fil khamri wal maisiri wa yasuddakum \'an zikril laahi wa \'anis Salaati fahal antum muntahoon',91,'5:91',13,49,97,2,0,123,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(761,5,'وَأَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَٱحْذَرُوا۟ ۚ فَإِن تَوَلَّيْتُمْ فَٱعْلَمُوٓا۟ أَنَّمَا عَلَىٰ رَسُولِنَا ٱلْبَلَـٰغُ ٱلْمُبِينُ','Wa atee\'ul laaha wa atee\'ur Rasoola wahzaroo; fa in tawal laitum fa\'lamooo annamaa \'alaa Rasoolinal balaaghul mubeen',92,'5:92',13,49,97,2,0,123,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(762,5,'لَيْسَ عَلَى ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ جُنَاحٌ فِيمَا طَعِمُوٓا۟ إِذَا مَا ٱتَّقَوا۟ وَّءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ ثُمَّ ٱتَّقَوا۟ وَّءَامَنُوا۟ ثُمَّ ٱتَّقَوا۟ وَّأَحْسَنُوا۟ ۗ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ','Laisa \'alal lazeena aamanoo wa \'amilus saalihaati junaahun feemaa ta\'imooo izaa mat taqaw wa aamanoo wa \'amilus saalihaati summat taqaw wa aamanoo summat taqaw wa ahsanoo; wallaahu yuhibbul muhsineen',93,'5:93',13,49,97,2,0,123,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(763,5,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَيَبْلُوَنَّكُمُ ٱللَّهُ بِشَىْءٍ مِّنَ ٱلصَّيْدِ تَنَالُهُۥٓ أَيْدِيكُمْ وَرِمَاحُكُمْ لِيَعْلَمَ ٱللَّهُ مَن يَخَافُهُۥ بِٱلْغَيْبِ ۚ فَمَنِ ٱعْتَدَىٰ بَعْدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٌ','Yaaa aiyuhal lazeena aamanoo la yabluwannnakumul laahu bishai\'im minas saidi tanaaluhooo aideekum wa rimaahukum liya\'lamal laahu mai yakhaafuhoo bilghaib; famani\' tadaa ba\'da zaalika falahoo \'azaabun aleem',94,'5:94',13,49,98,2,0,123,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(764,5,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقْتُلُوا۟ ٱلصَّيْدَ وَأَنتُمْ حُرُمٌ ۚ وَمَن قَتَلَهُۥ مِنكُم مُّتَعَمِّدًا فَجَزَآءٌ مِّثْلُ مَا قَتَلَ مِنَ ٱلنَّعَمِ يَحْكُمُ بِهِۦ ذَوَا عَدْلٍ مِّنكُمْ هَدْيًۢا بَـٰلِغَ ٱلْكَعْبَةِ أَوْ كَفَّـٰرَةٌ طَعَامُ مَسَـٰكِينَ أَوْ عَدْلُ ذَٰلِكَ صِيَامًا لِّيَذُوقَ وَبَالَ أَمْرِهِۦ ۗ عَفَا ٱللَّهُ عَمَّا سَلَفَ ۚ وَمَنْ عَادَ فَيَنتَقِمُ ٱللَّهُ مِنْهُ ۗ وَٱللَّهُ عَزِيزٌ ذُو ٱنتِقَامٍ','Yaaa aiyuhal lazeena aamanoo laa taqtuslus saida wa antum hurum; wa man qatalahoo minkum mut\'am midan fajazaaa\'um mislu maa qatala minanna\'ami yahkumu bihee zawaa \'adlim minkum hadyam baalighal Ka\'bati aw kaffaaratun ta\'aamu masaakeena aw \'adlu zaalika Siyaamal liyazooqa wabaala amrih; \'afal laahu \'ammaa salaf; wa man \'aada fayanta qimul laahu minh; wallaahu \'azeezun zuntiqaam',95,'5:95',13,49,98,2,0,123,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(765,5,'أُحِلَّ لَكُمْ صَيْدُ ٱلْبَحْرِ وَطَعَامُهُۥ مَتَـٰعًا لَّكُمْ وَلِلسَّيَّارَةِ ۖ وَحُرِّمَ عَلَيْكُمْ صَيْدُ ٱلْبَرِّ مَا دُمْتُمْ حُرُمًا ۗ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ','Uhilla lakum saidul bahri wa ta\'aamuhoo mataa\'al lakum wa lissaiyaarati wa hurrima \'alaikum saidul barri maa dumtum hurumaa; wattaqul laahal lazeee ilaihi tuhsharoon',96,'5:96',13,49,98,2,0,124,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(766,5,'۞ جَعَلَ ٱللَّهُ ٱلْكَعْبَةَ ٱلْبَيْتَ ٱلْحَرَامَ قِيَـٰمًا لِّلنَّاسِ وَٱلشَّهْرَ ٱلْحَرَامَ وَٱلْهَدْىَ وَٱلْقَلَـٰٓئِدَ ۚ ذَٰلِكَ لِتَعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَأَنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ','Ja\'alal laahul Ka\'batal Baital Haraama qiyaamal linnaasi wash Shahral Haraama walhadya walqalaaa\'id; zaalika lita\'lamooo annal laaha ya\'lamu maa fis samaawaati wa maa fil ardi wa annal laaha bikulli shai\'in \'Aleem',97,'5:97',13,50,98,2,0,124,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(767,5,'ٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ وَأَنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ','I\'lamooo annal laaha shadeedul \'iqaabi wa annal laaha Ghafoorur Raheem',98,'5:98',13,50,98,2,0,124,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(768,5,'مَّا عَلَى ٱلرَّسُولِ إِلَّا ٱلْبَلَـٰغُ ۗ وَٱللَّهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ','Maa \'alar Rasooli illal balaagh; wallaahu ya\'lamu maa tubdoona wa maa taktumoon',99,'5:99',13,50,98,2,0,124,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(769,5,'قُل لَّا يَسْتَوِى ٱلْخَبِيثُ وَٱلطَّيِّبُ وَلَوْ أَعْجَبَكَ كَثْرَةُ ٱلْخَبِيثِ ۚ فَٱتَّقُوا۟ ٱللَّهَ يَـٰٓأُو۟لِى ٱلْأَلْبَـٰبِ لَعَلَّكُمْ تُفْلِحُونَ','Qul laa yastawil khabeesu wattaiyibu wa law a\'jabaka kasratul khabees; fattaqul laaha yaaa ulil albaabi la\'allakum tuflihoon',100,'5:100',13,50,98,2,0,124,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(770,5,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَسْـَٔلُوا۟ عَنْ أَشْيَآءَ إِن تُبْدَ لَكُمْ تَسُؤْكُمْ وَإِن تَسْـَٔلُوا۟ عَنْهَا حِينَ يُنَزَّلُ ٱلْقُرْءَانُ تُبْدَ لَكُمْ عَفَا ٱللَّهُ عَنْهَا ۗ وَٱللَّهُ غَفُورٌ حَلِيمٌ','yaaa aiyuhal lazeena aamanoo laa tas\'aloo \'an ashyaaa\'a in tubda lakum tasu\'kum wa in tas\'aloo \'anhaa heena yunazzalul Qur\'aanu tubda lakum; \'afallaahu \'anhaa; wallaahu Ghafoorun Haleem',101,'5:101',13,50,99,2,0,124,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(771,5,'قَدْ سَأَلَهَا قَوْمٌ مِّن قَبْلِكُمْ ثُمَّ أَصْبَحُوا۟ بِهَا كَـٰفِرِينَ','Qad sa alahaa qawmum min qablikum summa asbahoo bihaa kaafireen',102,'5:102',13,50,99,2,0,124,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(772,5,'مَا جَعَلَ ٱللَّهُ مِنۢ بَحِيرَةٍ وَلَا سَآئِبَةٍ وَلَا وَصِيلَةٍ وَلَا حَامٍ ۙ وَلَـٰكِنَّ ٱلَّذِينَ كَفَرُوا۟ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ ۖ وَأَكْثَرُهُمْ لَا يَعْقِلُونَ','Maa ja\'alal laahu mim baheeratinw wa laa saaa\'ibatinw wa laa waseelatinw wa laa haaminw wa laakinnal lazeena kafaroo yaftaroona \'alallaahil kazib; wa aksaruhum laa ya\'qiloon',103,'5:103',13,50,99,2,0,124,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(773,5,'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ قَالُوا۟ حَسْبُنَا مَا وَجَدْنَا عَلَيْهِ ءَابَآءَنَآ ۚ أَوَلَوْ كَانَ ءَابَآؤُهُمْ لَا يَعْلَمُونَ شَيْـًٔا وَلَا يَهْتَدُونَ','Wa izaa qeela lahum ta\'aalaw ilaa maaa anzalallaahu wa ilar Rasooli qaaloo hasbunaa maa wajadnaa \'alaihi aabaaa\'anaa; awa law kaana aabaaa\'uhum laa ya\'lamoona shai\'anw wa laa yahtadoon',104,'5:104',13,50,99,2,0,125,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(774,5,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ عَلَيْكُمْ أَنفُسَكُمْ ۖ لَا يَضُرُّكُم مَّن ضَلَّ إِذَا ٱهْتَدَيْتُمْ ۚ إِلَى ٱللَّهِ مَرْجِعُكُمْ جَمِيعًا فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ','Yaaa aiyuhal lazeena aamanoo \'alaikum anfusakum laa yadurrukum man dalla izah tadaitum; ilal laahi marji\'ukum jamee\'an fayunabbi\'ukum bimaa kuntum ta\'maloon',105,'5:105',13,50,99,2,0,125,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(775,5,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ شَهَـٰدَةُ بَيْنِكُمْ إِذَا حَضَرَ أَحَدَكُمُ ٱلْمَوْتُ حِينَ ٱلْوَصِيَّةِ ٱثْنَانِ ذَوَا عَدْلٍ مِّنكُمْ أَوْ ءَاخَرَانِ مِنْ غَيْرِكُمْ إِنْ أَنتُمْ ضَرَبْتُمْ فِى ٱلْأَرْضِ فَأَصَـٰبَتْكُم مُّصِيبَةُ ٱلْمَوْتِ ۚ تَحْبِسُونَهُمَا مِنۢ بَعْدِ ٱلصَّلَوٰةِ فَيُقْسِمَانِ بِٱللَّهِ إِنِ ٱرْتَبْتُمْ لَا نَشْتَرِى بِهِۦ ثَمَنًا وَلَوْ كَانَ ذَا قُرْبَىٰ ۙ وَلَا نَكْتُمُ شَهَـٰدَةَ ٱللَّهِ إِنَّآ إِذًا لَّمِنَ ٱلْـَٔاثِمِينَ','Yaaa aiyuhal lazeena aamanoo shahaadatu bainikum izaa hadara ahadakumul mawtu heenal wasiyyatis naani zawaa \'adlim minkum aw aakharaani min ghairikum in antum darabtum fil ardi fa asaabatkum museebatul mawt; tahbi soonahumaa mim ba\'dis Salaati fa yuqsimaani billaahi inirtabtum laa nashtaree bihee samananw wa law kaana zaa qurbaa wa laa naktumu shahaadatal laahi innaaa izal laminal aasimeen',106,'5:106',13,50,99,2,0,125,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(776,5,'فَإِنْ عُثِرَ عَلَىٰٓ أَنَّهُمَا ٱسْتَحَقَّآ إِثْمًا فَـَٔاخَرَانِ يَقُومَانِ مَقَامَهُمَا مِنَ ٱلَّذِينَ ٱسْتَحَقَّ عَلَيْهِمُ ٱلْأَوْلَيَـٰنِ فَيُقْسِمَانِ بِٱللَّهِ لَشَهَـٰدَتُنَآ أَحَقُّ مِن شَهَـٰدَتِهِمَا وَمَا ٱعْتَدَيْنَآ إِنَّآ إِذًا لَّمِنَ ٱلظَّـٰلِمِينَ','Fa in \'usira \'alaaa annahumas tahaqqaaa isman fa aakharaani yaqoomaani maqaamahumaa minal lazeenas tahaqqa \'alaihimul awlayaani fa yuqsimaani billaahi lashahaadatunaaa ahaqqu min shahaadatihimaaa wa ma\'tadainaaa innaaa izal laminaz zaalimeen',107,'5:107',13,50,99,2,0,125,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(777,5,'ذَٰلِكَ أَدْنَىٰٓ أَن يَأْتُوا۟ بِٱلشَّهَـٰدَةِ عَلَىٰ وَجْهِهَآ أَوْ يَخَافُوٓا۟ أَن تُرَدَّ أَيْمَـٰنٌۢ بَعْدَ أَيْمَـٰنِهِمْ ۗ وَٱتَّقُوا۟ ٱللَّهَ وَٱسْمَعُوا۟ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَـٰسِقِينَ','Zaalika adnaaa ai yaatoo bishshahaadati \'alaa wajhihaaa aw yakhaafooo an turadda aimaanum ba\'da aimaanihim; wattaqul laaha wasma\'oo; wallaahu laa yahdil qawmal faasiqeen',108,'5:108',13,50,99,2,0,125,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(778,5,'۞ يَوْمَ يَجْمَعُ ٱللَّهُ ٱلرُّسُلَ فَيَقُولُ مَاذَآ أُجِبْتُمْ ۖ قَالُوا۟ لَا عِلْمَ لَنَآ ۖ إِنَّكَ أَنتَ عَلَّـٰمُ ٱلْغُيُوبِ','yawma yajma\'ul laahur Rusula fa yaqoolu maazaaa ujibtum qaaloo laa \'ilma lanaa innaka Anta \'Allaamul Ghuyoob',109,'5:109',13,51,100,2,0,126,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(779,5,'إِذْ قَالَ ٱللَّهُ يَـٰعِيسَى ٱبْنَ مَرْيَمَ ٱذْكُرْ نِعْمَتِى عَلَيْكَ وَعَلَىٰ وَٰلِدَتِكَ إِذْ أَيَّدتُّكَ بِرُوحِ ٱلْقُدُسِ تُكَلِّمُ ٱلنَّاسَ فِى ٱلْمَهْدِ وَكَهْلًا ۖ وَإِذْ عَلَّمْتُكَ ٱلْكِتَـٰبَ وَٱلْحِكْمَةَ وَٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ ۖ وَإِذْ تَخْلُقُ مِنَ ٱلطِّينِ كَهَيْـَٔةِ ٱلطَّيْرِ بِإِذْنِى فَتَنفُخُ فِيهَا فَتَكُونُ طَيْرًۢا بِإِذْنِى ۖ وَتُبْرِئُ ٱلْأَكْمَهَ وَٱلْأَبْرَصَ بِإِذْنِى ۖ وَإِذْ تُخْرِجُ ٱلْمَوْتَىٰ بِإِذْنِى ۖ وَإِذْ كَفَفْتُ بَنِىٓ إِسْرَٰٓءِيلَ عَنكَ إِذْ جِئْتَهُم بِٱلْبَيِّنَـٰتِ فَقَالَ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ إِنْ هَـٰذَآ إِلَّا سِحْرٌ مُّبِينٌ','Iz qaalal laahu yaa \'Eesab-na-Maryamaz kur ni\'matee \'alaika wa \'alaa waalidatik; iz aiyattuka bi Roohil Qudusi tukallimun naasa fil mahdi wa kahlanw wa iz \'allamtukal kitaaba wal Hikmata wa Tawraata wal Injeela wa iz Takhluqu minat teeni kahai \'atit tairi bi iznee fatanfukhu feeha fatakoonu tairam bi iznee wa tubri\'ul akmaha wal abrasa bi iznee wa iz tukhrijul mawtaa bi iznee wa iz kafaftu Baneee Israaa\'eela \'anka iz ji\'tahum bil baiyinaati fa qaalal lazeena kafaroo minhum in haazaaa illaa sihrum mubeen',110,'5:110',13,51,100,2,0,126,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(780,5,'وَإِذْ أَوْحَيْتُ إِلَى ٱلْحَوَارِيِّـۧنَ أَنْ ءَامِنُوا۟ بِى وَبِرَسُولِى قَالُوٓا۟ ءَامَنَّا وَٱشْهَدْ بِأَنَّنَا مُسْلِمُونَ','Wa iz awhaitu ilal hawaariyyeena an aaminoo bee wa bi Rasoolee qaalooo aamannaa washhad bi annanaa muslimoon',111,'5:111',13,51,100,2,0,126,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(781,5,'إِذْ قَالَ ٱلْحَوَارِيُّونَ يَـٰعِيسَى ٱبْنَ مَرْيَمَ هَلْ يَسْتَطِيعُ رَبُّكَ أَن يُنَزِّلَ عَلَيْنَا مَآئِدَةً مِّنَ ٱلسَّمَآءِ ۖ قَالَ ٱتَّقُوا۟ ٱللَّهَ إِن كُنتُم مُّؤْمِنِينَ','Iz qaalal hawaariyyoona yaa \'Eesab na Maryama hal yastatee\'u Rabbuka ai yunaz zila \'alinaa maaa\'idatam minas samaaa\'i qaalat taqul laaha in kuntum mu\'mineen',112,'5:112',13,51,100,2,0,126,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(782,5,'قَالُوا۟ نُرِيدُ أَن نَّأْكُلَ مِنْهَا وَتَطْمَئِنَّ قُلُوبُنَا وَنَعْلَمَ أَن قَدْ صَدَقْتَنَا وَنَكُونَ عَلَيْهَا مِنَ ٱلشَّـٰهِدِينَ','Qaaloo nureedu an naakula minhaa wa tatam\'inna quloo bunaa wa na\'lama an qad sadaqtana wa nakoona \'alaihaa minash shaahideen',113,'5:113',13,51,100,2,0,126,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(783,5,'قَالَ عِيسَى ٱبْنُ مَرْيَمَ ٱللَّهُمَّ رَبَّنَآ أَنزِلْ عَلَيْنَا مَآئِدَةً مِّنَ ٱلسَّمَآءِ تَكُونُ لَنَا عِيدًا لِّأَوَّلِنَا وَءَاخِرِنَا وَءَايَةً مِّنكَ ۖ وَٱرْزُقْنَا وَأَنتَ خَيْرُ ٱلرَّٰزِقِينَ','Qaala \'Eesab nu Maryamal laahumma Rabbanaaa anzil \'alainaa maaa\'idatam minas samaaa\'i takoonu lanaa \'eedal li awwalinaa wa aakirinaa wa Aayatam minka warzuqnaa wa Anta khairur raaziqeen',114,'5:114',13,51,100,2,0,127,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(784,5,'قَالَ ٱللَّهُ إِنِّى مُنَزِّلُهَا عَلَيْكُمْ ۖ فَمَن يَكْفُرْ بَعْدُ مِنكُمْ فَإِنِّىٓ أُعَذِّبُهُۥ عَذَابًا لَّآ أُعَذِّبُهُۥٓ أَحَدًا مِّنَ ٱلْعَـٰلَمِينَ','Waalal laahu innee munaz ziluhaa \'alaikum faman yakfur ba\'du minkum fa inneee u\'azzibuhoo \'azaabal laaa u\'azzibuhooo ahadam minal \'aalameen',115,'5:115',13,51,100,2,0,127,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(785,5,'وَإِذْ قَالَ ٱللَّهُ يَـٰعِيسَى ٱبْنَ مَرْيَمَ ءَأَنتَ قُلْتَ لِلنَّاسِ ٱتَّخِذُونِى وَأُمِّىَ إِلَـٰهَيْنِ مِن دُونِ ٱللَّهِ ۖ قَالَ سُبْحَـٰنَكَ مَا يَكُونُ لِىٓ أَنْ أَقُولَ مَا لَيْسَ لِى بِحَقٍّ ۚ إِن كُنتُ قُلْتُهُۥ فَقَدْ عَلِمْتَهُۥ ۚ تَعْلَمُ مَا فِى نَفْسِى وَلَآ أَعْلَمُ مَا فِى نَفْسِكَ ۚ إِنَّكَ أَنتَ عَلَّـٰمُ ٱلْغُيُوبِ','Wa iz qaalal laahu yaa \'Eesab na Maryama \'a-anta qulta linnaasit takhizoonee wa ummiya ilaahaini min doonil laahi qaala Subhaanaka maa yakoonu leee anaqoola maa yakkoonu leee an aqoola maa laisa lee bihaqq; in kuntu qultuhoo faqad \'alimtah; ta\'lamu maa fee nafsee wa laaa a\'almu maa fee nafsik; innaka Anta \'Allaamul Ghuyoob',116,'5:116',13,51,101,2,0,127,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(786,5,'مَا قُلْتُ لَهُمْ إِلَّا مَآ أَمَرْتَنِى بِهِۦٓ أَنِ ٱعْبُدُوا۟ ٱللَّهَ رَبِّى وَرَبَّكُمْ ۚ وَكُنتُ عَلَيْهِمْ شَهِيدًا مَّا دُمْتُ فِيهِمْ ۖ فَلَمَّا تَوَفَّيْتَنِى كُنتَ أَنتَ ٱلرَّقِيبَ عَلَيْهِمْ ۚ وَأَنتَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ','Maa qultu lahum illaa maaa amartanee bihee ani\'budul laaha Rabbeee wa Rabbakum; wa kuntu \'alaihim shaheedam maa dumtu feehim falammaa tawaffaitanee kunta Antar Raqeeba \'alaihim; wa Anta \'alaa kulli shai\'in Shaheed',117,'5:117',13,51,101,2,0,127,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(787,5,'إِن تُعَذِّبْهُمْ فَإِنَّهُمْ عِبَادُكَ ۖ وَإِن تَغْفِرْ لَهُمْ فَإِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ','In tu\'azzibhum fa innahum ibaaduka wa in taghfir lahum fa innaka Antal \'Azzezul Hakeem',118,'5:118',13,51,101,2,0,127,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(788,5,'قَالَ ٱللَّهُ هَـٰذَا يَوْمُ يَنفَعُ ٱلصَّـٰدِقِينَ صِدْقُهُمْ ۚ لَهُمْ جَنَّـٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَآ أَبَدًا ۚ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ','Qaalal laahu haaza yawmu yanfa\'us saadiqeena sidquhum; lahum janaatunn tajree min tahtihal anhaaru khaalideena feehaaa abadaa; radiyal laahu \'anhum wa radoo \'anh; zaalikal fawzul \'azeem',119,'5:119',13,51,101,2,0,127,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(789,5,'لِلَّهِ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا فِيهِنَّ ۚ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌۢ','Lillaahi mulkus samaawaati wal ardi wa maa feehinn; wa Huwa \'alaa kulli shain\'in Qadeer',120,'5:120',13,51,101,2,0,127,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(790,6,'ٱلْحَمْدُ لِلَّهِ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ وَجَعَلَ ٱلظُّلُمَـٰتِ وَٱلنُّورَ ۖ ثُمَّ ٱلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ يَعْدِلُونَ','Alhamdu lillaahil lazee khalaqas samaawaati wal arda wa ja\'alaz zulumaati wannoor; summal lazeena kafaroo bi Rabbihim ya\'diloon',1,'6:1',13,51,102,2,0,128,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(791,6,'هُوَ ٱلَّذِى خَلَقَكُم مِّن طِينٍ ثُمَّ قَضَىٰٓ أَجَلًا ۖ وَأَجَلٌ مُّسَمًّى عِندَهُۥ ۖ ثُمَّ أَنتُمْ تَمْتَرُونَ','Huwal lazee khalaqakum min teenin summa qadaaa ajalanw wa ajalum musamman \'indahoo summa antum tamtaroon',2,'6:2',13,51,102,2,0,128,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(792,6,'وَهُوَ ٱللَّهُ فِى ٱلسَّمَـٰوَٰتِ وَفِى ٱلْأَرْضِ ۖ يَعْلَمُ سِرَّكُمْ وَجَهْرَكُمْ وَيَعْلَمُ مَا تَكْسِبُونَ','Wa Huwal laahu fissamaawaati wa fil ardi ya\'lamu sirrakum wa jahrakum wa ya\'lamu maa taksiboon',3,'6:3',13,51,102,2,0,128,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(793,6,'وَمَا تَأْتِيهِم مِّنْ ءَايَةٍ مِّنْ ءَايَـٰتِ رَبِّهِمْ إِلَّا كَانُوا۟ عَنْهَا مُعْرِضِينَ','Wa maa taateehim min Aayatim min Aayaati Rabbihim illaa kaanoo \'anhaa mu\'rideen',4,'6:4',13,51,102,2,0,128,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(794,6,'فَقَدْ كَذَّبُوا۟ بِٱلْحَقِّ لَمَّا جَآءَهُمْ ۖ فَسَوْفَ يَأْتِيهِمْ أَنۢبَـٰٓؤُا۟ مَا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ','Faqad kazzaboo bilhaqqi lammaa jaaa\'ahum fasawfa yaateehim ambaaa\'u maa kaanoo bihee yastahzi\'oon',5,'6:5',13,51,102,2,0,128,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(795,6,'أَلَمْ يَرَوْا۟ كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّن قَرْنٍ مَّكَّنَّـٰهُمْ فِى ٱلْأَرْضِ مَا لَمْ نُمَكِّن لَّكُمْ وَأَرْسَلْنَا ٱلسَّمَآءَ عَلَيْهِم مِّدْرَارًا وَجَعَلْنَا ٱلْأَنْهَـٰرَ تَجْرِى مِن تَحْتِهِمْ فَأَهْلَكْنَـٰهُم بِذُنُوبِهِمْ وَأَنشَأْنَا مِنۢ بَعْدِهِمْ قَرْنًا ءَاخَرِينَ','Alam yaraw kam ahlaknaa min qablihim min qarnim makkannaahum fil ardi maa lam numakkil lakum wa arsalnas samaaa\'a \'alaihim midraaranw wa ja\'alnal anhaara tajree min tahtihim fa ahlak naahum bizunoobihim wa anshaanaa mim ba\'dihim qarnan aakhareen',6,'6:6',13,51,102,2,0,128,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(796,6,'وَلَوْ نَزَّلْنَا عَلَيْكَ كِتَـٰبًا فِى قِرْطَاسٍ فَلَمَسُوهُ بِأَيْدِيهِمْ لَقَالَ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَـٰذَآ إِلَّا سِحْرٌ مُّبِينٌ','Wa law nazzalnaa \'alaika Kitaaban fee qirtaasin falamasoohu bi aideehim laqaalal lazeena kafarooo in haazaaa illaa sihrum mubeen',7,'6:7',13,51,102,2,0,128,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(797,6,'وَقَالُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ مَلَكٌ ۖ وَلَوْ أَنزَلْنَا مَلَكًا لَّقُضِىَ ٱلْأَمْرُ ثُمَّ لَا يُنظَرُونَ','Wa qaaloo law laaa unzila alaihi malakunw wa law anzalna malakal laqudiyal amru summa laa yunzaroon',8,'6:8',13,51,102,2,0,128,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(798,6,'وَلَوْ جَعَلْنَـٰهُ مَلَكًا لَّجَعَلْنَـٰهُ رَجُلًا وَلَلَبَسْنَا عَلَيْهِم مَّا يَلْبِسُونَ','Wa law ja\'alnaahu malakal laja\'alnaahu rajulanw wa lalabasnaa \'alaihim maa yalbisoon',9,'6:9',13,51,102,2,0,129,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(799,6,'وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍ مِّن قَبْلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُوا۟ مِنْهُم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ','Wa laqadis tuhzi\'a bi-Rusulim min qablika fahaaqa billazeena sakhiroo minhum maa kaanoo bihee yastahzi\'oon',10,'6:10',13,51,102,2,0,129,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(800,6,'قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ ثُمَّ ٱنظُرُوا۟ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُكَذِّبِينَ','Qul seeroo fil ardi summan zuroo kaifa kaana \'aaqibatul mukazzibeen',11,'6:11',13,51,103,2,0,129,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(801,6,'قُل لِّمَن مَّا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ قُل لِّلَّهِ ۚ كَتَبَ عَلَىٰ نَفْسِهِ ٱلرَّحْمَةَ ۚ لَيَجْمَعَنَّكُمْ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ لَا رَيْبَ فِيهِ ۚ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ فَهُمْ لَا يُؤْمِنُونَ','Qul limam maa fis samaawaati wal ardi qul lillaah; kataba \'alaa nafsihir rahmah; la yajma \'annakum ilaa Yawmil Qiyaamati laa raiba feeh; allazeena khasirooo anfusahum fahum laa yu\'minoon',12,'6:12',13,51,103,2,0,129,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(802,6,'۞ وَلَهُۥ مَا سَكَنَ فِى ٱلَّيْلِ وَٱلنَّهَارِ ۚ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ','Wa lahoo maa sakana fillaili wannahaar; wa Huwas Samee\'ul Aleem',13,'6:13',13,52,103,2,0,129,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(803,6,'قُلْ أَغَيْرَ ٱللَّهِ أَتَّخِذُ وَلِيًّا فَاطِرِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَهُوَ يُطْعِمُ وَلَا يُطْعَمُ ۗ قُلْ إِنِّىٓ أُمِرْتُ أَنْ أَكُونَ أَوَّلَ مَنْ أَسْلَمَ ۖ وَلَا تَكُونَنَّ مِنَ ٱلْمُشْرِكِينَ','Qul aghairal laahi attakhizu waliyyan faatiris samaawaati wal ardi wa Huwa yut\'imu wa laa yut\'am; qul inneee umirtu an akoona awwala man salama wa laa takoonanna minal mushrikeen',14,'6:14',13,52,103,2,0,129,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(804,6,'قُلْ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍ','Qul inneee akhaafu in \'asaitu Rabbee \'azaaba Yawmin \'Azeem',15,'6:15',13,52,103,2,0,129,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(805,6,'مَّن يُصْرَفْ عَنْهُ يَوْمَئِذٍ فَقَدْ رَحِمَهُۥ ۚ وَذَٰلِكَ ٱلْفَوْزُ ٱلْمُبِينُ','Mai yusraf \'anhu Yawma\'izin faqad rahimah; wa zaalikal fawzul mubeen',16,'6:16',13,52,103,2,0,129,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(806,6,'وَإِن يَمْسَسْكَ ٱللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَ ۖ وَإِن يَمْسَسْكَ بِخَيْرٍ فَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ','Wa iny-yamsaskal laahu bidurrin falaaa kaashifa lahoo illaa Huwa wa iny-yamsaska bikhairin fa Huwa \'alaa kulli shai\'in Qadeer',17,'6:17',13,52,103,2,0,129,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(807,6,'وَهُوَ ٱلْقَاهِرُ فَوْقَ عِبَادِهِۦ ۚ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ','Wa Huwal gaahiru fawqa \'ibaadih; wa Huwal Hakeemul Khabeer',18,'6:18',13,52,103,2,0,129,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(808,6,'قُلْ أَىُّ شَىْءٍ أَكْبَرُ شَهَـٰدَةً ۖ قُلِ ٱللَّهُ ۖ شَهِيدٌۢ بَيْنِى وَبَيْنَكُمْ ۚ وَأُوحِىَ إِلَىَّ هَـٰذَا ٱلْقُرْءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَ ۚ أَئِنَّكُمْ لَتَشْهَدُونَ أَنَّ مَعَ ٱللَّهِ ءَالِهَةً أُخْرَىٰ ۚ قُل لَّآ أَشْهَدُ ۚ قُلْ إِنَّمَا هُوَ إِلَـٰهٌ وَٰحِدٌ وَإِنَّنِى بَرِىٓءٌ مِّمَّا تُشْرِكُونَ','Qul ayyu shai\'in akbaru shahaadatan qulil laahu shaheedum bainee wa bainakum; wa oohiya ilaiya haazal Qur\'aanu li unzirakum bihee wa mam balagh; a\'innakum latashhadoona anna ma\'al laahi aalihatan ukhraa; qul laaa ashhad; qul innamaa Huwa Ilaahunw Waahidunw wa innanee baree\'um mimmaa tushrikoon',19,'6:19',13,52,103,2,0,130,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(809,6,'ٱلَّذِينَ ءَاتَيْنَـٰهُمُ ٱلْكِتَـٰبَ يَعْرِفُونَهُۥ كَمَا يَعْرِفُونَ أَبْنَآءَهُمُ ۘ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ فَهُمْ لَا يُؤْمِنُونَ','Allazeena aatainaa humul Kitaaba ya\'rifoonahoo kamaa ya\'rifoona abnaaa\'ahum; allazeena khasirooo anfusahum fahum laa yu\'minoon',20,'6:20',13,52,103,2,0,130,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(810,6,'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَـٰتِهِۦٓ ۗ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّـٰلِمُونَ','Wa man azlamu mim manif tara \'alal laahi kaziban aw kazzaba bi Aayaatih; innahoo laa yuflihuz zaalimoon',21,'6:21',13,52,104,2,0,130,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(811,6,'وَيَوْمَ نَحْشُرُهُمْ جَمِيعًا ثُمَّ نَقُولُ لِلَّذِينَ أَشْرَكُوٓا۟ أَيْنَ شُرَكَآؤُكُمُ ٱلَّذِينَ كُنتُمْ تَزْعُمُونَ','Wa yawma nahshuruhum jamee\'an summa naqoolu lillazeena ashrakooo ayna shurakaaa\' ukumul lazeena kuntum taz\'umoon',22,'6:22',13,52,104,2,0,130,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(812,6,'ثُمَّ لَمْ تَكُن فِتْنَتُهُمْ إِلَّآ أَن قَالُوا۟ وَٱللَّهِ رَبِّنَا مَا كُنَّا مُشْرِكِينَ','Summa lam takun fitnatuhum illaaa an qaaloo wallaahi Rabbinaa maa kunnaa mushrikeen',23,'6:23',13,52,104,2,0,130,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(813,6,'ٱنظُرْ كَيْفَ كَذَبُوا۟ عَلَىٰٓ أَنفُسِهِمْ ۚ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ','Unzur kaifa kazaboo \'alaaa anfusihim, wa dalla \'anhum maa kaanoo yaftaroon',24,'6:24',13,52,104,2,0,130,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(814,6,'وَمِنْهُم مَّن يَسْتَمِعُ إِلَيْكَ ۖ وَجَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِىٓ ءَاذَانِهِمْ وَقْرًا ۚ وَإِن يَرَوْا۟ كُلَّ ءَايَةٍ لَّا يُؤْمِنُوا۟ بِهَا ۚ حَتَّىٰٓ إِذَا جَآءُوكَ يُجَـٰدِلُونَكَ يَقُولُ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَـٰذَآ إِلَّآ أَسَـٰطِيرُ ٱلْأَوَّلِينَ','Wa minhum mai yastami\'u ilaika wa ja\'alnaa \'alaa quloobihim akinnatan ai yafqahoohu wa feee aazaanihim waqraa; wa ai yaraw kulla Aayatil laa yu\'minoo bihaa; hattaaa izaa jaaa\'oka yujaadiloonaka yaqoolul lazeena kafaroo in haazaa illaaa asaateerul awwaleen',25,'6:25',13,52,104,2,0,130,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(815,6,'وَهُمْ يَنْهَوْنَ عَنْهُ وَيَنْـَٔوْنَ عَنْهُ ۖ وَإِن يُهْلِكُونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ','Wa hum yanhawna \'anhu wa yan\'awna \'anhu wa iny yuhlikoona illaa anfusahum wa maa yash\'uroon',26,'6:26',13,52,104,2,0,130,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(816,6,'وَلَوْ تَرَىٰٓ إِذْ وُقِفُوا۟ عَلَى ٱلنَّارِ فَقَالُوا۟ يَـٰلَيْتَنَا نُرَدُّ وَلَا نُكَذِّبَ بِـَٔايَـٰتِ رَبِّنَا وَنَكُونَ مِنَ ٱلْمُؤْمِنِينَ','Wa law taraaa iz wauqifoo \'alan Naari faqaaloo yaa laitanaa nuraddu wa laa nukaz ziba bi Aayaati Rabbinaa wa nakoona minal mu\'mineen',27,'6:27',13,52,104,2,0,130,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(817,6,'بَلْ بَدَا لَهُم مَّا كَانُوا۟ يُخْفُونَ مِن قَبْلُ ۖ وَلَوْ رُدُّوا۟ لَعَادُوا۟ لِمَا نُهُوا۟ عَنْهُ وَإِنَّهُمْ لَكَـٰذِبُونَ','Bal badaa lahum maa kaanoo yukhfoona min qablu wa law ruddoo la\'aadoo limaa nuhoo \'anhu wa innahum lakaaziboon',28,'6:28',13,52,104,2,0,131,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(818,6,'وَقَالُوٓا۟ إِنْ هِىَ إِلَّا حَيَاتُنَا ٱلدُّنْيَا وَمَا نَحْنُ بِمَبْعُوثِينَ','Wa qaalooo in hiya illaa hayaatunad dunyaa wa maa nahnu bimab\'ooseen',29,'6:29',13,52,104,2,0,131,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(819,6,'وَلَوْ تَرَىٰٓ إِذْ وُقِفُوا۟ عَلَىٰ رَبِّهِمْ ۚ قَالَ أَلَيْسَ هَـٰذَا بِٱلْحَقِّ ۚ قَالُوا۟ بَلَىٰ وَرَبِّنَا ۚ قَالَ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ','Wa law taraa iz wuqifoo \'alaa Rabbihim; qaala alaisa haazaa bilhaqq; qaaloo balaa wa Rabbinaa; qaala fazooqul \'azaaba bimaa kuntum takfuroon',30,'6:30',13,52,104,2,0,131,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(820,6,'قَدْ خَسِرَ ٱلَّذِينَ كَذَّبُوا۟ بِلِقَآءِ ٱللَّهِ ۖ حَتَّىٰٓ إِذَا جَآءَتْهُمُ ٱلسَّاعَةُ بَغْتَةً قَالُوا۟ يَـٰحَسْرَتَنَا عَلَىٰ مَا فَرَّطْنَا فِيهَا وَهُمْ يَحْمِلُونَ أَوْزَارَهُمْ عَلَىٰ ظُهُورِهِمْ ۚ أَلَا سَآءَ مَا يَزِرُونَ','Qad khasiral lazeena kazzaboo biliqaaa\'il laahi hattaaa izaa jaaa\'at humus Saa\'atu baghtan qaaloo yaa hasratanaa \'alaa maa farratnaa feehaa wa hum yahmiloona awzaarahum \'alaa zuhoorihim; alaa saaa\'a ma yaziroon',31,'6:31',13,52,105,2,0,131,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(821,6,'وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا لَعِبٌ وَلَهْوٌ ۖ وَلَلدَّارُ ٱلْـَٔاخِرَةُ خَيْرٌ لِّلَّذِينَ يَتَّقُونَ ۗ أَفَلَا تَعْقِلُونَ','Wa mal hayaatud dunyaaa illaa la\'ibunw wa lahwunw wa lad Daarul Aakhiratu kahyrul lillazeena yattaqoon; afalaa ta\'qiloon',32,'6:32',13,52,105,2,0,131,7,'2023-12-01 11:30:04','2026-09-22 00:06:42'),(822,6,'قَدْ نَعْلَمُ إِنَّهُۥ لَيَحْزُنُكَ ٱلَّذِى يَقُولُونَ ۖ فَإِنَّهُمْ لَا يُكَذِّبُونَكَ وَلَـٰكِنَّ ٱلظَّـٰلِمِينَ بِـَٔايَـٰتِ ٱللَّهِ يَجْحَدُونَ','Qad na\'lamu innahoo layahzunukal lazee yaqooloona fa innahum laa yukazziboonaka wa laakinnaz zaalimeena bi Aayaatil laahi yajhadoon',33,'6:33',13,52,105,2,0,131,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(823,6,'وَلَقَدْ كُذِّبَتْ رُسُلٌ مِّن قَبْلِكَ فَصَبَرُوا۟ عَلَىٰ مَا كُذِّبُوا۟ وَأُوذُوا۟ حَتَّىٰٓ أَتَىٰهُمْ نَصْرُنَا ۚ وَلَا مُبَدِّلَ لِكَلِمَـٰتِ ٱللَّهِ ۚ وَلَقَدْ جَآءَكَ مِن نَّبَإِى۟ ٱلْمُرْسَلِينَ','Wa laqad kuzzibat Rusulum min qablika fasabaroo \'alaa maa kuzziboo wa oozoo hattaaa ataahum nasrunaa; wa laa mubaddila li Kalimaatil laah; wa laqad jaaa\'aka min naba\'il mursaleen',34,'6:34',13,52,105,2,0,131,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(824,6,'وَإِن كَانَ كَبُرَ عَلَيْكَ إِعْرَاضُهُمْ فَإِنِ ٱسْتَطَعْتَ أَن تَبْتَغِىَ نَفَقًا فِى ٱلْأَرْضِ أَوْ سُلَّمًا فِى ٱلسَّمَآءِ فَتَأْتِيَهُم بِـَٔايَةٍ ۚ وَلَوْ شَآءَ ٱللَّهُ لَجَمَعَهُمْ عَلَى ٱلْهُدَىٰ ۚ فَلَا تَكُونَنَّ مِنَ ٱلْجَـٰهِلِينَ','Wa in kaana kabura \'alaika i\'raaduhum fa inistata\'ta an tabtaghiya nafaqan fil ardi aw sullaman fis samaaa\'i fataa tiyahum bi Aayah; wa law shaaa\'al laahu lajama\'ahum \'alal hudaa; falaa takoonanna minal jaahileen',35,'6:35',13,52,105,2,0,131,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(825,6,'۞ إِنَّمَا يَسْتَجِيبُ ٱلَّذِينَ يَسْمَعُونَ ۘ وَٱلْمَوْتَىٰ يَبْعَثُهُمُ ٱللَّهُ ثُمَّ إِلَيْهِ يُرْجَعُونَ','Innamaa yastajeebul lazeena yasma\'oon; walmawtaa yab\'asuhumul laahu summa ilaihi yurja\'oon',36,'6:36',14,53,105,2,0,132,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(826,6,'وَقَالُوا۟ لَوْلَا نُزِّلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦ ۚ قُلْ إِنَّ ٱللَّهَ قَادِرٌ عَلَىٰٓ أَن يُنَزِّلَ ءَايَةً وَلَـٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ','Wa qaaloo law laa nuzzila \'alaihi Aayatum mir Rabbih; qul innal laaha qaadirun \'alaaa ai yunazzila Aayatanw wa laakinna aksarahum laa ya\'lamoon',37,'6:37',14,53,105,2,0,132,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(827,6,'وَمَا مِن دَآبَّةٍ فِى ٱلْأَرْضِ وَلَا طَـٰٓئِرٍ يَطِيرُ بِجَنَاحَيْهِ إِلَّآ أُمَمٌ أَمْثَالُكُم ۚ مَّا فَرَّطْنَا فِى ٱلْكِتَـٰبِ مِن شَىْءٍ ۚ ثُمَّ إِلَىٰ رَبِّهِمْ يُحْشَرُونَ','Wa maa min daaabbatin fil ardi wa laa taaa\'iriny yateeru bijanaahaihi illaaa umamun amsaalukum; maa farratnaa fil Kitaabi min shai\'in summa ilaa Rabbihim yuhsharoon',38,'6:38',14,53,105,2,0,132,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(828,6,'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا صُمٌّ وَبُكْمٌ فِى ٱلظُّلُمَـٰتِ ۗ مَن يَشَإِ ٱللَّهُ يُضْلِلْهُ وَمَن يَشَأْ يَجْعَلْهُ عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ','Wallazeena kazzaboo bi Aayaatinaa summunw wa bukmun fiz zulumaat; mai yasha il laahu yudlilh; wa mai yashaa yaj\'alhu \'alaa Siraatim Mustaqeem',39,'6:39',14,53,105,2,0,132,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(829,6,'قُلْ أَرَءَيْتَكُمْ إِنْ أَتَىٰكُمْ عَذَابُ ٱللَّهِ أَوْ أَتَتْكُمُ ٱلسَّاعَةُ أَغَيْرَ ٱللَّهِ تَدْعُونَ إِن كُنتُمْ صَـٰدِقِينَ','Qaul ara\'aytakum in ataakum \'azaabul laahi aw atatkumus Saa\'atu a-ghairal laahi tad\'oona in kuntum saadiqeen',40,'6:40',14,53,105,2,0,132,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(830,6,'بَلْ إِيَّاهُ تَدْعُونَ فَيَكْشِفُ مَا تَدْعُونَ إِلَيْهِ إِن شَآءَ وَتَنسَوْنَ مَا تُشْرِكُونَ','Bal iyyaahu tad\'oona fa yakshifu maa tad\'oona ilaihi in shaaa\'a wa tansawna maa tushrikoon',41,'6:41',14,53,105,2,0,132,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(831,6,'وَلَقَدْ أَرْسَلْنَآ إِلَىٰٓ أُمَمٍ مِّن قَبْلِكَ فَأَخَذْنَـٰهُم بِٱلْبَأْسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمْ يَتَضَرَّعُونَ','Wa laqad arsalnaaa ilaaa umamim min qablika fa akhaznaahum bilbaasaaa\'i waddarraaa\'i la\'allahum yata darra\'oon',42,'6:42',14,53,106,2,0,132,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(832,6,'فَلَوْلَآ إِذْ جَآءَهُم بَأْسُنَا تَضَرَّعُوا۟ وَلَـٰكِن قَسَتْ قُلُوبُهُمْ وَزَيَّنَ لَهُمُ ٱلشَّيْطَـٰنُ مَا كَانُوا۟ يَعْمَلُونَ','Falaw laaa iz jaaa\'ahum baasunaa tadarra\'oo wa laakin qasat quloobuhum wa zaiyana lahumush Shaitaanu maa kaanoo ya\'maloon',43,'6:43',14,53,106,2,0,132,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(833,6,'فَلَمَّا نَسُوا۟ مَا ذُكِّرُوا۟ بِهِۦ فَتَحْنَا عَلَيْهِمْ أَبْوَٰبَ كُلِّ شَىْءٍ حَتَّىٰٓ إِذَا فَرِحُوا۟ بِمَآ أُوتُوٓا۟ أَخَذْنَـٰهُم بَغْتَةً فَإِذَا هُم مُّبْلِسُونَ','Falammaa nasoo maa zukkiroo bihee fatahnaa \'alaihim abwaaba kulli shai\'in hattaaa izaa farihoo bimaaa ootooo akhaznaahum baghtatan fa izaa hum mmublisoon',44,'6:44',14,53,106,2,0,132,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(834,6,'فَقُطِعَ دَابِرُ ٱلْقَوْمِ ٱلَّذِينَ ظَلَمُوا۟ ۚ وَٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَـٰلَمِينَ','Faquti\'a daabirul qawmil lazeena zalamoo; walhamdu lillaahi Rabbil \'aalameen',45,'6:45',14,53,106,2,0,133,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(835,6,'قُلْ أَرَءَيْتُمْ إِنْ أَخَذَ ٱللَّهُ سَمْعَكُمْ وَأَبْصَـٰرَكُمْ وَخَتَمَ عَلَىٰ قُلُوبِكُم مَّنْ إِلَـٰهٌ غَيْرُ ٱللَّهِ يَأْتِيكُم بِهِ ۗ ٱنظُرْ كَيْفَ نُصَرِّفُ ٱلْـَٔايَـٰتِ ثُمَّ هُمْ يَصْدِفُونَ','Qul ara\'aitum in akhazal laahu sam\'akum wa absaarakum wa khatama \'alaa quloobikum man ilaahun ghairul laahi yaateekum bih; unzur kaifa nusarriful Aayaati summa hum yasdifoon',46,'6:46',14,53,106,2,0,133,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(836,6,'قُلْ أَرَءَيْتَكُمْ إِنْ أَتَىٰكُمْ عَذَابُ ٱللَّهِ بَغْتَةً أَوْ جَهْرَةً هَلْ يُهْلَكُ إِلَّا ٱلْقَوْمُ ٱلظَّـٰلِمُونَ','Qul ara\'aitakum in ataakum \'azaabul laahi baghtatan aw jahratan hal yuhlaku illal qawmuz zaalimoon',47,'6:47',14,53,106,2,0,133,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(837,6,'وَمَا نُرْسِلُ ٱلْمُرْسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَ ۖ فَمَنْ ءَامَنَ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ','Wa maa nursilul mursaleena illaa mubashshireena wa munzireena faman aamana wa aslaha falaa khawfun \'alaihim wa laa hum yahzanoon',48,'6:48',14,53,106,2,0,133,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(838,6,'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا يَمَسُّهُمُ ٱلْعَذَابُ بِمَا كَانُوا۟ يَفْسُقُونَ','Wallazeena kazzaboo bi Aayaatinaa yamassuhumul \'azaabu bimaa kaanoo yafsuqoon',49,'6:49',14,53,106,2,0,133,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(839,6,'قُل لَّآ أَقُولُ لَكُمْ عِندِى خَزَآئِنُ ٱللَّهِ وَلَآ أَعْلَمُ ٱلْغَيْبَ وَلَآ أَقُولُ لَكُمْ إِنِّى مَلَكٌ ۖ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ ۚ قُلْ هَلْ يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ ۚ أَفَلَا تَتَفَكَّرُونَ','Qul laaa aqoolu lakum \'indee khazaaa\'inul laahi wa laaa a\'lamul ghaiba wa laaa aqoolu lakum innee malakun in attabi\'u illaa maa yoohaaa ilaiy; qul hal yastawil a\'maa walbaseer; afalaa tatafakkaroon',50,'6:50',14,53,106,2,0,133,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(840,6,'وَأَنذِرْ بِهِ ٱلَّذِينَ يَخَافُونَ أَن يُحْشَرُوٓا۟ إِلَىٰ رَبِّهِمْ ۙ لَيْسَ لَهُم مِّن دُونِهِۦ وَلِىٌّ وَلَا شَفِيعٌ لَّعَلَّهُمْ يَتَّقُونَ','Wa anzir bihil lazeena yakhaafoona ai yuhsharooo ilaa Rabbihim laisa lahum min doonihee waliyyunw wa laa shafee\'ul la\'allahum yattaqoon',51,'6:51',14,53,107,2,0,133,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(841,6,'وَلَا تَطْرُدِ ٱلَّذِينَ يَدْعُونَ رَبَّهُم بِٱلْغَدَوٰةِ وَٱلْعَشِىِّ يُرِيدُونَ وَجْهَهُۥ ۖ مَا عَلَيْكَ مِنْ حِسَابِهِم مِّن شَىْءٍ وَمَا مِنْ حِسَابِكَ عَلَيْهِم مِّن شَىْءٍ فَتَطْرُدَهُمْ فَتَكُونَ مِنَ ٱلظَّـٰلِمِينَ','Wa laa tatrudil lazeena yad\'oona Rabbahum bilghadaati wal \'ashiyyi yureedoona Wajhahoo ma \'alaika min hisaabihim min shai\'inw wa maa min hisaabika \'alaihim min shai\'in fatatrudahum fatakoona minaz zaalimeen',52,'6:52',14,53,107,2,0,133,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(842,6,'وَكَذَٰلِكَ فَتَنَّا بَعْضَهُم بِبَعْضٍ لِّيَقُولُوٓا۟ أَهَـٰٓؤُلَآءِ مَنَّ ٱللَّهُ عَلَيْهِم مِّنۢ بَيْنِنَآ ۗ أَلَيْسَ ٱللَّهُ بِأَعْلَمَ بِٱلشَّـٰكِرِينَ','Wa kazaalika fatannaa ba\'dahum biba\'dil liyaqoolooo ahaaa\'ulaaa\'i mannal laahu \'alaihim mim baininaa; alaisal laahu bi-a\'lama bish shaakireen',53,'6:53',14,53,107,2,0,134,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(843,6,'وَإِذَا جَآءَكَ ٱلَّذِينَ يُؤْمِنُونَ بِـَٔايَـٰتِنَا فَقُلْ سَلَـٰمٌ عَلَيْكُمْ ۖ كَتَبَ رَبُّكُمْ عَلَىٰ نَفْسِهِ ٱلرَّحْمَةَ ۖ أَنَّهُۥ مَنْ عَمِلَ مِنكُمْ سُوٓءًۢا بِجَهَـٰلَةٍ ثُمَّ تَابَ مِنۢ بَعْدِهِۦ وَأَصْلَحَ فَأَنَّهُۥ غَفُورٌ رَّحِيمٌ','Wa izaa jaaa\'akal lazeena yu\'minoona bi Aayaatinaa faqul salaamun \'alaikum kataba Rabbukum \'alaa nafsihir rahmata annahoo man \'amila minkum sooo\'am bijahaalatin summa taaba mim ba\'dihee wa aslaha fa annahoo Ghafoorur Raheem',54,'6:54',14,53,107,2,0,134,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(844,6,'وَكَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَـٰتِ وَلِتَسْتَبِينَ سَبِيلُ ٱلْمُجْرِمِينَ','Wa kazaalika nufassilul Aayaati wa litastabeena sabeelul mujrimeen',55,'6:55',14,53,107,2,0,134,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(845,6,'قُلْ إِنِّى نُهِيتُ أَنْ أَعْبُدَ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ ۚ قُل لَّآ أَتَّبِعُ أَهْوَآءَكُمْ ۙ قَدْ ضَلَلْتُ إِذًا وَمَآ أَنَا۠ مِنَ ٱلْمُهْتَدِينَ','Qul innee nuheetu an a\'budal lazeena tad\'oona min doonil laah; qul laaa attabi\'u ahwaaa\'akum qad dalaltu izanw wa maaa ana minal muhtadeen',56,'6:56',14,53,108,2,0,134,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(846,6,'قُلْ إِنِّى عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَكَذَّبْتُم بِهِۦ ۚ مَا عِندِى مَا تَسْتَعْجِلُونَ بِهِۦٓ ۚ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ ۖ يَقُصُّ ٱلْحَقَّ ۖ وَهُوَ خَيْرُ ٱلْفَـٰصِلِينَ','Qul innee \'alaa baiyinatim mir Rabbee wa kazzabtum bih; maa \'indee maa tasta\'jiloona bih; inil hukmu illaa lillaahi yaqussul haqqa wa Huwa khairul faasileen',57,'6:57',14,53,108,2,0,134,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(847,6,'قُل لَّوْ أَنَّ عِندِى مَا تَسْتَعْجِلُونَ بِهِۦ لَقُضِىَ ٱلْأَمْرُ بَيْنِى وَبَيْنَكُمْ ۗ وَٱللَّهُ أَعْلَمُ بِٱلظَّـٰلِمِينَ','Qul law anna \'indee maa tasta\'jiloona bihee laqudiyal amru bainee wa bainakum; wallaahu a\'lamu bizzaalimeen',58,'6:58',14,53,108,2,0,134,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(848,6,'۞ وَعِندَهُۥ مَفَاتِحُ ٱلْغَيْبِ لَا يَعْلَمُهَآ إِلَّا هُوَ ۚ وَيَعْلَمُ مَا فِى ٱلْبَرِّ وَٱلْبَحْرِ ۚ وَمَا تَسْقُطُ مِن وَرَقَةٍ إِلَّا يَعْلَمُهَا وَلَا حَبَّةٍ فِى ظُلُمَـٰتِ ٱلْأَرْضِ وَلَا رَطْبٍ وَلَا يَابِسٍ إِلَّا فِى كِتَـٰبٍ مُّبِينٍ','Wa \'indahoo mafaatihul ghaibi laa ya\'lamuhaaa illaa Hoo; wa ya\'lamu maa fil barri walbahr; wa maa tasqutu minw waraqatin illaa ya\'lamuhaa wa laa habbatin fee zulumaatil ardi wa laa ratbinw wa laa yaabisin illaa fee Kitaabim Mubeen',59,'6:59',14,54,108,2,0,134,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(849,6,'وَهُوَ ٱلَّذِى يَتَوَفَّىٰكُم بِٱلَّيْلِ وَيَعْلَمُ مَا جَرَحْتُم بِٱلنَّهَارِ ثُمَّ يَبْعَثُكُمْ فِيهِ لِيُقْضَىٰٓ أَجَلٌ مُّسَمًّى ۖ ثُمَّ إِلَيْهِ مَرْجِعُكُمْ ثُمَّ يُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ','Wa Huwal lazee yatawaf faakum billaili wa ya\'lamu maa jarahtum binnahaari summa yab\'asukum fee liyuqdaaa ajalum musamman summa ilaihi marji\'ukum summa yunabbi \'ukum bimaa kuntum ta\'maloon',60,'6:60',14,54,108,2,0,135,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(850,6,'وَهُوَ ٱلْقَاهِرُ فَوْقَ عِبَادِهِۦ ۖ وَيُرْسِلُ عَلَيْكُمْ حَفَظَةً حَتَّىٰٓ إِذَا جَآءَ أَحَدَكُمُ ٱلْمَوْتُ تَوَفَّتْهُ رُسُلُنَا وَهُمْ لَا يُفَرِّطُونَ','Wa huwal qaahiru fawqa \'ibaadihee wa yursilu \'alaikum hafazatan hattaaa izaa jaaa\'a ahadakumul mawtu tawaffathu rusulunaa wa hum laa yufarritoon',61,'6:61',14,54,109,2,0,135,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(851,6,'ثُمَّ رُدُّوٓا۟ إِلَى ٱللَّهِ مَوْلَىٰهُمُ ٱلْحَقِّ ۚ أَلَا لَهُ ٱلْحُكْمُ وَهُوَ أَسْرَعُ ٱلْحَـٰسِبِينَ','Summa ruddooo ilallaahi mawlaahumul haqq; alaa lahul hukmu wa Huwa asra\'ul haasibeen',62,'6:62',14,54,109,2,0,135,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(852,6,'قُلْ مَن يُنَجِّيكُم مِّن ظُلُمَـٰتِ ٱلْبَرِّ وَٱلْبَحْرِ تَدْعُونَهُۥ تَضَرُّعًا وَخُفْيَةً لَّئِنْ أَنجَىٰنَا مِنْ هَـٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّـٰكِرِينَ','Qul mai yunajjeekum min zulumaatil barri walbahri tad\'oonahoo tadarru\'anw wa khufyatann la\'in anjaanaa min haazihee lanakoonana minash shaakireen',63,'6:63',14,54,109,2,0,135,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(853,6,'قُلِ ٱللَّهُ يُنَجِّيكُم مِّنْهَا وَمِن كُلِّ كَرْبٍ ثُمَّ أَنتُمْ تُشْرِكُونَ','Qulil laahu yunajjjeekum minhaa wa min kulli karbin summa antum tushrikoon',64,'6:64',14,54,109,2,0,135,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(854,6,'قُلْ هُوَ ٱلْقَادِرُ عَلَىٰٓ أَن يَبْعَثَ عَلَيْكُمْ عَذَابًا مِّن فَوْقِكُمْ أَوْ مِن تَحْتِ أَرْجُلِكُمْ أَوْ يَلْبِسَكُمْ شِيَعًا وَيُذِيقَ بَعْضَكُم بَأْسَ بَعْضٍ ۗ ٱنظُرْ كَيْفَ نُصَرِّفُ ٱلْـَٔايَـٰتِ لَعَلَّهُمْ يَفْقَهُونَ','Qul huwal Qaadiru \'alaaa ai yab\'asa \'alaikum \'azaabam min fawqikum aw min tahti arjulikum aw yalbisakum shiya\'anw wa yuzeeqa ba\'dakum baasa ba\'d; unzur kaifa nusarriful Aayaati la\'allahum yafqahoon',65,'6:65',14,54,109,2,0,135,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(855,6,'وَكَذَّبَ بِهِۦ قَوْمُكَ وَهُوَ ٱلْحَقُّ ۚ قُل لَّسْتُ عَلَيْكُم بِوَكِيلٍ','Wa kaz zaba bihee qawmuka wa huwal haqq; qul lastu\'alaikum biwakeel',66,'6:66',14,54,109,2,0,135,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(856,6,'لِّكُلِّ نَبَإٍ مُّسْتَقَرٌّ ۚ وَسَوْفَ تَعْلَمُونَ','Likulli naba im mustaqar runw wa sawfa ta\'lamoon',67,'6:67',14,54,109,2,0,135,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(857,6,'وَإِذَا رَأَيْتَ ٱلَّذِينَ يَخُوضُونَ فِىٓ ءَايَـٰتِنَا فَأَعْرِضْ عَنْهُمْ حَتَّىٰ يَخُوضُوا۟ فِى حَدِيثٍ غَيْرِهِۦ ۚ وَإِمَّا يُنسِيَنَّكَ ٱلشَّيْطَـٰنُ فَلَا تَقْعُدْ بَعْدَ ٱلذِّكْرَىٰ مَعَ ٱلْقَوْمِ ٱلظَّـٰلِمِينَ','Wa izaa ra aital lazeena yakhoodoona feee Aayaatinaa fa a\'rid \'anhum hattaa yakkhoodoo fee hadeesin ghairih; wa immaa yunsiyannakash Shaitaanu falaa taq\'ud ba\'dazzikraa ma\'al qawmiz zaalimeen',68,'6:68',14,54,109,2,0,135,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(858,6,'وَمَا عَلَى ٱلَّذِينَ يَتَّقُونَ مِنْ حِسَابِهِم مِّن شَىْءٍ وَلَـٰكِن ذِكْرَىٰ لَعَلَّهُمْ يَتَّقُونَ','Wa maa \'alal lazeena yattaqoona min hisaabihim min shai\'inw wa laakin zikraa la\'allahum yattaqoon',69,'6:69',14,54,109,2,0,136,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(859,6,'وَذَرِ ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَهُمْ لَعِبًا وَلَهْوًا وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا ۚ وَذَكِّرْ بِهِۦٓ أَن تُبْسَلَ نَفْسٌۢ بِمَا كَسَبَتْ لَيْسَ لَهَا مِن دُونِ ٱللَّهِ وَلِىٌّ وَلَا شَفِيعٌ وَإِن تَعْدِلْ كُلَّ عَدْلٍ لَّا يُؤْخَذْ مِنْهَآ ۗ أُو۟لَـٰٓئِكَ ٱلَّذِينَ أُبْسِلُوا۟ بِمَا كَسَبُوا۟ ۖ لَهُمْ شَرَابٌ مِّنْ حَمِيمٍ وَعَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْفُرُونَ','Wa zaril lazeenat takhazoo deenahum la\'ibanwwa lahwanw wa gharrat humul ha yaatud dunyaa; wa zakkir biheee an tubsala nafsum bimaa kasabat laisa lahaa min doonil laahi waliyyunw wa laa shafee\'unw wa in ta\'dil kulla \'adlil laa yu\'khaz minhaa; ulaaa \'ikal lazeena ubsiloo bimaa kasaboo lahum sharaabum min hameeminw wa \'azaabun aleemum bimaa kaanoo yakkfuroon',70,'6:70',14,54,109,2,0,136,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(860,6,'قُلْ أَنَدْعُوا۟ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا وَنُرَدُّ عَلَىٰٓ أَعْقَابِنَا بَعْدَ إِذْ هَدَىٰنَا ٱللَّهُ كَٱلَّذِى ٱسْتَهْوَتْهُ ٱلشَّيَـٰطِينُ فِى ٱلْأَرْضِ حَيْرَانَ لَهُۥٓ أَصْحَـٰبٌ يَدْعُونَهُۥٓ إِلَى ٱلْهُدَى ٱئْتِنَا ۗ قُلْ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلْهُدَىٰ ۖ وَأُمِرْنَا لِنُسْلِمَ لِرَبِّ ٱلْعَـٰلَمِينَ','Qul anad\'oo min doonil laahi maa laa yanfa\'unaa wa laa yadurrunaa wa nuraddu \'alaaa a\'qaabina ba\'da iz hadaanal laahu kallazis tahwat hush Shayaateenu fil ardi hairaana lahooo ashaabuny yad\'oo nahooo ilal huda\' tinaa; qul inna hudal laahi huwal hudaa wa umirnaa linuslima li Rabbil \'aalameen',71,'6:71',14,54,110,2,0,136,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(861,6,'وَأَنْ أَقِيمُوا۟ ٱلصَّلَوٰةَ وَٱتَّقُوهُ ۚ وَهُوَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ','Wa an aqeemus Salaata wattaqooh; wa Hual lazeee ilaihi tuhsharoon',72,'6:72',14,54,110,2,0,136,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(862,6,'وَهُوَ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ ۖ وَيَوْمَ يَقُولُ كُن فَيَكُونُ ۚ قَوْلُهُ ٱلْحَقُّ ۚ وَلَهُ ٱلْمُلْكُ يَوْمَ يُنفَخُ فِى ٱلصُّورِ ۚ عَـٰلِمُ ٱلْغَيْبِ وَٱلشَّهَـٰدَةِ ۚ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ','Wa an Huwal lazee khalaqas samaawaati wal arda bilhaqq; wa Yawma yaqoolu kun fa yakoon; Qawluhul haqq; wa lahul mulku Yawma yunfakhu fis Soor; \'Aalimul Ghaibi wash shahaadah; wa Huwal Hakeemul Khabeer',73,'6:73',14,54,110,2,0,136,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(863,6,'۞ وَإِذْ قَالَ إِبْرَٰهِيمُ لِأَبِيهِ ءَازَرَ أَتَتَّخِذُ أَصْنَامًا ءَالِهَةً ۖ إِنِّىٓ أَرَىٰكَ وَقَوْمَكَ فِى ضَلَـٰلٍ مُّبِينٍ','Wa iz qaala Ibraaheemu li abeehi Aazara a-tattakhizu asnaaman aalihatan inneee araaka wa qawmaka fee dalaalim mmubeen',74,'6:74',14,55,110,2,0,137,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(864,6,'وَكَذَٰلِكَ نُرِىٓ إِبْرَٰهِيمَ مَلَكُوتَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَلِيَكُونَ مِنَ ٱلْمُوقِنِينَ','Wa kazaalika nureee Ibraaheema malakootas samaawaati wal ardi wa liyakoona minal mooqineen',75,'6:75',14,55,110,2,0,137,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(865,6,'فَلَمَّا جَنَّ عَلَيْهِ ٱلَّيْلُ رَءَا كَوْكَبًا ۖ قَالَ هَـٰذَا رَبِّى ۖ فَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ ٱلْـَٔافِلِينَ','Falammaa janna \'alaihil lailu ra aa kawkabaan qaala haaza Rabbee falammaaa afala qaala laaa uhibbul aafileen',76,'6:76',14,55,110,2,0,137,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(866,6,'فَلَمَّا رَءَا ٱلْقَمَرَ بَازِغًا قَالَ هَـٰذَا رَبِّى ۖ فَلَمَّآ أَفَلَ قَالَ لَئِن لَّمْ يَهْدِنِى رَبِّى لَأَكُونَنَّ مِنَ ٱلْقَوْمِ ٱلضَّآلِّينَ','Falammmaa ra al qamara baazighan qaala haazaa Rabbee falammmmaaa afala qaala la\'il lam yahdinee Rabbee la akoonanna minal qawmid daaalleen',77,'6:77',14,55,110,2,0,137,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(867,6,'فَلَمَّا رَءَا ٱلشَّمْسَ بَازِغَةً قَالَ هَـٰذَا رَبِّى هَـٰذَآ أَكْبَرُ ۖ فَلَمَّآ أَفَلَتْ قَالَ يَـٰقَوْمِ إِنِّى بَرِىٓءٌ مِّمَّا تُشْرِكُونَ','Falammmaa ra ashshamsa baazighatan qaala haazaa Rabbee haazaaa akbaru falammaaa afalat qaala yaa qawmi innee bareee\'um mimmaa tushrikoon',78,'6:78',14,55,110,2,0,137,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(868,6,'إِنِّى وَجَّهْتُ وَجْهِىَ لِلَّذِى فَطَرَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ حَنِيفًا ۖ وَمَآ أَنَا۠ مِنَ ٱلْمُشْرِكِينَ','Innnee wajjahtu wajhiya lillazee fataras samaawaati wal arda haneefanw wa maaa ana minal mushrikeen',79,'6:79',14,55,110,2,0,137,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(869,6,'وَحَآجَّهُۥ قَوْمُهُۥ ۚ قَالَ أَتُحَـٰٓجُّوٓنِّى فِى ٱللَّهِ وَقَدْ هَدَىٰنِ ۚ وَلَآ أَخَافُ مَا تُشْرِكُونَ بِهِۦٓ إِلَّآ أَن يَشَآءَ رَبِّى شَيْـًٔا ۗ وَسِعَ رَبِّى كُلَّ شَىْءٍ عِلْمًا ۗ أَفَلَا تَتَذَكَّرُونَ','Wa haaajjahoo qawmuh; qaala a-tuh aaajjooonnnee fillaahi wa qad hadaan; wa laaa akhaafu mmaa tushrikoona bihee illaaa ai yashaaa\'a Rabbee shai\'anw wasi\'a Rabbee kulla shai\'in \'ilman afalaa tatazakkaroon',80,'6:80',14,55,110,2,0,137,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(870,6,'وَكَيْفَ أَخَافُ مَآ أَشْرَكْتُمْ وَلَا تَخَافُونَ أَنَّكُمْ أَشْرَكْتُم بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ عَلَيْكُمْ سُلْطَـٰنًا ۚ فَأَىُّ ٱلْفَرِيقَيْنِ أَحَقُّ بِٱلْأَمْنِ ۖ إِن كُنتُمْ تَعْلَمُونَ','Wa kaifa akhaafu maaa ashraktum wa laa takhaafoona annakum ashraktum billaahi maa lam yunazzil bihee \'alaikum sultaanaa; fa aiyul fareeqaini ahaqqu bil amni in kuntum ta\'lamoon',81,'6:81',14,55,110,2,0,137,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(871,6,'ٱلَّذِينَ ءَامَنُوا۟ وَلَمْ يَلْبِسُوٓا۟ إِيمَـٰنَهُم بِظُلْمٍ أُو۟لَـٰٓئِكَ لَهُمُ ٱلْأَمْنُ وَهُم مُّهْتَدُونَ','Allazeena aamanoo wa lam yalbisooo eemaanahum bizulmin ulaaa\'ika lahumul amnu wa hum muhtadoon',82,'6:82',14,55,110,2,0,138,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(872,6,'وَتِلْكَ حُجَّتُنَآ ءَاتَيْنَـٰهَآ إِبْرَٰهِيمَ عَلَىٰ قَوْمِهِۦ ۚ نَرْفَعُ دَرَجَـٰتٍ مَّن نَّشَآءُ ۗ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ','Wa tilka hujjatunaaa aatainaahaaa Ibraaheema \'alaa qawmih; narfa\'u darajaatim man nashaaa\'; inna Rabbaka Hakeemun \'Aleem',83,'6:83',14,55,111,2,0,138,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(873,6,'وَوَهَبْنَا لَهُۥٓ إِسْحَـٰقَ وَيَعْقُوبَ ۚ كُلًّا هَدَيْنَا ۚ وَنُوحًا هَدَيْنَا مِن قَبْلُ ۖ وَمِن ذُرِّيَّتِهِۦ دَاوُۥدَ وَسُلَيْمَـٰنَ وَأَيُّوبَ وَيُوسُفَ وَمُوسَىٰ وَهَـٰرُونَ ۚ وَكَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ','Wa wahabnaa lahoo ishaaqa wa ya\'qoob; kullan hadainaa; wa Noohan hadainaa min qablu wa min zurriyyatihee Daawooda wa Sulaimaana wa Ayyooba wa Yoosufa wa Moosaa wa haaroon; wa kazaalika najzil muhsineen',84,'6:84',14,55,111,2,0,138,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(874,6,'وَزَكَرِيَّا وَيَحْيَىٰ وَعِيسَىٰ وَإِلْيَاسَ ۖ كُلٌّ مِّنَ ٱلصَّـٰلِحِينَ','Wa Zakariyyaa wa Yahyaa wa \'Eesaa wa Illyaasa kullum minas saaliheen',85,'6:85',14,55,111,2,0,138,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(875,6,'وَإِسْمَـٰعِيلَ وَٱلْيَسَعَ وَيُونُسَ وَلُوطًا ۚ وَكُلًّا فَضَّلْنَا عَلَى ٱلْعَـٰلَمِينَ','Wa Ismaa\'eela wal Yasa\'a wa Yoonusa wa Lootaa; wa kullan faddalnaa \'alal \'aalameen',86,'6:86',14,55,111,2,0,138,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(876,6,'وَمِنْ ءَابَآئِهِمْ وَذُرِّيَّـٰتِهِمْ وَإِخْوَٰنِهِمْ ۖ وَٱجْتَبَيْنَـٰهُمْ وَهَدَيْنَـٰهُمْ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ','Wa min aabaaa\'ihim wa zurriyyaatihim wa ikhwaanihim wajtabainaahum wa hadainaahum ilaa Siraatim Mustaqeem',87,'6:87',14,55,111,2,0,138,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(877,6,'ذَٰلِكَ هُدَى ٱللَّهِ يَهْدِى بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦ ۚ وَلَوْ أَشْرَكُوا۟ لَحَبِطَ عَنْهُم مَّا كَانُوا۟ يَعْمَلُونَ','Zaalika hudal laahi yahdee bihee mai yashaaa\'u min \'ibaadih; wa law ashrakoo lahabita \'anhum maa kaanoo ya\'maloon',88,'6:88',14,55,111,2,0,138,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(878,6,'أُو۟لَـٰٓئِكَ ٱلَّذِينَ ءَاتَيْنَـٰهُمُ ٱلْكِتَـٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ ۚ فَإِن يَكْفُرْ بِهَا هَـٰٓؤُلَآءِ فَقَدْ وَكَّلْنَا بِهَا قَوْمًا لَّيْسُوا۟ بِهَا بِكَـٰفِرِينَ','Ulaaa\'ikal lazeena aatainaahumul Kitaaba wal hukma wan Nubuwwah; fa iny yakfur bihaa haaa\'ulaaa\'i faqad wakkalnaa bihaa qawmal laisoo bihaa bikaafireen',89,'6:89',14,55,111,2,0,138,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(879,6,'أُو۟لَـٰٓئِكَ ٱلَّذِينَ هَدَى ٱللَّهُ ۖ فَبِهُدَىٰهُمُ ٱقْتَدِهْ ۗ قُل لَّآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا ۖ إِنْ هُوَ إِلَّا ذِكْرَىٰ لِلْعَـٰلَمِينَ','Ulaaa\'ikal lazeena hadal laahu fabihudaahumuq tadih; qul laaa as\'alukum \'alaihi ajran in huwa illaa zikraa lil \'aalameen',90,'6:90',14,55,111,2,0,138,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(880,6,'وَمَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدْرِهِۦٓ إِذْ قَالُوا۟ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ بَشَرٍ مِّن شَىْءٍ ۗ قُلْ مَنْ أَنزَلَ ٱلْكِتَـٰبَ ٱلَّذِى جَآءَ بِهِۦ مُوسَىٰ نُورًا وَهُدًى لِّلنَّاسِ ۖ تَجْعَلُونَهُۥ قَرَاطِيسَ تُبْدُونَهَا وَتُخْفُونَ كَثِيرًا ۖ وَعُلِّمْتُم مَّا لَمْ تَعْلَمُوٓا۟ أَنتُمْ وَلَآ ءَابَآؤُكُمْ ۖ قُلِ ٱللَّهُ ۖ ثُمَّ ذَرْهُمْ فِى خَوْضِهِمْ يَلْعَبُونَ','Wa maa qadarul laaha haqqa qadriheee iz qaaloo maaa anzalal laahu \'alaa basharim min shai\'; qul man anzalal Kitaabal lazee jaaa\'a bihee Moosaa nooranw wa hudal linnaasi taj\'aloonahoo qaraateesa tubdoonahaa wa tukhfoona kaseeranw wa \'ullimtum maa lam ta\'lamooo antum wa laaa aabaaa\'ukum qulil laahu summa zarhum fee khawdihim yal\'aboon',91,'6:91',14,55,112,2,0,139,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(881,6,'وَهَـٰذَا كِتَـٰبٌ أَنزَلْنَـٰهُ مُبَارَكٌ مُّصَدِّقُ ٱلَّذِى بَيْنَ يَدَيْهِ وَلِتُنذِرَ أُمَّ ٱلْقُرَىٰ وَمَنْ حَوْلَهَا ۚ وَٱلَّذِينَ يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ يُؤْمِنُونَ بِهِۦ ۖ وَهُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ','Wa haazaa Kitaabun anzalnaahu Mubaarakum musaddiqul lazee bainaa yadaihi wa litunzira ummal Quraa wa man hawlahaa; wallazeena yu\'minoona bil Aakhirati yu\'minoona bihee wa hum\'alaa Salaatihim yuhaafizoon',92,'6:92',14,55,112,2,0,139,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(882,6,'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ قَالَ أُوحِىَ إِلَىَّ وَلَمْ يُوحَ إِلَيْهِ شَىْءٌ وَمَن قَالَ سَأُنزِلُ مِثْلَ مَآ أَنزَلَ ٱللَّهُ ۗ وَلَوْ تَرَىٰٓ إِذِ ٱلظَّـٰلِمُونَ فِى غَمَرَٰتِ ٱلْمَوْتِ وَٱلْمَلَـٰٓئِكَةُ بَاسِطُوٓا۟ أَيْدِيهِمْ أَخْرِجُوٓا۟ أَنفُسَكُمُ ۖ ٱلْيَوْمَ تُجْزَوْنَ عَذَابَ ٱلْهُونِ بِمَا كُنتُمْ تَقُولُونَ عَلَى ٱللَّهِ غَيْرَ ٱلْحَقِّ وَكُنتُمْ عَنْ ءَايَـٰتِهِۦ تَسْتَكْبِرُونَ','Wa man azlamu mimmanif taraa \'alal laahi kaziban aw qaala oohiya ilaiya wa lam yooha ilaihi shai\'un wa man qaala sa unzilu misla maaa anzalal laah; wa law taraaa iziz zaalimoona fee ghamaraatil mawti walmalaaa\'ikatu baasitooo aideehim akhrijooo anfusakum; al yawma tujzawna \'azaabal hooni bimaa kuntum taqooloona \'alal laahi ghairal haqqi wa kuntum \'an aayaatihee tastakbiroon',93,'6:93',14,55,112,2,0,139,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(883,6,'وَلَقَدْ جِئْتُمُونَا فُرَٰدَىٰ كَمَا خَلَقْنَـٰكُمْ أَوَّلَ مَرَّةٍ وَتَرَكْتُم مَّا خَوَّلْنَـٰكُمْ وَرَآءَ ظُهُورِكُمْ ۖ وَمَا نَرَىٰ مَعَكُمْ شُفَعَآءَكُمُ ٱلَّذِينَ زَعَمْتُمْ أَنَّهُمْ فِيكُمْ شُرَكَـٰٓؤُا۟ ۚ لَقَد تَّقَطَّعَ بَيْنَكُمْ وَضَلَّ عَنكُم مَّا كُنتُمْ تَزْعُمُونَ','Wa laqad ji\'tumoonaa furaadaa kamaa khalaqnaakum awwala marratinw wa taraktum maa khawwalnaakum waraaa\'a zuhoorikum wa maa naraa ma\'akum shufa\'aaa\' akumul lazeena za\'amtum annahum feekum shurakaaa\'; laqat taqatta\'a bainakum wa dalla \'annkum maa kuntum taz\'umoon',94,'6:94',14,55,112,2,0,139,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(884,6,'۞ إِنَّ ٱللَّهَ فَالِقُ ٱلْحَبِّ وَٱلنَّوَىٰ ۖ يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَمُخْرِجُ ٱلْمَيِّتِ مِنَ ٱلْحَىِّ ۚ ذَٰلِكُمُ ٱللَّهُ ۖ فَأَنَّىٰ تُؤْفَكُونَ','Innal laaha faaliqul habbi wannawaa yukhrijul haiya minal maiyiti wa mukhrijul maiyiti minal haiy; zaalikumul laahu fa annaa tu\'fakoon',95,'6:95',14,56,113,2,0,140,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(885,6,'فَالِقُ ٱلْإِصْبَاحِ وَجَعَلَ ٱلَّيْلَ سَكَنًا وَٱلشَّمْسَ وَٱلْقَمَرَ حُسْبَانًا ۚ ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ','Faaliqul isbaahi wa ja\'alal laila sakananw washh shamsa walqamara husbaanaa; zaalika taqdeerul \'Azeezil \'Aleem',96,'6:96',14,56,113,2,0,140,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(886,6,'وَهُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلنُّجُومَ لِتَهْتَدُوا۟ بِهَا فِى ظُلُمَـٰتِ ٱلْبَرِّ وَٱلْبَحْرِ ۗ قَدْ فَصَّلْنَا ٱلْـَٔايَـٰتِ لِقَوْمٍ يَعْلَمُونَ','Wa Huwal lazee ja\'ala lakumun nujooma litahtadoo bihaa fee zulumaatil barri walbahr; qad fassalnal Aayaati liqawminy ya\'lamoon',97,'6:97',14,56,113,2,0,140,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(887,6,'وَهُوَ ٱلَّذِىٓ أَنشَأَكُم مِّن نَّفْسٍ وَٰحِدَةٍ فَمُسْتَقَرٌّ وَمُسْتَوْدَعٌ ۗ قَدْ فَصَّلْنَا ٱلْـَٔايَـٰتِ لِقَوْمٍ يَفْقَهُونَ','Wa hhuwal lazeee ansha akum min nasinw waahidatin famustaqarrunw wa mustawda\'; qad fassalnal Aayaati liqaw miny-yafqahoon',98,'6:98',14,56,113,2,0,140,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(888,6,'وَهُوَ ٱلَّذِىٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجْنَا بِهِۦ نَبَاتَ كُلِّ شَىْءٍ فَأَخْرَجْنَا مِنْهُ خَضِرًا نُّخْرِجُ مِنْهُ حَبًّا مُّتَرَاكِبًا وَمِنَ ٱلنَّخْلِ مِن طَلْعِهَا قِنْوَانٌ دَانِيَةٌ وَجَنَّـٰتٍ مِّنْ أَعْنَابٍ وَٱلزَّيْتُونَ وَٱلرُّمَّانَ مُشْتَبِهًا وَغَيْرَ مُتَشَـٰبِهٍ ۗ ٱنظُرُوٓا۟ إِلَىٰ ثَمَرِهِۦٓ إِذَآ أَثْمَرَ وَيَنْعِهِۦٓ ۚ إِنَّ فِى ذَٰلِكُمْ لَـَٔايَـٰتٍ لِّقَوْمٍ يُؤْمِنُونَ','Wa Huwal lazeee anzala minas samaaa\'i maaa\'an fa akhrajnaa bihee nabaata kulli shai\'in fa akhrajnaa minhu khadiran nukhriju minhu habbam mutaraakibanw wa minan nakhli min tal\'ihaa qinwaanun daaniyatunw wa jannaatim min a\'naabinw wazzaitoona warrummaana mushhtabihanw wa ghaira mutashaabih; unzurooo ilaa samariheee izaaa asmars wa yan\'ih; inna fee zaalikum la Aayaatil liqawminy yu\'minoon',99,'6:99',14,56,113,2,0,140,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(889,6,'وَجَعَلُوا۟ لِلَّهِ شُرَكَآءَ ٱلْجِنَّ وَخَلَقَهُمْ ۖ وَخَرَقُوا۟ لَهُۥ بَنِينَ وَبَنَـٰتٍۭ بِغَيْرِ عِلْمٍ ۚ سُبْحَـٰنَهُۥ وَتَعَـٰلَىٰ عَمَّا يَصِفُونَ','Wa ja\'aloo lillaahi shurakaaa\'al jinna wa khalaqa hum wa kharaqoo lahoo baneena wa banaatim bighairi \'ilm Subhaanahoo wa Ta\'aalaa \'amma yasifoon',100,'6:100',14,56,113,2,0,140,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(890,6,'بَدِيعُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ أَنَّىٰ يَكُونُ لَهُۥ وَلَدٌ وَلَمْ تَكُن لَّهُۥ صَـٰحِبَةٌ ۖ وَخَلَقَ كُلَّ شَىْءٍ ۖ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ','Badee\'us samaawaati wal ardi annnaa yakoonu lahoo waladunw wa lam takul lahoo saahibatunw wa khalaqa kulla shai\'in \'Aleem',101,'6:101',14,56,114,2,0,140,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(891,6,'ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ ۖ لَآ إِلَـٰهَ إِلَّا هُوَ ۖ خَـٰلِقُ كُلِّ شَىْءٍ فَٱعْبُدُوهُ ۚ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ وَكِيلٌ','Zaalikumul laahu Rabbukum laaa ilaaha illaa huwa khaaliqu kulli shai\'in fa\'budooh; wa huwa \'alaa kulli shai\'inw Wakeel',102,'6:102',14,56,114,2,0,141,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(892,6,'لَّا تُدْرِكُهُ ٱلْأَبْصَـٰرُ وَهُوَ يُدْرِكُ ٱلْأَبْصَـٰرَ ۖ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ','Laa tudrikuhul absaaru wa Huwa yudrikul absaara wa huwal Lateeful Khabeer',103,'6:103',14,56,114,2,0,141,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(893,6,'قَدْ جَآءَكُم بَصَآئِرُ مِن رَّبِّكُمْ ۖ فَمَنْ أَبْصَرَ فَلِنَفْسِهِۦ ۖ وَمَنْ عَمِىَ فَعَلَيْهَا ۚ وَمَآ أَنَا۠ عَلَيْكُم بِحَفِيظٍ','Qad jaaa\'akum basaaa\'iru mir Rabbikum faman absara falinafsihee wa man \'amiya fa\'alaihaa; wa maaa ana \'alaikum bihafeez',104,'6:104',14,56,114,2,0,141,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(894,6,'وَكَذَٰلِكَ نُصَرِّفُ ٱلْـَٔايَـٰتِ وَلِيَقُولُوا۟ دَرَسْتَ وَلِنُبَيِّنَهُۥ لِقَوْمٍ يَعْلَمُونَ','Wa kazaalika nusarriful Aayaati wa liyaqooloo darasta wa linubaiyinahoo liqawminy ya\'lamoon',105,'6:105',14,56,114,2,0,141,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(895,6,'ٱتَّبِعْ مَآ أُوحِىَ إِلَيْكَ مِن رَّبِّكَ ۖ لَآ إِلَـٰهَ إِلَّا هُوَ ۖ وَأَعْرِضْ عَنِ ٱلْمُشْرِكِينَ','ittabi\' maaa oohiya ilaika mir Rabbika laaa ilaaha illaa Huwa wa a\'rid \'anil mushrikeen',106,'6:106',14,56,114,2,0,141,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(896,6,'وَلَوْ شَآءَ ٱللَّهُ مَآ أَشْرَكُوا۟ ۗ وَمَا جَعَلْنَـٰكَ عَلَيْهِمْ حَفِيظًا ۖ وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍ','Wa law shaaa\'al laahu maaa ashrakoo; wa maa ja\'alnaaka \'alaihim hafeezanw wa maaa anta \'alaihim biwakeel',107,'6:107',14,56,114,2,0,141,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(897,6,'وَلَا تَسُبُّوا۟ ٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ فَيَسُبُّوا۟ ٱللَّهَ عَدْوًۢا بِغَيْرِ عِلْمٍ ۗ كَذَٰلِكَ زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمْ ثُمَّ إِلَىٰ رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا۟ يَعْمَلُونَ','Wa laa tasubbul lazeena yad\'oona min doonil laahi fa yasubbul laaha \'adwam bighairi \'ilm; kazaalika zaiyannaa likulli ummatin \'amalahum summa ilaa Rabbihim marji\'uhum fa yunabbi\'uhum bimaa kaanooya\'maloon',108,'6:108',14,56,114,2,0,141,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(898,6,'وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَـٰنِهِمْ لَئِن جَآءَتْهُمْ ءَايَةٌ لَّيُؤْمِنُنَّ بِهَا ۚ قُلْ إِنَّمَا ٱلْـَٔايَـٰتُ عِندَ ٱللَّهِ ۖ وَمَا يُشْعِرُكُمْ أَنَّهَآ إِذَا جَآءَتْ لَا يُؤْمِنُونَ','Wa aqsamoo billaahi jahda aimaanihim la\'in jaaa\'at hum Aayatul la yu\'minunna bihaa; qul innamal Aayaatu \'indal laahi wa maa yush\'irukum annahaaa izaa jaaa\'at laa yu\'minoon',109,'6:109',14,56,114,2,0,141,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(899,6,'وَنُقَلِّبُ أَفْـِٔدَتَهُمْ وَأَبْصَـٰرَهُمْ كَمَا لَمْ يُؤْمِنُوا۟ بِهِۦٓ أَوَّلَ مَرَّةٍ وَنَذَرُهُمْ فِى طُغْيَـٰنِهِمْ يَعْمَهُونَ','Wa nuqallibu af\'idatahum wa absaarahum kamaa lam yu\'minoo biheee awwala marratinw wa wa nazaruhum fee tughyaanihim ya\'mahoon',110,'6:110',14,56,114,2,0,141,7,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(900,6,'۞ وَلَوْ أَنَّنَا نَزَّلْنَآ إِلَيْهِمُ ٱلْمَلَـٰٓئِكَةَ وَكَلَّمَهُمُ ٱلْمَوْتَىٰ وَحَشَرْنَا عَلَيْهِمْ كُلَّ شَىْءٍ قُبُلًا مَّا كَانُوا۟ لِيُؤْمِنُوٓا۟ إِلَّآ أَن يَشَآءَ ٱللَّهُ وَلَـٰكِنَّ أَكْثَرَهُمْ يَجْهَلُونَ','Wa law annanaa nazzal naaa ilaihimul malaaa\'ikata wa kallamahumul mawtaa wa hasharnaa \'alaihim kulla shai\'in qubulam maa kaanoo liyu\'minooo illaaa ai yashaaa\'al laahu wa laakinna aksarahum yajhaloon',111,'6:111',15,57,115,2,0,142,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(901,6,'وَكَذَٰلِكَ جَعَلْنَا لِكُلِّ نَبِىٍّ عَدُوًّا شَيَـٰطِينَ ٱلْإِنسِ وَٱلْجِنِّ يُوحِى بَعْضُهُمْ إِلَىٰ بَعْضٍ زُخْرُفَ ٱلْقَوْلِ غُرُورًا ۚ وَلَوْ شَآءَ رَبُّكَ مَا فَعَلُوهُ ۖ فَذَرْهُمْ وَمَا يَفْتَرُونَ','Wa kazaalika ja\'alnaa likulli nabiyyin \'aduwwan Shayaateenal insi waljinni yoohee ba\'duhum ilaa ba\'din zukhrufal qawli ghurooraa; wa law shaaa\'a Rabbuka maa fa\'aloohu fazarhum wa maa yaftaroon',112,'6:112',15,57,115,2,0,142,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(902,6,'وَلِتَصْغَىٰٓ إِلَيْهِ أَفْـِٔدَةُ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ وَلِيَرْضَوْهُ وَلِيَقْتَرِفُوا۟ مَا هُم مُّقْتَرِفُونَ','Wa litasghaaa ilaihi af\'idatul lazeena laa yu\'minoona bil Aakhirati wa liyardawhu wa liyaqtarifoo maa hum muqtarifoon',113,'6:113',15,57,115,2,0,142,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(903,6,'أَفَغَيْرَ ٱللَّهِ أَبْتَغِى حَكَمًا وَهُوَ ٱلَّذِىٓ أَنزَلَ إِلَيْكُمُ ٱلْكِتَـٰبَ مُفَصَّلًا ۚ وَٱلَّذِينَ ءَاتَيْنَـٰهُمُ ٱلْكِتَـٰبَ يَعْلَمُونَ أَنَّهُۥ مُنَزَّلٌ مِّن رَّبِّكَ بِٱلْحَقِّ ۖ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ','Afaghairal laahi abtaghee hakamanw wa Huwal lazee anzala ilaikumul Kitaaba mufassalaa; wallazeena atai naahumul Kitaaba ya\'lamoona annahoo munazzalum mir Rabbika bilhaqqi falaa takoonanna minal mumtareen',114,'6:114',15,57,115,2,0,142,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(904,6,'وَتَمَّتْ كَلِمَتُ رَبِّكَ صِدْقًا وَعَدْلًا ۚ لَّا مُبَدِّلَ لِكَلِمَـٰتِهِۦ ۚ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ','Wa tammat Kalimatu Rabbika sidqanw wa \'adlaa; laa mubaddila li Kalimaatih; wa Huwas Samee\'ul \'Aleem',115,'6:115',15,57,115,2,0,142,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(905,6,'وَإِن تُطِعْ أَكْثَرَ مَن فِى ٱلْأَرْضِ يُضِلُّوكَ عَن سَبِيلِ ٱللَّهِ ۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ','Wa in tuti\' aksara man fil ardi yudillooka \'an sabeelil laah; iny yattabi\'oona illaz zanna wa in hum illaa yakhrusoon',116,'6:116',15,57,115,2,0,142,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(906,6,'إِنَّ رَبَّكَ هُوَ أَعْلَمُ مَن يَضِلُّ عَن سَبِيلِهِۦ ۖ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ','Inna rabbaka Huwa a\'lamu mai yadillu \'an sabeelihee wa Huwa a\'lamu bilmuhtadeen',117,'6:117',15,57,115,2,0,142,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(907,6,'فَكُلُوا۟ مِمَّا ذُكِرَ ٱسْمُ ٱللَّهِ عَلَيْهِ إِن كُنتُم بِـَٔايَـٰتِهِۦ مُؤْمِنِينَ','Fakuloo mimmmaa zukirasmul laahi \'alaihi in kuntum bi Aayaatihee mu\'mineen',118,'6:118',15,57,115,2,0,142,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(908,6,'وَمَا لَكُمْ أَلَّا تَأْكُلُوا۟ مِمَّا ذُكِرَ ٱسْمُ ٱللَّهِ عَلَيْهِ وَقَدْ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَيْكُمْ إِلَّا مَا ٱضْطُرِرْتُمْ إِلَيْهِ ۗ وَإِنَّ كَثِيرًا لَّيُضِلُّونَ بِأَهْوَآئِهِم بِغَيْرِ عِلْمٍ ۗ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِٱلْمُعْتَدِينَ','Wa maa lakum allaa taakuloo mimmaa zukirasmul laahi \'alaihi wa qad fassala lakum maa harrama \'alaikum illaa mad turirtum ilaih; wa inna kaseeral la yudilloona bi ahwaaa\'ihim bighairi \'ilm; inna Rabbaka Huwa a\'lamu bilmu\'tadeen',119,'6:119',15,57,115,2,0,143,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(909,6,'وَذَرُوا۟ ظَـٰهِرَ ٱلْإِثْمِ وَبَاطِنَهُۥٓ ۚ إِنَّ ٱلَّذِينَ يَكْسِبُونَ ٱلْإِثْمَ سَيُجْزَوْنَ بِمَا كَانُوا۟ يَقْتَرِفُونَ','Wa zaroo zaahiral ismi wa baatinah; innal lazeena yaksiboonal ismaa sa yujzawna bimaa kaanoo yaqtarifoon',120,'6:120',15,57,115,2,0,143,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(910,6,'وَلَا تَأْكُلُوا۟ مِمَّا لَمْ يُذْكَرِ ٱسْمُ ٱللَّهِ عَلَيْهِ وَإِنَّهُۥ لَفِسْقٌ ۗ وَإِنَّ ٱلشَّيَـٰطِينَ لَيُوحُونَ إِلَىٰٓ أَوْلِيَآئِهِمْ لِيُجَـٰدِلُوكُمْ ۖ وَإِنْ أَطَعْتُمُوهُمْ إِنَّكُمْ لَمُشْرِكُونَ','Wa laa taakuloo mimaa lam yuzkaris mullaahi \'alaihi wa innahoo lafisq; wa innash Shayaateena la yoohoona ilaaa awliyaaa\'ihim liyujaadilookum wa in ata\'tumoohum innnakum lamushrikoon',121,'6:121',15,57,115,2,0,143,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(911,6,'أَوَمَن كَانَ مَيْتًا فَأَحْيَيْنَـٰهُ وَجَعَلْنَا لَهُۥ نُورًا يَمْشِى بِهِۦ فِى ٱلنَّاسِ كَمَن مَّثَلُهُۥ فِى ٱلظُّلُمَـٰتِ لَيْسَ بِخَارِجٍ مِّنْهَا ۚ كَذَٰلِكَ زُيِّنَ لِلْكَـٰفِرِينَ مَا كَانُوا۟ يَعْمَلُونَ','Awa man kaana maitan fa ahyainaahu wa ja\'alnaa lahoo noorany yamshee bihee fin naasi kamamm masaluhoo fiz zulumaati laisa bikhaarijim minhaa; kazaalika zuyyina lilkaafireena maa kaanoo ya\'maloon',122,'6:122',15,57,116,2,0,143,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(912,6,'وَكَذَٰلِكَ جَعَلْنَا فِى كُلِّ قَرْيَةٍ أَكَـٰبِرَ مُجْرِمِيهَا لِيَمْكُرُوا۟ فِيهَا ۖ وَمَا يَمْكُرُونَ إِلَّا بِأَنفُسِهِمْ وَمَا يَشْعُرُونَ','Wa kazaalika ja\'alnaa fee kulli qaryatin akaabira mujrimeehaa liyamkuroo feehaa wa maa yamkuroona illaa bi anfusihim wa maa yash\'uroon',123,'6:123',15,57,116,2,0,143,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(913,6,'وَإِذَا جَآءَتْهُمْ ءَايَةٌ قَالُوا۟ لَن نُّؤْمِنَ حَتَّىٰ نُؤْتَىٰ مِثْلَ مَآ أُوتِىَ رُسُلُ ٱللَّهِ ۘ ٱللَّهُ أَعْلَمُ حَيْثُ يَجْعَلُ رِسَالَتَهُۥ ۗ سَيُصِيبُ ٱلَّذِينَ أَجْرَمُوا۟ صَغَارٌ عِندَ ٱللَّهِ وَعَذَابٌ شَدِيدٌۢ بِمَا كَانُوا۟ يَمْكُرُونَ','Wa izaa jaaa\'athum Aayatun qaaloo lan nu\'mina hatta nu\'taa misla maaa ootiya Rusulul laah; Allahu a\'almu haisu yaj\'alu Risaalatah; sa yuseebul lazeena ajramoo saghaarun \'indal laahi wa \'azaabun shadeedum bimaa kaanoo yamkuroon',124,'6:124',15,57,116,2,0,143,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(914,6,'فَمَن يُرِدِ ٱللَّهُ أَن يَهْدِيَهُۥ يَشْرَحْ صَدْرَهُۥ لِلْإِسْلَـٰمِ ۖ وَمَن يُرِدْ أَن يُضِلَّهُۥ يَجْعَلْ صَدْرَهُۥ ضَيِّقًا حَرَجًا كَأَنَّمَا يَصَّعَّدُ فِى ٱلسَّمَآءِ ۚ كَذَٰلِكَ يَجْعَلُ ٱللَّهُ ٱلرِّجْسَ عَلَى ٱلَّذِينَ لَا يُؤْمِنُونَ','Famai yuridil laahu ai yahdiyahoo yashrah sadrahoo lil islaami wa mai yurid ai yudillaho yaj\'al sadrahoo daiyiqan harajan ka annamaa yassa\' \'adu fis samaaa\'; kazaalika yaj\'alul laahur rijsa \'alal lazeena la yu\'minoon',125,'6:125',15,57,116,2,0,144,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(915,6,'وَهَـٰذَا صِرَٰطُ رَبِّكَ مُسْتَقِيمًا ۗ قَدْ فَصَّلْنَا ٱلْـَٔايَـٰتِ لِقَوْمٍ يَذَّكَّرُونَ','Wa haazaa siraatu Rabbika Mustaqeemaa; qad fassalnal Aayaati liqawminy yazzakkaroon',126,'6:126',15,57,116,2,0,144,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(916,6,'۞ لَهُمْ دَارُ ٱلسَّلَـٰمِ عِندَ رَبِّهِمْ ۖ وَهُوَ وَلِيُّهُم بِمَا كَانُوا۟ يَعْمَلُونَ','Lahum daarus salaami \'inda Rabbihim wa huwa waliyyuhum bimaa kaanoo ya\'maloon',127,'6:127',15,58,116,2,0,144,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(917,6,'وَيَوْمَ يَحْشُرُهُمْ جَمِيعًا يَـٰمَعْشَرَ ٱلْجِنِّ قَدِ ٱسْتَكْثَرْتُم مِّنَ ٱلْإِنسِ ۖ وَقَالَ أَوْلِيَآؤُهُم مِّنَ ٱلْإِنسِ رَبَّنَا ٱسْتَمْتَعَ بَعْضُنَا بِبَعْضٍ وَبَلَغْنَآ أَجَلَنَا ٱلَّذِىٓ أَجَّلْتَ لَنَا ۚ قَالَ ٱلنَّارُ مَثْوَىٰكُمْ خَـٰلِدِينَ فِيهَآ إِلَّا مَا شَآءَ ٱللَّهُ ۗ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ','Wa yamwa yahshuruhum jamee\'ai yaa ma\'sharal jinni qadistaksartum minal insi wa qaala awliyaaa\'uhy minal insi Rabbanas tamta\'a ba\'dunaa biba\'dinw wa balaghnaaa ajalannal lazeee ajjalta lanaa; qaalan Naaru maswaakum khaalideena feehaaa illaa maa shaaa\'allaah; inna Rabbaka Hakeemun \'Aleem',128,'6:128',15,58,116,2,0,144,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(918,6,'وَكَذَٰلِكَ نُوَلِّى بَعْضَ ٱلظَّـٰلِمِينَ بَعْضًۢا بِمَا كَانُوا۟ يَكْسِبُونَ','Wa kazaalika nuwallee ba\'daz zaalimeena ba\'dam bimaa kaanoo yaksiboon',129,'6:129',15,58,116,2,0,144,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(919,6,'يَـٰمَعْشَرَ ٱلْجِنِّ وَٱلْإِنسِ أَلَمْ يَأْتِكُمْ رُسُلٌ مِّنكُمْ يَقُصُّونَ عَلَيْكُمْ ءَايَـٰتِى وَيُنذِرُونَكُمْ لِقَآءَ يَوْمِكُمْ هَـٰذَا ۚ قَالُوا۟ شَهِدْنَا عَلَىٰٓ أَنفُسِنَا ۖ وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَشَهِدُوا۟ عَلَىٰٓ أَنفُسِهِمْ أَنَّهُمْ كَانُوا۟ كَـٰفِرِينَ','Yaa ma\'sharal jinni wal insi alam yaatikum Rusulum minkum yaqussoona \'alaikum Aayaatee wa yunziroonakum liqaaa\'a Yawmikum haazaa; qaaloo shahidnaa \'alaaa anfusinaa wa gharrat humul hayaatud dunyaa wa shahidooo \'alaa anfusihim annahum kaanoo kaafireen',130,'6:130',15,58,117,2,0,144,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(920,6,'ذَٰلِكَ أَن لَّمْ يَكُن رَّبُّكَ مُهْلِكَ ٱلْقُرَىٰ بِظُلْمٍ وَأَهْلُهَا غَـٰفِلُونَ','Zaalika al lam yakkur Rabbuka muhlikal quraa bizulminw wa ahluhaa ghaafiloon',131,'6:131',15,58,117,2,0,144,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(921,6,'وَلِكُلٍّ دَرَجَـٰتٌ مِّمَّا عَمِلُوا۟ ۚ وَمَا رَبُّكَ بِغَـٰفِلٍ عَمَّا يَعْمَلُونَ','Wa likullin darajaatum mimmaa \'amiloo; wa maa Rabbuka bighaafilin \'ammaa ya\'maloon',132,'6:132',15,58,117,2,0,145,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(922,6,'وَرَبُّكَ ٱلْغَنِىُّ ذُو ٱلرَّحْمَةِ ۚ إِن يَشَأْ يُذْهِبْكُمْ وَيَسْتَخْلِفْ مِنۢ بَعْدِكُم مَّا يَشَآءُ كَمَآ أَنشَأَكُم مِّن ذُرِّيَّةِ قَوْمٍ ءَاخَرِينَ','Wa Rabbukal ghaniyyu zur rahmah; iny yashaaa yuz hibkum wa yastakhlif mim ba\'dikum wa yastakhlif mim ba\'dikum maa yashaaa\'u kamaaa ansha akum min zurriyyati qawmin aakhareen',133,'6:133',15,58,117,2,0,145,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(923,6,'إِنَّ مَا تُوعَدُونَ لَـَٔاتٍ ۖ وَمَآ أَنتُم بِمُعْجِزِينَ','Inna maa too\'adoona la aatinw wa maaa antum bimu\'jizeen',134,'6:134',15,58,117,2,0,145,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(924,6,'قُلْ يَـٰقَوْمِ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنِّى عَامِلٌ ۖ فَسَوْفَ تَعْلَمُونَ مَن تَكُونُ لَهُۥ عَـٰقِبَةُ ٱلدَّارِ ۗ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّـٰلِمُونَ','Qul yaa qawmi\' maloo \'alaa makaanatikum innee \'aamilun fasawfa ta\'lamoona man takoonu lahoo \'aaqibatud daar; innahoo laa yuflihuz zaalimoon',135,'6:135',15,58,117,2,0,145,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(925,6,'وَجَعَلُوا۟ لِلَّهِ مِمَّا ذَرَأَ مِنَ ٱلْحَرْثِ وَٱلْأَنْعَـٰمِ نَصِيبًا فَقَالُوا۟ هَـٰذَا لِلَّهِ بِزَعْمِهِمْ وَهَـٰذَا لِشُرَكَآئِنَا ۖ فَمَا كَانَ لِشُرَكَآئِهِمْ فَلَا يَصِلُ إِلَى ٱللَّهِ ۖ وَمَا كَانَ لِلَّهِ فَهُوَ يَصِلُ إِلَىٰ شُرَكَآئِهِمْ ۗ سَآءَ مَا يَحْكُمُونَ','Wa ja\'aloo lillaahi mimmaa zara-a minal harsi walan\'aami naseeban faqaaloo haazaa lillaahi biza\'mihim wa haaza lishurakaa\'inaa famaa kaana lishurakaaa\'ihim falaa yasilu ilal laahi wa maa kaana lillaahi fahuwa yasilu ilaa shurakaaa\'ihim; saaa\'a maa yahkumoon',136,'6:136',15,58,117,2,0,145,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(926,6,'وَكَذَٰلِكَ زَيَّنَ لِكَثِيرٍ مِّنَ ٱلْمُشْرِكِينَ قَتْلَ أَوْلَـٰدِهِمْ شُرَكَآؤُهُمْ لِيُرْدُوهُمْ وَلِيَلْبِسُوا۟ عَلَيْهِمْ دِينَهُمْ ۖ وَلَوْ شَآءَ ٱللَّهُ مَا فَعَلُوهُ ۖ فَذَرْهُمْ وَمَا يَفْتَرُونَ','Wa kazaalika zaiyana likaseerim minal mushrikeena qatla awlaadihim shurakaaa\'uhum liyurdoohum wa liyalbisoo \'alaihim deenahum wa law shaaa\'al laahu maa fa\'aloohu fazarhum wa maa yaftaroon',137,'6:137',15,58,117,2,0,145,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(927,6,'وَقَالُوا۟ هَـٰذِهِۦٓ أَنْعَـٰمٌ وَحَرْثٌ حِجْرٌ لَّا يَطْعَمُهَآ إِلَّا مَن نَّشَآءُ بِزَعْمِهِمْ وَأَنْعَـٰمٌ حُرِّمَتْ ظُهُورُهَا وَأَنْعَـٰمٌ لَّا يَذْكُرُونَ ٱسْمَ ٱللَّهِ عَلَيْهَا ٱفْتِرَآءً عَلَيْهِ ۚ سَيَجْزِيهِم بِمَا كَانُوا۟ يَفْتَرُونَ','Wa qaaloo haaziheee an\'aamunw wa harsun hijrun laa yat\'amuhaaa illaa man nashaaa\'u biza\'mihim wa an\'aamun hurrimat zuhooruhaa wa an\'aamul laa yazkuroonas mal laahi \'alaihaf tiraaa\'an \'alaih; sa yajzeehim bimaa kaanoo yaftaroon',138,'6:138',15,58,117,2,0,146,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(928,6,'وَقَالُوا۟ مَا فِى بُطُونِ هَـٰذِهِ ٱلْأَنْعَـٰمِ خَالِصَةٌ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰٓ أَزْوَٰجِنَا ۖ وَإِن يَكُن مَّيْتَةً فَهُمْ فِيهِ شُرَكَآءُ ۚ سَيَجْزِيهِمْ وَصْفَهُمْ ۚ إِنَّهُۥ حَكِيمٌ عَلِيمٌ','Wa qaaloo maa fee butooni haazihil an\'aami khaalisatul lizukoorinaa wa muharramun \'alaaa azwaajinaa wa iny yakum maitatan fahum feehi shurakaaa\'; sa yajzeehim wasfahum; innahoo Hakeemun \'Aleem',139,'6:139',15,58,117,2,0,146,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(929,6,'قَدْ خَسِرَ ٱلَّذِينَ قَتَلُوٓا۟ أَوْلَـٰدَهُمْ سَفَهًۢا بِغَيْرِ عِلْمٍ وَحَرَّمُوا۟ مَا رَزَقَهُمُ ٱللَّهُ ٱفْتِرَآءً عَلَى ٱللَّهِ ۚ قَدْ ضَلُّوا۟ وَمَا كَانُوا۟ مُهْتَدِينَ','Qad khasiral lazeena qatalooo awlaadahum safaham bighairi \'ilminw wa harramoo maa razaqahumul laahuf tiraaa\'an \'alal laah; qad dalloo wa maa kaanoo muhtadeen',140,'6:140',15,58,117,2,0,146,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(930,6,'۞ وَهُوَ ٱلَّذِىٓ أَنشَأَ جَنَّـٰتٍ مَّعْرُوشَـٰتٍ وَغَيْرَ مَعْرُوشَـٰتٍ وَٱلنَّخْلَ وَٱلزَّرْعَ مُخْتَلِفًا أُكُلُهُۥ وَٱلزَّيْتُونَ وَٱلرُّمَّانَ مُتَشَـٰبِهًا وَغَيْرَ مُتَشَـٰبِهٍ ۚ كُلُوا۟ مِن ثَمَرِهِۦٓ إِذَآ أَثْمَرَ وَءَاتُوا۟ حَقَّهُۥ يَوْمَ حَصَادِهِۦ ۖ وَلَا تُسْرِفُوٓا۟ ۚ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْرِفِينَ','Wa Huwal lazee ansha-a jannaatim ma\'rooshaatinw wa ghaira ma\'rooshaatinw wan nakhla wazzar\'a mukhtalifan ukuluhoo wazzaitoona warrum maana mutashaabihanw wa ghaira mutashaabih; kuloo min samariheee izaaa asmara wa aatoo haqqahoo yawma hasaadihee wa laa tusrifoo; innahoo laa yuhibbul musrifeen',141,'6:141',15,59,118,2,0,146,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(931,6,'وَمِنَ ٱلْأَنْعَـٰمِ حَمُولَةً وَفَرْشًا ۚ كُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَـٰنِ ۚ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ','Wa minal an\'aami hamoolatanw wa farshaa; kuloo mimmaa razaqakumul laahu wa laa tattabi\'oo khutuwaatish Shaitaan; innahoo lakum \'aduwwum mubeen',142,'6:142',15,59,118,2,0,146,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(932,6,'ثَمَـٰنِيَةَ أَزْوَٰجٍ ۖ مِّنَ ٱلضَّأْنِ ٱثْنَيْنِ وَمِنَ ٱلْمَعْزِ ٱثْنَيْنِ ۗ قُلْ ءَآلذَّكَرَيْنِ حَرَّمَ أَمِ ٱلْأُنثَيَيْنِ أَمَّا ٱشْتَمَلَتْ عَلَيْهِ أَرْحَامُ ٱلْأُنثَيَيْنِ ۖ نَبِّـُٔونِى بِعِلْمٍ إِن كُنتُمْ صَـٰدِقِينَ','Samaaniyata azwaaj minad daanis naini wa minal ma\'zis nain; qul \'aazzaka raini harrama amil unsaiyayni ammash tamalat \'alaihi arhaamul unsayaini nabbi \'oonee bi\'ilmin in kuntum saadiqeen',143,'6:143',15,59,118,2,0,147,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(933,6,'وَمِنَ ٱلْإِبِلِ ٱثْنَيْنِ وَمِنَ ٱلْبَقَرِ ٱثْنَيْنِ ۗ قُلْ ءَآلذَّكَرَيْنِ حَرَّمَ أَمِ ٱلْأُنثَيَيْنِ أَمَّا ٱشْتَمَلَتْ عَلَيْهِ أَرْحَامُ ٱلْأُنثَيَيْنِ ۖ أَمْ كُنتُمْ شُهَدَآءَ إِذْ وَصَّىٰكُمُ ٱللَّهُ بِهَـٰذَا ۚ فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا لِّيُضِلَّ ٱلنَّاسَ بِغَيْرِ عِلْمٍ ۗ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ','Wa minal ibilis naini wa minal baqaris nain; qul \'aaazzakaraini harrama amil unsayaini ammash tamalat \'alaihi arhaamul unsayaini am kuntum shuhadaaa\'a iz wassaakumul laahu bihaazaa; faman azlamu mimmanif taraa \'alal laahi kazibal liyuddillan naasa bighari \'ilm; innal laaha laa yahdil qawmaz zaalimeen',144,'6:144',15,59,118,2,0,147,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(934,6,'قُل لَّآ أَجِدُ فِى مَآ أُوحِىَ إِلَىَّ مُحَرَّمًا عَلَىٰ طَاعِمٍ يَطْعَمُهُۥٓ إِلَّآ أَن يَكُونَ مَيْتَةً أَوْ دَمًا مَّسْفُوحًا أَوْ لَحْمَ خِنزِيرٍ فَإِنَّهُۥ رِجْسٌ أَوْ فِسْقًا أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ ۚ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ رَبَّكَ غَفُورٌ رَّحِيمٌ','Qul laaa ajidu fee maaa oohiya ilaiya muharraman \'alaa taa\'iminy yat\'amuhooo illaaa ai yakoona maitatan aw damam masfoohan aw lahma khinzeerin fa innahoo rijsun aw fisqan uhilla lighairil laahi bih; famanid turra ghaira baa ghinw wa laa \'aadin fa inna Rabbaka Ghafoorur Raheem',145,'6:145',15,59,119,2,0,147,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(935,6,'وَعَلَى ٱلَّذِينَ هَادُوا۟ حَرَّمْنَا كُلَّ ذِى ظُفُرٍ ۖ وَمِنَ ٱلْبَقَرِ وَٱلْغَنَمِ حَرَّمْنَا عَلَيْهِمْ شُحُومَهُمَآ إِلَّا مَا حَمَلَتْ ظُهُورُهُمَآ أَوِ ٱلْحَوَايَآ أَوْ مَا ٱخْتَلَطَ بِعَظْمٍ ۚ ذَٰلِكَ جَزَيْنَـٰهُم بِبَغْيِهِمْ ۖ وَإِنَّا لَصَـٰدِقُونَ','Wa \'alal lazeena haadoo harramnaa kulla zee zufurinw wa minal baqari walghanami harramnaa \'alihim shuh oomahumaaa illaa maa hamalat zuhooruhumaaa awil hawaayaaa aw makhtalata bi\'azm zaalika jazainaahum bibaghyihim wa innaa lasaa diqoon',146,'6:146',15,59,119,2,0,147,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(936,6,'فَإِن كَذَّبُوكَ فَقُل رَّبُّكُمْ ذُو رَحْمَةٍ وَٰسِعَةٍ وَلَا يُرَدُّ بَأْسُهُۥ عَنِ ٱلْقَوْمِ ٱلْمُجْرِمِينَ','Fa in kazzabooka faqur Rabbukum zoo rahmatinw waasi\'atinw waasi\'atinw wa laa yuraddu baasuhoo \'anil qawmil mujrimeen',147,'6:147',15,59,119,2,0,148,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(937,6,'سَيَقُولُ ٱلَّذِينَ أَشْرَكُوا۟ لَوْ شَآءَ ٱللَّهُ مَآ أَشْرَكْنَا وَلَآ ءَابَآؤُنَا وَلَا حَرَّمْنَا مِن شَىْءٍ ۚ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ حَتَّىٰ ذَاقُوا۟ بَأْسَنَا ۗ قُلْ هَلْ عِندَكُم مِّنْ عِلْمٍ فَتُخْرِجُوهُ لَنَآ ۖ إِن تَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ أَنتُمْ إِلَّا تَخْرُصُونَ','Sayaqoolul lazeena ashrakoo law shaaa\'al laahu maaa ashraknaa wa laaa aabaa\'unaa wa laa harramnaa min shai\'; kazaalika kazzabal lazeena min qablihim hattaa zaaqoo baasanaa; qul hal \'indakum min \'ilmin fatukh rijoohu lanaa in tattabi\'oona illaz zanna wa in antum illaa takhhrusoon',148,'6:148',15,59,119,2,0,148,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(938,6,'قُلْ فَلِلَّهِ ٱلْحُجَّةُ ٱلْبَـٰلِغَةُ ۖ فَلَوْ شَآءَ لَهَدَىٰكُمْ أَجْمَعِينَ','Qul falillaahil hujjatul baalighatu falaw shaaa\'a lahadaakum ajma\'een',149,'6:149',15,59,119,2,0,148,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(939,6,'قُلْ هَلُمَّ شُهَدَآءَكُمُ ٱلَّذِينَ يَشْهَدُونَ أَنَّ ٱللَّهَ حَرَّمَ هَـٰذَا ۖ فَإِن شَهِدُوا۟ فَلَا تَشْهَدْ مَعَهُمْ ۚ وَلَا تَتَّبِعْ أَهْوَآءَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا وَٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ وَهُم بِرَبِّهِمْ يَعْدِلُونَ','Qul halumma shuhadaaa\'akumul lazeena yash hadoona annal laaha harrama haazaa fa in shahidoo falaa tashhad ma\'ahum; wa laa tattabi\' ahwaaa\'al lazeena kazzaboo bi Aayaatinaa wallazeena laa yu\'minoona bil Aakhirati wa hum bi Rabbihim ya\'diloon',150,'6:150',15,59,119,2,0,148,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(940,6,'۞ قُلْ تَعَالَوْا۟ أَتْلُ مَا حَرَّمَ رَبُّكُمْ عَلَيْكُمْ ۖ أَلَّا تُشْرِكُوا۟ بِهِۦ شَيْـًٔا ۖ وَبِٱلْوَٰلِدَيْنِ إِحْسَـٰنًا ۖ وَلَا تَقْتُلُوٓا۟ أَوْلَـٰدَكُم مِّنْ إِمْلَـٰقٍ ۖ نَّحْنُ نَرْزُقُكُمْ وَإِيَّاهُمْ ۖ وَلَا تَقْرَبُوا۟ ٱلْفَوَٰحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ ۖ وَلَا تَقْتُلُوا۟ ٱلنَّفْسَ ٱلَّتِى حَرَّمَ ٱللَّهُ إِلَّا بِٱلْحَقِّ ۚ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَعْقِلُونَ','Qul ta\'aalaw atlu maa harrama Rabbukum \'alaikum allaa tushrikoo bihee shai\'anw wa bilwaalidaini ihsaananw wa laa taqtulooo aw alaadakum min imlaaq; nahnu narzuqukum wa iyyaahum wa laa taqrabul fawaahisha maa zahara minhaa wa maa batana wa laa taqtulun nafsal latee harramal laahu illaa bilhaqq; zaalikum wassaakum bihee la\'allakum ta\'qiloon',151,'6:151',15,60,120,2,0,148,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(941,6,'وَلَا تَقْرَبُوا۟ مَالَ ٱلْيَتِيمِ إِلَّا بِٱلَّتِى هِىَ أَحْسَنُ حَتَّىٰ يَبْلُغَ أَشُدَّهُۥ ۖ وَأَوْفُوا۟ ٱلْكَيْلَ وَٱلْمِيزَانَ بِٱلْقِسْطِ ۖ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا ۖ وَإِذَا قُلْتُمْ فَٱعْدِلُوا۟ وَلَوْ كَانَ ذَا قُرْبَىٰ ۖ وَبِعَهْدِ ٱللَّهِ أَوْفُوا۟ ۚ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَذَكَّرُونَ','Wa laa taqraboo maalal yateemi illaa billatee hiyaa ahsanu hattaa yablugha ashuddahoo wa awful kaila walmeezaana bilqisti laa nukallifu nafsan illaa wus\'ahaa wa izaa qultum fa\'diloo wa law kaana zaa qurbaa wa bi \'ahdil laahi awfoo; zaalikum wassaakum bihee la\'allakum tazakkarron',152,'6:152',15,60,120,2,0,149,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(942,6,'وَأَنَّ هَـٰذَا صِرَٰطِى مُسْتَقِيمًا فَٱتَّبِعُوهُ ۖ وَلَا تَتَّبِعُوا۟ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمْ عَن سَبِيلِهِۦ ۚ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَتَّقُونَ','Wa annna haazaa Siraatee mustaqeeman fattabi\'oohu wa laa tattabi\'us subula fatafarraqa bikum \'an sabeelih; zaalikum wassaakum bihee la\'allakum tattaqoon',153,'6:153',15,60,120,2,0,149,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(943,6,'ثُمَّ ءَاتَيْنَا مُوسَى ٱلْكِتَـٰبَ تَمَامًا عَلَى ٱلَّذِىٓ أَحْسَنَ وَتَفْصِيلًا لِّكُلِّ شَىْءٍ وَهُدًى وَرَحْمَةً لَّعَلَّهُم بِلِقَآءِ رَبِّهِمْ يُؤْمِنُونَ','Summa aatainaa Moosal Kitaaba tammaaman \'alal lazeee ahsana wa tafseelal likulli shai\'inw wa hudanw wa rahmatal la\'allahum biliqaaa\'i Rabbihim yu\'minoon',154,'6:154',15,60,120,2,0,149,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(944,6,'وَهَـٰذَا كِتَـٰبٌ أَنزَلْنَـٰهُ مُبَارَكٌ فَٱتَّبِعُوهُ وَٱتَّقُوا۟ لَعَلَّكُمْ تُرْحَمُونَ','Wa haazaa Kitaabun anzalnaahu Mubaarakun fattabi\'oohu wattaqoo la\'al lakum urhamoon',155,'6:155',15,60,121,2,0,149,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(945,6,'أَن تَقُولُوٓا۟ إِنَّمَآ أُنزِلَ ٱلْكِتَـٰبُ عَلَىٰ طَآئِفَتَيْنِ مِن قَبْلِنَا وَإِن كُنَّا عَن دِرَاسَتِهِمْ لَغَـٰفِلِينَ','An taqooloo innammaaa unzilal Kitaabu \'alaa taaa\'ifataini min qablinaa wa in kunnaa \'an diraasatihim laghaafileen',156,'6:156',15,60,121,2,0,149,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(946,6,'أَوْ تَقُولُوا۟ لَوْ أَنَّآ أُنزِلَ عَلَيْنَا ٱلْكِتَـٰبُ لَكُنَّآ أَهْدَىٰ مِنْهُمْ ۚ فَقَدْ جَآءَكُم بَيِّنَةٌ مِّن رَّبِّكُمْ وَهُدًى وَرَحْمَةٌ ۚ فَمَنْ أَظْلَمُ مِمَّن كَذَّبَ بِـَٔايَـٰتِ ٱللَّهِ وَصَدَفَ عَنْهَا ۗ سَنَجْزِى ٱلَّذِينَ يَصْدِفُونَ عَنْ ءَايَـٰتِنَا سُوٓءَ ٱلْعَذَابِ بِمَا كَانُوا۟ يَصْدِفُونَ','Aw taqooloo law annaaa unzila \'alainal kitaabu lakunnaaa ahdaa minhum; faqad jaaa\'akum baiyinatum mir Rabbikum wa hudanw wa rahmah; faman azlamu mimman kazzaba bi Aayaatil laahi wa sadaf \'anhaa; sanajzil lazeena yasdifoona \'an Aayaatinaa sooo\'al \'azaabi bimaa kaanoo yasdifoon',157,'6:157',15,60,121,2,0,149,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(947,6,'هَلْ يَنظُرُونَ إِلَّآ أَن تَأْتِيَهُمُ ٱلْمَلَـٰٓئِكَةُ أَوْ يَأْتِىَ رَبُّكَ أَوْ يَأْتِىَ بَعْضُ ءَايَـٰتِ رَبِّكَ ۗ يَوْمَ يَأْتِى بَعْضُ ءَايَـٰتِ رَبِّكَ لَا يَنفَعُ نَفْسًا إِيمَـٰنُهَا لَمْ تَكُنْ ءَامَنَتْ مِن قَبْلُ أَوْ كَسَبَتْ فِىٓ إِيمَـٰنِهَا خَيْرًا ۗ قُلِ ٱنتَظِرُوٓا۟ إِنَّا مُنتَظِرُونَ','hal yanzuroona illaaa an taatiyahumul malaaa\'ikatu aw yaatiya Rabbuka aw yaatiya ba\'du Aayaati Rabbik; yawma yaatee ba\'du Aayaati Rabbika laa yanfa\'u nafsan eemaanuhaa lam takun aamanat min qablu aw kasabat feee eemaanihaa khairaa; qulin tazirooo innaa muntaziroon',158,'6:158',15,60,121,2,0,150,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(948,6,'إِنَّ ٱلَّذِينَ فَرَّقُوا۟ دِينَهُمْ وَكَانُوا۟ شِيَعًا لَّسْتَ مِنْهُمْ فِى شَىْءٍ ۚ إِنَّمَآ أَمْرُهُمْ إِلَى ٱللَّهِ ثُمَّ يُنَبِّئُهُم بِمَا كَانُوا۟ يَفْعَلُونَ','Innal lazeena farraqoo deenahum wa kaanoo shiya\'allasta minhum fee shai\'; innamaaa amruhum ilallaahi summma yunabbi\'uhum bimaa kaanoo yaf\'aloon',159,'6:159',15,60,121,2,0,150,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(949,6,'مَن جَآءَ بِٱلْحَسَنَةِ فَلَهُۥ عَشْرُ أَمْثَالِهَا ۖ وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجْزَىٰٓ إِلَّا مِثْلَهَا وَهُمْ لَا يُظْلَمُونَ','man jaaa\'a bilhasanati falahoo \'ashru amsaalihaa wa man jaaa\'a bissaiyi\'ati falaa yujzaaa illaa mislahaa wa hum laa yuzlamoon',160,'6:160',15,60,121,2,0,150,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(950,6,'قُلْ إِنَّنِى هَدَىٰنِى رَبِّىٓ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ دِينًا قِيَمًا مِّلَّةَ إِبْرَٰهِيمَ حَنِيفًا ۚ وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ','Qul innanee hadaanee Rabbeee ilaa Siraatim Mustaqeemin deenan qiyamam Millata Ibraaheema haneefaa; wa maa kaana minal mushrikeen',161,'6:161',15,60,121,2,0,150,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(951,6,'قُلْ إِنَّ صَلَاتِى وَنُسُكِى وَمَحْيَاىَ وَمَمَاتِى لِلَّهِ رَبِّ ٱلْعَـٰلَمِينَ','Qul inna Salaatee wa nusukee wa mahyaaya wa mamaatee lillaahi Rabbil \'aalameen',162,'6:162',15,60,121,2,0,150,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(952,6,'لَا شَرِيكَ لَهُۥ ۖ وَبِذَٰلِكَ أُمِرْتُ وَأَنَا۠ أَوَّلُ ٱلْمُسْلِمِينَ','Laa shareeka lahoo wa bizaalika umirtu wa ana awwalul muslimeen',163,'6:163',15,60,121,2,0,150,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(953,6,'قُلْ أَغَيْرَ ٱللَّهِ أَبْغِى رَبًّا وَهُوَ رَبُّ كُلِّ شَىْءٍ ۚ وَلَا تَكْسِبُ كُلُّ نَفْسٍ إِلَّا عَلَيْهَا ۚ وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ ۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرْجِعُكُمْ فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ','Qul aghairal laahi abhee Rabbanw wa Huwa Rabbu kulli shai\'; wa laa taksibu kullu nafsin illaa \'alaihaa; wa laa taziru waaziratunw wizra ukhraa; summa ilaa Rabbikum marji\'ukum fa yunabbi\'ukum bimaa kuntum feehi takhtalifoon',164,'6:164',15,60,121,2,0,150,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(954,6,'وَهُوَ ٱلَّذِى جَعَلَكُمْ خَلَـٰٓئِفَ ٱلْأَرْضِ وَرَفَعَ بَعْضَكُمْ فَوْقَ بَعْضٍ دَرَجَـٰتٍ لِّيَبْلُوَكُمْ فِى مَآ ءَاتَىٰكُمْ ۗ إِنَّ رَبَّكَ سَرِيعُ ٱلْعِقَابِ وَإِنَّهُۥ لَغَفُورٌ رَّحِيمٌۢ','Wa Huwal lazee ja\'alakum khalaaa\'ifal ardi wa rafa\'a ba\'dakum fawqa ba\'din darajaatil liyabluwakum fee maaa aataakum; inna Rabbaka saree\'ul \'iqaab; wa innahoo la Ghafoorur Raheem',165,'6:165',15,60,121,2,0,150,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(955,7,'الٓمٓصٓ','Alif-Laaam-Meeem-Saaad',1,'7:1',16,61,122,2,0,151,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(956,7,'كِتَـٰبٌ أُنزِلَ إِلَيْكَ فَلَا يَكُن فِى صَدْرِكَ حَرَجٌ مِّنْهُ لِتُنذِرَ بِهِۦ وَذِكْرَىٰ لِلْمُؤْمِنِينَ','Kitaabun unzila ilaika falaa yakum fee sadrika harajum minhu litunzira bihee wa zikraa lilmu\'mineen',2,'7:2',16,61,122,2,0,151,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(957,7,'ٱتَّبِعُوا۟ مَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُمْ وَلَا تَتَّبِعُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ ۗ قَلِيلًا مَّا تَذَكَّرُونَ','Ittabi\'oo maaa unzila \'ilaikum mir Rabbikum wa laa tattabi\'oo min dooniheee awliyaaa\'; qaleelam maa tazakkaroon',3,'7:3',16,61,122,2,0,151,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(958,7,'وَكَم مِّن قَرْيَةٍ أَهْلَكْنَـٰهَا فَجَآءَهَا بَأْسُنَا بَيَـٰتًا أَوْ هُمْ قَآئِلُونَ','Wa kam min qaryatin ahlaknaahaa fajaaa\'ahaa baasunaa bayaatan aw hum qaaa\'iloon',4,'7:4',16,61,122,2,0,151,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(959,7,'فَمَا كَانَ دَعْوَىٰهُمْ إِذْ جَآءَهُم بَأْسُنَآ إِلَّآ أَن قَالُوٓا۟ إِنَّا كُنَّا ظَـٰلِمِينَ','Famaa kaana da\'waahum iz jaaa\'ahum baasunaa illaaa an qaalooo innaa kunnaa zaalimeen',5,'7:5',16,61,122,2,0,151,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(960,7,'فَلَنَسْـَٔلَنَّ ٱلَّذِينَ أُرْسِلَ إِلَيْهِمْ وَلَنَسْـَٔلَنَّ ٱلْمُرْسَلِينَ','Falanas \'alannal lazeena ursila ilaihim wa lanas \'alannal mursaleen',6,'7:6',16,61,122,2,0,151,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(961,7,'فَلَنَقُصَّنَّ عَلَيْهِم بِعِلْمٍ ۖ وَمَا كُنَّا غَآئِبِينَ','Falanaqussanna \'alaihim bi\'ilminw wa maa kunnaa ghaaa\'ibeen',7,'7:7',16,61,122,2,0,151,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(962,7,'وَٱلْوَزْنُ يَوْمَئِذٍ ٱلْحَقُّ ۚ فَمَن ثَقُلَتْ مَوَٰزِينُهُۥ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ','Walwaznu Yawma\'izinil haqq; faman saqulat mawaa zeenuhoo fa-ulaaa\'ika humul muflihoon',8,'7:8',16,61,122,2,0,151,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(963,7,'وَمَنْ خَفَّتْ مَوَٰزِينُهُۥ فَأُو۟لَـٰٓئِكَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُم بِمَا كَانُوا۟ بِـَٔايَـٰتِنَا يَظْلِمُونَ','Wa man khaffat mawaazeenuhoo fa ulaaa\'ikal lazeena khasirooo anfusahum bimaa kaanoo bi Aayaatinaa yazlimoon',9,'7:9',16,61,122,2,0,151,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(964,7,'وَلَقَدْ مَكَّنَّـٰكُمْ فِى ٱلْأَرْضِ وَجَعَلْنَا لَكُمْ فِيهَا مَعَـٰيِشَ ۗ قَلِيلًا مَّا تَشْكُرُونَ','Wa laqad makkannaakum fil ardi wa ja\'alnaa lakum feehaa ma\'aayish; qaleelam maa tashkuroon',10,'7:10',16,61,122,2,0,151,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(965,7,'وَلَقَدْ خَلَقْنَـٰكُمْ ثُمَّ صَوَّرْنَـٰكُمْ ثُمَّ قُلْنَا لِلْمَلَـٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ لَمْ يَكُن مِّنَ ٱلسَّـٰجِدِينَ','Wa laqad khalaqnaakum summa sawwarnaakum summa qulnaa lilmalaaa\'ikatis judoo li Aadama fa-sajadooo illaaa Ibleesa lam yakum minas saajideen',11,'7:11',16,61,123,2,0,151,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(966,7,'قَالَ مَا مَنَعَكَ أَلَّا تَسْجُدَ إِذْ أَمَرْتُكَ ۖ قَالَ أَنَا۠ خَيْرٌ مِّنْهُ خَلَقْتَنِى مِن نَّارٍ وَخَلَقْتَهُۥ مِن طِينٍ','Qaala maa mana\'aka allaa tasjuda iz amartuka qaala ana khairum minhu khalaqtanee min naarinw wa khalaqtahoo min teen',12,'7:12',16,61,123,2,0,152,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(967,7,'قَالَ فَٱهْبِطْ مِنْهَا فَمَا يَكُونُ لَكَ أَن تَتَكَبَّرَ فِيهَا فَٱخْرُجْ إِنَّكَ مِنَ ٱلصَّـٰغِرِينَ','Qaala fahbit minhaa famaa yakoonu laka an tatakabbara feehaa fakhruj innaka minas saaghireen',13,'7:13',16,61,123,2,0,152,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(968,7,'قَالَ أَنظِرْنِىٓ إِلَىٰ يَوْمِ يُبْعَثُونَ','Qaala anzirneee ilaa Yawmi yub\'asoon',14,'7:14',16,61,123,2,0,152,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(969,7,'قَالَ إِنَّكَ مِنَ ٱلْمُنظَرِينَ','Qaala innaka minal munzareen',15,'7:15',16,61,123,2,0,152,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(970,7,'قَالَ فَبِمَآ أَغْوَيْتَنِى لَأَقْعُدَنَّ لَهُمْ صِرَٰطَكَ ٱلْمُسْتَقِيمَ','Qaala fabimaaa aghway tanee la aq\'udanna lahum Siraatakal Mustaqeem',16,'7:16',16,61,123,2,0,152,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(971,7,'ثُمَّ لَـَٔاتِيَنَّهُم مِّنۢ بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ وَعَنْ أَيْمَـٰنِهِمْ وَعَن شَمَآئِلِهِمْ ۖ وَلَا تَجِدُ أَكْثَرَهُمْ شَـٰكِرِينَ','Summa la aatiyannahum mim baine aideehim wa min khalfihim wa \'an aimaanihim wa \'an shamaaa\'ilihim wa laa tajidu aksarahum shaakireen',17,'7:17',16,61,123,2,0,152,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(972,7,'قَالَ ٱخْرُجْ مِنْهَا مَذْءُومًا مَّدْحُورًا ۖ لَّمَن تَبِعَكَ مِنْهُمْ لَأَمْلَأَنَّ جَهَنَّمَ مِنكُمْ أَجْمَعِينَ','Qaalakh ruj mnhaa maz\'oomam madhooraa; laman tabi\'aka minhum la amla\'anna Jahannama minkum ajma\'een',18,'7:18',16,61,123,2,0,152,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(973,7,'وَيَـٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ فَكُلَا مِنْ حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَـٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّـٰلِمِينَ','Wa yaaa Aadamus kun anta wa zawjukal Jannata fakulaa min haisu shi\'tumaa wa laa taqrabaa haazihish shajarata fatakoonaa minza zaalimeen',19,'7:19',16,61,123,2,0,152,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(974,7,'فَوَسْوَسَ لَهُمَا ٱلشَّيْطَـٰنُ لِيُبْدِىَ لَهُمَا مَا وُۥرِىَ عَنْهُمَا مِن سَوْءَٰتِهِمَا وَقَالَ مَا نَهَىٰكُمَا رَبُّكُمَا عَنْ هَـٰذِهِ ٱلشَّجَرَةِ إِلَّآ أَن تَكُونَا مَلَكَيْنِ أَوْ تَكُونَا مِنَ ٱلْخَـٰلِدِينَ','Fawaswasa lahumash Shaitaanu liyubdiya lahumaa maa wooriya \'anhumaa min saw aatihimaa wa qaala maa nahaakumaa Rabbukumaa \'an haazihish shajarati illaaa an takoonaa malakaini aw takoonaa minal khaalideen',20,'7:20',16,61,123,2,0,152,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(975,7,'وَقَاسَمَهُمَآ إِنِّى لَكُمَا لَمِنَ ٱلنَّـٰصِحِينَ','Wa qaasamahumaaa innee lakumaa laminan naasiheen',21,'7:21',16,61,123,2,0,152,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(976,7,'فَدَلَّىٰهُمَا بِغُرُورٍ ۚ فَلَمَّا ذَاقَا ٱلشَّجَرَةَ بَدَتْ لَهُمَا سَوْءَٰتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ ٱلْجَنَّةِ ۖ وَنَادَىٰهُمَا رَبُّهُمَآ أَلَمْ أَنْهَكُمَا عَن تِلْكُمَا ٱلشَّجَرَةِ وَأَقُل لَّكُمَآ إِنَّ ٱلشَّيْطَـٰنَ لَكُمَا عَدُوٌّ مُّبِينٌ','Fadallaahumaa bighuroor; falammaa zaaqash shajarata badat lahumaa saw aatuhumaa wa tafiqaa yakhsifaani \'alaihimaa minw waraqil jannati wa naadaahumaa Rabbuhumaaa alam anhakumaa \'an tilkumash shajarati wa aqul lakumaaa innash Shaitaana lakumaa \'aduwwum mubeen',22,'7:22',16,61,123,2,0,152,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(977,7,'قَالَا رَبَّنَا ظَلَمْنَآ أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ ٱلْخَـٰسِرِينَ','Qaalaa Rabbanaa zalamnaaa anfusanaa wa illam taghfir lanaa wa tarhamnaa lanakoonanna minal khaasireen',23,'7:23',16,61,123,2,0,153,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(978,7,'قَالَ ٱهْبِطُوا۟ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ ۖ وَلَكُمْ فِى ٱلْأَرْضِ مُسْتَقَرٌّ وَمَتَـٰعٌ إِلَىٰ حِينٍ','Qaalah bitoo ba\'dukum liba\'din aduwwunw wa lakum fil ardi mmustaqarrunw wa mataa\'un ilaaheen',24,'7:24',16,61,123,2,0,153,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(979,7,'قَالَ فِيهَا تَحْيَوْنَ وَفِيهَا تَمُوتُونَ وَمِنْهَا تُخْرَجُونَ','Qaala feehaa tahyawna wa feehaa tamootoona wa minhaa tukhrajoon',25,'7:25',16,61,123,2,0,153,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(980,7,'يَـٰبَنِىٓ ءَادَمَ قَدْ أَنزَلْنَا عَلَيْكُمْ لِبَاسًا يُوَٰرِى سَوْءَٰتِكُمْ وَرِيشًا ۖ وَلِبَاسُ ٱلتَّقْوَىٰ ذَٰلِكَ خَيْرٌ ۚ ذَٰلِكَ مِنْ ءَايَـٰتِ ٱللَّهِ لَعَلَّهُمْ يَذَّكَّرُونَ','Yaa Baneee Aadama qad anzalnaa \'alaikum libaasany yuwaaree saw aatikum wa reeshanw wa libaasut taqwaa zaalika khair; zaalika min Aayaatil laahi la\'allahum yaz zakkaroon',26,'7:26',16,61,124,2,0,153,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(981,7,'يَـٰبَنِىٓ ءَادَمَ لَا يَفْتِنَنَّكُمُ ٱلشَّيْطَـٰنُ كَمَآ أَخْرَجَ أَبَوَيْكُم مِّنَ ٱلْجَنَّةِ يَنزِعُ عَنْهُمَا لِبَاسَهُمَا لِيُرِيَهُمَا سَوْءَٰتِهِمَآ ۗ إِنَّهُۥ يَرَىٰكُمْ هُوَ وَقَبِيلُهُۥ مِنْ حَيْثُ لَا تَرَوْنَهُمْ ۗ إِنَّا جَعَلْنَا ٱلشَّيَـٰطِينَ أَوْلِيَآءَ لِلَّذِينَ لَا يُؤْمِنُونَ','Yaa Banee Aadama laa yaftinannnakumush Shaitaanu kamaaa akhraja abawaikum minal Jannati yanzi\'u \'anhumaa libaasahumaa liyuriyahumaa saw aatihimaaa; innahoo yaraakum huwa wa qabeeluhoo min haisu laa tarawnahum; innaa ja\'alnash Shayaateena awliyaaa\'a lillazeena laa yu\'minoon',27,'7:27',16,61,124,2,0,153,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(982,7,'وَإِذَا فَعَلُوا۟ فَـٰحِشَةً قَالُوا۟ وَجَدْنَا عَلَيْهَآ ءَابَآءَنَا وَٱللَّهُ أَمَرَنَا بِهَا ۗ قُلْ إِنَّ ٱللَّهَ لَا يَأْمُرُ بِٱلْفَحْشَآءِ ۖ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ','Wa izaa fa\'aloo faahishatan qaaloo wajadnaa \'alaihaaa aabaaa\'ana wallaahu amaranaa bihaa; qul innal laaha laa yaamuru bilfahshaaa\'i a-taqooloona \'alal laahi mmaa laa ta\'lamoon',28,'7:28',16,61,124,2,0,153,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(983,7,'قُلْ أَمَرَ رَبِّى بِٱلْقِسْطِ ۖ وَأَقِيمُوا۟ وُجُوهَكُمْ عِندَ كُلِّ مَسْجِدٍ وَٱدْعُوهُ مُخْلِصِينَ لَهُ ٱلدِّينَ ۚ كَمَا بَدَأَكُمْ تَعُودُونَ','Qul amara Rabbee bilqisti wa aqeemoo wujoohakum \'inda kulli masjidin wad\'oohu mukhliseena lahud deen; kamaa bada akum ta\'oodoon',29,'7:29',16,61,124,2,0,153,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(984,7,'فَرِيقًا هَدَىٰ وَفَرِيقًا حَقَّ عَلَيْهِمُ ٱلضَّلَـٰلَةُ ۗ إِنَّهُمُ ٱتَّخَذُوا۟ ٱلشَّيَـٰطِينَ أَوْلِيَآءَ مِن دُونِ ٱللَّهِ وَيَحْسَبُونَ أَنَّهُم مُّهْتَدُونَ','Fareeqan hadaa wa fareeqan haqqa \'alaihimud dalaalah; innahumut takhazush Shayaateena awliyaaa\'a min doonil laahi wa yahsaboona annnahum muhtadoon',30,'7:30',16,61,124,2,0,153,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(985,7,'۞ يَـٰبَنِىٓ ءَادَمَ خُذُوا۟ زِينَتَكُمْ عِندَ كُلِّ مَسْجِدٍ وَكُلُوا۟ وَٱشْرَبُوا۟ وَلَا تُسْرِفُوٓا۟ ۚ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْرِفِينَ','Yaa Banneee Adama khuzoo zeenatakum \'inda kulli masjidinw wa kuloo washraboo wa laa tusrifoo; innahoo laa yuhibbul musrifeen',31,'7:31',16,62,124,2,0,154,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(986,7,'قُلْ مَنْ حَرَّمَ زِينَةَ ٱللَّهِ ٱلَّتِىٓ أَخْرَجَ لِعِبَادِهِۦ وَٱلطَّيِّبَـٰتِ مِنَ ٱلرِّزْقِ ۚ قُلْ هِىَ لِلَّذِينَ ءَامَنُوا۟ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا خَالِصَةً يَوْمَ ٱلْقِيَـٰمَةِ ۗ كَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَـٰتِ لِقَوْمٍ يَعْلَمُونَ','Qul man harrama zeenatal laahil lateee akhraja li\'ibaadihee wattaiyibaati minar rizq; qul hiya lillazeena aamanoo fil hayaatid dunyaa khaalisatany Yawmal Qiyaamah; kazaalika nufassihul Aayaati liqawminy ya\'lamoon',32,'7:32',16,62,125,2,0,154,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(987,7,'قُلْ إِنَّمَا حَرَّمَ رَبِّىَ ٱلْفَوَٰحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَٱلْإِثْمَ وَٱلْبَغْىَ بِغَيْرِ ٱلْحَقِّ وَأَن تُشْرِكُوا۟ بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَـٰنًا وَأَن تَقُولُوا۟ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ','Qul innamaa harrama Rabbiyal fawaahisha maa zahara minhaa wa maa bataa wal isma walbaghya bighairil haqqi wa an tushrikoo billaahi maa lam yunazzil bihee sultaananw wa an taqooloo \'alal laahi maa laa ta\'lamoon',33,'7:33',16,62,125,2,0,154,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(988,7,'وَلِكُلِّ أُمَّةٍ أَجَلٌ ۖ فَإِذَا جَآءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً ۖ وَلَا يَسْتَقْدِمُونَ','Wa likulli ummatin ajalun fa izaa jaaa\'a ajaluhum laa yastaakhiroona saa\'atanw wa laa yastaqdimoon',34,'7:34',16,62,125,2,0,154,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(989,7,'يَـٰبَنِىٓ ءَادَمَ إِمَّا يَأْتِيَنَّكُمْ رُسُلٌ مِّنكُمْ يَقُصُّونَ عَلَيْكُمْ ءَايَـٰتِى ۙ فَمَنِ ٱتَّقَىٰ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ','yaa Banee Aadama immaa yaatiyannakum Rusulum minkum yaqussoona \'alaikum Aayaatee famanit taqaa wa aslaha falaa khawfun \'alaihim wa laa hum yahzanoon',35,'7:35',16,62,125,2,0,154,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(990,7,'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا وَٱسْتَكْبَرُوا۟ عَنْهَآ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ','Wallazeena kazzaboo bi Aayaatinaa wastakbaroo \'anhhaaa ulaaa\'ika Ashaabun naari hum feehaa khaalidoon',36,'7:36',16,62,125,2,0,154,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(991,7,'فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَـٰتِهِۦٓ ۚ أُو۟لَـٰٓئِكَ يَنَالُهُمْ نَصِيبُهُم مِّنَ ٱلْكِتَـٰبِ ۖ حَتَّىٰٓ إِذَا جَآءَتْهُمْ رُسُلُنَا يَتَوَفَّوْنَهُمْ قَالُوٓا۟ أَيْنَ مَا كُنتُمْ تَدْعُونَ مِن دُونِ ٱللَّهِ ۖ قَالُوا۟ ضَلُّوا۟ عَنَّا وَشَهِدُوا۟ عَلَىٰٓ أَنفُسِهِمْ أَنَّهُمْ كَانُوا۟ كَـٰفِرِينَ','Faman azlamu mimmanif taraa \'alal laahi kaziban aw kazzaba bi Aayaatih; ulaaa\'ika yanaaluhum naseebuhum minal Kitaab; hataaa izaa jaaa\'at hum rusulunaa yatawaf fawnahum qaalooo aina maa kuntum tad\'oonaa min doonil laahi qaaloo dalloo \'annaa wa shahidoo \'alaaa anfusihim annahum kaanoo kaafieen',37,'7:37',16,62,125,2,0,154,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(992,7,'قَالَ ٱدْخُلُوا۟ فِىٓ أُمَمٍ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ ٱلْجِنِّ وَٱلْإِنسِ فِى ٱلنَّارِ ۖ كُلَّمَا دَخَلَتْ أُمَّةٌ لَّعَنَتْ أُخْتَهَا ۖ حَتَّىٰٓ إِذَا ٱدَّارَكُوا۟ فِيهَا جَمِيعًا قَالَتْ أُخْرَىٰهُمْ لِأُولَىٰهُمْ رَبَّنَا هَـٰٓؤُلَآءِ أَضَلُّونَا فَـَٔاتِهِمْ عَذَابًا ضِعْفًا مِّنَ ٱلنَّارِ ۖ قَالَ لِكُلٍّ ضِعْفٌ وَلَـٰكِن لَّا تَعْلَمُونَ','Qaalad khuloo feee umamin qad khalat min qablikum minal jinni wal insifin naari kullamaa dakhalat ummatul la\'anat ukhtahaa hattaaa izad daarakoo feehaa jamee\'an qaalat ukhraahum li oolaahum Rabbannaa haaa\'u laaa\'i adalloonaa fa aatihim \'azaaban di\'fam minan naari qaala likullin di funw wa laakil laa ta\'lamoon',38,'7:38',16,62,125,2,0,155,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(993,7,'وَقَالَتْ أُولَىٰهُمْ لِأُخْرَىٰهُمْ فَمَا كَانَ لَكُمْ عَلَيْنَا مِن فَضْلٍ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْسِبُونَ','Wa qaalat oolaahum li ukhraahum famaa kaana lakum \'alainaa min fadlin fazooqul azaaba bimaa kuntum taksiboon',39,'7:39',16,62,125,2,0,155,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(994,7,'إِنَّ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا وَٱسْتَكْبَرُوا۟ عَنْهَا لَا تُفَتَّحُ لَهُمْ أَبْوَٰبُ ٱلسَّمَآءِ وَلَا يَدْخُلُونَ ٱلْجَنَّةَ حَتَّىٰ يَلِجَ ٱلْجَمَلُ فِى سَمِّ ٱلْخِيَاطِ ۚ وَكَذَٰلِكَ نَجْزِى ٱلْمُجْرِمِينَ','Innal lazeena kazzaboo bi Aayaatinaa wastakbaroo \'anhaa laa tufattahu lahum ahwaabus samaaa\'i wa laa yadkhuloonal jannata hattaa yalijal jamalu fee sammil khiyaat; wa kazaalika najzil mujrimeen',40,'7:40',16,62,126,2,0,155,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(995,7,'لَهُم مِّن جَهَنَّمَ مِهَادٌ وَمِن فَوْقِهِمْ غَوَاشٍ ۚ وَكَذَٰلِكَ نَجْزِى ٱلظَّـٰلِمِينَ','Lahum min jahannama mihaadunw wa min fawqihim ghawaash; wa kazaalika najziz zaalimeen',41,'7:41',16,62,126,2,0,155,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(996,7,'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَآ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْجَنَّةِ ۖ هُمْ فِيهَا خَـٰلِدُونَ','Wallazeena aamanoo wa \'amilus saalihaati la nukallifu nafsan illaa wus\'ahaaa ulaaa\'ika Ashaabul jannati hum feehaa khaalidoon',42,'7:42',16,62,126,2,0,155,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(997,7,'وَنَزَعْنَا مَا فِى صُدُورِهِم مِّنْ غِلٍّ تَجْرِى مِن تَحْتِهِمُ ٱلْأَنْهَـٰرُ ۖ وَقَالُوا۟ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى هَدَىٰنَا لِهَـٰذَا وَمَا كُنَّا لِنَهْتَدِىَ لَوْلَآ أَنْ هَدَىٰنَا ٱللَّهُ ۖ لَقَدْ جَآءَتْ رُسُلُ رَبِّنَا بِٱلْحَقِّ ۖ وَنُودُوٓا۟ أَن تِلْكُمُ ٱلْجَنَّةُ أُورِثْتُمُوهَا بِمَا كُنتُمْ تَعْمَلُونَ','Wa naza\'naa maa fee sudoorihim min ghillin tajree min tahtihimul anhaaru wa qaalul hamdu lillaahil lazee hadaanaa lihaaza wa maa kunna linahtadiya law laaa ann hadaanal laahu laqad jaaa\'at Rusulu Rabbinaa bilhaqq; wa noodoo an tilkumul jannnatu ooristumoohaa bimaa kuntum ta\'maloon',43,'7:43',16,62,126,2,0,155,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(998,7,'وَنَادَىٰٓ أَصْحَـٰبُ ٱلْجَنَّةِ أَصْحَـٰبَ ٱلنَّارِ أَن قَدْ وَجَدْنَا مَا وَعَدَنَا رَبُّنَا حَقًّا فَهَلْ وَجَدتُّم مَّا وَعَدَ رَبُّكُمْ حَقًّا ۖ قَالُوا۟ نَعَمْ ۚ فَأَذَّنَ مُؤَذِّنٌۢ بَيْنَهُمْ أَن لَّعْنَةُ ٱللَّهِ عَلَى ٱلظَّـٰلِمِينَ','Wa naadaa Ashaabul jannati ashaaban Naari an qad wajadnaa maa wa\'adannaa Rabbunaa haqqan fahal wajattum maa wa\'ada Rabbukum haqqan qaaloo na\'am; fa azzana mu\'azzinum bainahum al la\'natul laahi \'alaz zaalimeen',44,'7:44',16,62,126,2,0,156,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(999,7,'ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِٱلْـَٔاخِرَةِ كَـٰفِرُونَ','Allazeena yasuddoona \'an sabeelil laahi wa yabghoo nahaa \'iwajanw wa hum bil Aakhirati kaafiroon',45,'7:45',16,62,126,2,0,156,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1000,7,'وَبَيْنَهُمَا حِجَابٌ ۚ وَعَلَى ٱلْأَعْرَافِ رِجَالٌ يَعْرِفُونَ كُلًّۢا بِسِيمَىٰهُمْ ۚ وَنَادَوْا۟ أَصْحَـٰبَ ٱلْجَنَّةِ أَن سَلَـٰمٌ عَلَيْكُمْ ۚ لَمْ يَدْخُلُوهَا وَهُمْ يَطْمَعُونَ','Wa bainahumaa hijaab; wa \'alal A\'raafi rijaaluny ya\'rifoona kullam biseemaahum; wa naadaw Ashaabal jannati an salaamun \'alaikum; lam yadkhuloohaa wa hum yatma\'oon',46,'7:46',16,62,126,2,0,156,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1001,7,'۞ وَإِذَا صُرِفَتْ أَبْصَـٰرُهُمْ تِلْقَآءَ أَصْحَـٰبِ ٱلنَّارِ قَالُوا۟ رَبَّنَا لَا تَجْعَلْنَا مَعَ ٱلْقَوْمِ ٱلظَّـٰلِمِينَ','Wa izaa surifat absaaruhum tilqaaa\'a Ashaabin Naari qaalo Rabbanaa laa taj\'alnaa ma\'al qawmiz zaalimneen',47,'7:47',16,63,126,2,0,156,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1002,7,'وَنَادَىٰٓ أَصْحَـٰبُ ٱلْأَعْرَافِ رِجَالًا يَعْرِفُونَهُم بِسِيمَىٰهُمْ قَالُوا۟ مَآ أَغْنَىٰ عَنكُمْ جَمْعُكُمْ وَمَا كُنتُمْ تَسْتَكْبِرُونَ','Wa naadaaa Ashaabul A\'raffi rijaalany ya\'rifoonahum biseemaahum qaaloo maaa aghnaa \'ankum jam\'ukum wa maa kuntum tastakbiroon',48,'7:48',16,63,127,2,0,156,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1003,7,'أَهَـٰٓؤُلَآءِ ٱلَّذِينَ أَقْسَمْتُمْ لَا يَنَالُهُمُ ٱللَّهُ بِرَحْمَةٍ ۚ ٱدْخُلُوا۟ ٱلْجَنَّةَ لَا خَوْفٌ عَلَيْكُمْ وَلَآ أَنتُمْ تَحْزَنُونَ','A haaa\'ulaaa\'il lazeena aqsamtum laa yanaaluhumul laahu birahma; udkhulul Jannata laa khawfun \'alaikum wa laaa antum tahzanoon',49,'7:49',16,63,127,2,0,156,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1004,7,'وَنَادَىٰٓ أَصْحَـٰبُ ٱلنَّارِ أَصْحَـٰبَ ٱلْجَنَّةِ أَنْ أَفِيضُوا۟ عَلَيْنَا مِنَ ٱلْمَآءِ أَوْ مِمَّا رَزَقَكُمُ ٱللَّهُ ۚ قَالُوٓا۟ إِنَّ ٱللَّهَ حَرَّمَهُمَا عَلَى ٱلْكَـٰفِرِينَ','Wa naadaaa Ashaabun Naari Ashaabal jannati an afeedoo \'alainaa minal maaa\'i aw mimma razaqakumul laah; qaaloo innal laaha harrama humaa \'alal kaafireen',50,'7:50',16,63,127,2,0,156,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1005,7,'ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَهُمْ لَهْوًا وَلَعِبًا وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا ۚ فَٱلْيَوْمَ نَنسَىٰهُمْ كَمَا نَسُوا۟ لِقَآءَ يَوْمِهِمْ هَـٰذَا وَمَا كَانُوا۟ بِـَٔايَـٰتِنَا يَجْحَدُونَ','Allazeenat takhazoo deenahu lahwanw wa la\'i-banw wa gharrat humul hayaatud dunyaa; fal Yawma nnannsaahum kamaa nasoo liqaaa\'a Yawmihim haazaa wa maa kaanoo bi aayaatinaa yajhadoon',51,'7:51',16,63,127,2,0,156,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1006,7,'وَلَقَدْ جِئْنَـٰهُم بِكِتَـٰبٍ فَصَّلْنَـٰهُ عَلَىٰ عِلْمٍ هُدًى وَرَحْمَةً لِّقَوْمٍ يُؤْمِنُونَ','Wa laqad ji\'naahum bi Kitaabin fassalnaahu \'alaa \'ilmin hudanw wa rahmatal liqawminy-yu\'miinoon',52,'7:52',16,63,127,2,0,157,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1007,7,'هَلْ يَنظُرُونَ إِلَّا تَأْوِيلَهُۥ ۚ يَوْمَ يَأْتِى تَأْوِيلُهُۥ يَقُولُ ٱلَّذِينَ نَسُوهُ مِن قَبْلُ قَدْ جَآءَتْ رُسُلُ رَبِّنَا بِٱلْحَقِّ فَهَل لَّنَا مِن شُفَعَآءَ فَيَشْفَعُوا۟ لَنَآ أَوْ نُرَدُّ فَنَعْمَلَ غَيْرَ ٱلَّذِى كُنَّا نَعْمَلُ ۚ قَدْ خَسِرُوٓا۟ أَنفُسَهُمْ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ','hal yanzuroona illaa taa weelah; yawma yaatee taaweeluhoo yaqoolul lazeena nasoohu min qablu qad jaaa\'at Rusulu Rabbinaa bilhaqq; fahal lanaa min shufa\'aaa\'a fa yashfa\'oo lanaaa aw nuraddu fana\'mala ghairal lazee kunnaa na\'mal; qad khasirooo anfusahum wa dalla \'anhum maa kaanoo yaftaroon',53,'7:53',16,63,127,2,0,157,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1008,7,'إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ يُغْشِى ٱلَّيْلَ ٱلنَّهَارَ يَطْلُبُهُۥ حَثِيثًا وَٱلشَّمْسَ وَٱلْقَمَرَ وَٱلنُّجُومَ مُسَخَّرَٰتٍۭ بِأَمْرِهِۦٓ ۗ أَلَا لَهُ ٱلْخَلْقُ وَٱلْأَمْرُ ۗ تَبَارَكَ ٱللَّهُ رَبُّ ٱلْعَـٰلَمِينَ','Inna Rabbakkumul laahul lazee khalaqas sammaawaati wal arda fee sittati qiyaamin summmas tawaa \'alal \'arshi yughshil lailan nahaara yatlu buhoo haseesanw washshamsa walqamara wannujooma musakhkharaatim bi amrih; alaa lahul khalqu wal-amr; tabaarakal laahu Rabbul \'aalameen',54,'7:54',16,63,128,2,0,157,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1009,7,'ٱدْعُوا۟ رَبَّكُمْ تَضَرُّعًا وَخُفْيَةً ۚ إِنَّهُۥ لَا يُحِبُّ ٱلْمُعْتَدِينَ','Ud\'oo Rabbakum tadarru\'anw wa khufyah; innahoo laa yuhibbul mu\'tadeen',55,'7:55',16,63,128,2,0,157,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1010,7,'وَلَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ بَعْدَ إِصْلَـٰحِهَا وَٱدْعُوهُ خَوْفًا وَطَمَعًا ۚ إِنَّ رَحْمَتَ ٱللَّهِ قَرِيبٌ مِّنَ ٱلْمُحْسِنِينَ','Wa laa tufsidoo fil ardi ba\'da islaahihaa wad\'oohu khawfanw wa tama\'aa; inna rahmatal laahi qareebum minal muhsineen',56,'7:56',16,63,128,2,0,157,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1011,7,'وَهُوَ ٱلَّذِى يُرْسِلُ ٱلرِّيَـٰحَ بُشْرًۢا بَيْنَ يَدَىْ رَحْمَتِهِۦ ۖ حَتَّىٰٓ إِذَآ أَقَلَّتْ سَحَابًا ثِقَالًا سُقْنَـٰهُ لِبَلَدٍ مَّيِّتٍ فَأَنزَلْنَا بِهِ ٱلْمَآءَ فَأَخْرَجْنَا بِهِۦ مِن كُلِّ ٱلثَّمَرَٰتِ ۚ كَذَٰلِكَ نُخْرِجُ ٱلْمَوْتَىٰ لَعَلَّكُمْ تَذَكَّرُونَ','Wa Huwal lazee yursilur riyaaha bushram baina yadai rahmatihee hattaaa izaaa aqallat sahaaban siqaalan suqnaahu libaladim maiyitin fa annzalnaa bihil maaa\'a fa akhrajnaa bihee minn kullis samaraat; kazaalika nukhrijul mawtaa la\'allakum tazakkaroon',57,'7:57',16,63,128,2,0,157,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1012,7,'وَٱلْبَلَدُ ٱلطَّيِّبُ يَخْرُجُ نَبَاتُهُۥ بِإِذْنِ رَبِّهِۦ ۖ وَٱلَّذِى خَبُثَ لَا يَخْرُجُ إِلَّا نَكِدًا ۚ كَذَٰلِكَ نُصَرِّفُ ٱلْـَٔايَـٰتِ لِقَوْمٍ يَشْكُرُونَ','Walbaladut taiyibu yakhruju nabaatuhoo bi-izni Rabbihee wallazee khabusa laa yakhruju illaa nakidaa; kazaalika nusarriful Aayaati liqawminy yashkuroon',58,'7:58',16,63,128,2,0,158,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1013,7,'لَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦ فَقَالَ يَـٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَـٰهٍ غَيْرُهُۥٓ إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍ','Laqad arsalnaa noohan ilaa qawmihee faqaala yaa qawmi\' budul laaha maa lakum min ilaahin ghairuhoo inneee akhaafu \'alaikum \'azaaba Yawmin \'Azeem',59,'7:59',16,63,129,2,0,158,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1014,7,'قَالَ ٱلْمَلَأُ مِن قَوْمِهِۦٓ إِنَّا لَنَرَىٰكَ فِى ضَلَـٰلٍ مُّبِينٍ','Qaalal mala-u min qaw miheee innaa lanaraaka fee dalaalim mubeen',60,'7:60',16,63,129,2,0,158,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1015,7,'قَالَ يَـٰقَوْمِ لَيْسَ بِى ضَلَـٰلَةٌ وَلَـٰكِنِّى رَسُولٌ مِّن رَّبِّ ٱلْعَـٰلَمِينَ','Qaala yaa qawmi laisa bee dalaalatunw wa laakinnee Rasoolum mir Rabbil \'aalameen',61,'7:61',16,63,129,2,0,158,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1016,7,'أُبَلِّغُكُمْ رِسَـٰلَـٰتِ رَبِّى وَأَنصَحُ لَكُمْ وَأَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ','Uballighukum Risaalaati Rabbee wa ansahu lakum wa a\'lamu minal laahi maa laa ta\'lamoon',62,'7:62',16,63,129,2,0,158,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1017,7,'أَوَعَجِبْتُمْ أَن جَآءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَىٰ رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ وَلِتَتَّقُوا۟ وَلَعَلَّكُمْ تُرْحَمُونَ','awa\'ajibtum an jaaa\'akum zikrum mir Rabbikum \'alaa rajulim minkum liyunzirakum wa litattaqoo wa la\'allakum turhamoon',63,'7:63',16,63,129,2,0,158,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1018,7,'فَكَذَّبُوهُ فَأَنجَيْنَـٰهُ وَٱلَّذِينَ مَعَهُۥ فِى ٱلْفُلْكِ وَأَغْرَقْنَا ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَآ ۚ إِنَّهُمْ كَانُوا۟ قَوْمًا عَمِينَ','Fakazzaboohu fa anjai naahu wallazeena ma\'ahoo fil fulki wa aghraqnal lazeena kazzaboo bi Aayaatinaa; innahum kaanoo qawman \'ameen',64,'7:64',16,63,129,2,0,158,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1019,7,'۞ وَإِلَىٰ عَادٍ أَخَاهُمْ هُودًا ۗ قَالَ يَـٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَـٰهٍ غَيْرُهُۥٓ ۚ أَفَلَا تَتَّقُونَ','Wa ilaa \'aadin akhaahum Hoodaa; qaala yaa qawmi\' budul laaha maa lakum min ilaahin ghairuh; afalaa tattaqoon',65,'7:65',16,64,130,2,0,158,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1020,7,'قَالَ ٱلْمَلَأُ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦٓ إِنَّا لَنَرَىٰكَ فِى سَفَاهَةٍ وَإِنَّا لَنَظُنُّكَ مِنَ ٱلْكَـٰذِبِينَ','Qaalal mala ul lazeena kafaroo min qawmiheee innaa lanaraaka fee safaahatinw wa innaa lannazunnuka minal kaazibeen',66,'7:66',16,64,130,2,0,158,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1021,7,'قَالَ يَـٰقَوْمِ لَيْسَ بِى سَفَاهَةٌ وَلَـٰكِنِّى رَسُولٌ مِّن رَّبِّ ٱلْعَـٰلَمِينَ','Qaala yaa qawmi laisa bee safaahatunw wa laakinnee Rasoolum mir Rabbil \'aalameen',67,'7:67',16,64,130,2,0,158,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1022,7,'أُبَلِّغُكُمْ رِسَـٰلَـٰتِ رَبِّى وَأَنَا۠ لَكُمْ نَاصِحٌ أَمِينٌ','Uballighukum Risaalaati Rabbee wa ana lakum naasihun ameen',68,'7:68',16,64,130,2,0,159,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1023,7,'أَوَعَجِبْتُمْ أَن جَآءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَىٰ رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ ۚ وَٱذْكُرُوٓا۟ إِذْ جَعَلَكُمْ خُلَفَآءَ مِنۢ بَعْدِ قَوْمِ نُوحٍ وَزَادَكُمْ فِى ٱلْخَلْقِ بَصْۜطَةً ۖ فَٱذْكُرُوٓا۟ ءَالَآءَ ٱللَّهِ لَعَلَّكُمْ تُفْلِحُونَ','awa \'ajibtum an jaaa\'akum zikrum mir Rabbikum \'alaa rajulim minkum liyunzirakum; wazkurooo iz ja\'alakum khulafaaa\'a mim ba\'di qawmi noohinw wa zaadakum filkhalqi bastatan fazkurooo aalaaa\'al laahi la\'allakum tuflihoon',69,'7:69',16,64,130,2,0,159,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1024,7,'قَالُوٓا۟ أَجِئْتَنَا لِنَعْبُدَ ٱللَّهَ وَحْدَهُۥ وَنَذَرَ مَا كَانَ يَعْبُدُ ءَابَآؤُنَا ۖ فَأْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ','Qaalooo aji\'tanaa lina\'budal laaha wahdahoo wa nazara maa kaana ya\'budu aabaaa\'u naa faatinaa bimaa ta\'idunaaa in kunta minas saadiqeen',70,'7:70',16,64,130,2,0,159,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1025,7,'قَالَ قَدْ وَقَعَ عَلَيْكُم مِّن رَّبِّكُمْ رِجْسٌ وَغَضَبٌ ۖ أَتُجَـٰدِلُونَنِى فِىٓ أَسْمَآءٍ سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّا نَزَّلَ ٱللَّهُ بِهَا مِن سُلْطَـٰنٍ ۚ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ','Qaala qad waqa\'a alaikum mir Rabbikum rijsunw wa ghadab, atujaadiloonanee feee asmaaa\'in sammaitumoohaaa antum wa aabaaa\'ukum maa nazzalal laahu bihaa min sultaan; fantazirooo innee ma\'akum minal muntazireen',71,'7:71',16,64,130,2,0,159,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1026,7,'فَأَنجَيْنَـٰهُ وَٱلَّذِينَ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَقَطَعْنَا دَابِرَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا ۖ وَمَا كَانُوا۟ مُؤْمِنِينَ','Fa anjainaahu wallazeena ma\'ahoo birahmatim minnaa wa qata\'naa daabiral lazeena kazzaboo bi Aayaatinaa wa maa kaanoo mu\'mineen',72,'7:72',16,64,130,2,0,159,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1027,7,'وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَـٰلِحًا ۗ قَالَ يَـٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَـٰهٍ غَيْرُهُۥ ۖ قَدْ جَآءَتْكُم بَيِّنَةٌ مِّن رَّبِّكُمْ ۖ هَـٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمْ ءَايَةً ۖ فَذَرُوهَا تَأْكُلْ فِىٓ أَرْضِ ٱللَّهِ ۖ وَلَا تَمَسُّوهَا بِسُوٓءٍ فَيَأْخُذَكُمْ عَذَابٌ أَلِيمٌ','Wa ilaa Samooda akhaahum Saalihaa; qaala yaa qawmi\' budul laaha maa lakum min ilaahin ghairuhoo qad jaaa\'atkum baiyinatum mir Rabbikum haazihee naaqatul laahi lakum Aayatan fazaroohaa taakul feee ardil laahi wa laa tamassoohaa bisooo\'in fa yaakhuzakum \'azaabun aleem',73,'7:73',16,64,131,2,0,159,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1028,7,'وَٱذْكُرُوٓا۟ إِذْ جَعَلَكُمْ خُلَفَآءَ مِنۢ بَعْدِ عَادٍ وَبَوَّأَكُمْ فِى ٱلْأَرْضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورًا وَتَنْحِتُونَ ٱلْجِبَالَ بُيُوتًا ۖ فَٱذْكُرُوٓا۟ ءَالَآءَ ٱللَّهِ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ','Wazkkurooo iz ja\'alakum khulafaaa\'a mim ba\'di \'Aadinw wa bawwa akum fil ardi tattakhizoona min suhoolihaa qusooranw wa tanhitoonal jibaala buyootan fazkurooo aalaaa\'al laahi wa laa ta\'saw fil ardi mufsideen',74,'7:74',16,64,131,2,0,160,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1029,7,'قَالَ ٱلْمَلَأُ ٱلَّذِينَ ٱسْتَكْبَرُوا۟ مِن قَوْمِهِۦ لِلَّذِينَ ٱسْتُضْعِفُوا۟ لِمَنْ ءَامَنَ مِنْهُمْ أَتَعْلَمُونَ أَنَّ صَـٰلِحًا مُّرْسَلٌ مِّن رَّبِّهِۦ ۚ قَالُوٓا۟ إِنَّا بِمَآ أُرْسِلَ بِهِۦ مُؤْمِنُونَ','Qaalal mala ul lazeenas takbaroo min qawmihee lillazeenas tud\'ifoo liman aamana minhum ata\'almoona anna Saaliham mursalum mir Rabbih; qaalooo innaa bimaaa ursila bihee mu\'minoon',75,'7:75',16,64,131,2,0,160,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1030,7,'قَالَ ٱلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا بِٱلَّذِىٓ ءَامَنتُم بِهِۦ كَـٰفِرُونَ','Qaalal lazeenas takbarooo innaa billazeee aamanntum bihee kaafiroon',76,'7:76',16,64,131,2,0,160,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1031,7,'فَعَقَرُوا۟ ٱلنَّاقَةَ وَعَتَوْا۟ عَنْ أَمْرِ رَبِّهِمْ وَقَالُوا۟ يَـٰصَـٰلِحُ ٱئْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلْمُرْسَلِينَ','Fa\'aqarun naaqata wa\'ataw \'an amri Rabbihim wa qaaloo yaa Saalihu\' tinaa bimaa ta\'idunaaa in kunta minal mursaleen',77,'7:77',16,64,131,2,0,160,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1032,7,'فَأَخَذَتْهُمُ ٱلرَّجْفَةُ فَأَصْبَحُوا۟ فِى دَارِهِمْ جَـٰثِمِينَ','Fa akhazat humur rajftu fa asbahoo fee daarihim jaasimmeen',78,'7:78',16,64,131,2,0,160,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1033,7,'فَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَـٰقَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَالَةَ رَبِّى وَنَصَحْتُ لَكُمْ وَلَـٰكِن لَّا تُحِبُّونَ ٱلنَّـٰصِحِينَ','Fa tawalla \'anhum wa qaala yaa qawmi laqad ablaghtukum Risaalata Rabbee wa nasahtu lakum wa laakil laa tuhibboonan naasiheen',79,'7:79',16,64,131,2,0,160,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1034,7,'وَلُوطًا إِذْ قَالَ لِقَوْمِهِۦٓ أَتَأْتُونَ ٱلْفَـٰحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ ٱلْعَـٰلَمِينَ','Wa Lootan iz qaala liqawmiheee ataatoonal faahishata maa sabaqakum bihaa min ahadim minal \'aalameen',80,'7:80',16,64,131,2,0,160,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1035,7,'إِنَّكُمْ لَتَأْتُونَ ٱلرِّجَالَ شَهْوَةً مِّن دُونِ ٱلنِّسَآءِ ۚ بَلْ أَنتُمْ قَوْمٌ مُّسْرِفُونَ','Innakum lataatoonar rijaala shahwatam min doonin nisaaa\'; bal antumqawmum musrifoon',81,'7:81',16,64,131,2,0,160,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1036,7,'وَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوٓا۟ أَخْرِجُوهُم مِّن قَرْيَتِكُمْ ۖ إِنَّهُمْ أُنَاسٌ يَتَطَهَّرُونَ','Wa maa kaana jawaaba qawmihee illaa an qaalooo akhrijoohum min qaryatikum innahum unaasuny yatatah haroon',82,'7:82',16,64,131,2,0,161,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1037,7,'فَأَنجَيْنَـٰهُ وَأَهْلَهُۥٓ إِلَّا ٱمْرَأَتَهُۥ كَانَتْ مِنَ ٱلْغَـٰبِرِينَ','Fa anjainaahu wa ahlahooo illam ra atahoo kaanat minal ghaabireen',83,'7:83',16,64,131,2,0,161,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1038,7,'وَأَمْطَرْنَا عَلَيْهِم مَّطَرًا ۖ فَٱنظُرْ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُجْرِمِينَ','Wa \'amtarnaa \'alaihim mataran fanzur kaifa kaana aaqibatul mujjrimeen',84,'7:84',16,64,131,2,0,161,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1039,7,'وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًا ۗ قَالَ يَـٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَـٰهٍ غَيْرُهُۥ ۖ قَدْ جَآءَتْكُم بَيِّنَةٌ مِّن رَّبِّكُمْ ۖ فَأَوْفُوا۟ ٱلْكَيْلَ وَٱلْمِيزَانَ وَلَا تَبْخَسُوا۟ ٱلنَّاسَ أَشْيَآءَهُمْ وَلَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ بَعْدَ إِصْلَـٰحِهَا ۚ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ','Wa ilaa Madyana akhaahum Shu\'aybaa; qaala yaa qawmi\' budul laaha maa lakum min ilaahin ghairuhoo qad jaaa\'atkum baiyinatum mir Rabbikum fa awful kaila walmeezaana wa laa tabkhasun naasa ashyaa\'ahum wa laa tufsidoo fil ardi ba\'da islaahihaa; zaalikum khairul lakum in kuntum mu\'mineen',85,'7:85',16,64,132,2,0,161,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1040,7,'وَلَا تَقْعُدُوا۟ بِكُلِّ صِرَٰطٍ تُوعِدُونَ وَتَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنْ ءَامَنَ بِهِۦ وَتَبْغُونَهَا عِوَجًا ۚ وَٱذْكُرُوٓا۟ إِذْ كُنتُمْ قَلِيلًا فَكَثَّرَكُمْ ۖ وَٱنظُرُوا۟ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُفْسِدِينَ','Wa laa taq\'udoo bikulli siraatin too\'idoona wa tasuddoona \'an sabeelil laahi man aamana bihee wa abghoonahaa \'iwajaa; waz kurooo iz kuntum qaleelan fakassarakum wanzuroo kaifa kaana \'aaqibatul mufsideen',86,'7:86',16,64,132,2,0,161,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1041,7,'وَإِن كَانَ طَآئِفَةٌ مِّنكُمْ ءَامَنُوا۟ بِٱلَّذِىٓ أُرْسِلْتُ بِهِۦ وَطَآئِفَةٌ لَّمْ يُؤْمِنُوا۟ فَٱصْبِرُوا۟ حَتَّىٰ يَحْكُمَ ٱللَّهُ بَيْنَنَا ۚ وَهُوَ خَيْرُ ٱلْحَـٰكِمِينَ','Wa In kaana taaa\'ifatum minkum aamanoo billazeee ursiltu bihee wa taaa\'ifatul lam yu\'minoo fasbiroo hattaa yahkumual laahu bainanaa; wa Huwa khairul haakimeen',87,'7:87',16,64,132,2,0,161,8,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1042,7,'۞ قَالَ ٱلْمَلَأُ ٱلَّذِينَ ٱسْتَكْبَرُوا۟ مِن قَوْمِهِۦ لَنُخْرِجَنَّكَ يَـٰشُعَيْبُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَكَ مِن قَرْيَتِنَآ أَوْ لَتَعُودُنَّ فِى مِلَّتِنَا ۚ قَالَ أَوَلَوْ كُنَّا كَـٰرِهِينَ','Qaalal mala ul lazeenas takbaroo min qawmihee lanukhrijannaka yaa Shu\'aibu wallazeena aamanoo ma\'aka min qaryatinaaa aw lata\'oo dunna fee millatinaa; qaala awa law kunnaa kaariheen',88,'7:88',17,65,132,2,0,162,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1043,7,'قَدِ ٱفْتَرَيْنَا عَلَى ٱللَّهِ كَذِبًا إِنْ عُدْنَا فِى مِلَّتِكُم بَعْدَ إِذْ نَجَّىٰنَا ٱللَّهُ مِنْهَا ۚ وَمَا يَكُونُ لَنَآ أَن نَّعُودَ فِيهَآ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّنَا ۚ وَسِعَ رَبُّنَا كُلَّ شَىْءٍ عِلْمًا ۚ عَلَى ٱللَّهِ تَوَكَّلْنَا ۚ رَبَّنَا ٱفْتَحْ بَيْنَنَا وَبَيْنَ قَوْمِنَا بِٱلْحَقِّ وَأَنتَ خَيْرُ ٱلْفَـٰتِحِينَ','Qadif tarainaa \'alal laahi kaziban in \'udnaa fee millatikum ba\'da iz najjaanal laahu minhaa; wa maa yakoonu lanaaa an na\'ooda feehaaa illaaa ai yashaaa\'al laahu Rabbunaa; wasi\'a Rabbunaa kulla shai\'in \'ilmaa; \'alal laahi tawakkalnaa; Rabbanaf tah bainanaa wa baina qawminaa bilhaqqi wa Anta khairul faatiheen',89,'7:89',17,65,132,2,0,162,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1044,7,'وَقَالَ ٱلْمَلَأُ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦ لَئِنِ ٱتَّبَعْتُمْ شُعَيْبًا إِنَّكُمْ إِذًا لَّخَـٰسِرُونَ','Wa qaalal mala ul lazeena kafaroo min qawmihee la\'init taba\'tum Shu\'aiban innakum izal lakhaasiroon',90,'7:90',17,65,132,2,0,162,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1045,7,'فَأَخَذَتْهُمُ ٱلرَّجْفَةُ فَأَصْبَحُوا۟ فِى دَارِهِمْ جَـٰثِمِينَ','Fa akhazat humur rajfatu fa asbahoo fee daarihim jaasimeen',91,'7:91',17,65,132,2,0,162,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1046,7,'ٱلَّذِينَ كَذَّبُوا۟ شُعَيْبًا كَأَن لَّمْ يَغْنَوْا۟ فِيهَا ۚ ٱلَّذِينَ كَذَّبُوا۟ شُعَيْبًا كَانُوا۟ هُمُ ٱلْخَـٰسِرِينَ','Allazeena kazzaboo Shu\'aiban ka al alm yaghnaw feehaa; allazeena kazzaboo Shu\'aiban kaanoo humul khaasireen',92,'7:92',17,65,132,2,0,162,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1047,7,'فَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَـٰقَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَـٰلَـٰتِ رَبِّى وَنَصَحْتُ لَكُمْ ۖ فَكَيْفَ ءَاسَىٰ عَلَىٰ قَوْمٍ كَـٰفِرِينَ','Fatawalla \'anhum wa qaala yaa qawmi laqad ablaghtukum Risaalaati Rabbee wa nasahtu lakum fakaifa aasaa\'alaa qawmin kaafireen',93,'7:93',17,65,132,2,0,162,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1048,7,'وَمَآ أَرْسَلْنَا فِى قَرْيَةٍ مِّن نَّبِىٍّ إِلَّآ أَخَذْنَآ أَهْلَهَا بِٱلْبَأْسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمْ يَضَّرَّعُونَ','Wa maaa arsalnaa fee qaryatim min Nabiyyin illaaa akhaznaaa ahlahaa bil baasaaa\'i waddarraaa\'i la\'allahum yaddarra\'oon',94,'7:94',17,65,133,2,0,162,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1049,7,'ثُمَّ بَدَّلْنَا مَكَانَ ٱلسَّيِّئَةِ ٱلْحَسَنَةَ حَتَّىٰ عَفَوا۟ وَّقَالُوا۟ قَدْ مَسَّ ءَابَآءَنَا ٱلضَّرَّآءُ وَٱلسَّرَّآءُ فَأَخَذْنَـٰهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ','Summa baddalnaa makaa nas saiyi\'atil hasanata hattaa \'afaw wa qaaloo qad massa aabaa\'anad darraaa\'u wassarraaa\'u fa akhaznaahum baghtatanw wa hum laa yash\'uroon',95,'7:95',17,65,133,2,0,162,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1050,7,'وَلَوْ أَنَّ أَهْلَ ٱلْقُرَىٰٓ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَفَتَحْنَا عَلَيْهِم بَرَكَـٰتٍ مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ وَلَـٰكِن كَذَّبُوا۟ فَأَخَذْنَـٰهُم بِمَا كَانُوا۟ يَكْسِبُونَ','Wa law anna ahlal quraaa aamanoo wattaqaw lafatahnaa \'alaihim barakaatim minas samaaa\'i wal ardi wa laakin kazzaboo fa akhaznaahum bimaa kaanoo yaksiboon',96,'7:96',17,65,133,2,0,163,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1051,7,'أَفَأَمِنَ أَهْلُ ٱلْقُرَىٰٓ أَن يَأْتِيَهُم بَأْسُنَا بَيَـٰتًا وَهُمْ نَآئِمُونَ','Afa amina ahlul quraaa ai yaatiyahum baasunaa bayaatanw wa hum naaa\'imoon',97,'7:97',17,65,133,2,0,163,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1052,7,'أَوَأَمِنَ أَهْلُ ٱلْقُرَىٰٓ أَن يَأْتِيَهُم بَأْسُنَا ضُحًى وَهُمْ يَلْعَبُونَ','Awa amina ahlul quraaa ai yaatiyahum baasunaa duhanw wa hum yal\'aboon',98,'7:98',17,65,133,2,0,163,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1053,7,'أَفَأَمِنُوا۟ مَكْرَ ٱللَّهِ ۚ فَلَا يَأْمَنُ مَكْرَ ٱللَّهِ إِلَّا ٱلْقَوْمُ ٱلْخَـٰسِرُونَ','Afa aminoo makral laah; falaa yaamanu makral laahi illal qawmul khaasiroon',99,'7:99',17,65,133,2,0,163,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1054,7,'أَوَلَمْ يَهْدِ لِلَّذِينَ يَرِثُونَ ٱلْأَرْضَ مِنۢ بَعْدِ أَهْلِهَآ أَن لَّوْ نَشَآءُ أَصَبْنَـٰهُم بِذُنُوبِهِمْ ۚ وَنَطْبَعُ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَسْمَعُونَ','Awa lam yahdi lillazeena yarisoonal arda mim ba\'di ahlihaaa al law nashaaa\'u asabnaahum bizunoobihim; wa natba\'u \'alaa quloobihim fahum laa yasma\'oon',100,'7:100',17,65,134,2,0,163,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1055,7,'تِلْكَ ٱلْقُرَىٰ نَقُصُّ عَلَيْكَ مِنْ أَنۢبَآئِهَا ۚ وَلَقَدْ جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَـٰتِ فَمَا كَانُوا۟ لِيُؤْمِنُوا۟ بِمَا كَذَّبُوا۟ مِن قَبْلُ ۚ كَذَٰلِكَ يَطْبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلْكَـٰفِرِينَ','Tilkal quraa naqussu \'alaika min ambaaa\'ihaa; wa laqad jaaa\'at hum Rusuluhum bilbaiyinaati famaa kaanoo liyu\'minoo bimaa kazzaboo min qabl; kazaalika yatba\'ul laahu \'alaa quloobil kaafireen',101,'7:101',17,65,134,2,0,163,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1056,7,'وَمَا وَجَدْنَا لِأَكْثَرِهِم مِّنْ عَهْدٍ ۖ وَإِن وَجَدْنَآ أَكْثَرَهُمْ لَفَـٰسِقِينَ','Wa maa wajadnaa li aksarihim min \'ahd; wa inw wajadnaaa aksarahum lafaasiqeen',102,'7:102',17,65,134,2,0,163,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1057,7,'ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِم مُّوسَىٰ بِـَٔايَـٰتِنَآ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَظَلَمُوا۟ بِهَا ۖ فَٱنظُرْ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُفْسِدِينَ','Summa ba\'asnaa mim ba\'dihim Moosaa bi Aayaatinaaa ilaa Fir\'awana wa mala\'ihee fazalamoo bihaa fanzur kaifa kaana \'aaqibatul mufsideen',103,'7:103',17,65,134,2,0,163,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1058,7,'وَقَالَ مُوسَىٰ يَـٰفِرْعَوْنُ إِنِّى رَسُولٌ مِّن رَّبِّ ٱلْعَـٰلَمِينَ','Wa qaala Moosaa yaa Fir\'awnu inee Rasoolum mir Rabbil \'aalameen',104,'7:104',17,65,134,2,0,163,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1059,7,'حَقِيقٌ عَلَىٰٓ أَن لَّآ أَقُولَ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ ۚ قَدْ جِئْتُكُم بِبَيِّنَةٍ مِّن رَّبِّكُمْ فَأَرْسِلْ مَعِىَ بَنِىٓ إِسْرَٰٓءِيلَ','Haqeequn \'alaaa al laaa aqoola \'alal laahi illal haqq; qad ji\'tukum bibaiyinatim mir Rabbikum fa arsil ma\'iya Baneee Israaa\'eel',105,'7:105',17,65,134,2,0,164,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1060,7,'قَالَ إِن كُنتَ جِئْتَ بِـَٔايَةٍ فَأْتِ بِهَآ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ','Qaala in kunta ji\'ta bi Aayatin faati bihaaa in kunta minas saadiqeen',106,'7:106',17,65,134,2,0,164,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1061,7,'فَأَلْقَىٰ عَصَاهُ فَإِذَا هِىَ ثُعْبَانٌ مُّبِينٌ','Qa alqaa \'asaahu fa izaa hiya su\'baanum mubeen',107,'7:107',17,65,134,2,0,164,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1062,7,'وَنَزَعَ يَدَهُۥ فَإِذَا هِىَ بَيْضَآءُ لِلنَّـٰظِرِينَ','Wa naza\'a yadahoo fa izaa hiya baidaaa\'u linnaazireen',108,'7:108',17,65,134,2,0,164,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1063,7,'قَالَ ٱلْمَلَأُ مِن قَوْمِ فِرْعَوْنَ إِنَّ هَـٰذَا لَسَـٰحِرٌ عَلِيمٌ','Qaalal mala-u min qawmi Fir\'awna inna haazaa lasaa hirun \'aleem',109,'7:109',17,65,135,2,0,164,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1064,7,'يُرِيدُ أَن يُخْرِجَكُم مِّنْ أَرْضِكُمْ ۖ فَمَاذَا تَأْمُرُونَ','Yureedu ai yukhrijakum min ardikum famaazaa taamuroon',110,'7:110',17,65,135,2,0,164,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1065,7,'قَالُوٓا۟ أَرْجِهْ وَأَخَاهُ وَأَرْسِلْ فِى ٱلْمَدَآئِنِ حَـٰشِرِينَ','Qaalooo arjih wa akhaahu wa arsil filmadaaa\'ini haashireen',111,'7:111',17,65,135,2,0,164,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1066,7,'يَأْتُوكَ بِكُلِّ سَـٰحِرٍ عَلِيمٍ','Yaatooka bikulli saahirin \'aleem',112,'7:112',17,65,135,2,0,164,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1067,7,'وَجَآءَ ٱلسَّحَرَةُ فِرْعَوْنَ قَالُوٓا۟ إِنَّ لَنَا لَأَجْرًا إِن كُنَّا نَحْنُ ٱلْغَـٰلِبِينَ','Wa jaaa\'as saharatu Fir\'awna qaaloo inna lanaa la ajjran in kunnaa nahnul ghaalibeen',113,'7:113',17,65,135,2,0,164,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1068,7,'قَالَ نَعَمْ وَإِنَّكُمْ لَمِنَ ٱلْمُقَرَّبِينَ','Qaala na\'am wa innakum laminal muqarrabeen',114,'7:114',17,65,135,2,0,164,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1069,7,'قَالُوا۟ يَـٰمُوسَىٰٓ إِمَّآ أَن تُلْقِىَ وَإِمَّآ أَن نَّكُونَ نَحْنُ ٱلْمُلْقِينَ','Qaaloo yaa Moosaaa immaaa an tulqiya wa immaaa an nakoona nahnul mulqeen',115,'7:115',17,65,135,2,0,164,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1070,7,'قَالَ أَلْقُوا۟ ۖ فَلَمَّآ أَلْقَوْا۟ سَحَرُوٓا۟ أَعْيُنَ ٱلنَّاسِ وَٱسْتَرْهَبُوهُمْ وَجَآءُو بِسِحْرٍ عَظِيمٍ','Qaala alqoo falam maaa alqaw saharooo a\'yunannaasi wastarhaboohum wa jaaa\'oo bisihrin \'azeem',116,'7:116',17,65,135,2,0,164,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1071,7,'۞ وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنْ أَلْقِ عَصَاكَ ۖ فَإِذَا هِىَ تَلْقَفُ مَا يَأْفِكُونَ','Wa awhainaaa ilaa Moosaaa an alqi \'asaaka fa izaa hiya talqafu maa yaafikoon',117,'7:117',17,66,135,2,0,164,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1072,7,'فَوَقَعَ ٱلْحَقُّ وَبَطَلَ مَا كَانُوا۟ يَعْمَلُونَ','Fawaqa\'al haqqu wa batala maa kaanoo ya\'maloon',118,'7:118',17,66,135,2,0,164,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1073,7,'فَغُلِبُوا۟ هُنَالِكَ وَٱنقَلَبُوا۟ صَـٰغِرِينَ','Faghuliboo hunaalika wanqalaboo saaghireen',119,'7:119',17,66,135,2,0,164,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1074,7,'وَأُلْقِىَ ٱلسَّحَرَةُ سَـٰجِدِينَ','Wa ulqiyas saharatu saajideen',120,'7:120',17,66,135,2,0,164,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1075,7,'قَالُوٓا۟ ءَامَنَّا بِرَبِّ ٱلْعَـٰلَمِينَ','Qaaloo aamannaa bi Rabbil \'aalameen',121,'7:121',17,66,135,2,0,165,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1076,7,'رَبِّ مُوسَىٰ وَهَـٰرُونَ','Rabbi Moosaa wa Haaroon',122,'7:122',17,66,135,2,0,165,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1077,7,'قَالَ فِرْعَوْنُ ءَامَنتُم بِهِۦ قَبْلَ أَنْ ءَاذَنَ لَكُمْ ۖ إِنَّ هَـٰذَا لَمَكْرٌ مَّكَرْتُمُوهُ فِى ٱلْمَدِينَةِ لِتُخْرِجُوا۟ مِنْهَآ أَهْلَهَا ۖ فَسَوْفَ تَعْلَمُونَ','Qaala Fir\'awnu aamantum bihee qabla an aazana lakum; inna haaza lamakrum makartumoohu filmadeenati litukhrijoo minhaaa ahlahaa fasawfa ta\'almoon',123,'7:123',17,66,135,2,0,165,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1078,7,'لَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَـٰفٍ ثُمَّ لَأُصَلِّبَنَّكُمْ أَجْمَعِينَ','La uqatti\'anna aidiyakum wa arjulakum min khilaafin summa la usallibannakum ajma\'een',124,'7:124',17,66,135,2,0,165,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1079,7,'قَالُوٓا۟ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ','Qaaloo innaaa ilaa Rabbinaa munqaliboon',125,'7:125',17,66,135,2,0,165,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1080,7,'وَمَا تَنقِمُ مِنَّآ إِلَّآ أَنْ ءَامَنَّا بِـَٔايَـٰتِ رَبِّنَا لَمَّا جَآءَتْنَا ۚ رَبَّنَآ أَفْرِغْ عَلَيْنَا صَبْرًا وَتَوَفَّنَا مُسْلِمِينَ','Wa maa tanqimu minnaaa illaaa an aamannaa bi Aayaati Rabbinaa lammaa jaaa\'atnaa; Rabbanaaa afrigh \'alainaa sabranw wa tawaffanaa muslimeen',126,'7:126',17,66,135,2,0,165,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1081,7,'وَقَالَ ٱلْمَلَأُ مِن قَوْمِ فِرْعَوْنَ أَتَذَرُ مُوسَىٰ وَقَوْمَهُۥ لِيُفْسِدُوا۟ فِى ٱلْأَرْضِ وَيَذَرَكَ وَءَالِهَتَكَ ۚ قَالَ سَنُقَتِّلُ أَبْنَآءَهُمْ وَنَسْتَحْىِۦ نِسَآءَهُمْ وَإِنَّا فَوْقَهُمْ قَـٰهِرُونَ','Wa qaalal mala-u min qawmi Fir\'awna atazaru Moosaa wa qawmahoo liyufsidoo fil ardi wa yazaraka wa aalihatak; qaala sanuqattilu abnaaa \'ahum wa nastahyee nisaaa\'ahum wa innaa fawqahum qaahiroon',127,'7:127',17,66,136,2,0,165,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1082,7,'قَالَ مُوسَىٰ لِقَوْمِهِ ٱسْتَعِينُوا۟ بِٱللَّهِ وَٱصْبِرُوٓا۟ ۖ إِنَّ ٱلْأَرْضَ لِلَّهِ يُورِثُهَا مَن يَشَآءُ مِنْ عِبَادِهِۦ ۖ وَٱلْعَـٰقِبَةُ لِلْمُتَّقِينَ','Qaala Moosaa liqawmihis ta\'eenoo billaahi wasbiroo innal arda lillaahi yoorisuhaa mai yashaaa\'u min \'ibaadihee wal \'aaqibatu lilmuttaqeen',128,'7:128',17,66,136,2,0,165,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1083,7,'قَالُوٓا۟ أُوذِينَا مِن قَبْلِ أَن تَأْتِيَنَا وَمِنۢ بَعْدِ مَا جِئْتَنَا ۚ قَالَ عَسَىٰ رَبُّكُمْ أَن يُهْلِكَ عَدُوَّكُمْ وَيَسْتَخْلِفَكُمْ فِى ٱلْأَرْضِ فَيَنظُرَ كَيْفَ تَعْمَلُونَ','Qaaloo oozeenaa min qabli an taatiyanaa wa mim ba\'di maa ji\'tanaa; qaala \'asaa Rabbukum ai yuhlika \'aduwwakum wa yastakhli fakum fil ardi fayanzura kaifa ta\'maloon',129,'7:129',17,66,136,2,0,165,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1084,7,'وَلَقَدْ أَخَذْنَآ ءَالَ فِرْعَوْنَ بِٱلسِّنِينَ وَنَقْصٍ مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمْ يَذَّكَّرُونَ','Wa laqad akhaznaaa Aala Fir\'awna bis sineena wa naqsim minas samaraati la\'allahum yazzakkaroon',130,'7:130',17,66,137,2,0,165,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1085,7,'فَإِذَا جَآءَتْهُمُ ٱلْحَسَنَةُ قَالُوا۟ لَنَا هَـٰذِهِۦ ۖ وَإِن تُصِبْهُمْ سَيِّئَةٌ يَطَّيَّرُوا۟ بِمُوسَىٰ وَمَن مَّعَهُۥٓ ۗ أَلَآ إِنَّمَا طَـٰٓئِرُهُمْ عِندَ ٱللَّهِ وَلَـٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ','Fa izaa jaaa\'at humul hasanatu qaaloo lanaa haazihee wa in tusibhum saiyi\'atuny yattaiyaroo bi Moosaa wa mam ma\'ah; alaaa innamaa taaa\'iruhum \'indal laahi wa laakinna aksarahum laa ya\'lamoon',131,'7:131',17,66,137,2,0,166,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1086,7,'وَقَالُوا۟ مَهْمَا تَأْتِنَا بِهِۦ مِنْ ءَايَةٍ لِّتَسْحَرَنَا بِهَا فَمَا نَحْنُ لَكَ بِمُؤْمِنِينَ','Wa qaaloo mahmaa taatinaa bihee min Aayatil litasharanaa bihaa famaa nahnu laka bimu\'mineen',132,'7:132',17,66,137,2,0,166,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1087,7,'فَأَرْسَلْنَا عَلَيْهِمُ ٱلطُّوفَانَ وَٱلْجَرَادَ وَٱلْقُمَّلَ وَٱلضَّفَادِعَ وَٱلدَّمَ ءَايَـٰتٍ مُّفَصَّلَـٰتٍ فَٱسْتَكْبَرُوا۟ وَكَانُوا۟ قَوْمًا مُّجْرِمِينَ','Fa arsalnaa \'alaihimut toofaana waljaraada walqum mala waddafaadi\'a waddama Aayaatim mufassalaatin fastakbaroo wa kaanoo qawmam mujrimeen',133,'7:133',17,66,137,2,0,166,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1088,7,'وَلَمَّا وَقَعَ عَلَيْهِمُ ٱلرِّجْزُ قَالُوا۟ يَـٰمُوسَى ٱدْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ ۖ لَئِن كَشَفْتَ عَنَّا ٱلرِّجْزَ لَنُؤْمِنَنَّ لَكَ وَلَنُرْسِلَنَّ مَعَكَ بَنِىٓ إِسْرَٰٓءِيلَ','Wa lammaa waqa\'a \'alaihimur rijzu qaaloo ya Moosad-u lanaa rabbaka bimaa \'ahida \'indaka la\'in kashafta \'annar rijza lanu \'minanna laka wa lanursilanna ma\'aka Banee Israaa\'eel',134,'7:134',17,66,137,2,0,166,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1089,7,'فَلَمَّا كَشَفْنَا عَنْهُمُ ٱلرِّجْزَ إِلَىٰٓ أَجَلٍ هُم بَـٰلِغُوهُ إِذَا هُمْ يَنكُثُونَ','Falammaa kashafnaa \'anhumur rijza ilaaa ajalin hum baalighoohu izaa hum yankusoon',135,'7:135',17,66,137,2,0,166,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1090,7,'فَٱنتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَـٰهُمْ فِى ٱلْيَمِّ بِأَنَّهُمْ كَذَّبُوا۟ بِـَٔايَـٰتِنَا وَكَانُوا۟ عَنْهَا غَـٰفِلِينَ','Fantaqamnaa minhum fa aghraqnaahum kazzaboo bi Aayaatinaa wa kaanoo \'anhaa ghaafileen',136,'7:136',17,66,137,2,0,166,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1091,7,'وَأَوْرَثْنَا ٱلْقَوْمَ ٱلَّذِينَ كَانُوا۟ يُسْتَضْعَفُونَ مَشَـٰرِقَ ٱلْأَرْضِ وَمَغَـٰرِبَهَا ٱلَّتِى بَـٰرَكْنَا فِيهَا ۖ وَتَمَّتْ كَلِمَتُ رَبِّكَ ٱلْحُسْنَىٰ عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ بِمَا صَبَرُوا۟ ۖ وَدَمَّرْنَا مَا كَانَ يَصْنَعُ فِرْعَوْنُ وَقَوْمُهُۥ وَمَا كَانُوا۟ يَعْرِشُونَ','Wa awrasnal qawmal lazeena kaanoo yustad\'afoona mashaariqal ardi wa maghaari bahal latee baaraknaa feehaa wa tammat kalimatu Rabbikal husnaa \'alaa Baneee Israaa\'eela bimaa sabaroo wa dammarnaa maa kaana yasna\'u Fir\'awnu wa qawmuhoo wa maa kaanoo ya\'rishoon',137,'7:137',17,66,137,2,0,166,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1092,7,'وَجَـٰوَزْنَا بِبَنِىٓ إِسْرَٰٓءِيلَ ٱلْبَحْرَ فَأَتَوْا۟ عَلَىٰ قَوْمٍ يَعْكُفُونَ عَلَىٰٓ أَصْنَامٍ لَّهُمْ ۚ قَالُوا۟ يَـٰمُوسَى ٱجْعَل لَّنَآ إِلَـٰهًا كَمَا لَهُمْ ءَالِهَةٌ ۚ قَالَ إِنَّكُمْ قَوْمٌ تَجْهَلُونَ','Wa jaawaznaa bi Banneee Israaa\'eelal bahra fa ataw \'alaa qawminy ya\'kufoona \'alaaa asnaamil lahum; qaaloo yaa Moosaj\'al lanaa ilaahan kamaa lahum aalihah; qaala innakum qawmun tajhaloon',138,'7:138',17,66,137,2,0,167,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1093,7,'إِنَّ هَـٰٓؤُلَآءِ مُتَبَّرٌ مَّا هُمْ فِيهِ وَبَـٰطِلٌ مَّا كَانُوا۟ يَعْمَلُونَ','Innaa haaa\'ulaaa\'i mutabbarum maa hum feehi wa baatilum maa kaanoo ya\'maloon',139,'7:139',17,66,137,2,0,167,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1094,7,'قَالَ أَغَيْرَ ٱللَّهِ أَبْغِيكُمْ إِلَـٰهًا وَهُوَ فَضَّلَكُمْ عَلَى ٱلْعَـٰلَمِينَ','Qaala a-ghairal laahi abgheekum ilaahanw wa Huwa faddalakum \'alal \'aalameen',140,'7:140',17,66,137,2,0,167,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1095,7,'وَإِذْ أَنجَيْنَـٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ ۖ يُقَتِّلُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ ۚ وَفِى ذَٰلِكُم بَلَآءٌ مِّن رَّبِّكُمْ عَظِيمٌ','Wa iz anjainaakum min Aali Fir\'awna yasoomoo nakum sooo\'al \'azaab, yuqattiloona abnaaa\'akum wa yastahyoona nisaaa\'akum; wa fee zaalikum balaaa\'um mir Rabbikum \'azeem',141,'7:141',17,66,137,2,0,167,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1096,7,'۞ وَوَٰعَدْنَا مُوسَىٰ ثَلَـٰثِينَ لَيْلَةً وَأَتْمَمْنَـٰهَا بِعَشْرٍ فَتَمَّ مِيقَـٰتُ رَبِّهِۦٓ أَرْبَعِينَ لَيْلَةً ۚ وَقَالَ مُوسَىٰ لِأَخِيهِ هَـٰرُونَ ٱخْلُفْنِى فِى قَوْمِى وَأَصْلِحْ وَلَا تَتَّبِعْ سَبِيلَ ٱلْمُفْسِدِينَ','Wa waa\'adnaa Moosaa salaaseena lailatanw wa at mamnaahaa bi\'ashrim fatamma meeqaatu Rabbihee arba\'eena lailah; wa qaala Moosaa liakheehi Haaroonakh lufnee fee qawmee wa aslih wa laa tattabi\' sabeelal mufsideen',142,'7:142',17,67,138,2,0,167,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1097,7,'وَلَمَّا جَآءَ مُوسَىٰ لِمِيقَـٰتِنَا وَكَلَّمَهُۥ رَبُّهُۥ قَالَ رَبِّ أَرِنِىٓ أَنظُرْ إِلَيْكَ ۚ قَالَ لَن تَرَىٰنِى وَلَـٰكِنِ ٱنظُرْ إِلَى ٱلْجَبَلِ فَإِنِ ٱسْتَقَرَّ مَكَانَهُۥ فَسَوْفَ تَرَىٰنِى ۚ فَلَمَّا تَجَلَّىٰ رَبُّهُۥ لِلْجَبَلِ جَعَلَهُۥ دَكًّا وَخَرَّ مُوسَىٰ صَعِقًا ۚ فَلَمَّآ أَفَاقَ قَالَ سُبْحَـٰنَكَ تُبْتُ إِلَيْكَ وَأَنَا۠ أَوَّلُ ٱلْمُؤْمِنِينَ','Wa lammaa jaaa\'a Moosa limeeqaatinaa wa kallamahoo Rabbuhoo qaala Rabbi arineee anzur ilaik; qaala lan taraanee wa laakininzur ilal jabali fa inistaqarra makaanahoo faswfa taraanee; falammaa tajallaa Rabbuhoo liljabali ja\'alahoo dakkanw wa kharra Moosaa sa\'iqaa; falammaaa afaaqa qaala Subhaanaka tubtu ilaika wa ana awwalul mu\'mineen',143,'7:143',17,67,138,2,0,167,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1098,7,'قَالَ يَـٰمُوسَىٰٓ إِنِّى ٱصْطَفَيْتُكَ عَلَى ٱلنَّاسِ بِرِسَـٰلَـٰتِى وَبِكَلَـٰمِى فَخُذْ مَآ ءَاتَيْتُكَ وَكُن مِّنَ ٱلشَّـٰكِرِينَ','Qaala yaa Moosaaa innis tafaituka \'alan naasi bi Risaalaatee wa bi kalaamee fakhuz maaa aataituka wa kum minash shaakireen',144,'7:144',17,67,138,2,0,168,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1099,7,'وَكَتَبْنَا لَهُۥ فِى ٱلْأَلْوَاحِ مِن كُلِّ شَىْءٍ مَّوْعِظَةً وَتَفْصِيلًا لِّكُلِّ شَىْءٍ فَخُذْهَا بِقُوَّةٍ وَأْمُرْ قَوْمَكَ يَأْخُذُوا۟ بِأَحْسَنِهَا ۚ سَأُو۟رِيكُمْ دَارَ ٱلْفَـٰسِقِينَ','Wa katabnaa lahoo fil alwaahi minkulli shai\'immaw \'izaanw wa tafseelal likulli shai\'in fakhuzhaa biquwwatinw waamur qawmaka yaakhuzoo bi ahsanihaa; wa ooreekum daaral faasiqeen',145,'7:145',17,67,138,2,0,168,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1100,7,'سَأَصْرِفُ عَنْ ءَايَـٰتِىَ ٱلَّذِينَ يَتَكَبَّرُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَإِن يَرَوْا۟ كُلَّ ءَايَةٍ لَّا يُؤْمِنُوا۟ بِهَا وَإِن يَرَوْا۟ سَبِيلَ ٱلرُّشْدِ لَا يَتَّخِذُوهُ سَبِيلًا وَإِن يَرَوْا۟ سَبِيلَ ٱلْغَىِّ يَتَّخِذُوهُ سَبِيلًا ۚ ذَٰلِكَ بِأَنَّهُمْ كَذَّبُوا۟ بِـَٔايَـٰتِنَا وَكَانُوا۟ عَنْهَا غَـٰفِلِينَ','Sa asrifu \'an Aayaatiyal lazeena yatakabbaroona fil ardi bighairil haqq; wa iny-yaraw kulla Aayatil laa yu\'minoo bihaa wa iny-yaraw sabeelar rushdi laa yattakhizoohu sabeelanw wa iny-yaraw sabeelal ghaiyi yatta khizoohu sabeelaa; zaalika bi annahum kazzaboo bi Aayaatinaa wa kaanoo \'anhaa ghaafileen',146,'7:146',17,67,138,2,0,168,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1101,7,'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا وَلِقَآءِ ٱلْـَٔاخِرَةِ حَبِطَتْ أَعْمَـٰلُهُمْ ۚ هَلْ يُجْزَوْنَ إِلَّا مَا كَانُوا۟ يَعْمَلُونَ','Wallazeena kazzaboo bi Aayaatinaa wa liqaaa\'il Aakhirati habitat \'amaaluhum; hal yujzawna illaa maa kaanoo ya\'maloon',147,'7:147',17,67,138,2,0,168,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1102,7,'وَٱتَّخَذَ قَوْمُ مُوسَىٰ مِنۢ بَعْدِهِۦ مِنْ حُلِيِّهِمْ عِجْلًا جَسَدًا لَّهُۥ خُوَارٌ ۚ أَلَمْ يَرَوْا۟ أَنَّهُۥ لَا يُكَلِّمُهُمْ وَلَا يَهْدِيهِمْ سَبِيلًا ۘ ٱتَّخَذُوهُ وَكَانُوا۟ ظَـٰلِمِينَ','Wattakhaza qawmu Moosaa mim ba\'dihee min huliyyihim \'ijlan jasadal lahoo khuwaar; alam yaraw annahoo laa yukallimuhum wa laa yahdeehim sabeelaa; ittakha zoohu wa kaanoo zaalimeen',148,'7:148',17,67,139,2,0,168,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1103,7,'وَلَمَّا سُقِطَ فِىٓ أَيْدِيهِمْ وَرَأَوْا۟ أَنَّهُمْ قَدْ ضَلُّوا۟ قَالُوا۟ لَئِن لَّمْ يَرْحَمْنَا رَبُّنَا وَيَغْفِرْ لَنَا لَنَكُونَنَّ مِنَ ٱلْخَـٰسِرِينَ','Wa lammaa suqita feee aideehim wa ra aw annahum qad dalloo qaaloo la\'il lam yarhamnaa Rabbunaa wa yaghfir lanaa lanakoonanna minal khaasireen',149,'7:149',17,67,139,2,0,168,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1104,7,'وَلَمَّا رَجَعَ مُوسَىٰٓ إِلَىٰ قَوْمِهِۦ غَضْبَـٰنَ أَسِفًا قَالَ بِئْسَمَا خَلَفْتُمُونِى مِنۢ بَعْدِىٓ ۖ أَعَجِلْتُمْ أَمْرَ رَبِّكُمْ ۖ وَأَلْقَى ٱلْأَلْوَاحَ وَأَخَذَ بِرَأْسِ أَخِيهِ يَجُرُّهُۥٓ إِلَيْهِ ۚ قَالَ ٱبْنَ أُمَّ إِنَّ ٱلْقَوْمَ ٱسْتَضْعَفُونِى وَكَادُوا۟ يَقْتُلُونَنِى فَلَا تُشْمِتْ بِىَ ٱلْأَعْدَآءَ وَلَا تَجْعَلْنِى مَعَ ٱلْقَوْمِ ٱلظَّـٰلِمِينَ','Wa lammaa raja\'a Moosaaa ilaa qawmihee ghadbaana asifan qaala bi\'samaa khalaftumoonee mim ba\'dee a-\'ajiltum amra Rabbikum wa alqal alwaaha wa akhaza biraasi akheehi yajurruhoo ilaih; qaalab na umma innal qawmas tad\'afoonee wa kadoo yaqtu loonanee; falaa tushmit biyal a\'daaa\'a wa laa taj\'alnee ma\'al qawmiz zaalimeen',150,'7:150',17,67,139,2,0,169,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1105,7,'قَالَ رَبِّ ٱغْفِرْ لِى وَلِأَخِى وَأَدْخِلْنَا فِى رَحْمَتِكَ ۖ وَأَنتَ أَرْحَمُ ٱلرَّٰحِمِينَ','Qaala Rabbigh fir lee wa li akhee wa adkhilnaa fee rahmatika wa Anta arhamur raahimeen',151,'7:151',17,67,139,2,0,169,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1106,7,'إِنَّ ٱلَّذِينَ ٱتَّخَذُوا۟ ٱلْعِجْلَ سَيَنَالُهُمْ غَضَبٌ مِّن رَّبِّهِمْ وَذِلَّةٌ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۚ وَكَذَٰلِكَ نَجْزِى ٱلْمُفْتَرِينَ','Innal lazeenat takhazul \'ijla-sa yanaaluhum ghadabum mir Rabbihim wa zillatun fil hayaatid dunyaa; wa kazaalika najzil muftareen',152,'7:152',17,67,140,2,0,169,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1107,7,'وَٱلَّذِينَ عَمِلُوا۟ ٱلسَّيِّـَٔاتِ ثُمَّ تَابُوا۟ مِنۢ بَعْدِهَا وَءَامَنُوٓا۟ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورٌ رَّحِيمٌ','Wallazeena \'amilus saiyiaati summa taaboo mim ba\'dihaa wa aamanooo inna Rabbaka mim ba\'dihaa la Ghafoorur Raheem',153,'7:153',17,67,140,2,0,169,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1108,7,'وَلَمَّا سَكَتَ عَن مُّوسَى ٱلْغَضَبُ أَخَذَ ٱلْأَلْوَاحَ ۖ وَفِى نُسْخَتِهَا هُدًى وَرَحْمَةٌ لِّلَّذِينَ هُمْ لِرَبِّهِمْ يَرْهَبُونَ','Wa lammaa sakata \'am Moosal ghadabu akhazal al waaha wa fee nnuskhatihaa hudanw wa rahmatul lillazeena hum li Rabbihim yarhaboon',154,'7:154',17,67,140,2,0,169,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1109,7,'وَٱخْتَارَ مُوسَىٰ قَوْمَهُۥ سَبْعِينَ رَجُلًا لِّمِيقَـٰتِنَا ۖ فَلَمَّآ أَخَذَتْهُمُ ٱلرَّجْفَةُ قَالَ رَبِّ لَوْ شِئْتَ أَهْلَكْتَهُم مِّن قَبْلُ وَإِيَّـٰىَ ۖ أَتُهْلِكُنَا بِمَا فَعَلَ ٱلسُّفَهَآءُ مِنَّآ ۖ إِنْ هِىَ إِلَّا فِتْنَتُكَ تُضِلُّ بِهَا مَن تَشَآءُ وَتَهْدِى مَن تَشَآءُ ۖ أَنتَ وَلِيُّنَا فَٱغْفِرْ لَنَا وَٱرْحَمْنَا ۖ وَأَنتَ خَيْرُ ٱلْغَـٰفِرِينَ','Wakhtaara Moosaa qawmahoo sab\'eena rajjulal limeeqaatinaa falammaa akhazat humur rajfatu qaala Rabbi law shi\'ta ahlaktahum min qablu wa iyyaaya atuhlikunna bimaa fa\'alas sufahaaa\'u minnaa in hiya illaa fitnatuka tudillu bihaa man tashaaa\'u wa tahdee man tashaaa\'u Anta waliyyunaa faghfir lanaa warhammnnaa wa Anta khairul ghaafireen',155,'7:155',17,67,140,2,0,169,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1110,7,'۞ وَٱكْتُبْ لَنَا فِى هَـٰذِهِ ٱلدُّنْيَا حَسَنَةً وَفِى ٱلْـَٔاخِرَةِ إِنَّا هُدْنَآ إِلَيْكَ ۚ قَالَ عَذَابِىٓ أُصِيبُ بِهِۦ مَنْ أَشَآءُ ۖ وَرَحْمَتِى وَسِعَتْ كُلَّ شَىْءٍ ۚ فَسَأَكْتُبُهَا لِلَّذِينَ يَتَّقُونَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَٱلَّذِينَ هُم بِـَٔايَـٰتِنَا يُؤْمِنُونَ','Waktub lanaa fee haazi hid dunyaa hasanatanw wa fil Aakhirati innnaa hudnaaa ilaik; qaala \'azaabee useebu bihee man ashaaa\'u wa rahmatee wasi\'at kulla shai\'; fasa aktubuhaa lillazeena yattaqoona wa yu\'toonaz Zakaata wallazeena hum bi Aayaatinaa yu\'minoon',156,'7:156',17,68,140,2,0,170,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1111,7,'ٱلَّذِينَ يَتَّبِعُونَ ٱلرَّسُولَ ٱلنَّبِىَّ ٱلْأُمِّىَّ ٱلَّذِى يَجِدُونَهُۥ مَكْتُوبًا عِندَهُمْ فِى ٱلتَّوْرَىٰةِ وَٱلْإِنجِيلِ يَأْمُرُهُم بِٱلْمَعْرُوفِ وَيَنْهَىٰهُمْ عَنِ ٱلْمُنكَرِ وَيُحِلُّ لَهُمُ ٱلطَّيِّبَـٰتِ وَيُحَرِّمُ عَلَيْهِمُ ٱلْخَبَـٰٓئِثَ وَيَضَعُ عَنْهُمْ إِصْرَهُمْ وَٱلْأَغْلَـٰلَ ٱلَّتِى كَانَتْ عَلَيْهِمْ ۚ فَٱلَّذِينَ ءَامَنُوا۟ بِهِۦ وَعَزَّرُوهُ وَنَصَرُوهُ وَٱتَّبَعُوا۟ ٱلنُّورَ ٱلَّذِىٓ أُنزِلَ مَعَهُۥٓ ۙ أُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ','Allazeena yattabi\'oonar Rasoolan Nabiyyal ummiyyal lazee yajidoonahoo maktooban \'indahum fit Tawraati wal Injeeli yaa muruhum bilma\'roofi wa yanhaahum \'anil munkari wa yuhillu lahumul taiyibaati wa yuharrimu \'alaihimul khabaaa\'isa wa yada\'u \'anhum israhum wal aghlaalal latee kaanat \'alaihim; fallazeena aamanoo bihee wa \'azzaroohu wa nnasaroohu wattaba\'un nooral lazeee unzila ma\'ahooo ulaaa\'ika humul muflihoon',157,'7:157',17,68,140,2,0,170,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1112,7,'قُلْ يَـٰٓأَيُّهَا ٱلنَّاسُ إِنِّى رَسُولُ ٱللَّهِ إِلَيْكُمْ جَمِيعًا ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ لَآ إِلَـٰهَ إِلَّا هُوَ يُحْىِۦ وَيُمِيتُ ۖ فَـَٔامِنُوا۟ بِٱللَّهِ وَرَسُولِهِ ٱلنَّبِىِّ ٱلْأُمِّىِّ ٱلَّذِى يُؤْمِنُ بِٱللَّهِ وَكَلِمَـٰتِهِۦ وَٱتَّبِعُوهُ لَعَلَّكُمْ تَهْتَدُونَ','Qul yaaa aiyuhan naasu innee Rasoohul laahi ilaikum jamee\'anil lazee lahoo mulkus samaawaati wal ardi laaa ilaaha illaa Huwa yuhyee wa yumeetu fa aaminoo billaahi wa Rasoolihin Nabiyyil ummiy yil lazee yu\'minu billaahi wa Kalimaatihee wattabi\'oohu la\'allakum tahtadoon',158,'7:158',17,68,141,2,0,170,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1113,7,'وَمِن قَوْمِ مُوسَىٰٓ أُمَّةٌ يَهْدُونَ بِٱلْحَقِّ وَبِهِۦ يَعْدِلُونَ','Wa min qawmi Moosaaa ummatuny yahdoona bilhaqqi wa bihee ya\'diloon',159,'7:159',17,68,141,2,0,170,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1114,7,'وَقَطَّعْنَـٰهُمُ ٱثْنَتَىْ عَشْرَةَ أَسْبَاطًا أُمَمًا ۚ وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ إِذِ ٱسْتَسْقَىٰهُ قَوْمُهُۥٓ أَنِ ٱضْرِب بِّعَصَاكَ ٱلْحَجَرَ ۖ فَٱنۢبَجَسَتْ مِنْهُ ٱثْنَتَا عَشْرَةَ عَيْنًا ۖ قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ ۚ وَظَلَّلْنَا عَلَيْهِمُ ٱلْغَمَـٰمَ وَأَنزَلْنَا عَلَيْهِمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ ۖ كُلُوا۟ مِن طَيِّبَـٰتِ مَا رَزَقْنَـٰكُمْ ۚ وَمَا ظَلَمُونَا وَلَـٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ','Wa qatta\' naahumus natai \'ashrata asbaatan umamaa; wa awhainaa ilaa Moosaaa izis tasqaahu qawmuhooo anid rib bi\'asaakal hajara fambajasat minhus nata \'ashrata \'ainan qad \'alima kullu unaasim mashrabahm; wa zallalnaa \'alaihimul ghammaamma wa anzalnaa \'alaihimul MManna was Salwaa kuloo min taiyibaati maa razaqnaakum; wa maa zalamoonaa wa laakin kaanooo anfusahum yazlimoon',160,'7:160',17,68,141,2,0,171,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1115,7,'وَإِذْ قِيلَ لَهُمُ ٱسْكُنُوا۟ هَـٰذِهِ ٱلْقَرْيَةَ وَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ وَقُولُوا۟ حِطَّةٌ وَٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًا نَّغْفِرْ لَكُمْ خَطِيٓـَٔـٰتِكُمْ ۚ سَنَزِيدُ ٱلْمُحْسِنِينَ','Wa iz qeela lahumuskunoo haazihil qaryata wa kuloo minhaa haisu shi\'tum wa qooloo hittatunw wadkhulul baaba sujjadan naghfir lakum khateee\'aatikum; sanazeedul muhsineen',161,'7:161',17,68,141,2,0,171,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1116,7,'فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ فَأَرْسَلْنَا عَلَيْهِمْ رِجْزًا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَظْلِمُونَ','Fabaddalal lazeena zalamoo minhum qawlan ghairal lazee qeela lahum fa arsalnaa \'alaihim rijzam minas samaaa\'i bimaa kaanoo yazlimoon',162,'7:162',17,68,141,2,0,171,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1117,7,'وَسْـَٔلْهُمْ عَنِ ٱلْقَرْيَةِ ٱلَّتِى كَانَتْ حَاضِرَةَ ٱلْبَحْرِ إِذْ يَعْدُونَ فِى ٱلسَّبْتِ إِذْ تَأْتِيهِمْ حِيتَانُهُمْ يَوْمَ سَبْتِهِمْ شُرَّعًا وَيَوْمَ لَا يَسْبِتُونَ ۙ لَا تَأْتِيهِمْ ۚ كَذَٰلِكَ نَبْلُوهُم بِمَا كَانُوا۟ يَفْسُقُونَ','Was\'alhum \'anil qaryatil latee kaanat haadiratal bahri iz ya\'doona fis Sabt iz taateehim heetaanuhum yawma Sabtihim shurra\'anw wa yawma laa yasbitoona laa taateehim; kazaalika nabloohum bimaa kaanoo yafsuqoon',163,'7:163',17,68,142,2,0,171,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1118,7,'وَإِذْ قَالَتْ أُمَّةٌ مِّنْهُمْ لِمَ تَعِظُونَ قَوْمًا ۙ ٱللَّهُ مُهْلِكُهُمْ أَوْ مُعَذِّبُهُمْ عَذَابًا شَدِيدًا ۖ قَالُوا۟ مَعْذِرَةً إِلَىٰ رَبِّكُمْ وَلَعَلَّهُمْ يَتَّقُونَ','Wa iz qaalat ummatum minhum lima ta\'izoona qaw manil laahu muhlikuhum aw mu\'azzibuhum \'azaaban shadeedan qaaloo ma\'ziratan ilaa Rabbikum wa la\'allahum tattaqoon',164,'7:164',17,68,142,2,0,172,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1119,7,'فَلَمَّا نَسُوا۟ مَا ذُكِّرُوا۟ بِهِۦٓ أَنجَيْنَا ٱلَّذِينَ يَنْهَوْنَ عَنِ ٱلسُّوٓءِ وَأَخَذْنَا ٱلَّذِينَ ظَلَمُوا۟ بِعَذَابٍۭ بَـِٔيسٍۭ بِمَا كَانُوا۟ يَفْسُقُونَ','Falammaa nasoo maa zukkiroo bihee anjainal lazeena yanhawna \'anis sooo\'i wa akhaznal lazeena zalamoo bi\'azaabim ba\'eeim bimaa kaanooyafsuqoon',165,'7:165',17,68,142,2,0,172,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1120,7,'فَلَمَّا عَتَوْا۟ عَن مَّا نُهُوا۟ عَنْهُ قُلْنَا لَهُمْ كُونُوا۟ قِرَدَةً خَـٰسِـِٔينَ','Falammaa \'ataw \'ammmaa nuhoo \'anhu qulna lahum kkoonoo qiradatan khaasi\'een',166,'7:166',17,68,142,2,0,172,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1121,7,'وَإِذْ تَأَذَّنَ رَبُّكَ لَيَبْعَثَنَّ عَلَيْهِمْ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ مَن يَسُومُهُمْ سُوٓءَ ٱلْعَذَابِ ۗ إِنَّ رَبَّكَ لَسَرِيعُ ٱلْعِقَابِ ۖ وَإِنَّهُۥ لَغَفُورٌ رَّحِيمٌ','Wa iz ta azzana Rabbuka la yab\'asannna \'alaihim ilaa Yawmil Qiyaamati mai yasoomuhum sooo\'al \'azaab; inna Rabbaka lasaree\'ul \'iqaab; wa innahoo la Ghafoorur Raheem',167,'7:167',17,68,142,2,0,172,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1122,7,'وَقَطَّعْنَـٰهُمْ فِى ٱلْأَرْضِ أُمَمًا ۖ مِّنْهُمُ ٱلصَّـٰلِحُونَ وَمِنْهُمْ دُونَ ذَٰلِكَ ۖ وَبَلَوْنَـٰهُم بِٱلْحَسَنَـٰتِ وَٱلسَّيِّـَٔاتِ لَعَلَّهُمْ يَرْجِعُونَ','Wa qatta\'naahum fil ardi umamam minhumus aalihoona wa min hum doona zaalika wa balawnaahum bilhasanaati wassaiyi aati la\'allahum yarji\'oon',168,'7:168',17,68,142,2,0,172,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1123,7,'فَخَلَفَ مِنۢ بَعْدِهِمْ خَلْفٌ وَرِثُوا۟ ٱلْكِتَـٰبَ يَأْخُذُونَ عَرَضَ هَـٰذَا ٱلْأَدْنَىٰ وَيَقُولُونَ سَيُغْفَرُ لَنَا وَإِن يَأْتِهِمْ عَرَضٌ مِّثْلُهُۥ يَأْخُذُوهُ ۚ أَلَمْ يُؤْخَذْ عَلَيْهِم مِّيثَـٰقُ ٱلْكِتَـٰبِ أَن لَّا يَقُولُوا۟ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ وَدَرَسُوا۟ مَا فِيهِ ۗ وَٱلدَّارُ ٱلْـَٔاخِرَةُ خَيْرٌ لِّلَّذِينَ يَتَّقُونَ ۗ أَفَلَا تَعْقِلُونَ','Fakhalafa mim ba\'dihim khalfunw warisul Kitaaba yaa khuzoona \'arada haazal adnaa wa yaqooloona sayughfaru lanaa wa iny yaatihim \'aradum misluhoo yaakhuzooh; alam yu\'khaz \'alaihim \'aradum misluhoo yaakhuzooh; alam yu\'khaz \'alaihim meesaaqul Kitaabi al laa yaqooloo \'alal laahi illal haqqa wa darasoo maa feeh; wad Daarul Aakhirtu khairul lillazeena yattaqoon; afalaa ta\'qiloon',169,'7:169',17,68,142,2,0,172,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1124,7,'وَٱلَّذِينَ يُمَسِّكُونَ بِٱلْكِتَـٰبِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ إِنَّا لَا نُضِيعُ أَجْرَ ٱلْمُصْلِحِينَ','Wallazeena yumas sikoona bil Kitaabi wa aqaamus Salaata innaa laa nudee\'uajral musliheen',170,'7:170',17,68,142,2,0,172,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1125,7,'۞ وَإِذْ نَتَقْنَا ٱلْجَبَلَ فَوْقَهُمْ كَأَنَّهُۥ ظُلَّةٌ وَظَنُّوٓا۟ أَنَّهُۥ وَاقِعٌۢ بِهِمْ خُذُوا۟ مَآ ءَاتَيْنَـٰكُم بِقُوَّةٍ وَٱذْكُرُوا۟ مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ','Wa iz nataqnal jabala fawqahum ka annahoo zullatunw wa zannooo annahoo waaqi\'um bihim khuzoo maaa aatainaakum biquwwatinw wazkuroo maa feehi la\'allakum tattaqoon',171,'7:171',18,69,142,2,0,173,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1126,7,'وَإِذْ أَخَذَ رَبُّكَ مِنۢ بَنِىٓ ءَادَمَ مِن ظُهُورِهِمْ ذُرِّيَّتَهُمْ وَأَشْهَدَهُمْ عَلَىٰٓ أَنفُسِهِمْ أَلَسْتُ بِرَبِّكُمْ ۖ قَالُوا۟ بَلَىٰ ۛ شَهِدْنَآ ۛ أَن تَقُولُوا۟ يَوْمَ ٱلْقِيَـٰمَةِ إِنَّا كُنَّا عَنْ هَـٰذَا غَـٰفِلِينَ','Wa iz akhaza Rabbuka mim Baneee Aadama min zuhoorihim zurriyyatahum wa ash hadahum \'alaa anfusihim alastu bi Rabbikum qaaloo balaa shahidnaaa; an taqooloo Yawmal Qiyaamati innaa kunnaa \'an haazaa ghaafileen',172,'7:172',18,69,143,2,0,173,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1127,7,'أَوْ تَقُولُوٓا۟ إِنَّمَآ أَشْرَكَ ءَابَآؤُنَا مِن قَبْلُ وَكُنَّا ذُرِّيَّةً مِّنۢ بَعْدِهِمْ ۖ أَفَتُهْلِكُنَا بِمَا فَعَلَ ٱلْمُبْطِلُونَ','Aw taqoolooo innamaaa ashraka aabaaa \'unaa min qablu wa kunnaa zurriyyatam mim ba\'dihim afatuhlikunna bimaa fa\'alal mubtiloon',173,'7:173',18,69,143,2,0,173,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1128,7,'وَكَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَـٰتِ وَلَعَلَّهُمْ يَرْجِعُونَ','Wa kazaalika nufassihul Aayaati wa la\'allahum yarji\'oon',174,'7:174',18,69,143,2,0,173,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1129,7,'وَٱتْلُ عَلَيْهِمْ نَبَأَ ٱلَّذِىٓ ءَاتَيْنَـٰهُ ءَايَـٰتِنَا فَٱنسَلَخَ مِنْهَا فَأَتْبَعَهُ ٱلشَّيْطَـٰنُ فَكَانَ مِنَ ٱلْغَاوِينَ','Watlu \'alaihim naba allazeee aatainaahu Aayaatinaa fansalakha minhaa fa atba\'a hush Shaytaano fakaana minal ghaaween',175,'7:175',18,69,143,2,0,173,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1130,7,'وَلَوْ شِئْنَا لَرَفَعْنَـٰهُ بِهَا وَلَـٰكِنَّهُۥٓ أَخْلَدَ إِلَى ٱلْأَرْضِ وَٱتَّبَعَ هَوَىٰهُ ۚ فَمَثَلُهُۥ كَمَثَلِ ٱلْكَلْبِ إِن تَحْمِلْ عَلَيْهِ يَلْهَثْ أَوْ تَتْرُكْهُ يَلْهَث ۚ ذَّٰلِكَ مَثَلُ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا ۚ فَٱقْصُصِ ٱلْقَصَصَ لَعَلَّهُمْ يَتَفَكَّرُونَ','Wa law shi\'naa larafa\'naahu bihaa wa laakin nahooo akhlada ilal ardi watta ba\'a hawaah; famasaluhoo kamasalil kalb; in tahmil \'alaihi yalhas aw tatruk hu yalhas; zaalika masalul qawmil lazeena kazzaboo bi Aayaatinaa; faqsusil qasasa la\'allahum yatafakkaroon',176,'7:176',18,69,143,2,0,173,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1131,7,'سَآءَ مَثَلًا ٱلْقَوْمُ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا وَأَنفُسَهُمْ كَانُوا۟ يَظْلِمُونَ','Saaa\'a masalanil qawmul lazeena kazzaboo bi Aayaatinaa wa anfusahum kaanoo yazlimoon',177,'7:177',18,69,143,2,0,173,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1132,7,'مَن يَهْدِ ٱللَّهُ فَهُوَ ٱلْمُهْتَدِى ۖ وَمَن يُضْلِلْ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْخَـٰسِرُونَ','mai yahdil laahu fa huwal muhtadee wa mai yudlil fa ulaaa\'ika humul khaasiroon',178,'7:178',18,69,143,2,0,173,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1133,7,'وَلَقَدْ ذَرَأْنَا لِجَهَنَّمَ كَثِيرًا مِّنَ ٱلْجِنِّ وَٱلْإِنسِ ۖ لَهُمْ قُلُوبٌ لَّا يَفْقَهُونَ بِهَا وَلَهُمْ أَعْيُنٌ لَّا يُبْصِرُونَ بِهَا وَلَهُمْ ءَاذَانٌ لَّا يَسْمَعُونَ بِهَآ ۚ أُو۟لَـٰٓئِكَ كَٱلْأَنْعَـٰمِ بَلْ هُمْ أَضَلُّ ۚ أُو۟لَـٰٓئِكَ هُمُ ٱلْغَـٰفِلُونَ','Wa laqad zaraanaa li jahannama kaseeram minal jinni wal insi lahum quloobul laa yafqahoona bihaa wa lahum a\'yunul laa yubisiroona bihaa wa lahum aazaanul laa yasma\'oona bihaa; ulaaa\'ika kal an\'aami bal hum adall; ulaaa\'ika humul ghaafiloon',179,'7:179',18,69,143,2,0,174,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1134,7,'وَلِلَّهِ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ فَٱدْعُوهُ بِهَا ۖ وَذَرُوا۟ ٱلَّذِينَ يُلْحِدُونَ فِىٓ أَسْمَـٰٓئِهِۦ ۚ سَيُجْزَوْنَ مَا كَانُوا۟ يَعْمَلُونَ','Wa lillaahil Asmaaa \'ul Husnaa fad\'oohu bihaa wa zarul lazeena yulhidoona feee Asmaaa\'ih; sa yujzawna maa kaanoo ya\'maloon',180,'7:180',18,69,143,2,0,174,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1135,7,'وَمِمَّنْ خَلَقْنَآ أُمَّةٌ يَهْدُونَ بِٱلْحَقِّ وَبِهِۦ يَعْدِلُونَ','Wa mimman khalaqnaaa ummatuny yahdoona bilhaqqi wa bihee ya\'diloon',181,'7:181',18,69,143,2,0,174,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1136,7,'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا سَنَسْتَدْرِجُهُم مِّنْ حَيْثُ لَا يَعْلَمُونَ','Wallazeena kazzaboo bi Aayaatinaa sanastadrijuhum min haisu laa ya\'lamoon',182,'7:182',18,69,144,2,0,174,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1137,7,'وَأُمْلِى لَهُمْ ۚ إِنَّ كَيْدِى مَتِينٌ','Wa umlee lahum; inna kaidee mateen',183,'7:183',18,69,144,2,0,174,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1138,7,'أَوَلَمْ يَتَفَكَّرُوا۟ ۗ مَا بِصَاحِبِهِم مِّن جِنَّةٍ ۚ إِنْ هُوَ إِلَّا نَذِيرٌ مُّبِينٌ','Awalam yatafakkaroo maa bisaahibihim min jinnah; in huwa illaa nazeerum mubeen',184,'7:184',18,69,144,2,0,174,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1139,7,'أَوَلَمْ يَنظُرُوا۟ فِى مَلَكُوتِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا خَلَقَ ٱللَّهُ مِن شَىْءٍ وَأَنْ عَسَىٰٓ أَن يَكُونَ قَدِ ٱقْتَرَبَ أَجَلُهُمْ ۖ فَبِأَىِّ حَدِيثٍۭ بَعْدَهُۥ يُؤْمِنُونَ','Awalam yanzuroo fee malakootis samaawaati wal ardi wa maa khalaqal laahu min shai\'inw wa an \'asaaa ai yakoona qadiqtaraba ajaluhum fabi aiyi hadeesim ba\'dahoo yu\'minoon',185,'7:185',18,69,144,2,0,174,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1140,7,'مَن يُضْلِلِ ٱللَّهُ فَلَا هَادِىَ لَهُۥ ۚ وَيَذَرُهُمْ فِى طُغْيَـٰنِهِمْ يَعْمَهُونَ','Mai yadlilil laahu falaa haadiyaa lah; wa yazaruhum fee tughyaanihim ya\'mahoon',186,'7:186',18,69,144,2,0,174,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1141,7,'يَسْـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرْسَىٰهَا ۖ قُلْ إِنَّمَا عِلْمُهَا عِندَ رَبِّى ۖ لَا يُجَلِّيهَا لِوَقْتِهَآ إِلَّا هُوَ ۚ ثَقُلَتْ فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ لَا تَأْتِيكُمْ إِلَّا بَغْتَةً ۗ يَسْـَٔلُونَكَ كَأَنَّكَ حَفِىٌّ عَنْهَا ۖ قُلْ إِنَّمَا عِلْمُهَا عِندَ ٱللَّهِ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ','Yas\'aloonaka \'anis Saa\'ati aiyaana mursaahaa qul innamaa \'ilmuhaa \'inda Rabbee laa yujallaeehaa liwaqtihaaa illaa Hoo; saqulat fis samaawaati wal ard; laa taateekum illaa baghtah; yas\'aloonaka ka annaka hafiyyun \'anhaa qul innamaa \'ilmuhaa \'indal laahi wa laakinna aksaran naasi laa ya\'lamoon',187,'7:187',18,69,144,2,0,174,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1142,7,'قُل لَّآ أَمْلِكُ لِنَفْسِى نَفْعًا وَلَا ضَرًّا إِلَّا مَا شَآءَ ٱللَّهُ ۚ وَلَوْ كُنتُ أَعْلَمُ ٱلْغَيْبَ لَٱسْتَكْثَرْتُ مِنَ ٱلْخَيْرِ وَمَا مَسَّنِىَ ٱلسُّوٓءُ ۚ إِنْ أَنَا۠ إِلَّا نَذِيرٌ وَبَشِيرٌ لِّقَوْمٍ يُؤْمِنُونَ','Qul laaa amliku linafsee naf\'anw wa laa darran illaa maa shaaa\'al laah; wa law kuntu a\'alamul ghaiba lastaksartu minal khairi wa maa massaniyas soo\'; in ana illaa nazeerunw wa basheerul liqawminy yu\'minoon',188,'7:188',18,69,144,2,0,175,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1143,7,'۞ هُوَ ٱلَّذِى خَلَقَكُم مِّن نَّفْسٍ وَٰحِدَةٍ وَجَعَلَ مِنْهَا زَوْجَهَا لِيَسْكُنَ إِلَيْهَا ۖ فَلَمَّا تَغَشَّىٰهَا حَمَلَتْ حَمْلًا خَفِيفًا فَمَرَّتْ بِهِۦ ۖ فَلَمَّآ أَثْقَلَت دَّعَوَا ٱللَّهَ رَبَّهُمَا لَئِنْ ءَاتَيْتَنَا صَـٰلِحًا لَّنَكُونَنَّ مِنَ ٱلشَّـٰكِرِينَ','Huwal lazee khalaqakum min nafsinw waahidatinw wa ja\'ala minhaa zawjahaa liyas kuna ilaihaa falammaa taghash shaahaa hamalat hamlan khafeefan famarrat bihee falammaaa asqalad da\'awal laaha Rabbahumaa la\'in aayaitanaa saalihal lanakoo nanna minash shaakireen',189,'7:189',18,70,145,2,0,175,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1144,7,'فَلَمَّآ ءَاتَىٰهُمَا صَـٰلِحًا جَعَلَا لَهُۥ شُرَكَآءَ فِيمَآ ءَاتَىٰهُمَا ۚ فَتَعَـٰلَى ٱللَّهُ عَمَّا يُشْرِكُونَ','Falammaaa aataahumaa saalihan ja\'alaa lahoo shurakaaa\'a feemaaa aataahumaa; fata\'aalal laahu \'ammaa yushrikoon',190,'7:190',18,70,145,2,0,175,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1145,7,'أَيُشْرِكُونَ مَا لَا يَخْلُقُ شَيْـًٔا وَهُمْ يُخْلَقُونَ','A yushrikoona maa laa yakhluqu shai\'anw wa hum yukhlaqoon',191,'7:191',18,70,145,2,0,175,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1146,7,'وَلَا يَسْتَطِيعُونَ لَهُمْ نَصْرًا وَلَآ أَنفُسَهُمْ يَنصُرُونَ','Wa laa yastatee\'oona lahum nasranw wa laaa anfusahum yansuroon',192,'7:192',18,70,145,2,0,175,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1147,7,'وَإِن تَدْعُوهُمْ إِلَى ٱلْهُدَىٰ لَا يَتَّبِعُوكُمْ ۚ سَوَآءٌ عَلَيْكُمْ أَدَعَوْتُمُوهُمْ أَمْ أَنتُمْ صَـٰمِتُونَ','Wa in tad\'oohum ilalhudaa laa yattabi\'ookum; sawaaa\'un \'alaikum a-da\'awtumoohum am antum saamitoon',193,'7:193',18,70,145,2,0,175,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1148,7,'إِنَّ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ عِبَادٌ أَمْثَالُكُمْ ۖ فَٱدْعُوهُمْ فَلْيَسْتَجِيبُوا۟ لَكُمْ إِن كُنتُمْ صَـٰدِقِينَ','Innal lazeena tad\'oona min doonil laahi \'ibaadun amsaalukum fad\'oohum fal yastajeeboo lakum in kuntum saadiqeen',194,'7:194',18,70,145,2,0,175,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1149,7,'أَلَهُمْ أَرْجُلٌ يَمْشُونَ بِهَآ ۖ أَمْ لَهُمْ أَيْدٍ يَبْطِشُونَ بِهَآ ۖ أَمْ لَهُمْ أَعْيُنٌ يُبْصِرُونَ بِهَآ ۖ أَمْ لَهُمْ ءَاذَانٌ يَسْمَعُونَ بِهَا ۗ قُلِ ٱدْعُوا۟ شُرَكَآءَكُمْ ثُمَّ كِيدُونِ فَلَا تُنظِرُونِ','A lahum arjuluny yamshoona bihaa am lahum aidiny yabtishoona bihaaa am lahum a\'yunuy yubsiroona bihaaa am lahum aazaanuny yasma\'oona bihaa; qulid\'oo shurakaaa\'akum summa keedooni falaa tunziroon',195,'7:195',18,70,145,2,0,175,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1150,7,'إِنَّ وَلِـِّۧىَ ٱللَّهُ ٱلَّذِى نَزَّلَ ٱلْكِتَـٰبَ ۖ وَهُوَ يَتَوَلَّى ٱلصَّـٰلِحِينَ','Inna waliyyial laahul lazee nazzalal Kitaaba wa Huwa yatawallas saaliheen',196,'7:196',18,70,145,2,0,176,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1151,7,'وَٱلَّذِينَ تَدْعُونَ مِن دُونِهِۦ لَا يَسْتَطِيعُونَ نَصْرَكُمْ وَلَآ أَنفُسَهُمْ يَنصُرُونَ','Wallazeena tad\'oona min doonihee laa yastatee\'oona nasrakum wa laaa anfusahum yansuroon',197,'7:197',18,70,145,2,0,176,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1152,7,'وَإِن تَدْعُوهُمْ إِلَى ٱلْهُدَىٰ لَا يَسْمَعُوا۟ ۖ وَتَرَىٰهُمْ يَنظُرُونَ إِلَيْكَ وَهُمْ لَا يُبْصِرُونَ','Wa in tad\'oohum ilal hudaa laa yasm\'oo wa taraahum yanzuroona ilaika wa hum laa yubsiroon',198,'7:198',18,70,145,2,0,176,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1153,7,'خُذِ ٱلْعَفْوَ وَأْمُرْ بِٱلْعُرْفِ وَأَعْرِضْ عَنِ ٱلْجَـٰهِلِينَ','khuzil \'afwa waamur bil\'urfi waa\'rid \'anil jaahileen',199,'7:199',18,70,145,2,0,176,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1154,7,'وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيْطَـٰنِ نَزْغٌ فَٱسْتَعِذْ بِٱللَّهِ ۚ إِنَّهُۥ سَمِيعٌ عَلِيمٌ','Wa immaa yanzaghannaka minash Shaitaani nazghun fasta\'iz billaah; innahoo Samee\'un Aleem',200,'7:200',18,70,145,2,0,176,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1155,7,'إِنَّ ٱلَّذِينَ ٱتَّقَوْا۟ إِذَا مَسَّهُمْ طَـٰٓئِفٌ مِّنَ ٱلشَّيْطَـٰنِ تَذَكَّرُوا۟ فَإِذَا هُم مُّبْصِرُونَ','Innal lazeenat taqaw izaa massahum taaa\'ifum minash Shaitaani tazakkaroo fa izaa hum mubsiroon',201,'7:201',18,70,145,2,0,176,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1156,7,'وَإِخْوَٰنُهُمْ يَمُدُّونَهُمْ فِى ٱلْغَىِّ ثُمَّ لَا يُقْصِرُونَ','Wa ikhwaanuhum yamuddoonahum fil ghaiyi summa laa yuqsiroon',202,'7:202',18,70,145,2,0,176,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1157,7,'وَإِذَا لَمْ تَأْتِهِم بِـَٔايَةٍ قَالُوا۟ لَوْلَا ٱجْتَبَيْتَهَا ۚ قُلْ إِنَّمَآ أَتَّبِعُ مَا يُوحَىٰٓ إِلَىَّ مِن رَّبِّى ۚ هَـٰذَا بَصَآئِرُ مِن رَّبِّكُمْ وَهُدًى وَرَحْمَةٌ لِّقَوْمٍ يُؤْمِنُونَ','Wa izaa lam taatihim bi aayatin qaaloo law lajtabai tahaa; qul innamaaa attabi\'u maa yoohaaa ilaiya mir Rabbee; haazaa basaaa\'iru mir Rabbikum wa hudanw wa rahmatul liqawminy yu\'minoon',203,'7:203',18,70,145,2,0,176,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1158,7,'وَإِذَا قُرِئَ ٱلْقُرْءَانُ فَٱسْتَمِعُوا۟ لَهُۥ وَأَنصِتُوا۟ لَعَلَّكُمْ تُرْحَمُونَ','Wa izaa quri\'al Quraanu fastami\'oo lahoo wa ansitoo la \'allakum turhamoon',204,'7:204',18,70,145,2,0,176,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1159,7,'وَٱذْكُر رَّبَّكَ فِى نَفْسِكَ تَضَرُّعًا وَخِيفَةً وَدُونَ ٱلْجَهْرِ مِنَ ٱلْقَوْلِ بِٱلْغُدُوِّ وَٱلْـَٔاصَالِ وَلَا تَكُن مِّنَ ٱلْغَـٰفِلِينَ','Wazkur Rabbaka fee nafsika tadarru\'anw wa kheefatanw wa doonal jahri minal qawli bilghuduwwi wal aasali wa laa takum minal ghaafileen',205,'7:205',18,70,145,2,0,176,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1160,7,'إِنَّ ٱلَّذِينَ عِندَ رَبِّكَ لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِهِۦ وَيُسَبِّحُونَهُۥ وَلَهُۥ يَسْجُدُونَ ۩','Innal lazeena \'inda Rabbika laa yastakbiroona \'an \'ibaadatihee wa yusabbihoonahoo wa lahoo yasjudoon',206,'7:206',18,70,145,2,1,176,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1161,8,'يَسْـَٔلُونَكَ عَنِ ٱلْأَنفَالِ ۖ قُلِ ٱلْأَنفَالُ لِلَّهِ وَٱلرَّسُولِ ۖ فَٱتَّقُوا۟ ٱللَّهَ وَأَصْلِحُوا۟ ذَاتَ بَيْنِكُمْ ۖ وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥٓ إِن كُنتُم مُّؤْمِنِينَ','Yas\'aloonaka \'anil anfaali qulil anfaalu lillaahi war Rasooli fattaqul laaha wa ahlihoo zaata bainikum wa atee\'ul laaha wa Rasoolahooo in kuntum mu\'mineen',1,'8:1',18,71,146,2,0,177,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1162,8,'إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتْ قُلُوبُهُمْ وَإِذَا تُلِيَتْ عَلَيْهِمْ ءَايَـٰتُهُۥ زَادَتْهُمْ إِيمَـٰنًا وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ','Innamal mu\'minoonal lazeena izaa zukiral laahu wajilat quloobuhum wa izaa tuliyat \'alaihim Aayaatuhoo zaadat hum eemaananw wa \'alaa Rabbihim yatawakkaloon',2,'8:2',18,71,146,2,0,177,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1163,8,'ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقْنَـٰهُمْ يُنفِقُونَ','Allazeena yuqeemoonas Salaata wa mimmaa razaqnaahum yunfiqoon',3,'8:3',18,71,146,2,0,177,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1164,8,'أُو۟لَـٰٓئِكَ هُمُ ٱلْمُؤْمِنُونَ حَقًّا ۚ لَّهُمْ دَرَجَـٰتٌ عِندَ رَبِّهِمْ وَمَغْفِرَةٌ وَرِزْقٌ كَرِيمٌ','Ulaaa\'ika humul mu\'minoona haqqaa; lahum darajaatun \'inda Rabbihim wa magh firatunw wa rizqun kareem',4,'8:4',18,71,146,2,0,177,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1165,8,'كَمَآ أَخْرَجَكَ رَبُّكَ مِنۢ بَيْتِكَ بِٱلْحَقِّ وَإِنَّ فَرِيقًا مِّنَ ٱلْمُؤْمِنِينَ لَكَـٰرِهُونَ','Kaamaaa akhrajaka Rabbuka mim baitika bilhaqq; wa inna fareeqam minal mu\'mineena lakaarihoon',5,'8:5',18,71,146,2,0,177,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1166,8,'يُجَـٰدِلُونَكَ فِى ٱلْحَقِّ بَعْدَ مَا تَبَيَّنَ كَأَنَّمَا يُسَاقُونَ إِلَى ٱلْمَوْتِ وَهُمْ يَنظُرُونَ','Yujaadiloonaka fil haqqi ba\'da maa tabaiyana kaannamaa yasaaqoona ilal mawti wa hum uanzuroon',6,'8:6',18,71,146,2,0,177,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1167,8,'وَإِذْ يَعِدُكُمُ ٱللَّهُ إِحْدَى ٱلطَّآئِفَتَيْنِ أَنَّهَا لَكُمْ وَتَوَدُّونَ أَنَّ غَيْرَ ذَاتِ ٱلشَّوْكَةِ تَكُونُ لَكُمْ وَيُرِيدُ ٱللَّهُ أَن يُحِقَّ ٱلْحَقَّ بِكَلِمَـٰتِهِۦ وَيَقْطَعَ دَابِرَ ٱلْكَـٰفِرِينَ','Wa iz ya\'idukumul laahu ihdat taaa\'ifataini annahaa lakum wa tawaddoona anna ghaira zaatish shawkati takoonu lakum wa yureedul laahu ai yuhiqqal haqqa bikalimaatihee wa taqta\'a daabiral kaafireen',7,'8:7',18,71,146,2,0,177,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1168,8,'لِيُحِقَّ ٱلْحَقَّ وَيُبْطِلَ ٱلْبَـٰطِلَ وَلَوْ كَرِهَ ٱلْمُجْرِمُونَ','Liyuhiqqal haqqa wa tubtilal baatila wa law karihal mujrimoon',8,'8:8',18,71,146,2,0,177,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1169,8,'إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَٱسْتَجَابَ لَكُمْ أَنِّى مُمِدُّكُم بِأَلْفٍ مِّنَ ٱلْمَلَـٰٓئِكَةِ مُرْدِفِينَ','Iz tastagheesoona Rabbakum fastajaaba lakum annee mumiddukum bi alfim minal malaaa\'ikati murdifeen',9,'8:9',18,71,146,2,0,178,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1170,8,'وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشْرَىٰ وَلِتَطْمَئِنَّ بِهِۦ قُلُوبُكُمْ ۚ وَمَا ٱلنَّصْرُ إِلَّا مِنْ عِندِ ٱللَّهِ ۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ','Wa maa ja\'alahul laahu illaa bushraa wa litatma\'inna bihee quloobukum; wa man nasru illaa min \'indil laah; innal laaha Azeezun Hakeem',10,'8:10',18,71,146,2,0,178,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1171,8,'إِذْ يُغَشِّيكُمُ ٱلنُّعَاسَ أَمَنَةً مِّنْهُ وَيُنَزِّلُ عَلَيْكُم مِّنَ ٱلسَّمَآءِ مَآءً لِّيُطَهِّرَكُم بِهِۦ وَيُذْهِبَ عَنكُمْ رِجْزَ ٱلشَّيْطَـٰنِ وَلِيَرْبِطَ عَلَىٰ قُلُوبِكُمْ وَيُثَبِّتَ بِهِ ٱلْأَقْدَامَ','Iz yughashsheekumun nu\'assa amanatam minhu wa yunazzilu \'alaikum minas samaaa\'i maaa\'al liyutah hirakum bihee wa yuzhiba \'ankum rijzash Shaitaani wa liyarbita \'ala quloobikum wa yusabbita bihil aqdaam',11,'8:11',18,71,147,2,0,178,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1172,8,'إِذْ يُوحِى رَبُّكَ إِلَى ٱلْمَلَـٰٓئِكَةِ أَنِّى مَعَكُمْ فَثَبِّتُوا۟ ٱلَّذِينَ ءَامَنُوا۟ ۚ سَأُلْقِى فِى قُلُوبِ ٱلَّذِينَ كَفَرُوا۟ ٱلرُّعْبَ فَٱضْرِبُوا۟ فَوْقَ ٱلْأَعْنَاقِ وَٱضْرِبُوا۟ مِنْهُمْ كُلَّ بَنَانٍ','Iz yoohee Rabbuka ilal malaaa\'ikati annee ma\'akum fasabbitul lazeena aamanoo; sa ulqee fee quloobil lazeena kafarur ru\'ba fadriboo fawqal a\'naaqi wadriboo minhum kulla banaan',12,'8:12',18,71,147,2,0,178,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1173,8,'ذَٰلِكَ بِأَنَّهُمْ شَآقُّوا۟ ٱللَّهَ وَرَسُولَهُۥ ۚ وَمَن يُشَاقِقِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ','Zaalika bi annahum shaaaqqul laaha wa Rasoolah; wa mai yushaqiqil laaha wa Rasoolahoo fa innal laaha shadeedul \'iqaab',13,'8:13',18,71,147,2,0,178,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1174,8,'ذَٰلِكُمْ فَذُوقُوهُ وَأَنَّ لِلْكَـٰفِرِينَ عَذَابَ ٱلنَّارِ','Zaalikum fazooqoohu wa anna lilkaafireena \'azaaban Naar',14,'8:14',18,71,147,2,0,178,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1175,8,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُوا۟ زَحْفًا فَلَا تُوَلُّوهُمُ ٱلْأَدْبَارَ','Yaaa aiyuhal lazeena aamanoo izaa laqeetumul lazeena kafaroo zahfan falaa tuwalloohumul adbaar',15,'8:15',18,71,147,2,0,178,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1176,8,'وَمَن يُوَلِّهِمْ يَوْمَئِذٍ دُبُرَهُۥٓ إِلَّا مُتَحَرِّفًا لِّقِتَالٍ أَوْ مُتَحَيِّزًا إِلَىٰ فِئَةٍ فَقَدْ بَآءَ بِغَضَبٍ مِّنَ ٱللَّهِ وَمَأْوَىٰهُ جَهَنَّمُ ۖ وَبِئْسَ ٱلْمَصِيرُ','Wa mai yuwallihim yawma\'izin duburahooo illaa mutaharrifal liqitaalin aw mutahaiyizan ilaa fi\'atin faqad baaa\'a bighadabim minal laahi wa maawaahu Jahannamu wa bi\'sal maseer',16,'8:16',18,71,147,2,0,178,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1177,8,'فَلَمْ تَقْتُلُوهُمْ وَلَـٰكِنَّ ٱللَّهَ قَتَلَهُمْ ۚ وَمَا رَمَيْتَ إِذْ رَمَيْتَ وَلَـٰكِنَّ ٱللَّهَ رَمَىٰ ۚ وَلِيُبْلِىَ ٱلْمُؤْمِنِينَ مِنْهُ بَلَآءً حَسَنًا ۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ','Falam taqtuloohum wa laakinnal laaha qatalahum; wa maa ramaita iz ramaita wa laakinnal laaha ramaa; wa liyubliyal mu\'mineena minhu balaaa\'an hasanaa; innal laaha Samee\'un Aleem',17,'8:17',18,71,147,2,0,179,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1178,8,'ذَٰلِكُمْ وَأَنَّ ٱللَّهَ مُوهِنُ كَيْدِ ٱلْكَـٰفِرِينَ','Zaalikum wa annal laaha moohinu kaidil kaafireen',18,'8:18',18,71,147,2,0,179,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1179,8,'إِن تَسْتَفْتِحُوا۟ فَقَدْ جَآءَكُمُ ٱلْفَتْحُ ۖ وَإِن تَنتَهُوا۟ فَهُوَ خَيْرٌ لَّكُمْ ۖ وَإِن تَعُودُوا۟ نَعُدْ وَلَن تُغْنِىَ عَنكُمْ فِئَتُكُمْ شَيْـًٔا وَلَوْ كَثُرَتْ وَأَنَّ ٱللَّهَ مَعَ ٱلْمُؤْمِنِينَ','In tastaftihoo faqad jaaa\'akumul fathu wa in tantahoo fahuwa khairul lakum wa in ta\'oodoo na\'ud wa lan tughniya \'ankum fi\'atukum shai\'anw wa law kasurat wa annal laaha ma\'al mu\'mineen',19,'8:19',18,71,147,2,0,179,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1180,8,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَوَلَّوْا۟ عَنْهُ وَأَنتُمْ تَسْمَعُونَ','Yaaa aiyuhal lazeena aamanoo atee\'ul laaha wa Rasoolahoo wa laa tawallaw \'anhu wa antum tasm\'oon',20,'8:20',18,71,148,2,0,179,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1181,8,'وَلَا تَكُونُوا۟ كَٱلَّذِينَ قَالُوا۟ سَمِعْنَا وَهُمْ لَا يَسْمَعُونَ','Wa laa takoonoo kallazeena qaaloo sami\'naa wa hum laa yasma\'oon',21,'8:21',18,71,148,2,0,179,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1182,8,'۞ إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلصُّمُّ ٱلْبُكْمُ ٱلَّذِينَ لَا يَعْقِلُونَ','Inna sharrad dawaaabbi \'indal laahis summul bukmul lazeena laa ya\'qiloon',22,'8:22',18,72,148,2,0,179,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1183,8,'وَلَوْ عَلِمَ ٱللَّهُ فِيهِمْ خَيْرًا لَّأَسْمَعَهُمْ ۖ وَلَوْ أَسْمَعَهُمْ لَتَوَلَّوا۟ وَّهُم مُّعْرِضُونَ','Wa law \'alimal laahu feehim khairal la asma\'ahum; wa law asma\'ahum latawallaw wa hum mu\'ridoon',23,'8:23',18,72,148,2,0,179,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1184,8,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱسْتَجِيبُوا۟ لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمْ لِمَا يُحْيِيكُمْ ۖ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَحُولُ بَيْنَ ٱلْمَرْءِ وَقَلْبِهِۦ وَأَنَّهُۥٓ إِلَيْهِ تُحْشَرُونَ','Yaaa aiyuhal lazeena aamanus tajeeboo lillaahi wa lir Rasooli izaa da\'aakum limaa yuhyeekum wa\'lamooo annal laaha yahoolu bainal mar\'i wa qalbihee wa anahooo ilaihi tuhsharoon',24,'8:24',18,72,148,2,0,179,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1185,8,'وَٱتَّقُوا۟ فِتْنَةً لَّا تُصِيبَنَّ ٱلَّذِينَ ظَلَمُوا۟ مِنكُمْ خَآصَّةً ۖ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ','Wattaqoo fitnatal laa tuseebannal lazeena zalamoo minkum khaaaassatanw wa\'lamooo annal laaha shadeedul \'iqaab',25,'8:25',18,72,148,2,0,179,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1186,8,'وَٱذْكُرُوٓا۟ إِذْ أَنتُمْ قَلِيلٌ مُّسْتَضْعَفُونَ فِى ٱلْأَرْضِ تَخَافُونَ أَن يَتَخَطَّفَكُمُ ٱلنَّاسُ فَـَٔاوَىٰكُمْ وَأَيَّدَكُم بِنَصْرِهِۦ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَـٰتِ لَعَلَّكُمْ تَشْكُرُونَ','Wazkurooo iz antum qaleelum mustad \'afoona filardi takhaafoona ai yatakhat tafakumun naasu fa aawaakum wa aiyadakum binasrihee wa razaqakum minat taiyibaati la\'allakum tashkuroon',26,'8:26',18,72,148,2,0,180,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1187,8,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَخُونُوا۟ ٱللَّهَ وَٱلرَّسُولَ وَتَخُونُوٓا۟ أَمَـٰنَـٰتِكُمْ وَأَنتُمْ تَعْلَمُونَ','Yaaa aiyuhal lazeena aamanoo laa takhoonal laaha war Rasoola wa takhoonooo amaanaatikum wa antum ta\'lamoon',27,'8:27',18,72,148,2,0,180,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1188,8,'وَٱعْلَمُوٓا۟ أَنَّمَآ أَمْوَٰلُكُمْ وَأَوْلَـٰدُكُمْ فِتْنَةٌ وَأَنَّ ٱللَّهَ عِندَهُۥٓ أَجْرٌ عَظِيمٌ','Wa\'lamooo annamaaa amwaalukum wa awlaadukum fitnatunw wa annal laaha \'indahooo ajrun azeem',28,'8:28',18,72,148,2,0,180,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1189,8,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تَتَّقُوا۟ ٱللَّهَ يَجْعَل لَّكُمْ فُرْقَانًا وَيُكَفِّرْ عَنكُمْ سَيِّـَٔاتِكُمْ وَيَغْفِرْ لَكُمْ ۗ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ','Yaaa aiyuhal lazeena aamanooo in tattaqul laaha yaj\'al lakum furqaananw wa yukaffir \'ankum saiyi aatikum wa yaghfir lakum; wallaahu zul fadlil \'azeem',29,'8:29',18,72,149,2,0,180,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1190,8,'وَإِذْ يَمْكُرُ بِكَ ٱلَّذِينَ كَفَرُوا۟ لِيُثْبِتُوكَ أَوْ يَقْتُلُوكَ أَوْ يُخْرِجُوكَ ۚ وَيَمْكُرُونَ وَيَمْكُرُ ٱللَّهُ ۖ وَٱللَّهُ خَيْرُ ٱلْمَـٰكِرِينَ','Wa iz yamkuru bikal lazeena kafaroo liyusbitooka aw yaqtulooka aw yukhrijook; wa yamkuroona wa yamkurul laahu wallaahu khairul maakireen',30,'8:30',18,72,149,2,0,180,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1191,8,'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَـٰتُنَا قَالُوا۟ قَدْ سَمِعْنَا لَوْ نَشَآءُ لَقُلْنَا مِثْلَ هَـٰذَآ ۙ إِنْ هَـٰذَآ إِلَّآ أَسَـٰطِيرُ ٱلْأَوَّلِينَ','Wa izaa tutlaa \'alaihim Aayaatunaa qaaloo qad sami\'naa law nashaaa\'u laqulnaa misla haazaaa in haazaaa illaaa asaateerul awwaleen',31,'8:31',18,72,149,2,0,180,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1192,8,'وَإِذْ قَالُوا۟ ٱللَّهُمَّ إِن كَانَ هَـٰذَا هُوَ ٱلْحَقَّ مِنْ عِندِكَ فَأَمْطِرْ عَلَيْنَا حِجَارَةً مِّنَ ٱلسَّمَآءِ أَوِ ٱئْتِنَا بِعَذَابٍ أَلِيمٍ','Wa iz qaalul laahumma in kaana haazaa huwal haqqa min \'indika fa amtir \'alainaa hijaaratam minas samaaa\'i awi\'tinaa bi \'azaabin alaeem',32,'8:32',18,72,149,2,0,180,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1193,8,'وَمَا كَانَ ٱللَّهُ لِيُعَذِّبَهُمْ وَأَنتَ فِيهِمْ ۚ وَمَا كَانَ ٱللَّهُ مُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَ','Wa maa kanal laahu liyu\'az zibahum wa anta feehim; wa maa kaanal laahu mu\'az zibahum wa hum yastaghfiroon',33,'8:33',18,72,149,2,0,180,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1194,8,'وَمَا لَهُمْ أَلَّا يُعَذِّبَهُمُ ٱللَّهُ وَهُمْ يَصُدُّونَ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ وَمَا كَانُوٓا۟ أَوْلِيَآءَهُۥٓ ۚ إِنْ أَوْلِيَآؤُهُۥٓ إِلَّا ٱلْمُتَّقُونَ وَلَـٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ','Wa maa lahum allaa yu\'az zibahumul laahu wa hum yasuddoona \'anil Masjidil-Haraami wa maa kaanooo awliyaaa\'ah; in awliyaaa\' uhooo illal muttaqoona wa laakinna aksarahum laa ya\'lamoon',34,'8:34',18,72,149,2,0,181,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1195,8,'وَمَا كَانَ صَلَاتُهُمْ عِندَ ٱلْبَيْتِ إِلَّا مُكَآءً وَتَصْدِيَةً ۚ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ','Wa maa kaana Salaatuhum \'indal Baiti illa mukaaa anw-wa tasdiyah; fazooqul \'azaaba bimaa kuntum takfuroon',35,'8:35',18,72,149,2,0,181,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1196,8,'إِنَّ ٱلَّذِينَ كَفَرُوا۟ يُنفِقُونَ أَمْوَٰلَهُمْ لِيَصُدُّوا۟ عَن سَبِيلِ ٱللَّهِ ۚ فَسَيُنفِقُونَهَا ثُمَّ تَكُونُ عَلَيْهِمْ حَسْرَةً ثُمَّ يُغْلَبُونَ ۗ وَٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ جَهَنَّمَ يُحْشَرُونَ','Innal lazeena kafaroo yunfiqoona amwaalahum liyasuddoo \'an sabeelil laah; fasayunfiqoonahaa summa takoonu \'alaihim hasratan summa yughlaboon; wal lazeena kafarooo ilaa Jahannnama yuhsharoona',36,'8:36',18,72,149,2,0,181,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1197,8,'لِيَمِيزَ ٱللَّهُ ٱلْخَبِيثَ مِنَ ٱلطَّيِّبِ وَيَجْعَلَ ٱلْخَبِيثَ بَعْضَهُۥ عَلَىٰ بَعْضٍ فَيَرْكُمَهُۥ جَمِيعًا فَيَجْعَلَهُۥ فِى جَهَنَّمَ ۚ أُو۟لَـٰٓئِكَ هُمُ ٱلْخَـٰسِرُونَ','Liyameezal laahul khabeesa minat taiyibi wa yaj\'alal khabeesa ba\'dahoo \'ala ba\'din fayarkumahoo jamee\'an fayaj\'alahoo fee Jahannnam; ulaaa\'ika humul khaasiroon',37,'8:37',18,72,149,2,0,181,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1198,8,'قُل لِّلَّذِينَ كَفَرُوٓا۟ إِن يَنتَهُوا۟ يُغْفَرْ لَهُم مَّا قَدْ سَلَفَ وَإِن يَعُودُوا۟ فَقَدْ مَضَتْ سُنَّتُ ٱلْأَوَّلِينَ','Qul lillazeena kafarooo iny yantahoo yughfar lahum maa qad salafa wa iny ya\'oodoo faqad madat sunnatul awwaleen',38,'8:38',18,72,150,2,0,181,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1199,8,'وَقَـٰتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌ وَيَكُونَ ٱلدِّينُ كُلُّهُۥ لِلَّهِ ۚ فَإِنِ ٱنتَهَوْا۟ فَإِنَّ ٱللَّهَ بِمَا يَعْمَلُونَ بَصِيرٌ','Wa qaatiloohum hattaa laa takoona fitnatunw wa yakoonaddeenu kulluhoo lillaah; fainin tahaw fa innallaaha bimaa ya\'maloona Baseer',39,'8:39',18,72,150,2,0,181,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1200,8,'وَإِن تَوَلَّوْا۟ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَوْلَىٰكُمْ ۚ نِعْمَ ٱلْمَوْلَىٰ وَنِعْمَ ٱلنَّصِيرُ','Wa in tawallaw fa\'lamooo annal laaha mawlaakum; ni\'mal mawlaa wa ni\'man naseer',40,'8:40',18,72,150,2,0,181,9,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1201,8,'۞ وَٱعْلَمُوٓا۟ أَنَّمَا غَنِمْتُم مِّن شَىْءٍ فَأَنَّ لِلَّهِ خُمُسَهُۥ وَلِلرَّسُولِ وَلِذِى ٱلْقُرْبَىٰ وَٱلْيَتَـٰمَىٰ وَٱلْمَسَـٰكِينِ وَٱبْنِ ٱلسَّبِيلِ إِن كُنتُمْ ءَامَنتُم بِٱللَّهِ وَمَآ أَنزَلْنَا عَلَىٰ عَبْدِنَا يَوْمَ ٱلْفُرْقَانِ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ','Wa\'lamooo annamaa ghanimtum min sha\'in fa anna lillaahi khumusahoo wa lir Rasooli wa lizil qurba walyataamaa walmasaakeeni wabnis sabeeli in kuntum aamantum billaahi wa maaa anzalnaa \'ala \'abdinaa yawmal Furqaani yawmaltaqal jam\'aan; wal laahu \'alaa kulli shai\'in Qadeer',41,'8:41',19,73,150,2,0,182,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1202,8,'إِذْ أَنتُم بِٱلْعُدْوَةِ ٱلدُّنْيَا وَهُم بِٱلْعُدْوَةِ ٱلْقُصْوَىٰ وَٱلرَّكْبُ أَسْفَلَ مِنكُمْ ۚ وَلَوْ تَوَاعَدتُّمْ لَٱخْتَلَفْتُمْ فِى ٱلْمِيعَـٰدِ ۙ وَلَـٰكِن لِّيَقْضِىَ ٱللَّهُ أَمْرًا كَانَ مَفْعُولًا لِّيَهْلِكَ مَنْ هَلَكَ عَنۢ بَيِّنَةٍ وَيَحْيَىٰ مَنْ حَىَّ عَنۢ بَيِّنَةٍ ۗ وَإِنَّ ٱللَّهَ لَسَمِيعٌ عَلِيمٌ','Iz antum bil\'udwatid dunyaa wa hum bil\'udwatil quswaa warrakbu asfala minkum; wa law tawaa\'attum lakhtalaftum fil mee\'aadi wa laakil liyaqdiyal laahu amran kaana maf\'oolal liyahlika man halaka \'am baiyinatinw wa yahyaa man haiya \'am baiyinah; wa innal laaha la Samee\'un \'Aleem',42,'8:42',19,73,150,2,0,182,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1203,8,'إِذْ يُرِيكَهُمُ ٱللَّهُ فِى مَنَامِكَ قَلِيلًا ۖ وَلَوْ أَرَىٰكَهُمْ كَثِيرًا لَّفَشِلْتُمْ وَلَتَنَـٰزَعْتُمْ فِى ٱلْأَمْرِ وَلَـٰكِنَّ ٱللَّهَ سَلَّمَ ۗ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ','Iz yureekahumul laahu fee manaamika qaleela; wa law araakahum kaseeral lafashiltum wa latanaaza\'tum fil amri wa laakinnal laaha sallam; innahoo \'aleemum bizaatis sudoor',43,'8:43',19,73,150,2,0,182,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1204,8,'وَإِذْ يُرِيكُمُوهُمْ إِذِ ٱلْتَقَيْتُمْ فِىٓ أَعْيُنِكُمْ قَلِيلًا وَيُقَلِّلُكُمْ فِىٓ أَعْيُنِهِمْ لِيَقْضِىَ ٱللَّهُ أَمْرًا كَانَ مَفْعُولًا ۗ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ','Wa iz yureekumoohum izil taqaitum feee a\'yunikum qaleelanw wa yuqallilukum feee a\'yunihim liyaqdiyal laahu amran kaana maf\'oolaa; wa ilal laahi turja\'ul umoor',44,'8:44',19,73,150,2,0,182,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1205,8,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا لَقِيتُمْ فِئَةً فَٱثْبُتُوا۟ وَٱذْكُرُوا۟ ٱللَّهَ كَثِيرًا لَّعَلَّكُمْ تُفْلِحُونَ','Yaaa aiyuhal lazeena aamanooo izaa laqeetum fi\'atan fasbutoo wazkurul laaha kaseeral la\'allakum tuflihoon',45,'8:45',19,73,151,2,0,182,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1206,8,'وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَنَـٰزَعُوا۟ فَتَفْشَلُوا۟ وَتَذْهَبَ رِيحُكُمْ ۖ وَٱصْبِرُوٓا۟ ۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّـٰبِرِينَ','Wa atee\'ul laaha wa Rasoolahoo wa laa tanaaza\'oo fatafshaloo wa tazhaba reehukum wasbiroo; innal laaha ma\'as saabireen',46,'8:46',19,73,151,2,0,183,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1207,8,'وَلَا تَكُونُوا۟ كَٱلَّذِينَ خَرَجُوا۟ مِن دِيَـٰرِهِم بَطَرًا وَرِئَآءَ ٱلنَّاسِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ ۚ وَٱللَّهُ بِمَا يَعْمَلُونَ مُحِيطٌ','Wa laa takoonoo kallazeena kharajoo min diyaarihim bataranw wa ri\'aaa\'an naasi wa yasuddoona \'an sabeelil laah; wallaahu bimaa ya\'maloona muheet',47,'8:47',19,73,151,2,0,183,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1208,8,'وَإِذْ زَيَّنَ لَهُمُ ٱلشَّيْطَـٰنُ أَعْمَـٰلَهُمْ وَقَالَ لَا غَالِبَ لَكُمُ ٱلْيَوْمَ مِنَ ٱلنَّاسِ وَإِنِّى جَارٌ لَّكُمْ ۖ فَلَمَّا تَرَآءَتِ ٱلْفِئَتَانِ نَكَصَ عَلَىٰ عَقِبَيْهِ وَقَالَ إِنِّى بَرِىٓءٌ مِّنكُمْ إِنِّىٓ أَرَىٰ مَا لَا تَرَوْنَ إِنِّىٓ أَخَافُ ٱللَّهَ ۚ وَٱللَّهُ شَدِيدُ ٱلْعِقَابِ','Wa iz zaiyana lahumush shaitaanu a\'ma alahum wa qaala laa ghaaliba lakumul yawma minan naasi wa innee jaarul lakum falammaa taraaa\'atil fi\'ataani nakasa \'alaa aqibaihi wa qaala innee bareee\'um minkum innee araa maa laa tarawna inneee akhaaful laah; wallaahu shadeedul \'iqaab',48,'8:48',19,73,151,2,0,183,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1209,8,'إِذْ يَقُولُ ٱلْمُنَـٰفِقُونَ وَٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ غَرَّ هَـٰٓؤُلَآءِ دِينُهُمْ ۗ وَمَن يَتَوَكَّلْ عَلَى ٱللَّهِ فَإِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ','Iz yaqoolul munaafiqoona wallazeena fee quloobihim maradun gharra haaa\'ulaaa\'i deenuhum; wa mai yatawakkal \'alal laahi fa innal laaha \'azee zun Hakeem',49,'8:49',19,73,152,2,0,183,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1210,8,'وَلَوْ تَرَىٰٓ إِذْ يَتَوَفَّى ٱلَّذِينَ كَفَرُوا۟ ۙ ٱلْمَلَـٰٓئِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَـٰرَهُمْ وَذُوقُوا۟ عَذَابَ ٱلْحَرِيقِ','Wa law taraaa iz yatawaf fal lazeena kafarul malaaa\'ikatu yadriboona wujoohahum wa adbaarahum wa zooqoo \'azaabal hareeq',50,'8:50',19,73,152,2,0,183,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1211,8,'ذَٰلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ ٱللَّهَ لَيْسَ بِظَلَّـٰمٍ لِّلْعَبِيدِ','Zaalika bimaa qaddamat aideekum wa anal laaha laisa bizallaamil lil \'abeed',51,'8:51',19,73,152,2,0,183,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1212,8,'كَدَأْبِ ءَالِ فِرْعَوْنَ ۙ وَٱلَّذِينَ مِن قَبْلِهِمْ ۚ كَفَرُوا۟ بِـَٔايَـٰتِ ٱللَّهِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ ۗ إِنَّ ٱللَّهَ قَوِىٌّ شَدِيدُ ٱلْعِقَابِ','Kadaabi Aali Fir\'awna wal lazeena min qablihim; kafaroo bi Aayaatil laahi fa akhazahu mul laahu bizunoobihim; innal laaha qawiyyun shadeedul \'iqaab',52,'8:52',19,73,152,2,0,183,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1213,8,'ذَٰلِكَ بِأَنَّ ٱللَّهَ لَمْ يَكُ مُغَيِّرًا نِّعْمَةً أَنْعَمَهَا عَلَىٰ قَوْمٍ حَتَّىٰ يُغَيِّرُوا۟ مَا بِأَنفُسِهِمْ ۙ وَأَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ','Zaalika bi annal laaha lam yaku mughaiyiran ni matan an\'amahaa \'alaa qawmin hattaa yughaiyiroo maa bianfusihim wa annallaaha samee un \'Aleem',53,'8:53',19,73,152,2,0,184,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1214,8,'كَدَأْبِ ءَالِ فِرْعَوْنَ ۙ وَٱلَّذِينَ مِن قَبْلِهِمْ ۚ كَذَّبُوا۟ بِـَٔايَـٰتِ رَبِّهِمْ فَأَهْلَكْنَـٰهُم بِذُنُوبِهِمْ وَأَغْرَقْنَآ ءَالَ فِرْعَوْنَ ۚ وَكُلٌّ كَانُوا۟ ظَـٰلِمِينَ','Kadaabi Aali Fir\'awna wallazeena min qablihim; kazzaboo bi Aayaati Rabbihim faahlaknaahum bizunoobihim wa aghraqnaa Aala Fir\'awn; wa kullun kaanoo zaalimeen',54,'8:54',19,73,152,2,0,184,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1215,8,'إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلَّذِينَ كَفَرُوا۟ فَهُمْ لَا يُؤْمِنُونَ','Inna sharrad dawaaabbi \'indal laahil lazeena kafaroo fahum laa yu\'minoon',55,'8:55',19,73,152,2,0,184,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1216,8,'ٱلَّذِينَ عَـٰهَدتَّ مِنْهُمْ ثُمَّ يَنقُضُونَ عَهْدَهُمْ فِى كُلِّ مَرَّةٍ وَهُمْ لَا يَتَّقُونَ','Allazeena\'aahatta min hum summa yanqudoona \'ahdahum fee kulli marratinw wa hum laa yattaqoon',56,'8:56',19,73,152,2,0,184,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1217,8,'فَإِمَّا تَثْقَفَنَّهُمْ فِى ٱلْحَرْبِ فَشَرِّدْ بِهِم مَّنْ خَلْفَهُمْ لَعَلَّهُمْ يَذَّكَّرُونَ','Fa immaa tasqafannahum fil harbi fasharrid bihim man khalfahum la\'allahum yazzakkaroon',57,'8:57',19,73,152,2,0,184,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1218,8,'وَإِمَّا تَخَافَنَّ مِن قَوْمٍ خِيَانَةً فَٱنۢبِذْ إِلَيْهِمْ عَلَىٰ سَوَآءٍ ۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْخَآئِنِينَ','Wa immaa takhaafana min qawmin khiyaanatan fambiz ilaihim \'alaa sawaaa\'; innal laaha laayuhibbul khaaa\'ineen',58,'8:58',19,73,152,2,0,184,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1219,8,'وَلَا يَحْسَبَنَّ ٱلَّذِينَ كَفَرُوا۟ سَبَقُوٓا۟ ۚ إِنَّهُمْ لَا يُعْجِزُونَ','Wa laa yahsabannal lazeena kafaroo sabaqooo; innahum laa yu\'jizoon',59,'8:59',19,73,153,2,0,184,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1220,8,'وَأَعِدُّوا۟ لَهُم مَّا ٱسْتَطَعْتُم مِّن قُوَّةٍ وَمِن رِّبَاطِ ٱلْخَيْلِ تُرْهِبُونَ بِهِۦ عَدُوَّ ٱللَّهِ وَعَدُوَّكُمْ وَءَاخَرِينَ مِن دُونِهِمْ لَا تَعْلَمُونَهُمُ ٱللَّهُ يَعْلَمُهُمْ ۚ وَمَا تُنفِقُوا۟ مِن شَىْءٍ فِى سَبِيلِ ٱللَّهِ يُوَفَّ إِلَيْكُمْ وَأَنتُمْ لَا تُظْلَمُونَ','Wa a\'iddoo lahum mastata\'tum min quwwatinw wa mirribaatil khaili turhiboona bihee \'aduwwal laahi wa \'aduwwakum wa aakhareena min doonihim laa ta\'lamoo nahum Allaahu ya\'lamuhum; wa maa tunfiqoo min shai\'in fee sabeelil laahi yuwaf failaikum wa antum laa tuzlamoon',60,'8:60',19,73,153,2,0,184,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1221,8,'۞ وَإِن جَنَحُوا۟ لِلسَّلْمِ فَٱجْنَحْ لَهَا وَتَوَكَّلْ عَلَى ٱللَّهِ ۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ','Wa in janahoo lissalmi fajnah lahaa wa tawakkal \'alal laah; innahoo Huwas Samee\'ul \'Aleem',61,'8:61',19,74,153,2,0,184,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1222,8,'وَإِن يُرِيدُوٓا۟ أَن يَخْدَعُوكَ فَإِنَّ حَسْبَكَ ٱللَّهُ ۚ هُوَ ٱلَّذِىٓ أَيَّدَكَ بِنَصْرِهِۦ وَبِٱلْمُؤْمِنِينَ','Wa iny yureedooo any-yakhda\'ooka fainna hasbakal laah; Huwal lazeee aiyadaka binasrihee wa bilmu\'mineen',62,'8:62',19,74,153,2,0,185,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1223,8,'وَأَلَّفَ بَيْنَ قُلُوبِهِمْ ۚ لَوْ أَنفَقْتَ مَا فِى ٱلْأَرْضِ جَمِيعًا مَّآ أَلَّفْتَ بَيْنَ قُلُوبِهِمْ وَلَـٰكِنَّ ٱللَّهَ أَلَّفَ بَيْنَهُمْ ۚ إِنَّهُۥ عَزِيزٌ حَكِيمٌ','Wa allafa baina quloobihim; law anfaqta maa fil ardi jamee\'am maaa allafta baina quloobihim wa laakinnallaaha allafa bainahum; innaahoo \'Azeezun Hakeem',63,'8:63',19,74,153,2,0,185,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1224,8,'يَـٰٓأَيُّهَا ٱلنَّبِىُّ حَسْبُكَ ٱللَّهُ وَمَنِ ٱتَّبَعَكَ مِنَ ٱلْمُؤْمِنِينَ','Yaaa aiyuhan Nabiyyu hasbukal laahu wa manittaba \'aka minal mu\'mineen',64,'8:64',19,74,153,2,0,185,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1225,8,'يَـٰٓأَيُّهَا ٱلنَّبِىُّ حَرِّضِ ٱلْمُؤْمِنِينَ عَلَى ٱلْقِتَالِ ۚ إِن يَكُن مِّنكُمْ عِشْرُونَ صَـٰبِرُونَ يَغْلِبُوا۟ مِا۟ئَتَيْنِ ۚ وَإِن يَكُن مِّنكُم مِّا۟ئَةٌ يَغْلِبُوٓا۟ أَلْفًا مِّنَ ٱلَّذِينَ كَفَرُوا۟ بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ','Yaaa aiyuhan Nabiyyu harridil mu\'mineena \'alal qitaal; iny-yakum minkum \'ishroona saabiroona yaghliboo mi\'atayn; wa iny-yakum minkum min\'atuny yaghlibooo alfam minal lazeena kafaroo bi anahum qawmul laa yafqahoon',65,'8:65',19,74,154,2,0,185,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1226,8,'ٱلْـَٔـٰنَ خَفَّفَ ٱللَّهُ عَنكُمْ وَعَلِمَ أَنَّ فِيكُمْ ضَعْفًا ۚ فَإِن يَكُن مِّنكُم مِّا۟ئَةٌ صَابِرَةٌ يَغْلِبُوا۟ مِا۟ئَتَيْنِ ۚ وَإِن يَكُن مِّنكُمْ أَلْفٌ يَغْلِبُوٓا۟ أَلْفَيْنِ بِإِذْنِ ٱللَّهِ ۗ وَٱللَّهُ مَعَ ٱلصَّـٰبِرِينَ','Al\'aana khaffafal laahu \'ankum wa \'alima anna feekum da\'faa; fa-iny yakum minkum mi\'atun saabiratuny yaghliboo mi\'atayn; wa iny-yakum minkum alfuny yaghlibooo alfaini bi iznil laah; wallaahu ma\'as saabireen',66,'8:66',19,74,154,2,0,185,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1227,8,'مَا كَانَ لِنَبِىٍّ أَن يَكُونَ لَهُۥٓ أَسْرَىٰ حَتَّىٰ يُثْخِنَ فِى ٱلْأَرْضِ ۚ تُرِيدُونَ عَرَضَ ٱلدُّنْيَا وَٱللَّهُ يُرِيدُ ٱلْـَٔاخِرَةَ ۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ','Maa kaana li Nabiyyin ai yakoona lahooo asraa hatta yuskhina fil ard; tureedoona aradad dunyaa wallaahu yureedul Aakhirah; wallaahu \'Azeezun Hakeem',67,'8:67',19,74,154,2,0,185,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1228,8,'لَّوْلَا كِتَـٰبٌ مِّنَ ٱللَّهِ سَبَقَ لَمَسَّكُمْ فِيمَآ أَخَذْتُمْ عَذَابٌ عَظِيمٌ','Law laa Kitaabum minal laahi sabaqa lamassakum fee maaa akhaztum \'azaabun \'azeem',68,'8:68',19,74,154,2,0,185,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1229,8,'فَكُلُوا۟ مِمَّا غَنِمْتُمْ حَلَـٰلًا طَيِّبًا ۚ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ','Fakuloo mimaa ghanimtum halaalan taiyibaa; watta qullaah; innal laaha Ghafoorur Raheem',69,'8:69',19,74,154,2,0,185,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1230,8,'يَـٰٓأَيُّهَا ٱلنَّبِىُّ قُل لِّمَن فِىٓ أَيْدِيكُم مِّنَ ٱلْأَسْرَىٰٓ إِن يَعْلَمِ ٱللَّهُ فِى قُلُوبِكُمْ خَيْرًا يُؤْتِكُمْ خَيْرًا مِّمَّآ أُخِذَ مِنكُمْ وَيَغْفِرْ لَكُمْ ۗ وَٱللَّهُ غَفُورٌ رَّحِيمٌ','Yaaa aiyuhan Nabiyyu qul liman feee aideekum minal asraaa iny-ya lamillaahu fee quloobikum khairany yu\'tikum khayram mimmaaa ukhiza minkum wa yaghfir lakum; wallaahu Ghafoorur Raheem',70,'8:70',19,74,155,2,0,186,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1231,8,'وَإِن يُرِيدُوا۟ خِيَانَتَكَ فَقَدْ خَانُوا۟ ٱللَّهَ مِن قَبْلُ فَأَمْكَنَ مِنْهُمْ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ','Wa iny-yureedoo khiyaa nataka faqad khaanullaaha min qablu fa amkana minhum; wallaahu \'aleemum Hakeem',71,'8:71',19,74,155,2,0,186,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1232,8,'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَـٰهَدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَوا۟ وَّنَصَرُوٓا۟ أُو۟لَـٰٓئِكَ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ ۚ وَٱلَّذِينَ ءَامَنُوا۟ وَلَمْ يُهَاجِرُوا۟ مَا لَكُم مِّن وَلَـٰيَتِهِم مِّن شَىْءٍ حَتَّىٰ يُهَاجِرُوا۟ ۚ وَإِنِ ٱسْتَنصَرُوكُمْ فِى ٱلدِّينِ فَعَلَيْكُمُ ٱلنَّصْرُ إِلَّا عَلَىٰ قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُم مِّيثَـٰقٌ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ','Innal lazeena aamanoo wa haajaroo wa jaahadoo bi amwaalihim wa anfusihim fee sabeelil laahi wallazeena aawaw wa nasarooo ulaaa\'ika ba\'duhum awliyaaa\'u ba\'d; wallazeena aamanoo wa lam yuhaajiroo maa lakum minw walaayatihim min shai\'in hatta yuhaajiroo; wa inistan sarookum fid deeni fa\'alaiku munnasru illaa \'alaa qawmim bainakum wa bainahum meesaaq; wallaahu bimaa ta\'maloona Baseer',72,'8:72',19,74,155,2,0,186,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1233,8,'وَٱلَّذِينَ كَفَرُوا۟ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ ۚ إِلَّا تَفْعَلُوهُ تَكُن فِتْنَةٌ فِى ٱلْأَرْضِ وَفَسَادٌ كَبِيرٌ','Wallazeena kafaroo ba\'duhum awliyaaa\'u ba\'d; illaa taf\'aloohu takun fitnatun fil ardi wa fasaadun kabeer',73,'8:73',19,74,155,2,0,186,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1234,8,'وَٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَـٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَوا۟ وَّنَصَرُوٓا۟ أُو۟لَـٰٓئِكَ هُمُ ٱلْمُؤْمِنُونَ حَقًّا ۚ لَّهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ','Wallazeena aamanoo wa haajaroo wa jaahadoo fee sabeelil laahi wallazeena aawaw wa nasarooo ulaaa\'ika humul mu\'minoona haqqaa; lahum maghfiratunw wa rizqun kareem',74,'8:74',19,74,155,2,0,186,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1235,8,'وَٱلَّذِينَ ءَامَنُوا۟ مِنۢ بَعْدُ وَهَاجَرُوا۟ وَجَـٰهَدُوا۟ مَعَكُمْ فَأُو۟لَـٰٓئِكَ مِنكُمْ ۚ وَأُو۟لُوا۟ ٱلْأَرْحَامِ بَعْضُهُمْ أَوْلَىٰ بِبَعْضٍ فِى كِتَـٰبِ ٱللَّهِ ۗ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌۢ','Wallazeena aamanoo mim ba\'du wa haajaroo wa jaahadoo ma;akum faulaaa\'ika minkum; wa ulul arhaami baduhum awlaa biba\'din fee Kitaabil laah; innal laaha bikulli shai\'in \'Aleem',75,'8:75',19,74,155,2,0,186,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1236,9,'بَرَآءَةٌ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلَّذِينَ عَـٰهَدتُّم مِّنَ ٱلْمُشْرِكِينَ','Baraaa\'atum minal laahi wa Rasooliheee ilal lazeena \'anhattum minal mushrikeen',1,'9:1',19,75,156,2,0,187,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1237,9,'فَسِيحُوا۟ فِى ٱلْأَرْضِ أَرْبَعَةَ أَشْهُرٍ وَٱعْلَمُوٓا۟ أَنَّكُمْ غَيْرُ مُعْجِزِى ٱللَّهِ ۙ وَأَنَّ ٱللَّهَ مُخْزِى ٱلْكَـٰفِرِينَ','Faseehoo fil ardi arba\'ata ashhurinw wa\'lamoooannakum ghairu mu\'jizil laahi wa annal laaha mukhzil kaafireen',2,'9:2',19,75,156,2,0,187,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1238,9,'وَأَذَٰنٌ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلنَّاسِ يَوْمَ ٱلْحَجِّ ٱلْأَكْبَرِ أَنَّ ٱللَّهَ بَرِىٓءٌ مِّنَ ٱلْمُشْرِكِينَ ۙ وَرَسُولُهُۥ ۚ فَإِن تُبْتُمْ فَهُوَ خَيْرٌ لَّكُمْ ۖ وَإِن تَوَلَّيْتُمْ فَٱعْلَمُوٓا۟ أَنَّكُمْ غَيْرُ مُعْجِزِى ٱللَّهِ ۗ وَبَشِّرِ ٱلَّذِينَ كَفَرُوا۟ بِعَذَابٍ أَلِيمٍ','Wa azaanum minal laahi wa Rasooliheee ilan naasi yawmal Hajjil Akbari annal laaha bareee\'um minal mushrikeena wa Rasooluh; fa-in tubtum fahuwa khairullakum wa in tawallaitum fa\'lamooo annakum ghairu mu\'jizil laah; wa bashiril lazeena kafaroo biazaabin aleem',3,'9:3',19,75,156,2,0,187,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1239,9,'إِلَّا ٱلَّذِينَ عَـٰهَدتُّم مِّنَ ٱلْمُشْرِكِينَ ثُمَّ لَمْ يَنقُصُوكُمْ شَيْـًٔا وَلَمْ يُظَـٰهِرُوا۟ عَلَيْكُمْ أَحَدًا فَأَتِمُّوٓا۟ إِلَيْهِمْ عَهْدَهُمْ إِلَىٰ مُدَّتِهِمْ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ','Illal lazeena \'aahattum minal mushrikeena summa lam yanqusookum shai\'anw-wa lam yuzaahiroo \'alaikum ahadan fa atimmooo ilaihim \'ahdahum ilaa muddatihim; innal laaha yuhibbul muttaqeen',4,'9:4',19,75,156,2,0,187,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1240,9,'فَإِذَا ٱنسَلَخَ ٱلْأَشْهُرُ ٱلْحُرُمُ فَٱقْتُلُوا۟ ٱلْمُشْرِكِينَ حَيْثُ وَجَدتُّمُوهُمْ وَخُذُوهُمْ وَٱحْصُرُوهُمْ وَٱقْعُدُوا۟ لَهُمْ كُلَّ مَرْصَدٍ ۚ فَإِن تَابُوا۟ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ فَخَلُّوا۟ سَبِيلَهُمْ ۚ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ','Fa izansalakhal Ashhurul Hurumu faqtulul mushrikeena haisu wajattumoohum wa khuzoohum wahsuroohum qaq\'udoo lahum kulla marsad; fa-in taaboo wa aqaamus Salaata wa aatawuz Zakaata fakhalloo sabeelahum; innal laaha Ghafoorur Raheem',5,'9:5',19,75,156,2,0,187,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1241,9,'وَإِنْ أَحَدٌ مِّنَ ٱلْمُشْرِكِينَ ٱسْتَجَارَكَ فَأَجِرْهُ حَتَّىٰ يَسْمَعَ كَلَـٰمَ ٱللَّهِ ثُمَّ أَبْلِغْهُ مَأْمَنَهُۥ ۚ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَعْلَمُونَ','Wa in ahadum minal mushrikeenas tajaaraka fa ajirhu hattaa yasma\'a Kalaamal laahi summa ablighhu maa manah; zaalika bi annahum qawmul laa ya\'lamoon',6,'9:6',19,75,156,2,0,187,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1242,9,'كَيْفَ يَكُونُ لِلْمُشْرِكِينَ عَهْدٌ عِندَ ٱللَّهِ وَعِندَ رَسُولِهِۦٓ إِلَّا ٱلَّذِينَ عَـٰهَدتُّمْ عِندَ ٱلْمَسْجِدِ ٱلْحَرَامِ ۖ فَمَا ٱسْتَقَـٰمُوا۟ لَكُمْ فَٱسْتَقِيمُوا۟ لَهُمْ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ','Kaifa yakoonu lilmush rikeena \'ahdun \'indallaahi wa \'inda Rasoolihee illal lazeena \'aahattum \'indal Masjidil Haraami famas taqaamoo lakum fastaqeemoo lahum; innallaaha yuhibbul muttaqeen',7,'9:7',19,75,157,2,0,188,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1243,9,'كَيْفَ وَإِن يَظْهَرُوا۟ عَلَيْكُمْ لَا يَرْقُبُوا۟ فِيكُمْ إِلًّا وَلَا ذِمَّةً ۚ يُرْضُونَكُم بِأَفْوَٰهِهِمْ وَتَأْبَىٰ قُلُوبُهُمْ وَأَكْثَرُهُمْ فَـٰسِقُونَ','Kaifa wa iny-yazharoo \'alaikum laa yarquboo feekum illanw wa laa zimmah; yurdoo nakum biafwaahihim wa taabaa quloobuhum wa aksaruhum faasiqoon',8,'9:8',19,75,157,2,0,188,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1244,9,'ٱشْتَرَوْا۟ بِـَٔايَـٰتِ ٱللَّهِ ثَمَنًا قَلِيلًا فَصَدُّوا۟ عَن سَبِيلِهِۦٓ ۚ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ','Ishtaraw bi Aayaatil laahi samanan qaleelan fasaddoo \'an sabeelih; innahum saaa\'a maa kaanoo ya\'maloon',9,'9:9',19,75,157,2,0,188,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1245,9,'لَا يَرْقُبُونَ فِى مُؤْمِنٍ إِلًّا وَلَا ذِمَّةً ۚ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُعْتَدُونَ','Laa yarquboona fee mu\'minin illanw wa laa zimmah wa ulaaa \'ika humulmu \'tadoon',10,'9:10',19,75,157,2,0,188,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1246,9,'فَإِن تَابُوا۟ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ فَإِخْوَٰنُكُمْ فِى ٱلدِّينِ ۗ وَنُفَصِّلُ ٱلْـَٔايَـٰتِ لِقَوْمٍ يَعْلَمُونَ','Fa in taaboo wa aqaamus Salaata wa aatawuz Zakaata fa ikhwaanukum fid deen; wa nufassilul Aayaati liqawminy ya\'lamoon',11,'9:11',19,75,157,2,0,188,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1247,9,'وَإِن نَّكَثُوٓا۟ أَيْمَـٰنَهُم مِّنۢ بَعْدِ عَهْدِهِمْ وَطَعَنُوا۟ فِى دِينِكُمْ فَقَـٰتِلُوٓا۟ أَئِمَّةَ ٱلْكُفْرِ ۙ إِنَّهُمْ لَآ أَيْمَـٰنَ لَهُمْ لَعَلَّهُمْ يَنتَهُونَ','Wa in nakasooo aimaanahum mim ba\'di \'ahdihim wa ta\'anoo fee deenikum faqaatilooo a\'immatal kufri innahum laaa aimaana lahum la\'allahum yantahoon',12,'9:12',19,75,157,2,0,188,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1248,9,'أَلَا تُقَـٰتِلُونَ قَوْمًا نَّكَثُوٓا۟ أَيْمَـٰنَهُمْ وَهَمُّوا۟ بِإِخْرَاجِ ٱلرَّسُولِ وَهُم بَدَءُوكُمْ أَوَّلَ مَرَّةٍ ۚ أَتَخْشَوْنَهُمْ ۚ فَٱللَّهُ أَحَقُّ أَن تَخْشَوْهُ إِن كُنتُم مُّؤْمِنِينَ','Alaa tuqaatiloona qawman nakasooo aimaanahum wa hammoo bi ikhraajir Rasooli wa hum bada\'ookum awwala marrah; atakhshawnahum; fallaahu ahaqqu an takhshawhu in kuntum mu\'mineen',13,'9:13',19,75,157,2,0,188,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1249,9,'قَـٰتِلُوهُمْ يُعَذِّبْهُمُ ٱللَّهُ بِأَيْدِيكُمْ وَيُخْزِهِمْ وَيَنصُرْكُمْ عَلَيْهِمْ وَيَشْفِ صُدُورَ قَوْمٍ مُّؤْمِنِينَ','Qaatiloohum yu\'az zibhumul laahu bi aideekum wa yukhzihim wa yansurkum \'alaihim wa yashfi sudoora qawmim mu \'mineen',14,'9:14',19,75,157,2,0,189,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1250,9,'وَيُذْهِبْ غَيْظَ قُلُوبِهِمْ ۗ وَيَتُوبُ ٱللَّهُ عَلَىٰ مَن يَشَآءُ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ','Wa yuzhib ghaiza quloobihim; wa yatoobullaahu \'alaa mai yashaaa\'; wallaahu \'Aleemun Hakeem',15,'9:15',19,75,157,2,0,189,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1251,9,'أَمْ حَسِبْتُمْ أَن تُتْرَكُوا۟ وَلَمَّا يَعْلَمِ ٱللَّهُ ٱلَّذِينَ جَـٰهَدُوا۟ مِنكُمْ وَلَمْ يَتَّخِذُوا۟ مِن دُونِ ٱللَّهِ وَلَا رَسُولِهِۦ وَلَا ٱلْمُؤْمِنِينَ وَلِيجَةً ۚ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ','Am hasibtum an turakoo wa lammaa ya\'lamil laahul lazeena jaahadoo minkum wa lam yattakhizoo min doonil laahi wa laa Rasoolihee wa lalmu\'mineena waleejah; wallaahu khabeerum bimaa ta\'maloon',16,'9:16',19,75,157,2,0,189,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1252,9,'مَا كَانَ لِلْمُشْرِكِينَ أَن يَعْمُرُوا۟ مَسَـٰجِدَ ٱللَّهِ شَـٰهِدِينَ عَلَىٰٓ أَنفُسِهِم بِٱلْكُفْرِ ۚ أُو۟لَـٰٓئِكَ حَبِطَتْ أَعْمَـٰلُهُمْ وَفِى ٱلنَّارِ هُمْ خَـٰلِدُونَ','maa kaana lilmushrikeena ai ya\'muroo masaajidal laahi shaahideena \'alaaa anfusihim bilkufr; ulaaa\'ika habitat a\'maaluhum wa fin naari hum khaalidoon',17,'9:17',19,75,158,2,0,189,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1253,9,'إِنَّمَا يَعْمُرُ مَسَـٰجِدَ ٱللَّهِ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَلَمْ يَخْشَ إِلَّا ٱللَّهَ ۖ فَعَسَىٰٓ أُو۟لَـٰٓئِكَ أَن يَكُونُوا۟ مِنَ ٱلْمُهْتَدِينَ','Innamaa ya\'muru masaa jidal laahi man aamana billaahi wal Yawmil Aakhiri wa aqaamas Salaata wa aataz Zakaata wa lam yakkhsa illal laaha fa\'asaaa ulaaa\'ika ai yakoonoo minal muhtadeen',18,'9:18',19,75,158,2,0,189,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1254,9,'۞ أَجَعَلْتُمْ سِقَايَةَ ٱلْحَآجِّ وَعِمَارَةَ ٱلْمَسْجِدِ ٱلْحَرَامِ كَمَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَجَـٰهَدَ فِى سَبِيلِ ٱللَّهِ ۚ لَا يَسْتَوُۥنَ عِندَ ٱللَّهِ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ','Aja\'altum siqaayatal haaajji wa \'imaaratal masjidil haraami kamman aamana billaahi wal Yawmil Aakhiri wa jaahada fee sabeelil laah; laa yastawoona \'indal laah; wallaahu laa yahdil qawmaz zaalimeen',19,'9:19',19,76,158,2,0,189,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1255,9,'ٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَـٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ أَعْظَمُ دَرَجَةً عِندَ ٱللَّهِ ۚ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْفَآئِزُونَ','Allazeena aamanoo wa haajaroo wa jaahadoo fee sabeelil laahi bi amwaalihim wa anufsihim a\'zamu darajatan \'indal laah; wa ulaaa\'ika humul faaa\'izoon',20,'9:20',19,76,158,2,0,189,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1256,9,'يُبَشِّرُهُمْ رَبُّهُم بِرَحْمَةٍ مِّنْهُ وَرِضْوَٰنٍ وَجَنَّـٰتٍ لَّهُمْ فِيهَا نَعِيمٌ مُّقِيمٌ','Yubashshiruhum Rabbuhum birahmatim minhu wa ridwaaninw wa Jannaatil lahum feehaa na\'eemum muqeem',21,'9:21',19,76,158,2,0,190,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1257,9,'خَـٰلِدِينَ فِيهَآ أَبَدًا ۚ إِنَّ ٱللَّهَ عِندَهُۥٓ أَجْرٌ عَظِيمٌ','Khaalideena feehaaa abadaa; innal laaha \'indahooo ajrun \'azeem',22,'9:22',19,76,158,2,0,190,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1258,9,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوٓا۟ ءَابَآءَكُمْ وَإِخْوَٰنَكُمْ أَوْلِيَآءَ إِنِ ٱسْتَحَبُّوا۟ ٱلْكُفْرَ عَلَى ٱلْإِيمَـٰنِ ۚ وَمَن يَتَوَلَّهُم مِّنكُمْ فَأُو۟لَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ','Yaaa aiyuhal lazeena aamanoo laa tattakhizooo aabaaa \'akum wa ikhwaanakum awliyaaa\'a inis tahabbul kufra \'alal eemaan; wa mai yatawal lahum minkum fa ulaaa\'ika humuz zaalimoon',23,'9:23',19,76,158,2,0,190,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1259,9,'قُلْ إِن كَانَ ءَابَآؤُكُمْ وَأَبْنَآؤُكُمْ وَإِخْوَٰنُكُمْ وَأَزْوَٰجُكُمْ وَعَشِيرَتُكُمْ وَأَمْوَٰلٌ ٱقْتَرَفْتُمُوهَا وَتِجَـٰرَةٌ تَخْشَوْنَ كَسَادَهَا وَمَسَـٰكِنُ تَرْضَوْنَهَآ أَحَبَّ إِلَيْكُم مِّنَ ٱللَّهِ وَرَسُولِهِۦ وَجِهَادٍ فِى سَبِيلِهِۦ فَتَرَبَّصُوا۟ حَتَّىٰ يَأْتِىَ ٱللَّهُ بِأَمْرِهِۦ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَـٰسِقِينَ','Qul in kaana aabaaa\'ukum wa abnaaa\'ukum wa ikhwaanukum wa azwaajukum wa \'asheeratukum wa amwaaluniq taraftumoohaa wa tijaaratun takhshawna kasaadahaa wa masaakinu tardawnahaaa ahabba ilaikum minal laahi wa Rasoolihee wa Jihaadin fee Sabeelihee fatarabbasoo hattaa yaatiyallaahu bi amrih; wallaahu laa yahdil qawmal faasiqeen',24,'9:24',19,76,158,2,0,190,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1260,9,'لَقَدْ نَصَرَكُمُ ٱللَّهُ فِى مَوَاطِنَ كَثِيرَةٍ ۙ وَيَوْمَ حُنَيْنٍ ۙ إِذْ أَعْجَبَتْكُمْ كَثْرَتُكُمْ فَلَمْ تُغْنِ عَنكُمْ شَيْـًٔا وَضَاقَتْ عَلَيْكُمُ ٱلْأَرْضُ بِمَا رَحُبَتْ ثُمَّ وَلَّيْتُم مُّدْبِرِينَ','Laqad nasarakumul laahu fee mawaatina kaseeratinw wa yawma Hunainin iz a\'jabatkum kasratukum falam tughni \'ankum shai\'anw wa daaqat \'alaikumul ardu bimaa rahubat summa wallaitum mudbireen',25,'9:25',19,76,159,2,0,190,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1261,9,'ثُمَّ أَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلْمُؤْمِنِينَ وَأَنزَلَ جُنُودًا لَّمْ تَرَوْهَا وَعَذَّبَ ٱلَّذِينَ كَفَرُوا۟ ۚ وَذَٰلِكَ جَزَآءُ ٱلْكَـٰفِرِينَ','Summa anzalal laahu sakeenatahoo \'alaa Rasoolihee wa \'alalmu \'mineena wa anzala junoodal lam tarawhaa wa azzabal lazeena kafaroo; wa zaalika jazaaa\'ul kaafireen',26,'9:26',19,76,159,2,0,190,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1262,9,'ثُمَّ يَتُوبُ ٱللَّهُ مِنۢ بَعْدِ ذَٰلِكَ عَلَىٰ مَن يَشَآءُ ۗ وَٱللَّهُ غَفُورٌ رَّحِيمٌ','Summa yatoobul laahu mim ba\'di zaalika \'alaa mai yashaaa\'; wallaahu Ghafoorur Raheem',27,'9:27',19,76,159,2,0,191,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1263,9,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّمَا ٱلْمُشْرِكُونَ نَجَسٌ فَلَا يَقْرَبُوا۟ ٱلْمَسْجِدَ ٱلْحَرَامَ بَعْدَ عَامِهِمْ هَـٰذَا ۚ وَإِنْ خِفْتُمْ عَيْلَةً فَسَوْفَ يُغْنِيكُمُ ٱللَّهُ مِن فَضْلِهِۦٓ إِن شَآءَ ۚ إِنَّ ٱللَّهَ عَلِيمٌ حَكِيمٌ','Yaaa aiyuhal lazeena aamanooo innamal mushrikoona najasun falaa yaqrabul Masjidal Haraama ba\'da \'aamihim haaza; wa in khiftum \'ailatan fasawfa yughnee kumul laahu min fadliheee in shaaa\'; innallaaha \'Aleemun hakeem',28,'9:28',19,76,159,2,0,191,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1264,9,'قَـٰتِلُوا۟ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱللَّهِ وَلَا بِٱلْيَوْمِ ٱلْـَٔاخِرِ وَلَا يُحَرِّمُونَ مَا حَرَّمَ ٱللَّهُ وَرَسُولُهُۥ وَلَا يَدِينُونَ دِينَ ٱلْحَقِّ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ حَتَّىٰ يُعْطُوا۟ ٱلْجِزْيَةَ عَن يَدٍ وَهُمْ صَـٰغِرُونَ','Qaatilul lazeena laa yu\'minoona billaahi wa laa bil yawmil Aakhiri wa laa yuharrimoona maa harramal laahu wa Rasooluhoo wa laa yadeenoona deenal haqqi minal lazeena ootul Kitaaba hattaa yu\'tul jizyata ai yadinw wa hum saaghiroon',29,'9:29',19,76,159,2,0,191,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1265,9,'وَقَالَتِ ٱلْيَهُودُ عُزَيْرٌ ٱبْنُ ٱللَّهِ وَقَالَتِ ٱلنَّصَـٰرَى ٱلْمَسِيحُ ٱبْنُ ٱللَّهِ ۖ ذَٰلِكَ قَوْلُهُم بِأَفْوَٰهِهِمْ ۖ يُضَـٰهِـُٔونَ قَوْلَ ٱلَّذِينَ كَفَرُوا۟ مِن قَبْلُ ۚ قَـٰتَلَهُمُ ٱللَّهُ ۚ أَنَّىٰ يُؤْفَكُونَ','Q qaalatil yahoodu \'Uzairunib nul laahi wa qaalatin Nasaaral Maseehub nul laahi zaalika qawluhum bi afwaahihim yudaahi\'oona qawlal lazeena kafaroo min qabl; qatalahumul laah; annaa yu\'fakoon',30,'9:30',19,76,160,2,0,191,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1266,9,'ٱتَّخَذُوٓا۟ أَحْبَارَهُمْ وَرُهْبَـٰنَهُمْ أَرْبَابًا مِّن دُونِ ٱللَّهِ وَٱلْمَسِيحَ ٱبْنَ مَرْيَمَ وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوٓا۟ إِلَـٰهًا وَٰحِدًا ۖ لَّآ إِلَـٰهَ إِلَّا هُوَ ۚ سُبْحَـٰنَهُۥ عَمَّا يُشْرِكُونَ','ittakhazooo ahbaarahum wa ruhbaanahum arbaabammin doonil laahi wal Maseehab na Maryama wa maaa umirooo illaa liya\'budooo Ilaahanw Waa hidan laaa ilaaha illaa Hoo; Subhaanahoo \'ammaa yushrikoon',31,'9:31',19,76,160,2,0,191,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1267,9,'يُرِيدُونَ أَن يُطْفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفْوَٰهِهِمْ وَيَأْبَى ٱللَّهُ إِلَّآ أَن يُتِمَّ نُورَهُۥ وَلَوْ كَرِهَ ٱلْكَـٰفِرُونَ','Yureedoona ai yutfi\'oo nooral laahi bi\'afwaahihim wa yaaballaahu illaaa ai yutimma noorahoo wa law karihal kaafiroon',32,'9:32',19,76,160,2,0,192,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1268,9,'هُوَ ٱلَّذِىٓ أَرْسَلَ رَسُولَهُۥ بِٱلْهُدَىٰ وَدِينِ ٱلْحَقِّ لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوْ كَرِهَ ٱلْمُشْرِكُونَ','huwal lazeee ar sala Rasoolahoo bilhudaa wa deenil haqqi liyuzhirahoo \'alad deeni kullihee wa law karihal mushrikoon',33,'9:33',19,76,160,2,0,192,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1269,9,'۞ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ كَثِيرًا مِّنَ ٱلْأَحْبَارِ وَٱلرُّهْبَانِ لَيَأْكُلُونَ أَمْوَٰلَ ٱلنَّاسِ بِٱلْبَـٰطِلِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ ۗ وَٱلَّذِينَ يَكْنِزُونَ ٱلذَّهَبَ وَٱلْفِضَّةَ وَلَا يُنفِقُونَهَا فِى سَبِيلِ ٱللَّهِ فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ','Yaaa aiyuhal lazeena aamanooo inna kaseeramminal ahbaari warruhbaani la yaakuloona amwaalan naasi bil baatili wa yasuddoona \'an sabeelil laah; wallazeena yaknizoonaz zahaba wal fiddata wa laayunfiqoonahaa fee sabeelil laahi fabashshirhum bi\'azaabin aleem',34,'9:34',20,77,160,2,0,192,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1270,9,'يَوْمَ يُحْمَىٰ عَلَيْهَا فِى نَارِ جَهَنَّمَ فَتُكْوَىٰ بِهَا جِبَاهُهُمْ وَجُنُوبُهُمْ وَظُهُورُهُمْ ۖ هَـٰذَا مَا كَنَزْتُمْ لِأَنفُسِكُمْ فَذُوقُوا۟ مَا كُنتُمْ تَكْنِزُونَ','Yawma yuhmaa \'alaihaa fee naari jahannama fatukwaa bihaa jibaahuhum haazaa maa kanaztum li anfusikum fazooqoo maa kuntum taknizoon',35,'9:35',20,77,160,2,0,192,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1271,9,'إِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثْنَا عَشَرَ شَهْرًا فِى كِتَـٰبِ ٱللَّهِ يَوْمَ خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ مِنْهَآ أَرْبَعَةٌ حُرُمٌ ۚ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ ۚ فَلَا تَظْلِمُوا۟ فِيهِنَّ أَنفُسَكُمْ ۚ وَقَـٰتِلُوا۟ ٱلْمُشْرِكِينَ كَآفَّةً كَمَا يُقَـٰتِلُونَكُمْ كَآفَّةً ۚ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ','Inna \'iddatash shuhoori \'indal laahis naa \'ashara shahran fee Kitaabil laahi yawma khalaqas samaawaati wal arda minhaaa arba\'atun hurum; zaalikad deenul qaiyim; falaa tazlimoo feehinna anfusakum; wa qaatilul mushrikeena kaaaf fattan kamaa yuqaati loonakum kaaaffah; wa\'lamooo annal laaha ma\'al muttaqeen',36,'9:36',20,77,160,2,0,192,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1272,9,'إِنَّمَا ٱلنَّسِىٓءُ زِيَادَةٌ فِى ٱلْكُفْرِ ۖ يُضَلُّ بِهِ ٱلَّذِينَ كَفَرُوا۟ يُحِلُّونَهُۥ عَامًا وَيُحَرِّمُونَهُۥ عَامًا لِّيُوَاطِـُٔوا۟ عِدَّةَ مَا حَرَّمَ ٱللَّهُ فَيُحِلُّوا۟ مَا حَرَّمَ ٱللَّهُ ۚ زُيِّنَ لَهُمْ سُوٓءُ أَعْمَـٰلِهِمْ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَـٰفِرِينَ','Innamma naseee\'u ziyaadatun filkufri yudallu bihillazeena kafaroo yuhil loonahoo \'aamanw wa yuhar rimoonahoo \'aamalliyu watti\'oo \'iddata maa harramal laah; zuyyina lahum sooo\'u a\'maalihim; wallaahu laa yahdil qawmal kaafireen',37,'9:37',20,77,160,2,0,193,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1273,9,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ مَا لَكُمْ إِذَا قِيلَ لَكُمُ ٱنفِرُوا۟ فِى سَبِيلِ ٱللَّهِ ٱثَّاقَلْتُمْ إِلَى ٱلْأَرْضِ ۚ أَرَضِيتُم بِٱلْحَيَوٰةِ ٱلدُّنْيَا مِنَ ٱلْـَٔاخِرَةِ ۚ فَمَا مَتَـٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا فِى ٱلْـَٔاخِرَةِ إِلَّا قَلِيلٌ','Yaaa aiyuhal lazeena aamanoo maa lakum izaa qeela lakumun firoo fee sabeelil laahis saaqaltum ilal ard; aradeetum bilhayaatid dunyaa minal Aakhirah; famaa ma taaul hayaatiddunyaa fil Aakhirati illaa qaleel',38,'9:38',20,77,161,2,0,193,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1274,9,'إِلَّا تَنفِرُوا۟ يُعَذِّبْكُمْ عَذَابًا أَلِيمًا وَيَسْتَبْدِلْ قَوْمًا غَيْرَكُمْ وَلَا تَضُرُّوهُ شَيْـًٔا ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ','Illaa tanfiroo yu\'az zibkum \'azaaban aleemanw wa yastabdil qawman ghairakum wa laa tadurroohu shai\'aa; wal laahu \'alaa kulli shai\'in Qadeer',39,'9:39',20,77,161,2,0,193,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1275,9,'إِلَّا تَنصُرُوهُ فَقَدْ نَصَرَهُ ٱللَّهُ إِذْ أَخْرَجَهُ ٱلَّذِينَ كَفَرُوا۟ ثَانِىَ ٱثْنَيْنِ إِذْ هُمَا فِى ٱلْغَارِ إِذْ يَقُولُ لِصَـٰحِبِهِۦ لَا تَحْزَنْ إِنَّ ٱللَّهَ مَعَنَا ۖ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيْهِ وَأَيَّدَهُۥ بِجُنُودٍ لَّمْ تَرَوْهَا وَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُوا۟ ٱلسُّفْلَىٰ ۗ وَكَلِمَةُ ٱللَّهِ هِىَ ٱلْعُلْيَا ۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ','Illaa tansuroohu faqad nasarahul laahu iz akhrajahul lazeena kafaroo saaniyasnaini iz humaa filghaari iz yaqoolu lisaahibihee la tahzan innnal laaha ma\'anaa fa anzalallaahu sakeenatahoo \'alaihi wa aiyadahoo bijunoodil lam tarawhaa wa ja\'ala kalimatal lazeena kafarus suflaa; wa Kalimatul laahi hiyal \'ulyaa; wallaahu \'Azeezun Hakeem;',40,'9:40',20,77,161,2,0,193,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1276,9,'ٱنفِرُوا۟ خِفَافًا وَثِقَالًا وَجَـٰهِدُوا۟ بِأَمْوَٰلِكُمْ وَأَنفُسِكُمْ فِى سَبِيلِ ٱللَّهِ ۚ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ','Infiroo khifaafanw wa siqaalanw wa jaahidoo bi amwaalikum wa anfusikum fee sabeelil laah; zaalikum khairul lakum in kuntum ta\'lamoon',41,'9:41',20,77,161,2,0,194,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1277,9,'لَوْ كَانَ عَرَضًا قَرِيبًا وَسَفَرًا قَاصِدًا لَّٱتَّبَعُوكَ وَلَـٰكِنۢ بَعُدَتْ عَلَيْهِمُ ٱلشُّقَّةُ ۚ وَسَيَحْلِفُونَ بِٱللَّهِ لَوِ ٱسْتَطَعْنَا لَخَرَجْنَا مَعَكُمْ يُهْلِكُونَ أَنفُسَهُمْ وَٱللَّهُ يَعْلَمُ إِنَّهُمْ لَكَـٰذِبُونَ','Law kaana \'aradan qareebanw wa safaran qaasidal lattaba\'ooka wa laakim ba\'udat \'alaihimush shuqqah; wa sayahlifoona billaahi lawis tata\'naa lakharajnaa ma\'akum; yuhlikoona anfusahum wal laahu ya\'lamu innahum lakaa ziboon',42,'9:42',20,77,161,2,0,194,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1278,9,'عَفَا ٱللَّهُ عَنكَ لِمَ أَذِنتَ لَهُمْ حَتَّىٰ يَتَبَيَّنَ لَكَ ٱلَّذِينَ صَدَقُوا۟ وَتَعْلَمَ ٱلْكَـٰذِبِينَ','\'Afal laahu \'anka lima azinta lahum hattaa yatabai yana lakal lazeena sadaqoo wa ta\'lamal kaazibeen',43,'9:43',20,77,162,2,0,194,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1279,9,'لَا يَسْتَـْٔذِنُكَ ٱلَّذِينَ يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ أَن يُجَـٰهِدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ ۗ وَٱللَّهُ عَلِيمٌۢ بِٱلْمُتَّقِينَ','Laa yastaazinukal lazeena yu\'minoona billaahi wal Yawmil Aakhiri ai yujaa hidoo bi amwaalihim wa anfusihim; wallaahu \'aleemum bilmut taqeen',44,'9:44',20,77,162,2,0,194,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1280,9,'إِنَّمَا يَسْتَـْٔذِنُكَ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَٱرْتَابَتْ قُلُوبُهُمْ فَهُمْ فِى رَيْبِهِمْ يَتَرَدَّدُونَ','Innamaa yastaazinukal lazeena laa yu\'minoona billaahi wal Yawmil Aakhiri wartaabat quloobuhum fahum fee raibihim yataraddadoon',45,'9:45',20,77,162,2,0,194,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1281,9,'۞ وَلَوْ أَرَادُوا۟ ٱلْخُرُوجَ لَأَعَدُّوا۟ لَهُۥ عُدَّةً وَلَـٰكِن كَرِهَ ٱللَّهُ ٱنۢبِعَاثَهُمْ فَثَبَّطَهُمْ وَقِيلَ ٱقْعُدُوا۟ مَعَ ٱلْقَـٰعِدِينَ','Wa law araadul khurooja la-\'addoo lahoo \'uddatanw wa laakin karihal laahum bi\'aasahum fasabbatahum wa qeelaq \'udoo ma\'al qaa\'ideen',46,'9:46',20,78,162,2,0,194,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1282,9,'لَوْ خَرَجُوا۟ فِيكُم مَّا زَادُوكُمْ إِلَّا خَبَالًا وَلَأَوْضَعُوا۟ خِلَـٰلَكُمْ يَبْغُونَكُمُ ٱلْفِتْنَةَ وَفِيكُمْ سَمَّـٰعُونَ لَهُمْ ۗ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّـٰلِمِينَ','Law kharajoo feekum maa zaadookum ilaa Khabaalanw wa la awda\'oo khilaalakum yabghoona kumul fitnata wa feekum sammaa\'oona lahum; wallaahu \'aleemum biz zaalimeen',47,'9:47',20,78,162,2,0,194,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1283,9,'لَقَدِ ٱبْتَغَوُا۟ ٱلْفِتْنَةَ مِن قَبْلُ وَقَلَّبُوا۟ لَكَ ٱلْأُمُورَ حَتَّىٰ جَآءَ ٱلْحَقُّ وَظَهَرَ أَمْرُ ٱللَّهِ وَهُمْ كَـٰرِهُونَ','Laqadib taghawul fitnata min qablu wa qallaboo lakal umoora hattaa jaaa\'al haqqu wa zahara amrul laahi wa hum kaarihoon',48,'9:48',20,78,162,2,0,195,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1284,9,'وَمِنْهُم مَّن يَقُولُ ٱئْذَن لِّى وَلَا تَفْتِنِّىٓ ۚ أَلَا فِى ٱلْفِتْنَةِ سَقَطُوا۟ ۗ وَإِنَّ جَهَنَّمَ لَمُحِيطَةٌۢ بِٱلْكَـٰفِرِينَ','Wa minhum mai yaqoolu\' zal lee wa laa taftinneee; alaa fil fitnati saqatoo; wa inna Jahannama lamuheetatum bil kaafireen',49,'9:49',20,78,162,2,0,195,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1285,9,'إِن تُصِبْكَ حَسَنَةٌ تَسُؤْهُمْ ۖ وَإِن تُصِبْكَ مُصِيبَةٌ يَقُولُوا۟ قَدْ أَخَذْنَآ أَمْرَنَا مِن قَبْلُ وَيَتَوَلَّوا۟ وَّهُمْ فَرِحُونَ','in tusibka hasanatun tasu\'hum; wa in tusibka museebatuny yaqooloo qad akhaznaaa amranaa min qablu wa yatawallaw wa hum farihoon',50,'9:50',20,78,162,2,0,195,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1286,9,'قُل لَّن يُصِيبَنَآ إِلَّا مَا كَتَبَ ٱللَّهُ لَنَا هُوَ مَوْلَىٰنَا ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ','Qul lany-yuseebanaaa illaa maa katabal laahu lanaa Huwa mawlaanaa; wa \'alal laahi falyatawak kalimu \'minoon',51,'9:51',20,78,162,2,0,195,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1287,9,'قُلْ هَلْ تَرَبَّصُونَ بِنَآ إِلَّآ إِحْدَى ٱلْحُسْنَيَيْنِ ۖ وَنَحْنُ نَتَرَبَّصُ بِكُمْ أَن يُصِيبَكُمُ ٱللَّهُ بِعَذَابٍ مِّنْ عِندِهِۦٓ أَوْ بِأَيْدِينَا ۖ فَتَرَبَّصُوٓا۟ إِنَّا مَعَكُم مُّتَرَبِّصُونَ','Qul hal tarabbasoona binaaa illaaa ihdal husnayayni wa nahnu natrabbasu bikum ai yus eebakumul laahu bi\'azaa bim min \'indiheee aw biaidee naa fatarabbasooo innaa ma\'akum mutarabbisoon',52,'9:52',20,78,162,2,0,195,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1288,9,'قُلْ أَنفِقُوا۟ طَوْعًا أَوْ كَرْهًا لَّن يُتَقَبَّلَ مِنكُمْ ۖ إِنَّكُمْ كُنتُمْ قَوْمًا فَـٰسِقِينَ','Qul anfiqoo taw\'an aw karhal lany yutaqabbala min kum innakum kuntum qawman faasiqeen',53,'9:53',20,78,162,2,0,195,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1289,9,'وَمَا مَنَعَهُمْ أَن تُقْبَلَ مِنْهُمْ نَفَقَـٰتُهُمْ إِلَّآ أَنَّهُمْ كَفَرُوا۟ بِٱللَّهِ وَبِرَسُولِهِۦ وَلَا يَأْتُونَ ٱلصَّلَوٰةَ إِلَّا وَهُمْ كُسَالَىٰ وَلَا يُنفِقُونَ إِلَّا وَهُمْ كَـٰرِهُونَ','Wa maa mana\'ahum an tuqbala minhum nafaqaatuhum illaaa annnahum kafaroo billaahi wa bi Rasoolihee wa laa yaatoonas Salaata illaa wa hum kusaalaa wa laa yunfiqoona illaa wa hum kaarihoon',54,'9:54',20,78,162,2,0,195,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1290,9,'فَلَا تُعْجِبْكَ أَمْوَٰلُهُمْ وَلَآ أَوْلَـٰدُهُمْ ۚ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُعَذِّبَهُم بِهَا فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَتَزْهَقَ أَنفُسُهُمْ وَهُمْ كَـٰفِرُونَ','Falaa tu\'jibka amwaaluhum wa laaa awlaaduhum; innamaa yureedul laahu liyu\'az zibahum bihaa fil hayaatid dunyaa wa tazhaqa anfusuhum wa hum kaafiroon',55,'9:55',20,78,162,2,0,196,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1291,9,'وَيَحْلِفُونَ بِٱللَّهِ إِنَّهُمْ لَمِنكُمْ وَمَا هُم مِّنكُمْ وَلَـٰكِنَّهُمْ قَوْمٌ يَفْرَقُونَ','Wa yahlifoona billaahi innnahum laminkum wa maa hum minkum wa laakinnahum qawmuny yafraqoon',56,'9:56',20,78,162,2,0,196,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1292,9,'لَوْ يَجِدُونَ مَلْجَـًٔا أَوْ مَغَـٰرَٰتٍ أَوْ مُدَّخَلًا لَّوَلَّوْا۟ إِلَيْهِ وَهُمْ يَجْمَحُونَ','Law yajidoona malja\'an aw maghaaraatin aw mudda khalal lawallaw ilaihi wa hum yajmahoon',57,'9:57',20,78,162,2,0,196,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1293,9,'وَمِنْهُم مَّن يَلْمِزُكَ فِى ٱلصَّدَقَـٰتِ فَإِنْ أُعْطُوا۟ مِنْهَا رَضُوا۟ وَإِن لَّمْ يُعْطَوْا۟ مِنْهَآ إِذَا هُمْ يَسْخَطُونَ','Wa minhum mai yalmizuka fis sadaqaati fa-in u\'too minhaa radoo wa illam yu\'taw minhaaa izaa hum yaskhatoon',58,'9:58',20,78,162,2,0,196,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1294,9,'وَلَوْ أَنَّهُمْ رَضُوا۟ مَآ ءَاتَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ وَقَالُوا۟ حَسْبُنَا ٱللَّهُ سَيُؤْتِينَا ٱللَّهُ مِن فَضْلِهِۦ وَرَسُولُهُۥٓ إِنَّآ إِلَى ٱللَّهِ رَٰغِبُونَ','Wa law annahum radoo maaa aataahumul laahu wa Rasooluhoo wa qaaloo hasbunal laahu wayu\'teenallaahu min fadlihee wa Rasooluhooo innaaa ilallaahi raaghiboon',59,'9:59',20,78,162,2,0,196,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1295,9,'۞ إِنَّمَا ٱلصَّدَقَـٰتُ لِلْفُقَرَآءِ وَٱلْمَسَـٰكِينِ وَٱلْعَـٰمِلِينَ عَلَيْهَا وَٱلْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِى ٱلرِّقَابِ وَٱلْغَـٰرِمِينَ وَفِى سَبِيلِ ٱللَّهِ وَٱبْنِ ٱلسَّبِيلِ ۖ فَرِيضَةً مِّنَ ٱللَّهِ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ','Innamas sadaqaatu lilfuqaraaa\'i walmasaakeeni wal \'aamileena \'alaihaa wal mu\'al lafati quloobuhum wa fir riqaabi walghaarimeena wa fee sabeelil laahi wabnis sabeeli fareedatam minal laah; wal laahu \'Aleemun Hakeem',60,'9:60',20,79,163,2,0,196,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1296,9,'وَمِنْهُمُ ٱلَّذِينَ يُؤْذُونَ ٱلنَّبِىَّ وَيَقُولُونَ هُوَ أُذُنٌ ۚ قُلْ أُذُنُ خَيْرٍ لَّكُمْ يُؤْمِنُ بِٱللَّهِ وَيُؤْمِنُ لِلْمُؤْمِنِينَ وَرَحْمَةٌ لِّلَّذِينَ ءَامَنُوا۟ مِنكُمْ ۚ وَٱلَّذِينَ يُؤْذُونَ رَسُولَ ٱللَّهِ لَهُمْ عَذَابٌ أَلِيمٌ','Wa minhumul lazeena yu\'zoonan nabiyya wa yaqooloona huwa uzun; qul uzunu khairil lakum yu\'minu billaahi wa yu\'minu lilmu mi neena wa rahmatul lillazeena aamanoo minkum; wallazeena yu\'zoona Rasoolal laahi lahum \'azaabun aleem',61,'9:61',20,79,163,2,0,196,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1297,9,'يَحْلِفُونَ بِٱللَّهِ لَكُمْ لِيُرْضُوكُمْ وَٱللَّهُ وَرَسُولُهُۥٓ أَحَقُّ أَن يُرْضُوهُ إِن كَانُوا۟ مُؤْمِنِينَ','yahlifoona billaahi lakum liyurdookum wallaahu wa Rasooluhoo ahaqqu ai yurdoohu in kaanoo mu\'mineen',62,'9:62',20,79,163,2,0,197,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1298,9,'أَلَمْ يَعْلَمُوٓا۟ أَنَّهُۥ مَن يُحَادِدِ ٱللَّهَ وَرَسُولَهُۥ فَأَنَّ لَهُۥ نَارَ جَهَنَّمَ خَـٰلِدًا فِيهَا ۚ ذَٰلِكَ ٱلْخِزْىُ ٱلْعَظِيمُ','Alam ya\'lamooo annahoo mai yuhaadidillaaha wa Rasoolahoo faanna lahoo Naara jahannama khaalidan feehaa; zaalikal khizyul \'Azeem',63,'9:63',20,79,163,2,0,197,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1299,9,'يَحْذَرُ ٱلْمُنَـٰفِقُونَ أَن تُنَزَّلَ عَلَيْهِمْ سُورَةٌ تُنَبِّئُهُم بِمَا فِى قُلُوبِهِمْ ۚ قُلِ ٱسْتَهْزِءُوٓا۟ إِنَّ ٱللَّهَ مُخْرِجٌ مَّا تَحْذَرُونَ','Yahzarul munaafiqoona an tunaz zala \'alaihim Sooratun tunabbi \'uhum bimaa feequloobihim; qulistahzi\'oo innal laaha mukhrijum maa tahzaroon',64,'9:64',20,79,163,2,0,197,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1300,9,'وَلَئِن سَأَلْتَهُمْ لَيَقُولُنَّ إِنَّمَا كُنَّا نَخُوضُ وَنَلْعَبُ ۚ قُلْ أَبِٱللَّهِ وَءَايَـٰتِهِۦ وَرَسُولِهِۦ كُنتُمْ تَسْتَهْزِءُونَ','Wala\'in sa altahum layaqoolunna innamaa kunnaa nakhoodu wa nal\'ab; qul abillaahi wa \'Aayaatihee wa Rasoolihee kuntum tastahzi\'oon',65,'9:65',20,79,163,2,0,197,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1301,9,'لَا تَعْتَذِرُوا۟ قَدْ كَفَرْتُم بَعْدَ إِيمَـٰنِكُمْ ۚ إِن نَّعْفُ عَن طَآئِفَةٍ مِّنكُمْ نُعَذِّبْ طَآئِفَةًۢ بِأَنَّهُمْ كَانُوا۟ مُجْرِمِينَ','Laa ta\'taziroo qad kafartum ba\'da eemaanikum; in na\'fu \'an taaa\'ifatim minkum nu\'az zib taaa\'ifatam bi annahum kaanoo mujrimeen',66,'9:66',20,79,163,2,0,197,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1302,9,'ٱلْمُنَـٰفِقُونَ وَٱلْمُنَـٰفِقَـٰتُ بَعْضُهُم مِّنۢ بَعْضٍ ۚ يَأْمُرُونَ بِٱلْمُنكَرِ وَيَنْهَوْنَ عَنِ ٱلْمَعْرُوفِ وَيَقْبِضُونَ أَيْدِيَهُمْ ۚ نَسُوا۟ ٱللَّهَ فَنَسِيَهُمْ ۗ إِنَّ ٱلْمُنَـٰفِقِينَ هُمُ ٱلْفَـٰسِقُونَ','Almunaafiqoona wal munaafiqaatu ba\'duhum mim ba\'d; yaamuroona bilmunkari wa yanhawna \'anil ma\'roofi wa yaqbidoona aidiyahum; nasul laaha fanasiyahum; innal munaafiqeena humul faasiqoon',67,'9:67',20,79,164,2,0,197,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1303,9,'وَعَدَ ٱللَّهُ ٱلْمُنَـٰفِقِينَ وَٱلْمُنَـٰفِقَـٰتِ وَٱلْكُفَّارَ نَارَ جَهَنَّمَ خَـٰلِدِينَ فِيهَا ۚ هِىَ حَسْبُهُمْ ۚ وَلَعَنَهُمُ ٱللَّهُ ۖ وَلَهُمْ عَذَابٌ مُّقِيمٌ','Wa\'adal laahul munafiqeena wal munaafiqaati wal kuffaara naara jahannnamma khaalideena feehaa; hiya hasbuhum; wa la\'annahumul laahu wa lahum \'azaabum muqeem',68,'9:68',20,79,164,2,0,197,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1304,9,'كَٱلَّذِينَ مِن قَبْلِكُمْ كَانُوٓا۟ أَشَدَّ مِنكُمْ قُوَّةً وَأَكْثَرَ أَمْوَٰلًا وَأَوْلَـٰدًا فَٱسْتَمْتَعُوا۟ بِخَلَـٰقِهِمْ فَٱسْتَمْتَعْتُم بِخَلَـٰقِكُمْ كَمَا ٱسْتَمْتَعَ ٱلَّذِينَ مِن قَبْلِكُم بِخَلَـٰقِهِمْ وَخُضْتُمْ كَٱلَّذِى خَاضُوٓا۟ ۚ أُو۟لَـٰٓئِكَ حَبِطَتْ أَعْمَـٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ ۖ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْخَـٰسِرُونَ','Kallazeena min qablikum kaanoo ashadda minkum quwwatanw wa aksara amwaalanw wa awlaadan fastamta\'oo bikhalaaqihim fastamta\'tum bikhalaaqikum kamas tamta\'al lazeena min qablikum bikhalaa qihim wa khudtum kallazee khaadooo; ulaaa\'ika habitat a\'maaluhum fid dunyaa wal Aakhirati wa ulaaa\'ika humul khaasiroon',69,'9:69',20,79,164,2,0,198,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1305,9,'أَلَمْ يَأْتِهِمْ نَبَأُ ٱلَّذِينَ مِن قَبْلِهِمْ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ وَقَوْمِ إِبْرَٰهِيمَ وَأَصْحَـٰبِ مَدْيَنَ وَٱلْمُؤْتَفِكَـٰتِ ۚ أَتَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَـٰتِ ۖ فَمَا كَانَ ٱللَّهُ لِيَظْلِمَهُمْ وَلَـٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ','Alam yaatihim naba ul lazeena min qablihim qawmi Noohinw wa \'Aadinw wa Samooda wa qawmi Ibraaheema wa ashaabi adyana walmu\'tafikaat; atathum Rusuluhum bilbaiyinaati famaa kaanal laahu liyazlimahum wa laakin kaanooo anfusahum yazlimoon',70,'9:70',20,79,164,2,0,198,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1306,9,'وَٱلْمُؤْمِنُونَ وَٱلْمُؤْمِنَـٰتُ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ ۚ يَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَيُطِيعُونَ ٱللَّهَ وَرَسُولَهُۥٓ ۚ أُو۟لَـٰٓئِكَ سَيَرْحَمُهُمُ ٱللَّهُ ۗ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ','Walmu\'minoona wal mu\'minaatu ba\'duhum awliyaaa\'u ba;d; yaamuroona bilma\'roofi wa yanhawna \'anil munkari wa yuqeemoonas Salaata wa yu\'toonaz Zakaata wa yutee\'oonal laaha wa Rasoolah; ulaaa\'ika sayarhamuhumul laah; innallaaha \'Azeezun Hakeem',71,'9:71',20,79,164,2,0,198,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1307,9,'وَعَدَ ٱللَّهُ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَـٰتِ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا وَمَسَـٰكِنَ طَيِّبَةً فِى جَنَّـٰتِ عَدْنٍ ۚ وَرِضْوَٰنٌ مِّنَ ٱللَّهِ أَكْبَرُ ۚ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ','Wa\'adal laahulmu\' mineena walmu\'minaati Jannaatin tajree min tahtihal anhaaru khaalideena feehaa wa masaakina taiyibatan fee Jannnaati \'adn; wa ridwaanum minal laahi akbar; zaalika hual fawzul \'azeem',72,'9:72',20,79,164,2,0,198,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1308,9,'يَـٰٓأَيُّهَا ٱلنَّبِىُّ جَـٰهِدِ ٱلْكُفَّارَ وَٱلْمُنَـٰفِقِينَ وَٱغْلُظْ عَلَيْهِمْ ۚ وَمَأْوَىٰهُمْ جَهَنَّمُ ۖ وَبِئْسَ ٱلْمَصِيرُ','yaaa aiyuhan Nabiyyu jaahidil kuffaara walmunaafiqeena waghluz \'alaihim; wa maawaahum jahannnamu wa bi\'sal maseer',73,'9:73',20,79,165,2,0,199,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1309,9,'يَحْلِفُونَ بِٱللَّهِ مَا قَالُوا۟ وَلَقَدْ قَالُوا۟ كَلِمَةَ ٱلْكُفْرِ وَكَفَرُوا۟ بَعْدَ إِسْلَـٰمِهِمْ وَهَمُّوا۟ بِمَا لَمْ يَنَالُوا۟ ۚ وَمَا نَقَمُوٓا۟ إِلَّآ أَنْ أَغْنَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ مِن فَضْلِهِۦ ۚ فَإِن يَتُوبُوا۟ يَكُ خَيْرًا لَّهُمْ ۖ وَإِن يَتَوَلَّوْا۟ يُعَذِّبْهُمُ ٱللَّهُ عَذَابًا أَلِيمًا فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ ۚ وَمَا لَهُمْ فِى ٱلْأَرْضِ مِن وَلِىٍّ وَلَا نَصِيرٍ','Yahlifoona billaahi wa qaaloo wa laqad qaaloo kalimatal kufri wa kafaroo ba\'da Islaamihim wa hammoo bimaa lam yanaaloo; wa maa naqamooo illaaa an aghnaa humullaahu wa Rasooluhoo min fadlih; fainy yatooboo yaku khairal lahum wa iny yatawal law yu\'az zibhumullaahu \'azaaban aleeman fiddunyaa wal Aakhirah; wamaa lahum fil ardi minw waliyyinw wa laa naseer',74,'9:74',20,79,165,2,0,199,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1310,9,'۞ وَمِنْهُم مَّنْ عَـٰهَدَ ٱللَّهَ لَئِنْ ءَاتَىٰنَا مِن فَضْلِهِۦ لَنَصَّدَّقَنَّ وَلَنَكُونَنَّ مِنَ ٱلصَّـٰلِحِينَ','Wa minhum man \'aaha dal laaha la\'in aataanaa min fadlihee lanas saddaqanna wa lanakoonanna minassaaliheen',75,'9:75',20,80,165,2,0,199,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1311,9,'فَلَمَّآ ءَاتَىٰهُم مِّن فَضْلِهِۦ بَخِلُوا۟ بِهِۦ وَتَوَلَّوا۟ وَّهُم مُّعْرِضُونَ','Falammaaa aataahum min fadlihee bakhiloo bihee wa tawallaw wa hum mu\'ridoon',76,'9:76',20,80,165,2,0,199,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1312,9,'فَأَعْقَبَهُمْ نِفَاقًا فِى قُلُوبِهِمْ إِلَىٰ يَوْمِ يَلْقَوْنَهُۥ بِمَآ أَخْلَفُوا۟ ٱللَّهَ مَا وَعَدُوهُ وَبِمَا كَانُوا۟ يَكْذِبُونَ','Fa a\'qabahum nifaaqan fee quloobihim ilaa Yawmi yalqaw nahoo bimaaa akhlaful laaha maa wa\'adoohu wa bimaa kaanoo yakhziboon',77,'9:77',20,80,165,2,0,199,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1313,9,'أَلَمْ يَعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ سِرَّهُمْ وَنَجْوَىٰهُمْ وَأَنَّ ٱللَّهَ عَلَّـٰمُ ٱلْغُيُوبِ','Alam ya\'lamooo annal laaha ya\'lamu sirrahum wa najwaahum wa annal laaha \'Allaamul Ghuyoob',78,'9:78',20,80,165,2,0,199,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1314,9,'ٱلَّذِينَ يَلْمِزُونَ ٱلْمُطَّوِّعِينَ مِنَ ٱلْمُؤْمِنِينَ فِى ٱلصَّدَقَـٰتِ وَٱلَّذِينَ لَا يَجِدُونَ إِلَّا جُهْدَهُمْ فَيَسْخَرُونَ مِنْهُمْ ۙ سَخِرَ ٱللَّهُ مِنْهُمْ وَلَهُمْ عَذَابٌ أَلِيمٌ','Allazeena yalmizoonal mut tawwi\'eena minalmu\'mineena fis sadaqaati wallazeena laa yajidoona illaa juhdahum fayaskharoona minhum sakhiral laahu minhum wa lahum azaabun aleem',79,'9:79',20,80,165,2,0,199,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1315,9,'ٱسْتَغْفِرْ لَهُمْ أَوْ لَا تَسْتَغْفِرْ لَهُمْ إِن تَسْتَغْفِرْ لَهُمْ سَبْعِينَ مَرَّةً فَلَن يَغْفِرَ ٱللَّهُ لَهُمْ ۚ ذَٰلِكَ بِأَنَّهُمْ كَفَرُوا۟ بِٱللَّهِ وَرَسُولِهِۦ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَـٰسِقِينَ','istaghfir lahum aw laa tastaghfir lahum in tastaghfir lahum sab\'eena marratan falany yaghfiral laahu lahum; zaalika bi annahum kafaroo billaahi wa Rasoolih; wallaahu laa yahdil qawmal faasiqeen',80,'9:80',20,80,165,2,0,200,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1316,9,'فَرِحَ ٱلْمُخَلَّفُونَ بِمَقْعَدِهِمْ خِلَـٰفَ رَسُولِ ٱللَّهِ وَكَرِهُوٓا۟ أَن يُجَـٰهِدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ وَقَالُوا۟ لَا تَنفِرُوا۟ فِى ٱلْحَرِّ ۗ قُلْ نَارُ جَهَنَّمَ أَشَدُّ حَرًّا ۚ لَّوْ كَانُوا۟ يَفْقَهُونَ','Farihal mukhallafoona bimaq\'adihim khilaafa Rasoolil laahi wa karihooo ai yujaahidoo bi amwaalihim wa anfusihim fee sabeelil laahi wa qaaloo la tanfiroo fil harr; qul Naaru jahannama ashaddu harraa; law kaanoo yafqahoon',81,'9:81',20,80,166,2,0,200,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1317,9,'فَلْيَضْحَكُوا۟ قَلِيلًا وَلْيَبْكُوا۟ كَثِيرًا جَزَآءًۢ بِمَا كَانُوا۟ يَكْسِبُونَ','Falyadhakoo qaleelanw walyabkoo kaseeran jazaaa\'am bimaa kaanoo yaksiboon',82,'9:82',20,80,166,2,0,200,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1318,9,'فَإِن رَّجَعَكَ ٱللَّهُ إِلَىٰ طَآئِفَةٍ مِّنْهُمْ فَٱسْتَـْٔذَنُوكَ لِلْخُرُوجِ فَقُل لَّن تَخْرُجُوا۟ مَعِىَ أَبَدًا وَلَن تُقَـٰتِلُوا۟ مَعِىَ عَدُوًّا ۖ إِنَّكُمْ رَضِيتُم بِٱلْقُعُودِ أَوَّلَ مَرَّةٍ فَٱقْعُدُوا۟ مَعَ ٱلْخَـٰلِفِينَ','Fa ir raja\'akal laahu ilaa taaa\'ifatim minhum fastaaa zanooka lilkhurooji faqul lan takhrujoo ma\'iya abadanw a lan tuqaatiloo ma\'iya \'aduwwan innakum radeetum bilqu\'oodi awwala marratin faq\'udoo ma\'al khaalifeen',83,'9:83',20,80,166,2,0,200,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1319,9,'وَلَا تُصَلِّ عَلَىٰٓ أَحَدٍ مِّنْهُم مَّاتَ أَبَدًا وَلَا تَقُمْ عَلَىٰ قَبْرِهِۦٓ ۖ إِنَّهُمْ كَفَرُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَمَاتُوا۟ وَهُمْ فَـٰسِقُونَ','Wa laa tusalli \'alaaa ahadim minhum maata abadanw wa laa taqum \'alaa qabriheee innahum kafaroo billaahi wa Rasoolihee wa maatoo wa hum faasiqoon',84,'9:84',20,80,166,2,0,200,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1320,9,'وَلَا تُعْجِبْكَ أَمْوَٰلُهُمْ وَأَوْلَـٰدُهُمْ ۚ إِنَّمَا يُرِيدُ ٱللَّهُ أَن يُعَذِّبَهُم بِهَا فِى ٱلدُّنْيَا وَتَزْهَقَ أَنفُسُهُمْ وَهُمْ كَـٰفِرُونَ','Wa laa tu\'jibka amwaa luhum wa awlaaduhum; innamaa yureedul laahu ai yu\'az zibahum bihaa fid dunyaa wa tazhaqa anfusuhum wa hum kaafiroon',85,'9:85',20,80,166,2,0,200,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1321,9,'وَإِذَآ أُنزِلَتْ سُورَةٌ أَنْ ءَامِنُوا۟ بِٱللَّهِ وَجَـٰهِدُوا۟ مَعَ رَسُولِهِ ٱسْتَـْٔذَنَكَ أُو۟لُوا۟ ٱلطَّوْلِ مِنْهُمْ وَقَالُوا۟ ذَرْنَا نَكُن مَّعَ ٱلْقَـٰعِدِينَ','Wa izaaa unzilat Sooratun an aaminoo billaahi wa jaahidoo ma\'a Rasoolihis taazanaka uluttawli minhum wa qaaloo zarnaa nakum ma\'alqaa \'ideen',86,'9:86',20,80,166,2,0,200,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1322,9,'رَضُوا۟ بِأَن يَكُونُوا۟ مَعَ ٱلْخَوَالِفِ وَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ','Radoo bi ai yakoonoo ma\'al khawaalifi wa tubi\'a \'alaa quloobihim fahum laa yafqahoon',87,'9:87',20,80,166,2,0,201,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1323,9,'لَـٰكِنِ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ جَـٰهَدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ ۚ وَأُو۟لَـٰٓئِكَ لَهُمُ ٱلْخَيْرَٰتُ ۖ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ','Laakinir Rasoolu wal lazeena aamanoo ma\'ahoo jaahadoo bi amwaalihim wa anfusihim; wa ulaaa\'ika lahumul khairaatu wa ulaaa\'ika humul muflihoon',88,'9:88',20,80,166,2,0,201,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1324,9,'أَعَدَّ ٱللَّهُ لَهُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ','A\'addal laahu lahum Jannaatin tajree min tahtihal anhaaru khaalideena feehaa; zaalikal fawzul \'azeem',89,'9:89',20,80,166,2,0,201,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1325,9,'وَجَآءَ ٱلْمُعَذِّرُونَ مِنَ ٱلْأَعْرَابِ لِيُؤْذَنَ لَهُمْ وَقَعَدَ ٱلَّذِينَ كَذَبُوا۟ ٱللَّهَ وَرَسُولَهُۥ ۚ سَيُصِيبُ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ عَذَابٌ أَلِيمٌ','Wa jaaa\'al mu\'az ziroona minal A\'raabi liyu\'zana lahum wa qa\'adal lazeena kazabul laaha wa Rasoolah; sayuseebul lazeena kafaroo minhum \'azaabun aleem',90,'9:90',20,80,167,2,0,201,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1326,9,'لَّيْسَ عَلَى ٱلضُّعَفَآءِ وَلَا عَلَى ٱلْمَرْضَىٰ وَلَا عَلَى ٱلَّذِينَ لَا يَجِدُونَ مَا يُنفِقُونَ حَرَجٌ إِذَا نَصَحُوا۟ لِلَّهِ وَرَسُولِهِۦ ۚ مَا عَلَى ٱلْمُحْسِنِينَ مِن سَبِيلٍ ۚ وَٱللَّهُ غَفُورٌ رَّحِيمٌ','Laisa \'alad du\'aaaa\'i wa laa \'alal mardaa wa laa \'alal lazeena laa yajidoona maa yunfiqoona harajun izaa nasahoo lillaahi wa Rasoolih; maa \'alal muhsineena min sabeel; wallaahu Ghafoorur Raheem',91,'9:91',20,80,167,2,0,201,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1327,9,'وَلَا عَلَى ٱلَّذِينَ إِذَا مَآ أَتَوْكَ لِتَحْمِلَهُمْ قُلْتَ لَآ أَجِدُ مَآ أَحْمِلُكُمْ عَلَيْهِ تَوَلَّوا۟ وَّأَعْيُنُهُمْ تَفِيضُ مِنَ ٱلدَّمْعِ حَزَنًا أَلَّا يَجِدُوا۟ مَا يُنفِقُونَ','Wa laa \'alal lazeena izaa maaa atawka litahmilahum qulta laaa ajidu maaa ahmilukum \'alaihi tawallaw wa a\'yunuhum tafeedu minaddam\'i hazanan allaa yajidoo maa yunfiqoon',92,'9:92',20,80,167,2,0,201,10,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1328,9,'۞ إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَسْتَـْٔذِنُونَكَ وَهُمْ أَغْنِيَآءُ ۚ رَضُوا۟ بِأَن يَكُونُوا۟ مَعَ ٱلْخَوَالِفِ وَطَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَعْلَمُونَ','Innamas sabeelu \'alal lazeena yastaazinoonaka wa hum aghniyaaa\'; radoo biany-yakoonoo ma\'al khawaalifi wa taba\'al laahu \'alaa quloobihim fahum laa ya\'lamoon',93,'9:93',21,81,167,2,0,201,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1329,9,'يَعْتَذِرُونَ إِلَيْكُمْ إِذَا رَجَعْتُمْ إِلَيْهِمْ ۚ قُل لَّا تَعْتَذِرُوا۟ لَن نُّؤْمِنَ لَكُمْ قَدْ نَبَّأَنَا ٱللَّهُ مِنْ أَخْبَارِكُمْ ۚ وَسَيَرَى ٱللَّهُ عَمَلَكُمْ وَرَسُولُهُۥ ثُمَّ تُرَدُّونَ إِلَىٰ عَـٰلِمِ ٱلْغَيْبِ وَٱلشَّهَـٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ','ya\'taziroona ilaikum izaa raja\'tum ilaihim; qul laa ta\'taziroo lan nu\'mina lakum qad nabba annal laahu min akhbaarikum; wa sa yaral laahu \'amalakum wa Rasooluhoo suma turaddoona ilaa \'Aalimil Ghaibi washshahaadati fa yunabbi\'ukum bimaa kuntum ta\'maloon',94,'9:94',21,81,167,2,0,202,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1330,9,'سَيَحْلِفُونَ بِٱللَّهِ لَكُمْ إِذَا ٱنقَلَبْتُمْ إِلَيْهِمْ لِتُعْرِضُوا۟ عَنْهُمْ ۖ فَأَعْرِضُوا۟ عَنْهُمْ ۖ إِنَّهُمْ رِجْسٌ ۖ وَمَأْوَىٰهُمْ جَهَنَّمُ جَزَآءًۢ بِمَا كَانُوا۟ يَكْسِبُونَ','Sa yahlifoona billaahi lakum izanqalabtum ilaihim litu\'ridoo \'anhum fa a\'ridoo \'anhum innahum rijsunw wa maawaahum jahannamu jazaaa \'ambimaa kaanoo yaksiboon',95,'9:95',21,81,167,2,0,202,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1331,9,'يَحْلِفُونَ لَكُمْ لِتَرْضَوْا۟ عَنْهُمْ ۖ فَإِن تَرْضَوْا۟ عَنْهُمْ فَإِنَّ ٱللَّهَ لَا يَرْضَىٰ عَنِ ٱلْقَوْمِ ٱلْفَـٰسِقِينَ','Yahlifoona lakum litardaw \'anhum fa in tardaw \'anhum fa innal laaha laa yardaa \'anil qawmil faasiqeen',96,'9:96',21,81,167,2,0,202,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1332,9,'ٱلْأَعْرَابُ أَشَدُّ كُفْرًا وَنِفَاقًا وَأَجْدَرُ أَلَّا يَعْلَمُوا۟ حُدُودَ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ','Al A\'raabu ashaddu kufranw wa nifaaqanw wa ajdaru allaa ya\'lamoo hudooda maaa anzalal laahu \'alaa Rasoolih; wallaahu \'Aleemun Hakeem',97,'9:97',21,81,167,2,0,202,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1333,9,'وَمِنَ ٱلْأَعْرَابِ مَن يَتَّخِذُ مَا يُنفِقُ مَغْرَمًا وَيَتَرَبَّصُ بِكُمُ ٱلدَّوَآئِرَ ۚ عَلَيْهِمْ دَآئِرَةُ ٱلسَّوْءِ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ','Wa minal A\'raabi mai yattakhizu maa yunfiqu maghramanw wa yatarabbasu bikumud dawaaa\'ir; alaihim daaa\'iratus saw\'; wallaahu Samee\'un \'Aleem',98,'9:98',21,81,167,2,0,202,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1334,9,'وَمِنَ ٱلْأَعْرَابِ مَن يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَيَتَّخِذُ مَا يُنفِقُ قُرُبَـٰتٍ عِندَ ٱللَّهِ وَصَلَوَٰتِ ٱلرَّسُولِ ۚ أَلَآ إِنَّهَا قُرْبَةٌ لَّهُمْ ۚ سَيُدْخِلُهُمُ ٱللَّهُ فِى رَحْمَتِهِۦٓ ۗ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ','Wa minal A\'raabi mai yu\'minu billaahi wal yawmil AAkhiri wa yattakhizu maa yunfiqu qurubaatin \'indal laahi wa salawaatir Rasool; alaaa innahaa qurbatul lahum; sayudkhiluhumul laahu fee rahmatih; innal laaha Ghafoorur Raheem',99,'9:99',21,81,167,2,0,202,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1335,9,'وَٱلسَّـٰبِقُونَ ٱلْأَوَّلُونَ مِنَ ٱلْمُهَـٰجِرِينَ وَٱلْأَنصَارِ وَٱلَّذِينَ ٱتَّبَعُوهُم بِإِحْسَـٰنٍ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ وَأَعَدَّ لَهُمْ جَنَّـٰتٍ تَجْرِى تَحْتَهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَآ أَبَدًا ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ','Was saabiqoonal awwa loona minal Muhaajireena wal Ansaari wallazeenat taba\'oo hum bi ihsaanir radiyal laahu \'anhum wa radoo \'anhu wa a\'adda lahum jannnaatin tajree tahtahal anhaaru khaalideena feehaaa abadaa; zaalikal fawzul \'azeem',100,'9:100',21,81,168,2,0,203,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1336,9,'وَمِمَّنْ حَوْلَكُم مِّنَ ٱلْأَعْرَابِ مُنَـٰفِقُونَ ۖ وَمِنْ أَهْلِ ٱلْمَدِينَةِ ۖ مَرَدُوا۟ عَلَى ٱلنِّفَاقِ لَا تَعْلَمُهُمْ ۖ نَحْنُ نَعْلَمُهُمْ ۚ سَنُعَذِّبُهُم مَّرَّتَيْنِ ثُمَّ يُرَدُّونَ إِلَىٰ عَذَابٍ عَظِيمٍ','Wa mimmann hawlakum minal A\'raabi munaafiqoona wa min ahlil Madeenati maradoo \'alan nifaaq, laa ta\'lamuhum nahnu na\'lamuhum; sanu\'azzibuhum marrataini summa yuraddoona ilaa \'azaabin \'azeem',101,'9:101',21,81,168,2,0,203,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1337,9,'وَءَاخَرُونَ ٱعْتَرَفُوا۟ بِذُنُوبِهِمْ خَلَطُوا۟ عَمَلًا صَـٰلِحًا وَءَاخَرَ سَيِّئًا عَسَى ٱللَّهُ أَن يَتُوبَ عَلَيْهِمْ ۚ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ','Wa aakharoona\' tarafoo bizunoobihim khalatoo \'amalan saalihanw wa aakhara saiyi\'an \'asal laahu ai yatooba \'alaihim; innal laaha Ghafoorur Raheem',102,'9:102',21,81,168,2,0,203,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1338,9,'خُذْ مِنْ أَمْوَٰلِهِمْ صَدَقَةً تُطَهِّرُهُمْ وَتُزَكِّيهِم بِهَا وَصَلِّ عَلَيْهِمْ ۖ إِنَّ صَلَوٰتَكَ سَكَنٌ لَّهُمْ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ','Khuz min amwaalihim sadaqtan tutahhiruhum wa tuzakkeehim bihaa wa salli \'alaihim inna salaataka sakanul lahum; wallaahu Samee\'un \'Aleem',103,'9:103',21,81,168,2,0,203,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1339,9,'أَلَمْ يَعْلَمُوٓا۟ أَنَّ ٱللَّهَ هُوَ يَقْبَلُ ٱلتَّوْبَةَ عَنْ عِبَادِهِۦ وَيَأْخُذُ ٱلصَّدَقَـٰتِ وَأَنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ','Alam ya\'lamooo annnal laaha huwa yaqbalut tawbata \'an ibaadihee wa yaakhuzus sadaqaati wa annal laaha Huwat awwaabur Raheem',104,'9:104',21,81,168,2,0,203,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1340,9,'وَقُلِ ٱعْمَلُوا۟ فَسَيَرَى ٱللَّهُ عَمَلَكُمْ وَرَسُولُهُۥ وَٱلْمُؤْمِنُونَ ۖ وَسَتُرَدُّونَ إِلَىٰ عَـٰلِمِ ٱلْغَيْبِ وَٱلشَّهَـٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ','Wa quli\'maloo fasayaral laahu \'amalakum wa Rasooluhoo walmu\'minoona wa saturaddoona ilaa \'Aalimil Ghaibi washshahaadati fa yunabbi\'ukum bimaa kuntum ta\'maloon',105,'9:105',21,81,168,2,0,203,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1341,9,'وَءَاخَرُونَ مُرْجَوْنَ لِأَمْرِ ٱللَّهِ إِمَّا يُعَذِّبُهُمْ وَإِمَّا يَتُوبُ عَلَيْهِمْ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ','Wa aakharoona murjawna li amril laahi imaa yu\'az zibuhum wa immaa yatoobu \'alaihim; wallaahu \'Aleemun Hakeem',106,'9:106',21,81,168,2,0,203,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1342,9,'وَٱلَّذِينَ ٱتَّخَذُوا۟ مَسْجِدًا ضِرَارًا وَكُفْرًا وَتَفْرِيقًۢا بَيْنَ ٱلْمُؤْمِنِينَ وَإِرْصَادًا لِّمَنْ حَارَبَ ٱللَّهَ وَرَسُولَهُۥ مِن قَبْلُ ۚ وَلَيَحْلِفُنَّ إِنْ أَرَدْنَآ إِلَّا ٱلْحُسْنَىٰ ۖ وَٱللَّهُ يَشْهَدُ إِنَّهُمْ لَكَـٰذِبُونَ','Wallazeenat takhazoo masjidan diraaranw wa kufranw wa tafreeqam bainal mu\'mineena wa irsaadal liman haarabal laaha wa Rasoolahoo min qabl; wa la yahlifunna in aradnaaa illal husnaa wallaahu yash hadu innahum lakaaziboon',107,'9:107',21,81,168,2,0,204,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1343,9,'لَا تَقُمْ فِيهِ أَبَدًا ۚ لَّمَسْجِدٌ أُسِّسَ عَلَى ٱلتَّقْوَىٰ مِنْ أَوَّلِ يَوْمٍ أَحَقُّ أَن تَقُومَ فِيهِ ۚ فِيهِ رِجَالٌ يُحِبُّونَ أَن يَتَطَهَّرُوا۟ ۚ وَٱللَّهُ يُحِبُّ ٱلْمُطَّهِّرِينَ','Laa taqum feehi abadaa; lamasjidun ussisa \'alat taqwaa min awwali yawmin ahaqqu an taqooma feeh; feehi rijaaluny yuhibbona ai yatatahharoo, wallaahu yuhibbul mmuttah hireen',108,'9:108',21,81,168,2,0,204,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1344,9,'أَفَمَنْ أَسَّسَ بُنْيَـٰنَهُۥ عَلَىٰ تَقْوَىٰ مِنَ ٱللَّهِ وَرِضْوَٰنٍ خَيْرٌ أَم مَّنْ أَسَّسَ بُنْيَـٰنَهُۥ عَلَىٰ شَفَا جُرُفٍ هَارٍ فَٱنْهَارَ بِهِۦ فِى نَارِ جَهَنَّمَ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ','Afaman assasa bunyaa nahoo \'alaa taqwaa minal laahi wa ridwaanin khairun am man assasa bunyaanahoo \'alaa shafaa jurufin haarin fanhaara bihee fee Naari Jahannnam; wallaahu laa yahdil qawmaz zaalimeen',109,'9:109',21,81,168,2,0,204,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1345,9,'لَا يَزَالُ بُنْيَـٰنُهُمُ ٱلَّذِى بَنَوْا۟ رِيبَةً فِى قُلُوبِهِمْ إِلَّآ أَن تَقَطَّعَ قُلُوبُهُمْ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ','Laa yazaalu bunyaanu humul lazee banaw reebatan fee quloobihim illaaa an taqatta\'a quloobuhum; wal laahu \'Aleemun Hakeem',110,'9:110',21,81,168,2,0,204,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1346,9,'۞ إِنَّ ٱللَّهَ ٱشْتَرَىٰ مِنَ ٱلْمُؤْمِنِينَ أَنفُسَهُمْ وَأَمْوَٰلَهُم بِأَنَّ لَهُمُ ٱلْجَنَّةَ ۚ يُقَـٰتِلُونَ فِى سَبِيلِ ٱللَّهِ فَيَقْتُلُونَ وَيُقْتَلُونَ ۖ وَعْدًا عَلَيْهِ حَقًّا فِى ٱلتَّوْرَىٰةِ وَٱلْإِنجِيلِ وَٱلْقُرْءَانِ ۚ وَمَنْ أَوْفَىٰ بِعَهْدِهِۦ مِنَ ٱللَّهِ ۚ فَٱسْتَبْشِرُوا۟ بِبَيْعِكُمُ ٱلَّذِى بَايَعْتُم بِهِۦ ۚ وَذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ','Innal laahash taraa minal mu\'mineena anfusahum wa amwaalahum bi anna lahumul jannah; yuqaatiloona fee sabeelil laahi fa yaqtuloona wa yuqtaloona wa\'dan \'alaihi haqqan fit Tawraati wal Injeeli wal Qur-aan; wa man awfaa be\'ahdihee minal laah; fastabshiroo bibai\'ikumul lazee baaya\'tum bih; wa zaalika huwal fawzul \'azeem',111,'9:111',21,82,169,2,0,204,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1347,9,'ٱلتَّـٰٓئِبُونَ ٱلْعَـٰبِدُونَ ٱلْحَـٰمِدُونَ ٱلسَّـٰٓئِحُونَ ٱلرَّٰكِعُونَ ٱلسَّـٰجِدُونَ ٱلْـَٔامِرُونَ بِٱلْمَعْرُوفِ وَٱلنَّاهُونَ عَنِ ٱلْمُنكَرِ وَٱلْحَـٰفِظُونَ لِحُدُودِ ٱللَّهِ ۗ وَبَشِّرِ ٱلْمُؤْمِنِينَ','At taaa\'iboonal \'aabidoonal haamidoonas saaa\'ihoonar raaki\'oonas saajidoonal aamiroona bilma\'roofi wannaahoona \'anil munkari walhaafizoona lihudoodil laah; wa bashshiril mu\'mineen',112,'9:112',21,82,169,2,0,205,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1348,9,'مَا كَانَ لِلنَّبِىِّ وَٱلَّذِينَ ءَامَنُوٓا۟ أَن يَسْتَغْفِرُوا۟ لِلْمُشْرِكِينَ وَلَوْ كَانُوٓا۟ أُو۟لِى قُرْبَىٰ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَـٰبُ ٱلْجَحِيمِ','Maa kaana lin nabiyyi wallazeena aamanooo ai yastaghfiroo lilmushrikeena wa law kaanoo ulee qurbaa mim ba\'di maa tabiyana lahum annahum Ashaabul jaheem',113,'9:113',21,82,169,2,0,205,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1349,9,'وَمَا كَانَ ٱسْتِغْفَارُ إِبْرَٰهِيمَ لِأَبِيهِ إِلَّا عَن مَّوْعِدَةٍ وَعَدَهَآ إِيَّاهُ فَلَمَّا تَبَيَّنَ لَهُۥٓ أَنَّهُۥ عَدُوٌّ لِّلَّهِ تَبَرَّأَ مِنْهُ ۚ إِنَّ إِبْرَٰهِيمَ لَأَوَّٰهٌ حَلِيمٌ','Wa maa kaanas tighfaaru ibraaheema li abeehi illaa \'ammaw \'idatinw wa \'adahaaa iyyaahu falammaa tabaiyana lahooo annahoo \'aduwwul lillaahi tabarra a minh; inna Ibraaheema la awwaahum haleem',114,'9:114',21,82,169,2,0,205,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1350,9,'وَمَا كَانَ ٱللَّهُ لِيُضِلَّ قَوْمًۢا بَعْدَ إِذْ هَدَىٰهُمْ حَتَّىٰ يُبَيِّنَ لَهُم مَّا يَتَّقُونَ ۚ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ','Wa maa kaanal laahu liyudilla qawmam ba\'da iz hadaahum hatta yubaiyina lahum maa yattaqoon; innal laaha bikulli shai\'in \'Aleem',115,'9:115',21,82,169,2,0,205,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1351,9,'إِنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ يُحْىِۦ وَيُمِيتُ ۚ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ','Innal laaha lahoo mulkus samaawaati wal ardi yuhyee wa yumeet; wa maa lakum min doonil laahi minw waliyyinw wa laa naseer',116,'9:116',21,82,169,2,0,205,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1352,9,'لَّقَد تَّابَ ٱللَّهُ عَلَى ٱلنَّبِىِّ وَٱلْمُهَـٰجِرِينَ وَٱلْأَنصَارِ ٱلَّذِينَ ٱتَّبَعُوهُ فِى سَاعَةِ ٱلْعُسْرَةِ مِنۢ بَعْدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقٍ مِّنْهُمْ ثُمَّ تَابَ عَلَيْهِمْ ۚ إِنَّهُۥ بِهِمْ رَءُوفٌ رَّحِيمٌ','Laqat taabal laahu \'alan nabiyyi wal Muhaajireena wal Ansaaril lazeenat taba\'oohu fee saa\'atil \'usrati mim ba\'di maa kaada yazeeghu quloobu fareeqim minhum summma taaba \'alaihim; innahoo bihim Ra\'oofur Raheem',117,'9:117',21,82,169,2,0,205,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1353,9,'وَعَلَى ٱلثَّلَـٰثَةِ ٱلَّذِينَ خُلِّفُوا۟ حَتَّىٰٓ إِذَا ضَاقَتْ عَلَيْهِمُ ٱلْأَرْضُ بِمَا رَحُبَتْ وَضَاقَتْ عَلَيْهِمْ أَنفُسُهُمْ وَظَنُّوٓا۟ أَن لَّا مَلْجَأَ مِنَ ٱللَّهِ إِلَّآ إِلَيْهِ ثُمَّ تَابَ عَلَيْهِمْ لِيَتُوبُوٓا۟ ۚ إِنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ','Wa \'alas salaasatil lazeena khullifoo hattaaa izaa daaqat \'alaihimul ardu bimaa rahubat wa daaqat \'alaihim anfusuhum wa zannnooo al laa malja-a minal laahi illaaa ilaihi summa taaba \'alaihim liyatooboo; innal laaha Huwat Tawwaabur Raheem',118,'9:118',21,82,169,2,0,206,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1354,9,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَكُونُوا۟ مَعَ ٱلصَّـٰدِقِينَ','Yaaa aiyuhal lazeena aamanut taqul laaha wa koonoo ma\'as saadiqeen',119,'9:119',21,82,170,2,0,206,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1355,9,'مَا كَانَ لِأَهْلِ ٱلْمَدِينَةِ وَمَنْ حَوْلَهُم مِّنَ ٱلْأَعْرَابِ أَن يَتَخَلَّفُوا۟ عَن رَّسُولِ ٱللَّهِ وَلَا يَرْغَبُوا۟ بِأَنفُسِهِمْ عَن نَّفْسِهِۦ ۚ ذَٰلِكَ بِأَنَّهُمْ لَا يُصِيبُهُمْ ظَمَأٌ وَلَا نَصَبٌ وَلَا مَخْمَصَةٌ فِى سَبِيلِ ٱللَّهِ وَلَا يَطَـُٔونَ مَوْطِئًا يَغِيظُ ٱلْكُفَّارَ وَلَا يَنَالُونَ مِنْ عَدُوٍّ نَّيْلًا إِلَّا كُتِبَ لَهُم بِهِۦ عَمَلٌ صَـٰلِحٌ ۚ إِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ','Maa kaana li ahlil Madeenati wa man hawlahum minal A\'raabi ai yatakhallafoo \'ar-Rasoolil laahi wa laa yarghaboo bi anfusihim \'an nafsih; zaalika bi annahum laa yuseebuhum zama unw wa laa nasabunw wa laa makhmasatun fee sabeelil laahi wa laa yata\'oona mawti\'ai yagheezul kuffaara wa laa yanaaloona min \'aduwwin nailan illaa kutiba lahum bihee \'amalun saalih; innal laaha laa yudee\'u ajral muhsineen',120,'9:120',21,82,170,2,0,206,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1356,9,'وَلَا يُنفِقُونَ نَفَقَةً صَغِيرَةً وَلَا كَبِيرَةً وَلَا يَقْطَعُونَ وَادِيًا إِلَّا كُتِبَ لَهُمْ لِيَجْزِيَهُمُ ٱللَّهُ أَحْسَنَ مَا كَانُوا۟ يَعْمَلُونَ','Wa laa yunfiqoona nafa qatan sagheeratanw wa laa kabeeratanw wa laa yaqta\'oona waadiyan illaa kutiba lahum liyajziyahumul laahu ahsana maa kaanoo ya\'maloon',121,'9:121',21,82,170,2,0,206,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1357,9,'۞ وَمَا كَانَ ٱلْمُؤْمِنُونَ لِيَنفِرُوا۟ كَآفَّةً ۚ فَلَوْلَا نَفَرَ مِن كُلِّ فِرْقَةٍ مِّنْهُمْ طَآئِفَةٌ لِّيَتَفَقَّهُوا۟ فِى ٱلدِّينِ وَلِيُنذِرُوا۟ قَوْمَهُمْ إِذَا رَجَعُوٓا۟ إِلَيْهِمْ لَعَلَّهُمْ يَحْذَرُونَ','Wa maa kaanal mu\'minoona liyanfiroo kaaaffah; falaw laa nafara min kulli firqatim minhum taaa\'ifatul liyatafaqqahoo fiddeeni wa liyunziroo qawmahum izaa raja\'ooo ilaihim la\'allahum yahzaroon',122,'9:122',21,83,170,2,0,206,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1358,9,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ قَـٰتِلُوا۟ ٱلَّذِينَ يَلُونَكُم مِّنَ ٱلْكُفَّارِ وَلْيَجِدُوا۟ فِيكُمْ غِلْظَةً ۚ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ','Yaaa aiyuhal lazeena aamanoo qaatilul lazeena yaloonakum minal kuffaari walyajidoo feekum ghilzah; wa\'lamooo annal laaha ma\'al muttaqeen',123,'9:123',21,83,171,2,0,207,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1359,9,'وَإِذَا مَآ أُنزِلَتْ سُورَةٌ فَمِنْهُم مَّن يَقُولُ أَيُّكُمْ زَادَتْهُ هَـٰذِهِۦٓ إِيمَـٰنًا ۚ فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ فَزَادَتْهُمْ إِيمَـٰنًا وَهُمْ يَسْتَبْشِرُونَ','Wa izaa maaa unzilat Sooratun faminhum mai yaqoolu aiyukum zaadat hu haazihee eemaanaa; fa ammal lazeena aamanoo fazaadat hum eemaananw wa hum yastabshiroon',124,'9:124',21,83,171,2,0,207,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1360,9,'وَأَمَّا ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ فَزَادَتْهُمْ رِجْسًا إِلَىٰ رِجْسِهِمْ وَمَاتُوا۟ وَهُمْ كَـٰفِرُونَ','Wa ammal lazeena fee quloobihim maradun fazaadat hum rijsan ilaa rijsihim wa maatoo wa hum kaafiroon',125,'9:125',21,83,171,2,0,207,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1361,9,'أَوَلَا يَرَوْنَ أَنَّهُمْ يُفْتَنُونَ فِى كُلِّ عَامٍ مَّرَّةً أَوْ مَرَّتَيْنِ ثُمَّ لَا يَتُوبُونَ وَلَا هُمْ يَذَّكَّرُونَ','Awalaa yarawna annahum yuftanoona fee kulli \'aamim marratan aw marrataini summa laa yatooboona wa laa hum yazzakkkaroon',126,'9:126',21,83,171,2,0,207,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1362,9,'وَإِذَا مَآ أُنزِلَتْ سُورَةٌ نَّظَرَ بَعْضُهُمْ إِلَىٰ بَعْضٍ هَلْ يَرَىٰكُم مِّنْ أَحَدٍ ثُمَّ ٱنصَرَفُوا۟ ۚ صَرَفَ ٱللَّهُ قُلُوبَهُم بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ','Wa izaa maaa unzilat Sooratun nazara ba\'duhum ilaa ba\'din hal yaraakum min ahadin summman sarafoo; sarafal laahu quloobahum bi annahum qawmul laa yafqahoon',127,'9:127',21,83,171,2,0,207,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1363,9,'لَقَدْ جَآءَكُمْ رَسُولٌ مِّنْ أَنفُسِكُمْ عَزِيزٌ عَلَيْهِ مَا عَنِتُّمْ حَرِيصٌ عَلَيْكُم بِٱلْمُؤْمِنِينَ رَءُوفٌ رَّحِيمٌ','Laqad jaaa\'akum Rasoolum min anfusikum \'azeezun \'alaihi maa \'anittum hareesun \'alaikum bilmu\'mineena ra\'oofur raheem',128,'9:128',21,83,171,2,0,207,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1364,9,'فَإِن تَوَلَّوْا۟ فَقُلْ حَسْبِىَ ٱللَّهُ لَآ إِلَـٰهَ إِلَّا هُوَ ۖ عَلَيْهِ تَوَكَّلْتُ ۖ وَهُوَ رَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ','Fa in tawallaw faqul lhasbiyal laahu laaa ilaaha illaa Huwa \'alaihi tawakkkaltu wa Huwa Rabbul \'Arshil \'Azeem',129,'9:129',21,83,171,2,0,207,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1365,10,'الٓر ۚ تِلْكَ ءَايَـٰتُ ٱلْكِتَـٰبِ ٱلْحَكِيمِ','Alif-Laaam-Raa; tilka Aayaatul Kitaabil Hakeem',1,'10:1',21,83,172,3,0,208,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1366,10,'أَكَانَ لِلنَّاسِ عَجَبًا أَنْ أَوْحَيْنَآ إِلَىٰ رَجُلٍ مِّنْهُمْ أَنْ أَنذِرِ ٱلنَّاسَ وَبَشِّرِ ٱلَّذِينَ ءَامَنُوٓا۟ أَنَّ لَهُمْ قَدَمَ صِدْقٍ عِندَ رَبِّهِمْ ۗ قَالَ ٱلْكَـٰفِرُونَ إِنَّ هَـٰذَا لَسَـٰحِرٌ مُّبِينٌ','A kaana linnaasi \'aaban an awhainaaa ilaa rajulim minhum an anzirin naasa wa bashshiril lazeena aamanoo anna lahum qadama sidqin \'inda Rabbihim; qaalal kaafiroona inna haaza lasaahirum mubeen',2,'10:2',21,83,172,3,0,208,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1367,10,'إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ۖ يُدَبِّرُ ٱلْأَمْرَ ۖ مَا مِن شَفِيعٍ إِلَّا مِنۢ بَعْدِ إِذْنِهِۦ ۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ فَٱعْبُدُوهُ ۚ أَفَلَا تَذَكَّرُونَ','Inna Rabbakumul laahul lazee khalaqas samaawaati wal arda fee sittati aiyaamin summas tawaa \'alal \'Arshi yudabbirul amra maa min shafee\'in illaa mim ba\'di iznih; zalikumul laahu Rabbukum fa\'budooh; afalaa tazakkaroon',3,'10:3',21,83,172,3,0,208,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1368,10,'إِلَيْهِ مَرْجِعُكُمْ جَمِيعًا ۖ وَعْدَ ٱللَّهِ حَقًّا ۚ إِنَّهُۥ يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ لِيَجْزِىَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ بِٱلْقِسْطِ ۚ وَٱلَّذِينَ كَفَرُوا۟ لَهُمْ شَرَابٌ مِّنْ حَمِيمٍ وَعَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْفُرُونَ','Ilaihi marji\'ukum jamee \'anw wa\'dal laahi haqqaa; innahoo yabda\'ul khalqa summa yu\'eeduhoo liyajziyal lazeena aamanoo wa \'amilus saalihaati bilqist; wallazeena kafaroo lahum sharaabum min hamee minw wa \'azaabun aleemum bimaa kaanoo yakfuroon',4,'10:4',21,83,172,3,0,208,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1369,10,'هُوَ ٱلَّذِى جَعَلَ ٱلشَّمْسَ ضِيَآءً وَٱلْقَمَرَ نُورًا وَقَدَّرَهُۥ مَنَازِلَ لِتَعْلَمُوا۟ عَدَدَ ٱلسِّنِينَ وَٱلْحِسَابَ ۚ مَا خَلَقَ ٱللَّهُ ذَٰلِكَ إِلَّا بِٱلْحَقِّ ۚ يُفَصِّلُ ٱلْـَٔايَـٰتِ لِقَوْمٍ يَعْلَمُونَ','Huwal lazee ja\'alash shamsa diyaaa\'anw walqamara nooranw wa qaddarahoo manaaz zila lita\'lamoo \'adadas sineena walhisaab; maa khalaqal laahu zaalika illa bilhaqq; yufassilul aayaati liqawminw ya\'lamoon',5,'10:5',21,83,172,3,0,208,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1370,10,'إِنَّ فِى ٱخْتِلَـٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَمَا خَلَقَ ٱللَّهُ فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ لَـَٔايَـٰتٍ لِّقَوْمٍ يَتَّقُونَ','Inna fikh tilaafil laili wannahaari wa maa khalaqal laahu fis samaawaati wal ardi la Aayaatil liqawminy yattaqoon',6,'10:6',21,83,172,3,0,208,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1371,10,'إِنَّ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا وَرَضُوا۟ بِٱلْحَيَوٰةِ ٱلدُّنْيَا وَٱطْمَأَنُّوا۟ بِهَا وَٱلَّذِينَ هُمْ عَنْ ءَايَـٰتِنَا غَـٰفِلُونَ','Innal lazeena laa yarjoona liqaaa\'anaa wa radoo bilhayaatid dunyaa watma annoo bihaa wallazeena hum \'an Aayaatinaa ghaafiloon',7,'10:7',21,83,172,3,0,209,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1372,10,'أُو۟لَـٰٓئِكَ مَأْوَىٰهُمُ ٱلنَّارُ بِمَا كَانُوا۟ يَكْسِبُونَ','Ulaaa\'ika maawaahumun Naaru bimaa kaanoo yaksiboon',8,'10:8',21,83,172,3,0,209,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1373,10,'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ يَهْدِيهِمْ رَبُّهُم بِإِيمَـٰنِهِمْ ۖ تَجْرِى مِن تَحْتِهِمُ ٱلْأَنْهَـٰرُ فِى جَنَّـٰتِ ٱلنَّعِيمِ','Innal lazeena aamanoo wa \'amilus saalihaati yahdeehim Rabbuhum bi eemaanihim tajree min tahtihimul anhaaru fee jannaatin Na\'eem',9,'10:9',21,83,172,3,0,209,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1374,10,'دَعْوَىٰهُمْ فِيهَا سُبْحَـٰنَكَ ٱللَّهُمَّ وَتَحِيَّتُهُمْ فِيهَا سَلَـٰمٌ ۚ وَءَاخِرُ دَعْوَىٰهُمْ أَنِ ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَـٰلَمِينَ','Da\'waahum feehaa Subbaanakal laahumma wa tahiyyatuhum feehaa salaam; wa aakhiru da\'waahum anil hamdu lillaahi Rabbil \'aalameen',10,'10:10',21,83,172,3,0,209,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1375,10,'۞ وَلَوْ يُعَجِّلُ ٱللَّهُ لِلنَّاسِ ٱلشَّرَّ ٱسْتِعْجَالَهُم بِٱلْخَيْرِ لَقُضِىَ إِلَيْهِمْ أَجَلُهُمْ ۖ فَنَذَرُ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا فِى طُغْيَـٰنِهِمْ يَعْمَهُونَ','Wa law yu\'aijilul laahu linnaasish sharras ti\'jaalahum bilkhairi laqudiya ilaihim ajaluhum fanazarul lazeena laa yarjoona liqaaa\'anna fee tughyaanihim ya\'mahoon',11,'10:11',21,84,173,3,0,209,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1376,10,'وَإِذَا مَسَّ ٱلْإِنسَـٰنَ ٱلضُّرُّ دَعَانَا لِجَنۢبِهِۦٓ أَوْ قَاعِدًا أَوْ قَآئِمًا فَلَمَّا كَشَفْنَا عَنْهُ ضُرَّهُۥ مَرَّ كَأَن لَّمْ يَدْعُنَآ إِلَىٰ ضُرٍّ مَّسَّهُۥ ۚ كَذَٰلِكَ زُيِّنَ لِلْمُسْرِفِينَ مَا كَانُوا۟ يَعْمَلُونَ','Wa izaa massal insaanad durru da\'aanaa lijambiheee aw qaa\'idan aw qaaa\'iman falammaa kashafnaa \'anhu durrahoo marra ka al lam yad\'unaaa ilaa durrim massah; kazaalika zuyyina lilmusrifeena maa kaanoo ya\'maloon',12,'10:12',21,84,173,3,0,209,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1377,10,'وَلَقَدْ أَهْلَكْنَا ٱلْقُرُونَ مِن قَبْلِكُمْ لَمَّا ظَلَمُوا۟ ۙ وَجَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَـٰتِ وَمَا كَانُوا۟ لِيُؤْمِنُوا۟ ۚ كَذَٰلِكَ نَجْزِى ٱلْقَوْمَ ٱلْمُجْرِمِينَ','Wa laqad ahlaknal quroona min qablikum lammaa zalamoo wa jaaa\'at hum Rusuluhum bil baiyinaati wa maa kaanoo liyu\'minoo; kazaalika najzil qawmal mujrimeen',13,'10:13',21,84,173,3,0,209,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1378,10,'ثُمَّ جَعَلْنَـٰكُمْ خَلَـٰٓئِفَ فِى ٱلْأَرْضِ مِنۢ بَعْدِهِمْ لِنَنظُرَ كَيْفَ تَعْمَلُونَ','Summa ja\'alnaakum khalaaa\'ifa fil ardi mim ba\'dihim linanzura kaifa ta\'maloon',14,'10:14',21,84,173,3,0,209,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1379,10,'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَاتُنَا بَيِّنَـٰتٍ ۙ قَالَ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا ٱئْتِ بِقُرْءَانٍ غَيْرِ هَـٰذَآ أَوْ بَدِّلْهُ ۚ قُلْ مَا يَكُونُ لِىٓ أَنْ أُبَدِّلَهُۥ مِن تِلْقَآئِ نَفْسِىٓ ۖ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ ۖ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍ','Wa izaa tutlaa \'alaihim aayaatunaa baiyinaatin qaalal lazeena laa yarjoona liqaaa\'ana\'ti bi Quraanin ghairi haazaaa aw baddilh; qul maa yakoonu leee an ubaddilahoo min tilqaaa\'i nafsee in attabi\'u illaa maa yoohaaa ilaiya inneee akhaafu in \'asaytu Rabbee \'azaaba Yawmin \'Azeeem',15,'10:15',21,84,173,3,0,210,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1380,10,'قُل لَّوْ شَآءَ ٱللَّهُ مَا تَلَوْتُهُۥ عَلَيْكُمْ وَلَآ أَدْرَىٰكُم بِهِۦ ۖ فَقَدْ لَبِثْتُ فِيكُمْ عُمُرًا مِّن قَبْلِهِۦٓ ۚ أَفَلَا تَعْقِلُونَ','Qul law shaaa\'al laahu maa talawtuhoo \'alaikum wa laaa adraakum bihee faqad labistu feekum \'umuram min qablih; afalaa ta\'qiloon',16,'10:16',21,84,173,3,0,210,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1381,10,'فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَـٰتِهِۦٓ ۚ إِنَّهُۥ لَا يُفْلِحُ ٱلْمُجْرِمُونَ','Faman azlamu mimmanif taraa \'alal laahi kaziban aw kazzaba bi Aayaatih; innahoo laa yuflihul mujrimoon',17,'10:17',21,84,173,3,0,210,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1382,10,'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ وَيَقُولُونَ هَـٰٓؤُلَآءِ شُفَعَـٰٓؤُنَا عِندَ ٱللَّهِ ۚ قُلْ أَتُنَبِّـُٔونَ ٱللَّهَ بِمَا لَا يَعْلَمُ فِى ٱلسَّمَـٰوَٰتِ وَلَا فِى ٱلْأَرْضِ ۚ سُبْحَـٰنَهُۥ وَتَعَـٰلَىٰ عَمَّا يُشْرِكُونَ','Wa ya\'budoona min doonil laahi maa laa yadurruhum wa laa yanfa\'uhum wa yaqooloona haaa\'ulaaa\'i shufa\'aaa \'unaa \'indal laah; qul atunabbi \'oonal laaha bima laa ya\'lamu fis samaawaati wa laa fil ard; subhaanahoo wa Ta\'aalaa \'ammaa yushrikoon',18,'10:18',21,84,173,3,0,210,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1383,10,'وَمَا كَانَ ٱلنَّاسُ إِلَّآ أُمَّةً وَٰحِدَةً فَٱخْتَلَفُوا۟ ۚ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَقُضِىَ بَيْنَهُمْ فِيمَا فِيهِ يَخْتَلِفُونَ','Wa maa kaanan naasu illaaa ummmatanw waahidatan fakh talafoo; wa law laa kalimatun sabaqat mir Rabbika laqudiya bainahum fee maa feehi yakhtalifoon',19,'10:19',21,84,173,3,0,210,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1384,10,'وَيَقُولُونَ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦ ۖ فَقُلْ إِنَّمَا ٱلْغَيْبُ لِلَّهِ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ','W yaqooloona law laaa unzila \'alaihi aayatum mir Rabbihee faqul innamal ghaibu lillaahi fantaziroo innee ma\'akum minal muntazireen',20,'10:20',21,84,173,3,0,210,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1385,10,'وَإِذَآ أَذَقْنَا ٱلنَّاسَ رَحْمَةً مِّنۢ بَعْدِ ضَرَّآءَ مَسَّتْهُمْ إِذَا لَهُم مَّكْرٌ فِىٓ ءَايَاتِنَا ۚ قُلِ ٱللَّهُ أَسْرَعُ مَكْرًا ۚ إِنَّ رُسُلَنَا يَكْتُبُونَ مَا تَمْكُرُونَ','Wa izaaa azaqnan naasa rahmatam mim ba\'di darraaa\'a massat hum izaa lahum makrun feee aayaatinaa; qulil laahu asra\'u makraa; inna rusulanaa yaktuboona maa tamkuroon',21,'10:21',21,84,174,3,0,211,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1386,10,'هُوَ ٱلَّذِى يُسَيِّرُكُمْ فِى ٱلْبَرِّ وَٱلْبَحْرِ ۖ حَتَّىٰٓ إِذَا كُنتُمْ فِى ٱلْفُلْكِ وَجَرَيْنَ بِهِم بِرِيحٍ طَيِّبَةٍ وَفَرِحُوا۟ بِهَا جَآءَتْهَا رِيحٌ عَاصِفٌ وَجَآءَهُمُ ٱلْمَوْجُ مِن كُلِّ مَكَانٍ وَظَنُّوٓا۟ أَنَّهُمْ أُحِيطَ بِهِمْ ۙ دَعَوُا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ لَئِنْ أَنجَيْتَنَا مِنْ هَـٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّـٰكِرِينَ','Huwal lazee yusaiyirukum fil barri walbahri hattaaa izaa kuntum fil fulki wa jaraina bihim bireeh in taiyibatinw wa farihoo bihaa jaaa\'at haa reehun \'aasifunw wa jaaa\'ahumul mawju min kulli makaaninw wa zannooo annahum uheeta bihim da\'awul laaha mukhliseena lahud deena la\'in anjaitanaa min haazihee lanakoonannna minash shaakireen',22,'10:22',21,84,174,3,0,211,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1387,10,'فَلَمَّآ أَنجَىٰهُمْ إِذَا هُمْ يَبْغُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ ۗ يَـٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَا بَغْيُكُمْ عَلَىٰٓ أَنفُسِكُم ۖ مَّتَـٰعَ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ ثُمَّ إِلَيْنَا مَرْجِعُكُمْ فَنُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ','Falammaaa anjaahum izaa hum yabghoona fil ardi bighairil haqq; yaaa aiyuhannaasu innamaa bagh yukum \'alaaa anfusikum mataa\'al hayaatid dunyaa summa ilainaa marji\'ukum fanunabbi \'ukum bimaa kuntum ta\'maloon',23,'10:23',21,84,174,3,0,211,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1388,10,'إِنَّمَا مَثَلُ ٱلْحَيَوٰةِ ٱلدُّنْيَا كَمَآءٍ أَنزَلْنَـٰهُ مِنَ ٱلسَّمَآءِ فَٱخْتَلَطَ بِهِۦ نَبَاتُ ٱلْأَرْضِ مِمَّا يَأْكُلُ ٱلنَّاسُ وَٱلْأَنْعَـٰمُ حَتَّىٰٓ إِذَآ أَخَذَتِ ٱلْأَرْضُ زُخْرُفَهَا وَٱزَّيَّنَتْ وَظَنَّ أَهْلُهَآ أَنَّهُمْ قَـٰدِرُونَ عَلَيْهَآ أَتَىٰهَآ أَمْرُنَا لَيْلًا أَوْ نَهَارًا فَجَعَلْنَـٰهَا حَصِيدًا كَأَن لَّمْ تَغْنَ بِٱلْأَمْسِ ۚ كَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَـٰتِ لِقَوْمٍ يَتَفَكَّرُونَ','Innamaa masalul hayaatid dunyaa kammaaa\'in anzalnaahu minas sammaaa\'i fakhtalata bihee nabaatul ardi mimmaa yaakulun naasu wal an\'aam; hattaaa izaaa akhazatil ardu zukhrufahaa wazziyanat wa zanna ahluhaaa annahum qaadiroona \'alaihaaa ataahaaa amrunaa lailan aw nahaaran faja\'alnaahaa haseedan ka allam taghna bil-ams; kazaalika nufassilul aayaati liqawminy yatafakkaroon',24,'10:24',21,84,174,3,0,211,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1389,10,'وَٱللَّهُ يَدْعُوٓا۟ إِلَىٰ دَارِ ٱلسَّلَـٰمِ وَيَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ','Wallaahu yad\'ooo ilaa daaris salaami wa yahdee mai yashaaa\'u ilaa Siraatim Mustaqeem',25,'10:25',21,84,174,3,0,211,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1390,10,'۞ لِّلَّذِينَ أَحْسَنُوا۟ ٱلْحُسْنَىٰ وَزِيَادَةٌ ۖ وَلَا يَرْهَقُ وُجُوهَهُمْ قَتَرٌ وَلَا ذِلَّةٌ ۚ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْجَنَّةِ ۖ هُمْ فِيهَا خَـٰلِدُونَ','Lillazeena ahsanul husnaa wa ziyaadahtunw wa laa yarhaqu wujoohahum qatarunw wa laa zillah; ulaaa\'ika ashaabul jannnati hum feehaa khaalidoon',26,'10:26',22,85,174,3,0,212,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1391,10,'وَٱلَّذِينَ كَسَبُوا۟ ٱلسَّيِّـَٔاتِ جَزَآءُ سَيِّئَةٍۭ بِمِثْلِهَا وَتَرْهَقُهُمْ ذِلَّةٌ ۖ مَّا لَهُم مِّنَ ٱللَّهِ مِنْ عَاصِمٍ ۖ كَأَنَّمَآ أُغْشِيَتْ وُجُوهُهُمْ قِطَعًا مِّنَ ٱلَّيْلِ مُظْلِمًا ۚ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ','Wallazeena kasabus saiyi aati jazaaa\'u saiyi\'atim bimislihaa wa tarhaquhum zillah; maa lahum minal laahi min \'aasimin ka annamaaa ughshiyat wujoohuhum qita \'am minal laili muzlimaa; ulaaa\'ika Ashaabun Naari hum feeha khaalidoon',27,'10:27',22,85,174,3,0,212,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1392,10,'وَيَوْمَ نَحْشُرُهُمْ جَمِيعًا ثُمَّ نَقُولُ لِلَّذِينَ أَشْرَكُوا۟ مَكَانَكُمْ أَنتُمْ وَشُرَكَآؤُكُمْ ۚ فَزَيَّلْنَا بَيْنَهُمْ ۖ وَقَالَ شُرَكَآؤُهُم مَّا كُنتُمْ إِيَّانَا تَعْبُدُونَ','Wa yawma nahshuruhum jamee\'an summa naqoolu lillazeena ashrakoo makaanakum antum wa shurakaaa\'ukum; fazaiyalnaa bainahum wa qaala shurakaaa\'uhum maa kuntum iyyaanaa ta\'budoon',28,'10:28',22,85,174,3,0,212,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1393,10,'فَكَفَىٰ بِٱللَّهِ شَهِيدًۢا بَيْنَنَا وَبَيْنَكُمْ إِن كُنَّا عَنْ عِبَادَتِكُمْ لَغَـٰفِلِينَ','Fakafaa billaahi shaheedam bainanaa wa bainakum in kunnaa \'an \'ibaadatikum laghaafileen',29,'10:29',22,85,174,3,0,212,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1394,10,'هُنَالِكَ تَبْلُوا۟ كُلُّ نَفْسٍ مَّآ أَسْلَفَتْ ۚ وَرُدُّوٓا۟ إِلَى ٱللَّهِ مَوْلَىٰهُمُ ٱلْحَقِّ ۖ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ','Hunaalika tabloo kullu nafsim maaa aslafat; wa ruddoo ilal laahi mawlaahu mul haqqi wa dalla \'anhum maa kaanoo yaftaroon',30,'10:30',22,85,174,3,0,212,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1395,10,'قُلْ مَن يَرْزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ أَمَّن يَمْلِكُ ٱلسَّمْعَ وَٱلْأَبْصَـٰرَ وَمَن يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَيُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ وَمَن يُدَبِّرُ ٱلْأَمْرَ ۚ فَسَيَقُولُونَ ٱللَّهُ ۚ فَقُلْ أَفَلَا تَتَّقُونَ','Qul mai yarzuqukum minas samaaa\'i wal ardi ammany yamlikus sam\'a wal absaara wa mai yukhrijul haiya minal maiyiti wa yikhrijul maiyita minal haiyi wa mai yudabbirul amr; fasa yaqooloonal laah; faqul afalaa tattaqoon',31,'10:31',22,85,175,3,0,212,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1396,10,'فَذَٰلِكُمُ ٱللَّهُ رَبُّكُمُ ٱلْحَقُّ ۖ فَمَاذَا بَعْدَ ٱلْحَقِّ إِلَّا ٱلضَّلَـٰلُ ۖ فَأَنَّىٰ تُصْرَفُونَ','Fazaalikumul laahu Rabbukumul haqq; famaazaa ba\'dal haqqi illad dalaalu fa annnaa tusrafoon',32,'10:32',22,85,175,3,0,212,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1397,10,'كَذَٰلِكَ حَقَّتْ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ فَسَقُوٓا۟ أَنَّهُمْ لَا يُؤْمِنُونَ','Kazaalika haqqat Kalimatu Rabbika \'alal lazeena fasaqooo annahum laa yu\'minoon',33,'10:33',22,85,175,3,0,212,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1398,10,'قُلْ هَلْ مِن شُرَكَآئِكُم مَّن يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ ۚ قُلِ ٱللَّهُ يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ ۖ فَأَنَّىٰ تُؤْفَكُونَ','Qul hal min shurakaaa \'ikum mai yabda\'ul khalqa suma yu\'eeduh; qulil laahu yabda\'ul khalqa summa yu\'eeduhoo fa annaa tu\'fakoon',34,'10:34',22,85,175,3,0,213,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1399,10,'قُلْ هَلْ مِن شُرَكَآئِكُم مَّن يَهْدِىٓ إِلَى ٱلْحَقِّ ۚ قُلِ ٱللَّهُ يَهْدِى لِلْحَقِّ ۗ أَفَمَن يَهْدِىٓ إِلَى ٱلْحَقِّ أَحَقُّ أَن يُتَّبَعَ أَمَّن لَّا يَهِدِّىٓ إِلَّآ أَن يُهْدَىٰ ۖ فَمَا لَكُمْ كَيْفَ تَحْكُمُونَ','Qul hal min shurakaaa \'ikum mai yahdeee ilal haqq; qulil laahu yahdee lilhaqq; afamai yahdeee ilal haqqi ahaqqu ai yuttaba\'a ammal laa yahiddeee illaaa ai yuhdaa famaa lakum kaifa tahkumoon',35,'10:35',22,85,175,3,0,213,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1400,10,'وَمَا يَتَّبِعُ أَكْثَرُهُمْ إِلَّا ظَنًّا ۚ إِنَّ ٱلظَّنَّ لَا يُغْنِى مِنَ ٱلْحَقِّ شَيْـًٔا ۚ إِنَّ ٱللَّهَ عَلِيمٌۢ بِمَا يَفْعَلُونَ','Wa maa yattabi\'u aksaruhum illaa zannaa; innaz zanna laa yughnee minal haqqi shai\'aa; innal laaha \'Aleemum bimaa yaf\'aloon',36,'10:36',22,85,175,3,0,213,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1401,10,'وَمَا كَانَ هَـٰذَا ٱلْقُرْءَانُ أَن يُفْتَرَىٰ مِن دُونِ ٱللَّهِ وَلَـٰكِن تَصْدِيقَ ٱلَّذِى بَيْنَ يَدَيْهِ وَتَفْصِيلَ ٱلْكِتَـٰبِ لَا رَيْبَ فِيهِ مِن رَّبِّ ٱلْعَـٰلَمِينَ','Wa maa kaana haazal Quraanu ai yuftaraa min doonil laahi wa laakin tasdeeqal lazee baina yadaihi wa tafseelal Kitaabi laa raiba fee mir Rabbil \'aalameen',37,'10:37',22,85,175,3,0,213,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1402,10,'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ ۖ قُلْ فَأْتُوا۟ بِسُورَةٍ مِّثْلِهِۦ وَٱدْعُوا۟ مَنِ ٱسْتَطَعْتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَـٰدِقِينَ','Am yaqooloonaf taraahu qul faatoo bisooratim mislihee wad\'oo manis tata\'tum min doonil laahi in kuntum saadiqeen',38,'10:38',22,85,175,3,0,213,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1403,10,'بَلْ كَذَّبُوا۟ بِمَا لَمْ يُحِيطُوا۟ بِعِلْمِهِۦ وَلَمَّا يَأْتِهِمْ تَأْوِيلُهُۥ ۚ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ ۖ فَٱنظُرْ كَيْفَ كَانَ عَـٰقِبَةُ ٱلظَّـٰلِمِينَ','Bal kazzaboo bimaa lam yuheetoo bi\'ilmihee wa lammaa yaatihim taaweeluh; kazaalika kazzabal lazeena min qablihim fanzur kaifa kaana \'aaqibatuz zaalimeen',39,'10:39',22,85,175,3,0,213,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1404,10,'وَمِنْهُم مَّن يُؤْمِنُ بِهِۦ وَمِنْهُم مَّن لَّا يُؤْمِنُ بِهِۦ ۚ وَرَبُّكَ أَعْلَمُ بِٱلْمُفْسِدِينَ','Wa minhum mai yu \'minu bihee wa minhum mal laa yu\'minu bih; wa Rabbuka a\'lamu bilmufsideen',40,'10:40',22,85,175,3,0,213,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1405,10,'وَإِن كَذَّبُوكَ فَقُل لِّى عَمَلِى وَلَكُمْ عَمَلُكُمْ ۖ أَنتُم بَرِيٓـُٔونَ مِمَّآ أَعْمَلُ وَأَنَا۠ بَرِىٓءٌ مِّمَّا تَعْمَلُونَ','Wa in kazzabooka faqul lee \'amalee wa lakum \'amalukum antum bareee\'oona mimmaaa a\'malu wa ana bareee\'um mimmaa ta\'maloon',41,'10:41',22,85,176,3,0,213,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1406,10,'وَمِنْهُم مَّن يَسْتَمِعُونَ إِلَيْكَ ۚ أَفَأَنتَ تُسْمِعُ ٱلصُّمَّ وَلَوْ كَانُوا۟ لَا يَعْقِلُونَ','Wa minhum mai yastami\'oona iliak; afa anta tusmi\'us summa wa law kaanoo la ya\'qiloon',42,'10:42',22,85,176,3,0,213,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1407,10,'وَمِنْهُم مَّن يَنظُرُ إِلَيْكَ ۚ أَفَأَنتَ تَهْدِى ٱلْعُمْىَ وَلَوْ كَانُوا۟ لَا يُبْصِرُونَ','Wa minhum mai yanzuru ilaik; afa anta tahdil \'umya wa law kaanoo laa yubsiroon',43,'10:43',22,85,176,3,0,214,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1408,10,'إِنَّ ٱللَّهَ لَا يَظْلِمُ ٱلنَّاسَ شَيْـًٔا وَلَـٰكِنَّ ٱلنَّاسَ أَنفُسَهُمْ يَظْلِمُونَ','Innal laaha laa yazlimun naasa shai\'anw wa laakin nannaasa anfusahum yazlimoon',44,'10:44',22,85,176,3,0,214,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1409,10,'وَيَوْمَ يَحْشُرُهُمْ كَأَن لَّمْ يَلْبَثُوٓا۟ إِلَّا سَاعَةً مِّنَ ٱلنَّهَارِ يَتَعَارَفُونَ بَيْنَهُمْ ۚ قَدْ خَسِرَ ٱلَّذِينَ كَذَّبُوا۟ بِلِقَآءِ ٱللَّهِ وَمَا كَانُوا۟ مُهْتَدِينَ','Wa Yawma yahshuruhum ka al lam yalbasooo illaa saa\'atam minan nahaari yata\'aarafoona bainahum; qad khasiral lazeena kazzaboo biliqaaa\'il laahi wa maa kaanoo muhtadeen',45,'10:45',22,85,176,3,0,214,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1410,10,'وَإِمَّا نُرِيَنَّكَ بَعْضَ ٱلَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا مَرْجِعُهُمْ ثُمَّ ٱللَّهُ شَهِيدٌ عَلَىٰ مَا يَفْعَلُونَ','Wa imma nuriyannaka ba\'dal lazee na\'iduhum aw natawaffayannaka fa ilainaa marji\'uhum summal laahu shaheedun \'alaa maa yaf\'aloon',46,'10:46',22,85,176,3,0,214,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1411,10,'وَلِكُلِّ أُمَّةٍ رَّسُولٌ ۖ فَإِذَا جَآءَ رَسُولُهُمْ قُضِىَ بَيْنَهُم بِٱلْقِسْطِ وَهُمْ لَا يُظْلَمُونَ','Wa likulli ummatir Rasoolun fa izaa jaaa\'a Rasooluhum qudiya bainahum bilqisti wa hum laa yuzlamoon',47,'10:47',22,85,176,3,0,214,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1412,10,'وَيَقُولُونَ مَتَىٰ هَـٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَـٰدِقِينَ','Wa yaqooloona mataa haazal wa\'du in kuntum saadiqeen',48,'10:48',22,85,176,3,0,214,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1413,10,'قُل لَّآ أَمْلِكُ لِنَفْسِى ضَرًّا وَلَا نَفْعًا إِلَّا مَا شَآءَ ٱللَّهُ ۗ لِكُلِّ أُمَّةٍ أَجَلٌ ۚ إِذَا جَآءَ أَجَلُهُمْ فَلَا يَسْتَـْٔخِرُونَ سَاعَةً ۖ وَلَا يَسْتَقْدِمُونَ','Qul laaa amliku linafsee darranw wa laa naf\'an illaa maa shaaa\'al laah; likulli ummatin ajalun izaa jaaa\'a ajaluhum falaaa yastaakhiroona saa\'a tanw wa laa yastaqdimoon',49,'10:49',22,85,176,3,0,214,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1414,10,'قُلْ أَرَءَيْتُمْ إِنْ أَتَىٰكُمْ عَذَابُهُۥ بَيَـٰتًا أَوْ نَهَارًا مَّاذَا يَسْتَعْجِلُ مِنْهُ ٱلْمُجْرِمُونَ','Qul ara\'aitum in ataakum \'azaabuhoo bayaatan aw nahaaram maazaa yasta\'jilu minhul mujrimoon',50,'10:50',22,85,176,3,0,214,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1415,10,'أَثُمَّ إِذَا مَا وَقَعَ ءَامَنتُم بِهِۦٓ ۚ ءَآلْـَٔـٰنَ وَقَدْ كُنتُم بِهِۦ تَسْتَعْجِلُونَ','Asumma izaa maa waqa\'a aamantum bih; aaal\'aana wa qad kuntum bihee tasta\'jiloon',51,'10:51',22,85,176,3,0,214,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1416,10,'ثُمَّ قِيلَ لِلَّذِينَ ظَلَمُوا۟ ذُوقُوا۟ عَذَابَ ٱلْخُلْدِ هَلْ تُجْزَوْنَ إِلَّا بِمَا كُنتُمْ تَكْسِبُونَ','Summa qeela lillazeena zalamoo zooqoo \'azaabal khuld hal tujzawna illaa bimaa kuntum taksiboon',52,'10:52',22,85,176,3,0,214,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1417,10,'۞ وَيَسْتَنۢبِـُٔونَكَ أَحَقٌّ هُوَ ۖ قُلْ إِى وَرَبِّىٓ إِنَّهُۥ لَحَقٌّ ۖ وَمَآ أَنتُم بِمُعْجِزِينَ','Wa yastambi\'oonaka ahaqqun huwa qul ee wa Rabbeee innahoo lahaqq; wa maaa antum bimu\'jizeen',53,'10:53',22,86,176,3,0,214,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1418,10,'وَلَوْ أَنَّ لِكُلِّ نَفْسٍ ظَلَمَتْ مَا فِى ٱلْأَرْضِ لَٱفْتَدَتْ بِهِۦ ۗ وَأَسَرُّوا۟ ٱلنَّدَامَةَ لَمَّا رَأَوُا۟ ٱلْعَذَابَ ۖ وَقُضِىَ بَيْنَهُم بِٱلْقِسْطِ ۚ وَهُمْ لَا يُظْلَمُونَ','Wa law anna likulli nafsin zalamat maa fil ardi laftadat bih; wa asarrun nadaamata lammaa ra awul \'azaab, wa qudiya bainahum bilqist; wa hum laa yuzlamoon',54,'10:54',22,86,177,3,0,215,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1419,10,'أَلَآ إِنَّ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۗ أَلَآ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ وَلَـٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ','Alaaa inna lillaahi maa fis samaawaati wal ard; alaaa inna wa\'dal laahi haqqunw wa laakinna aksarahum laa ya\'lamoon',55,'10:55',22,86,177,3,0,215,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1420,10,'هُوَ يُحْىِۦ وَيُمِيتُ وَإِلَيْهِ تُرْجَعُونَ','Huwa yuhyee wa yumeetu wailaihi turja\'oon',56,'10:56',22,86,177,3,0,215,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1421,10,'يَـٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَتْكُم مَّوْعِظَةٌ مِّن رَّبِّكُمْ وَشِفَآءٌ لِّمَا فِى ٱلصُّدُورِ وَهُدًى وَرَحْمَةٌ لِّلْمُؤْمِنِينَ','Yaaa aiyuhan naasu qad jaaa\'atkum maw \'izatum mir Rabbikum wa shifaaa\'ul limaa fis sudoori wa hudanw wa rahmatul lilmu\'mineen',57,'10:57',22,86,177,3,0,215,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1422,10,'قُلْ بِفَضْلِ ٱللَّهِ وَبِرَحْمَتِهِۦ فَبِذَٰلِكَ فَلْيَفْرَحُوا۟ هُوَ خَيْرٌ مِّمَّا يَجْمَعُونَ','Qul bifadlil laahi wa birahmatihii fabizaalika falyaf rahoo huwa khairum mimmaa yajma\'oon',58,'10:58',22,86,177,3,0,215,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1423,10,'قُلْ أَرَءَيْتُم مَّآ أَنزَلَ ٱللَّهُ لَكُم مِّن رِّزْقٍ فَجَعَلْتُم مِّنْهُ حَرَامًا وَحَلَـٰلًا قُلْ ءَآللَّهُ أَذِنَ لَكُمْ ۖ أَمْ عَلَى ٱللَّهِ تَفْتَرُونَ','Qul ara\'aitum maaa anzalal laahu lakum mir rizqin faja\'altum minhu haraamanw wa halaalan qul aaallaahu azina lakum am \'alal laahi taftaroon',59,'10:59',22,86,177,3,0,215,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1424,10,'وَمَا ظَنُّ ٱلَّذِينَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ يَوْمَ ٱلْقِيَـٰمَةِ ۗ إِنَّ ٱللَّهَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَـٰكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ','Wa maa zannul lazeena yaftaroona \'alal laahil kaziba Yawmal Qiyaamah; innal laaha lazoo fadlin \'alan naasi wa laakinna aksarahum laa yashkuroon',60,'10:60',22,86,177,3,0,215,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1425,10,'وَمَا تَكُونُ فِى شَأْنٍ وَمَا تَتْلُوا۟ مِنْهُ مِن قُرْءَانٍ وَلَا تَعْمَلُونَ مِنْ عَمَلٍ إِلَّا كُنَّا عَلَيْكُمْ شُهُودًا إِذْ تُفِيضُونَ فِيهِ ۚ وَمَا يَعْزُبُ عَن رَّبِّكَ مِن مِّثْقَالِ ذَرَّةٍ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ وَلَآ أَصْغَرَ مِن ذَٰلِكَ وَلَآ أَكْبَرَ إِلَّا فِى كِتَـٰبٍ مُّبِينٍ','Wa maa takoonu fee shaaninw wa maa tatloo minhu min quraaninw wa laa ta\'maloona min \'amalin illaa kunnaa \'alaikum shuhoodan iz tufeedoona feeh; wa maa ya\'zubu \'ar Rabbika mim mis qaali zarratin fil ardi wa laa fis samaaa\'i wa laaa asghara min zaalika wa laaa akbara illaa fee Kitaabim Mubeen',61,'10:61',22,86,178,3,0,215,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1426,10,'أَلَآ إِنَّ أَوْلِيَآءَ ٱللَّهِ لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ','Alaa innaa awliyaaa\'al laahi laa khawfun \'alaihim wa laa hum yahzanoon',62,'10:62',22,86,178,3,0,216,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1427,10,'ٱلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ','Allazeena aamanoo wa kaanoo yattaqoon',63,'10:63',22,86,178,3,0,216,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1428,10,'لَهُمُ ٱلْبُشْرَىٰ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْـَٔاخِرَةِ ۚ لَا تَبْدِيلَ لِكَلِمَـٰتِ ٱللَّهِ ۚ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ','Lahumul bushraa filha yaatid dunyaa wa fil Aakhirah; laa tabdeela likalimaatil laah; zaalika huwal fawzul \'azeem',64,'10:64',22,86,178,3,0,216,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1429,10,'وَلَا يَحْزُنكَ قَوْلُهُمْ ۘ إِنَّ ٱلْعِزَّةَ لِلَّهِ جَمِيعًا ۚ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ','Wa laa yahzunka qawluhum; innal \'izzata lillaahi jamee\'aa; Huwas Samee\'ul \'Aleem',65,'10:65',22,86,178,3,0,216,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1430,10,'أَلَآ إِنَّ لِلَّهِ مَن فِى ٱلسَّمَـٰوَٰتِ وَمَن فِى ٱلْأَرْضِ ۗ وَمَا يَتَّبِعُ ٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ شُرَكَآءَ ۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ','Alaaa inna lillaahi man fis samaawaati wa man fil ard; wa maa yattabi\'ul lazeena yad\'oona min doonil laahi shurakaaa\'; iny yattabi\'oona illaz zannna wa in hum illaa yakhrusoon',66,'10:66',22,86,178,3,0,216,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1431,10,'هُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلَّيْلَ لِتَسْكُنُوا۟ فِيهِ وَٱلنَّهَارَ مُبْصِرًا ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّقَوْمٍ يَسْمَعُونَ','Huwal lazee ja\'ala lakumul laila litaskunoo feehi wannahaara mubsiraa; inna fee zaalika la Aayaatil liqawmai yasma\'oon',67,'10:67',22,86,178,3,0,216,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1432,10,'قَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدًا ۗ سُبْحَـٰنَهُۥ ۖ هُوَ ٱلْغَنِىُّ ۖ لَهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ إِنْ عِندَكُم مِّن سُلْطَـٰنٍۭ بِهَـٰذَآ ۚ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ','Qaalut takhazal laahu waladan Subhaanahoo Huwal Ghaniyyu lahoo maa fis samaawaati wa maa fil ard; in \'indakum min sultaanim bihaazaaa; ataqooloona \'alal laahi maa laa ta\'lamoon',68,'10:68',22,86,178,3,0,216,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1433,10,'قُلْ إِنَّ ٱلَّذِينَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ لَا يُفْلِحُونَ','Qul innal lazeena yaftaroona \'alal laahil kaziba laa yuflihoon',69,'10:69',22,86,178,3,0,216,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1434,10,'مَتَـٰعٌ فِى ٱلدُّنْيَا ثُمَّ إِلَيْنَا مَرْجِعُهُمْ ثُمَّ نُذِيقُهُمُ ٱلْعَذَابَ ٱلشَّدِيدَ بِمَا كَانُوا۟ يَكْفُرُونَ','Mataa\'un fiddunyaa summa ilainaa marji\'uhum summa nuzeequhumul \'azaabash shadeeda bimaa kaanoo yakkfuroon',70,'10:70',22,86,178,3,0,216,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1435,10,'۞ وَٱتْلُ عَلَيْهِمْ نَبَأَ نُوحٍ إِذْ قَالَ لِقَوْمِهِۦ يَـٰقَوْمِ إِن كَانَ كَبُرَ عَلَيْكُم مَّقَامِى وَتَذْكِيرِى بِـَٔايَـٰتِ ٱللَّهِ فَعَلَى ٱللَّهِ تَوَكَّلْتُ فَأَجْمِعُوٓا۟ أَمْرَكُمْ وَشُرَكَآءَكُمْ ثُمَّ لَا يَكُنْ أَمْرُكُمْ عَلَيْكُمْ غُمَّةً ثُمَّ ٱقْضُوٓا۟ إِلَىَّ وَلَا تُنظِرُونِ','Watlu \'alaihim naba-a-Noohin iz qaala liqawmihee yaa qawmi in kaana kabura \'alaikum maqaamee wa tazkeeree bi Aayaatil laahi fa\'alal laahi tawakkaltu fa ajmi\'ooo amrakum wa shurakaaa\'akum summa laa yakun amrukum \'alaikum ghummatan summmaq dooo ilaiya wa laa tunziroon',71,'10:71',22,87,179,3,0,217,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1436,10,'فَإِن تَوَلَّيْتُمْ فَمَا سَأَلْتُكُم مِّنْ أَجْرٍ ۖ إِنْ أَجْرِىَ إِلَّا عَلَى ٱللَّهِ ۖ وَأُمِرْتُ أَنْ أَكُونَ مِنَ ٱلْمُسْلِمِينَ','Fa in tawallaitum famaa sa altukum min ajrin in ajriya illaa \'alal laahi wa umirtu an akoona minal muslimeen',72,'10:72',22,87,179,3,0,217,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1437,10,'فَكَذَّبُوهُ فَنَجَّيْنَـٰهُ وَمَن مَّعَهُۥ فِى ٱلْفُلْكِ وَجَعَلْنَـٰهُمْ خَلَـٰٓئِفَ وَأَغْرَقْنَا ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا ۖ فَٱنظُرْ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُنذَرِينَ','Fakazzaboohu fanajjainaahu wa mamm\'ahoo fil fulki wa ja\'alnaahum khalaaa\'ifa wa aghraqnal lazeena kazzaboo bi aayaatinaa fanzur kaifa kaana \'aaqibatul munzareen',73,'10:73',22,87,179,3,0,217,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1438,10,'ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِۦ رُسُلًا إِلَىٰ قَوْمِهِمْ فَجَآءُوهُم بِٱلْبَيِّنَـٰتِ فَمَا كَانُوا۟ لِيُؤْمِنُوا۟ بِمَا كَذَّبُوا۟ بِهِۦ مِن قَبْلُ ۚ كَذَٰلِكَ نَطْبَعُ عَلَىٰ قُلُوبِ ٱلْمُعْتَدِينَ','Summma ba\'asnaa mim ba\'dihee Rusulan ilaa qawmihim fajaaa\'oohum bilbaiyinaati famaa kaanoo liyu\'minoo bimaa kazzaboo bihee min qabl; kazaalika natba\'u \'alaa quloobil mu\'tadeen',74,'10:74',22,87,179,3,0,217,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1439,10,'ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِم مُّوسَىٰ وَهَـٰرُونَ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ بِـَٔايَـٰتِنَا فَٱسْتَكْبَرُوا۟ وَكَانُوا۟ قَوْمًا مُّجْرِمِينَ','Summa ba\'asnaa mim ba\'dihim Moosaa Wa Haaroona ilaa Fir\'awna wa mala\'ihee bi aayaatinaa fastakbaroo wa kaanoo qawmam mujrimeen',75,'10:75',22,87,179,3,0,217,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1440,10,'فَلَمَّا جَآءَهُمُ ٱلْحَقُّ مِنْ عِندِنَا قَالُوٓا۟ إِنَّ هَـٰذَا لَسِحْرٌ مُّبِينٌ','Falammaa jaaa\'ahumul haqqu min \'indinaa qaalooo inna haazaa lasihrum mubeen',76,'10:76',22,87,179,3,0,217,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1441,10,'قَالَ مُوسَىٰٓ أَتَقُولُونَ لِلْحَقِّ لَمَّا جَآءَكُمْ ۖ أَسِحْرٌ هَـٰذَا وَلَا يُفْلِحُ ٱلسَّـٰحِرُونَ','Qaalaa Moosaaa ataqooloona lilhaqqi lammmaa jaaa\'a kum asihrun haazaa wa laa yuflihus saabiroon',77,'10:77',22,87,179,3,0,217,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1442,10,'قَالُوٓا۟ أَجِئْتَنَا لِتَلْفِتَنَا عَمَّا وَجَدْنَا عَلَيْهِ ءَابَآءَنَا وَتَكُونَ لَكُمَا ٱلْكِبْرِيَآءُ فِى ٱلْأَرْضِ وَمَا نَحْنُ لَكُمَا بِمُؤْمِنِينَ','Qaaloo aji\'tanaa litalfitanaa \'ammaa wajadnaa \'alaihi aabaaa\'anaa wa takoona lakumal kibriyaaa\'u fil ardi wa maa nahnu lakumaa bimu\' mineen',78,'10:78',22,87,179,3,0,217,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1443,10,'وَقَالَ فِرْعَوْنُ ٱئْتُونِى بِكُلِّ سَـٰحِرٍ عَلِيمٍ','Wa qaala Fir\'awnu\' toonee bikulli saahirin \'aleem',79,'10:79',22,87,179,3,0,218,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1444,10,'فَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالَ لَهُم مُّوسَىٰٓ أَلْقُوا۟ مَآ أَنتُم مُّلْقُونَ','Falammaa jaaa\'assa haratu qaala lahum Moosaaa alqoo maaa antum mulqoon',80,'10:80',22,87,179,3,0,218,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1445,10,'فَلَمَّآ أَلْقَوْا۟ قَالَ مُوسَىٰ مَا جِئْتُم بِهِ ٱلسِّحْرُ ۖ إِنَّ ٱللَّهَ سَيُبْطِلُهُۥٓ ۖ إِنَّ ٱللَّهَ لَا يُصْلِحُ عَمَلَ ٱلْمُفْسِدِينَ','Falammaaa alqaw qaala Moosaa maa ji\'tum bihis sihru innal laaha sa yubtiluhoo innal laaha laa yuslihu \'amalal mufsideen',81,'10:81',22,87,179,3,0,218,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1446,10,'وَيُحِقُّ ٱللَّهُ ٱلْحَقَّ بِكَلِمَـٰتِهِۦ وَلَوْ كَرِهَ ٱلْمُجْرِمُونَ','Wa yuhiqqul laahul haqqa bi Kalimaatihee wa law karihal mujrimoon',82,'10:82',22,87,179,3,0,218,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1447,10,'فَمَآ ءَامَنَ لِمُوسَىٰٓ إِلَّا ذُرِّيَّةٌ مِّن قَوْمِهِۦ عَلَىٰ خَوْفٍ مِّن فِرْعَوْنَ وَمَلَإِي۟هِمْ أَن يَفْتِنَهُمْ ۚ وَإِنَّ فِرْعَوْنَ لَعَالٍ فِى ٱلْأَرْضِ وَإِنَّهُۥ لَمِنَ ٱلْمُسْرِفِينَ','Famaaa aamana li-Moosaaa illaa zurriyyatum min qawmihee \'alaa khawfim min Fir\'awna wa mala\'ihim ai yaftinahum; wa inna Fir\'awna la\'aalin fil ardi wa innahoo laminal musrifeen',83,'10:83',22,87,180,3,0,218,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1448,10,'وَقَالَ مُوسَىٰ يَـٰقَوْمِ إِن كُنتُمْ ءَامَنتُم بِٱللَّهِ فَعَلَيْهِ تَوَكَّلُوٓا۟ إِن كُنتُم مُّسْلِمِينَ','Wa qaala Moosaa yaa qawmi in kuntum aamantum billaahi fa\'alaihi tawakkalooo in kuntum muslimeen',84,'10:84',22,87,180,3,0,218,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1449,10,'فَقَالُوا۟ عَلَى ٱللَّهِ تَوَكَّلْنَا رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلْقَوْمِ ٱلظَّـٰلِمِينَ','Faqaaloo \'alal laahi tawakkalnaa Rabbanaa laa taj\'alnaa fitnatal lilqawmiz zaalimeen',85,'10:85',22,87,180,3,0,218,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1450,10,'وَنَجِّنَا بِرَحْمَتِكَ مِنَ ٱلْقَوْمِ ٱلْكَـٰفِرِينَ','Wa najjinaa birahmatika minal qawmil kaafireen',86,'10:86',22,87,180,3,0,218,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1451,10,'وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰ وَأَخِيهِ أَن تَبَوَّءَا لِقَوْمِكُمَا بِمِصْرَ بُيُوتًا وَٱجْعَلُوا۟ بُيُوتَكُمْ قِبْلَةً وَأَقِيمُوا۟ ٱلصَّلَوٰةَ ۗ وَبَشِّرِ ٱلْمُؤْمِنِينَ','Wa awhainaaa ilaa Moosaa wa akheehi an tabaw wa aa liqawmikuma bi Misra bu yootanw waj\'aloo bu yootakum qiblatanw wa aqeemus Salaah; wa bashshiril mu\'mineen',87,'10:87',22,87,180,3,0,218,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1452,10,'وَقَالَ مُوسَىٰ رَبَّنَآ إِنَّكَ ءَاتَيْتَ فِرْعَوْنَ وَمَلَأَهُۥ زِينَةً وَأَمْوَٰلًا فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا رَبَّنَا لِيُضِلُّوا۟ عَن سَبِيلِكَ ۖ رَبَّنَا ٱطْمِسْ عَلَىٰٓ أَمْوَٰلِهِمْ وَٱشْدُدْ عَلَىٰ قُلُوبِهِمْ فَلَا يُؤْمِنُوا۟ حَتَّىٰ يَرَوُا۟ ٱلْعَذَابَ ٱلْأَلِيمَ','Wa qaala Mosaa Rabbanaaa innaka aataita Fir\'awna wa mala ahoo zeenatanw wa amwaalan fil hayaatid dunyaa Rabbanaa liyudillo \'ansabeelika Rabbanat mis \'alaaa amwaalihim washdud \'alaa quloobihim falaa yu\'minoo hatta yarawul \'azaabal aleem',88,'10:88',22,87,180,3,0,218,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1453,10,'قَالَ قَدْ أُجِيبَت دَّعْوَتُكُمَا فَٱسْتَقِيمَا وَلَا تَتَّبِعَآنِّ سَبِيلَ ٱلَّذِينَ لَا يَعْلَمُونَ','Qaala qad ujeebad da\'watukumaa fastaqeemaa wa laa tattabi\'aaanni sabeelal lazeena laaya\'lamoon',89,'10:89',22,87,180,3,0,219,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1454,10,'۞ وَجَـٰوَزْنَا بِبَنِىٓ إِسْرَٰٓءِيلَ ٱلْبَحْرَ فَأَتْبَعَهُمْ فِرْعَوْنُ وَجُنُودُهُۥ بَغْيًا وَعَدْوًا ۖ حَتَّىٰٓ إِذَآ أَدْرَكَهُ ٱلْغَرَقُ قَالَ ءَامَنتُ أَنَّهُۥ لَآ إِلَـٰهَ إِلَّا ٱلَّذِىٓ ءَامَنَتْ بِهِۦ بَنُوٓا۟ إِسْرَٰٓءِيلَ وَأَنَا۠ مِنَ ٱلْمُسْلِمِينَ','Wa jaawaznaa bi Baneee Israaa\'eelal bahra fa atba\'ahum Fir\'awnu wa junooduhoo baghyanw wa \'adwan hattaaa izaaa adrakahul gharaqu qaala aamantu annnahoo laaa ilaaha illal lazeee aamanat bihee Banooo Israaa\'eela wa ana minal muslimeen',90,'10:90',22,88,180,3,0,219,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1455,10,'ءَآلْـَٔـٰنَ وَقَدْ عَصَيْتَ قَبْلُ وَكُنتَ مِنَ ٱلْمُفْسِدِينَ','Aaal\'aana wa qad \'asaita qablu wa kunta minal mufsideen',91,'10:91',22,88,180,3,0,219,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1456,10,'فَٱلْيَوْمَ نُنَجِّيكَ بِبَدَنِكَ لِتَكُونَ لِمَنْ خَلْفَكَ ءَايَةً ۚ وَإِنَّ كَثِيرًا مِّنَ ٱلنَّاسِ عَنْ ءَايَـٰتِنَا لَغَـٰفِلُونَ','Falyawma nunajjeeka bibadanika litakoona liman khalfaka Aayah; wa inna kaseeram minan naasi \'an aayaatinaa laghaafiloon',92,'10:92',22,88,180,3,0,219,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1457,10,'وَلَقَدْ بَوَّأْنَا بَنِىٓ إِسْرَٰٓءِيلَ مُبَوَّأَ صِدْقٍ وَرَزَقْنَـٰهُم مِّنَ ٱلطَّيِّبَـٰتِ فَمَا ٱخْتَلَفُوا۟ حَتَّىٰ جَآءَهُمُ ٱلْعِلْمُ ۚ إِنَّ رَبَّكَ يَقْضِى بَيْنَهُمْ يَوْمَ ٱلْقِيَـٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ','Wa laqad bawwaanaa Baneee Israaa\'eela mubawwa-a sidqinw wa razaqnaahum minnat taiyibaati famakh talafoo hattaa jaaa\'ahmul \'ilm; inna Rabbaka yaqdee bainahum Yawmal Qiyaamati feemaa kaanoo feehi yakhtalifoon',93,'10:93',22,88,181,3,0,219,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1458,10,'فَإِن كُنتَ فِى شَكٍّ مِّمَّآ أَنزَلْنَآ إِلَيْكَ فَسْـَٔلِ ٱلَّذِينَ يَقْرَءُونَ ٱلْكِتَـٰبَ مِن قَبْلِكَ ۚ لَقَدْ جَآءَكَ ٱلْحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ','Fa in kunta fee shakkim mimmaaa anzalnaaa ilaika fas\'alil lazeena yaqra\'oonal Kitaaba min qablik; laqad jaaa\'akal haqqu mir Rabbika falaa takoonanna minal mumtareen',94,'10:94',22,88,181,3,0,219,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1459,10,'وَلَا تَكُونَنَّ مِنَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِ ٱللَّهِ فَتَكُونَ مِنَ ٱلْخَـٰسِرِينَ','Wa laa takoonanna minal lazeena kazzaboo bi Aayaatil laahi fatakoona minal khaasireen',95,'10:95',22,88,181,3,0,219,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1460,10,'إِنَّ ٱلَّذِينَ حَقَّتْ عَلَيْهِمْ كَلِمَتُ رَبِّكَ لَا يُؤْمِنُونَ','Innal lazeena haqqat \'alaihim Kalimatu Rabbika laa yu\'minoon',96,'10:96',22,88,181,3,0,219,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1461,10,'وَلَوْ جَآءَتْهُمْ كُلُّ ءَايَةٍ حَتَّىٰ يَرَوُا۟ ٱلْعَذَابَ ٱلْأَلِيمَ','Wa law jaaa\'at hum kullu Aayatin hattaa yarawul \'azaabal aleem',97,'10:97',22,88,181,3,0,219,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1462,10,'فَلَوْلَا كَانَتْ قَرْيَةٌ ءَامَنَتْ فَنَفَعَهَآ إِيمَـٰنُهَآ إِلَّا قَوْمَ يُونُسَ لَمَّآ ءَامَنُوا۟ كَشَفْنَا عَنْهُمْ عَذَابَ ٱلْخِزْىِ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَمَتَّعْنَـٰهُمْ إِلَىٰ حِينٍ','Falaw laa kaanat qaryatun aamanat fanafa\'ahaaa eemaanuhaaa illaa qawma Yoonusa lammaaa aamanoo kashafnaa \'anhum \'azaabal khizyi fil hayaatid dunyaa wa matta\'naahum ilaa heen',98,'10:98',22,88,181,3,0,220,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1463,10,'وَلَوْ شَآءَ رَبُّكَ لَـَٔامَنَ مَن فِى ٱلْأَرْضِ كُلُّهُمْ جَمِيعًا ۚ أَفَأَنتَ تُكْرِهُ ٱلنَّاسَ حَتَّىٰ يَكُونُوا۟ مُؤْمِنِينَ','Wa law shaaa\'a Rabbuka la aamana man fil ardi kulluhum jamee\'aa; afa anta tukrihun naasa hattaa yakoonoo mu\'mineen',99,'10:99',22,88,181,3,0,220,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1464,10,'وَمَا كَانَ لِنَفْسٍ أَن تُؤْمِنَ إِلَّا بِإِذْنِ ٱللَّهِ ۚ وَيَجْعَلُ ٱلرِّجْسَ عَلَى ٱلَّذِينَ لَا يَعْقِلُونَ','Wa maa kaana linafsin an tu\'mina illaa bi iznil laah; wa yaj\'alur rijsa \'alal lazeena laa ya\'qiloon',100,'10:100',22,88,181,3,0,220,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1465,10,'قُلِ ٱنظُرُوا۟ مَاذَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَمَا تُغْنِى ٱلْـَٔايَـٰتُ وَٱلنُّذُرُ عَن قَوْمٍ لَّا يُؤْمِنُونَ','Qulin zuroo maazaa fissamaawaati wal ard; wa maa tughnil Aayaatu wannuzuru \'an qawmil laa yu\'minoon',101,'10:101',22,88,181,3,0,220,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1466,10,'فَهَلْ يَنتَظِرُونَ إِلَّا مِثْلَ أَيَّامِ ٱلَّذِينَ خَلَوْا۟ مِن قَبْلِهِمْ ۚ قُلْ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ','Fahal yantaziroona illaa misla ayyaamil lazeena khalaw min qablihim; qul fantazirooo innee ma\'akum minal muntazireen',102,'10:102',22,88,181,3,0,220,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1467,10,'ثُمَّ نُنَجِّى رُسُلَنَا وَٱلَّذِينَ ءَامَنُوا۟ ۚ كَذَٰلِكَ حَقًّا عَلَيْنَا نُنجِ ٱلْمُؤْمِنِينَ','Summma nunajjee Ruslanaa wallazeena aamanoo; kazaalika haqqan \'alainaa nunjil mu\'mineen',103,'10:103',22,88,181,3,0,220,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1468,10,'قُلْ يَـٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمْ فِى شَكٍّ مِّن دِينِى فَلَآ أَعْبُدُ ٱلَّذِينَ تَعْبُدُونَ مِن دُونِ ٱللَّهِ وَلَـٰكِنْ أَعْبُدُ ٱللَّهَ ٱلَّذِى يَتَوَفَّىٰكُمْ ۖ وَأُمِرْتُ أَنْ أَكُونَ مِنَ ٱلْمُؤْمِنِينَ','Qul yaaa ayyuhan naasu in kuntum fee shakkkim min deenee falaa a\'budul lazeena ta\'budoona min doonil laahi wa laakin a\'budul laahal lazee yatawaffaakum wa umirtu an akoona minal mu\'mineen',104,'10:104',22,88,182,3,0,220,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1469,10,'وَأَنْ أَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفًا وَلَا تَكُونَنَّ مِنَ ٱلْمُشْرِكِينَ','Wa an aqim wajhaka liddeeni Haneefanw wa laa takoonannna minal mushrikeen',105,'10:105',22,88,182,3,0,220,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1470,10,'وَلَا تَدْعُ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكَ وَلَا يَضُرُّكَ ۖ فَإِن فَعَلْتَ فَإِنَّكَ إِذًا مِّنَ ٱلظَّـٰلِمِينَ','Wa laa tad\'u min doonil laahi maa laa yanfa\'uka wa laa yadurruka fa in fa\'alta fa innaka izam minaz zaalimeen',106,'10:106',22,88,182,3,0,220,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1471,10,'وَإِن يَمْسَسْكَ ٱللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَ ۖ وَإِن يُرِدْكَ بِخَيْرٍ فَلَا رَآدَّ لِفَضْلِهِۦ ۚ يُصِيبُ بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦ ۚ وَهُوَ ٱلْغَفُورُ ٱلرَّحِيمُ','Wa iny yamsaskal laahu bidurrin falaa kaashifa lahoo illaa Huwa wa iny yuridka bikhairin falaa raaadda lifadlih; yuseebu bihee man yashaaa\'u min \'ibaadih; wa huwal Ghafoorur Raheem',107,'10:107',22,88,182,3,0,221,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1472,10,'قُلْ يَـٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَكُمُ ٱلْحَقُّ مِن رَّبِّكُمْ ۖ فَمَنِ ٱهْتَدَىٰ فَإِنَّمَا يَهْتَدِى لِنَفْسِهِۦ ۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا ۖ وَمَآ أَنَا۠ عَلَيْكُم بِوَكِيلٍ','Qul yaaa aiyuhan naasu qad jaaa\'akumul haqqu mir Rabbikum famanih tadaa fa innamaa yahtadee linafsihee wa man dalla fa innamaa yadillu \'alaihaa wa maaa ana \'alaikum biwakeel',108,'10:108',22,88,182,3,0,221,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1473,10,'وَٱتَّبِعْ مَا يُوحَىٰٓ إِلَيْكَ وَٱصْبِرْ حَتَّىٰ يَحْكُمَ ٱللَّهُ ۚ وَهُوَ خَيْرُ ٱلْحَـٰكِمِينَ','Qattabi\' maa yoohaaa ilaika wasbir hattaa yahkumal laah; wa Huwa khairul haakimeen',109,'10:109',22,88,182,3,0,221,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1474,11,'الٓر ۚ كِتَـٰبٌ أُحْكِمَتْ ءَايَـٰتُهُۥ ثُمَّ فُصِّلَتْ مِن لَّدُنْ حَكِيمٍ خَبِيرٍ','Alif-Laaam-Raa; Kitaabun uhkimat Aayaatuhoo summa fussilat mil ladun Hakeemin Khabeer',1,'11:1',22,88,183,3,0,221,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1475,11,'أَلَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ ۚ إِنَّنِى لَكُم مِّنْهُ نَذِيرٌ وَبَشِيرٌ','Allaa ta\'budooo illal laah; innanee lakum minhu nazeerunw wa basheer',2,'11:2',22,88,183,3,0,221,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1476,11,'وَأَنِ ٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ يُمَتِّعْكُم مَّتَـٰعًا حَسَنًا إِلَىٰٓ أَجَلٍ مُّسَمًّى وَيُؤْتِ كُلَّ ذِى فَضْلٍ فَضْلَهُۥ ۖ وَإِن تَوَلَّوْا۟ فَإِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ كَبِيرٍ','Wa anis taghfiroo Rabbakum summa toobooo ilaihi yumatti\'kum mataa\'an hasanan ilaaa ajalim musammanw wa yu\'ti kulla zee fadlin fadlahoo wa in tawallaw fa inneee akhaafu \'alaikum \'azaaba Yawmin Kabeer',3,'11:3',22,88,183,3,0,221,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1477,11,'إِلَى ٱللَّهِ مَرْجِعُكُمْ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ','Ilal laahi marji\'ukum wa Huwa \'alaa kulli shai\'in Qadeer',4,'11:4',22,88,183,3,0,221,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1478,11,'أَلَآ إِنَّهُمْ يَثْنُونَ صُدُورَهُمْ لِيَسْتَخْفُوا۟ مِنْهُ ۚ أَلَا حِينَ يَسْتَغْشُونَ ثِيَابَهُمْ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ ۚ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ','Alaa innahum yasnoona sudoorahum liyastakhfoo minh; alaa heena yastaghshoona siyaabahum ya\'lamu maa yusiroona wa maa yu\'linoon; innahoo \'aleemum bizaatis sudoor',5,'11:5',22,88,183,3,0,221,11,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1479,11,'۞ وَمَا مِن دَآبَّةٍ فِى ٱلْأَرْضِ إِلَّا عَلَى ٱللَّهِ رِزْقُهَا وَيَعْلَمُ مُسْتَقَرَّهَا وَمُسْتَوْدَعَهَا ۚ كُلٌّ فِى كِتَـٰبٍ مُّبِينٍ','Wa maa min daaabbatin fil ardi illaa \'alal laahi rizquhaa wa ya\'lamu mustaqarrahaa wa mustawda\'ahaa; kullun fee Kitaabim Mubeen',6,'11:6',23,89,183,3,0,222,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1480,11,'وَهُوَ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ وَكَانَ عَرْشُهُۥ عَلَى ٱلْمَآءِ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا ۗ وَلَئِن قُلْتَ إِنَّكُم مَّبْعُوثُونَ مِنۢ بَعْدِ ٱلْمَوْتِ لَيَقُولَنَّ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَـٰذَآ إِلَّا سِحْرٌ مُّبِينٌ','Wa Huwal lazee khalaqas samaawaati wal alrda fee sittati aiyaaminw wa kaana \'Arshuhoo alal maaa\'i liyablu wakum aiyukum ahsanu \'amalaa; wa la\'in qulta innakum mab\'oosoona mim ba\'dil mawti la yaqoolanal lazeena kafaroo in haazaaa illaa sihrum mubeen',7,'11:7',23,89,183,3,0,222,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1481,11,'وَلَئِنْ أَخَّرْنَا عَنْهُمُ ٱلْعَذَابَ إِلَىٰٓ أُمَّةٍ مَّعْدُودَةٍ لَّيَقُولُنَّ مَا يَحْبِسُهُۥٓ ۗ أَلَا يَوْمَ يَأْتِيهِمْ لَيْسَ مَصْرُوفًا عَنْهُمْ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ','Wala\'in akhkharnaa \'anhumul \'azaaba ilaaa ummatim ma\'doodatil la yaqoolunna maa yahbisuh; alaa yawma yaateehim laisa masroofan \'anhum wa haaqa bihim maa kaanoo bihee yastahzi\'oon',8,'11:8',23,89,183,3,0,222,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1482,11,'وَلَئِنْ أَذَقْنَا ٱلْإِنسَـٰنَ مِنَّا رَحْمَةً ثُمَّ نَزَعْنَـٰهَا مِنْهُ إِنَّهُۥ لَيَـُٔوسٌ كَفُورٌ','Wa la\'in azaqnal insaana minnaa rahmatan summa naza\'naahaa minhu, innahoo laya\'oosun kafoor',9,'11:9',23,89,184,3,0,222,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1483,11,'وَلَئِنْ أَذَقْنَـٰهُ نَعْمَآءَ بَعْدَ ضَرَّآءَ مَسَّتْهُ لَيَقُولَنَّ ذَهَبَ ٱلسَّيِّـَٔاتُ عَنِّىٓ ۚ إِنَّهُۥ لَفَرِحٌ فَخُورٌ','Wala\'in azaqnaahu na\'maaa\'a ba\'da darraaa\'a massat hu la yaqoolanna zahabas saiyiaatu \'anneee; innahoo lafarihun fakhoor',10,'11:10',23,89,184,3,0,222,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1484,11,'إِلَّا ٱلَّذِينَ صَبَرُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أُو۟لَـٰٓئِكَ لَهُم مَّغْفِرَةٌ وَأَجْرٌ كَبِيرٌ','Illal lazeena sabaroo wa \'amilus saalihaati ulaaa\'ika lahum maghfiratunw wa ajrun kabeer',11,'11:11',23,89,184,3,0,222,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1485,11,'فَلَعَلَّكَ تَارِكٌۢ بَعْضَ مَا يُوحَىٰٓ إِلَيْكَ وَضَآئِقٌۢ بِهِۦ صَدْرُكَ أَن يَقُولُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ كَنزٌ أَوْ جَآءَ مَعَهُۥ مَلَكٌ ۚ إِنَّمَآ أَنتَ نَذِيرٌ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ وَكِيلٌ','Fala\'allaka taarikum ba\'da maa yoohaaa ilaika wa daaa\'iqum bihee sadruka ai yaqooloo law laaa unzila \'alaihi kanzun aw jaaa\'a ma\'ahoo malak; innamaa anta nazeer; wallaahu \'alaa kulli shai\'inw wakeel',12,'11:12',23,89,184,3,0,222,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1486,11,'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ ۖ قُلْ فَأْتُوا۟ بِعَشْرِ سُوَرٍ مِّثْلِهِۦ مُفْتَرَيَـٰتٍ وَٱدْعُوا۟ مَنِ ٱسْتَطَعْتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَـٰدِقِينَ','Am yaqooloonaf taraahu qul faatoo bi\'ashri Suwarim mislihee muftarayaatinw wad\'oo manis tata\'tum min doonil laahi in kuntum saadiqeen',13,'11:13',23,89,184,3,0,223,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1487,11,'فَإِلَّمْ يَسْتَجِيبُوا۟ لَكُمْ فَٱعْلَمُوٓا۟ أَنَّمَآ أُنزِلَ بِعِلْمِ ٱللَّهِ وَأَن لَّآ إِلَـٰهَ إِلَّا هُوَ ۖ فَهَلْ أَنتُم مُّسْلِمُونَ','Fa il lam yastajeeboo lakum fa\'lamooo annamaaa unzilla bi\'ilmil laahi wa al laaa ilaaha illaa Huwa fahal antum muslimoon',14,'11:14',23,89,184,3,0,223,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1488,11,'مَن كَانَ يُرِيدُ ٱلْحَيَوٰةَ ٱلدُّنْيَا وَزِينَتَهَا نُوَفِّ إِلَيْهِمْ أَعْمَـٰلَهُمْ فِيهَا وَهُمْ فِيهَا لَا يُبْخَسُونَ','Man kaana yureedul hayaatad dunyaa zeenatahaa nuwaffi ilaihim a\'maa lahum feehaa wa hum feehaa laa yubkhasoon',15,'11:15',23,89,184,3,0,223,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1489,11,'أُو۟لَـٰٓئِكَ ٱلَّذِينَ لَيْسَ لَهُمْ فِى ٱلْـَٔاخِرَةِ إِلَّا ٱلنَّارُ ۖ وَحَبِطَ مَا صَنَعُوا۟ فِيهَا وَبَـٰطِلٌ مَّا كَانُوا۟ يَعْمَلُونَ','Ulaaa\'ikal lazeena laisa lahum fil Aakhirati illan Naaru wa habita maa sana\'oo feehaa wa baatilum maa kaanoo ya\'maloon',16,'11:16',23,89,184,3,0,223,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1490,11,'أَفَمَن كَانَ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّهِۦ وَيَتْلُوهُ شَاهِدٌ مِّنْهُ وَمِن قَبْلِهِۦ كِتَـٰبُ مُوسَىٰٓ إِمَامًا وَرَحْمَةً ۚ أُو۟لَـٰٓئِكَ يُؤْمِنُونَ بِهِۦ ۚ وَمَن يَكْفُرْ بِهِۦ مِنَ ٱلْأَحْزَابِ فَٱلنَّارُ مَوْعِدُهُۥ ۚ فَلَا تَكُ فِى مِرْيَةٍ مِّنْهُ ۚ إِنَّهُ ٱلْحَقُّ مِن رَّبِّكَ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يُؤْمِنُونَ','Afaman kaana \'alas baiyinatim mir Rabbihee wa yatloohu shaahidum minhu wa min qablihee Kitaabu Moosaaa imaamanw wa rahmah; ulaaa \'ika yu\'minoona bih; wa mai yakfur bihee minal Ahzaabi fan Naaru maw\'iduh; falaa taku fee miryatim minh; innahul haqqu mir Rabbika wa laakinna aksaran naasi laa yu\'minoon',17,'11:17',23,89,184,3,0,223,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1491,11,'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا ۚ أُو۟لَـٰٓئِكَ يُعْرَضُونَ عَلَىٰ رَبِّهِمْ وَيَقُولُ ٱلْأَشْهَـٰدُ هَـٰٓؤُلَآءِ ٱلَّذِينَ كَذَبُوا۟ عَلَىٰ رَبِّهِمْ ۚ أَلَا لَعْنَةُ ٱللَّهِ عَلَى ٱلظَّـٰلِمِينَ','Wa man azlamu mimmanif taraa \'alal laahi kazibaa; ulaaa\'ika yu\'radoona \'alaa Rabbihim wa yaqoolul ashhaa duhaaa\'ulaaa\'il lazeena kazaboo \'alaa Rabbihim; alaa la\'natul laahi alaz zaalimeen',18,'11:18',23,89,184,3,0,223,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1492,11,'ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِٱلْـَٔاخِرَةِ هُمْ كَـٰفِرُونَ','Allazeena yasuddoona \'an sabeelil laahi wa yabghoonahaa \'iwajanw wa hum bil Aakhiratihum kaafiroon',19,'11:19',23,89,184,3,0,223,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1493,11,'أُو۟لَـٰٓئِكَ لَمْ يَكُونُوا۟ مُعْجِزِينَ فِى ٱلْأَرْضِ وَمَا كَانَ لَهُم مِّن دُونِ ٱللَّهِ مِنْ أَوْلِيَآءَ ۘ يُضَـٰعَفُ لَهُمُ ٱلْعَذَابُ ۚ مَا كَانُوا۟ يَسْتَطِيعُونَ ٱلسَّمْعَ وَمَا كَانُوا۟ يُبْصِرُونَ','Ulaaa\'ika lam yakoonoo mu\'jizeena fil ardi wa maa kaana lahum min doonil laahi min awliyaaa\'; yudaa\'afu lahumul \'azaab; maa kaanoo yastatee\'oonas sam\'a wa maa kaanoo yubsiroon',20,'11:20',23,89,184,3,0,224,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1494,11,'أُو۟لَـٰٓئِكَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ','Ulaaa\'ikal lazeena khasirooo anfusahum wa dalla \'anhum maa kaanoo yaftaroon',21,'11:21',23,89,184,3,0,224,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1495,11,'لَا جَرَمَ أَنَّهُمْ فِى ٱلْـَٔاخِرَةِ هُمُ ٱلْأَخْسَرُونَ','Laa jarama annahum fil Aakhirati humul akhsaroon',22,'11:22',23,89,184,3,0,224,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1496,11,'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَأَخْبَتُوٓا۟ إِلَىٰ رَبِّهِمْ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْجَنَّةِ ۖ هُمْ فِيهَا خَـٰلِدُونَ','Innal lazeena aamanoo wa \'amilus saalihaati wa akhbatooo ilaa Rabbihim ulaaa\'ika Ashaabul Jannati hum feehaa khaalidoon',23,'11:23',23,89,184,3,0,224,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1497,11,'۞ مَثَلُ ٱلْفَرِيقَيْنِ كَٱلْأَعْمَىٰ وَٱلْأَصَمِّ وَٱلْبَصِيرِ وَٱلسَّمِيعِ ۚ هَلْ يَسْتَوِيَانِ مَثَلًا ۚ أَفَلَا تَذَكَّرُونَ','Masalul fareeqini kal a\'maa wal asammi walbaseeri wassamee\'; hal yastawiyaani masalaa; afalaa tazakkaroon',24,'11:24',23,90,184,3,0,224,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1498,11,'وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦٓ إِنِّى لَكُمْ نَذِيرٌ مُّبِينٌ','Wa laqad arsalnaa Noohan ilaa qawmihee innee lakum nazeerum mubeen',25,'11:25',23,90,185,3,0,224,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1499,11,'أَن لَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ ۖ إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ أَلِيمٍ','Al laa ta\'budooo illal laaha inneee akhaafu \'alaikum \'azaaba Yawmin aleem',26,'11:26',23,90,185,3,0,224,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1500,11,'فَقَالَ ٱلْمَلَأُ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦ مَا نَرَىٰكَ إِلَّا بَشَرًا مِّثْلَنَا وَمَا نَرَىٰكَ ٱتَّبَعَكَ إِلَّا ٱلَّذِينَ هُمْ أَرَاذِلُنَا بَادِىَ ٱلرَّأْىِ وَمَا نَرَىٰ لَكُمْ عَلَيْنَا مِن فَضْلٍۭ بَلْ نَظُنُّكُمْ كَـٰذِبِينَ','Faqaalal mala ul lazeena kafaroo min qawmihee ma naraaka illaa basharam mislanaa wa maa naraakat taba\'aka illal lazeena hum araazilunaa baadiyar raayi wa maa naraa lakum \'alainaa min fadlim bal nazunnukum kaazibeen',27,'11:27',23,90,185,3,0,224,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1501,11,'قَالَ يَـٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَءَاتَىٰنِى رَحْمَةً مِّنْ عِندِهِۦ فَعُمِّيَتْ عَلَيْكُمْ أَنُلْزِمُكُمُوهَا وَأَنتُمْ لَهَا كَـٰرِهُونَ','Qaala yaa qawmi ara\'aitum in kuntu \'alaa baiyinatim mir Rabbee wa aataanee rahmatam min \'indihee fa\'um miyat \'alaikum anulzimuku moohaa wa antum lahaa kaarihoon',28,'11:28',23,90,185,3,0,224,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1502,11,'وَيَـٰقَوْمِ لَآ أَسْـَٔلُكُمْ عَلَيْهِ مَالًا ۖ إِنْ أَجْرِىَ إِلَّا عَلَى ٱللَّهِ ۚ وَمَآ أَنَا۠ بِطَارِدِ ٱلَّذِينَ ءَامَنُوٓا۟ ۚ إِنَّهُم مُّلَـٰقُوا۟ رَبِّهِمْ وَلَـٰكِنِّىٓ أَرَىٰكُمْ قَوْمًا تَجْهَلُونَ','Wa yaa qawmi laaa as\'alukum \'alaihi maalan in ajriya illaa \'alal laah; wa maaa ana bitaaridil lazeena aamanoo; innahum mulaaqoo Rabbihim wa laakinneee araakum qawman tajhaloon',29,'11:29',23,90,185,3,0,225,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1503,11,'وَيَـٰقَوْمِ مَن يَنصُرُنِى مِنَ ٱللَّهِ إِن طَرَدتُّهُمْ ۚ أَفَلَا تَذَكَّرُونَ','Wa yaa qawmi mai yansurunee minal laahi in tarattuhum; afalaa tazak karoon',30,'11:30',23,90,185,3,0,225,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1504,11,'وَلَآ أَقُولُ لَكُمْ عِندِى خَزَآئِنُ ٱللَّهِ وَلَآ أَعْلَمُ ٱلْغَيْبَ وَلَآ أَقُولُ إِنِّى مَلَكٌ وَلَآ أَقُولُ لِلَّذِينَ تَزْدَرِىٓ أَعْيُنُكُمْ لَن يُؤْتِيَهُمُ ٱللَّهُ خَيْرًا ۖ ٱللَّهُ أَعْلَمُ بِمَا فِىٓ أَنفُسِهِمْ ۖ إِنِّىٓ إِذًا لَّمِنَ ٱلظَّـٰلِمِينَ','Wa laa aqoolu lakum \'indee khazaa\'inul laahi wa laaa a\'lamul ghaiba wa laa aqoolu inee malakunw wa laaa aqoolu lillazeena tazdareee a\'yunukum lai yu\'tiyahumul laahu khairan Allaahu a\'lamu bimaa feee anfusihim innee izal laminaz zaalimeen',31,'11:31',23,90,185,3,0,225,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1505,11,'قَالُوا۟ يَـٰنُوحُ قَدْ جَـٰدَلْتَنَا فَأَكْثَرْتَ جِدَٰلَنَا فَأْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ','Qaaloo yaa Noohu qad jaadaltanaa fa aksarta jidaalanaa faatinaa bimaa ta\'idunaaa in kunta minas saadiqeen',32,'11:32',23,90,185,3,0,225,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1506,11,'قَالَ إِنَّمَا يَأْتِيكُم بِهِ ٱللَّهُ إِن شَآءَ وَمَآ أَنتُم بِمُعْجِزِينَ','Qaala innamaa yaateekum bihil laahu in shaaa\'a wa maaa antum bimu\'jizeen',33,'11:33',23,90,185,3,0,225,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1507,11,'وَلَا يَنفَعُكُمْ نُصْحِىٓ إِنْ أَرَدتُّ أَنْ أَنصَحَ لَكُمْ إِن كَانَ ٱللَّهُ يُرِيدُ أَن يُغْوِيَكُمْ ۚ هُوَ رَبُّكُمْ وَإِلَيْهِ تُرْجَعُونَ','Wa laa yanfa\'ukum nusheee in arattu an ansaha lakum in kaanal laahu yureedu ai yughwi yakum; Huwa Rabbukum wa ilaihi turja\'oon',34,'11:34',23,90,185,3,0,225,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1508,11,'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ ۖ قُلْ إِنِ ٱفْتَرَيْتُهُۥ فَعَلَىَّ إِجْرَامِى وَأَنَا۠ بَرِىٓءٌ مِّمَّا تُجْرِمُونَ','Am yaqooloonaf taraahu qul inif taraituhoo fa\'alaiya ijraamee wa ana bareee\'um mimmaa tujrimoon',35,'11:35',23,90,185,3,0,225,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1509,11,'وَأُوحِىَ إِلَىٰ نُوحٍ أَنَّهُۥ لَن يُؤْمِنَ مِن قَوْمِكَ إِلَّا مَن قَدْ ءَامَنَ فَلَا تَبْتَئِسْ بِمَا كَانُوا۟ يَفْعَلُونَ','Wa oohiya ilaa Noohin annahoo lany-yu\'mina min qawmika illaa man qad aamana falaa tabta\'is bimaa kaanoo yaf\'aloon',36,'11:36',23,90,186,3,0,225,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1510,11,'وَٱصْنَعِ ٱلْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا وَلَا تُخَـٰطِبْنِى فِى ٱلَّذِينَ ظَلَمُوٓا۟ ۚ إِنَّهُم مُّغْرَقُونَ','Wasna\'il fulka bi-a\'yuninaa wa wahyinaa wa laa tukhaa tibnee fil lazeena zalamoo; innahum mughraqoon',37,'11:37',23,90,186,3,0,225,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1511,11,'وَيَصْنَعُ ٱلْفُلْكَ وَكُلَّمَا مَرَّ عَلَيْهِ مَلَأٌ مِّن قَوْمِهِۦ سَخِرُوا۟ مِنْهُ ۚ قَالَ إِن تَسْخَرُوا۟ مِنَّا فَإِنَّا نَسْخَرُ مِنكُمْ كَمَا تَسْخَرُونَ','Wa yasn\'ul fulka wa kullamaa marra \'alaihi malaum min qawmihee sakhiroo minh; qaala in taskharoo minnaa fa innaa naskharu minkum kamaa taskharoon',38,'11:38',23,90,186,3,0,226,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1512,11,'فَسَوْفَ تَعْلَمُونَ مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ','Fasawfa ta\'lamoona mai yaateehi \'azaabuny yaukhzeehi wa yahillu \'alaihi \'azaabum muqeem',39,'11:39',23,90,186,3,0,226,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1513,11,'حَتَّىٰٓ إِذَا جَآءَ أَمْرُنَا وَفَارَ ٱلتَّنُّورُ قُلْنَا ٱحْمِلْ فِيهَا مِن كُلٍّ زَوْجَيْنِ ٱثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ ٱلْقَوْلُ وَمَنْ ءَامَنَ ۚ وَمَآ ءَامَنَ مَعَهُۥٓ إِلَّا قَلِيلٌ','Hattaaa izaa jaaa\'a amrunaa wa faarat tannooru qulnah mil feehaa min kullin zawjainis naini wa ahlaka illaa man sabaqa \'alaihil qawlu wa man aaman; wa maaa aamana ma\'ahooo illaa qaleel',40,'11:40',23,90,186,3,0,226,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1514,11,'۞ وَقَالَ ٱرْكَبُوا۟ فِيهَا بِسْمِ ٱللَّهِ مَجْر۪ىٰهَا وَمُرْسَىٰهَآ ۚ إِنَّ رَبِّى لَغَفُورٌ رَّحِيمٌ','Wa qaalar kaboo feehaa bismil laahi majraihaa wa mursaahaa; inna Rabbee la Ghafoorur Raheem',41,'11:41',23,91,186,3,0,226,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1515,11,'وَهِىَ تَجْرِى بِهِمْ فِى مَوْجٍ كَٱلْجِبَالِ وَنَادَىٰ نُوحٌ ٱبْنَهُۥ وَكَانَ فِى مَعْزِلٍ يَـٰبُنَىَّ ٱرْكَب مَّعَنَا وَلَا تَكُن مَّعَ ٱلْكَـٰفِرِينَ','Wa hiya tajree bihim fee mawjin kaljibaali wa naadaa Noohunib nahoo wa kaana fee ma\'ziliny yaa bunai yarkam ma\'anaa wa laa takum ma\'al kaafireen',42,'11:42',23,91,186,3,0,226,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1516,11,'قَالَ سَـَٔاوِىٓ إِلَىٰ جَبَلٍ يَعْصِمُنِى مِنَ ٱلْمَآءِ ۚ قَالَ لَا عَاصِمَ ٱلْيَوْمَ مِنْ أَمْرِ ٱللَّهِ إِلَّا مَن رَّحِمَ ۚ وَحَالَ بَيْنَهُمَا ٱلْمَوْجُ فَكَانَ مِنَ ٱلْمُغْرَقِينَ','Qaala sa aaweee ilaa jabaliny ya\'simunee minal maaa\'; qaala laa \'aasimal yawma min amril laahi illaa mar rahim; wa haala bainahumal mawju fakaana minal mughraqeen',43,'11:43',23,91,186,3,0,226,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1517,11,'وَقِيلَ يَـٰٓأَرْضُ ٱبْلَعِى مَآءَكِ وَيَـٰسَمَآءُ أَقْلِعِى وَغِيضَ ٱلْمَآءُ وَقُضِىَ ٱلْأَمْرُ وَٱسْتَوَتْ عَلَى ٱلْجُودِىِّ ۖ وَقِيلَ بُعْدًا لِّلْقَوْمِ ٱلظَّـٰلِمِينَ','Wa qeela yaaa ardubla\'ee maaa\'aki wa yaa samaaa\'u aqi\'ee wa gheedal maaa\'u wa qudiyal amru wastawat \'alal joodiyyi wa qeela bu\'dal lilqawmiz zaalimeen',44,'11:44',23,91,186,3,0,226,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1518,11,'وَنَادَىٰ نُوحٌ رَّبَّهُۥ فَقَالَ رَبِّ إِنَّ ٱبْنِى مِنْ أَهْلِى وَإِنَّ وَعْدَكَ ٱلْحَقُّ وَأَنتَ أَحْكَمُ ٱلْحَـٰكِمِينَ','Wa naadaa noohur Rabbahoo faqaala Rabbi innabnee min ahlee wa inna wa\'dakal haqqu wa Anta ahkamul haakimeen',45,'11:45',23,91,186,3,0,226,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1519,11,'قَالَ يَـٰنُوحُ إِنَّهُۥ لَيْسَ مِنْ أَهْلِكَ ۖ إِنَّهُۥ عَمَلٌ غَيْرُ صَـٰلِحٍ ۖ فَلَا تَسْـَٔلْنِ مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ ۖ إِنِّىٓ أَعِظُكَ أَن تَكُونَ مِنَ ٱلْجَـٰهِلِينَ','Qaala yaa Noohu innahoo laisa min ahlika innahoo \'amalun ghairu saalihin falaa tas\'alni mmaa laisa laka bihee \'ilmun inneee a\'izuka an takoona minal jaahileen',46,'11:46',23,91,186,3,0,227,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1520,11,'قَالَ رَبِّ إِنِّىٓ أَعُوذُ بِكَ أَنْ أَسْـَٔلَكَ مَا لَيْسَ لِى بِهِۦ عِلْمٌ ۖ وَإِلَّا تَغْفِرْ لِى وَتَرْحَمْنِىٓ أَكُن مِّنَ ٱلْخَـٰسِرِينَ','Qaala rabbi inneee a\'oozu bika an as\'alaka maa laisa lee bihee \'ilmunw wa illaa taghfir lee wa tarhamneee akum minal khaasireen',47,'11:47',23,91,186,3,0,227,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1521,11,'قِيلَ يَـٰنُوحُ ٱهْبِطْ بِسَلَـٰمٍ مِّنَّا وَبَرَكَـٰتٍ عَلَيْكَ وَعَلَىٰٓ أُمَمٍ مِّمَّن مَّعَكَ ۚ وَأُمَمٌ سَنُمَتِّعُهُمْ ثُمَّ يَمَسُّهُم مِّنَّا عَذَابٌ أَلِيمٌ','Qeela yaa Noohuh bit bisalaamim minnaa wa barakaatin \'alaika wa \'alaaa umamim mimmam ma\'ak; wa umamun sanumatti\'uhum summa yamassuhum minaa \'azaabun aleem',48,'11:48',23,91,186,3,0,227,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1522,11,'تِلْكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهَآ إِلَيْكَ ۖ مَا كُنتَ تَعْلَمُهَآ أَنتَ وَلَا قَوْمُكَ مِن قَبْلِ هَـٰذَا ۖ فَٱصْبِرْ ۖ إِنَّ ٱلْعَـٰقِبَةَ لِلْمُتَّقِينَ','Tilka min ambaaa\'il ghaibi nooheehaaa ilaika maa kunta ta\'lamuhaaaa anta wa laa qawmuka min qabli haazaa fasbir innal \'aaqibata lilmuttaqeen',49,'11:49',23,91,186,3,0,227,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1523,11,'وَإِلَىٰ عَادٍ أَخَاهُمْ هُودًا ۚ قَالَ يَـٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَـٰهٍ غَيْرُهُۥٓ ۖ إِنْ أَنتُمْ إِلَّا مُفْتَرُونَ','Wa ilaa \'aadin akhaahum Hoodaa; qaala yaa qawmi\' budul laaha maa lakum min ilaahin ghairuhooo in antum illaa muftaroon',50,'11:50',23,91,187,3,0,227,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1524,11,'يَـٰقَوْمِ لَآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا ۖ إِنْ أَجْرِىَ إِلَّا عَلَى ٱلَّذِى فَطَرَنِىٓ ۚ أَفَلَا تَعْقِلُونَ','Yaa qawmi laaa as\'alukum \'alaihi ajran in ajriya illaa \'alal lazee fataranee; afalaa ta\'qiloon',51,'11:51',23,91,187,3,0,227,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1525,11,'وَيَـٰقَوْمِ ٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ يُرْسِلِ ٱلسَّمَآءَ عَلَيْكُم مِّدْرَارًا وَيَزِدْكُمْ قُوَّةً إِلَىٰ قُوَّتِكُمْ وَلَا تَتَوَلَّوْا۟ مُجْرِمِينَ','Wa yaa qawmis taghfiroo Rabbakum summa toobooo ilaihi yursilis samaaa\'a \'alaikum midraaranw wa yazidkum quwwatan ilaa quwwatikum wa laa tatawallaw mujrimeen',52,'11:52',23,91,187,3,0,227,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1526,11,'قَالُوا۟ يَـٰهُودُ مَا جِئْتَنَا بِبَيِّنَةٍ وَمَا نَحْنُ بِتَارِكِىٓ ءَالِهَتِنَا عَن قَوْلِكَ وَمَا نَحْنُ لَكَ بِمُؤْمِنِينَ','Qaaloo yaa Hoodu maa ji\'tanaa bibaiyinatinw wa maa nahnu bitaarikeee aalihatinaa \'an qawlika wa maa nahnu laka bimu\'mineen',53,'11:53',23,91,187,3,0,227,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1527,11,'إِن نَّقُولُ إِلَّا ٱعْتَرَىٰكَ بَعْضُ ءَالِهَتِنَا بِسُوٓءٍ ۗ قَالَ إِنِّىٓ أُشْهِدُ ٱللَّهَ وَٱشْهَدُوٓا۟ أَنِّى بَرِىٓءٌ مِّمَّا تُشْرِكُونَ','In naqoolu illa\' taraaka ba\'du aalihatinaa bisooo\'; qaala inneee ushhidul laaha wash hadooo annee bareee\'um mimmaa tushrikoon',54,'11:54',23,91,187,3,0,228,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1528,11,'مِن دُونِهِۦ ۖ فَكِيدُونِى جَمِيعًا ثُمَّ لَا تُنظِرُونِ','Min doonihee fakeedoonee jamee\'an summa laa tunziroon',55,'11:55',23,91,187,3,0,228,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1529,11,'إِنِّى تَوَكَّلْتُ عَلَى ٱللَّهِ رَبِّى وَرَبِّكُم ۚ مَّا مِن دَآبَّةٍ إِلَّا هُوَ ءَاخِذٌۢ بِنَاصِيَتِهَآ ۚ إِنَّ رَبِّى عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ','Innee tawakkaltu \'alallaahi Rabbee wa Rabbikum; maa min daaabbatin illaa Huwa aakhizum binaasiyatihaa; inna Rabbee \'alaa Siraatim mustaqeem',56,'11:56',23,91,187,3,0,228,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1530,11,'فَإِن تَوَلَّوْا۟ فَقَدْ أَبْلَغْتُكُم مَّآ أُرْسِلْتُ بِهِۦٓ إِلَيْكُمْ ۚ وَيَسْتَخْلِفُ رَبِّى قَوْمًا غَيْرَكُمْ وَلَا تَضُرُّونَهُۥ شَيْـًٔا ۚ إِنَّ رَبِّى عَلَىٰ كُلِّ شَىْءٍ حَفِيظٌ','Fa in tawallaw faqad ablaghtukum maaa ursiltu biheee ilaikum; wa yastakhlifu Rabbee qawman ghairakum wa laa tadur roonahoo shai\'aa; inna Rabbee \'alaa kulli shai\'in Hafeez',57,'11:57',23,91,187,3,0,228,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1531,11,'وَلَمَّا جَآءَ أَمْرُنَا نَجَّيْنَا هُودًا وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَنَجَّيْنَـٰهُم مِّنْ عَذَابٍ غَلِيظٍ','Wa lammaa jaaa\'a amrunaa najainaa Hoodanw wallazeena aamanoo ma\'ahoo birahmatim minnaa wa najainaahum min \'azaabin ghaleez',58,'11:58',23,91,187,3,0,228,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1532,11,'وَتِلْكَ عَادٌ ۖ جَحَدُوا۟ بِـَٔايَـٰتِ رَبِّهِمْ وَعَصَوْا۟ رُسُلَهُۥ وَٱتَّبَعُوٓا۟ أَمْرَ كُلِّ جَبَّارٍ عَنِيدٍ','Wa tilka \'aad, jahadoo bi Aayaati Rabbihim wa \'asaw Rusulahoo wattaba\'ooo amra kulli jabbaarin \'aneed',59,'11:59',23,91,187,3,0,228,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1533,11,'وَأُتْبِعُوا۟ فِى هَـٰذِهِ ٱلدُّنْيَا لَعْنَةً وَيَوْمَ ٱلْقِيَـٰمَةِ ۗ أَلَآ إِنَّ عَادًا كَفَرُوا۟ رَبَّهُمْ ۗ أَلَا بُعْدًا لِّعَادٍ قَوْمِ هُودٍ','Wa utbi\'oo fee haazihid dunyaa la\'natanw wa Yawmal Qiyaamah; alaaa inna \'Aadan kafaroo Rabbahum; alaa bu\'dal li \'Aadin qawmin Hood',60,'11:60',23,91,187,3,0,228,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1534,11,'۞ وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَـٰلِحًا ۚ قَالَ يَـٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَـٰهٍ غَيْرُهُۥ ۖ هُوَ أَنشَأَكُم مِّنَ ٱلْأَرْضِ وَٱسْتَعْمَرَكُمْ فِيهَا فَٱسْتَغْفِرُوهُ ثُمَّ تُوبُوٓا۟ إِلَيْهِ ۚ إِنَّ رَبِّى قَرِيبٌ مُّجِيبٌ','Wa ilaa Samooda akhaahum Saalihaa; qaala yaa qawmi\' budul laaha maa lakum min ilaahim ghairuhoo Huwa ansha akum minal ardi wasta\' marakum feehaa fastaghfiroohu summa toobooo ilaih; inna Rabbee Qareebum Mujeeb',61,'11:61',23,92,188,3,0,228,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1535,11,'قَالُوا۟ يَـٰصَـٰلِحُ قَدْ كُنتَ فِينَا مَرْجُوًّا قَبْلَ هَـٰذَآ ۖ أَتَنْهَىٰنَآ أَن نَّعْبُدَ مَا يَعْبُدُ ءَابَآؤُنَا وَإِنَّنَا لَفِى شَكٍّ مِّمَّا تَدْعُونَآ إِلَيْهِ مُرِيبٍ','Qaaloo yaa Saalihu qad kunta feenaa marjuwwan qabla haazaaa atanhaanaaa an na\'bu da maa ya\'budu aabaaa\'unaa wa innanaa lafee shakkim mimmaa tad\'oonaaa ilaihi mureeb',62,'11:62',23,92,188,3,0,228,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1536,11,'قَالَ يَـٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَءَاتَىٰنِى مِنْهُ رَحْمَةً فَمَن يَنصُرُنِى مِنَ ٱللَّهِ إِنْ عَصَيْتُهُۥ ۖ فَمَا تَزِيدُونَنِى غَيْرَ تَخْسِيرٍ','Qaala yaa qawmi ara\'aytum in kuntu \'alaa baiyinatim mir Rabbee wa aataanee minhu rahmatan famai yansurunee minal laahi in \'asaituhoo famaa tazeedoonanee ghaira takhseer',63,'11:63',23,92,188,3,0,229,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1537,11,'وَيَـٰقَوْمِ هَـٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمْ ءَايَةً فَذَرُوهَا تَأْكُلْ فِىٓ أَرْضِ ٱللَّهِ وَلَا تَمَسُّوهَا بِسُوٓءٍ فَيَأْخُذَكُمْ عَذَابٌ قَرِيبٌ','Wa yaa qawmi haazihee naaqatul laahi lakum aayatan fazaroohaa taakul feee ardil laahi wa laa tamassoohaa bisooo\'in fa yaakhuzakum azaabun qareeb',64,'11:64',23,92,188,3,0,229,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1538,11,'فَعَقَرُوهَا فَقَالَ تَمَتَّعُوا۟ فِى دَارِكُمْ ثَلَـٰثَةَ أَيَّامٍ ۖ ذَٰلِكَ وَعْدٌ غَيْرُ مَكْذُوبٍ','Fa \'aqaroohaa faqaala tamatta\'oo fee daarikum salaasata aiyaamin zaalika wa\'dun ghairu makzoob',65,'11:65',23,92,188,3,0,229,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1539,11,'فَلَمَّا جَآءَ أَمْرُنَا نَجَّيْنَا صَـٰلِحًا وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَمِنْ خِزْىِ يَوْمِئِذٍ ۗ إِنَّ رَبَّكَ هُوَ ٱلْقَوِىُّ ٱلْعَزِيزُ','Falammaa jaaa\'a amrunaa najjainaa Saalihanw wal lazeena aamanoo ma\'ahoo birahmatim minnaa wa min khizyi Yawmi\'iz inna Rabbaka Huwal Qawiyyul \'Azeez',66,'11:66',23,92,188,3,0,229,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1540,11,'وَأَخَذَ ٱلَّذِينَ ظَلَمُوا۟ ٱلصَّيْحَةُ فَأَصْبَحُوا۟ فِى دِيَـٰرِهِمْ جَـٰثِمِينَ','Wa akhazal lazeena zalamus saihatu fa asbahoo fee diyaarihim jaasimeena',67,'11:67',23,92,188,3,0,229,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1541,11,'كَأَن لَّمْ يَغْنَوْا۟ فِيهَآ ۗ أَلَآ إِنَّ ثَمُودَا۟ كَفَرُوا۟ رَبَّهُمْ ۗ أَلَا بُعْدًا لِّثَمُودَ','Ka al lam yaghnaw feehaaa; alaaa inna Samooda kafaroo Rabbahum; alaa bu\'dal li Samood.',68,'11:68',23,92,188,3,0,229,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1542,11,'وَلَقَدْ جَآءَتْ رُسُلُنَآ إِبْرَٰهِيمَ بِٱلْبُشْرَىٰ قَالُوا۟ سَلَـٰمًا ۖ قَالَ سَلَـٰمٌ ۖ فَمَا لَبِثَ أَن جَآءَ بِعِجْلٍ حَنِيذٍ','Wa laqad jaaa\'at Rusulunaaa Ibraaheema bilbushraa qaaloo salaaman qaala salaamun famaa labisa an jaaa\'a bi\'ijin haneez',69,'11:69',23,92,189,3,0,229,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1543,11,'فَلَمَّا رَءَآ أَيْدِيَهُمْ لَا تَصِلُ إِلَيْهِ نَكِرَهُمْ وَأَوْجَسَ مِنْهُمْ خِيفَةً ۚ قَالُوا۟ لَا تَخَفْ إِنَّآ أُرْسِلْنَآ إِلَىٰ قَوْمِ لُوطٍ','Falammaa ra aaa aidiyahum laa tasilu ilaihi nakirahum wa awjasa minhum kheefah; qaaloo la takhaf innaaa ursilnaaa ilaa qawmi Loot',70,'11:70',23,92,189,3,0,229,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1544,11,'وَٱمْرَأَتُهُۥ قَآئِمَةٌ فَضَحِكَتْ فَبَشَّرْنَـٰهَا بِإِسْحَـٰقَ وَمِن وَرَآءِ إِسْحَـٰقَ يَعْقُوبَ','Wamra atuhoo qaaa\'imatun fadahikat fabashsharnaahaa bi Ishaaqa wa minw waraaa\'i Ishaaqa Ya\'qoob',71,'11:71',23,92,189,3,0,229,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1545,11,'قَالَتْ يَـٰوَيْلَتَىٰٓ ءَأَلِدُ وَأَنَا۠ عَجُوزٌ وَهَـٰذَا بَعْلِى شَيْخًا ۖ إِنَّ هَـٰذَا لَشَىْءٌ عَجِيبٌ','Qaalat yaa wailataaa \'aalidu wa ana \'ajoozunw wa haaza ba\'lee shaikhan inna haazaa lashai\'un \'ajeeb',72,'11:72',23,92,189,3,0,230,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1546,11,'قَالُوٓا۟ أَتَعْجَبِينَ مِنْ أَمْرِ ٱللَّهِ ۖ رَحْمَتُ ٱللَّهِ وَبَرَكَـٰتُهُۥ عَلَيْكُمْ أَهْلَ ٱلْبَيْتِ ۚ إِنَّهُۥ حَمِيدٌ مَّجِيدٌ','Qaalooo ata\'jabeena min amril laahi rahmatul laahi wa barakaatuho \'alaikum Ahlal Bayt; innahoo Hameedum Majeed',73,'11:73',23,92,189,3,0,230,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1547,11,'فَلَمَّا ذَهَبَ عَنْ إِبْرَٰهِيمَ ٱلرَّوْعُ وَجَآءَتْهُ ٱلْبُشْرَىٰ يُجَـٰدِلُنَا فِى قَوْمِ لُوطٍ','Falammaa zahaba an Ibraaheemar raw\'u wa jaaa\'at hul bushraaa yujaadilunaa fee qawmi Loot',74,'11:74',23,92,189,3,0,230,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1548,11,'إِنَّ إِبْرَٰهِيمَ لَحَلِيمٌ أَوَّٰهٌ مُّنِيبٌ','Inna Ibraaheema lahaleemun awwwaahum muneeb',75,'11:75',23,92,189,3,0,230,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1549,11,'يَـٰٓإِبْرَٰهِيمُ أَعْرِضْ عَنْ هَـٰذَآ ۖ إِنَّهُۥ قَدْ جَآءَ أَمْرُ رَبِّكَ ۖ وَإِنَّهُمْ ءَاتِيهِمْ عَذَابٌ غَيْرُ مَرْدُودٍ','Yaaa Ibraaheemu a\'rid \'an haazaaa innahoo qad jaaa\'a amru Rabbika wa innahum aateehim \'azaabun ghairun mardood',76,'11:76',23,92,189,3,0,230,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1550,11,'وَلَمَّا جَآءَتْ رُسُلُنَا لُوطًا سِىٓءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًا وَقَالَ هَـٰذَا يَوْمٌ عَصِيبٌ','Wa lammaa jaaa\'at Rusulunaa Lootan seee\'a bihim wa daaqa bihim zar\'anw wa qaala haazaa yawmun \'aseeb',77,'11:77',23,92,189,3,0,230,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1551,11,'وَجَآءَهُۥ قَوْمُهُۥ يُهْرَعُونَ إِلَيْهِ وَمِن قَبْلُ كَانُوا۟ يَعْمَلُونَ ٱلسَّيِّـَٔاتِ ۚ قَالَ يَـٰقَوْمِ هَـٰٓؤُلَآءِ بَنَاتِى هُنَّ أَطْهَرُ لَكُمْ ۖ فَٱتَّقُوا۟ ٱللَّهَ وَلَا تُخْزُونِ فِى ضَيْفِىٓ ۖ أَلَيْسَ مِنكُمْ رَجُلٌ رَّشِيدٌ','Wa jaaa\'ahoo qawmuhoo yuhra\'oona ilaihi wa min qablu kaanoo ya\'maloonas saiyiaat; qaala yaa qawmi haaa\'ulaaa\'i banaatee hunna atharu lakum fattaqul laaha wa laa tukhzooni fee daifee alaisa minkum rajulur rasheed',78,'11:78',23,92,189,3,0,230,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1552,11,'قَالُوا۟ لَقَدْ عَلِمْتَ مَا لَنَا فِى بَنَاتِكَ مِنْ حَقٍّ وَإِنَّكَ لَتَعْلَمُ مَا نُرِيدُ','Qaaloo laqad \'alimta maa lanaa fee banastika min haqq, wa innaka lata\'lamu maa nureed',79,'11:79',23,92,189,3,0,230,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1553,11,'قَالَ لَوْ أَنَّ لِى بِكُمْ قُوَّةً أَوْ ءَاوِىٓ إِلَىٰ رُكْنٍ شَدِيدٍ','Qaala law anna lee bikum quwwatan aw aaweee ilaa ruknin shadeed',80,'11:80',23,92,189,3,0,230,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1554,11,'قَالُوا۟ يَـٰلُوطُ إِنَّا رُسُلُ رَبِّكَ لَن يَصِلُوٓا۟ إِلَيْكَ ۖ فَأَسْرِ بِأَهْلِكَ بِقِطْعٍ مِّنَ ٱلَّيْلِ وَلَا يَلْتَفِتْ مِنكُمْ أَحَدٌ إِلَّا ٱمْرَأَتَكَ ۖ إِنَّهُۥ مُصِيبُهَا مَآ أَصَابَهُمْ ۚ إِنَّ مَوْعِدَهُمُ ٱلصُّبْحُ ۚ أَلَيْسَ ٱلصُّبْحُ بِقَرِيبٍ','Qaaloo yaa Lootu innaa Rusulu Rabbika lai yasiloo ilaika fa asri bi ahlika biqit \'im minal laili wa laa yaltafit minkum ahadun illam ra ataka innahoo museebuhaa maaa asaabahum; inna maw\'i dahumus subh; alaisas subhu biqareeb',81,'11:81',23,92,189,3,0,230,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1555,11,'فَلَمَّا جَآءَ أَمْرُنَا جَعَلْنَا عَـٰلِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ مَّنضُودٍ','Falammaa jaaa\'a amrunaa ja\'alnaa \'aaliyahaa saafilahaa wa amtamaa \'alaihaa hijaaratam min sijjeelim mandood',82,'11:82',23,92,189,3,0,231,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1556,11,'مُّسَوَّمَةً عِندَ رَبِّكَ ۖ وَمَا هِىَ مِنَ ٱلظَّـٰلِمِينَ بِبَعِيدٍ','Musawwamatan \'inda Rabbik; wa maa hiya minaz zaalimena biba\'eed',83,'11:83',23,92,189,3,0,231,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1557,11,'۞ وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًا ۚ قَالَ يَـٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَـٰهٍ غَيْرُهُۥ ۖ وَلَا تَنقُصُوا۟ ٱلْمِكْيَالَ وَٱلْمِيزَانَ ۚ إِنِّىٓ أَرَىٰكُم بِخَيْرٍ وَإِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ مُّحِيطٍ','Wa ilaa Madyana akhaahum Shu\'aibaa; qaala yaa qawmi\' budul laaha maa lakum min ilaahin ghairuhoo wa laa tanqusul mikyaala walmeezaan; inneee araakum bikhairinw wa innee akhaafu \'alaikum \'azaaba Yawmim muheet',84,'11:84',24,93,190,3,0,231,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1558,11,'وَيَـٰقَوْمِ أَوْفُوا۟ ٱلْمِكْيَالَ وَٱلْمِيزَانَ بِٱلْقِسْطِ ۖ وَلَا تَبْخَسُوا۟ ٱلنَّاسَ أَشْيَآءَهُمْ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ','Wa yaa qawmi awful mikyaala walmeezaana bilqisti wa laa tabkhasun naasa ashyaaa\'ahum wa laa ta\'saw fil ardi mufsideen',85,'11:85',24,93,190,3,0,231,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1559,11,'بَقِيَّتُ ٱللَّهِ خَيْرٌ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ ۚ وَمَآ أَنَا۠ عَلَيْكُم بِحَفِيظٍ','Baqiyyatul laahi khairul lakum in kuntum mu\'mineen; wa maa ana \'alaikum bihafeez',86,'11:86',24,93,190,3,0,231,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1560,11,'قَالُوا۟ يَـٰشُعَيْبُ أَصَلَوٰتُكَ تَأْمُرُكَ أَن نَّتْرُكَ مَا يَعْبُدُ ءَابَآؤُنَآ أَوْ أَن نَّفْعَلَ فِىٓ أَمْوَٰلِنَا مَا نَشَـٰٓؤُا۟ ۖ إِنَّكَ لَأَنتَ ٱلْحَلِيمُ ٱلرَّشِيدُ','Qaaloo yaa Shu\'aybu asalaatuka taamuruka an natruka maa ya\'budu aabaaa\'unaaa aw an naf\'ala feee amwaalinaa maa nashaaa\'oo innaka la antal haleemur rasheed',87,'11:87',24,93,190,3,0,231,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1561,11,'قَالَ يَـٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَرَزَقَنِى مِنْهُ رِزْقًا حَسَنًا ۚ وَمَآ أُرِيدُ أَنْ أُخَالِفَكُمْ إِلَىٰ مَآ أَنْهَىٰكُمْ عَنْهُ ۚ إِنْ أُرِيدُ إِلَّا ٱلْإِصْلَـٰحَ مَا ٱسْتَطَعْتُ ۚ وَمَا تَوْفِيقِىٓ إِلَّا بِٱللَّهِ ۚ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ','Qaala yaa qawmi ara\'aitum in kuntu \'alaa baiyinatim mir Rabbee wa razaqanee minhu rizqan hasanaa; wa maaa ureedu an ukhaalifakum ilaa maaa anhaakum \'anh; in ureedu illal islaaha mastata\'t; wa maa tawfeeqeee illaa billaah; \'alaihi tawakkaltu wa ilaihi uneeb',88,'11:88',24,93,190,3,0,231,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1562,11,'وَيَـٰقَوْمِ لَا يَجْرِمَنَّكُمْ شِقَاقِىٓ أَن يُصِيبَكُم مِّثْلُ مَآ أَصَابَ قَوْمَ نُوحٍ أَوْ قَوْمَ هُودٍ أَوْ قَوْمَ صَـٰلِحٍ ۚ وَمَا قَوْمُ لُوطٍ مِّنكُم بِبَعِيدٍ','Wa yaa qawmi laa yajri mannakum shiqaaqeee ai yuseebakum mislu maaa asaaba qawma Noohin aw qawma Hoodin aw qawma Saalih; wa maa qawmu Lootim minkum biba\'eed',89,'11:89',24,93,190,3,0,232,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1563,11,'وَٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ ۚ إِنَّ رَبِّى رَحِيمٌ وَدُودٌ','Wastaghfiroo Rabbakum summa toobooo ilaih; inna Rabbee Raheemunw Wadood',90,'11:90',24,93,190,3,0,232,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1564,11,'قَالُوا۟ يَـٰشُعَيْبُ مَا نَفْقَهُ كَثِيرًا مِّمَّا تَقُولُ وَإِنَّا لَنَرَىٰكَ فِينَا ضَعِيفًا ۖ وَلَوْلَا رَهْطُكَ لَرَجَمْنَـٰكَ ۖ وَمَآ أَنتَ عَلَيْنَا بِعَزِيزٍ','Qaaloo yaa Shu\'aibu maa nafqahu kaseeram mimmaa taqoolu wa innaa lanaraaka feenaa da\'eefanw wa law laa rahtuka larajamnaaka wa maaa anta \'alainaa bi\'azeez',91,'11:91',24,93,190,3,0,232,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1565,11,'قَالَ يَـٰقَوْمِ أَرَهْطِىٓ أَعَزُّ عَلَيْكُم مِّنَ ٱللَّهِ وَٱتَّخَذْتُمُوهُ وَرَآءَكُمْ ظِهْرِيًّا ۖ إِنَّ رَبِّى بِمَا تَعْمَلُونَ مُحِيطٌ','Qaala yaa qawmi arahteee a\'azzu \'alaikum minal laahi wattakhaztumoohu waraaa\'akum zihriyyan inna Rabbee bimaa ta\'maloona muheet',92,'11:92',24,93,190,3,0,232,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1566,11,'وَيَـٰقَوْمِ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنِّى عَـٰمِلٌ ۖ سَوْفَ تَعْلَمُونَ مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَمَنْ هُوَ كَـٰذِبٌ ۖ وَٱرْتَقِبُوٓا۟ إِنِّى مَعَكُمْ رَقِيبٌ','Wa yaa qawmi\' maloo \'alaa makaanatikum innee \'aamilun sawfa ta\'lamoona mai yaateehi \'azaabuny yukhzeehi wa man huwa kaazib; wartaqibooo innnee ma\'akum raqeeb',93,'11:93',24,93,190,3,0,232,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1567,11,'وَلَمَّا جَآءَ أَمْرُنَا نَجَّيْنَا شُعَيْبًا وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَأَخَذَتِ ٱلَّذِينَ ظَلَمُوا۟ ٱلصَّيْحَةُ فَأَصْبَحُوا۟ فِى دِيَـٰرِهِمْ جَـٰثِمِينَ','Wa lammaa jaaa\'a amrunaa najjainaa shu\'aibanw wal lazeena aamanoo ma\'ahoo birahmatim minnaa wa akhazatil lazeena zalamus saihatu fa asbahoo fee diyaarihim jaasimeen',94,'11:94',24,93,190,3,0,232,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1568,11,'كَأَن لَّمْ يَغْنَوْا۟ فِيهَآ ۗ أَلَا بُعْدًا لِّمَدْيَنَ كَمَا بَعِدَتْ ثَمُودُ','Ka-al-lam yaghnaw feehaaa; alaa bu\'dal li Madyana Kamaa ba\'idat Samood',95,'11:95',24,93,190,3,0,232,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1569,11,'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَـٰتِنَا وَسُلْطَـٰنٍ مُّبِينٍ','Wa laqad arsalnaa Moosaa bi Aayaatinaa wa sultaanim mubeen',96,'11:96',24,93,191,3,0,232,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1570,11,'إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَٱتَّبَعُوٓا۟ أَمْرَ فِرْعَوْنَ ۖ وَمَآ أَمْرُ فِرْعَوْنَ بِرَشِيدٍ','Ilaa Fir\'awna wa mala\'ihee fattaba\'ooo amra Fir\'awna wa maaa amru Fir\'awna birasheed',97,'11:97',24,93,191,3,0,232,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1571,11,'يَقْدُمُ قَوْمَهُۥ يَوْمَ ٱلْقِيَـٰمَةِ فَأَوْرَدَهُمُ ٱلنَّارَ ۖ وَبِئْسَ ٱلْوِرْدُ ٱلْمَوْرُودُ','Yaqdumu qawmahoo Yawmal Qiyaamati fa awrada humun Naara wa bi\'sal wirdul mawrood',98,'11:98',24,93,191,3,0,233,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1572,11,'وَأُتْبِعُوا۟ فِى هَـٰذِهِۦ لَعْنَةً وَيَوْمَ ٱلْقِيَـٰمَةِ ۚ بِئْسَ ٱلرِّفْدُ ٱلْمَرْفُودُ','Wa utbi\'oo fee haazihee la\'natanw wa Yawmal Qiyaamah; bi\'sar rifdul marfood',99,'11:99',24,93,191,3,0,233,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1573,11,'ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْقُرَىٰ نَقُصُّهُۥ عَلَيْكَ ۖ مِنْهَا قَآئِمٌ وَحَصِيدٌ','Zaalika min ambaaa\'il quraa naqussuhoo \'alaika minhaa qaaa\'imunw wa haseed',100,'11:100',24,93,191,3,0,233,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1574,11,'وَمَا ظَلَمْنَـٰهُمْ وَلَـٰكِن ظَلَمُوٓا۟ أَنفُسَهُمْ ۖ فَمَآ أَغْنَتْ عَنْهُمْ ءَالِهَتُهُمُ ٱلَّتِى يَدْعُونَ مِن دُونِ ٱللَّهِ مِن شَىْءٍ لَّمَّا جَآءَ أَمْرُ رَبِّكَ ۖ وَمَا زَادُوهُمْ غَيْرَ تَتْبِيبٍ','Wa maa zalamnaahum wa laakin zalamooo anfusahum famaaa aghnat \'anhum aalihatuhumul latee yad\'oona min doonil laahi min shai\'il lammaa jaaa\'a amru Rabbika wa maa zaadoohum ghaira tatbeeb',101,'11:101',24,93,191,3,0,233,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1575,11,'وَكَذَٰلِكَ أَخْذُ رَبِّكَ إِذَآ أَخَذَ ٱلْقُرَىٰ وَهِىَ ظَـٰلِمَةٌ ۚ إِنَّ أَخْذَهُۥٓ أَلِيمٌ شَدِيدٌ','Wa kazaalika akhzu Rabbika izaaa akhazal quraa wa hiya zaalimah; inna akhzahooo aleemun shadeed',102,'11:102',24,93,191,3,0,233,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1576,11,'إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّمَنْ خَافَ عَذَابَ ٱلْـَٔاخِرَةِ ۚ ذَٰلِكَ يَوْمٌ مَّجْمُوعٌ لَّهُ ٱلنَّاسُ وَذَٰلِكَ يَوْمٌ مَّشْهُودٌ','Inna fee zaalika la aayatal liman khaafa \'azaabal Aakhirah; zaalika Yawmum majmoo\'ul lahun naasu wa zaalika Yawmum mashhood',103,'11:103',24,93,191,3,0,233,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1577,11,'وَمَا نُؤَخِّرُهُۥٓ إِلَّا لِأَجَلٍ مَّعْدُودٍ','Wa maa nu\'akhkhiruhooo illaa li ajalim ma\'dood',104,'11:104',24,93,191,3,0,233,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1578,11,'يَوْمَ يَأْتِ لَا تَكَلَّمُ نَفْسٌ إِلَّا بِإِذْنِهِۦ ۚ فَمِنْهُمْ شَقِىٌّ وَسَعِيدٌ','Yawma yaati laa takallamu nafsun illaa bi iznih; faminhum shaqiyyunw wa sa\'eed',105,'11:105',24,93,191,3,0,233,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1579,11,'فَأَمَّا ٱلَّذِينَ شَقُوا۟ فَفِى ٱلنَّارِ لَهُمْ فِيهَا زَفِيرٌ وَشَهِيقٌ','Fa ammal lazeena shaqoo fafin Naari lahum feehaa zafeerunw wa shaheeq',106,'11:106',24,93,191,3,0,233,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1580,11,'خَـٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَـٰوَٰتُ وَٱلْأَرْضُ إِلَّا مَا شَآءَ رَبُّكَ ۚ إِنَّ رَبَّكَ فَعَّالٌ لِّمَا يُرِيدُ','Khaalideena feehaa maa daamatis samaawaatu wal ardu illaa maa shaaa\'a Rabbuk; inna Rabbaka fa\' \'aalul limaa yureed',107,'11:107',24,93,191,3,0,233,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1581,11,'۞ وَأَمَّا ٱلَّذِينَ سُعِدُوا۟ فَفِى ٱلْجَنَّةِ خَـٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَـٰوَٰتُ وَٱلْأَرْضُ إِلَّا مَا شَآءَ رَبُّكَ ۖ عَطَآءً غَيْرَ مَجْذُوذٍ','Wa ammal lazeena su\'idoo fafil Jannati khaalideena feehaa maa daamatis samaawaatu wal ardu illaa maa shaaa\'a Rabbuk; ataaa\'an ghaira majzooz',108,'11:108',24,94,191,3,0,233,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1582,11,'فَلَا تَكُ فِى مِرْيَةٍ مِّمَّا يَعْبُدُ هَـٰٓؤُلَآءِ ۚ مَا يَعْبُدُونَ إِلَّا كَمَا يَعْبُدُ ءَابَآؤُهُم مِّن قَبْلُ ۚ وَإِنَّا لَمُوَفُّوهُمْ نَصِيبَهُمْ غَيْرَ مَنقُوصٍ','Falaa taku fee miryatim mimmmaa ya\'budu haaa\'ulaaa\'; maa ya\'budoona illaa kamaa ya\'budu aabaaa\'uhum min qabl; wa innaa lamuwaf foohum naseebahum ghaira manqoos',109,'11:109',24,94,191,3,0,234,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1583,11,'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَـٰبَ فَٱخْتُلِفَ فِيهِ ۚ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَقُضِىَ بَيْنَهُمْ ۚ وَإِنَّهُمْ لَفِى شَكٍّ مِّنْهُ مُرِيبٍ','Wa laqad aatainaa Moosal Kitaaba fakhtulifa feeh; wa law laa Kalimatun sabaqat mir Rabbika laqudiya bainahum; wa innahum lafee shakkim minhu mureeb',110,'11:110',24,94,192,3,0,234,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1584,11,'وَإِنَّ كُلًّا لَّمَّا لَيُوَفِّيَنَّهُمْ رَبُّكَ أَعْمَـٰلَهُمْ ۚ إِنَّهُۥ بِمَا يَعْمَلُونَ خَبِيرٌ','Wa inna kullal lammaa la yuwaffiyannahum Rabbuka a\'maalahum; innahoo bimaa ya\'maloona Khabeer',111,'11:111',24,94,192,3,0,234,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1585,11,'فَٱسْتَقِمْ كَمَآ أُمِرْتَ وَمَن تَابَ مَعَكَ وَلَا تَطْغَوْا۟ ۚ إِنَّهُۥ بِمَا تَعْمَلُونَ بَصِيرٌ','Fastaqim kamaaa umirta wa man taaba ma\'aka wa laa tatghaw; innahoo bimaa ta\'maloona Baseer',112,'11:112',24,94,192,3,0,234,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1586,11,'وَلَا تَرْكَنُوٓا۟ إِلَى ٱلَّذِينَ ظَلَمُوا۟ فَتَمَسَّكُمُ ٱلنَّارُ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِنْ أَوْلِيَآءَ ثُمَّ لَا تُنصَرُونَ','Wa laa tarkanooo ilal lazeena zalamoo fatamassa kumun Naaru wa maa lakum min doonil laahi min awliyaaa\'a summa laa tunsaroon',113,'11:113',24,94,192,3,0,234,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1587,11,'وَأَقِمِ ٱلصَّلَوٰةَ طَرَفَىِ ٱلنَّهَارِ وَزُلَفًا مِّنَ ٱلَّيْلِ ۚ إِنَّ ٱلْحَسَنَـٰتِ يُذْهِبْنَ ٱلسَّيِّـَٔاتِ ۚ ذَٰلِكَ ذِكْرَىٰ لِلذَّٰكِرِينَ','Wa aqimis Salaata tarafayin nahaari wa zulafam minal layl; innal hasanaati yuzhibnas saiyi aat; zaalika zikraa liz zaakireen',114,'11:114',24,94,192,3,0,234,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1588,11,'وَٱصْبِرْ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ','Wasbir fa innal laaha laa yudee\'u ajral muhsineen',115,'11:115',24,94,192,3,0,234,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1589,11,'فَلَوْلَا كَانَ مِنَ ٱلْقُرُونِ مِن قَبْلِكُمْ أُو۟لُوا۟ بَقِيَّةٍ يَنْهَوْنَ عَنِ ٱلْفَسَادِ فِى ٱلْأَرْضِ إِلَّا قَلِيلًا مِّمَّنْ أَنجَيْنَا مِنْهُمْ ۗ وَٱتَّبَعَ ٱلَّذِينَ ظَلَمُوا۟ مَآ أُتْرِفُوا۟ فِيهِ وَكَانُوا۟ مُجْرِمِينَ','Falw laa kaana minal qurooni min qablikum ooloo baqiyyatiny yanhawna \'anil fasaadi fil ardi illaa qaleelam mimman anjainaa minhum; wattaba\'al lazeena zalamoo maaa utrifoo feehi wa kaanoo mujrimeen',116,'11:116',24,94,192,3,0,234,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1590,11,'وَمَا كَانَ رَبُّكَ لِيُهْلِكَ ٱلْقُرَىٰ بِظُلْمٍ وَأَهْلُهَا مُصْلِحُونَ','Wa maa kaana Rabbuka liyuhlikal quraa bizulminw wa ahluhaa muslihoon',117,'11:117',24,94,192,3,0,234,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1591,11,'وَلَوْ شَآءَ رَبُّكَ لَجَعَلَ ٱلنَّاسَ أُمَّةً وَٰحِدَةً ۖ وَلَا يَزَالُونَ مُخْتَلِفِينَ','Wa law shaaa\'a Rabbuka laja\'alannnaasa ummatanw waa hidatanw wa laa yazaaloona mukhtalifeen',118,'11:118',24,94,192,3,0,235,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1592,11,'إِلَّا مَن رَّحِمَ رَبُّكَ ۚ وَلِذَٰلِكَ خَلَقَهُمْ ۗ وَتَمَّتْ كَلِمَةُ رَبِّكَ لَأَمْلَأَنَّ جَهَنَّمَ مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ أَجْمَعِينَ','Illaa mar rahima Rabbuk; wa lizaalika khalaqahum; wa tammat Kalimatu Rabbika la amla\'ana Jahannama minal jinnati wannnaasi ajma\'een',119,'11:119',24,94,192,3,0,235,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1593,11,'وَكُلًّا نَّقُصُّ عَلَيْكَ مِنْ أَنۢبَآءِ ٱلرُّسُلِ مَا نُثَبِّتُ بِهِۦ فُؤَادَكَ ۚ وَجَآءَكَ فِى هَـٰذِهِ ٱلْحَقُّ وَمَوْعِظَةٌ وَذِكْرَىٰ لِلْمُؤْمِنِينَ','Wa kullan naqussu \'alaika min ambaaa\'ir Rusuli maa nusabbitu bihee fu\'aadak; wa jaaa\'aka fee haazihil haqqu wa maw\'izatunw wa zikraa lilmu\' mineen',120,'11:120',24,94,192,3,0,235,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1594,11,'وَقُل لِّلَّذِينَ لَا يُؤْمِنُونَ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنَّا عَـٰمِلُونَ','Wa qul lillazeena laa yu\'minoona\' maloo \'alaa makaanatikum innaa \'aamiloon',121,'11:121',24,94,192,3,0,235,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1595,11,'وَٱنتَظِرُوٓا۟ إِنَّا مُنتَظِرُونَ','Wantaziroo innaa mun taziroon',122,'11:122',24,94,192,3,0,235,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1596,11,'وَلِلَّهِ غَيْبُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَإِلَيْهِ يُرْجَعُ ٱلْأَمْرُ كُلُّهُۥ فَٱعْبُدْهُ وَتَوَكَّلْ عَلَيْهِ ۚ وَمَا رَبُّكَ بِغَـٰفِلٍ عَمَّا تَعْمَلُونَ','Wa lillaahi ghaibus samaawaati wal ardi wa ilaihi yurja\'ul amru kulluhoo fa\'bu-dhu wa tawakkal \'alaih; wa maa Rabbuka bighaafilin \'ammaa ta\'maloon',123,'11:123',24,94,192,3,0,235,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1597,12,'الٓر ۚ تِلْكَ ءَايَـٰتُ ٱلْكِتَـٰبِ ٱلْمُبِينِ','Alif-Laaam-Raa; tilka Aayaatul Kitaabil Mubeen',1,'12:1',24,94,193,3,0,235,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1598,12,'إِنَّآ أَنزَلْنَـٰهُ قُرْءَٰنًا عَرَبِيًّا لَّعَلَّكُمْ تَعْقِلُونَ','Innaaa anzalnaahu quraanan \'Arabiyyal la \'allakum ta\'qiloon',2,'12:2',24,94,193,3,0,235,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1599,12,'نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ ٱلْقَصَصِ بِمَآ أَوْحَيْنَآ إِلَيْكَ هَـٰذَا ٱلْقُرْءَانَ وَإِن كُنتَ مِن قَبْلِهِۦ لَمِنَ ٱلْغَـٰفِلِينَ','Nahnu naqussu \'alaika ahsanal qasasi bimaaa awhainaaa ilaika haazal quraana wa in kunta min qablihee laminal ghaafileen',3,'12:3',24,94,193,3,0,235,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1600,12,'إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَـٰٓأَبَتِ إِنِّى رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا وَٱلشَّمْسَ وَٱلْقَمَرَ رَأَيْتُهُمْ لِى سَـٰجِدِينَ','Iz qaala Yoosufu li abeehi yaaa abati innee ra aytu ahada \'ashara kawkabanw wash shamsa walqamara ra aytuhum lee saajideen',4,'12:4',24,94,193,3,0,235,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1601,12,'قَالَ يَـٰبُنَىَّ لَا تَقْصُصْ رُءْيَاكَ عَلَىٰٓ إِخْوَتِكَ فَيَكِيدُوا۟ لَكَ كَيْدًا ۖ إِنَّ ٱلشَّيْطَـٰنَ لِلْإِنسَـٰنِ عَدُوٌّ مُّبِينٌ','Qaala yaa bunaiya laa taqsus ru\'yaaka \'alaaa ikhwatika fayakeedoo laka kaidaa; innash Shaitaana lil insaani \'aduwwum mubeen',5,'12:5',24,94,193,3,0,236,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1602,12,'وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِن تَأْوِيلِ ٱلْأَحَادِيثِ وَيُتِمُّ نِعْمَتَهُۥ عَلَيْكَ وَعَلَىٰٓ ءَالِ يَعْقُوبَ كَمَآ أَتَمَّهَا عَلَىٰٓ أَبَوَيْكَ مِن قَبْلُ إِبْرَٰهِيمَ وَإِسْحَـٰقَ ۚ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ','Wa kazaalika yajtabeeka rabbuka wa yu\'allimuka min taaweelil ahaadeesi wa yutimmu ni\'matahoo \'alaika wa \'alaaa Aali Ya\'qooba kamaaa atammahaa \'alaaa abawaika min qablu Ibraaheema wa Ishaaq; inna Rabbaka \'Aleemun hakeem',6,'12:6',24,94,193,3,0,236,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1603,12,'۞ لَّقَدْ كَانَ فِى يُوسُفَ وَإِخْوَتِهِۦٓ ءَايَـٰتٌ لِّلسَّآئِلِينَ','Laqad kaana fee Yoosufa wa ikhwatiheee Aayaatul lissaaa\'ileen',7,'12:7',24,95,194,3,0,236,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1604,12,'إِذْ قَالُوا۟ لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰٓ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ إِنَّ أَبَانَا لَفِى ضَلَـٰلٍ مُّبِينٍ','Iz qaaloo la Yoosufu wa akhoohu ahabbu ilaaa Abeenaa minnaa wa nahnu \'usbah; inna abaanaa lafee dalaalim mubeen',8,'12:8',24,95,194,3,0,236,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1605,12,'ٱقْتُلُوا۟ يُوسُفَ أَوِ ٱطْرَحُوهُ أَرْضًا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا۟ مِنۢ بَعْدِهِۦ قَوْمًا صَـٰلِحِينَ','Uqtuloo Yoosufa awitra hoohu ardany yakhlu lakum wajhu abeekum wa takoonoo mim ba\'dihee qawman saaliheen',9,'12:9',24,95,194,3,0,236,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1606,12,'قَالَ قَآئِلٌ مِّنْهُمْ لَا تَقْتُلُوا۟ يُوسُفَ وَأَلْقُوهُ فِى غَيَـٰبَتِ ٱلْجُبِّ يَلْتَقِطْهُ بَعْضُ ٱلسَّيَّارَةِ إِن كُنتُمْ فَـٰعِلِينَ','Qaalaa qaaa\'ilum minhum laa taqtuloo Yoosufa wa alqoohu fee ghayaabatil jubbi yaltaqithu badus sai yaarati in kuntum faa \'ileen',10,'12:10',24,95,194,3,0,236,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1607,12,'قَالُوا۟ يَـٰٓأَبَانَا مَا لَكَ لَا تَأْمَ۫نَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُۥ لَنَـٰصِحُونَ','Qaaloo yaaa abaanaa maa laka laa taamannaa \'alaa Yoosufa wa innaa lahoo lanaa sihoon',11,'12:11',24,95,194,3,0,236,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1608,12,'أَرْسِلْهُ مَعَنَا غَدًا يَرْتَعْ وَيَلْعَبْ وَإِنَّا لَهُۥ لَحَـٰفِظُونَ','Arilhu ma\'anaa ghadany yarta\'wa yal\'ab wa innaa lahoo lahaafizoon',12,'12:12',24,95,194,3,0,236,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1609,12,'قَالَ إِنِّى لَيَحْزُنُنِىٓ أَن تَذْهَبُوا۟ بِهِۦ وَأَخَافُ أَن يَأْكُلَهُ ٱلذِّئْبُ وَأَنتُمْ عَنْهُ غَـٰفِلُونَ','Qaala innee la yahzununeee an tazhaboo bihee wa akhaafu anyyaakulahuz zi\'bu wa antum \'anhu ghaafiloon',13,'12:13',24,95,194,3,0,236,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1610,12,'قَالُوا۟ لَئِنْ أَكَلَهُ ٱلذِّئْبُ وَنَحْنُ عُصْبَةٌ إِنَّآ إِذًا لَّخَـٰسِرُونَ','Qaaloo la in akalahuzzi\'bu wa nahnu \'usbatun innaaa izal lakhaasiroon',14,'12:14',24,95,194,3,0,236,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1611,12,'فَلَمَّا ذَهَبُوا۟ بِهِۦ وَأَجْمَعُوٓا۟ أَن يَجْعَلُوهُ فِى غَيَـٰبَتِ ٱلْجُبِّ ۚ وَأَوْحَيْنَآ إِلَيْهِ لَتُنَبِّئَنَّهُم بِأَمْرِهِمْ هَـٰذَا وَهُمْ لَا يَشْعُرُونَ','Falammaa zahaboo bihee wa ajma\'ooo anyyaj\'aloohu fee ghayaabatil jubb; wa awyainaaa ilaihi latunabbi \'annahum bi amrihim haaza wa hum laa yash\'uroon',15,'12:15',24,95,194,3,0,237,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1612,12,'وَجَآءُوٓ أَبَاهُمْ عِشَآءً يَبْكُونَ','Wa jaaa\'ooo abaahum \'ishaaa \'any yabkoon',16,'12:16',24,95,194,3,0,237,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1613,12,'قَالُوا۟ يَـٰٓأَبَانَآ إِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِندَ مَتَـٰعِنَا فَأَكَلَهُ ٱلذِّئْبُ ۖ وَمَآ أَنتَ بِمُؤْمِنٍ لَّنَا وَلَوْ كُنَّا صَـٰدِقِينَ','Qaaloo yaaa abaanaaa innaa zahabnaa nastabiqu wa taraknaa Yoosufa \'inda mataa\'inaa fa akhalahuz zi\'b, wa maaa anta bimu\'minil lanaa wa law kunnaa saadiqeen',17,'12:17',24,95,194,3,0,237,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1614,12,'وَجَآءُو عَلَىٰ قَمِيصِهِۦ بِدَمٍ كَذِبٍ ۚ قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا ۖ فَصَبْرٌ جَمِيلٌ ۖ وَٱللَّهُ ٱلْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ','Wa jaaa\'oo \'alaa qamee shihee bidamin kazi\' qaala bal sawwalat lakum anfusukum amraa; fasabrun jameel; wallaahul musta\'aanu \'alaa man tasifoon',18,'12:18',24,95,194,3,0,237,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1615,12,'وَجَآءَتْ سَيَّارَةٌ فَأَرْسَلُوا۟ وَارِدَهُمْ فَأَدْلَىٰ دَلْوَهُۥ ۖ قَالَ يَـٰبُشْرَىٰ هَـٰذَا غُلَـٰمٌ ۚ وَأَسَرُّوهُ بِضَـٰعَةً ۚ وَٱللَّهُ عَلِيمٌۢ بِمَا يَعْمَلُونَ','Wa jaaa\'at saiyaaratun fa-arsaloo waaridahum fa adlaa dalwah; qaala yaa bushraa haaza ghulaam; wa asarroohu bi-daa\'ah; wallaahu \'aleemum bimaa ya\'maloon',19,'12:19',24,95,194,3,0,237,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1616,12,'وَشَرَوْهُ بِثَمَنٍۭ بَخْسٍ دَرَٰهِمَ مَعْدُودَةٍ وَكَانُوا۟ فِيهِ مِنَ ٱلزَّٰهِدِينَ','Wa sharawhu bisamanim bakhsin daraahima ma\'doo datinw wa kaanoo feehi minaz zaahideen',20,'12:20',24,95,194,3,0,237,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1617,12,'وَقَالَ ٱلَّذِى ٱشْتَرَىٰهُ مِن مِّصْرَ لِٱمْرَأَتِهِۦٓ أَكْرِمِى مَثْوَىٰهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوْ نَتَّخِذَهُۥ وَلَدًا ۚ وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِى ٱلْأَرْضِ وَلِنُعَلِّمَهُۥ مِن تَأْوِيلِ ٱلْأَحَادِيثِ ۚ وَٱللَّهُ غَالِبٌ عَلَىٰٓ أَمْرِهِۦ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ','Wa qaalal lazish taraahu mim Misra limra atiheee akrimee maswaahu \'asaaa any-yanfa\'anaaa aw nattakhizahoo waladaa; wa kazaalika mak-kannaa li-Yoosufa fil ardi wa linu\'allimahoo min taaweelil ahaadees; wallaahu ghaalibun \'alaaa amrihee wa laakinna aksaran naasi laa ya\'lamoon',21,'12:21',24,95,195,3,0,237,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1618,12,'وَلَمَّا بَلَغَ أَشُدَّهُۥٓ ءَاتَيْنَـٰهُ حُكْمًا وَعِلْمًا ۚ وَكَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ','Wa lammaa balagha ashuddahooo aatainaahu bukmanw wa \'ilmaa; wa kazaa lika najzil muhsineen',22,'12:22',24,95,195,3,0,237,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1619,12,'وَرَٰوَدَتْهُ ٱلَّتِى هُوَ فِى بَيْتِهَا عَن نَّفْسِهِۦ وَغَلَّقَتِ ٱلْأَبْوَٰبَ وَقَالَتْ هَيْتَ لَكَ ۚ قَالَ مَعَاذَ ٱللَّهِ ۖ إِنَّهُۥ رَبِّىٓ أَحْسَنَ مَثْوَاىَ ۖ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّـٰلِمُونَ','Wa raawadat hul latee huwa fee baitihaa \'an nafsihee wa ghallaqatil abwaaba wa qaalat haita lak; qaala ma\'aazal laahi innahoo rabbeee ahsana maswaay; innahoo laa yuflihuz-zaalimoon',23,'12:23',24,95,195,3,0,238,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1620,12,'وَلَقَدْ هَمَّتْ بِهِۦ ۖ وَهَمَّ بِهَا لَوْلَآ أَن رَّءَا بُرْهَـٰنَ رَبِّهِۦ ۚ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ ٱلسُّوٓءَ وَٱلْفَحْشَآءَ ۚ إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُخْلَصِينَ','Wa laqad hammat bihee wa hamma bihaa law laaa ar ra-aa burhaana rabbih;; kazaalika linasrifa \'anhu sooo\'a walfa hshaaa\'; innahoo min \'ibaadi nal mukhlaseen',24,'12:24',24,95,195,3,0,238,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1621,12,'وَٱسْتَبَقَا ٱلْبَابَ وَقَدَّتْ قَمِيصَهُۥ مِن دُبُرٍ وَأَلْفَيَا سَيِّدَهَا لَدَا ٱلْبَابِ ۚ قَالَتْ مَا جَزَآءُ مَنْ أَرَادَ بِأَهْلِكَ سُوٓءًا إِلَّآ أَن يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌ','Wastabaqal baaba wa qaddat qameesahoo min dubu rinw wa alfayaa saiyidahaa ladal baab; qaalat maa jazaaa\'u man araada bi ahlika sooo\'an illaaa any-yusjana aw azaabun aleem',25,'12:25',24,95,195,3,0,238,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1622,12,'قَالَ هِىَ رَٰوَدَتْنِى عَن نَّفْسِى ۚ وَشَهِدَ شَاهِدٌ مِّنْ أَهْلِهَآ إِن كَانَ قَمِيصُهُۥ قُدَّ مِن قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ ٱلْكَـٰذِبِينَ','Qaala hiya raawadatnee \'an nafsee wa shahida shaahidum min ahlihaa in kaana qameesuhoo qudda min qubulin fasadaqat wa huwa minal kaazibeen',26,'12:26',24,95,195,3,0,238,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1623,12,'وَإِن كَانَ قَمِيصُهُۥ قُدَّ مِن دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ ٱلصَّـٰدِقِينَ','Wa in kaana qameesuhoo qudda min duburin fakazabat wa huwa minas saadiqeen',27,'12:27',24,95,195,3,0,238,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1624,12,'فَلَمَّا رَءَا قَمِيصَهُۥ قُدَّ مِن دُبُرٍ قَالَ إِنَّهُۥ مِن كَيْدِكُنَّ ۖ إِنَّ كَيْدَكُنَّ عَظِيمٌ','Falammaa ra-aa qamee sahoo qudda min duburin qaala innahoo min kaidikunna inna kaidakunna \'azeem',28,'12:28',24,95,195,3,0,238,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1625,12,'يُوسُفُ أَعْرِضْ عَنْ هَـٰذَا ۚ وَٱسْتَغْفِرِى لِذَنۢبِكِ ۖ إِنَّكِ كُنتِ مِنَ ٱلْخَاطِـِٔينَ','Yoosofu a\'rid \'an haaza wastaghfiree lizambiki innaki kunti minal khaati\'een',29,'12:29',24,95,195,3,0,238,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1626,12,'۞ وَقَالَ نِسْوَةٌ فِى ٱلْمَدِينَةِ ٱمْرَأَتُ ٱلْعَزِيزِ تُرَٰوِدُ فَتَىٰهَا عَن نَّفْسِهِۦ ۖ قَدْ شَغَفَهَا حُبًّا ۖ إِنَّا لَنَرَىٰهَا فِى ضَلَـٰلٍ مُّبِينٍ','Wa qaala niswatun filma deenatim ra atul\'Azeezi turaawidu fataahaa \'an nafsihee qad shaghafahaa bubbaa; innaa lana raahaa fee dalaalim mubeen',30,'12:30',24,96,196,3,0,238,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1627,12,'فَلَمَّا سَمِعَتْ بِمَكْرِهِنَّ أَرْسَلَتْ إِلَيْهِنَّ وَأَعْتَدَتْ لَهُنَّ مُتَّكَـًٔا وَءَاتَتْ كُلَّ وَٰحِدَةٍ مِّنْهُنَّ سِكِّينًا وَقَالَتِ ٱخْرُجْ عَلَيْهِنَّ ۖ فَلَمَّا رَأَيْنَهُۥٓ أَكْبَرْنَهُۥ وَقَطَّعْنَ أَيْدِيَهُنَّ وَقُلْنَ حَـٰشَ لِلَّهِ مَا هَـٰذَا بَشَرًا إِنْ هَـٰذَآ إِلَّا مَلَكٌ كَرِيمٌ','Falammaa sami\'at bimak rihinna arsalat ilaihinna wa a\'tadat lahunna muttaka anw wa aatat kulla waahidatim min hunna sikkeenanw wa qaala tikh ruj \'alaihinna falammaa ra aynahooo akbarnahoo wa qatta\'na aydiyahunna wa qulna haasha lillaahi maa haaza basharaa; in haazaaa illaa malakun kareem',31,'12:31',24,96,196,3,0,239,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1628,12,'قَالَتْ فَذَٰلِكُنَّ ٱلَّذِى لُمْتُنَّنِى فِيهِ ۖ وَلَقَدْ رَٰوَدتُّهُۥ عَن نَّفْسِهِۦ فَٱسْتَعْصَمَ ۖ وَلَئِن لَّمْ يَفْعَلْ مَآ ءَامُرُهُۥ لَيُسْجَنَنَّ وَلَيَكُونًا مِّنَ ٱلصَّـٰغِرِينَ','Qaalat fazaalikunnal lazee lumtunnanee feeh; wa laqad raawattuhoo \'an nafsihee fasta\'sam; wa la\'il lam yaf\'al maaa aamuruhoo la yusjananna wa la yakoonam minas saaghireen',32,'12:32',24,96,196,3,0,239,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1629,12,'قَالَ رَبِّ ٱلسِّجْنُ أَحَبُّ إِلَىَّ مِمَّا يَدْعُونَنِىٓ إِلَيْهِ ۖ وَإِلَّا تَصْرِفْ عَنِّى كَيْدَهُنَّ أَصْبُ إِلَيْهِنَّ وَأَكُن مِّنَ ٱلْجَـٰهِلِينَ','Qaala rabbis sijnu ahabbu ilaiya mimma yad\'oo naneee \'ilaihi wa illaa tasrif \'annee kaidahunna asbu ilaihinna wa akum minal jaahileen',33,'12:33',24,96,196,3,0,239,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1630,12,'فَٱسْتَجَابَ لَهُۥ رَبُّهُۥ فَصَرَفَ عَنْهُ كَيْدَهُنَّ ۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ','Fastajaaba lahoo rabbuhoo fasarafa \'anhu kaidahunn; innahoo Huswas_Samee\'ul \'Aleem',34,'12:34',24,96,196,3,0,239,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1631,12,'ثُمَّ بَدَا لَهُم مِّنۢ بَعْدِ مَا رَأَوُا۟ ٱلْـَٔايَـٰتِ لَيَسْجُنُنَّهُۥ حَتَّىٰ حِينٍ','Summa badaa lahum mim ba\'di maa ra-awul Aayaati layasjununnahoo hatta heen',35,'12:35',24,96,196,3,0,239,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1632,12,'وَدَخَلَ مَعَهُ ٱلسِّجْنَ فَتَيَانِ ۖ قَالَ أَحَدُهُمَآ إِنِّىٓ أَرَىٰنِىٓ أَعْصِرُ خَمْرًا ۖ وَقَالَ ٱلْـَٔاخَرُ إِنِّىٓ أَرَىٰنِىٓ أَحْمِلُ فَوْقَ رَأْسِى خُبْزًا تَأْكُلُ ٱلطَّيْرُ مِنْهُ ۖ نَبِّئْنَا بِتَأْوِيلِهِۦٓ ۖ إِنَّا نَرَىٰكَ مِنَ ٱلْمُحْسِنِينَ','Wa dakhala ma\'ahussijna fata yaan; qaala ahaduhumaaa inneee araaneee a\'siru khamranw wa qaalal aakharu inneee khubzan taakulut tairu minh; nabbi \'naa bitaaweelihee innaa naraaka minal muhsineen',36,'12:36',24,96,197,3,0,239,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1633,12,'قَالَ لَا يَأْتِيكُمَا طَعَامٌ تُرْزَقَانِهِۦٓ إِلَّا نَبَّأْتُكُمَا بِتَأْوِيلِهِۦ قَبْلَ أَن يَأْتِيَكُمَا ۚ ذَٰلِكُمَا مِمَّا عَلَّمَنِى رَبِّىٓ ۚ إِنِّى تَرَكْتُ مِلَّةَ قَوْمٍ لَّا يُؤْمِنُونَ بِٱللَّهِ وَهُم بِٱلْـَٔاخِرَةِ هُمْ كَـٰفِرُونَ','Qaala laa yaateekumaa ta\'aamun turzaqaaniheee illaa nabbaatukumaa bitaaweelihee qabla any yaatiyakumaa; zaali kumaa mimmaa \'allamanee rabbee; innee taraktu millata qawmil laa yu\'minoona billaahi wahum bil aakhirati hum kaafiroon',37,'12:37',24,96,197,3,0,239,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1634,12,'وَٱتَّبَعْتُ مِلَّةَ ءَابَآءِىٓ إِبْرَٰهِيمَ وَإِسْحَـٰقَ وَيَعْقُوبَ ۚ مَا كَانَ لَنَآ أَن نُّشْرِكَ بِٱللَّهِ مِن شَىْءٍ ۚ ذَٰلِكَ مِن فَضْلِ ٱللَّهِ عَلَيْنَا وَعَلَى ٱلنَّاسِ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَشْكُرُونَ','Wattab\'tu millata aabaaa\'eee Ibraaheema wa Ishaaqa wa Ya\'qoob; maa kaana lanaaa an nushrika billaahi min shai\' zaalikamin fadlil laahi \'alainaa wa \'alan naasi wa laakinna aksaran naasi laa yashkuroon',38,'12:38',24,96,197,3,0,240,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1635,12,'يَـٰصَـٰحِبَىِ ٱلسِّجْنِ ءَأَرْبَابٌ مُّتَفَرِّقُونَ خَيْرٌ أَمِ ٱللَّهُ ٱلْوَٰحِدُ ٱلْقَهَّارُ','Yaa saahibayis sijni \'a-arbaabum mutafarriqoona khayrun amil laahul waahidul qahhaar',39,'12:39',24,96,197,3,0,240,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1636,12,'مَا تَعْبُدُونَ مِن دُونِهِۦٓ إِلَّآ أَسْمَآءً سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلْطَـٰنٍ ۚ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ ۚ أَمَرَ أَلَّا تَعْبُدُوٓا۟ إِلَّآ إِيَّاهُ ۚ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ','Maa ta\'budoona min doonihee illaaa asmaaa\'an sam maitumoohaaa antum wa aabaaa\'ukum maaa anzalal laahu bihaa min sultan; inilhukmu illaa lillaah; amara allaa ta\'budooo illaaa iyyaah; zaalikad deenul qaiyimu wa laakinna aksaran naasi laa ya\'lamoon',40,'12:40',24,96,197,3,0,240,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1637,12,'يَـٰصَـٰحِبَىِ ٱلسِّجْنِ أَمَّآ أَحَدُكُمَا فَيَسْقِى رَبَّهُۥ خَمْرًا ۖ وَأَمَّا ٱلْـَٔاخَرُ فَيُصْلَبُ فَتَأْكُلُ ٱلطَّيْرُ مِن رَّأْسِهِۦ ۚ قُضِىَ ٱلْأَمْرُ ٱلَّذِى فِيهِ تَسْتَفْتِيَانِ','Yaa saahibayis sijni ammaaa ahadukumaa fa yasqee rabbahoo khamranw wa ammal aakharu fa yuslabu fataakulut tairu mir raasih; qudiyal amrul lazee feehi tastaftiyaan',41,'12:41',24,96,197,3,0,240,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1638,12,'وَقَالَ لِلَّذِى ظَنَّ أَنَّهُۥ نَاجٍ مِّنْهُمَا ٱذْكُرْنِى عِندَ رَبِّكَ فَأَنسَىٰهُ ٱلشَّيْطَـٰنُ ذِكْرَ رَبِّهِۦ فَلَبِثَ فِى ٱلسِّجْنِ بِضْعَ سِنِينَ','Wa qaala lillazee zanna annahoo najim minhumaz kurnee \'inda rabbika fa-ansaahush Shaitaanu zikra Rabbihee falabisa fis sijni bad\'a sineen',42,'12:42',24,96,197,3,0,240,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1639,12,'وَقَالَ ٱلْمَلِكُ إِنِّىٓ أَرَىٰ سَبْعَ بَقَرَٰتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعَ سُنۢبُلَـٰتٍ خُضْرٍ وَأُخَرَ يَابِسَـٰتٍ ۖ يَـٰٓأَيُّهَا ٱلْمَلَأُ أَفْتُونِى فِى رُءْيَـٰىَ إِن كُنتُمْ لِلرُّءْيَا تَعْبُرُونَ','Wa qaalal maliku inneee araa sab\'a baqaraatin simaaniny yaakuluhunna sab\'un \'ijaafunw wa sab\'a sumbulaatinkhudrinw wa ukhara yaabisaat; yaaa ayuhal mala-u aftoonee fee nu\'yaaya in kuntum lirru\'yaa ta\'buroon',43,'12:43',24,96,198,3,0,240,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1640,12,'قَالُوٓا۟ أَضْغَـٰثُ أَحْلَـٰمٍ ۖ وَمَا نَحْنُ بِتَأْوِيلِ ٱلْأَحْلَـٰمِ بِعَـٰلِمِينَ','Qaalooo adghaasu ahlaa minw wa maa nahnu bitaaweelil ahlaami bi\'aalimeen',44,'12:44',24,96,198,3,0,241,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1641,12,'وَقَالَ ٱلَّذِى نَجَا مِنْهُمَا وَٱدَّكَرَ بَعْدَ أُمَّةٍ أَنَا۠ أُنَبِّئُكُم بِتَأْوِيلِهِۦ فَأَرْسِلُونِ','Wa qaalal lazee najaa minhumaa waddakara ba\'da ummatin ana unabbi\'ukum bitalweelihee fa-arsiloon',45,'12:45',24,96,198,3,0,241,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1642,12,'يُوسُفُ أَيُّهَا ٱلصِّدِّيقُ أَفْتِنَا فِى سَبْعِ بَقَرَٰتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعِ سُنۢبُلَـٰتٍ خُضْرٍ وَأُخَرَ يَابِسَـٰتٍ لَّعَلِّىٓ أَرْجِعُ إِلَى ٱلنَّاسِ لَعَلَّهُمْ يَعْلَمُونَ','Yoosufu ayyuhas siddee qu aftinaa fee sab\'i baqaraatin simaaniny yaakuluhunna sab\'un \'ijaafunw wa sabi\'i sumbulaatin khudrinw wa ukhara yaabisaatil la\'alleee arj\'u ilan naasi la\'allahum ya\'lamoon',46,'12:46',24,96,198,3,0,241,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1643,12,'قَالَ تَزْرَعُونَ سَبْعَ سِنِينَ دَأَبًا فَمَا حَصَدتُّمْ فَذَرُوهُ فِى سُنۢبُلِهِۦٓ إِلَّا قَلِيلًا مِّمَّا تَأْكُلُونَ','Qaala tazra\'oona sab\'a sineena da aban famaa basattum fazaroohu fee sumbu liheee illaa qaleelam mimmaa taakuloon',47,'12:47',24,96,198,3,0,241,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1644,12,'ثُمَّ يَأْتِى مِنۢ بَعْدِ ذَٰلِكَ سَبْعٌ شِدَادٌ يَأْكُلْنَ مَا قَدَّمْتُمْ لَهُنَّ إِلَّا قَلِيلًا مِّمَّا تُحْصِنُونَ','Summa yaatee mim ba\'di zaalika sab\'un shidaaduny yaa kulna maa qaddamtum lahunna illaa qaleelam mimma tuhsinoon',48,'12:48',24,96,198,3,0,241,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1645,12,'ثُمَّ يَأْتِى مِنۢ بَعْدِ ذَٰلِكَ عَامٌ فِيهِ يُغَاثُ ٱلنَّاسُ وَفِيهِ يَعْصِرُونَ','Summa yadtee mim ba\'di zaalika \'aamun feehi yughaa sun naasu wa feehi ya\'siroon',49,'12:49',24,96,198,3,0,241,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1646,12,'وَقَالَ ٱلْمَلِكُ ٱئْتُونِى بِهِۦ ۖ فَلَمَّا جَآءَهُ ٱلرَّسُولُ قَالَ ٱرْجِعْ إِلَىٰ رَبِّكَ فَسْـَٔلْهُ مَا بَالُ ٱلنِّسْوَةِ ٱلَّـٰتِى قَطَّعْنَ أَيْدِيَهُنَّ ۚ إِنَّ رَبِّى بِكَيْدِهِنَّ عَلِيمٌ','Wa qaalal maliku\'toonee bihee falammaa jaaa\'ahur rasoolu qaalar-ji ilaa rabbika fas\'alhu maa baalun niswatil laatee qatta\'na aydiyahunn; inna Rabbee bikaidihinna \'Aleem',50,'12:50',24,96,199,3,0,241,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1647,12,'قَالَ مَا خَطْبُكُنَّ إِذْ رَٰوَدتُّنَّ يُوسُفَ عَن نَّفْسِهِۦ ۚ قُلْنَ حَـٰشَ لِلَّهِ مَا عَلِمْنَا عَلَيْهِ مِن سُوٓءٍ ۚ قَالَتِ ٱمْرَأَتُ ٱلْعَزِيزِ ٱلْـَٔـٰنَ حَصْحَصَ ٱلْحَقُّ أَنَا۠ رَٰوَدتُّهُۥ عَن نَّفْسِهِۦ وَإِنَّهُۥ لَمِنَ ٱلصَّـٰدِقِينَ','Qaala maa khatbukunna iz raawattunna Yoosufa \'annafsih; qulna haasha lillaahi maa \'alimnaa \'alaihi min sooo\'; qaalatim ra atul \'Azeezil \'aana hashasal haqq, ana raawat tuhoo \'an nafsihee wa innahoo laminas saadiqeen',51,'12:51',24,96,199,3,0,241,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1648,12,'ذَٰلِكَ لِيَعْلَمَ أَنِّى لَمْ أَخُنْهُ بِٱلْغَيْبِ وَأَنَّ ٱللَّهَ لَا يَهْدِى كَيْدَ ٱلْخَآئِنِينَ','Zaalika liya\'lama annee lam akhunhu bilghaibi wa annal laaha laa yahdee kaidal khaaa\'ineen',52,'12:52',24,96,199,3,0,241,12,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1649,12,'۞ وَمَآ أُبَرِّئُ نَفْسِىٓ ۚ إِنَّ ٱلنَّفْسَ لَأَمَّارَةٌۢ بِٱلسُّوٓءِ إِلَّا مَا رَحِمَ رَبِّىٓ ۚ إِنَّ رَبِّى غَفُورٌ رَّحِيمٌ','Wa maa ubarri\'u nafsee; innan nafsa la ammaaratum bissooo\'i illaa maa rahima Rabbee; inna Rabbee Ghafoorur Raheem',53,'12:53',25,97,199,3,0,242,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1650,12,'وَقَالَ ٱلْمَلِكُ ٱئْتُونِى بِهِۦٓ أَسْتَخْلِصْهُ لِنَفْسِى ۖ فَلَمَّا كَلَّمَهُۥ قَالَ إِنَّكَ ٱلْيَوْمَ لَدَيْنَا مَكِينٌ أَمِينٌ','Wa qaalal maliku\' toonee biheee astakhlishu linafsee falammaa kallamahoo qaala innakal yawma ladainaa makeenun ameen',54,'12:54',25,97,199,3,0,242,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1651,12,'قَالَ ٱجْعَلْنِى عَلَىٰ خَزَآئِنِ ٱلْأَرْضِ ۖ إِنِّى حَفِيظٌ عَلِيمٌ','Qaalaj \'alnee \'alaa khazaaa\'inil ardi innee hafeezun \'aleem',55,'12:55',25,97,199,3,0,242,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1652,12,'وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِى ٱلْأَرْضِ يَتَبَوَّأُ مِنْهَا حَيْثُ يَشَآءُ ۚ نُصِيبُ بِرَحْمَتِنَا مَن نَّشَآءُ ۖ وَلَا نُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ','Wa kazaalika makkannaa li Yoosufa fil ardi yatabawwa\'u minhaa haisu yashaaaa\'; nuseebu birahmatinaa man nashaaa\'u wa laa nudee\'u ajral muhsineen',56,'12:56',25,97,199,3,0,242,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1653,12,'وَلَأَجْرُ ٱلْـَٔاخِرَةِ خَيْرٌ لِّلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ','Wa la ajrul Aakhirati khairul lillazeena aamanoo wa kaanoo yattaqoon',57,'12:57',25,97,199,3,0,242,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1654,12,'وَجَآءَ إِخْوَةُ يُوسُفَ فَدَخَلُوا۟ عَلَيْهِ فَعَرَفَهُمْ وَهُمْ لَهُۥ مُنكِرُونَ','Wa jaaa\'a ikhwatu Yoosufa fadakhaloo \'alaihi fa\'arafahum wa hum lahoo munkiroon',58,'12:58',25,97,200,3,0,242,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1655,12,'وَلَمَّا جَهَّزَهُم بِجَهَازِهِمْ قَالَ ٱئْتُونِى بِأَخٍ لَّكُم مِّنْ أَبِيكُمْ ۚ أَلَا تَرَوْنَ أَنِّىٓ أُوفِى ٱلْكَيْلَ وَأَنَا۠ خَيْرُ ٱلْمُنزِلِينَ','Wa lammaa jahhazahum bijahaazihim qaala\' toonee bi akhil lakum min abeekum; alaa tarawna anneee oofil kaila wa ana khairul munzileen',59,'12:59',25,97,200,3,0,242,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1656,12,'فَإِن لَّمْ تَأْتُونِى بِهِۦ فَلَا كَيْلَ لَكُمْ عِندِى وَلَا تَقْرَبُونِ','Fa il lam taatoonee bihee falaa kaila lakum \'indee wa laa taqraboon',60,'12:60',25,97,200,3,0,242,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1657,12,'قَالُوا۟ سَنُرَٰوِدُ عَنْهُ أَبَاهُ وَإِنَّا لَفَـٰعِلُونَ','Qaaloo sanuraawidu \'anhu abaahu wa innaa lafaa\'iloon',61,'12:61',25,97,200,3,0,242,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1658,12,'وَقَالَ لِفِتْيَـٰنِهِ ٱجْعَلُوا۟ بِضَـٰعَتَهُمْ فِى رِحَالِهِمْ لَعَلَّهُمْ يَعْرِفُونَهَآ إِذَا ٱنقَلَبُوٓا۟ إِلَىٰٓ أَهْلِهِمْ لَعَلَّهُمْ يَرْجِعُونَ','Wa qaala lifityaanihij \'aloo bidaa\'atahum fee rihaalihim la\'allahum ya\'rifoonahaaa izan qalabooo ilaaa ahlihim la\'allahum yarji\'oon',62,'12:62',25,97,200,3,0,242,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1659,12,'فَلَمَّا رَجَعُوٓا۟ إِلَىٰٓ أَبِيهِمْ قَالُوا۟ يَـٰٓأَبَانَا مُنِعَ مِنَّا ٱلْكَيْلُ فَأَرْسِلْ مَعَنَآ أَخَانَا نَكْتَلْ وَإِنَّا لَهُۥ لَحَـٰفِظُونَ','Falammaa raja\'ooo ilaaa abeehim qaaloo yaaa abaanaa muni\'a minnal kailu fa arsil ma\'anaaa akhaanaa naktal wa innaa lahoo lahaafizoon',63,'12:63',25,97,200,3,0,242,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1660,12,'قَالَ هَلْ ءَامَنُكُمْ عَلَيْهِ إِلَّا كَمَآ أَمِنتُكُمْ عَلَىٰٓ أَخِيهِ مِن قَبْلُ ۖ فَٱللَّهُ خَيْرٌ حَـٰفِظًا ۖ وَهُوَ أَرْحَمُ ٱلرَّٰحِمِينَ','Qaala hal aamanukum \'alihi illaa kamaa amintukum \'alaaa akheehimin qabl; fal laahu khairun haafizanw wa Huwa arhamur Raahimeen',64,'12:64',25,97,200,3,0,243,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1661,12,'وَلَمَّا فَتَحُوا۟ مَتَـٰعَهُمْ وَجَدُوا۟ بِضَـٰعَتَهُمْ رُدَّتْ إِلَيْهِمْ ۖ قَالُوا۟ يَـٰٓأَبَانَا مَا نَبْغِى ۖ هَـٰذِهِۦ بِضَـٰعَتُنَا رُدَّتْ إِلَيْنَا ۖ وَنَمِيرُ أَهْلَنَا وَنَحْفَظُ أَخَانَا وَنَزْدَادُ كَيْلَ بَعِيرٍ ۖ ذَٰلِكَ كَيْلٌ يَسِيرٌ','Wa lammaa fatahoo mataa \'ahum wajadoo bidaa\'atahum ruddat ilaihim qaaloo yaaa abaanaa maa nabghee; haazihee bida \'atunaa ruddat ilainaa wa nameeru ahlanaa wa nahfazu akhaanaa wa nazdaadu kaila ba\'eer; zaalika kailuny yaseer',65,'12:65',25,97,200,3,0,243,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1662,12,'قَالَ لَنْ أُرْسِلَهُۥ مَعَكُمْ حَتَّىٰ تُؤْتُونِ مَوْثِقًا مِّنَ ٱللَّهِ لَتَأْتُنَّنِى بِهِۦٓ إِلَّآ أَن يُحَاطَ بِكُمْ ۖ فَلَمَّآ ءَاتَوْهُ مَوْثِقَهُمْ قَالَ ٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٌ','Qaala lan ursilahoo ma\'akum hattaa tu\'tooni mawsiqam minal laahis lataa tunnanee biheee illaaa nay yuhaata bikum falammaaa aatawhu mawsiqahum qaalal laahu \'alaa maa naqoolu Wakeel',66,'12:66',25,97,200,3,0,243,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1663,12,'وَقَالَ يَـٰبَنِىَّ لَا تَدْخُلُوا۟ مِنۢ بَابٍ وَٰحِدٍ وَٱدْخُلُوا۟ مِنْ أَبْوَٰبٍ مُّتَفَرِّقَةٍ ۖ وَمَآ أُغْنِى عَنكُم مِّنَ ٱللَّهِ مِن شَىْءٍ ۖ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ ۖ عَلَيْهِ تَوَكَّلْتُ ۖ وَعَلَيْهِ فَلْيَتَوَكَّلِ ٱلْمُتَوَكِّلُونَ','Wa qaala yaa baniyya laa tadkhuloo mim baabinw waa hidinw wadkhuloo min abwaabim mutafarriqah; wa maaa ughnee \'ankum minal laahi min shai\'in; inil hukmu illaa lillaahi \'alaihi tawakkaltu wa \'alaihi fal yatawakkalil Mutawakkiloon',67,'12:67',25,97,200,3,0,243,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1664,12,'وَلَمَّا دَخَلُوا۟ مِنْ حَيْثُ أَمَرَهُمْ أَبُوهُم مَّا كَانَ يُغْنِى عَنْهُم مِّنَ ٱللَّهِ مِن شَىْءٍ إِلَّا حَاجَةً فِى نَفْسِ يَعْقُوبَ قَضَىٰهَا ۚ وَإِنَّهُۥ لَذُو عِلْمٍ لِّمَا عَلَّمْنَـٰهُ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ','Wa lammaa dakhaloo min haisu amarahum aboohum maa kaana yughnee \'anhum minal laahi min shai\'in illaa haajatan fee nafsi Ya\'qooba qadaahaa; wa innahoo lazoo \'ilmil limaa \'allamnaahu wa laakinna aksaran naasi laa ya\'lamoon',68,'12:68',25,97,200,3,0,243,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1665,12,'وَلَمَّا دَخَلُوا۟ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيْهِ أَخَاهُ ۖ قَالَ إِنِّىٓ أَنَا۠ أَخُوكَ فَلَا تَبْتَئِسْ بِمَا كَانُوا۟ يَعْمَلُونَ','Wa lammaa dakhaloo \'alaa Yoosufa aawaaa ilaihi akhaahu qaala inneee ana akhooka falaa tabta\'is bimaa kaanoo ya\'maloon',69,'12:69',25,97,201,3,0,243,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1666,12,'فَلَمَّا جَهَّزَهُم بِجَهَازِهِمْ جَعَلَ ٱلسِّقَايَةَ فِى رَحْلِ أَخِيهِ ثُمَّ أَذَّنَ مُؤَذِّنٌ أَيَّتُهَا ٱلْعِيرُ إِنَّكُمْ لَسَـٰرِقُونَ','Falammaa jahhazahum bijahaazihim ja\'alas siqaayata fee rahli akheehi summa azzana mu\'azzinun ayyatuhal\'eeru innakum lasaariqoon',70,'12:70',25,97,201,3,0,244,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1667,12,'قَالُوا۟ وَأَقْبَلُوا۟ عَلَيْهِم مَّاذَا تَفْقِدُونَ','Qaaloo wa aqbaloo \'alaihim maazaa tafqidoon',71,'12:71',25,97,201,3,0,244,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1668,12,'قَالُوا۟ نَفْقِدُ صُوَاعَ ٱلْمَلِكِ وَلِمَن جَآءَ بِهِۦ حِمْلُ بَعِيرٍ وَأَنَا۠ بِهِۦ زَعِيمٌ','Qaaloo nafqidu suwaa\'al maliki wa liman jaaa\'a bihee himlu ba\'eerinw wa ana bihee za\'eem',72,'12:72',25,97,201,3,0,244,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1669,12,'قَالُوا۟ تَٱللَّهِ لَقَدْ عَلِمْتُم مَّا جِئْنَا لِنُفْسِدَ فِى ٱلْأَرْضِ وَمَا كُنَّا سَـٰرِقِينَ','Qaaloo tallaahi laqad \'alimtum maa ji\'na linufsida fil ardi wa maa kunnaa saariqeen',73,'12:73',25,97,201,3,0,244,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1670,12,'قَالُوا۟ فَمَا جَزَٰٓؤُهُۥٓ إِن كُنتُمْ كَـٰذِبِينَ','Qaaloo famaa jazaaa\'u hooo in kuntum kaazibeen',74,'12:74',25,97,201,3,0,244,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1671,12,'قَالُوا۟ جَزَٰٓؤُهُۥ مَن وُجِدَ فِى رَحْلِهِۦ فَهُوَ جَزَٰٓؤُهُۥ ۚ كَذَٰلِكَ نَجْزِى ٱلظَّـٰلِمِينَ','Qaaloo jazaaa\'uhoo manw wujida fee rahlihee fahuwa jazaaa\'uh; kazaalika najziz zaalimeen',75,'12:75',25,97,201,3,0,244,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1672,12,'فَبَدَأَ بِأَوْعِيَتِهِمْ قَبْلَ وِعَآءِ أَخِيهِ ثُمَّ ٱسْتَخْرَجَهَا مِن وِعَآءِ أَخِيهِ ۚ كَذَٰلِكَ كِدْنَا لِيُوسُفَ ۖ مَا كَانَ لِيَأْخُذَ أَخَاهُ فِى دِينِ ٱلْمَلِكِ إِلَّآ أَن يَشَآءَ ٱللَّهُ ۚ نَرْفَعُ دَرَجَـٰتٍ مَّن نَّشَآءُ ۗ وَفَوْقَ كُلِّ ذِى عِلْمٍ عَلِيمٌ','Fabada-a bi-aw\'iyatihim qabla wi\'aaa\'i akheehi summas takhrajahaa minw wi \'aaa\'i akheeh; kazaalika kidnaa li Yoosuf; maa kaana liyaakhuza akhaahu fee deenil maliki illaaa any yashaaa\'al laah; narfa\'u darajaatim man nashaaa\'; wa fawqa kulli zee \'ilmin \'Aleem',76,'12:76',25,97,201,3,0,244,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1673,12,'۞ قَالُوٓا۟ إِن يَسْرِقْ فَقَدْ سَرَقَ أَخٌ لَّهُۥ مِن قَبْلُ ۚ فَأَسَرَّهَا يُوسُفُ فِى نَفْسِهِۦ وَلَمْ يُبْدِهَا لَهُمْ ۚ قَالَ أَنتُمْ شَرٌّ مَّكَانًا ۖ وَٱللَّهُ أَعْلَمُ بِمَا تَصِفُونَ','Qaaloo iny yasriq faqad saraqa akhul lahoo min qabl; fa asarrahaa Yoosufu fee nafsihee wa lam yubdihaa lahum; qaala antum sharrum makaananw wallaahu a\'lamu bimaa tasifoon',77,'12:77',25,98,201,3,0,244,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1674,12,'قَالُوا۟ يَـٰٓأَيُّهَا ٱلْعَزِيزُ إِنَّ لَهُۥٓ أَبًا شَيْخًا كَبِيرًا فَخُذْ أَحَدَنَا مَكَانَهُۥٓ ۖ إِنَّا نَرَىٰكَ مِنَ ٱلْمُحْسِنِينَ','Qaaloo yaaa ayyuhal \'Azeezu inna lahooo aban shaikhan kabeeran fakhuz ahadanaa makaanahoo innaa naraaka minal muhsineen',78,'12:78',25,98,201,3,0,244,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1675,12,'قَالَ مَعَاذَ ٱللَّهِ أَن نَّأْخُذَ إِلَّا مَن وَجَدْنَا مَتَـٰعَنَا عِندَهُۥٓ إِنَّآ إِذًا لَّظَـٰلِمُونَ','Qaala ma\'aazal laahi an naakhuza illaa manw wajadnaa mataa\'anaa \'indahoo innaaa izal lazaalimoon',79,'12:79',25,98,201,3,0,245,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1676,12,'فَلَمَّا ٱسْتَيْـَٔسُوا۟ مِنْهُ خَلَصُوا۟ نَجِيًّا ۖ قَالَ كَبِيرُهُمْ أَلَمْ تَعْلَمُوٓا۟ أَنَّ أَبَاكُمْ قَدْ أَخَذَ عَلَيْكُم مَّوْثِقًا مِّنَ ٱللَّهِ وَمِن قَبْلُ مَا فَرَّطتُمْ فِى يُوسُفَ ۖ فَلَنْ أَبْرَحَ ٱلْأَرْضَ حَتَّىٰ يَأْذَنَ لِىٓ أَبِىٓ أَوْ يَحْكُمَ ٱللَّهُ لِى ۖ وَهُوَ خَيْرُ ٱلْحَـٰكِمِينَ','Falammas tay\'asoo minhu khalasoo najiyyan qaala kabeeruhum alam ta\'lamoon anna abaakum qad akhaza \'alaikum mawsiqam minal laahi wa min qablu maa farrattum fee Yoosufa falan abrahal arda hattaa yaazana leee abeee aw yahkumal laahu lee wa huwa khairul lhaakimeen',80,'12:80',25,98,202,3,0,245,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1677,12,'ٱرْجِعُوٓا۟ إِلَىٰٓ أَبِيكُمْ فَقُولُوا۟ يَـٰٓأَبَانَآ إِنَّ ٱبْنَكَ سَرَقَ وَمَا شَهِدْنَآ إِلَّا بِمَا عَلِمْنَا وَمَا كُنَّا لِلْغَيْبِ حَـٰفِظِينَ','Irji\'ooo ilaaa abeekum faqooloo yaaa abaanaaa innab naka saraq; wa maa shahidnaaa illaa bimaa \'alimnaa wa maa kunnaa lilghaibi haafizeen',81,'12:81',25,98,202,3,0,245,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1678,12,'وَسْـَٔلِ ٱلْقَرْيَةَ ٱلَّتِى كُنَّا فِيهَا وَٱلْعِيرَ ٱلَّتِىٓ أَقْبَلْنَا فِيهَا ۖ وَإِنَّا لَصَـٰدِقُونَ','Was\'alil qaryatal latee kunnaa feehaa wal\'eeral lateee aqbalnaa feehaa wa innaa lasaadiqoon',82,'12:82',25,98,202,3,0,245,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1679,12,'قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا ۖ فَصَبْرٌ جَمِيلٌ ۖ عَسَى ٱللَّهُ أَن يَأْتِيَنِى بِهِمْ جَمِيعًا ۚ إِنَّهُۥ هُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ','Qaala bal sawwalat lakum anfusukum amran fasabrun jameelun \'asal laahu any yaa tiyanee bihim jamee\'aa; innahoo Huwal \'Aleemul Hakeem',83,'12:83',25,98,202,3,0,245,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1680,12,'وَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَـٰٓأَسَفَىٰ عَلَىٰ يُوسُفَ وَٱبْيَضَّتْ عَيْنَاهُ مِنَ ٱلْحُزْنِ فَهُوَ كَظِيمٌ','Wa tawallaa \'anhum wa qaala yaaa asafaa \'alaa Yoosufa wabyaddat \'aynaahu minal huzni fahuwa kazeem',84,'12:84',25,98,202,3,0,245,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1681,12,'قَالُوا۟ تَٱللَّهِ تَفْتَؤُا۟ تَذْكُرُ يُوسُفَ حَتَّىٰ تَكُونَ حَرَضًا أَوْ تَكُونَ مِنَ ٱلْهَـٰلِكِينَ','Qaaloo tallaahi tafta\'u tazkuru Yoosufa hattaa takoona haradan aw takoona minal haalikeen',85,'12:85',25,98,202,3,0,245,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1682,12,'قَالَ إِنَّمَآ أَشْكُوا۟ بَثِّى وَحُزْنِىٓ إِلَى ٱللَّهِ وَأَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ','Qaala innamaaa ashkoo bassee wa huzneee ilal laahi wa a\'lamu minal laahi maa laa ta\'lamoon',86,'12:86',25,98,202,3,0,245,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1683,12,'يَـٰبَنِىَّ ٱذْهَبُوا۟ فَتَحَسَّسُوا۟ مِن يُوسُفَ وَأَخِيهِ وَلَا تَا۟يْـَٔسُوا۟ مِن رَّوْحِ ٱللَّهِ ۖ إِنَّهُۥ لَا يَا۟يْـَٔسُ مِن رَّوْحِ ٱللَّهِ إِلَّا ٱلْقَوْمُ ٱلْكَـٰفِرُونَ','Yaa baniyyaz haboo fatahassasoo miny Yoosufa wa akheehi wa laa tai\'asoo mir rawhil laahi innahoo laa yai\'asu mir rawhil laahi illal qawmul kaafiroon',87,'12:87',25,98,202,3,0,246,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1684,12,'فَلَمَّا دَخَلُوا۟ عَلَيْهِ قَالُوا۟ يَـٰٓأَيُّهَا ٱلْعَزِيزُ مَسَّنَا وَأَهْلَنَا ٱلضُّرُّ وَجِئْنَا بِبِضَـٰعَةٍ مُّزْجَىٰةٍ فَأَوْفِ لَنَا ٱلْكَيْلَ وَتَصَدَّقْ عَلَيْنَآ ۖ إِنَّ ٱللَّهَ يَجْزِى ٱلْمُتَصَدِّقِينَ','Falammaa dakhaloo \'alaihi qaaloo yaaa ayyuhal \'Azeezu massanaa wa ahlanad durru wa ji\'naa bibidaa \'timmuzjaatin fa awfi lanal kaila wa tasaddaq \'alainaa innal laaha yajzil mutasaddiqeen',88,'12:88',25,98,202,3,0,246,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1685,12,'قَالَ هَلْ عَلِمْتُم مَّا فَعَلْتُم بِيُوسُفَ وَأَخِيهِ إِذْ أَنتُمْ جَـٰهِلُونَ','Qaala hal \'alimtum maa fa\'altum bi Yoosufa wa akheehi iz antum jaahiloon',89,'12:89',25,98,202,3,0,246,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1686,12,'قَالُوٓا۟ أَءِنَّكَ لَأَنتَ يُوسُفُ ۖ قَالَ أَنَا۠ يُوسُفُ وَهَـٰذَآ أَخِى ۖ قَدْ مَنَّ ٱللَّهُ عَلَيْنَآ ۖ إِنَّهُۥ مَن يَتَّقِ وَيَصْبِرْ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ','Qaaloo \'a innaka la anta Yoosufu qaala ana Yoosufu wa haazaaa akhee qad mannal laahu \'alainaa innahoo mai yattaqi wa yasbir fa innal laaha laa yudee\'u ajral muhsineen',90,'12:90',25,98,202,3,0,246,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1687,12,'قَالُوا۟ تَٱللَّهِ لَقَدْ ءَاثَرَكَ ٱللَّهُ عَلَيْنَا وَإِن كُنَّا لَخَـٰطِـِٔينَ','Qaaloo tallaahi laqad aasarakal laahu \'alainaa wa in kunnaa lakhaati\'een',91,'12:91',25,98,202,3,0,246,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1688,12,'قَالَ لَا تَثْرِيبَ عَلَيْكُمُ ٱلْيَوْمَ ۖ يَغْفِرُ ٱللَّهُ لَكُمْ ۖ وَهُوَ أَرْحَمُ ٱلرَّٰحِمِينَ','Qaala laa tasreeba \'alaikumul yawma yaghfirul laahu lakum wa Huwa arhamur raahimeen',92,'12:92',25,98,202,3,0,246,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1689,12,'ٱذْهَبُوا۟ بِقَمِيصِى هَـٰذَا فَأَلْقُوهُ عَلَىٰ وَجْهِ أَبِى يَأْتِ بَصِيرًا وَأْتُونِى بِأَهْلِكُمْ أَجْمَعِينَ','Izhaboo biqameesee haazaa fa alqoohu \'alaa wajhi abee yaati baseeranw waatoonee bi ahlikum ajma\'een',93,'12:93',25,98,202,3,0,246,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1690,12,'وَلَمَّا فَصَلَتِ ٱلْعِيرُ قَالَ أَبُوهُمْ إِنِّى لَأَجِدُ رِيحَ يُوسُفَ ۖ لَوْلَآ أَن تُفَنِّدُونِ','Wa lammaa fasalatil \'eeru qaala aboohum innee la ajidu reeha Yoosufa law laaa an tufannidoon',94,'12:94',25,98,203,3,0,246,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1691,12,'قَالُوا۟ تَٱللَّهِ إِنَّكَ لَفِى ضَلَـٰلِكَ ٱلْقَدِيمِ','Qaaloo tallaahi innaka lafee dalaalikal qadeem',95,'12:95',25,98,203,3,0,246,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1692,12,'فَلَمَّآ أَن جَآءَ ٱلْبَشِيرُ أَلْقَىٰهُ عَلَىٰ وَجْهِهِۦ فَٱرْتَدَّ بَصِيرًا ۖ قَالَ أَلَمْ أَقُل لَّكُمْ إِنِّىٓ أَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ','Falammaaa an jaaa\'albasheeru alqaahu \'alaa wajhihee fartadda baseeran qaala alam aqul lakum inneee a\'lamu minal laahi maa laa ta\'lamoon',96,'12:96',25,98,203,3,0,247,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1693,12,'قَالُوا۟ يَـٰٓأَبَانَا ٱسْتَغْفِرْ لَنَا ذُنُوبَنَآ إِنَّا كُنَّا خَـٰطِـِٔينَ','Qaaloo yaaa abaanas taghfir lanaa zunoo =banaaa innaa kunnaa khaati\'een',97,'12:97',25,98,203,3,0,247,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1694,12,'قَالَ سَوْفَ أَسْتَغْفِرُ لَكُمْ رَبِّىٓ ۖ إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ','Qaala sawfa astaghfiru lakum Rabbeee innahoo Huwal Ghafoorur Raheem',98,'12:98',25,98,203,3,0,247,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1695,12,'فَلَمَّا دَخَلُوا۟ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيْهِ أَبَوَيْهِ وَقَالَ ٱدْخُلُوا۟ مِصْرَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ','Falammaa dakhaloo \'alaa Yoosufa aawaaa ilaihi abayaihi wa qaalad khuloo Misra inshaaa\'al laahu aamineen',99,'12:99',25,98,203,3,0,247,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1696,12,'وَرَفَعَ أَبَوَيْهِ عَلَى ٱلْعَرْشِ وَخَرُّوا۟ لَهُۥ سُجَّدًا ۖ وَقَالَ يَـٰٓأَبَتِ هَـٰذَا تَأْوِيلُ رُءْيَـٰىَ مِن قَبْلُ قَدْ جَعَلَهَا رَبِّى حَقًّا ۖ وَقَدْ أَحْسَنَ بِىٓ إِذْ أَخْرَجَنِى مِنَ ٱلسِّجْنِ وَجَآءَ بِكُم مِّنَ ٱلْبَدْوِ مِنۢ بَعْدِ أَن نَّزَغَ ٱلشَّيْطَـٰنُ بَيْنِى وَبَيْنَ إِخْوَتِىٓ ۚ إِنَّ رَبِّى لَطِيفٌ لِّمَا يَشَآءُ ۚ إِنَّهُۥ هُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ','Wa raf\'a abawaihi \'alal \'arshi wa kharroo lahoo sujjadaa; wa qaala yaaa abati haaza taaweelu ru\'yaaya min qablu qad ja\'alahaa Rabbee haqqaa; wa qad ahsana beee iz akhrajanee minas sijni wa jaaa\'a bikum minal badwi mim ba\'di an nazaghash Shaitaanu bainee wa baina ikhwatee; inna Rabbee lateeful limaa yashaaa\'; innahoo Huwal \'Aleemul Hakeem',100,'12:100',25,98,203,3,0,247,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1697,12,'۞ رَبِّ قَدْ ءَاتَيْتَنِى مِنَ ٱلْمُلْكِ وَعَلَّمْتَنِى مِن تَأْوِيلِ ٱلْأَحَادِيثِ ۚ فَاطِرَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ أَنتَ وَلِىِّۦ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ ۖ تَوَفَّنِى مُسْلِمًا وَأَلْحِقْنِى بِٱلصَّـٰلِحِينَ','Rabbi qad aataitanee minal mulki wa \'allamtanee min taaweelil ahaadees; faati ras samaawaati wal ardi Anta waliyyee fid dunyaa wal Aakhirati tawaffanee muslimanw wa alhiqnee bissaaliheen',101,'12:101',25,99,203,3,0,247,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1698,12,'ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهِ إِلَيْكَ ۖ وَمَا كُنتَ لَدَيْهِمْ إِذْ أَجْمَعُوٓا۟ أَمْرَهُمْ وَهُمْ يَمْكُرُونَ','Zaalika min ambaaa\'il ghaibi nooheehi ilaika wa maa kunta ladaihim iz ajma\'ooo amrahum wa hum yamkuroon',102,'12:102',25,99,203,3,0,247,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1699,12,'وَمَآ أَكْثَرُ ٱلنَّاسِ وَلَوْ حَرَصْتَ بِمُؤْمِنِينَ','Wa maa aksarun naasi wa law harasta bimu\'mineen',103,'12:103',25,99,203,3,0,247,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1700,12,'وَمَا تَسْـَٔلُهُمْ عَلَيْهِ مِنْ أَجْرٍ ۚ إِنْ هُوَ إِلَّا ذِكْرٌ لِّلْعَـٰلَمِينَ','Wa maa tas\'aluhum \'alaihi min ajr; in huwa illaa zikrul lil\'aalameen',104,'12:104',25,99,203,3,0,248,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1701,12,'وَكَأَيِّن مِّنْ ءَايَةٍ فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ يَمُرُّونَ عَلَيْهَا وَهُمْ عَنْهَا مُعْرِضُونَ','Wa ka ayyim min Aayatin fis samaawaati wal ardi yamurroona \'alaihaa wa hum \'anhaa mu\'ridoon',105,'12:105',25,99,204,3,0,248,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1702,12,'وَمَا يُؤْمِنُ أَكْثَرُهُم بِٱللَّهِ إِلَّا وَهُم مُّشْرِكُونَ','Wa maa yu\'minu aksaru hum billaahi illaa wa hum mushrikoon',106,'12:106',25,99,204,3,0,248,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1703,12,'أَفَأَمِنُوٓا۟ أَن تَأْتِيَهُمْ غَـٰشِيَةٌ مِّنْ عَذَابِ ٱللَّهِ أَوْ تَأْتِيَهُمُ ٱلسَّاعَةُ بَغْتَةً وَهُمْ لَا يَشْعُرُونَ','Afa aminooo an taatiya hum ghaashiyatum min \'azaabil laahi aw taatiyahumus Saa\'atu baghtatanw wa hum laa yash\'uroon',107,'12:107',25,99,204,3,0,248,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1704,12,'قُلْ هَـٰذِهِۦ سَبِيلِىٓ أَدْعُوٓا۟ إِلَى ٱللَّهِ ۚ عَلَىٰ بَصِيرَةٍ أَنَا۠ وَمَنِ ٱتَّبَعَنِى ۖ وَسُبْحَـٰنَ ٱللَّهِ وَمَآ أَنَا۠ مِنَ ٱلْمُشْرِكِينَ','Qul haazihee sabeeleee ad\'ooo ilal laah; \'alaa baseera tin ana wa manit taba\'anee wa Subhaanal laahi wa maaa ana minal mushrikeen',108,'12:108',25,99,204,3,0,248,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1705,12,'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِىٓ إِلَيْهِم مِّنْ أَهْلِ ٱلْقُرَىٰٓ ۗ أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَـٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ ۗ وَلَدَارُ ٱلْـَٔاخِرَةِ خَيْرٌ لِّلَّذِينَ ٱتَّقَوْا۟ ۗ أَفَلَا تَعْقِلُونَ','Wa maaa arsalnaa min qablika illaa rijaalan nooheee ilaihim min ahlil quraa; afalam yaseeroo fil ardi fa yanzuroo kaifa kaana \'aaqibatul lazeena min qablihim; wa la Daarul Aakhirati Khairul lillazeenat taqaw; afalaa ta\'qiloon',109,'12:109',25,99,204,3,0,248,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1706,12,'حَتَّىٰٓ إِذَا ٱسْتَيْـَٔسَ ٱلرُّسُلُ وَظَنُّوٓا۟ أَنَّهُمْ قَدْ كُذِبُوا۟ جَآءَهُمْ نَصْرُنَا فَنُجِّىَ مَن نَّشَآءُ ۖ وَلَا يُرَدُّ بَأْسُنَا عَنِ ٱلْقَوْمِ ٱلْمُجْرِمِينَ','Hattaaa izas tai\'asar Rusulu wa zannooo annahum qad kuziboo jaaa\'ahum nas runaa fanujjiya man nashaaa\'u wa laa yuraddu baasunna \'anil qawmil mujrimeen',110,'12:110',25,99,204,3,0,248,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1707,12,'لَقَدْ كَانَ فِى قَصَصِهِمْ عِبْرَةٌ لِّأُو۟لِى ٱلْأَلْبَـٰبِ ۗ مَا كَانَ حَدِيثًا يُفْتَرَىٰ وَلَـٰكِن تَصْدِيقَ ٱلَّذِى بَيْنَ يَدَيْهِ وَتَفْصِيلَ كُلِّ شَىْءٍ وَهُدًى وَرَحْمَةً لِّقَوْمٍ يُؤْمِنُونَ','Laqad kaana fee qasasihim \'ibratul li ulil albaa; maa kaana hadeesany yuftaraa wa laakin tasdeeqal lazee baina yadihi wa tafseela kulli shai\'inw wa hudanw wa rahmatal liqawminy yu\'minoon',111,'12:111',25,99,204,3,0,248,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1708,13,'الٓمٓر ۚ تِلْكَ ءَايَـٰتُ ٱلْكِتَـٰبِ ۗ وَٱلَّذِىٓ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ ٱلْحَقُّ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يُؤْمِنُونَ','Alif-Laaam-Meeem-Raa; tilka Aayaatul Kitaab; wallazee unzila ilaika mir Rabbikal haqqu wa laakinna aksaran naasi laa yu\'minoon',1,'13:1',25,99,205,3,0,249,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1709,13,'ٱللَّهُ ٱلَّذِى رَفَعَ ٱلسَّمَـٰوَٰتِ بِغَيْرِ عَمَدٍ تَرَوْنَهَا ۖ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ۖ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ ۖ كُلٌّ يَجْرِى لِأَجَلٍ مُّسَمًّى ۚ يُدَبِّرُ ٱلْأَمْرَ يُفَصِّلُ ٱلْـَٔايَـٰتِ لَعَلَّكُم بِلِقَآءِ رَبِّكُمْ تُوقِنُونَ','Allaahul lazee raf\'as samaawaati bighairi \'amadin tarawnahaa summas tawaa \'alal \'Arshi wa sakhkharash shamsa walqamara kulluny yajree li ajalim musammaa; yudabbirul amra yufassilil Aayaati la\'allakum biliqaaa\'i Rabbikum tooqinoon',2,'13:2',25,99,205,3,0,249,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1710,13,'وَهُوَ ٱلَّذِى مَدَّ ٱلْأَرْضَ وَجَعَلَ فِيهَا رَوَٰسِىَ وَأَنْهَـٰرًا ۖ وَمِن كُلِّ ٱلثَّمَرَٰتِ جَعَلَ فِيهَا زَوْجَيْنِ ٱثْنَيْنِ ۖ يُغْشِى ٱلَّيْلَ ٱلنَّهَارَ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّقَوْمٍ يَتَفَكَّرُونَ','Wa Huwal lazee maddal arda wa ja\'ala feehaa rawaasiya wa anhaaraa; wa min kullis samaraati ja\'ala feehaa zawjainis yaini Yughshil lailan nahaar; inna fee zaalika la aayaatil liqawminy yatafakkaroon',3,'13:3',25,99,205,3,0,249,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1711,13,'وَفِى ٱلْأَرْضِ قِطَعٌ مُّتَجَـٰوِرَٰتٌ وَجَنَّـٰتٌ مِّنْ أَعْنَـٰبٍ وَزَرْعٌ وَنَخِيلٌ صِنْوَانٌ وَغَيْرُ صِنْوَانٍ يُسْقَىٰ بِمَآءٍ وَٰحِدٍ وَنُفَضِّلُ بَعْضَهَا عَلَىٰ بَعْضٍ فِى ٱلْأُكُلِ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّقَوْمٍ يَعْقِلُونَ','Wa fil ardi qita\'um muta jaawiraatunw wa jannaatum min a\'naabinw wa zar\'unw wa nakheelun sinwaanunw wa ghairu sinwaaniny yusqaa bimaaa\'inw waahid; wa nufaddilu ba\'dahaa \'alaa ba\'din fil-ukul; inna fee zaalika la aayaatil liqawminy ya\'qiloon',4,'13:4',25,99,205,3,0,249,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1712,13,'۞ وَإِن تَعْجَبْ فَعَجَبٌ قَوْلُهُمْ أَءِذَا كُنَّا تُرَٰبًا أَءِنَّا لَفِى خَلْقٍ جَدِيدٍ ۗ أُو۟لَـٰٓئِكَ ٱلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ ۖ وَأُو۟لَـٰٓئِكَ ٱلْأَغْلَـٰلُ فِىٓ أَعْنَاقِهِمْ ۖ وَأُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ','Wa in ta\'jab fa\'ajabun qawluhm \'a-izaa kunna turaaban \'a-inna lafee khalqin jadeed; ulaaa \'ikal lazeena kafaroo bi Rabbihim wa ulaaa\'ikal aghlaalu feee a\'naaqihim wa ulaa\'ika Ashaabun Naari hum feehaa khaalidoon',5,'13:5',25,100,205,3,0,249,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1713,13,'وَيَسْتَعْجِلُونَكَ بِٱلسَّيِّئَةِ قَبْلَ ٱلْحَسَنَةِ وَقَدْ خَلَتْ مِن قَبْلِهِمُ ٱلْمَثُلَـٰتُ ۗ وَإِنَّ رَبَّكَ لَذُو مَغْفِرَةٍ لِّلنَّاسِ عَلَىٰ ظُلْمِهِمْ ۖ وَإِنَّ رَبَّكَ لَشَدِيدُ ٱلْعِقَابِ','Wa yasta\'jiloonaka bis saiyi\'ati qablal hasanati wa qad khalat min qablihimul masulaat; wa inna Rabbaka lazoo maghfiratil linnaasi \'alaa zulmihim wa inna Rabbaka lashadeedul \'iqaab',6,'13:6',25,100,205,3,0,250,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1714,13,'وَيَقُولُ ٱلَّذِينَ كَفَرُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦٓ ۗ إِنَّمَآ أَنتَ مُنذِرٌ ۖ وَلِكُلِّ قَوْمٍ هَادٍ','Wa yaqoolul lazeena kafaroo law laaa unzila \'alaihi Aayatum mir Rabbih; innamaaa anta munzirunw wa likulli qawmin haad',7,'13:7',25,100,205,3,0,250,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1715,13,'ٱللَّهُ يَعْلَمُ مَا تَحْمِلُ كُلُّ أُنثَىٰ وَمَا تَغِيضُ ٱلْأَرْحَامُ وَمَا تَزْدَادُ ۖ وَكُلُّ شَىْءٍ عِندَهُۥ بِمِقْدَارٍ','Allaahu ya\'lamu maa tahmilu kullu unsaa wa maa tagheedul arhaamu wa maa tazdaad, wa kullu shai\'in \'indahoo bimiqdaar',8,'13:8',25,100,206,3,0,250,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1716,13,'عَـٰلِمُ ٱلْغَيْبِ وَٱلشَّهَـٰدَةِ ٱلْكَبِيرُ ٱلْمُتَعَالِ','\'Aalimul Ghaibi wash shahaadatil Kaabeerul Muta\'aal',9,'13:9',25,100,206,3,0,250,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1717,13,'سَوَآءٌ مِّنكُم مَّنْ أَسَرَّ ٱلْقَوْلَ وَمَن جَهَرَ بِهِۦ وَمَنْ هُوَ مُسْتَخْفٍۭ بِٱلَّيْلِ وَسَارِبٌۢ بِٱلنَّهَارِ','Sawaaa\'um minkum man asarral qawla wa man jahara bihee wa man huwa mustakhfim billaili wa saaribum binnahaar',10,'13:10',25,100,206,3,0,250,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1718,13,'لَهُۥ مُعَقِّبَـٰتٌ مِّنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦ يَحْفَظُونَهُۥ مِنْ أَمْرِ ٱللَّهِ ۗ إِنَّ ٱللَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ حَتَّىٰ يُغَيِّرُوا۟ مَا بِأَنفُسِهِمْ ۗ وَإِذَآ أَرَادَ ٱللَّهُ بِقَوْمٍ سُوٓءًا فَلَا مَرَدَّ لَهُۥ ۚ وَمَا لَهُم مِّن دُونِهِۦ مِن وَالٍ','Lahoo mu\'aqqibaatum mim baini yadaihi wa min khalfihee yahfazoonahoo min amril laah; innal laaha laa yughaiyiru maa biqawmin hattaa yughaiyiroo maa bianfusihim; wa izaaa araadal laahu biqawmin sooo\'an falaa maradda lah; wa maa lahum min dooniheeminw waal',11,'13:11',25,100,206,3,0,250,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1719,13,'هُوَ ٱلَّذِى يُرِيكُمُ ٱلْبَرْقَ خَوْفًا وَطَمَعًا وَيُنشِئُ ٱلسَّحَابَ ٱلثِّقَالَ','Huwal lazee yureekumul barqa khawfanw wa tama\'anw wa yunshi\'us sahaabas siqaal',12,'13:12',25,100,206,3,0,250,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1720,13,'وَيُسَبِّحُ ٱلرَّعْدُ بِحَمْدِهِۦ وَٱلْمَلَـٰٓئِكَةُ مِنْ خِيفَتِهِۦ وَيُرْسِلُ ٱلصَّوَٰعِقَ فَيُصِيبُ بِهَا مَن يَشَآءُ وَهُمْ يُجَـٰدِلُونَ فِى ٱللَّهِ وَهُوَ شَدِيدُ ٱلْمِحَالِ','Wa yusabbihur ra\'du bihamdihee walmalaaa\'ikatu min kheefatihee wa yursilus sawaa\'iqa fa yuseebu bihaa mai yashaaa\'u wa hum yujaadiloona fil laahi wa Huwa shadeedul mihaal',13,'13:13',25,100,206,3,0,250,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1721,13,'لَهُۥ دَعْوَةُ ٱلْحَقِّ ۖ وَٱلَّذِينَ يَدْعُونَ مِن دُونِهِۦ لَا يَسْتَجِيبُونَ لَهُم بِشَىْءٍ إِلَّا كَبَـٰسِطِ كَفَّيْهِ إِلَى ٱلْمَآءِ لِيَبْلُغَ فَاهُ وَمَا هُوَ بِبَـٰلِغِهِۦ ۚ وَمَا دُعَآءُ ٱلْكَـٰفِرِينَ إِلَّا فِى ضَلَـٰلٍ','Lahoo da\'watul haqq; wallazeena yad\'oona min doonihee laa yastajeeboona lahum bishai\'in illaa kabaasiti kaffaihi ilal maaa\'i liyablugha faahu wa maa huwa bibaalighih; wa maa du\'aaa\'ul aafireena illaa fee dalaal',14,'13:14',25,100,206,3,0,251,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1722,13,'وَلِلَّهِ يَسْجُدُ مَن فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ طَوْعًا وَكَرْهًا وَظِلَـٰلُهُم بِٱلْغُدُوِّ وَٱلْـَٔاصَالِ ۩','Wa lillaahi yasjudu man fis samaawaati wal ardi taw \'anw wa karhanw wa zilaaluhum bilghuduwwi wal aasaal',15,'13:15',25,100,206,3,2,251,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1723,13,'قُلْ مَن رَّبُّ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ قُلِ ٱللَّهُ ۚ قُلْ أَفَٱتَّخَذْتُم مِّن دُونِهِۦٓ أَوْلِيَآءَ لَا يَمْلِكُونَ لِأَنفُسِهِمْ نَفْعًا وَلَا ضَرًّا ۚ قُلْ هَلْ يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ أَمْ هَلْ تَسْتَوِى ٱلظُّلُمَـٰتُ وَٱلنُّورُ ۗ أَمْ جَعَلُوا۟ لِلَّهِ شُرَكَآءَ خَلَقُوا۟ كَخَلْقِهِۦ فَتَشَـٰبَهَ ٱلْخَلْقُ عَلَيْهِمْ ۚ قُلِ ٱللَّهُ خَـٰلِقُ كُلِّ شَىْءٍ وَهُوَ ٱلْوَٰحِدُ ٱلْقَهَّـٰرُ','Wul mar Rabbus samaawaati wal ard; qulillaah; qul afattakhaztum min dooniheee awliyaaa\'a laa yamlikoona li anfusihim naf\'anw wa laa darraa; qul hal yastawil a\'maa wal baseeru am hal tastawiz zulumaatu wannoor; am ja\'aloo lillaahi shurakaaa\'a khalaqoo kakhalqihee fatashaa bahal khalqu \'alaihim; qulil laahu Khaaliqu kulli shai\'inw wa Huwal Waahidul Qahhar',16,'13:16',25,100,206,3,0,251,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1724,13,'أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَسَالَتْ أَوْدِيَةٌۢ بِقَدَرِهَا فَٱحْتَمَلَ ٱلسَّيْلُ زَبَدًا رَّابِيًا ۚ وَمِمَّا يُوقِدُونَ عَلَيْهِ فِى ٱلنَّارِ ٱبْتِغَآءَ حِلْيَةٍ أَوْ مَتَـٰعٍ زَبَدٌ مِّثْلُهُۥ ۚ كَذَٰلِكَ يَضْرِبُ ٱللَّهُ ٱلْحَقَّ وَٱلْبَـٰطِلَ ۚ فَأَمَّا ٱلزَّبَدُ فَيَذْهَبُ جُفَآءً ۖ وَأَمَّا مَا يَنفَعُ ٱلنَّاسَ فَيَمْكُثُ فِى ٱلْأَرْضِ ۚ كَذَٰلِكَ يَضْرِبُ ٱللَّهُ ٱلْأَمْثَالَ','Anzala minas samaaa\'i maaa\'an fasaalat awdiyatum biqadarihaa fahtamalas sailu zabadar raabiyaa; wa mimmmaa yooqidoona \'alaihi fin naarib tighaaa\'a bilyatin aw mataa\'in zabadum misluh; kazaalika yadribul laahul haqqa wal baatil; fa ammaz zabadu fa yazhabu jufaaa\'aa; wa ammaa maa yanfa\'un naasa fa yamkusu fil ard; kazaalika yadribul laahul amsaal',17,'13:17',25,100,206,3,0,251,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1725,13,'لِلَّذِينَ ٱسْتَجَابُوا۟ لِرَبِّهِمُ ٱلْحُسْنَىٰ ۚ وَٱلَّذِينَ لَمْ يَسْتَجِيبُوا۟ لَهُۥ لَوْ أَنَّ لَهُم مَّا فِى ٱلْأَرْضِ جَمِيعًا وَمِثْلَهُۥ مَعَهُۥ لَٱفْتَدَوْا۟ بِهِۦٓ ۚ أُو۟لَـٰٓئِكَ لَهُمْ سُوٓءُ ٱلْحِسَابِ وَمَأْوَىٰهُمْ جَهَنَّمُ ۖ وَبِئْسَ ٱلْمِهَادُ','Lillazeenas tajaaboo lirabbihimul husnaa; wallazeena lam yastajeeboo lahoo law anna lahum maa fil ardi jamee\'anw wa mislahoo ma\'ahoo laftadaw bih; ulaaa\'ika lahum sooo\'ul hisaab; wa maawaahum Jahannamu wa bi\'sal mihaad',18,'13:18',25,100,206,3,0,251,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1726,13,'۞ أَفَمَن يَعْلَمُ أَنَّمَآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ ٱلْحَقُّ كَمَنْ هُوَ أَعْمَىٰٓ ۚ إِنَّمَا يَتَذَكَّرُ أُو۟لُوا۟ ٱلْأَلْبَـٰبِ','Afamai ya\'lamu annamaaa unzila ilaika mir Rabbikal haqqu kaman huwa a\'maa; innamaa yatazakkaru ulul albaab',19,'13:19',26,101,207,3,0,252,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1727,13,'ٱلَّذِينَ يُوفُونَ بِعَهْدِ ٱللَّهِ وَلَا يَنقُضُونَ ٱلْمِيثَـٰقَ','Allazeena yoofoona bi\'ahdil laahi wa laa yanqu doonal meesaaq',20,'13:20',26,101,207,3,0,252,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1728,13,'وَٱلَّذِينَ يَصِلُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيَخْشَوْنَ رَبَّهُمْ وَيَخَافُونَ سُوٓءَ ٱلْحِسَابِ','Wallazeena yasiloona maaa amaral laahu bihee an yoosala wa yakhshawna Rabbahum wa yakhaafoona sooo\'al hisaab',21,'13:21',26,101,207,3,0,252,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1729,13,'وَٱلَّذِينَ صَبَرُوا۟ ٱبْتِغَآءَ وَجْهِ رَبِّهِمْ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَنفَقُوا۟ مِمَّا رَزَقْنَـٰهُمْ سِرًّا وَعَلَانِيَةً وَيَدْرَءُونَ بِٱلْحَسَنَةِ ٱلسَّيِّئَةَ أُو۟لَـٰٓئِكَ لَهُمْ عُقْبَى ٱلدَّارِ','Wallazeena sabarub tighaaa\'a Wajhi Rabbihim wa aqaamus Salaata wa anfaqoo mimmaa razaqnaahum sirranw wa \'alaaniyatanw wa yadra\'oona bilhasanatis saiyi\'ata ulaaa\'ika lahum \'uqbad daar',22,'13:22',26,101,207,3,0,252,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1730,13,'جَنَّـٰتُ عَدْنٍ يَدْخُلُونَهَا وَمَن صَلَحَ مِنْ ءَابَآئِهِمْ وَأَزْوَٰجِهِمْ وَذُرِّيَّـٰتِهِمْ ۖ وَٱلْمَلَـٰٓئِكَةُ يَدْخُلُونَ عَلَيْهِم مِّن كُلِّ بَابٍ','jannaatu \'adiny yadkhu loonahaa wa man salaha min aabaaa\'ihim wa man salaha min aabaaa\'ihim wa azwaajihim wa zurriyyaatihim walmalaaa\'i katu yadkhuloona \'alaihim min kulli baab',23,'13:23',26,101,207,3,0,252,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1731,13,'سَلَـٰمٌ عَلَيْكُم بِمَا صَبَرْتُمْ ۚ فَنِعْمَ عُقْبَى ٱلدَّارِ','Salaamun \'alaikum bimaa sabartum; fani\'ma \'uqbad daar',24,'13:24',26,101,207,3,0,252,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1732,13,'وَٱلَّذِينَ يَنقُضُونَ عَهْدَ ٱللَّهِ مِنۢ بَعْدِ مِيثَـٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفْسِدُونَ فِى ٱلْأَرْضِ ۙ أُو۟لَـٰٓئِكَ لَهُمُ ٱللَّعْنَةُ وَلَهُمْ سُوٓءُ ٱلدَّارِ','Wallazeena yanqudoona \'Ahdal laahi mim ba\'di meesaaqihee wa yaqta\'oona maaa amaral laahu biheee ai yoosala wa yufsidoona fil ardi ulaaa\'ika lahumul la\'natu wa lahum sooo\'ud daar',25,'13:25',26,101,207,3,0,252,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1733,13,'ٱللَّهُ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ ۚ وَفَرِحُوا۟ بِٱلْحَيَوٰةِ ٱلدُّنْيَا وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَا فِى ٱلْـَٔاخِرَةِ إِلَّا مَتَـٰعٌ','Allaahu yabsutur rizqa limai yashaaa\'u wa yaqdir; wa farihoo bilhayaatid dunyaa wa mal hayaatud dunya fil Aakhirati illaa mataa\'',26,'13:26',26,101,207,3,0,252,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1734,13,'وَيَقُولُ ٱلَّذِينَ كَفَرُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦ ۗ قُلْ إِنَّ ٱللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهْدِىٓ إِلَيْهِ مَنْ أَنَابَ','Wa yaqoolul lazeena kafaroo law laaa unzila \'alaihi Aayatum mir Rabbih; qul innal laaha yudillu mai yashaa\'u wa yahdeee ilaihi man anaab',27,'13:27',26,101,208,3,0,252,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1735,13,'ٱلَّذِينَ ءَامَنُوا۟ وَتَطْمَئِنُّ قُلُوبُهُم بِذِكْرِ ٱللَّهِ ۗ أَلَا بِذِكْرِ ٱللَّهِ تَطْمَئِنُّ ٱلْقُلُوبُ','Allazeena aamanoo wa tatma\'innu quloobuhum bizikril laah; alaa bizikril laahi tatma\'innul quloob',28,'13:28',26,101,208,3,0,252,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1736,13,'ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ طُوبَىٰ لَهُمْ وَحُسْنُ مَـَٔابٍ','Allazeena aamanoo w a\'amilus saalihaati toobaa lahum wa husnu ma aab',29,'13:29',26,101,208,3,0,253,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1737,13,'كَذَٰلِكَ أَرْسَلْنَـٰكَ فِىٓ أُمَّةٍ قَدْ خَلَتْ مِن قَبْلِهَآ أُمَمٌ لِّتَتْلُوَا۟ عَلَيْهِمُ ٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ وَهُمْ يَكْفُرُونَ بِٱلرَّحْمَـٰنِ ۚ قُلْ هُوَ رَبِّى لَآ إِلَـٰهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ مَتَابِ','Kazaalika arsalnaaka feee ummatin qad khalat min qablihaaa umamul litatluwa \'alaihimul lazeee awhainaaa ilaika wa hum yakfuroona bir Rahmaaan; qul Huwa Rabbee laaa ilaaha illaa Huwa Rabbee laaa ilaaha illaa Huwa \'alaihi tawakkaltu wa ilaihi mataab',30,'13:30',26,101,208,3,0,253,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1738,13,'وَلَوْ أَنَّ قُرْءَانًا سُيِّرَتْ بِهِ ٱلْجِبَالُ أَوْ قُطِّعَتْ بِهِ ٱلْأَرْضُ أَوْ كُلِّمَ بِهِ ٱلْمَوْتَىٰ ۗ بَل لِّلَّهِ ٱلْأَمْرُ جَمِيعًا ۗ أَفَلَمْ يَا۟يْـَٔسِ ٱلَّذِينَ ءَامَنُوٓا۟ أَن لَّوْ يَشَآءُ ٱللَّهُ لَهَدَى ٱلنَّاسَ جَمِيعًا ۗ وَلَا يَزَالُ ٱلَّذِينَ كَفَرُوا۟ تُصِيبُهُم بِمَا صَنَعُوا۟ قَارِعَةٌ أَوْ تَحُلُّ قَرِيبًا مِّن دَارِهِمْ حَتَّىٰ يَأْتِىَ وَعْدُ ٱللَّهِ ۚ إِنَّ ٱللَّهَ لَا يُخْلِفُ ٱلْمِيعَادَ','Wa law anna Quraanan suyyirat bihil jibaalu aw qutti\'at bihil ardu aw kullima bihil mawtaa; bal lillaahil amru jamee\'aa; afalam yai\'asil lazeena aamanooo al law yashaaa \'ullaahu lahadan naasa jamee\'aa; wa laa yazaalul lazeena kafaroo tuseebuhum bimaa sana\'oo qaari\'atun aw tahullu qareebam min daarihim hatta yaatiya wa\'dul laah; innal laaha laa yukhliful mee\'aad',31,'13:31',26,101,208,3,0,253,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1739,13,'وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍ مِّن قَبْلِكَ فَأَمْلَيْتُ لِلَّذِينَ كَفَرُوا۟ ثُمَّ أَخَذْتُهُمْ ۖ فَكَيْفَ كَانَ عِقَابِ','Wa laqadis tuhzi\'a bi Rusulim min qablika fa amlaitu lillazeena kafaroo summa akhaztuhum fakaifa kaana \'iqaab',32,'13:32',26,101,209,3,0,253,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1740,13,'أَفَمَنْ هُوَ قَآئِمٌ عَلَىٰ كُلِّ نَفْسٍۭ بِمَا كَسَبَتْ ۗ وَجَعَلُوا۟ لِلَّهِ شُرَكَآءَ قُلْ سَمُّوهُمْ ۚ أَمْ تُنَبِّـُٔونَهُۥ بِمَا لَا يَعْلَمُ فِى ٱلْأَرْضِ أَم بِظَـٰهِرٍ مِّنَ ٱلْقَوْلِ ۗ بَلْ زُيِّنَ لِلَّذِينَ كَفَرُوا۟ مَكْرُهُمْ وَصُدُّوا۟ عَنِ ٱلسَّبِيلِ ۗ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍ','Afaman Huwa qaaa\'imun \'alaa kulli nafsim bimaa kasabat; wa ja\'aloo illlaahi shurakaaa\'a qul samoohum; am tunabbi\'oona hoo bimaa laa ya\'lamu fil ardi; am bizaahirim minal qawl; bal zuyyina lillazeena kafaroo makruhum wa suddoo \'anis sabeel; wa mai yudlilil laaahu famaa lahoo min haad;',33,'13:33',26,101,209,3,0,253,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1741,13,'لَّهُمْ عَذَابٌ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَلَعَذَابُ ٱلْـَٔاخِرَةِ أَشَقُّ ۖ وَمَا لَهُم مِّنَ ٱللَّهِ مِن وَاقٍ','Lahum \'azaabun fil hayaatid dunyaa wa la\'azaabul Aakhirati ashaaq, wa maa lahum minal laahi min-waaq',34,'13:34',26,101,209,3,0,253,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1742,13,'۞ مَّثَلُ ٱلْجَنَّةِ ٱلَّتِى وُعِدَ ٱلْمُتَّقُونَ ۖ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ۖ أُكُلُهَا دَآئِمٌ وَظِلُّهَا ۚ تِلْكَ عُقْبَى ٱلَّذِينَ ٱتَّقَوا۟ ۖ وَّعُقْبَى ٱلْكَـٰفِرِينَ ٱلنَّارُ','Masalul Jannatil latee wu\'idal muttaqoona tajree min tahtihal anhaaru ukuluhaa daaa\'imunw wa zilluhaa; tilka uqbal lazeenat taqaw wa \'uqbal kafireenan Naar',35,'13:35',26,102,209,3,0,254,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1743,13,'وَٱلَّذِينَ ءَاتَيْنَـٰهُمُ ٱلْكِتَـٰبَ يَفْرَحُونَ بِمَآ أُنزِلَ إِلَيْكَ ۖ وَمِنَ ٱلْأَحْزَابِ مَن يُنكِرُ بَعْضَهُۥ ۚ قُلْ إِنَّمَآ أُمِرْتُ أَنْ أَعْبُدَ ٱللَّهَ وَلَآ أُشْرِكَ بِهِۦٓ ۚ إِلَيْهِ أَدْعُوا۟ وَإِلَيْهِ مَـَٔابِ','Wallazeena aatainaa humul Kitaaba yafrahoona bimaa unzila ilaika wa minal Ahzaabi mai yunkiru ba\'dah; qul innamaa umirtu an a\'budal laaha wa laaa ushrika bih; ilaihi ad\'oo wa ilaihi maab',36,'13:36',26,102,209,3,0,254,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1744,13,'وَكَذَٰلِكَ أَنزَلْنَـٰهُ حُكْمًا عَرَبِيًّا ۚ وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم بَعْدَ مَا جَآءَكَ مِنَ ٱلْعِلْمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِىٍّ وَلَا وَاقٍ','Wa kazaalika anzalnaahu hukman \'Arabiyyaa; wa la\'init taba\'ta ahwaaa \'ahum ba\'da maa jaaa\'aka minal \'ilmi maa laka minal laahi minw waliyinw wa laa waaq',37,'13:37',26,102,209,3,0,254,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1745,13,'وَلَقَدْ أَرْسَلْنَا رُسُلًا مِّن قَبْلِكَ وَجَعَلْنَا لَهُمْ أَزْوَٰجًا وَذُرِّيَّةً ۚ وَمَا كَانَ لِرَسُولٍ أَن يَأْتِىَ بِـَٔايَةٍ إِلَّا بِإِذْنِ ٱللَّهِ ۗ لِكُلِّ أَجَلٍ كِتَابٌ','Wa laqad arsalnaa Rusulam min qablika wa ja\'alnaa lahum azwaajanw wa zurriyyah; wa maa kaana lirasoolin ai yaatiya bi aayatin illaa bi iznil laah; likulli ajalin kitaab',38,'13:38',26,102,210,3,0,254,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1746,13,'يَمْحُوا۟ ٱللَّهُ مَا يَشَآءُ وَيُثْبِتُ ۖ وَعِندَهُۥٓ أُمُّ ٱلْكِتَـٰبِ','Yamhul laahu maa yashaaa\'u wa yusbitu wa \'indahooo ummul Kitaab',39,'13:39',26,102,210,3,0,254,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1747,13,'وَإِن مَّا نُرِيَنَّكَ بَعْضَ ٱلَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِنَّمَا عَلَيْكَ ٱلْبَلَـٰغُ وَعَلَيْنَا ٱلْحِسَابُ','Wa im maa nurriyannaka ba\'dal lazee na\'iduhum aw nata waffayannaka fa innamaa \'alaikal balaaghu wa \'alainal hisaab',40,'13:40',26,102,210,3,0,254,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1748,13,'أَوَلَمْ يَرَوْا۟ أَنَّا نَأْتِى ٱلْأَرْضَ نَنقُصُهَا مِنْ أَطْرَافِهَا ۚ وَٱللَّهُ يَحْكُمُ لَا مُعَقِّبَ لِحُكْمِهِۦ ۚ وَهُوَ سَرِيعُ ٱلْحِسَابِ','Awalam yaraw annaa naatil arda nanqusuhaa min atraafihaa; wallaahu yahkumu laa mu\'aqqiba lihukmih; wa Huwa saree\'ul hisaab',41,'13:41',26,102,210,3,0,254,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1749,13,'وَقَدْ مَكَرَ ٱلَّذِينَ مِن قَبْلِهِمْ فَلِلَّهِ ٱلْمَكْرُ جَمِيعًا ۖ يَعْلَمُ مَا تَكْسِبُ كُلُّ نَفْسٍ ۗ وَسَيَعْلَمُ ٱلْكُفَّـٰرُ لِمَنْ عُقْبَى ٱلدَّارِ','Wa qad makaral lazeena min qablihim falillaahil makru jamee\'aa; ya\'lamu maa taksibu kullu nafs; wa sa ya\'lamul kuffaaru liman \'uqbad daar',42,'13:42',26,102,210,3,0,254,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1750,13,'وَيَقُولُ ٱلَّذِينَ كَفَرُوا۟ لَسْتَ مُرْسَلًا ۚ قُلْ كَفَىٰ بِٱللَّهِ شَهِيدًۢا بَيْنِى وَبَيْنَكُمْ وَمَنْ عِندَهُۥ عِلْمُ ٱلْكِتَـٰبِ','Wa yaqoolul lazeena kafaroo lasta mursalaa; qul kafaa billaahi shaheedam bainee wa bainakum wa man \'indahoo \'ilmul Kitaab',43,'13:43',26,102,210,3,0,255,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1751,14,'الٓر ۚ كِتَـٰبٌ أَنزَلْنَـٰهُ إِلَيْكَ لِتُخْرِجَ ٱلنَّاسَ مِنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ بِإِذْنِ رَبِّهِمْ إِلَىٰ صِرَٰطِ ٱلْعَزِيزِ ٱلْحَمِيدِ','Alif-Laaam-Raa; Kitaabun anzalnaahu ilaika litukhrijan-naasa minaz zulumaati ilan noori bi-izni Rabbihim ilaa siraatil \'Azeezil Hameed',1,'14:1',26,102,211,3,0,255,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1752,14,'ٱللَّهِ ٱلَّذِى لَهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَوَيْلٌ لِّلْكَـٰفِرِينَ مِنْ عَذَابٍ شَدِيدٍ','Allaahil lazee lahoo maa fis samaawaati wa maa fill ard; wa wailul lilkaafireena min \'azaabin shadeed',2,'14:2',26,102,211,3,0,255,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1753,14,'ٱلَّذِينَ يَسْتَحِبُّونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا عَلَى ٱلْـَٔاخِرَةِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبْغُونَهَا عِوَجًا ۚ أُو۟لَـٰٓئِكَ فِى ضَلَـٰلٍۭ بَعِيدٍ','Allazeena yastahibboo nal hayaatad dunyaa \'alal aakhirati wa yasuddoona \'ansabeelil laahi wa yabghoonahaa \'iwajaa; ulaaa \'ika fee dalaalim ba\'eed',3,'14:3',26,102,211,3,0,255,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1754,14,'وَمَآ أَرْسَلْنَا مِن رَّسُولٍ إِلَّا بِلِسَانِ قَوْمِهِۦ لِيُبَيِّنَ لَهُمْ ۖ فَيُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ','Wa maaa arsalnaa mir Rasoolin illaa bilisaani qawmihee liyubaiyina lahum faiudillul laahu mai yashaaa\'u wa yahde mai yashaaa\'; wa Huwal \'Azeezul Hakeem',4,'14:4',26,102,211,3,0,255,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1755,14,'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَـٰتِنَآ أَنْ أَخْرِجْ قَوْمَكَ مِنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ وَذَكِّرْهُم بِأَيَّىٰمِ ٱللَّهِ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ','Wa laqad arsalnaa Moosaa bi Aayaatinaa an akhrij qawmaka minaz zulumaati ilan noori wa zak kirhum bi ayyaamil laah; inna fee zaalika la aayaatil likulli sabbaarin shakoor',5,'14:5',26,102,211,3,0,255,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1756,14,'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِ ٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ إِذْ أَنجَىٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ وَيُذَبِّحُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ ۚ وَفِى ذَٰلِكُم بَلَآءٌ مِّن رَّبِّكُمْ عَظِيمٌ','Wa iz qaala Moosaa liqawmihiz kuroo ni\'matal laahi \'alaikum iz anjaakum min Aali Fir\'awna yasoomoo nakum sooo\'al \'azaabi wa yuzabbihoona abnaaa\'akum wa yastahyoona nisaaa\'akum; wa fee zaalikum balaaa\'um mir Rabbikum \'azeem',6,'14:6',26,102,211,3,0,256,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1757,14,'وَإِذْ تَأَذَّنَ رَبُّكُمْ لَئِن شَكَرْتُمْ لَأَزِيدَنَّكُمْ ۖ وَلَئِن كَفَرْتُمْ إِنَّ عَذَابِى لَشَدِيدٌ','Wa iz ta azzana Rabbukum la\'in shakartum la azeedannakum wa la\'in kafartum inn\'azaabee lashadeed',7,'14:7',26,102,212,3,0,256,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1758,14,'وَقَالَ مُوسَىٰٓ إِن تَكْفُرُوٓا۟ أَنتُمْ وَمَن فِى ٱلْأَرْضِ جَمِيعًا فَإِنَّ ٱللَّهَ لَغَنِىٌّ حَمِيدٌ','Wa qaala Moosaaa in takfurooo antum wa man fil ardi jamee\'an fa innal laaha la Ghaniyyun Hameed',8,'14:8',26,102,212,3,0,256,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1759,14,'أَلَمْ يَأْتِكُمْ نَبَؤُا۟ ٱلَّذِينَ مِن قَبْلِكُمْ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ ۛ وَٱلَّذِينَ مِنۢ بَعْدِهِمْ ۛ لَا يَعْلَمُهُمْ إِلَّا ٱللَّهُ ۚ جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَـٰتِ فَرَدُّوٓا۟ أَيْدِيَهُمْ فِىٓ أَفْوَٰهِهِمْ وَقَالُوٓا۟ إِنَّا كَفَرْنَا بِمَآ أُرْسِلْتُم بِهِۦ وَإِنَّا لَفِى شَكٍّ مِّمَّا تَدْعُونَنَآ إِلَيْهِ مُرِيبٍ','Alam yaatikum naba\'ul lazeena min qablikum qawmi Noohinw wa \'Aadinw wa Samood, wallazeena mim ba\'dihim; laa ya\'lamuhum illallaah; jaaa\'at hum Rusuluhum bilbaiyinaati faraddooo aydiyahum feee afwaahihim wa qaalooo innaa kafarnaa bimaaa ursiltum bihee wa innaa lafee shakkim mimmaa tad\'oonanaaa ilaihi mureeb',9,'14:9',26,102,212,3,0,256,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1760,14,'۞ قَالَتْ رُسُلُهُمْ أَفِى ٱللَّهِ شَكٌّ فَاطِرِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ يَدْعُوكُمْ لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَىٰٓ أَجَلٍ مُّسَمًّى ۚ قَالُوٓا۟ إِنْ أَنتُمْ إِلَّا بَشَرٌ مِّثْلُنَا تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ ءَابَآؤُنَا فَأْتُونَا بِسُلْطَـٰنٍ مُّبِينٍ','Qaalat Rusuluhum afillaahi shakkun faatiris samaawaati wal ardi yad\'ookum liyaghfira lakum min zunoobikum wa yu\'akhkhirakum ilaaa ajalim musam maa; qaaloo in antum illaa basharum mislunaa tureedoona an tasuddoonaa \'ammaa kaana ya\'budu aabaaa\'unaa faatoonaa bisul taanim mubeen',10,'14:10',26,103,212,3,0,256,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1761,14,'قَالَتْ لَهُمْ رُسُلُهُمْ إِن نَّحْنُ إِلَّا بَشَرٌ مِّثْلُكُمْ وَلَـٰكِنَّ ٱللَّهَ يَمُنُّ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ ۖ وَمَا كَانَ لَنَآ أَن نَّأْتِيَكُم بِسُلْطَـٰنٍ إِلَّا بِإِذْنِ ٱللَّهِ ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ','Qaalat lahum Rusuluhum in nahnu illaa basharum mislukum wa laakinnal laaha yamunnu \'alaa mai yashaaa\'u min \'ibaadihee wa maa kaana lanaaa an naatiyakum bisul taanin illaa bi iznil laah; wa \'alal laahi falyatawakkalil mu\'minonn',11,'14:11',26,103,212,3,0,257,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1762,14,'وَمَا لَنَآ أَلَّا نَتَوَكَّلَ عَلَى ٱللَّهِ وَقَدْ هَدَىٰنَا سُبُلَنَا ۚ وَلَنَصْبِرَنَّ عَلَىٰ مَآ ءَاذَيْتُمُونَا ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُتَوَكِّلُونَ','Wa maa lanaa allaa natawakkala \'alal laahi wa qad hadaanaa subulanaa; wa lanasbiranna \'alaa maaa aazaitumoonaa; wa \'alal laahi falyatawakkalil mutawakkiloon',12,'14:12',26,103,212,3,0,257,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1763,14,'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِرُسُلِهِمْ لَنُخْرِجَنَّكُم مِّنْ أَرْضِنَآ أَوْ لَتَعُودُنَّ فِى مِلَّتِنَا ۖ فَأَوْحَىٰٓ إِلَيْهِمْ رَبُّهُمْ لَنُهْلِكَنَّ ٱلظَّـٰلِمِينَ','Wa qaalal lazeena kafaroo li Rusulihim lanukhrijanna kum min aardinaaa aw lata\'oo dunna fee millatinaa fa awhaaa ilaihim Rabbuhum lanuhlikannaz zalimeen',13,'14:13',26,103,213,3,0,257,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1764,14,'وَلَنُسْكِنَنَّكُمُ ٱلْأَرْضَ مِنۢ بَعْدِهِمْ ۚ ذَٰلِكَ لِمَنْ خَافَ مَقَامِى وَخَافَ وَعِيدِ','Wa lanuskinan nakumul arda mim ba\'dihim; zaalika liman khaafa maqaamee wa khaafa wa\'eed',14,'14:14',26,103,213,3,0,257,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1765,14,'وَٱسْتَفْتَحُوا۟ وَخَابَ كُلُّ جَبَّارٍ عَنِيدٍ','Wastaftahoo wa khaaba kullu jabbaarin \'aneed',15,'14:15',26,103,213,3,0,257,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1766,14,'مِّن وَرَآئِهِۦ جَهَنَّمُ وَيُسْقَىٰ مِن مَّآءٍ صَدِيدٍ','Minw waraaa\'ihee jahannamu wa yusqaa mim maaa\'in sadeed',16,'14:16',26,103,213,3,0,257,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1767,14,'يَتَجَرَّعُهُۥ وَلَا يَكَادُ يُسِيغُهُۥ وَيَأْتِيهِ ٱلْمَوْتُ مِن كُلِّ مَكَانٍ وَمَا هُوَ بِمَيِّتٍ ۖ وَمِن وَرَآئِهِۦ عَذَابٌ غَلِيظٌ','Yatajarra\'uhoo wa laa yakaadu yuseeghuhoo wa yaateehil mawtu min kulli makaaninw wa maa huwa bimaiyitinw wa minw waraaa\'ihee \'azaabun ghaleez',17,'14:17',26,103,213,3,0,257,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1768,14,'مَّثَلُ ٱلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ ۖ أَعْمَـٰلُهُمْ كَرَمَادٍ ٱشْتَدَّتْ بِهِ ٱلرِّيحُ فِى يَوْمٍ عَاصِفٍ ۖ لَّا يَقْدِرُونَ مِمَّا كَسَبُوا۟ عَلَىٰ شَىْءٍ ۚ ذَٰلِكَ هُوَ ٱلضَّلَـٰلُ ٱلْبَعِيدُ','Masalul lazeena kafaroo bi Rabbihim a\'maaluhum karamaadinish taddat bihir reehu fee yawmin \'aasif; laa yaqdiroona mimmaa kasaboo \'alaa shai\'; zaalika huwad dalaalul ba\'eed',18,'14:18',26,103,213,3,0,257,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1769,14,'أَلَمْ تَرَ أَنَّ ٱللَّهَ خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ ۚ إِن يَشَأْ يُذْهِبْكُمْ وَيَأْتِ بِخَلْقٍ جَدِيدٍ','Alam tara annal laaha khalaqas samaawaati wal arda bilhaqq; iny yashaa yuzhibkum wa yaati bikhalqin jadeed',19,'14:19',26,103,213,3,0,258,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1770,14,'وَمَا ذَٰلِكَ عَلَى ٱللَّهِ بِعَزِيزٍ','Wa maa zaalika \'alal laahi bi \'azeez',20,'14:20',26,103,213,3,0,258,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1771,14,'وَبَرَزُوا۟ لِلَّهِ جَمِيعًا فَقَالَ ٱلضُّعَفَـٰٓؤُا۟ لِلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا كُنَّا لَكُمْ تَبَعًا فَهَلْ أَنتُم مُّغْنُونَ عَنَّا مِنْ عَذَابِ ٱللَّهِ مِن شَىْءٍ ۚ قَالُوا۟ لَوْ هَدَىٰنَا ٱللَّهُ لَهَدَيْنَـٰكُمْ ۖ سَوَآءٌ عَلَيْنَآ أَجَزِعْنَآ أَمْ صَبَرْنَا مَا لَنَا مِن مَّحِيصٍ','Wa barazoo lillaahi jamee\'an faqaalad du\'afaaa\'u lillazeenas takbarooo innaa kunnaa lakum taba\'an fahal antum mughnoona \'annaa min \'azaabil laahi min shai\'; qaaloo law hadaanal laahu lahadai naakum sawaaa\'un \'alainaaa ajazi\'naa am sabarnaa maa lanaa mim mahees',21,'14:21',26,103,213,3,0,258,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1772,14,'وَقَالَ ٱلشَّيْطَـٰنُ لَمَّا قُضِىَ ٱلْأَمْرُ إِنَّ ٱللَّهَ وَعَدَكُمْ وَعْدَ ٱلْحَقِّ وَوَعَدتُّكُمْ فَأَخْلَفْتُكُمْ ۖ وَمَا كَانَ لِىَ عَلَيْكُم مِّن سُلْطَـٰنٍ إِلَّآ أَن دَعَوْتُكُمْ فَٱسْتَجَبْتُمْ لِى ۖ فَلَا تَلُومُونِى وَلُومُوٓا۟ أَنفُسَكُم ۖ مَّآ أَنَا۠ بِمُصْرِخِكُمْ وَمَآ أَنتُم بِمُصْرِخِىَّ ۖ إِنِّى كَفَرْتُ بِمَآ أَشْرَكْتُمُونِ مِن قَبْلُ ۗ إِنَّ ٱلظَّـٰلِمِينَ لَهُمْ عَذَابٌ أَلِيمٌ','Wa qaalash Shaitaanu lammaa qudiyal amru innal laaha wa\'adakum wa\'dal haqqi wa wa\'attukum faakhlaftukum wa maa kaana liya \'alaikum min sultaanin illaaa an da\'awtukum fastajabtum lee falaa taloomoonee wa loomooo anfusakum maaa ana bimusrikhikum wa maaa antum bimusrikhiyya innee kafartu bimaaa ashraktumooni min qabl; innaz zaalimeena lahum azaabun aleem',22,'14:22',26,103,214,3,0,258,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1773,14,'وَأُدْخِلَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا بِإِذْنِ رَبِّهِمْ ۖ تَحِيَّتُهُمْ فِيهَا سَلَـٰمٌ','Wa udkhilal lazeena aamanoo wa \'amilus saalihaati Jannaatin tajree min tahtihal anhaaru khaalideena feehaa bi izni Rabbihim tahiyyatuhum feeha salaam',23,'14:23',26,103,214,3,0,258,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1774,14,'أَلَمْ تَرَ كَيْفَ ضَرَبَ ٱللَّهُ مَثَلًا كَلِمَةً طَيِّبَةً كَشَجَرَةٍ طَيِّبَةٍ أَصْلُهَا ثَابِتٌ وَفَرْعُهَا فِى ٱلسَّمَآءِ','Alam tara kaifa darabal laahu masalan kalimatan taiyibatan kashajaratin taiyibatin asluhaa saabitunw wa far\'uhaa fis samaaa\'',24,'14:24',26,103,214,3,0,258,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1775,14,'تُؤْتِىٓ أُكُلَهَا كُلَّ حِينٍۭ بِإِذْنِ رَبِّهَا ۗ وَيَضْرِبُ ٱللَّهُ ٱلْأَمْثَالَ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ','Tu\'teee ukulahaa kulla heenim bi izni Rabbihaa; wa yadribul laahul amsaala linnaasi la\'allahum yatazak karoon',25,'14:25',26,103,214,3,0,259,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1776,14,'وَمَثَلُ كَلِمَةٍ خَبِيثَةٍ كَشَجَرَةٍ خَبِيثَةٍ ٱجْتُثَّتْ مِن فَوْقِ ٱلْأَرْضِ مَا لَهَا مِن قَرَارٍ','Wa masalu kalimatin khabeesatin kashajaratin khabee satinij tussat min fawqil ardi maa lahaa min qaraar',26,'14:26',26,103,214,3,0,259,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1777,14,'يُثَبِّتُ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ بِٱلْقَوْلِ ٱلثَّابِتِ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْـَٔاخِرَةِ ۖ وَيُضِلُّ ٱللَّهُ ٱلظَّـٰلِمِينَ ۚ وَيَفْعَلُ ٱللَّهُ مَا يَشَآءُ','Yusabbitul laahul lazeena aamanoo bilqawlis saabiti fil hayaatid dunyaa wa fil Aakhirati wa yudillul laahuz zaalimeen; wa yaf\'alul laahu maa yashaaa\'',27,'14:27',26,103,214,3,0,259,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1778,14,'۞ أَلَمْ تَرَ إِلَى ٱلَّذِينَ بَدَّلُوا۟ نِعْمَتَ ٱللَّهِ كُفْرًا وَأَحَلُّوا۟ قَوْمَهُمْ دَارَ ٱلْبَوَارِ','Alam tara ilal lazeena baddaloo ni\'matal laahi kufranw wa ahalloo qawmahum daaral bawaar',28,'14:28',26,104,215,3,0,259,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1779,14,'جَهَنَّمَ يَصْلَوْنَهَا ۖ وَبِئْسَ ٱلْقَرَارُ','Jahannama yaslawnahaa wa bi\'sal qaraar',29,'14:29',26,104,215,3,0,259,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1780,14,'وَجَعَلُوا۟ لِلَّهِ أَندَادًا لِّيُضِلُّوا۟ عَن سَبِيلِهِۦ ۗ قُلْ تَمَتَّعُوا۟ فَإِنَّ مَصِيرَكُمْ إِلَى ٱلنَّارِ','Wa ja\'aloo lillaahi andaadal liyudilloo \'an sabeelih; qul tamatta\'oo fa innaa maseerakum ilan Naar',30,'14:30',26,104,215,3,0,259,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1781,14,'قُل لِّعِبَادِىَ ٱلَّذِينَ ءَامَنُوا۟ يُقِيمُوا۟ ٱلصَّلَوٰةَ وَيُنفِقُوا۟ مِمَّا رَزَقْنَـٰهُمْ سِرًّا وَعَلَانِيَةً مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا خِلَـٰلٌ','Qul li\'ibaadiyal lazeena aamanoo yuqeemus Salaata wa yunfiqoo mimmaa razaqnaahum sirranw wa \'alaaniyatam min qabli any yaatiya Yawmul laa bai\'un feehi wa laa khilaal',31,'14:31',26,104,215,3,0,259,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1782,14,'ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزْقًا لَّكُمْ ۖ وَسَخَّرَ لَكُمُ ٱلْفُلْكَ لِتَجْرِىَ فِى ٱلْبَحْرِ بِأَمْرِهِۦ ۖ وَسَخَّرَ لَكُمُ ٱلْأَنْهَـٰرَ','Allaahul lazee khalaqas samaawaati wal arda wa anzala minas samaaa\'i maaa\'an faakhraja bihee minas samaraati rizqal lakum wa sakhkhara lakumul fulka litajriya fil bahri bi amrihee wa sakhkhara lakumul anhaar',32,'14:32',26,104,215,3,0,259,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1783,14,'وَسَخَّرَ لَكُمُ ٱلشَّمْسَ وَٱلْقَمَرَ دَآئِبَيْنِ ۖ وَسَخَّرَ لَكُمُ ٱلَّيْلَ وَٱلنَّهَارَ','Wa sakhkhara lakumush shamsa walqamara daaa\'ibaini wa sakhkhara lakumul laila wannahaar',33,'14:33',26,104,215,3,0,259,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1784,14,'وَءَاتَىٰكُم مِّن كُلِّ مَا سَأَلْتُمُوهُ ۚ وَإِن تَعُدُّوا۟ نِعْمَتَ ٱللَّهِ لَا تُحْصُوهَآ ۗ إِنَّ ٱلْإِنسَـٰنَ لَظَلُومٌ كَفَّارٌ','Wa aataakum min kulli maa sa altumooh; wa in ta\'uddoo ni\'matal laahi laa tuhsoohaa; innal insaana lazaloo mun kaffaar',34,'14:34',26,104,215,3,0,260,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1785,14,'وَإِذْ قَالَ إِبْرَٰهِيمُ رَبِّ ٱجْعَلْ هَـٰذَا ٱلْبَلَدَ ءَامِنًا وَٱجْنُبْنِى وَبَنِىَّ أَن نَّعْبُدَ ٱلْأَصْنَامَ','Wa iz qaala Ibraaheemu Rabbij \'al haazal balada aaminanw wajnubnee wa baniyya an na\'budal asnaam',35,'14:35',26,104,216,3,0,260,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1786,14,'رَبِّ إِنَّهُنَّ أَضْلَلْنَ كَثِيرًا مِّنَ ٱلنَّاسِ ۖ فَمَن تَبِعَنِى فَإِنَّهُۥ مِنِّى ۖ وَمَنْ عَصَانِى فَإِنَّكَ غَفُورٌ رَّحِيمٌ','Rabbi innahunna adlalna kaseeram minan naasi faman tabi\'anee fa innahoo minnee wa man \'asaanee fa innaka Ghafoorur Raheem',36,'14:36',26,104,216,3,0,260,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1787,14,'رَّبَّنَآ إِنِّىٓ أَسْكَنتُ مِن ذُرِّيَّتِى بِوَادٍ غَيْرِ ذِى زَرْعٍ عِندَ بَيْتِكَ ٱلْمُحَرَّمِ رَبَّنَا لِيُقِيمُوا۟ ٱلصَّلَوٰةَ فَٱجْعَلْ أَفْـِٔدَةً مِّنَ ٱلنَّاسِ تَهْوِىٓ إِلَيْهِمْ وَٱرْزُقْهُم مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمْ يَشْكُرُونَ','Rabbanaaa inneee askantu min zurriyyatee biwaadin ghairi zee zar\'in \'inda Baitikal Muharrami Rabbanaa liyuqeemus Salaata faj\'al af\'idatam minan naasi tahweee ilaihim warzuqhum minas samaraati la\'allahum yashkuroon',37,'14:37',26,104,216,3,0,260,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1788,14,'رَبَّنَآ إِنَّكَ تَعْلَمُ مَا نُخْفِى وَمَا نُعْلِنُ ۗ وَمَا يَخْفَىٰ عَلَى ٱللَّهِ مِن شَىْءٍ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ','Rabbanaaa innaka ta\'lamu maa nukhfee wa maa nu\'lin; wa maa yakhfaa \'alal laahi min shai\'in fil ardi wa laa fis samaaa\'',38,'14:38',26,104,216,3,0,260,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1789,14,'ٱلْحَمْدُ لِلَّهِ ٱلَّذِى وَهَبَ لِى عَلَى ٱلْكِبَرِ إِسْمَـٰعِيلَ وَإِسْحَـٰقَ ۚ إِنَّ رَبِّى لَسَمِيعُ ٱلدُّعَآءِ','Alhamdu lillaahil lazee wahaba lee \'alal kibari Ismaa\'eela wa Ishaaq; inna Rabbee lasamee\'ud du\'aaa',39,'14:39',26,104,216,3,0,260,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1790,14,'رَبِّ ٱجْعَلْنِى مُقِيمَ ٱلصَّلَوٰةِ وَمِن ذُرِّيَّتِى ۚ رَبَّنَا وَتَقَبَّلْ دُعَآءِ','Rabbij \'alnee muqeemas Salaati wa min zurriyyatee Rabbanaa wa taqabbal du\'aaa\'',40,'14:40',26,104,216,3,0,260,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1791,14,'رَبَّنَا ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ ٱلْحِسَابُ','Rabbanagh fir lee wa liwaalidaiya wa lilmu\'mineena Yawma yaqoomul hisaab',41,'14:41',26,104,216,3,0,260,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1792,14,'وَلَا تَحْسَبَنَّ ٱللَّهَ غَـٰفِلًا عَمَّا يَعْمَلُ ٱلظَّـٰلِمُونَ ۚ إِنَّمَا يُؤَخِّرُهُمْ لِيَوْمٍ تَشْخَصُ فِيهِ ٱلْأَبْصَـٰرُ','Wa laa tahsabannal laaha ghaafilan \'ammaa ya\'maluz zaalimoon; innamaa yu\'akh khiruhum li Yawmin tashkhasu feehil absaar',42,'14:42',26,104,217,3,0,260,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1793,14,'مُهْطِعِينَ مُقْنِعِى رُءُوسِهِمْ لَا يَرْتَدُّ إِلَيْهِمْ طَرْفُهُمْ ۖ وَأَفْـِٔدَتُهُمْ هَوَآءٌ','Muhti\'eena muqni\'ee ru\'oosihim laa yartaddu ilaihim tarfuhum wa af\'idatuhum hawaaa\'',43,'14:43',26,104,217,3,0,261,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1794,14,'وَأَنذِرِ ٱلنَّاسَ يَوْمَ يَأْتِيهِمُ ٱلْعَذَابُ فَيَقُولُ ٱلَّذِينَ ظَلَمُوا۟ رَبَّنَآ أَخِّرْنَآ إِلَىٰٓ أَجَلٍ قَرِيبٍ نُّجِبْ دَعْوَتَكَ وَنَتَّبِعِ ٱلرُّسُلَ ۗ أَوَلَمْ تَكُونُوٓا۟ أَقْسَمْتُم مِّن قَبْلُ مَا لَكُم مِّن زَوَالٍ','Wa anzirin naasa Yawma yaateehimul \'azaabu fa yaqoolul lazeena zalamoo Rabbanaaa akhkhirnaaa ilaaa ajalin qareebin nujib da\'wataka wa nattabi \'ir Rusul; awalam takoonooo aqsamtum min qablu maa lakum min zawaal',44,'14:44',26,104,217,3,0,261,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1795,14,'وَسَكَنتُمْ فِى مَسَـٰكِنِ ٱلَّذِينَ ظَلَمُوٓا۟ أَنفُسَهُمْ وَتَبَيَّنَ لَكُمْ كَيْفَ فَعَلْنَا بِهِمْ وَضَرَبْنَا لَكُمُ ٱلْأَمْثَالَ','Wa sakantum fee masaakinil lazeena zalamooo anfusahum wa tabaiyana lakum kaifa fa\'alnaa bihim wa darabnaa lakumul amsaal',45,'14:45',26,104,217,3,0,261,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1796,14,'وَقَدْ مَكَرُوا۟ مَكْرَهُمْ وَعِندَ ٱللَّهِ مَكْرُهُمْ وَإِن كَانَ مَكْرُهُمْ لِتَزُولَ مِنْهُ ٱلْجِبَالُ','Wa qad makaroo makrahum wa \'indal laahi makruhum wa in kaana makruhum litazoola minhul jibaal',46,'14:46',26,104,217,3,0,261,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1797,14,'فَلَا تَحْسَبَنَّ ٱللَّهَ مُخْلِفَ وَعْدِهِۦ رُسُلَهُۥٓ ۗ إِنَّ ٱللَّهَ عَزِيزٌ ذُو ٱنتِقَامٍ','Falaa tahsabannal laaha mukhlifa wa\'dihee Rusulah; innal laaha \'azeezun zuntiqaam',47,'14:47',26,104,217,3,0,261,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1798,14,'يَوْمَ تُبَدَّلُ ٱلْأَرْضُ غَيْرَ ٱلْأَرْضِ وَٱلسَّمَـٰوَٰتُ ۖ وَبَرَزُوا۟ لِلَّهِ ٱلْوَٰحِدِ ٱلْقَهَّارِ','Yawma tubaddalul ardu ghairal ardi wassamaawaatu wa barazoo lillaahil Waahidil Qahhaar',48,'14:48',26,104,217,3,0,261,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1799,14,'وَتَرَى ٱلْمُجْرِمِينَ يَوْمَئِذٍ مُّقَرَّنِينَ فِى ٱلْأَصْفَادِ','Wa taral mujrimeena Yawma \'izim muqarraneena filasfaad',49,'14:49',26,104,217,3,0,261,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1800,14,'سَرَابِيلُهُم مِّن قَطِرَانٍ وَتَغْشَىٰ وُجُوهَهُمُ ٱلنَّارُ','Saraabeeluhum min qatiraaninw wa taghshaa wujoohahumun Naar',50,'14:50',26,104,217,3,0,261,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1801,14,'لِيَجْزِىَ ٱللَّهُ كُلَّ نَفْسٍ مَّا كَسَبَتْ ۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ','Liyajziyal laahu kulla nafsim maa kasabat; innal laaha saree\'ul hisaab',51,'14:51',26,104,217,3,0,261,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1802,14,'هَـٰذَا بَلَـٰغٌ لِّلنَّاسِ وَلِيُنذَرُوا۟ بِهِۦ وَلِيَعْلَمُوٓا۟ أَنَّمَا هُوَ إِلَـٰهٌ وَٰحِدٌ وَلِيَذَّكَّرَ أُو۟لُوا۟ ٱلْأَلْبَـٰبِ','Haaza balaaghul linnaasi wa liyunzaroo bihee wa liya\'lamooo annamaa Huwa Illaahunw Waahidunw wa liyaz zakkara ulul albaab',52,'14:52',26,104,217,3,0,261,13,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1803,15,'الٓر ۚ تِلْكَ ءَايَـٰتُ ٱلْكِتَـٰبِ وَقُرْءَانٍ مُّبِينٍ','Alif-Laaam-Raa; tilka Aayaatul Kitaabi wa Qur-aa-nim Mubeen',1,'15:1',27,105,218,3,0,262,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1804,15,'رُّبَمَا يَوَدُّ ٱلَّذِينَ كَفَرُوا۟ لَوْ كَانُوا۟ مُسْلِمِينَ','Rubamaa yawaddul lazeena kafaroo law kaanoo muslimeen',2,'15:2',27,105,218,3,0,262,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1805,15,'ذَرْهُمْ يَأْكُلُوا۟ وَيَتَمَتَّعُوا۟ وَيُلْهِهِمُ ٱلْأَمَلُ ۖ فَسَوْفَ يَعْلَمُونَ','Zarhum yaakuloo wa tatamatta\'oo wa yulhihimul amalu fasawfa ya\'lamoon',3,'15:3',27,105,218,3,0,262,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1806,15,'وَمَآ أَهْلَكْنَا مِن قَرْيَةٍ إِلَّا وَلَهَا كِتَابٌ مَّعْلُومٌ','Wa maaa ahlaknaa min qaryatin illaa wa lahaa kitaabum ma\'loom',4,'15:4',27,105,218,3,0,262,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1807,15,'مَّا تَسْبِقُ مِنْ أُمَّةٍ أَجَلَهَا وَمَا يَسْتَـْٔخِرُونَ','Maa tasbiqu min ummatin ajalahaa wa maa yastaakhiroon',5,'15:5',27,105,218,3,0,262,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1808,15,'وَقَالُوا۟ يَـٰٓأَيُّهَا ٱلَّذِى نُزِّلَ عَلَيْهِ ٱلذِّكْرُ إِنَّكَ لَمَجْنُونٌ','Wa qaaloo yaaa aiyuhal lazee nuzzila \'alaihiz Zikru innaka lamajnoon',6,'15:6',27,105,218,3,0,262,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1809,15,'لَّوْ مَا تَأْتِينَا بِٱلْمَلَـٰٓئِكَةِ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ','Law maa taateenaa bil malaaa\'ikati in kunta minas saadiqeen',7,'15:7',27,105,218,3,0,262,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1810,15,'مَا نُنَزِّلُ ٱلْمَلَـٰٓئِكَةَ إِلَّا بِٱلْحَقِّ وَمَا كَانُوٓا۟ إِذًا مُّنظَرِينَ','Maa nunazzilul malaaa\'i kata illaa bilhaqqi wa maa kaanooo izam munzareen',8,'15:8',27,105,218,3,0,262,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1811,15,'إِنَّا نَحْنُ نَزَّلْنَا ٱلذِّكْرَ وَإِنَّا لَهُۥ لَحَـٰفِظُونَ','Innaa Nahnu nazalnaz Zikra wa Innaa lahoo lahaa fizoon',9,'15:9',27,105,218,3,0,262,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1812,15,'وَلَقَدْ أَرْسَلْنَا مِن قَبْلِكَ فِى شِيَعِ ٱلْأَوَّلِينَ','Wa laqad arsalnaa min qablika fee shiya\'il awwaleen',10,'15:10',27,105,218,3,0,262,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1813,15,'وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ','Wa maa yaateehim mir Rasoolin illaa kaanoo bihee yastahzi\'oon',11,'15:11',27,105,218,3,0,262,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1814,15,'كَذَٰلِكَ نَسْلُكُهُۥ فِى قُلُوبِ ٱلْمُجْرِمِينَ','kazaalika naslukuhoo fee quloobil mujrimeen',12,'15:12',27,105,218,3,0,262,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1815,15,'لَا يُؤْمِنُونَ بِهِۦ ۖ وَقَدْ خَلَتْ سُنَّةُ ٱلْأَوَّلِينَ','Laa yu\'minoona bihee wa qad khalat sunnatul awwaleen',13,'15:13',27,105,218,3,0,262,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1816,15,'وَلَوْ فَتَحْنَا عَلَيْهِم بَابًا مِّنَ ٱلسَّمَآءِ فَظَلُّوا۟ فِيهِ يَعْرُجُونَ','Wa law fatahnaa \'alaihim baabam minas samaaa\'i fazaloo feehi ya\'rujoon',14,'15:14',27,105,218,3,0,262,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1817,15,'لَقَالُوٓا۟ إِنَّمَا سُكِّرَتْ أَبْصَـٰرُنَا بَلْ نَحْنُ قَوْمٌ مَّسْحُورُونَ','Laqaaloo innamaa sukkirat absaarunaa bal nahnu qawmum mashooroon',15,'15:15',27,105,218,3,0,262,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1818,15,'وَلَقَدْ جَعَلْنَا فِى ٱلسَّمَآءِ بُرُوجًا وَزَيَّنَّـٰهَا لِلنَّـٰظِرِينَ','Wa laqad ja\'alnaa fissamaaa\'i buroojanw wa zaiyannaahaa linnaazireen',16,'15:16',27,105,219,3,0,263,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1819,15,'وَحَفِظْنَـٰهَا مِن كُلِّ شَيْطَـٰنٍ رَّجِيمٍ','Wa hafiznaahaa min kulli Shaitaanir rajeem',17,'15:17',27,105,219,3,0,263,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1820,15,'إِلَّا مَنِ ٱسْتَرَقَ ٱلسَّمْعَ فَأَتْبَعَهُۥ شِهَابٌ مُّبِينٌ','Illaa manis taraqas sam\'a fa atba\'ahoo shihaabum mubeen',18,'15:18',27,105,219,3,0,263,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1821,15,'وَٱلْأَرْضَ مَدَدْنَـٰهَا وَأَلْقَيْنَا فِيهَا رَوَٰسِىَ وَأَنۢبَتْنَا فِيهَا مِن كُلِّ شَىْءٍ مَّوْزُونٍ','Wal arda madadnaahaa wa alqainaa feehaa rawaasiya wa ambatnaa feehaa min kulli shai\'im mawzoon',19,'15:19',27,105,219,3,0,263,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1822,15,'وَجَعَلْنَا لَكُمْ فِيهَا مَعَـٰيِشَ وَمَن لَّسْتُمْ لَهُۥ بِرَٰزِقِينَ','Wa ja\'alnaa lakum feehaa ma\'aayisha wa mal lastum lahoo biraaziqeen',20,'15:20',27,105,219,3,0,263,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1823,15,'وَإِن مِّن شَىْءٍ إِلَّا عِندَنَا خَزَآئِنُهُۥ وَمَا نُنَزِّلُهُۥٓ إِلَّا بِقَدَرٍ مَّعْلُومٍ','Wa im min shai\'in illaa \'indanaa khazaaa \'inuhoo wa maa nunazziluhooo illaa biqadarim ma\'loom',21,'15:21',27,105,219,3,0,263,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1824,15,'وَأَرْسَلْنَا ٱلرِّيَـٰحَ لَوَٰقِحَ فَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءً فَأَسْقَيْنَـٰكُمُوهُ وَمَآ أَنتُمْ لَهُۥ بِخَـٰزِنِينَ','Wa arsalnar riyaaha la waaqiha fa anzalnaa minas samaaa\'i maaa\'an fa asqai naakumoohu wa maaa antum lahoo bikhaazineen',22,'15:22',27,105,219,3,0,263,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1825,15,'وَإِنَّا لَنَحْنُ نُحْىِۦ وَنُمِيتُ وَنَحْنُ ٱلْوَٰرِثُونَ','Wa innnaa la nahnu nuhyee wa numeetu wa nahnul waarisoon',23,'15:23',27,105,219,3,0,263,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1826,15,'وَلَقَدْ عَلِمْنَا ٱلْمُسْتَقْدِمِينَ مِنكُمْ وَلَقَدْ عَلِمْنَا ٱلْمُسْتَـْٔخِرِينَ','Wa la qad \'alimnal mustaqdimeena minkum wa laqad \'alimnal mustaakhireen',24,'15:24',27,105,219,3,0,263,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1827,15,'وَإِنَّ رَبَّكَ هُوَ يَحْشُرُهُمْ ۚ إِنَّهُۥ حَكِيمٌ عَلِيمٌ','Wa inna Rabbaka Huwa yahshuruhum; innahoo Hakeem \'Aleem',25,'15:25',27,105,219,3,0,263,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1828,15,'وَلَقَدْ خَلَقْنَا ٱلْإِنسَـٰنَ مِن صَلْصَـٰلٍ مِّنْ حَمَإٍ مَّسْنُونٍ','Wa laqad khalaqnal insaana min salsaalim min hama im masnoon',26,'15:26',27,105,220,3,0,263,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1829,15,'وَٱلْجَآنَّ خَلَقْنَـٰهُ مِن قَبْلُ مِن نَّارِ ٱلسَّمُومِ','Waljaaanna khalaqnaahu min qablu min naaris samoom',27,'15:27',27,105,220,3,0,263,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1830,15,'وَإِذْ قَالَ رَبُّكَ لِلْمَلَـٰٓئِكَةِ إِنِّى خَـٰلِقٌۢ بَشَرًا مِّن صَلْصَـٰلٍ مِّنْ حَمَإٍ مَّسْنُونٍ','Wa iz qaala Rabbuka lilmalaaa\' ikati innee khaaliqum basharam min salsaalim min hama im masnoon',28,'15:28',27,105,220,3,0,263,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1831,15,'فَإِذَا سَوَّيْتُهُۥ وَنَفَخْتُ فِيهِ مِن رُّوحِى فَقَعُوا۟ لَهُۥ سَـٰجِدِينَ','Fa izaa sawwaituhoo wa nafakhtu feehi mir roohee faqa\'oo lahoo saajideen',29,'15:29',27,105,220,3,0,263,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1832,15,'فَسَجَدَ ٱلْمَلَـٰٓئِكَةُ كُلُّهُمْ أَجْمَعُونَ','Fasajadal malaaa\'ikatu kulluhum ajma\'oon',30,'15:30',27,105,220,3,0,263,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1833,15,'إِلَّآ إِبْلِيسَ أَبَىٰٓ أَن يَكُونَ مَعَ ٱلسَّـٰجِدِينَ','Illaaa ibleesa abaaa ai yakoona ma\'as saajideen',31,'15:31',27,105,220,3,0,263,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1834,15,'قَالَ يَـٰٓإِبْلِيسُ مَا لَكَ أَلَّا تَكُونَ مَعَ ٱلسَّـٰجِدِينَ','Qaala yaaa Ibleesu maa laka allaa takoona ma\'as saajideen',32,'15:32',27,105,220,3,0,264,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1835,15,'قَالَ لَمْ أَكُن لِّأَسْجُدَ لِبَشَرٍ خَلَقْتَهُۥ مِن صَلْصَـٰلٍ مِّنْ حَمَإٍ مَّسْنُونٍ','Qaala lam akul li asjuda libasharin khalaqtahoo min salsaalim min hama im masnoon',33,'15:33',27,105,220,3,0,264,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1836,15,'قَالَ فَٱخْرُجْ مِنْهَا فَإِنَّكَ رَجِيمٌ','Qaala fakhruj minhaa fa innaka rajeem',34,'15:34',27,105,220,3,0,264,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1837,15,'وَإِنَّ عَلَيْكَ ٱللَّعْنَةَ إِلَىٰ يَوْمِ ٱلدِّينِ','Wa inna \'alikal la\'nata ilaa Yawmid Deen',35,'15:35',27,105,220,3,0,264,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1838,15,'قَالَ رَبِّ فَأَنظِرْنِىٓ إِلَىٰ يَوْمِ يُبْعَثُونَ','Qaala Rabbi fa anzirneee ilaa Yawmi yub\'asoon',36,'15:36',27,105,220,3,0,264,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1839,15,'قَالَ فَإِنَّكَ مِنَ ٱلْمُنظَرِينَ','Qaala fa innaka minal munzareen',37,'15:37',27,105,220,3,0,264,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1840,15,'إِلَىٰ يَوْمِ ٱلْوَقْتِ ٱلْمَعْلُومِ','Ilaa Yawmil waqtil ma\'loom',38,'15:38',27,105,220,3,0,264,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1841,15,'قَالَ رَبِّ بِمَآ أَغْوَيْتَنِى لَأُزَيِّنَنَّ لَهُمْ فِى ٱلْأَرْضِ وَلَأُغْوِيَنَّهُمْ أَجْمَعِينَ','Qaala Rabbi bimaaa aghwaitanee la uzayyinaana lahum fil ardi wa la ughwiyan nahum ajma\'een',39,'15:39',27,105,220,3,0,264,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1842,15,'إِلَّا عِبَادَكَ مِنْهُمُ ٱلْمُخْلَصِينَ','Illaa \'ibaadaka minhumul mukhlaseen',40,'15:40',27,105,220,3,0,264,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1843,15,'قَالَ هَـٰذَا صِرَٰطٌ عَلَىَّ مُسْتَقِيمٌ','Qaala haaza Siraatun \'alaiya Mustaqeem',41,'15:41',27,105,220,3,0,264,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1844,15,'إِنَّ عِبَادِى لَيْسَ لَكَ عَلَيْهِمْ سُلْطَـٰنٌ إِلَّا مَنِ ٱتَّبَعَكَ مِنَ ٱلْغَاوِينَ','Inna \'ibaadee laisa laka \'alaihim sultaanun illaa manittaba\'aka minal ghaaween',42,'15:42',27,105,220,3,0,264,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1845,15,'وَإِنَّ جَهَنَّمَ لَمَوْعِدُهُمْ أَجْمَعِينَ','Wa inna jahannama lamaw\'iduhum ajma\'een',43,'15:43',27,105,220,3,0,264,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1846,15,'لَهَا سَبْعَةُ أَبْوَٰبٍ لِّكُلِّ بَابٍ مِّنْهُمْ جُزْءٌ مَّقْسُومٌ','Lahaa sab\'atu abwaab; likulli baabim minhum juz\'um maqsoom',44,'15:44',27,105,220,3,0,264,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1847,15,'إِنَّ ٱلْمُتَّقِينَ فِى جَنَّـٰتٍ وَعُيُونٍ','Innal muttaqeena fee Jannaatinw wa \'uyoon',45,'15:45',27,105,221,3,0,264,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1848,15,'ٱدْخُلُوهَا بِسَلَـٰمٍ ءَامِنِينَ','Udkhuloohaa bisalaamin aamineen',46,'15:46',27,105,221,3,0,264,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1849,15,'وَنَزَعْنَا مَا فِى صُدُورِهِم مِّنْ غِلٍّ إِخْوَٰنًا عَلَىٰ سُرُرٍ مُّتَقَـٰبِلِينَ','Wa naza\'naa ma fee sudoorihim min ghillin ikhwaanan \'alaa sururim mutaqaabileen',47,'15:47',27,105,221,3,0,264,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1850,15,'لَا يَمَسُّهُمْ فِيهَا نَصَبٌ وَمَا هُم مِّنْهَا بِمُخْرَجِينَ','Laa yamas suhum feehaa nasabunw wa maa hum minhaa bimukhrajeen',48,'15:48',27,105,221,3,0,264,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1851,15,'۞ نَبِّئْ عِبَادِىٓ أَنِّىٓ أَنَا ٱلْغَفُورُ ٱلرَّحِيمُ','Nabbi\' \'ibaadeee annneee anal Ghafoorur Raheem',49,'15:49',27,106,221,3,0,264,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1852,15,'وَأَنَّ عَذَابِى هُوَ ٱلْعَذَابُ ٱلْأَلِيمُ','Wa anna \'azaabee uwal \'azaabul aleem',50,'15:50',27,106,221,3,0,264,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1853,15,'وَنَبِّئْهُمْ عَن ضَيْفِ إِبْرَٰهِيمَ','Wa nabbi\'hum \'an daifi Ibraaheem',51,'15:51',27,106,221,3,0,264,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1854,15,'إِذْ دَخَلُوا۟ عَلَيْهِ فَقَالُوا۟ سَلَـٰمًا قَالَ إِنَّا مِنكُمْ وَجِلُونَ','Iz dakhaloo \'alaihi faqaaloo salaaman qaala innaa minkum wajiloon',52,'15:52',27,106,221,3,0,265,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1855,15,'قَالُوا۟ لَا تَوْجَلْ إِنَّا نُبَشِّرُكَ بِغُلَـٰمٍ عَلِيمٍ','Qaaloo la tawjal innaa nubashshiruka bighulaamin \'aleem',53,'15:53',27,106,221,3,0,265,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1856,15,'قَالَ أَبَشَّرْتُمُونِى عَلَىٰٓ أَن مَّسَّنِىَ ٱلْكِبَرُ فَبِمَ تُبَشِّرُونَ','Qaala abashshartumoonee \'alaaa am massaniyal kibaru fabima tubashshiroon',54,'15:54',27,106,221,3,0,265,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1857,15,'قَالُوا۟ بَشَّرْنَـٰكَ بِٱلْحَقِّ فَلَا تَكُن مِّنَ ٱلْقَـٰنِطِينَ','Qaaloo bashsharnaaka bilhaqqi falaa takum minal qaaniteen',55,'15:55',27,106,221,3,0,265,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1858,15,'قَالَ وَمَن يَقْنَطُ مِن رَّحْمَةِ رَبِّهِۦٓ إِلَّا ٱلضَّآلُّونَ','Qaala wa mai yaqnatu mir rahmati Rabbiheee illad daaaloon',56,'15:56',27,106,221,3,0,265,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1859,15,'قَالَ فَمَا خَطْبُكُمْ أَيُّهَا ٱلْمُرْسَلُونَ','Qaala famaa khatbukum aiyuhal mursaloon',57,'15:57',27,106,221,3,0,265,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1860,15,'قَالُوٓا۟ إِنَّآ أُرْسِلْنَآ إِلَىٰ قَوْمٍ مُّجْرِمِينَ','Qaaloo innaaa ursilnaaa ilaa qawmim mujrimeen',58,'15:58',27,106,221,3,0,265,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1861,15,'إِلَّآ ءَالَ لُوطٍ إِنَّا لَمُنَجُّوهُمْ أَجْمَعِينَ','Illaaa Aala Loot; innaa lamunajjoohum ajma\'een',59,'15:59',27,106,221,3,0,265,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1862,15,'إِلَّا ٱمْرَأَتَهُۥ قَدَّرْنَآ ۙ إِنَّهَا لَمِنَ ٱلْغَـٰبِرِينَ','Illam ra atahoo qaddarnaaa innahaa laminal ghaabireen',60,'15:60',27,106,221,3,0,265,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1863,15,'فَلَمَّا جَآءَ ءَالَ لُوطٍ ٱلْمُرْسَلُونَ','Falamma jaaa\'a Aala Lootinil mursaloon',61,'15:61',27,106,222,3,0,265,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1864,15,'قَالَ إِنَّكُمْ قَوْمٌ مُّنكَرُونَ','Qaala innakum qawmum munkaroon',62,'15:62',27,106,222,3,0,265,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1865,15,'قَالُوا۟ بَلْ جِئْنَـٰكَ بِمَا كَانُوا۟ فِيهِ يَمْتَرُونَ','Qaaloo bal ji\'naaka bimaa kaanoo feehi yamtaroon',63,'15:63',27,106,222,3,0,265,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1866,15,'وَأَتَيْنَـٰكَ بِٱلْحَقِّ وَإِنَّا لَصَـٰدِقُونَ','Wa atainaaka bilhaqqi wa innaa lasaadiqoon',64,'15:64',27,106,222,3,0,265,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1867,15,'فَأَسْرِ بِأَهْلِكَ بِقِطْعٍ مِّنَ ٱلَّيْلِ وَٱتَّبِعْ أَدْبَـٰرَهُمْ وَلَا يَلْتَفِتْ مِنكُمْ أَحَدٌ وَٱمْضُوا۟ حَيْثُ تُؤْمَرُونَ','Fa asri bi ahlika biqit\'im minal laili wattabi\' adbaarahum wa laa yaltafit minkum ahadunw wamdoo haisu tu\'maroon',65,'15:65',27,106,222,3,0,265,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1868,15,'وَقَضَيْنَآ إِلَيْهِ ذَٰلِكَ ٱلْأَمْرَ أَنَّ دَابِرَ هَـٰٓؤُلَآءِ مَقْطُوعٌ مُّصْبِحِينَ','Wa qadainaaa ilaihi zaalikal amra anna daabira haaa\'ulaaa\'i maqtoo\'um musbiheen',66,'15:66',27,106,222,3,0,265,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1869,15,'وَجَآءَ أَهْلُ ٱلْمَدِينَةِ يَسْتَبْشِرُونَ','Wa jaaa\'a ahlul madeenati yastabshiroon',67,'15:67',27,106,222,3,0,265,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1870,15,'قَالَ إِنَّ هَـٰٓؤُلَآءِ ضَيْفِى فَلَا تَفْضَحُونِ','Qaala inna haaa\'ulaaa\'i daifee falaa tafdahoon',68,'15:68',27,106,222,3,0,265,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1871,15,'وَٱتَّقُوا۟ ٱللَّهَ وَلَا تُخْزُونِ','Wattaqul laaha wa laa tukhzoon',69,'15:69',27,106,222,3,0,265,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1872,15,'قَالُوٓا۟ أَوَلَمْ نَنْهَكَ عَنِ ٱلْعَـٰلَمِينَ','Qaalooo awalam nanhaka \'anil \'aalameen',70,'15:70',27,106,222,3,0,265,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1873,15,'قَالَ هَـٰٓؤُلَآءِ بَنَاتِىٓ إِن كُنتُمْ فَـٰعِلِينَ','Qaala haaa\'ulaaa\'i banaateee in kuntum faa\'ileen',71,'15:71',27,106,222,3,0,266,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1874,15,'لَعَمْرُكَ إِنَّهُمْ لَفِى سَكْرَتِهِمْ يَعْمَهُونَ','La\'amruka innahum lafee sakratihim ya\'mahoon',72,'15:72',27,106,222,3,0,266,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1875,15,'فَأَخَذَتْهُمُ ٱلصَّيْحَةُ مُشْرِقِينَ','Fa akhazat humus saihatu mushriqeen',73,'15:73',27,106,222,3,0,266,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1876,15,'فَجَعَلْنَا عَـٰلِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهِمْ حِجَارَةً مِّن سِجِّيلٍ','Faja\'alnaa \'aaliyahaa saafilahaa wa amtamaa \'alaihim hijaaratam min sjijjeel',74,'15:74',27,106,222,3,0,266,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1877,15,'إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّلْمُتَوَسِّمِينَ','Inna fee zaalika la Aayaatil lilmutawassimeen',75,'15:75',27,106,222,3,0,266,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1878,15,'وَإِنَّهَا لَبِسَبِيلٍ مُّقِيمٍ','Wa innahaa labi sabeelim muqeem',76,'15:76',27,106,222,3,0,266,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1879,15,'إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّلْمُؤْمِنِينَ','Inna fee zaalika la Aayatal lilmu\'mineen',77,'15:77',27,106,222,3,0,266,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1880,15,'وَإِن كَانَ أَصْحَـٰبُ ٱلْأَيْكَةِ لَظَـٰلِمِينَ','Wa in kaana Ashaabul Aikati lazaalimeen',78,'15:78',27,106,222,3,0,266,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1881,15,'فَٱنتَقَمْنَا مِنْهُمْ وَإِنَّهُمَا لَبِإِمَامٍ مُّبِينٍ','Fantaqamnaa minhum wa innahumaa labi imaamim mubeen',79,'15:79',27,106,222,3,0,266,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1882,15,'وَلَقَدْ كَذَّبَ أَصْحَـٰبُ ٱلْحِجْرِ ٱلْمُرْسَلِينَ','Wa laqad kazzaba ashaabul Hijril mursaleen',80,'15:80',27,106,223,3,0,266,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1883,15,'وَءَاتَيْنَـٰهُمْ ءَايَـٰتِنَا فَكَانُوا۟ عَنْهَا مُعْرِضِينَ','Wa aatainaahum Aayaatinaa fakaanoo \'anhaa mu\'rideen',81,'15:81',27,106,223,3,0,266,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1884,15,'وَكَانُوا۟ يَنْحِتُونَ مِنَ ٱلْجِبَالِ بُيُوتًا ءَامِنِينَ','Wa kaanoo yanhitoona minal jibaali buyootan aamineen',82,'15:82',27,106,223,3,0,266,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1885,15,'فَأَخَذَتْهُمُ ٱلصَّيْحَةُ مُصْبِحِينَ','Fa akhazat humus saihatu musbiheen',83,'15:83',27,106,223,3,0,266,14,'2023-12-01 11:30:05','2026-09-22 00:06:42');
INSERT INTO `chapter_details` VALUES (1886,15,'فَمَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا۟ يَكْسِبُونَ','Famaaa aghnaa \'anhum maa kaanoo yaksiboon',84,'15:84',27,106,223,3,0,266,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1887,15,'وَمَا خَلَقْنَا ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَآ إِلَّا بِٱلْحَقِّ ۗ وَإِنَّ ٱلسَّاعَةَ لَـَٔاتِيَةٌ ۖ فَٱصْفَحِ ٱلصَّفْحَ ٱلْجَمِيلَ','Wa maa khalaqnas samaawaati wal arda wa maa bainahumaaa illaa bilhaqq; wa innas Saa\'ata la aatiyatun fasfahis safhal jameel',85,'15:85',27,106,223,3,0,266,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1888,15,'إِنَّ رَبَّكَ هُوَ ٱلْخَلَّـٰقُ ٱلْعَلِيمُ','Inna Rabbaka Huwal khallaaqul \'aleem',86,'15:86',27,106,223,3,0,266,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1889,15,'وَلَقَدْ ءَاتَيْنَـٰكَ سَبْعًا مِّنَ ٱلْمَثَانِى وَٱلْقُرْءَانَ ٱلْعَظِيمَ','Wa laqad aatainaaka sab\'am mnal masaanee wal Qur-aanal \'azeem',87,'15:87',27,106,223,3,0,266,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1890,15,'لَا تَمُدَّنَّ عَيْنَيْكَ إِلَىٰ مَا مَتَّعْنَا بِهِۦٓ أَزْوَٰجًا مِّنْهُمْ وَلَا تَحْزَنْ عَلَيْهِمْ وَٱخْفِضْ جَنَاحَكَ لِلْمُؤْمِنِينَ','Laa tamuddanna \'ainaika ilaa maa matta \'naa biheee azwaajam minhum wa laa tahzan \'alaihim wakhfid janaahaka lilmu \'mineen',88,'15:88',27,106,223,3,0,266,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1891,15,'وَقُلْ إِنِّىٓ أَنَا ٱلنَّذِيرُ ٱلْمُبِينُ','Wa qul inneee anan nazeerul mubeen',89,'15:89',27,106,223,3,0,266,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1892,15,'كَمَآ أَنزَلْنَا عَلَى ٱلْمُقْتَسِمِينَ','Kamaaa anzalnaa \'alal muqtasimeen',90,'15:90',27,106,223,3,0,266,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1893,15,'ٱلَّذِينَ جَعَلُوا۟ ٱلْقُرْءَانَ عِضِينَ','Allazeena ja\'alul Quraana\'ideen',91,'15:91',27,106,223,3,0,267,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1894,15,'فَوَرَبِّكَ لَنَسْـَٔلَنَّهُمْ أَجْمَعِينَ','Fawa Rabbika lanas\'a lannahum ajma\'een',92,'15:92',27,106,223,3,0,267,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1895,15,'عَمَّا كَانُوا۟ يَعْمَلُونَ','\'Ammaa kaanoo ya\'maloon',93,'15:93',27,106,223,3,0,267,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1896,15,'فَٱصْدَعْ بِمَا تُؤْمَرُ وَأَعْرِضْ عَنِ ٱلْمُشْرِكِينَ','Fasda\' bimaa tu\'maru wa a\'rid anil mushrikeen',94,'15:94',27,106,223,3,0,267,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1897,15,'إِنَّا كَفَيْنَـٰكَ ٱلْمُسْتَهْزِءِينَ','Innaa kafainaakal mustahzi\'een',95,'15:95',27,106,223,3,0,267,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1898,15,'ٱلَّذِينَ يَجْعَلُونَ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَ ۚ فَسَوْفَ يَعْلَمُونَ','Allazeena yaj\'aloona ma\'al laahi ilaahan aakhar; fasawfa ya\'lamoon',96,'15:96',27,106,223,3,0,267,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1899,15,'وَلَقَدْ نَعْلَمُ أَنَّكَ يَضِيقُ صَدْرُكَ بِمَا يَقُولُونَ','Wa laqad na\'lamu annak yadeequ sadruka bimaa yaqooloon',97,'15:97',27,106,223,3,0,267,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1900,15,'فَسَبِّحْ بِحَمْدِ رَبِّكَ وَكُن مِّنَ ٱلسَّـٰجِدِينَ','Fasbbih bihamdi Rabbika wa kum minas saajideen',98,'15:98',27,106,223,3,0,267,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1901,15,'وَٱعْبُدْ رَبَّكَ حَتَّىٰ يَأْتِيَكَ ٱلْيَقِينُ','Wa\'bud Rabbaka hattaa yaatiyakal yaqeen',99,'15:99',27,106,223,3,0,267,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1902,16,'أَتَىٰٓ أَمْرُ ٱللَّهِ فَلَا تَسْتَعْجِلُوهُ ۚ سُبْحَـٰنَهُۥ وَتَعَـٰلَىٰ عَمَّا يُشْرِكُونَ','Ataaa amrullaahi falaa tasta\'jilooh; Subhaanahoo wa Ta\'aalaa \'ammaa yushrikoon',1,'16:1',27,107,224,3,0,267,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1903,16,'يُنَزِّلُ ٱلْمَلَـٰٓئِكَةَ بِٱلرُّوحِ مِنْ أَمْرِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦٓ أَنْ أَنذِرُوٓا۟ أَنَّهُۥ لَآ إِلَـٰهَ إِلَّآ أَنَا۠ فَٱتَّقُونِ','Yunazzilul malaaa \'ikata birroohi min amrihee \'alaa mai yashaaa\'u min \'ibaadiheee an anzirooo annahoo laaa ilaaha illaaa ana fattaqoon',2,'16:2',27,107,224,3,0,267,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1904,16,'خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ ۚ تَعَـٰلَىٰ عَمَّا يُشْرِكُونَ','Khalaqas samaawaati wal arda bilhaqq; Ta\'aalaa \'ammaa yushrikoon',3,'16:3',27,107,224,3,0,267,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1905,16,'خَلَقَ ٱلْإِنسَـٰنَ مِن نُّطْفَةٍ فَإِذَا هُوَ خَصِيمٌ مُّبِينٌ','Khalaqal insaana min nutfatin fa izaa huwa khaseemum mubeen',4,'16:4',27,107,224,3,0,267,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1906,16,'وَٱلْأَنْعَـٰمَ خَلَقَهَا ۗ لَكُمْ فِيهَا دِفْءٌ وَمَنَـٰفِعُ وَمِنْهَا تَأْكُلُونَ','Wal an \'amaa khalaqahaa; lakum feehaa dif\'unw wa manaafi\'u wa minhaa taakuloon',5,'16:5',27,107,224,3,0,267,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1907,16,'وَلَكُمْ فِيهَا جَمَالٌ حِينَ تُرِيحُونَ وَحِينَ تَسْرَحُونَ','Wa lakum feehaa jamaalun heena tureehoona wa heena tasrahoon',6,'16:6',27,107,224,3,0,267,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1908,16,'وَتَحْمِلُ أَثْقَالَكُمْ إِلَىٰ بَلَدٍ لَّمْ تَكُونُوا۟ بَـٰلِغِيهِ إِلَّا بِشِقِّ ٱلْأَنفُسِ ۚ إِنَّ رَبَّكُمْ لَرَءُوفٌ رَّحِيمٌ','Wa tahmilu asqaalakum ilaa baladil lam takoonoo baaligheehi illaa bishiqqil anfus; inna Rabbakum la Ra\'oofur Raheem',7,'16:7',27,107,224,3,0,268,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1909,16,'وَٱلْخَيْلَ وَٱلْبِغَالَ وَٱلْحَمِيرَ لِتَرْكَبُوهَا وَزِينَةً ۚ وَيَخْلُقُ مَا لَا تَعْلَمُونَ','Walkhaila wal bighaala wal hameera litarkaboohaa wa zeenah; wa yakhluqu maa laa ta\'lamoon',8,'16:8',27,107,224,3,0,268,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1910,16,'وَعَلَى ٱللَّهِ قَصْدُ ٱلسَّبِيلِ وَمِنْهَا جَآئِرٌ ۚ وَلَوْ شَآءَ لَهَدَىٰكُمْ أَجْمَعِينَ','Wa \'alal laahi qasdus sabeeli wa minhaa jaaa\'ir; wa law shaaa\'a lahadaakum ajma\'een',9,'16:9',27,107,224,3,0,268,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1911,16,'هُوَ ٱلَّذِىٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً ۖ لَّكُم مِّنْهُ شَرَابٌ وَمِنْهُ شَجَرٌ فِيهِ تُسِيمُونَ','Huwal lazeee anzala minas samaaa\'i maaa\'al lakum minhu sharaabunw wa minhu shajarun feehi tuseemoon',10,'16:10',27,107,225,3,0,268,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1912,16,'يُنۢبِتُ لَكُم بِهِ ٱلزَّرْعَ وَٱلزَّيْتُونَ وَٱلنَّخِيلَ وَٱلْأَعْنَـٰبَ وَمِن كُلِّ ٱلثَّمَرَٰتِ ۗ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَتَفَكَّرُونَ','Yumbitu lakum bihiz zar\'a wazzaitoona wanna kheela wal-a\'naaba wa min kullis samaraat, inna fee zaalika la Aayatal liqawminy yatafakkaroon',11,'16:11',27,107,225,3,0,268,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1913,16,'وَسَخَّرَ لَكُمُ ٱلَّيْلَ وَٱلنَّهَارَ وَٱلشَّمْسَ وَٱلْقَمَرَ ۖ وَٱلنُّجُومُ مُسَخَّرَٰتٌۢ بِأَمْرِهِۦٓ ۗ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّقَوْمٍ يَعْقِلُونَ','Wa sakkhkhara lakumul laila wannahaara wash shamsa walqamara wannujoomu musakhkharaatum bi amrih; inna fee zaalika la Aayaatil liqawminy ya\'qiloon',12,'16:12',27,107,225,3,0,268,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1914,16,'وَمَا ذَرَأَ لَكُمْ فِى ٱلْأَرْضِ مُخْتَلِفًا أَلْوَٰنُهُۥٓ ۗ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَذَّكَّرُونَ','Wa maa zara a lakum fil ardi mukhtalifan alwaanuh; inna fee zaalika la Aayatal liqawminy yazakkaroon',13,'16:13',27,107,225,3,0,268,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1915,16,'وَهُوَ ٱلَّذِى سَخَّرَ ٱلْبَحْرَ لِتَأْكُلُوا۟ مِنْهُ لَحْمًا طَرِيًّا وَتَسْتَخْرِجُوا۟ مِنْهُ حِلْيَةً تَلْبَسُونَهَا وَتَرَى ٱلْفُلْكَ مَوَاخِرَ فِيهِ وَلِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ','Wa Huwal lazee sakhkharal bahra litaakuloo minhu lahman tariyyanw wa tastakhrijoo minhu hilyatan talbasoonahaa wa taral fulka mawaakhira feehi wa litabtaghoo min fadlihee wa la\'allakum tashkuroon',14,'16:14',27,107,225,3,0,268,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1916,16,'وَأَلْقَىٰ فِى ٱلْأَرْضِ رَوَٰسِىَ أَن تَمِيدَ بِكُمْ وَأَنْهَـٰرًا وَسُبُلًا لَّعَلَّكُمْ تَهْتَدُونَ','Wa alqaa fil ardi rawaasiya an tameeda bikum wa anhaaranw wa sublulal la \'allakum tahtadoon',15,'16:15',27,107,225,3,0,269,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1917,16,'وَعَلَـٰمَـٰتٍ ۚ وَبِٱلنَّجْمِ هُمْ يَهْتَدُونَ','Wa \'alaamaat; wa bin najmi hum yahtadoon',16,'16:16',27,107,225,3,0,269,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1918,16,'أَفَمَن يَخْلُقُ كَمَن لَّا يَخْلُقُ ۗ أَفَلَا تَذَكَّرُونَ','Afamany yakhluqu kamallaa yakhluq; afalaa tazak karoon',17,'16:17',27,107,225,3,0,269,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1919,16,'وَإِن تَعُدُّوا۟ نِعْمَةَ ٱللَّهِ لَا تُحْصُوهَآ ۗ إِنَّ ٱللَّهَ لَغَفُورٌ رَّحِيمٌ','Wa in ta\'uddoo ni\'matal laahi laa tuhsoohaa; innal laaha la Ghafoorur Raheem',18,'16:18',27,107,225,3,0,269,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1920,16,'وَٱللَّهُ يَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ','Wallaahu ya\'lamu maa tusirroona wa maa tu\'linoon',19,'16:19',27,107,225,3,0,269,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1921,16,'وَٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ لَا يَخْلُقُونَ شَيْـًٔا وَهُمْ يُخْلَقُونَ','Wallazeena yad\'oona min doonil laahi laa yakhluqoona shai\'anw wa hum yukhlaqoon',20,'16:20',27,107,225,3,0,269,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1922,16,'أَمْوَٰتٌ غَيْرُ أَحْيَآءٍ ۖ وَمَا يَشْعُرُونَ أَيَّانَ يُبْعَثُونَ','Amwaatun ghairu ahyaaa\'inw wa maa yash\'uroona aiyaana yub\'asoon',21,'16:21',27,107,225,3,0,269,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1923,16,'إِلَـٰهُكُمْ إِلَـٰهٌ وَٰحِدٌ ۚ فَٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ قُلُوبُهُم مُّنكِرَةٌ وَهُم مُّسْتَكْبِرُونَ','Illahukum Ilaahunw Waahid; fallazeena laa yu\'minoona bil Aakhirati quloobuhum munkiratunw wa hum mustakbiroon',22,'16:22',27,107,226,3,0,269,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1924,16,'لَا جَرَمَ أَنَّ ٱللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ ۚ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْتَكْبِرِينَ','Laa jarama annal laaha ya\'lamu maa yusirrona wa ma yu\'linoon; innahoo laa yuhibbul mustakbireen',23,'16:23',27,107,226,3,0,269,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1925,16,'وَإِذَا قِيلَ لَهُم مَّاذَآ أَنزَلَ رَبُّكُمْ ۙ قَالُوٓا۟ أَسَـٰطِيرُ ٱلْأَوَّلِينَ','Wa izaa qeela lahum maazaaa anzala Rabbukum qaaloo asaateerul awwaleen',24,'16:24',27,107,226,3,0,269,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1926,16,'لِيَحْمِلُوٓا۟ أَوْزَارَهُمْ كَامِلَةً يَوْمَ ٱلْقِيَـٰمَةِ ۙ وَمِنْ أَوْزَارِ ٱلَّذِينَ يُضِلُّونَهُم بِغَيْرِ عِلْمٍ ۗ أَلَا سَآءَ مَا يَزِرُونَ','Liyahmilooo awzaarahum kaamilatany Yawmal Qiyaamati wa min awzaaril lazeena yudilloonahum bighairi \'ilm; alaa saaa\'a maa yaziroon',25,'16:25',27,107,226,3,0,269,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1927,16,'قَدْ مَكَرَ ٱلَّذِينَ مِن قَبْلِهِمْ فَأَتَى ٱللَّهُ بُنْيَـٰنَهُم مِّنَ ٱلْقَوَاعِدِ فَخَرَّ عَلَيْهِمُ ٱلسَّقْفُ مِن فَوْقِهِمْ وَأَتَىٰهُمُ ٱلْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ','Qad makaral lazeena min qablihim fa atal laahu bunyaa nahum minal qawaa\'idi fakharra \'alaihimus saqfu min fawqihim wa ataahumul \'azaabu min haisu laa yash\'uroon',26,'16:26',27,107,227,3,0,269,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1928,16,'ثُمَّ يَوْمَ ٱلْقِيَـٰمَةِ يُخْزِيهِمْ وَيَقُولُ أَيْنَ شُرَكَآءِىَ ٱلَّذِينَ كُنتُمْ تُشَـٰٓقُّونَ فِيهِمْ ۚ قَالَ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ إِنَّ ٱلْخِزْىَ ٱلْيَوْمَ وَٱلسُّوٓءَ عَلَى ٱلْكَـٰفِرِينَ','Summa Yawmal Qiyaamati yukhzeehim wa yaqoolu aina shurakaaa\'iyal lazeena kuntum tushaaaqqoona feehim; qaalal lazeena ootul \'ilma innal khizyal Yawma wassooo\'a \'alal kaafireen',27,'16:27',27,107,227,3,0,270,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1929,16,'ٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلْمَلَـٰٓئِكَةُ ظَالِمِىٓ أَنفُسِهِمْ ۖ فَأَلْقَوُا۟ ٱلسَّلَمَ مَا كُنَّا نَعْمَلُ مِن سُوٓءٍۭ ۚ بَلَىٰٓ إِنَّ ٱللَّهَ عَلِيمٌۢ بِمَا كُنتُمْ تَعْمَلُونَ','Allazeena tatawaf faahu mul malaaa\'ikatu zaalimeee anfusihim fa alqawus salama maa kunnaa na\'malu min sooo\'; balaaa innal laaha \'aleemum bimaa kuntum ta\'maloon',28,'16:28',27,107,227,3,0,270,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1930,16,'فَٱدْخُلُوٓا۟ أَبْوَٰبَ جَهَنَّمَ خَـٰلِدِينَ فِيهَا ۖ فَلَبِئْسَ مَثْوَى ٱلْمُتَكَبِّرِينَ','Fadkhulooo abwaaba jahannama khaalideena feeha falabi\'sa maswal mutakab bireen',29,'16:29',27,107,227,3,0,270,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1931,16,'۞ وَقِيلَ لِلَّذِينَ ٱتَّقَوْا۟ مَاذَآ أَنزَلَ رَبُّكُمْ ۚ قَالُوا۟ خَيْرًا ۗ لِّلَّذِينَ أَحْسَنُوا۟ فِى هَـٰذِهِ ٱلدُّنْيَا حَسَنَةٌ ۚ وَلَدَارُ ٱلْـَٔاخِرَةِ خَيْرٌ ۚ وَلَنِعْمَ دَارُ ٱلْمُتَّقِينَ','Wa qeela lillazeenat taqaw maazaaa anzala Rabbukum; qaaloo khairaa; lillazeena absanoo fee haazihid dunyaa hasanah; wa la Daarul Aakhirati khair; wa lani\'ma daarul muttaqeen',30,'16:30',27,108,227,3,0,270,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1932,16,'جَنَّـٰتُ عَدْنٍ يَدْخُلُونَهَا تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ۖ لَهُمْ فِيهَا مَا يَشَآءُونَ ۚ كَذَٰلِكَ يَجْزِى ٱللَّهُ ٱلْمُتَّقِينَ','Jannaatu \'Adniny yadkhuloonahaa tajree min tahtihal anhaaru lahum feehaa maa yashaaa\'oon; kazaalika yajzil laahul muttaqeen',31,'16:31',27,108,227,3,0,270,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1933,16,'ٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلْمَلَـٰٓئِكَةُ طَيِّبِينَ ۙ يَقُولُونَ سَلَـٰمٌ عَلَيْكُمُ ٱدْخُلُوا۟ ٱلْجَنَّةَ بِمَا كُنتُمْ تَعْمَلُونَ','Allazeena tatawaf faahumul malaaa\'ikatu taiyibeena yaqooloona salaamun \'alai kumud khulul Jannata bimaa kuntum ta\'maloon',32,'16:32',27,108,227,3,0,270,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1934,16,'هَلْ يَنظُرُونَ إِلَّآ أَن تَأْتِيَهُمُ ٱلْمَلَـٰٓئِكَةُ أَوْ يَأْتِىَ أَمْرُ رَبِّكَ ۚ كَذَٰلِكَ فَعَلَ ٱلَّذِينَ مِن قَبْلِهِمْ ۚ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَـٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ','Hal yanzuroona illaaa an taatiyahumul malaaa\'ikatu aw yaatiya amru Rabbik; kazaalika fa\'alal lazeena min qablihim; wa maa zalamahumul laahu wa laakin kaanoo anfusahum yazlimoon',33,'16:33',27,108,227,3,0,270,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1935,16,'فَأَصَابَهُمْ سَيِّـَٔاتُ مَا عَمِلُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ','Fa asaabahum saiyi aatu maa \'amiloo wa haaqa bihim maa kaano bihee yastahzi\'oon',34,'16:34',27,108,227,3,0,270,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1936,16,'وَقَالَ ٱلَّذِينَ أَشْرَكُوا۟ لَوْ شَآءَ ٱللَّهُ مَا عَبَدْنَا مِن دُونِهِۦ مِن شَىْءٍ نَّحْنُ وَلَآ ءَابَآؤُنَا وَلَا حَرَّمْنَا مِن دُونِهِۦ مِن شَىْءٍ ۚ كَذَٰلِكَ فَعَلَ ٱلَّذِينَ مِن قَبْلِهِمْ ۚ فَهَلْ عَلَى ٱلرُّسُلِ إِلَّا ٱلْبَلَـٰغُ ٱلْمُبِينُ','Wa qaalal lazeena ashrakoo law shaaa\'al laahu ma \'abadnaa min doonihee min shai\'in nahnu wa laaa aabaaa\'unaa wa laa harramnaa min doonihee min shai\'; kazaalika fa\'alal lazeena min qablihim fahal \'alar Rusuli illal balaaghul mubeen',35,'16:35',27,108,228,3,0,271,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1937,16,'وَلَقَدْ بَعَثْنَا فِى كُلِّ أُمَّةٍ رَّسُولًا أَنِ ٱعْبُدُوا۟ ٱللَّهَ وَٱجْتَنِبُوا۟ ٱلطَّـٰغُوتَ ۖ فَمِنْهُم مَّنْ هَدَى ٱللَّهُ وَمِنْهُم مَّنْ حَقَّتْ عَلَيْهِ ٱلضَّلَـٰلَةُ ۚ فَسِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُكَذِّبِينَ','Wa laqad ba\'asnaa fee kulli ummatir Rasoolan ani\'budul laaha wajtanibut Taaghoota faminhum man hadal laahu wa minhum man haqqat \'alaihid dalaalah; faseeroo fil ardi fanzuroo kaifa kaana \'aaqibatul mukazzibeen',36,'16:36',27,108,228,3,0,271,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1938,16,'إِن تَحْرِصْ عَلَىٰ هُدَىٰهُمْ فَإِنَّ ٱللَّهَ لَا يَهْدِى مَن يُضِلُّ ۖ وَمَا لَهُم مِّن نَّـٰصِرِينَ','In tahris \'alaa hudaahum fa innal laaha laa yahdee mai yudillu wa maa lahum min naasireen',37,'16:37',27,108,228,3,0,271,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1939,16,'وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَـٰنِهِمْ ۙ لَا يَبْعَثُ ٱللَّهُ مَن يَمُوتُ ۚ بَلَىٰ وَعْدًا عَلَيْهِ حَقًّا وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ','Wa aqsamoo billaahi jahda aimaanihim laa yab\'asul laahu mai yamoot; balaa wa\'dan \'alaihi haqqanw wa laakinna aksaran naasi laa ya\'lamoon',38,'16:38',27,108,228,3,0,271,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1940,16,'لِيُبَيِّنَ لَهُمُ ٱلَّذِى يَخْتَلِفُونَ فِيهِ وَلِيَعْلَمَ ٱلَّذِينَ كَفَرُوٓا۟ أَنَّهُمْ كَانُوا۟ كَـٰذِبِينَ','Liyubaiyina lahumul lazee yakhtalifoona feehi wa liya\'lamal lazeena kafarooo annahum kaanoo kaazibeen',39,'16:39',27,108,228,3,0,271,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1941,16,'إِنَّمَا قَوْلُنَا لِشَىْءٍ إِذَآ أَرَدْنَـٰهُ أَن نَّقُولَ لَهُۥ كُن فَيَكُونُ','Innamaa qawlunaa lisha y\'in izaa aradnaahu an naqoola lahoo kun fa yakoon',40,'16:40',27,108,228,3,0,271,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1942,16,'وَٱلَّذِينَ هَاجَرُوا۟ فِى ٱللَّهِ مِنۢ بَعْدِ مَا ظُلِمُوا۟ لَنُبَوِّئَنَّهُمْ فِى ٱلدُّنْيَا حَسَنَةً ۖ وَلَأَجْرُ ٱلْـَٔاخِرَةِ أَكْبَرُ ۚ لَوْ كَانُوا۟ يَعْلَمُونَ','Wallazeena haajaroo fil laahi mim ba\'di maa zulimoo lanubawwi\' annahum fiddunyaa hasanatanw wa la ajrul Aakhirati akbar; law kaanoo ya\'lamoon',41,'16:41',27,108,229,3,0,271,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1943,16,'ٱلَّذِينَ صَبَرُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ','Allazeena sabaroo wa \'alaa Rabbihim yatawak kaloon',42,'16:42',27,108,229,3,0,271,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1944,16,'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِىٓ إِلَيْهِمْ ۚ فَسْـَٔلُوٓا۟ أَهْلَ ٱلذِّكْرِ إِن كُنتُمْ لَا تَعْلَمُونَ','Wa maaa arsalnaa min qablika illaa rijaalan nooheee ilaihim; fas\'alooo ahlaz zikri in kuntum laa ta\'lamoon',43,'16:43',27,108,229,3,0,272,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1945,16,'بِٱلْبَيِّنَـٰتِ وَٱلزُّبُرِ ۗ وَأَنزَلْنَآ إِلَيْكَ ٱلذِّكْرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمْ وَلَعَلَّهُمْ يَتَفَكَّرُونَ','Bilbaiyinaati waz Zubur; wa anzalnaaa ilaikaz Zikra litubaiyina linnaasi maa nuzzila ilaihim wa la\'allahum yatafakkaroon',44,'16:44',27,108,229,3,0,272,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1946,16,'أَفَأَمِنَ ٱلَّذِينَ مَكَرُوا۟ ٱلسَّيِّـَٔاتِ أَن يَخْسِفَ ٱللَّهُ بِهِمُ ٱلْأَرْضَ أَوْ يَأْتِيَهُمُ ٱلْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ','Afa aminal lazeena makarus saiyi aati ai yakhsifal laahu bihimul arda aw yaaa tiyahumul \'azaabu min haisu laa yash\'uroon',45,'16:45',27,108,229,3,0,272,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1947,16,'أَوْ يَأْخُذَهُمْ فِى تَقَلُّبِهِمْ فَمَا هُم بِمُعْجِزِينَ','Aw yaakhuzahum fee taqallubihim famaa hum bi mu\'jizeen',46,'16:46',27,108,229,3,0,272,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1948,16,'أَوْ يَأْخُذَهُمْ عَلَىٰ تَخَوُّفٍ فَإِنَّ رَبَّكُمْ لَرَءُوفٌ رَّحِيمٌ','Aw yaakhuzahum \'alaa takhawwuf; fa inna Rabbakum la Ra\'oofur Raheem',47,'16:47',27,108,229,3,0,272,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1949,16,'أَوَلَمْ يَرَوْا۟ إِلَىٰ مَا خَلَقَ ٱللَّهُ مِن شَىْءٍ يَتَفَيَّؤُا۟ ظِلَـٰلُهُۥ عَنِ ٱلْيَمِينِ وَٱلشَّمَآئِلِ سُجَّدًا لِّلَّهِ وَهُمْ دَٰخِرُونَ','Awa lam yaraw ilaa maa khalaqal laahu min shai\'iny-yatafaiya\'u zilaaluhoo \'anil yameeni washshamaaa\' ili sujjadal lillaahi wa hum daakhiroon',48,'16:48',27,108,229,3,0,272,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1950,16,'وَلِلَّهِ يَسْجُدُ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ مِن دَآبَّةٍ وَٱلْمَلَـٰٓئِكَةُ وَهُمْ لَا يَسْتَكْبِرُونَ','Wa lillaahi yasjudu maa fis samaawaati wa maa fil ardi min daaabbatinw walma laaa\'ikatu wa hum laa yastakbiroon',49,'16:49',27,108,229,3,0,272,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1951,16,'يَخَافُونَ رَبَّهُم مِّن فَوْقِهِمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ ۩','yakhaafoona Rabbahum min fawqihim wa yaf\'aloona maa yu\'maroon',50,'16:50',27,108,229,3,3,272,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1952,16,'۞ وَقَالَ ٱللَّهُ لَا تَتَّخِذُوٓا۟ إِلَـٰهَيْنِ ٱثْنَيْنِ ۖ إِنَّمَا هُوَ إِلَـٰهٌ وَٰحِدٌ ۖ فَإِيَّـٰىَ فَٱرْهَبُونِ','Wa qaalal laahu laa tatta khizooo ilaahainis naini innamaa Huwa Ilaahunw Waahid; fa iyyaaya farhaboon',51,'16:51',28,109,230,3,0,272,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1953,16,'وَلَهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَلَهُ ٱلدِّينُ وَاصِبًا ۚ أَفَغَيْرَ ٱللَّهِ تَتَّقُونَ','Wa lahoo maa fis samaawaati wal ardi wa lahud deenu waasibaa; afaghairal laahi tattaqoon',52,'16:52',28,109,230,3,0,272,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1954,16,'وَمَا بِكُم مِّن نِّعْمَةٍ فَمِنَ ٱللَّهِ ۖ ثُمَّ إِذَا مَسَّكُمُ ٱلضُّرُّ فَإِلَيْهِ تَجْـَٔرُونَ','Wa maa bikum minni\'matin faminal laahi summa izaa massakumud durru fa ilaihi taj\'aroon',53,'16:53',28,109,230,3,0,272,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1955,16,'ثُمَّ إِذَا كَشَفَ ٱلضُّرَّ عَنكُمْ إِذَا فَرِيقٌ مِّنكُم بِرَبِّهِمْ يُشْرِكُونَ','Summaa izaa kashafad durra \'ankum izaa fareequm minkum bi Rabbihim yushrikoon',54,'16:54',28,109,230,3,0,272,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1956,16,'لِيَكْفُرُوا۟ بِمَآ ءَاتَيْنَـٰهُمْ ۚ فَتَمَتَّعُوا۟ ۖ فَسَوْفَ تَعْلَمُونَ','Liyakfuroo bimaa aatainaahum; fatamatta\'oo, faswfa ta\'lamoon',55,'16:55',28,109,230,3,0,273,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1957,16,'وَيَجْعَلُونَ لِمَا لَا يَعْلَمُونَ نَصِيبًا مِّمَّا رَزَقْنَـٰهُمْ ۗ تَٱللَّهِ لَتُسْـَٔلُنَّ عَمَّا كُنتُمْ تَفْتَرُونَ','Wa yaj\'aloona limaa laa ya\'lamoona naseebam mimmaa razaqnnaahum; tallaahi latus\'alunaa \'ammaa kuntum taftaroon',56,'16:56',28,109,230,3,0,273,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1958,16,'وَيَجْعَلُونَ لِلَّهِ ٱلْبَنَـٰتِ سُبْحَـٰنَهُۥ ۙ وَلَهُم مَّا يَشْتَهُونَ','Wa yaj\'aloona lillaahil banaati Subhaanahoo wa lahum maa yashtahoon',57,'16:57',28,109,230,3,0,273,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1959,16,'وَإِذَا بُشِّرَ أَحَدُهُم بِٱلْأُنثَىٰ ظَلَّ وَجْهُهُۥ مُسْوَدًّا وَهُوَ كَظِيمٌ','Wa izaa bushshira ahaduhum bil unsaa zalla wajhuhoo muswaddanw wa huwa kazeem',58,'16:58',28,109,230,3,0,273,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1960,16,'يَتَوَٰرَىٰ مِنَ ٱلْقَوْمِ مِن سُوٓءِ مَا بُشِّرَ بِهِۦٓ ۚ أَيُمْسِكُهُۥ عَلَىٰ هُونٍ أَمْ يَدُسُّهُۥ فِى ٱلتُّرَابِ ۗ أَلَا سَآءَ مَا يَحْكُمُونَ','yatawaaraa minal qawmimin sooo\'i maa bushshira bih; a-yumsikuhoo \'alaa hoonin am yadussuhoo fit turaab; alaa saaa\'a maa yahkumoon',59,'16:59',28,109,230,3,0,273,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1961,16,'لِلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ مَثَلُ ٱلسَّوْءِ ۖ وَلِلَّهِ ٱلْمَثَلُ ٱلْأَعْلَىٰ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ','Lillazeena laa yu\'minoona bil Aakhirati masalus saw\'i wa lillaahil masalul a\'laa; wa Huwal \'Azeezul Hakeem',60,'16:60',28,109,230,3,0,273,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1962,16,'وَلَوْ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِظُلْمِهِم مَّا تَرَكَ عَلَيْهَا مِن دَآبَّةٍ وَلَـٰكِن يُؤَخِّرُهُمْ إِلَىٰٓ أَجَلٍ مُّسَمًّى ۖ فَإِذَا جَآءَ أَجَلُهُمْ لَا يَسْتَـْٔخِرُونَ سَاعَةً ۖ وَلَا يَسْتَقْدِمُونَ','Wa law yu\'aakhizul laahun naasa bizulminhim maa taraka \'alaihaa min daaabbatinw wa laakiny yu\'akhkhiruhum ilaaa ajalim musamman fa izaa jaaa\'a ajaluhum laa yastaakhiroona saa\'atanw wa laa yastaqdimoon',61,'16:61',28,109,231,3,0,273,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1963,16,'وَيَجْعَلُونَ لِلَّهِ مَا يَكْرَهُونَ وَتَصِفُ أَلْسِنَتُهُمُ ٱلْكَذِبَ أَنَّ لَهُمُ ٱلْحُسْنَىٰ ۖ لَا جَرَمَ أَنَّ لَهُمُ ٱلنَّارَ وَأَنَّهُم مُّفْرَطُونَ','Wa yaj\'aloona lillaahi maa yakrahoona wa tasifu alsinatuhumul kaziba anna lahumul husnaa laa jarama anna lahumun Naara wa annahum mufratoon',62,'16:62',28,109,231,3,0,273,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1964,16,'تَٱللَّهِ لَقَدْ أَرْسَلْنَآ إِلَىٰٓ أُمَمٍ مِّن قَبْلِكَ فَزَيَّنَ لَهُمُ ٱلشَّيْطَـٰنُ أَعْمَـٰلَهُمْ فَهُوَ وَلِيُّهُمُ ٱلْيَوْمَ وَلَهُمْ عَذَابٌ أَلِيمٌ','Tallaahi laqad arsalnaaa ilaaa umamim min qablika fazayyana lahumush Shaitaanu a\'maalahum fahuwa waliyyuhumul yawma wa lahum \'azaabun aleem',63,'16:63',28,109,231,3,0,273,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1965,16,'وَمَآ أَنزَلْنَا عَلَيْكَ ٱلْكِتَـٰبَ إِلَّا لِتُبَيِّنَ لَهُمُ ٱلَّذِى ٱخْتَلَفُوا۟ فِيهِ ۙ وَهُدًى وَرَحْمَةً لِّقَوْمٍ يُؤْمِنُونَ','Wa maaa anzalnaa \'alaikal Kitaaba illaa litubaiyina lahumul lazikh talafoo feehi wa hudanw wa rahmatal liqawminy yu\'minoon',64,'16:64',28,109,231,3,0,273,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1966,16,'وَٱللَّهُ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَحْيَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَآ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَسْمَعُونَ','Wallaahu anzala minas samaaa\'i maaa\'an fa ahyaa bihil arda ba\'da mawtihaa; inna fee zaalika la aayatal liqaw miny yasma\'oon',65,'16:65',28,109,231,3,0,274,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1967,16,'وَإِنَّ لَكُمْ فِى ٱلْأَنْعَـٰمِ لَعِبْرَةً ۖ نُّسْقِيكُم مِّمَّا فِى بُطُونِهِۦ مِنۢ بَيْنِ فَرْثٍ وَدَمٍ لَّبَنًا خَالِصًا سَآئِغًا لِّلشَّـٰرِبِينَ','Wa inna lakum fil an\'aami la\'ibrah; nusqeekum mimmmaa fee butoonihee mim baini farsinw wa damil labanann khaalisan saaa\'ighallish shaaribeen',66,'16:66',28,109,232,3,0,274,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1968,16,'وَمِن ثَمَرَٰتِ ٱلنَّخِيلِ وَٱلْأَعْنَـٰبِ تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا ۗ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَعْقِلُونَ','Wa min samaraatin nakheeli wal a\'nnaabi tattakhizoona minhu sakaranw wa rizqann hasanaa; inna fee zaalika la Aayatal liqawminy ya\'qiloon',67,'16:67',28,109,232,3,0,274,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1969,16,'وَأَوْحَىٰ رَبُّكَ إِلَى ٱلنَّحْلِ أَنِ ٱتَّخِذِى مِنَ ٱلْجِبَالِ بُيُوتًا وَمِنَ ٱلشَّجَرِ وَمِمَّا يَعْرِشُونَ','Wa awhaa Rabbuka ilannnabli anit takhizee minal jabaali buyootanw wa minash shajari wa mimmaa ya\'rishoon',68,'16:68',28,109,232,3,0,274,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1970,16,'ثُمَّ كُلِى مِن كُلِّ ٱلثَّمَرَٰتِ فَٱسْلُكِى سُبُلَ رَبِّكِ ذُلُلًا ۚ يَخْرُجُ مِنۢ بُطُونِهَا شَرَابٌ مُّخْتَلِفٌ أَلْوَٰنُهُۥ فِيهِ شِفَآءٌ لِّلنَّاسِ ۗ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَتَفَكَّرُونَ','Summma kulee min kullis samaraati faslukee subula Rabbiki zululaa; yakhruju mim butoonihaa sharaabum mukh talifun alwaanuhoo feehi shifaaa\'ul linnaas, innna fee zaalika la Aayatal liqawminy yatafakkaroon',69,'16:69',28,109,232,3,0,274,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1971,16,'وَٱللَّهُ خَلَقَكُمْ ثُمَّ يَتَوَفَّىٰكُمْ ۚ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرْذَلِ ٱلْعُمُرِ لِكَىْ لَا يَعْلَمَ بَعْدَ عِلْمٍ شَيْـًٔا ۚ إِنَّ ٱللَّهَ عَلِيمٌ قَدِيرٌ','Wallaahu khalaqakum suma tatawaffaakum; wa minkum many-yuradu ilaaa arzalil \'umuri likai laa ya\'lama ba\'da \'ilmin shai\'aa; innal laaha \'Aleemun Qadeer',70,'16:70',28,109,232,3,0,274,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1972,16,'وَٱللَّهُ فَضَّلَ بَعْضَكُمْ عَلَىٰ بَعْضٍ فِى ٱلرِّزْقِ ۚ فَمَا ٱلَّذِينَ فُضِّلُوا۟ بِرَآدِّى رِزْقِهِمْ عَلَىٰ مَا مَلَكَتْ أَيْمَـٰنُهُمْ فَهُمْ فِيهِ سَوَآءٌ ۚ أَفَبِنِعْمَةِ ٱللَّهِ يَجْحَدُونَ','Wallaahu faddala ba\'dakum \'alaa ba\'din fir rizq; famal lazeena fuddiloo biraaaddee rizqihim \'alaa maa malakat aimaanuhum fahum feehi sawaaa\'; afabini\'matil laahi yajhadoon',71,'16:71',28,109,233,3,0,274,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1973,16,'وَٱللَّهُ جَعَلَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَٰجًا وَجَعَلَ لَكُم مِّنْ أَزْوَٰجِكُم بَنِينَ وَحَفَدَةً وَرَزَقَكُم مِّنَ ٱلطَّيِّبَـٰتِ ۚ أَفَبِٱلْبَـٰطِلِ يُؤْمِنُونَ وَبِنِعْمَتِ ٱللَّهِ هُمْ يَكْفُرُونَ','Wallaahu ja\'ala lakum min anfusikum azwaajanw wa ja\'ala lakum min azwaajikum baneena wa hafadatanw wa razaqakum minat yaiyibaat; afabil baatili yu\'minoona wa bini\'matil laahi hum yakkfuroon',72,'16:72',28,109,233,3,0,274,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1974,16,'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمْلِكُ لَهُمْ رِزْقًا مِّنَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ شَيْـًٔا وَلَا يَسْتَطِيعُونَ','Wa ya\'budoona min doonil laahi maa laa yamliku lahum rizqam minas samaawaati wal ardi shai\'anw wa laa yastatee\'oon',73,'16:73',28,109,233,3,0,275,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1975,16,'فَلَا تَضْرِبُوا۟ لِلَّهِ ٱلْأَمْثَالَ ۚ إِنَّ ٱللَّهَ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ','Falaa tadriboo lillaahil amsaal; innal laaha ya\'lamu wa antum laa ta\'lamoon',74,'16:74',28,109,233,3,0,275,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1976,16,'۞ ضَرَبَ ٱللَّهُ مَثَلًا عَبْدًا مَّمْلُوكًا لَّا يَقْدِرُ عَلَىٰ شَىْءٍ وَمَن رَّزَقْنَـٰهُ مِنَّا رِزْقًا حَسَنًا فَهُوَ يُنفِقُ مِنْهُ سِرًّا وَجَهْرًا ۖ هَلْ يَسْتَوُۥنَ ۚ ٱلْحَمْدُ لِلَّهِ ۚ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ','Darabal laahu masalan \'abdam mammlookal laa yaqdiru \'alaa shai\'inw wa marrazaqnaahu mminnaa rizqan hasanan fahuwa yunfiqu minhu sirranw wa jahra; hal yasta-woon; alhamdu lillaah; bal aksaruhum laa ya\'lamoon',75,'16:75',28,110,233,3,0,275,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1977,16,'وَضَرَبَ ٱللَّهُ مَثَلًا رَّجُلَيْنِ أَحَدُهُمَآ أَبْكَمُ لَا يَقْدِرُ عَلَىٰ شَىْءٍ وَهُوَ كَلٌّ عَلَىٰ مَوْلَىٰهُ أَيْنَمَا يُوَجِّههُّ لَا يَأْتِ بِخَيْرٍ ۖ هَلْ يَسْتَوِى هُوَ وَمَن يَأْمُرُ بِٱلْعَدْلِ ۙ وَهُوَ عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ','Wa darabal laahu masalar rajulaini ahaduhumaaa abkamu laa yaqdiru \'alaa shai\'inw wa huwa kallun \'alaa mawlaahu ainamaa yuwajjihhu laa yaati bikhairin hal yastawee huwa wa many-yaamuru bil\'adli wa huwa \'alaa Siraatim MMustaqeem',76,'16:76',28,110,233,3,0,275,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1978,16,'وَلِلَّهِ غَيْبُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَمَآ أَمْرُ ٱلسَّاعَةِ إِلَّا كَلَمْحِ ٱلْبَصَرِ أَوْ هُوَ أَقْرَبُ ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ','Wa lillaahi ghaibus samaawaati wal ard; wa maaa amrus Saa\'ati illaa kalamhil basari aw huwa aqrab; innal laaha \'alaaa kulli shai\'in Qadeer',77,'16:77',28,110,234,3,0,275,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1979,16,'وَٱللَّهُ أَخْرَجَكُم مِّنۢ بُطُونِ أُمَّهَـٰتِكُمْ لَا تَعْلَمُونَ شَيْـًٔا وَجَعَلَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَـٰرَ وَٱلْأَفْـِٔدَةَ ۙ لَعَلَّكُمْ تَشْكُرُونَ','Wallaahu akhrajakum mim butooni ummahaatikum laa ta\'lamoona shai\'anw wa ja\'ala lakumus sam\'a wal absaara wal af\'idata la\'allakum tashkuroon',78,'16:78',28,110,234,3,0,275,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1980,16,'أَلَمْ يَرَوْا۟ إِلَى ٱلطَّيْرِ مُسَخَّرَٰتٍ فِى جَوِّ ٱلسَّمَآءِ مَا يُمْسِكُهُنَّ إِلَّا ٱللَّهُ ۗ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّقَوْمٍ يُؤْمِنُونَ','Alam yaraw ilat tairi musakhkharaatin fee jawwis samaaa\'i maa yumsikuhunna illal laah; inna fee zaalika la Aayaatil liqawminy yu\'minoon',79,'16:79',28,110,234,3,0,275,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1981,16,'وَٱللَّهُ جَعَلَ لَكُم مِّنۢ بُيُوتِكُمْ سَكَنًا وَجَعَلَ لَكُم مِّن جُلُودِ ٱلْأَنْعَـٰمِ بُيُوتًا تَسْتَخِفُّونَهَا يَوْمَ ظَعْنِكُمْ وَيَوْمَ إِقَامَتِكُمْ ۙ وَمِنْ أَصْوَافِهَا وَأَوْبَارِهَا وَأَشْعَارِهَآ أَثَـٰثًا وَمَتَـٰعًا إِلَىٰ حِينٍ','Wallaahu ja\'ala lakum min juloodil an\'aami buyootan tastakhif foonahaa yawma za\'nikum wa yawma iqaamatikum wa min aswaafihaa wa awbaarihaa wa ash\'aarihaaa asaasanw wa mataa\'an ilaa been',80,'16:80',28,110,234,3,0,276,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1982,16,'وَٱللَّهُ جَعَلَ لَكُم مِّمَّا خَلَقَ ظِلَـٰلًا وَجَعَلَ لَكُم مِّنَ ٱلْجِبَالِ أَكْنَـٰنًا وَجَعَلَ لَكُمْ سَرَٰبِيلَ تَقِيكُمُ ٱلْحَرَّ وَسَرَٰبِيلَ تَقِيكُم بَأْسَكُمْ ۚ كَذَٰلِكَ يُتِمُّ نِعْمَتَهُۥ عَلَيْكُمْ لَعَلَّكُمْ تُسْلِمُونَ','Wallaahu ja\'ala lakum mimmaa khalaqa zilaalanw wa ja\'ala lakum minal jibaali aknaananw wa ja\'ala lakum saraabeela taqeekumul harra wa saraabeela taqeekum baasakum; kazaalika yutimmu ni\'matahoo alaikum la\'allakum tuslimoon',81,'16:81',28,110,234,3,0,276,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1983,16,'فَإِن تَوَلَّوْا۟ فَإِنَّمَا عَلَيْكَ ٱلْبَلَـٰغُ ٱلْمُبِينُ','Fa in tawallaw fa innamaa \'alaikal balaaghul mubeen',82,'16:82',28,110,234,3,0,276,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1984,16,'يَعْرِفُونَ نِعْمَتَ ٱللَّهِ ثُمَّ يُنكِرُونَهَا وَأَكْثَرُهُمُ ٱلْكَـٰفِرُونَ','Ya\'rifoona ni\'matal laahi summa yunkiroonahaa wa aksaruhumul kaafiroon',83,'16:83',28,110,234,3,0,276,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1985,16,'وَيَوْمَ نَبْعَثُ مِن كُلِّ أُمَّةٍ شَهِيدًا ثُمَّ لَا يُؤْذَنُ لِلَّذِينَ كَفَرُوا۟ وَلَا هُمْ يُسْتَعْتَبُونَ','Wa yawma nab\'asu min kulli ummatin shaheedan summa laa yu\'zanu lillazeena kafaroo wa laa hum yusta\'taboon',84,'16:84',28,110,235,3,0,276,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1986,16,'وَإِذَا رَءَا ٱلَّذِينَ ظَلَمُوا۟ ٱلْعَذَابَ فَلَا يُخَفَّفُ عَنْهُمْ وَلَا هُمْ يُنظَرُونَ','Wa izaa ra al lazeena zalamul \'azaaba falaa yukhaf fafu \'anhum wa laa hum yunzaroon',85,'16:85',28,110,235,3,0,276,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1987,16,'وَإِذَا رَءَا ٱلَّذِينَ أَشْرَكُوا۟ شُرَكَآءَهُمْ قَالُوا۟ رَبَّنَا هَـٰٓؤُلَآءِ شُرَكَآؤُنَا ٱلَّذِينَ كُنَّا نَدْعُوا۟ مِن دُونِكَ ۖ فَأَلْقَوْا۟ إِلَيْهِمُ ٱلْقَوْلَ إِنَّكُمْ لَكَـٰذِبُونَ','Wa izaa ra al lazeena ashrakoo shurakaaa\'ahum qaaloo Rabbana haaa\'ulaaa\'i shurakaaa\'unal lazeena kunnaa nad\'oo min doonika fa alqaw ilaihimul qawla innakum lakaaziboon',86,'16:86',28,110,235,3,0,276,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1988,16,'وَأَلْقَوْا۟ إِلَى ٱللَّهِ يَوْمَئِذٍ ٱلسَّلَمَ ۖ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ','Wa alqaw ilal laahi yawma\'izinis salama wa dalla \'anhum maa kaanoo yaftaroon',87,'16:87',28,110,235,3,0,276,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1989,16,'ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ زِدْنَـٰهُمْ عَذَابًا فَوْقَ ٱلْعَذَابِ بِمَا كَانُوا۟ يُفْسِدُونَ','Allazeena kafaroo wa saddoo \'an sabeelil laahi zidnaahum \'azaaban fawqal \'azaabi bimaa kaanoo yufsidoon',88,'16:88',28,110,235,3,0,277,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1990,16,'وَيَوْمَ نَبْعَثُ فِى كُلِّ أُمَّةٍ شَهِيدًا عَلَيْهِم مِّنْ أَنفُسِهِمْ ۖ وَجِئْنَا بِكَ شَهِيدًا عَلَىٰ هَـٰٓؤُلَآءِ ۚ وَنَزَّلْنَا عَلَيْكَ ٱلْكِتَـٰبَ تِبْيَـٰنًا لِّكُلِّ شَىْءٍ وَهُدًى وَرَحْمَةً وَبُشْرَىٰ لِلْمُسْلِمِينَ','Wa yawma nab\'asu fee kulli ummmatin shaheedan \'alaihim min anfusihim wa ji\'naa bika shaheedan \'alaa haaa\'ulaaa\'; wa nazzalnaa \'alaikal Kitaaba tibyaanal likulli shai\'inw wa hudanw wa rahmatanw wa bushraa lilmuslimeen',89,'16:89',28,110,235,3,0,277,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1991,16,'۞ إِنَّ ٱللَّهَ يَأْمُرُ بِٱلْعَدْلِ وَٱلْإِحْسَـٰنِ وَإِيتَآئِ ذِى ٱلْقُرْبَىٰ وَيَنْهَىٰ عَنِ ٱلْفَحْشَآءِ وَٱلْمُنكَرِ وَٱلْبَغْىِ ۚ يَعِظُكُمْ لَعَلَّكُمْ تَذَكَّرُونَ','Innal laaha yaamaru bil \'adli wal ihsaani wa eetaaa\'i zil qurbaa wa yanhaa \'anil fahshaaa\'i wal munkari walbagh-i\' ya\'izukum la\'allakum tazakkkaroon',90,'16:90',28,111,236,3,0,277,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1992,16,'وَأَوْفُوا۟ بِعَهْدِ ٱللَّهِ إِذَا عَـٰهَدتُّمْ وَلَا تَنقُضُوا۟ ٱلْأَيْمَـٰنَ بَعْدَ تَوْكِيدِهَا وَقَدْ جَعَلْتُمُ ٱللَّهَ عَلَيْكُمْ كَفِيلًا ۚ إِنَّ ٱللَّهَ يَعْلَمُ مَا تَفْعَلُونَ','Wa awfoo bi Ahdil laahi izaa \'aahattum wa laa tanqudul aimaana ba\'da tawkeedihaa wa qad ja\'altumul laaha \'alaikum kafeelaa; innal laaha ya\'lamu maa taf\'aloon',91,'16:91',28,111,236,3,0,277,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1993,16,'وَلَا تَكُونُوا۟ كَٱلَّتِى نَقَضَتْ غَزْلَهَا مِنۢ بَعْدِ قُوَّةٍ أَنكَـٰثًا تَتَّخِذُونَ أَيْمَـٰنَكُمْ دَخَلًۢا بَيْنَكُمْ أَن تَكُونَ أُمَّةٌ هِىَ أَرْبَىٰ مِنْ أُمَّةٍ ۚ إِنَّمَا يَبْلُوكُمُ ٱللَّهُ بِهِۦ ۚ وَلَيُبَيِّنَنَّ لَكُمْ يَوْمَ ٱلْقِيَـٰمَةِ مَا كُنتُمْ فِيهِ تَخْتَلِفُونَ','Wa laa takoonoo kallatee naqadat ghazlahaa mim ba\'di quwwatin ankaasaa; tattakhizoona aimaanakum dakhlalam bainakum an takoona ummatun hiya arbaa min ummah; innnamaa yablookumul laahu bih; wa la yubaiyinanna lakum yawmal Qiyaamati maa kuntum fee takhtalifoon',92,'16:92',28,111,236,3,0,277,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1994,16,'وَلَوْ شَآءَ ٱللَّهُ لَجَعَلَكُمْ أُمَّةً وَٰحِدَةً وَلَـٰكِن يُضِلُّ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ ۚ وَلَتُسْـَٔلُنَّ عَمَّا كُنتُمْ تَعْمَلُونَ','Wa law shaaa\'al laahu laja\'alakum ummmatanw waahidatanw wa laakiny yudillu many-yashaaa\'u wa yahdee many-yashaaa\'; wa latus\'alunna \'ammaa kuntum ta\'maloon',93,'16:93',28,111,236,3,0,277,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1995,16,'وَلَا تَتَّخِذُوٓا۟ أَيْمَـٰنَكُمْ دَخَلًۢا بَيْنَكُمْ فَتَزِلَّ قَدَمٌۢ بَعْدَ ثُبُوتِهَا وَتَذُوقُوا۟ ٱلسُّوٓءَ بِمَا صَدَدتُّمْ عَن سَبِيلِ ٱللَّهِ ۖ وَلَكُمْ عَذَابٌ عَظِيمٌ','Wa laa tattakhizooo aimaanakum dakhalam bainakum ftazilla qadamum ba\'da subootihaa wa tazooqus sooo\'a bimmaa sadattum \'an sabeelil laahi wa lakum \'azaabun \'azeem',94,'16:94',28,111,236,3,0,278,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1996,16,'وَلَا تَشْتَرُوا۟ بِعَهْدِ ٱللَّهِ ثَمَنًا قَلِيلًا ۚ إِنَّمَا عِندَ ٱللَّهِ هُوَ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ','Wa laa tashtaroo bi \'ahdil laahi samanan qaleelaa; innamaa \'indal laahi huwa khairul lakum in kuntum ta\'lamoon',95,'16:95',28,111,236,3,0,278,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1997,16,'مَا عِندَكُمْ يَنفَدُ ۖ وَمَا عِندَ ٱللَّهِ بَاقٍ ۗ وَلَنَجْزِيَنَّ ٱلَّذِينَ صَبَرُوٓا۟ أَجْرَهُم بِأَحْسَنِ مَا كَانُوا۟ يَعْمَلُونَ','maa \'indakum yanfadu wa maa \'indal laahi baaq; wa lanajziyannal lazeena sabarooo ajjrahum bi ahsani maa kaanoo ya\'maloon',96,'16:96',28,111,236,3,0,278,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1998,16,'مَنْ عَمِلَ صَـٰلِحًا مِّن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَلَنُحْيِيَنَّهُۥ حَيَوٰةً طَيِّبَةً ۖ وَلَنَجْزِيَنَّهُمْ أَجْرَهُم بِأَحْسَنِ مَا كَانُوا۟ يَعْمَلُونَ','Man \'amila saaliham min zakarin aw unsaa wa huwa mu\'minun falanuhyiyannahoo hayaatan taiiyibatanw wa lanajzi yannnahum ajrahum bi ahsani maa kaanoo ya\'maloon',97,'16:97',28,111,236,3,0,278,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(1999,16,'فَإِذَا قَرَأْتَ ٱلْقُرْءَانَ فَٱسْتَعِذْ بِٱللَّهِ مِنَ ٱلشَّيْطَـٰنِ ٱلرَّجِيمِ','Fa izaa qara tal Quraana fasta\'iz billaahi minashh Shai taanir rajeem',98,'16:98',28,111,236,3,0,278,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(2000,16,'إِنَّهُۥ لَيْسَ لَهُۥ سُلْطَـٰنٌ عَلَى ٱلَّذِينَ ءَامَنُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ','Innahoo laisa lahoo sultaanun \'alal lazeena aamanoo wa \'alaa Rabbihim yatawakkaloon',99,'16:99',28,111,236,3,0,278,14,'2023-12-01 11:30:05','2026-09-22 00:06:42'),(2001,16,'إِنَّمَا سُلْطَـٰنُهُۥ عَلَى ٱلَّذِينَ يَتَوَلَّوْنَهُۥ وَٱلَّذِينَ هُم بِهِۦ مُشْرِكُونَ','Innnamaa sultaanuhoo \'alal lazeena yatawallawnahoo wallazeena hum bihee mushrikoon',100,'16:100',28,111,236,3,0,278,14,'2023-1