INSERT INTO `dhikrs` VALUES (1,1,'Subhan Allah','Subhan Allah','سُبْحَانَ ٱللَّٰهِ','سُبْحَانَ ٱللَّٰهِ','2026-09-22 00:06:37','2026-09-22 00:06:37'),(2,2,'Al-hamdulillah','Al-hamdulillah','ٱلْحَمْدُ لِلَّٰهِ','ٱلْحَمْدُ لِلَّٰهِ','2026-09-22 00:06:37','2026-09-22 00:06:37'),(3,3,'Allāhu Akbar','Allāhu Akbar','ٱللَّٰهُ أَكْبَرُ','ٱللَّٰهُ أَكْبَرُ','2026-09-22 00:06:37','2026-09-22 00:06:37'),(4,4,'La ilaha illallah','La ilaha illallah','لَا إِلَٰهَ إِلَّا ٱللَّٰهُ','لَا إِلَٰهَ إِلَّا ٱللَّٰهُ','2026-09-22 00:06:37','2026-09-22 00:06:37'),(5,5,'Astaghfirullah','Astaghfirullah','ٱسْتِغْفَار','ٱسْتِغْفَار','2026-09-22 00:06:37','2026-09-22 00:06:37'),(6,6,'Darood Sharif','Allaahumma salli alaa Muhammadinw wa alaa aali Muhammad kamaa sallayta alaa Ibraaheema wa alaa aali Ibraaheem, innaka Hameedum Majeed.Allaahumma baarik alaa Muhammadinw wa alaa aali Muhammadin, kamaa baarakta alaa Ibraaheema wa alaa aali Ibraaheema, innaka Hameedum Majeed.','دارود شريف','اَللّٰھُمَّ صَلِّ عَلٰی مُحَمَّدٍ وَّعَلٰٓی اٰلِ مُحَمَّدٍ کَمَا صَلَّیْتَ عَلٰٓی اِبْرَاھِیْمَ وَعَلٰٓی اٰلِ اِبْرَاھِیْمَ اِنَّکَ حَمِیْدٌ مَّجِیْدٌ اَللّٰھُمَّ بَارِکْ عَلٰی مُحَمَّدٍ وَّعَلٰٓی اٰلِ مُحَمَّدٍ کَمَا بَارَکْتَ عَلٰٓی اِبْرَاھِیْمَ وَعَلٰٓی اٰلِ اِبْرَاھِیْمَ اِنَّکَ حَمِیْدٌ مَّجِیْد','2026-09-22 00:06:37','2026-09-22 00:06:37');
