  `verse_number` int NOT NULL,
  `translate_name` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `verse_translations_chapter_detail_id_foreign` (`chapter_detail_id`),
